function _kpiEmpRowsHtml(entries, periodDate, isEditing, isAvg) {
    const pk = periodDate.replace(/-/g, '');
    return entries.map(function(entry, empIdx) {
        const hasSaved = !!entry.id;
        const sc = hasSaved ? '#16a34a' : 'transparent';
        const rowClass = isAvg ? 'kpi-avg-row' : (empIdx % 2 === 1 ? 'kpi-row-alt' : '');
        let cells = '<td class="kpi-grid-name-col"><div class="kpi-grid-name-cell">' +
            '<span class="kpi-grid-emp-name">' + entry.employee_name + '</span>' +
            (!isAvg ? '<span class="kpi-grid-status" id="kpiS-' + pk + '-' + empIdx + '" style="color:' + sc + '" title="' + (hasSaved ? 'Saved' : '') + '">' + (hasSaved ? '✓' : '') + '</span>' : '') +
            '</div></td>';
        _KPI_GRID_FIELDS.forEach(function(f) {
            const tc = _kpiThresholdCls(f.key, entry[f.key], false);
            if (f.computed || isAvg) {
                cells += '<td class="kpi-grid-computed' + (isAvg ? ' kpi-avg-cell' : '') + (tc ? ' ' + tc : '') + '" id="kpiC-' + pk + '-' + empIdx + '-' + f.key + '">' + _kpiFormatComputed(f.key, entry[f.key]) + '</td>';
            } else if (!isEditing) {
                // View mode: formatted text — money columns show $, all centered.
                cells += '<td class="kpi-grid-computed kpi-grid-view-val' + (tc ? ' ' + tc : '') + '">' + _kpiFormatComputed(f.key, entry[f.key]) + '</td>';
            } else {
                const val = entry[f.key] != null ? entry[f.key] : '';
                cells += '<td class="kpi-grid-td-input"><input class="kpi-grid-input' + (tc ? ' ' + tc : '') + '" type="number" step="' + f.step + '" min="0" id="kpi-' + pk + '-' + empIdx + '-' + f.key + '" value="' + val + '" oninput="_kpiUpdateRow(\'' + pk + '\',' + empIdx + ')"></td>';
            }
        });
        return '<tr class="' + rowClass + '" data-period="' + periodDate + '">' + cells + '</tr>';
    }).join('');
}

// The district manager isn't on any store roster (kpi-manage excludes corp
// roles), but they regularly help a store with buying/listing, so their numbers
// should be creditable on that period. While editing the current period:
//   - the DM/CEO themselves get an "add me" row;
//   - a store's own editors (manager / owner-manager / ASM) get an "add the DM"
//     row — whoever fills the KPIs can credit the DM for the shift he worked.
// Either way it's a one-off entry for THAT period only, persisted only if
// numbers are actually saved for it; past periods are historical snapshots.
const _KPI_STORE_EDIT_ROLES = new Set(['manager', 'owner (manager)', 'owner manager', 'assistant manager']);

// The DM's name, pulled from the auth directory (role "district manager") so it
// isn't hardcoded. null if the directory hasn't cached yet or there's no DM.
function _kpiDmName() {
    try {
        const auth = JSON.parse(localStorage.getItem('speeksAuthCache') || '{}');
        const dm = (auth.users || []).find(function(u) { return (u.role || '').toLowerCase().trim() === 'district manager'; });
        return dm && dm.name ? dm.name : null;
    } catch (e) { return null; }
}

function _kpiAddSelfRowHtml(p, isEditing) {
    if (!isEditing || !p.is_editable) return '';
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    const inEntries = function(nm) { return (p.entries || []).some(function(e) { return e.employee_name === nm; }); };

    // Who this button adds, and how it's labelled.
    let name, tag, who;
    if (role === 'ceo' || role === 'district manager') {
        name = sessionStorage.getItem('speeksUserName'); tag = role === 'ceo' ? 'CEO' : 'DM'; who = 'self';
    } else if (_KPI_STORE_EDIT_ROLES.has(role)) {
        name = _kpiDmName(); tag = 'DM'; who = 'dm';
    } else {
        return '';
    }
    if (!name || inEntries(name)) return '';

    const cols = 1 + _KPI_GRID_FIELDS.length;
    const period = _kpiCurrentTab === 'weekly' ? 'week' : 'month';
    const helped = who === 'self' ? 'you helped' : 'they helped';
    return '<tr><td colspan="' + cols + '" style="padding:8px 12px; background:#f8fafc; border-top:1px solid #f1f5f9;">' +
        '<button type="button" onclick="_kpiAddSelf(\'' + p.period_end_date + '\', \'' + who + '\')" title="Adds a row for ' + escapeHtml(name) + ' on this ' + period + ' only — use it when ' + helped + ' the store with buying or listing" ' +
        'style="font-size:12px; font-weight:800; color:#1d4ed8; background:#eff6ff; border:1.5px solid #bfdbfe; border-radius:8px; padding:6px 12px; cursor:pointer;">+ Add ' + escapeHtml(name) + ' (' + tag + ') — helped out this ' + period + '</button>' +
        '</td></tr>';
}

// who: 'self' (DM/CEO adds themselves) or 'dm' (a store editor adds the DM).
function _kpiAddSelf(periodDate, who) {
    const name = who === 'dm' ? _kpiDmName() : sessionStorage.getItem('speeksUserName');
    if (!name) return;
    const p = (_kpiPeriodsData || []).find(function(x) { return x.period_end_date === periodDate; });
    if (!p || p.entries.some(function(e) { return e.employee_name === name; })) return;
    // _selfAdded marks the row as a local, not-yet-saved addition so cancelling
    // the edit can remove it again (saved rows have an id and are kept).
    p.entries.push({ employee_name: name, _selfAdded: true });
    if (_kpiCurrentTab === 'weekly') _kpiRenderWeekly(_kpiPeriodsData);
    else _kpiRenderMonthly(_kpiPeriodsData);
}

// Cancelling an edit discards self-added rows that were never saved — the DM
// shouldn't linger in the grid after backing out.
function _kpiStripUnsavedSelfRows() {
    (_kpiPeriodsData || []).forEach(function(p) {
        p.entries = (p.entries || []).filter(function(e) { return !(e._selfAdded && !e.id); });
    });
}

function _kpiUpdateRow(pk, empIdx) {
    const g   = function(k) { var el = document.getElementById('kpi-' + pk + '-' + empIdx + '-' + k); return el ? (Number(el.value) || 0) : 0; };
    const bv  = g('buying_value'),        bc  = g('buying_cost');
    const tc  = g('transaction_count'),   tco = g('transaction_converted');
    const dc  = g('device_count'),        dco = g('device_converted');
    const ndv = g('no_deal_value'),       ndc = g('no_deal_cost');
    const lrp = g('listed_retail_price'),  lc = g('listed_cost'), lsv = g('listed_sold_value');
    const gp  = bv - bc;
    const r2  = function(n) { return n !== null ? Math.round(n * 100) / 100 : null; };
    const computed = {
        estimated_gross_profit:  gp,
        gross_margin_pct:        bv  > 0 ? r2((1-bc/bv)*100)        : null,
        customer_conversion_pct: tc  > 0 ? r2((tco/tc)*100)         : null,
        device_conversion_pct:   dc  > 0 ? r2((dco/dc)*100)         : null,
        lost_profit:             ndv - ndc,
        no_deal_vs_buying_pct:   gp  > 0 ? r2(((ndv-ndc)/gp)*100)  : null,
        listed_gross_margin_pct: lrp > 0 ? r2((1-lc/lrp)*100)      : null,
        listed_sold_pct:         lrp > 0 ? r2((lsv/lrp)*100)        : null,
    };
    Object.keys(computed).forEach(function(key) {
        const el = document.getElementById('kpiC-' + pk + '-' + empIdx + '-' + key);
        if (el) {
            el.textContent = _kpiFormatComputed(key, computed[key]);
            const tc = _kpiThresholdCls(key, computed[key], false);
            el.className = 'kpi-grid-computed' + (tc ? ' ' + tc : '');
        }
    });
    // Re-grade the directly-entered metrics that carry highlighting (time, no deals)
    ['avg_transaction_time', 'no_deal_count'].forEach(function(key) {
        const el = document.getElementById('kpi-' + pk + '-' + empIdx + '-' + key);
        if (el) {
            const tc = _kpiThresholdCls(key, el.value, false);
            el.className = 'kpi-grid-input' + (tc ? ' ' + tc : '');
        }
    });
    const statusEl = document.getElementById('kpiS-' + pk + '-' + empIdx);
    if (statusEl) { statusEl.textContent = '●'; statusEl.style.color = '#f59e0b'; statusEl.title = 'Unsaved'; }
}

function _kpiStoreTotalRowHtml(entries) {
    // Sum all numeric input fields; average avg_transaction_time
    const totals = { employee_name: 'Store Total' };
    _KPI_INPUT_FIELDS.forEach(function(f) {
        if (f === 'avg_transaction_time') {
            const vals = entries.map(function(e) { return Number(e[f]); }).filter(function(v) { return v > 0 && !isNaN(v); });
            totals[f] = vals.length ? vals.reduce(function(a, b) { return a + b; }, 0) / vals.length : null;
        } else {
            const vals = entries.map(function(e) { return Number(e[f]); }).filter(function(v) { return v != null && !isNaN(v); });
            totals[f] = vals.length ? vals.reduce(function(a, b) { return a + b; }, 0) : null;
        }
    });
    const computed = _kpiCalcDerived(totals);
    let cells = '<td class="kpi-grid-name-col kpi-total-name-col"><div class="kpi-grid-name-cell"><span class="kpi-grid-emp-name kpi-total-emp-name">Store Total</span></div></td>';
    _KPI_GRID_FIELDS.forEach(function(f) {
        const tc = _kpiThresholdCls(f.key, computed[f.key], true);
        cells += '<td class="kpi-grid-computed kpi-total-cell' + (tc ? ' ' + tc : '') + '">' + _kpiFormatComputed(f.key, computed[f.key]) + '</td>';
    });
    return '<tr class="kpi-total-row">' + cells + '</tr>';
}

// ── Coaching notes ──────────────────────────────────────────────────────────
// One free-text box per period, sitting under that period's numbers. Its own
// row rather than a column, because it's about the whole store's week, not any
// one employee's cell.
//
// Independent of the grid's Edit mode ON PURPOSE. Edit mode is a guarded state
// for rewriting numbers (and only works on the current period); a note is
// something you jot while reading, most often about a week that has already
// locked. Making it wait for Edit would put a lock on the one thing that has no
// reason to be locked — and would mean you could never annotate last week.
// Collapsed by default: most periods never get a note, and an always-open
// textarea under every one of them turns the grid into mostly empty boxes. So the
// resting state is a single bar, and the editor only exists when asked for.
//
// The cost of collapsing is that an existing note can hide — so the bar carries
// its own evidence: a filled dot, the author and date, and the note's opening
// words. You can tell which periods have notes without opening any of them.
//
// Expanded state is remembered per period (module-level, not persisted) so the
// re-renders that follow a numbers save don't slam the box shut mid-thought.
const _kpiNotesOpen = new Set();

// Who may WRITE a note. Must mirror canEditNotes() in the kpi-manage function —
// the backend is the real gate, this only decides whether to draw an editor.
// (Frontend and backend role lists drifting apart is what made every DM write to
// the Margin Guide 403 for a week, so they get checked as a pair.)
//
// Narrower than KPI editing on purpose: a coaching note is the store manager's
// prep for a conversation with their own team, so nobody above them edits it.
// DM, CEO and corp read only; assistant managers read only.
const _KPI_NOTE_EDIT_ROLES = new Set(['manager', 'owner (manager)', 'owner manager', 'multi-store manager']);

// Editing also requires that the store on screen is actually theirs — a DM's
// store picker and an MSM's routing both mean the grid can be showing a store
// the viewer doesn't manage.
function _kpiCanEditNotes() {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    if (!_KPI_NOTE_EDIT_ROLES.has(role)) return false;
    const onScreen = (_kpiResolveStore() || '').toUpperCase();
    if (!onScreen) return false;
    // An MSM manages every store in the list, not just the one whose dashboard
    // they're currently on — _kpiResolveStore can legitimately show them either.
    if (role === 'multi-store manager') return MULTISTORE_MANAGER_STORES.indexOf(onScreen) !== -1;
    return (sessionStorage.getItem('speeksUserStore') || '').toUpperCase() === onScreen;
}

function _kpiNotePreview(note) {
    const flat = String(note || '').replace(/\s+/g, ' ').trim();
    return flat.length > 90 ? flat.slice(0, 89) + '…' : flat;
}

function _kpiToggleNote(pk) {
    const box = document.getElementById('kpiNoteBox-' + pk);
    if (!box) return;
    const open = !box.classList.contains('is-open');
    box.classList.toggle('is-open', open);
    const head = document.getElementById('kpiNoteHead-' + pk);
    if (head) head.setAttribute('aria-expanded', String(open));
    if (open) {
        _kpiNotesOpen.add(pk);
        // Opening the bar is the request to write — put the cursor where the
        // writing happens instead of making it a second click.
        const ta = document.getElementById('kpiNote-' + pk);
        if (ta) { ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length); }
    } else {
        _kpiNotesOpen.delete(pk);
    }
}

function _kpiNoteRowHtml(p) {
    const pk    = p.period_end_date.replace(/-/g, '');
    const note  = p.note || '';
    const by    = p.note_by || '';
    const at    = p.note_at ? _kpiNoteStamp(p.note_at) : '';
    const meta  = (by && at) ? escapeHtml(by) + ' · ' + escapeHtml(at)
                : by ? escapeHtml(by) : '';
    const open  = _kpiNotesOpen.has(pk);
    const canEdit = _kpiCanEditNotes();

    // For a read-only viewer an empty period has nothing to show, so show
    // nothing. Otherwise a DM's grid grows an "Coaching Notes — none" bar under
    // every period of every store, which is pure noise for someone who couldn't
    // fill it in anyway. Managers always get the bar: theirs is an invitation.
    if (!canEdit && !note) return '';

    // Read-only viewers (DM, CEO, ASM, anyone looking at a store that isn't
    // theirs) get the note as text. No textarea, so there's no editor to type
    // into and only discover on save that it wasn't allowed.
    const body = canEdit
        ? '<textarea class="kpi-note-input" id="kpiNote-' + pk + '" rows="3" maxlength="4000" ' +
            'placeholder="What stood out this period? Wins to call out, patterns to work on, who to sit down with." ' +
            'oninput="_kpiNoteDirty(\'' + pk + '\')" ' +
            'onblur="_kpiSaveNote(\'' + p.period_end_date + '\')">' + escapeHtml(note) + '</textarea>' +
          '<div class="kpi-note-foot">' +
            '<span class="kpi-note-status" id="kpiNoteStatus-' + pk + '"></span>' +
            '<button type="button" class="kpi-note-save" id="kpiNoteSave-' + pk + '" ' +
              'onclick="_kpiSaveNote(\'' + p.period_end_date + '\')" disabled>Save Note</button>' +
          '</div>'
        : '<div class="kpi-note-read">' + escapeHtml(note) + '</div>';

    return '<tr class="kpi-note-row"><td colspan="24">' +
        '<div class="kpi-note-box' + (note ? ' has-note' : '') + (open ? ' is-open' : '') +
            (canEdit ? '' : ' is-readonly') + '" id="kpiNoteBox-' + pk + '">' +
          '<button type="button" class="kpi-note-head" id="kpiNoteHead-' + pk + '" ' +
            'aria-expanded="' + open + '" aria-controls="kpiNoteBody-' + pk + '" ' +
            'onclick="_kpiToggleNote(\'' + pk + '\')">' +
            '<svg class="kpi-note-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18l6-6-6-6"/></svg>' +
            '<span class="kpi-note-title">Coaching Notes</span>' +
            '<span class="kpi-note-dot" aria-hidden="true"></span>' +
            '<span class="kpi-note-preview" id="kpiNotePreview-' + pk + '">' + escapeHtml(_kpiNotePreview(note)) + '</span>' +
            '<span class="kpi-note-meta" id="kpiNoteMeta-' + pk + '">' + meta + '</span>' +
          '</button>' +
          '<div class="kpi-note-body" id="kpiNoteBody-' + pk + '">' + body + '</div>' +
        '</div></td></tr>';
}

// Short "when", in the store's timezone — a coaching note found weeks later
// needs a date more than it needs a clock.
function _kpiNoteStamp(iso) {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '';
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'America/Chicago' });
}

function _kpiNoteDirty(pk) {
    const st = document.getElementById('kpiNoteStatus-' + pk);
    const bt = document.getElementById('kpiNoteSave-' + pk);
    if (st) { st.textContent = 'Unsaved changes'; st.className = 'kpi-note-status is-dirty'; }
    if (bt) bt.disabled = false;
}

// Saves without re-rendering the grid. A full reload here would tear the
// textarea out from under the cursor on every blur — and blur is the common
// save path, since the whole point is that you can type and move on.
async function _kpiSaveNote(periodDate) {
    const pk  = periodDate.replace(/-/g, '');
    const ta  = document.getElementById('kpiNote-' + pk);
    const st  = document.getElementById('kpiNoteStatus-' + pk);
    const bt  = document.getElementById('kpiNoteSave-' + pk);
    if (!ta) return;
    const period = (_kpiPeriodsData || []).find(function(p) { return p.period_end_date === periodDate; });
    const value  = ta.value.trim();
    // Nothing changed — a blur with no edit shouldn't cost a round trip or
    // flash a status the user didn't cause.
    if (period && (period.note || '') === value) {
        if (bt) bt.disabled = true;
        if (st && st.classList.contains('is-dirty')) { st.textContent = ''; st.className = 'kpi-note-status'; }
        return;
    }
    const store = _kpiResolveStore();
    const pin   = sessionStorage.getItem('speeksUserPin');
    if (!store || !pin) return;
    if (st) { st.textContent = 'Saving…'; st.className = 'kpi-note-status'; }
    if (bt) bt.disabled = true;
    try {
        // Same hard timeout as the row saves — a hung request would otherwise sit
        // on "Saving…" with the button disabled and no way back.
        const resp = await _kpiPostEntry({
            action: 'save_note', store: store, period_type: _kpiCurrentTab,
            period_end_date: periodDate, note: value,
        }, pin);
        const result = await resp.json();
        if (!resp.ok || result.success === false) throw new Error(result.error || 'Save failed');
        // Keep the in-memory period in step so the next blur sees no change, and
        // so a tab switch back re-renders what was actually saved.
        if (period) {
            period.note    = result.note || '';
            period.note_by = result.note_by || '';
            period.note_at = result.note_at || null;
        }
        const meta = document.getElementById('kpiNoteMeta-' + pk);
        if (meta) {
            meta.textContent = (result.note_by && result.note_at)
                ? result.note_by + ' · ' + _kpiNoteStamp(result.note_at)
                : (result.note_by || '');
        }
        // The bar is what everyone sees once this collapses, so its preview and
        // its has-a-note dot have to move with the save — not wait for a reload.
        const prev = document.getElementById('kpiNotePreview-' + pk);
        if (prev) prev.textContent = _kpiNotePreview(result.note || '');
        const box = document.getElementById('kpiNoteBox-' + pk);
        if (box) box.classList.toggle('has-note', !!(result.note || ''));
        if (st) { st.textContent = 'Saved'; st.className = 'kpi-note-status is-saved'; }
    } catch (e) {
        if (st) { st.textContent = String(e.message || 'Could not save'); st.className = 'kpi-note-status is-error'; }
        if (bt) bt.disabled = false;   // leave the way back open
    }
}

function _kpiWeekRangeLabel(periodEndDate) {
    const end = new Date(periodEndDate + 'T12:00:00');
    const start = new Date(end);
    start.setDate(start.getDate() - 6);
    const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    const sm = months[start.getMonth()], sd = start.getDate();
    const em = months[end.getMonth()],   ed = end.getDate();
    return 'Week ' + sm + ' ' + sd + ' - ' + em + ' ' + ed;
}

function _kpiRenderWeekly(periods) {
    const body = document.getElementById('kpiModalBody');
    if (!body) return;
    const store = _kpiResolveStore();
    const sub = document.getElementById('kpiModalSubtitle');
    if (sub) sub.textContent = store + ' · 4-Week View';

    // Always show the current (editable) week plus any past weeks with saved data.
    // Rendering it even in view mode means clicking Edit just swaps its cells from
    // text to inputs IN PLACE — no new section appears, so nothing on the page shifts.
    // A period with a note but no numbers still has to render, or the note it
    // holds becomes unreachable the moment it exists.
    let visible = (periods || []).filter(function(p) { return p.is_editable || !!(p.note) || p.entries.some(function(e) { return e.id; }); });
    if (_kpiEditingPeriod) {
        const ep = periods.find(function(p) { return p.period_end_date === _kpiEditingPeriod; });
        if (ep && !visible.find(function(p) { return p.period_end_date === ep.period_end_date; })) visible.unshift(ep);
        else if (ep) { visible = visible.filter(function(p) { return p.period_end_date !== ep.period_end_date; }); visible.unshift(ep); }
    }

    _kpiSyncHeaderBtns();
    if (!visible.length) {
        body.innerHTML = '<div class="kpi-empty-state">No weekly KPI data yet. Click ✏️ Edit above to enter the current week.</div>';
        return;
    }
    const wkBadges = ['Current Week','Last Week','2 Weeks Ago','3 Weeks Ago'];
    const wkBClass = ['badge-current','badge-prev','badge-old','badge-old'];
    let tbody = '';
    visible.forEach(function(p, i) {
        const isEd = _kpiEditingPeriod === p.period_end_date;
        tbody += _kpiSectionDividerHtml('📅 ' + _kpiWeekRangeLabel(p.period_end_date), wkBadges[i] || '', wkBClass[i] || 'badge-old',
            _kpiSectionControls(p.period_end_date, isEd, p.is_editable), '#3b82f6');
        tbody += _kpiHeaderRowsHtml();
        tbody += _kpiEmpRowsHtml(p.entries, p.period_end_date, isEd, false);
        tbody += _kpiAddSelfRowHtml(p, isEd);
        const hasSavedData = p.entries.some(function(e) { return e.id; });
        if (hasSavedData) tbody += _kpiStoreTotalRowHtml(p.entries);
        tbody += _kpiNoteRowHtml(p);   // last: the week's numbers, then the week's notes
    });
    body.innerHTML = '<div class="kpi-grid-scroll-wrapper"><table class="kpi-entry-grid kpi-full-table">' + _kpiColgroupHtml() + '<tbody>' + tbody + '</tbody></table></div>';
}

// `periods` lets the date-range picker export a wider span than the on-screen
// window holds (see _exOpen). Called with no args it falls back to what's
// currently rendered, so any other caller behaves exactly as before.
function _kpiExportCSV(periods, spanTag) {
    const src = (periods && periods.length) ? periods : _kpiPeriodsData;
    if (!src || !src.length) return;
    const store = _kpiResolveStore() || sessionStorage.getItem('speeksUserStore') || 'STORE';
    const isWeekly = _kpiCurrentTab === 'weekly';

    const headers = [
        'Period','Employee',
        'Buy Value','Buy Cost','Est. GP','Margin %',
        '# Trans','# Conv.','Conv. %',
        '# Devices','# Dev Conv.','Dev Conv. %',
        'Avg Time (min)',
        '# No Deals','ND Value','ND Cost','Lost Profit','% vs Buy GP',
        '# Listed','Retail ($)','Cost ($)','Sold ($)','Listed Margin %','% Sold',
        'Google Reviews'
    ];

    const csvRows = [headers];

    // oldest → newest reads better in a spreadsheet than the newest-first UI order
    src.slice().sort(function(a, b) {
        return a.period_end_date < b.period_end_date ? -1 : a.period_end_date > b.period_end_date ? 1 : 0;
    }).forEach(function(p) {
        const label = isWeekly ? _kpiWeekRangeLabel(p.period_end_date) : p.period_label;
        p.entries.forEach(function(raw) {
            const e = _kpiCalcDerived(raw);
            const r2 = function(v) { return v == null ? '' : Math.round(v * 100) / 100; };
            csvRows.push([
                label,
                e.employee_name,
                r2(e.buying_value),       r2(e.buying_cost),
                r2(e.estimated_gross_profit), r2(e.gross_margin_pct),
                r2(e.transaction_count),  r2(e.transaction_converted), r2(e.customer_conversion_pct),
                r2(e.device_count),       r2(e.device_converted),      r2(e.device_conversion_pct),
                r2(e.avg_transaction_time),
                r2(e.no_deal_count),      r2(e.no_deal_value),         r2(e.no_deal_cost),
                r2(e.lost_profit),        r2(e.no_deal_vs_buying_pct),
                r2(e.listed_count),       r2(e.listed_retail_price),   r2(e.listed_cost),
                r2(e.listed_sold_value),  r2(e.listed_gross_margin_pct), r2(e.listed_sold_pct),
                r2(e.mtd_google_reviews)
            ]);
        });
    });

    const csv = csvRows.map(function(row) {
        return row.map(function(v) {
            const s = String(v);
            return s.includes(',') || s.includes('"') || s.includes('\n') ? '"' + s.replace(/"/g, '""') + '"' : s;
        }).join(',');
    }).join('\r\n');

    const tab = isWeekly ? 'Weekly' : 'Monthly';
    const ts  = new Date().toISOString().slice(0, 10);
    const filename = store + '_KPI_' + tab + '_' + (spanTag ? spanTag + '_' : '') + ts + '.csv';

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url; a.download = filename; a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

// --- 11c. MODULE: MONTHLY PERFORMANCE BRIEF (district-level, DM-editable) ---
let _mbData = {};        // { period_end_date: { metric_key: value } }
let _mbMonths = [];      // sorted date strings
let _mbMetrics = [];     // catalog [{key,label,type,section}]
let _mbEditable = '';    // editable period_end_date
let _mbEditing = false;
let _mbView = null;          // 'overview' | 'store' (decided by role on first load)
let _mbOverviewData = {};    // { store: { period_end_date: { metric_key: value } } }
let _mbOverviewMonth = '';   // newest month WITH data — the overview's default
let _mbOverviewEditable = ''; // editable period_end_date (same across stores)
// Month explicitly chosen in the Overview picker. '' means "follow the default",
// so a fresh load always lands on the newest month rather than a stale pick.
let _mbOverviewPick = '';
// How many months the Overview picker offers. THIRTEEN, not twelve: twelve
// entries reach back to the month AFTER the one you're comparing against, so the
// same month last year — the whole point of the YoY rows — would be the first
// month off the end of the list. The 13th is that month.
// A display cap only; the fetch still loads every month on file.
const MB_OVERVIEW_MONTHS = 13;

function _mbMonthLabel(dateStr) {
    const d = new Date(dateStr + 'T12:00:00');
    return d.toLocaleString('en-US', { month: 'long', year: 'numeric' });
}

// Compact column header, e.g. "Apr '26"
function _mbMonthLabelShort(dateStr) {
    const d = new Date(dateStr + 'T12:00:00');
    return d.toLocaleString('en-US', { month: 'short' }) + " '" + String(d.getFullYear()).slice(-2);
}

const MB_MONTH_WINDOW = 6; // how many recent months to show across the brief

function _mbFmt(type, v) {
    if (v == null || v === '' || isNaN(Number(v))) return '—';
    const n = Number(v);
    // Sign OUTSIDE the symbol. Until YoY rows existed no money metric could go
    // negative, so '$' + n rendered fine; a down year would have printed "$-1,274".
    if (type === 'money') {
        const r = Math.round(n);
        return (r < 0 ? '-$' : '$') + Math.abs(r).toLocaleString();
    }
    if (type === 'pct')    return n.toFixed(1) + '%';
    if (type === 'rating') return n.toFixed(1) + ' ★';
    if (type === 'int')    return Math.round(n).toLocaleString();
    return String(Math.round(n * 10) / 10);
}

// Metrics where a DECREASE is good (lower = better). All others: increase = good.
//
// These two Sets are now REBUILT FROM THE CATALOG on every load (see
// _mbSyncMetricFlags) — the row's lower_is_better / no_shade columns are the
// source of truth, so a row added in Manage Rows grades correctly without a
// deploy. They start as the shipped values so the very first render, and any
// fallback where the catalog can't be read, still grades the way it always did.
// `let`, not `const`, purely so they can be reassigned; every .has() call site
// is unchanged.
let _MB_INVERSE = new Set([
    'avg_transaction_time', 'inventory_cost', 'inventory_cost_under_30', 'pct_inventory_over_30',
    'recycled_inventory', 'recycled_pct_inventory', 'inventory_confiscation',
    'refunds', 'discounts', 'return_rate', 'shipping_label_cost', 'shipping_cost_pct_sales',
    'paymore_ranking', 'defect_rate', 'late_shipment_rate', 'case_no_resolution',
]);

// Metrics that never get good/bad coloring — month-over-month or cross-store
// comparison isn't meaningful for them (running totals / external rankings).
let _MB_NO_SHADE = new Set(['google_score', 'google_reviews', 'paymore_ranking']);

// Adopt the catalog's grading flags. Called after every load, before render.
// Older payloads (or the fallback catalog) carry no flags at all — in that case
// keep whatever is already in the Sets rather than silently clearing them, which
// would flip every "lower is better" metric to green-when-rising.
function _mbSyncMetricFlags() {
    if (!Array.isArray(_mbMetrics) || !_mbMetrics.length) return;
    if (!_mbMetrics.some(m => 'lower_is_better' in m || 'no_shade' in m)) return;
    _MB_INVERSE  = new Set(_mbMetrics.filter(m => m.lower_is_better).map(m => m.key));
    _MB_NO_SHADE = new Set(_mbMetrics.filter(m => m.no_shade).map(m => m.key));
}

// True for any row the DM shouldn't be able to type into: the legacy spreadsheet
// formulas (_MB_DERIVED) and anything the catalog marks derived.
function _mbIsDerived(m) {
    return _MB_DERIVED_KEYS.has(m.key) || (m && m.source === 'derived');
}

// A row whose VALUE IS ALREADY A CHANGE (YoY $ or YoY %), as opposed to a level.
// These are graded on direction rather than ranked against the other stores —
// see the shading block in _mbRenderOverview for why. yoy_prior is deliberately
// excluded: it's last year's level, so ranking it is meaningful.
function _mbIsChangeMetric(m) {
    return !!m && (m.formula_key === 'yoy_pct' || m.formula_key === 'yoy_delta');
}

// Green when the change is in the good direction for this row, red when it
// isn't, nothing at zero or with no data. Returns a class suffix (leading space)
// so callers can append it to 'mb-val'.
function _mbChangeCls(m, v) {
    if (v == null || isNaN(Number(v))) return '';
    const n = Number(v);
    if (n === 0) return '';
    const good = _MB_INVERSE.has(m.key) ? (n < 0) : (n > 0);
    return good ? ' mb-best' : ' mb-worst';
}

// Derived metrics, replicating the Monthly KPI spreadsheet's cell formulas.
// These are auto-calculated from the manually entered fields (and locked in edit
// mode). Percent metrics are stored as percent numbers (58.54), not fractions.
// Order matters: pct_non_ebay_sales uses the three channel percentages above it.
const _mbR2  = n => Math.round(n * 100) / 100;
const _mbPctOf = (num, den) => (num != null && den > 0) ? _mbR2(num / den * 100) : null;
const _MB_DERIVED = [
    ['buy_value_per_customer', v => (v.buying != null && v.num_customers > 0 && v.customer_close_rate > 0)
        ? _mbR2(v.buying / (v.num_customers * v.customer_close_rate / 100)) : null],
    ['pct_returning_customers', v => _mbPctOf(v.returning_customers, v.num_customers)],
    ['pct_inventory_over_30',   v => _mbPctOf(v.inventory_cost_under_30, v.inventory_cost)],
    ['return_rate',             v => _mbPctOf(v.refunds, v.gross_sales)],
    ['gross_profit',            v => (v.net_sales != null && v.cogs != null) ? _mbR2(v.net_sales - v.cogs) : null],
    ['gross_profit_pct',        v => (v.net_sales > 0 && v.cogs != null) ? _mbR2((1 - v.cogs / v.net_sales) * 100) : null],
    ['cogs_sold_vs_listed',     v => _mbPctOf(v.cogs, v.inventory_cost)],
    ['pct_sales_at_pos',        v => _mbPctOf(v.sales_at_pos, v.net_sales)],
    ['pct_sales_online',        v => _mbPctOf(v.sales_online, v.net_sales)],
    ['pct_sales_draft_order',   v => _mbPctOf(v.sale_draft_order, v.net_sales)],
    ['pct_non_ebay_sales',      v => (v.pct_sales_at_pos != null && v.pct_sales_online != null && v.pct_sales_draft_order != null)
        ? _mbR2(v.pct_sales_at_pos + v.pct_sales_online + v.pct_sales_draft_order) : null],
    ['shipping_cost_pct_sales', v => _mbPctOf(v.shipping_label_cost, v.net_sales)],
    ['recycled_pct_inventory',  v => _mbPctOf(v.recycled_inventory, v.inventory_cost)],
];
const _MB_DERIVED_KEYS = new Set(_MB_DERIVED.map(d => d[0]));

// Fills the derived keys of a values object in place (null when inputs incomplete).
function _mbApplyDerived(values) {
    _MB_DERIVED.forEach(([key, fn]) => {
        const x = fn(values);
        values[key] = (x == null || !isFinite(x)) ? null : x;
    });
    return values;
}

// ── Cross-period formulas ───────────────────────────────────────────────────
// _MB_DERIVED above computes a value from OTHER VALUES IN THE SAME MONTH, and
// those results are stored — they're saved alongside the numbers they came from.
//
// These are different: they reach into a DIFFERENT PERIOD, so they are computed
// at render time and never stored. If someone corrects last July's buying, every
// YoY built on it has to move with it; a stored copy would quietly go stale and
// there would be nothing on screen to reveal that it had.
//
// The registry is parameterised on purpose. `yoy_pct` doesn't know about buying
// — it takes the metric_key to compare as formula_arg. So "YoY Buying", "YoY NET
// Sales" and "YoY Gross Profit" are three CATALOG ROWS, not three functions, and
// a DM adds the next one from Manage Rows without touching this file.
//
// Signature: (arg, byMonth, month) -> number | null
//   arg      the metric_key being compared (from the catalog row's formula_arg)
//   byMonth  { 'YYYY-MM-DD': { metric_key: value } } for ONE store
//   month    the period being rendered
const _MB_FORMULAS = {
    // Percent change against the same month one year earlier.
    yoy_pct: (arg, byMonth, month) => {
        const p = _mbYoyPair(arg, byMonth, month);
        // A zero base has no meaningful percentage — "up from nothing" is
        // infinite, not 100%, so show nothing rather than a made-up number.
        if (!p || p.then === 0) return null;
        return _mbR2((p.now - p.then) / Math.abs(p.then) * 100);
    },
    // Absolute change against the same month one year earlier, in the source
    // metric's own unit. Unlike yoy_pct a zero base is fine here: "up $8,234
    // from nothing" is a real, readable statement.
    yoy_delta: (arg, byMonth, month) => {
        const p = _mbYoyPair(arg, byMonth, month);
        return p ? _mbR2(p.now - p.then) : null;
    },
    // The same month last year, as it stood — no arithmetic, just the number to
    // compare against. Useful as a plain reference row beside the current month.
    yoy_prior: (arg, byMonth, month) => {
        const p = _mbYoyPair(arg, byMonth, month);
        return p ? p.then : null;
    },
};

// Shared lookup for every year-over-year formula: this month's value and the
// same month last year, or null if either is missing. One place to get the
// "is there a prior year at all" question right.
function _mbYoyPair(arg, byMonth, month) {
    if (!arg) return null;
    const prev = _mbPriorYearKey(byMonth, month);
    if (!prev) return null;
    const now  = Number((byMonth[month] || {})[arg]);
    const then = Number((byMonth[prev]  || {})[arg]);
    if (!isFinite(now) || !isFinite(then)) return null;
    return { now, then };
}

// The period_end_date exactly one year before `month`, if it's on file. Both are
// month-ends, so this is "same month, previous year" — matched on the YYYY-MM
// prefix rather than by subtracting days, which would miss Feb 29 and any
// month-end whose day-of-month differs across years.
function _mbPriorYearKey(byMonth, month) {
    const m = String(month || '').match(/^(\d{4})-(\d{2})/);
    if (!m) return null;
    const target = (Number(m[1]) - 1) + '-' + m[2];
    return Object.keys(byMonth || {}).find(k => k.slice(0, 7) === target) || null;
}

// Fill every cross-period row into one store's data, in memory only. Run after
// each load so that rendering, the delta chips and the CSV export all read these
// exactly like stored values and need no special-casing.
function _mbApplyComputedRows(byMonth) {
    if (!byMonth) return byMonth;
    const computed = (_mbMetrics || []).filter(m =>
        m.source === 'derived' && m.formula_key && m.formula_key !== 'legacy' && _MB_FORMULAS[m.formula_key]);
    if (!computed.length) return byMonth;
    Object.keys(byMonth).forEach(month => {
        computed.forEach(m => {
            let v = null;
            try { v = _MB_FORMULAS[m.formula_key](m.formula_arg, byMonth, month); }
            catch (e) { v = null; }   // one bad row must not blank the brief
            byMonth[month][m.key] = (v == null || !isFinite(v)) ? null : v;
        });
    });
    return byMonth;
}

// Live recompute while typing in edit mode: reads every metric input with the
// given id prefix, derives, and writes results back into the locked inputs.
function _mbLiveDerive(prefix) {
    const values = {};
    _mbMetrics.forEach(m => {
        const el = document.getElementById(prefix + m.key);
        if (el) values[m.key] = el.value === '' ? null : Number(el.value);
    });
    _mbApplyDerived(values);
    _MB_DERIVED_KEYS.forEach(key => {
        const el = document.getElementById(prefix + key);
        if (el) el.value = values[key] != null ? values[key] : '';
    });
}

// Unsigned magnitude of a change, formatted by type (direction shown via arrow).
function _mbDeltaMag(type, diff) {
    const a = Math.abs(diff);
    if (type === 'money')  return '$' + Math.round(a).toLocaleString();
    if (type === 'pct')    return a.toFixed(1) + ' pts';
    if (type === 'rating') return a.toFixed(1);
    if (type === 'int')    return Math.round(a).toLocaleString();
    return String(Math.round(a * 10) / 10);
}

const MB_STORES = ['OVL', 'LEE', 'WSP', 'MPL', 'BAL'];
const MB_STORE_DOT = { OVL: '🟣', LEE: '🔵', WSP: '🟢', MPL: '🟠', BAL: '🔴' };

function _mbDefaultView() {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    return (role === 'ceo' || role === 'district manager') ? 'overview' : 'store';
}

// Reflect the active view in the controls: highlight the toggle, and only show
// the store picker in Store View (and only for CEO/DM — Overview spans all stores).
function _mbSyncControls() {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    const canPickStore = (role === 'ceo' || role === 'district manager');
    document.getElementById('mbViewOverviewBtn')?.classList.toggle('active', _mbView === 'overview');
    document.getElementById('mbViewStoreBtn')?.classList.toggle('active', _mbView === 'store');
    const sel = document.getElementById('mbStoreSelect');
    if (sel) sel.style.display = (_mbView === 'store' && canPickStore) ? '' : 'none';
    // Manage Rows edits the catalog, which is the same on both views — but hide
    // it mid-edit so the shape of the report can't change under an open form.
    const rowsBtn = document.getElementById('mbRowsBtn');
    if (rowsBtn) rowsBtn.style.display = (_mbCanManageRows() && !_mbEditing) ? '' : 'none';
    _mbSyncOverviewMonths();
    const sub = document.getElementById('mbSubtitle');
    if (sub) {
        const store = (sel && canPickStore ? sel.value : null) || sessionStorage.getItem('speeksUserStore') || '';
        sub.textContent = _mbView === 'overview' ? 'All Stores' : (store + ' · Store View');
    }
}

// Month picker for the Overview. Store View already shows five months side by
// side, so it needs no picker — this is Overview-only.
//
// Every month for every store is ALREADY in _mbOverviewData (the fetch pulls a
// store's whole history), so changing months is a re-render off memory. No
// refetch, no spinner.
function _mbSyncOverviewMonths() {
    const sel = document.getElementById('mbOverviewMonth');
    if (!sel) return;
    if (_mbView !== 'overview') { sel.style.display = 'none'; return; }

    // Only months that actually carry values for some store. The API lists the
    // open edit window in `months` before anything is entered for it, and an
    // empty month in the picker is a dead end.
    const months = new Set();
    Object.keys(_mbOverviewData).forEach(s => {
        const byMonth = _mbOverviewData[s] || {};
        Object.keys(byMonth).forEach(mo => {
            if (byMonth[mo] && Object.keys(byMonth[mo]).length) months.add(mo);
        });
    });
    // Newest first, capped at a year. There are 23 months on file and growing;
    // past a year the list is scrolling rather than choosing. This caps only the
    // PICKER — nothing else is windowed, so the YoY rows still reach back into
    // the full history for their prior-year figure.
    const list = [...months].sort().reverse().slice(0, MB_OVERVIEW_MONTHS);
    if (!list.length) { sel.style.display = 'none'; return; }

    // A pick that no longer exists (store switch, fresh load) falls back to the
    // newest month rather than leaving the select pointing at nothing.
    if (_mbOverviewPick && list.indexOf(_mbOverviewPick) === -1) _mbOverviewPick = '';
    const current = _mbOverviewPick || _mbOverviewMonth || list[0];

    sel.innerHTML = list.map(mo =>
        '<option value="' + mo + '"' + (mo === current ? ' selected' : '') + '>' + _mbMonthLabel(mo) + '</option>'
    ).join('');
    sel.value = current;
    sel.style.display = '';
    // While editing, the view is pinned to the open month — offering a picker
    // that can't move would be a lie, and moving it mid-edit would silently
    // retarget the inputs at a locked month.
    sel.disabled = !!_mbEditing;
    sel.title = _mbEditing ? 'Finish or cancel editing to change months' : 'View a previous month';
}

function mbSetOverviewMonth(month) {
    if (_mbEditing) return;                  // guarded above, belt and braces
    _mbOverviewPick = month || '';
    _mbRenderOverview();
    _mbSyncOverviewMonths();
}

function mbSetView(view) {
    if (_mbView === view) return;
    _mbView = view;
    _mbEditing = false;
    fetchMonthlyBrief();
}

// Dispatcher — loads + renders the data for whichever view is active.
function fetchMonthlyBrief() {
    if (_mbView === null) _mbView = _mbDefaultView();
    _mbSyncControls();
    return (_mbView === 'overview') ? fetchMonthlyBriefOverview() : fetchMonthlyBriefStore();
}

// OVERVIEW (CEO/DM): the most-recent month for every store, side by side.
async function fetchMonthlyBriefOverview() {
    const body = document.getElementById('mbBody');
    if (!body) return;
    _mbEditing = false;
    // A reload starts from the newest month. Keeping a stale pick across a view
    // switch would silently reopen on an old month with no obvious cause.
    _mbOverviewPick = '';
    body.innerHTML = '<div class="status-message">Syncing Performance Brief…</div>';
    // allSettled so one store being unreachable doesn't blank the whole overview
    const settled = await Promise.allSettled(MB_STORES.map(s =>
        fetch(`${MONTHLY_BRIEF_URL}?store=${s}&v=${Date.now()}`).then(r => r.json()).then(d => ({ s, d }))
    ));
    _mbOverviewData = {};
    const dataMonths = new Set();
    let editable = '';
    let anyOk = false;
    settled.forEach(res => {
        if (res.status !== 'fulfilled') return;
        anyOk = true;
        const { s, d } = res.value;
        const data = d.data || {};
        _mbOverviewData[s] = data;
        // only count months that actually carry values (the API lists the open
        // edit window in `months` even before any numbers are entered for it)
        Object.keys(data).forEach(mo => { if (data[mo] && Object.keys(data[mo]).length) dataMonths.add(mo); });
        if ((d.metrics || []).length) _mbMetrics = d.metrics;
        if (d.editable_period) editable = d.editable_period;
    });
    if (!anyOk) {
        body.innerHTML = '<div class="status-message" style="color:var(--red-alert)">Failed to load overview.</div>';
        return;
    }
    _mbOverviewEditable = editable;
    // Catalog flags first — _mbApplyComputedRows reads _mbMetrics to know which
    // rows are computed, so it has to run after the metrics have landed.
    _mbSyncMetricFlags();
    Object.keys(_mbOverviewData).forEach(s => _mbApplyComputedRows(_mbOverviewData[s]));
    // Display the most recent month that has data (useful for everyone); editing
    // switches to the open edit window, which may still be awaiting entry.
    _mbOverviewMonth = [...dataMonths].sort().reverse()[0] || editable || '';
    renderMonthlyBrief();
}

// STORE VIEW: 5-month history for a single store.
async function fetchMonthlyBriefStore() {
    const body = document.getElementById('mbBody');
    if (!body) return;
    const sel = document.getElementById('mbStoreSelect');
    let store = sel ? sel.value : (sessionStorage.getItem('speeksUserStore') || 'OVL');
    // Managers without the picker default to their own store
    if (sel && sel.offsetParent === null) { store = sessionStorage.getItem('speeksUserStore') || store; }
    _mbEditing = false;
    body.innerHTML = '<div class="status-message">Syncing Performance Brief…</div>';
    try {
        const d = await fetch(`${MONTHLY_BRIEF_URL}?store=${store}&v=${Date.now()}`).then(r => r.json());
        _mbData     = d.data || {};
        _mbMonths   = d.months || [];
        _mbMetrics  = d.metrics || [];
        _mbEditable = d.editable_period || '';
        _mbSyncMetricFlags();
        _mbApplyComputedRows(_mbData);
        renderMonthlyBrief();
    } catch (e) {
        body.innerHTML = '<div class="status-message" style="color:var(--red-alert)">Failed to load brief.</div>';
    }
}

function renderMonthlyBrief() {
    _mbSyncControls();
    if (_mbView === 'overview') return _mbRenderOverview();
    return _mbRenderStore();
}

function _mbRenderStore() {
    const body = document.getElementById('mbBody');
    if (!body) return;

    // Newest-first window of up to 5 months. Only include the editable month
    // when actively editing — it stays hidden until the user clicks Edit.
    const monthSet = new Set(_mbMonths);
    if (_mbEditable && _mbEditing) monthSet.add(_mbEditable);
    const months = [...monthSet].sort().reverse().slice(0, MB_MONTH_WINDOW)
        .filter(mo => {
            if (_mbEditing && mo === _mbEditable) return true;
            const d = _mbData[mo] || {};
            return Object.values(d).some(v => v != null);
        });
    if (!months.length) { body.innerHTML = '<div class="status-message">No data available.</div>'; return; }

    // Edit for DM, CEO, and owner-manager on the editable (current) month
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    const isDM = role === 'district manager';
    const canEdit = (isDM || role === 'ceo' || role === 'owner manager') && !!_mbEditable && months.includes(_mbEditable);
    const editBtn = document.getElementById('mbEditBtn');
    if (editBtn) editBtn.style.display = (canEdit && !_mbEditing) ? 'inline-block' : 'none';
    const saveBtn = document.getElementById('mbSaveBtn');
    const cancelBtn = document.getElementById('mbCancelBtn');
    if (saveBtn)   saveBtn.style.display   = (_mbEditing) ? 'inline-block' : 'none';
    if (cancelBtn) cancelBtn.style.display = (_mbEditing) ? 'inline-block' : 'none';

    const totalCols = 1 + months.length + (months.length - 1); // metric + months + deltas between

    // Header: Metric | newest | Δ | prev | Δ | prev | …  (newest on the left)
    let head = '<th class="mb-th-metric">Metric</th>';
    months.forEach((mo, i) => {
        const isEditCol = (mo === _mbEditable);
        head += '<th class="mb-th-val' + (isEditCol ? ' mb-th-current' : '') + '">' + _mbMonthLabelShort(mo) + '</th>';
        if (i < months.length - 1) head += '<th class="mb-th-delta">Δ</th>';
    });

    // Group metrics by section (preserve catalog order)
    const sections = [];
    const bySection = {};
    _mbMetrics.forEach(m => {
        if (!bySection[m.section]) { bySection[m.section] = []; sections.push(m.section); }
        bySection[m.section].push(m);
    });

    let html = '<table class="mb-table"><thead><tr>' + head + '</tr></thead><tbody>';

    sections.forEach(sec => {
        html += '<tr class="mb-section-row"><td colspan="' + totalCols + '">' + sec + '</td></tr>';
        bySection[sec].forEach(m => {
            html += '<tr class="mb-row"><td class="mb-metric-name" title="' + m.label + '">' + m.label + '</td>';
            months.forEach((mo, i) => {
                const v = (_mbData[mo] || {})[m.key];
                // Value cell — editable month becomes an input in edit mode
                if (_mbEditing && canEdit && mo === _mbEditable) {
                    const step = (m.type === 'int') ? '1' : (m.type === 'rating' ? '0.1' : '0.01');
                    if (_mbIsDerived(m)) {
                        // Computed cell — locked. Either a spreadsheet formula that
                        // fills itself from the other inputs, or a cross-period row
                        // (YoY) that isn't stored at all and so has nothing to type.
                        const auto = _MB_DERIVED_KEYS.has(m.key) ? 'Auto-calculated' : 'Calculated from history';
                        html += '<td class="mb-val mb-val-primary"><input class="mb-input mb-input-auto" type="number" disabled ' +
                            'title="' + auto + '" placeholder="auto" id="mb-in-' + m.key + '" value="' + (v != null ? v : '') + '"></td>';
                    } else {
                        html += '<td class="mb-val mb-val-primary"><input class="mb-input" type="number" step="' + step +
                            '" id="mb-in-' + m.key + '" value="' + (v != null ? v : '') + '" oninput="_mbLiveDerive(\'mb-in-\')"></td>';
                    }
                } else {
                    const ebayOverride = _mbEbayThresholdCls(m.key, v);
                    let cls;
                    if (ebayOverride !== null) {
                        // Clear eBay cells in the current month keep the primary column tint
                        cls = (ebayOverride === 'mb-val' && mo === _mbEditable) ? 'mb-val mb-val-primary' : ebayOverride;
                    } else {
                        cls = (mo === _mbEditable) ? 'mb-val mb-val-primary' : 'mb-val';
                    }
                    html += '<td class="' + cls + '">' + _mbFmt(m.type, v) + '</td>';
                }
                // Delta between this (newer, left) and the next (older, right) month.
                // diff = new − old so a positive value means it grew vs the prior month.
                if (i < months.length - 1) {
                    const older = (_mbData[months[i + 1]] || {})[m.key];
                    let chip = '<span class="mb-dash">—</span>';
                    if (v != null && older != null && !isNaN(v) && !isNaN(older)) {
                        const diff = Number(v) - Number(older);
                        if (diff === 0) {
                            chip = '<span class="mb-chip mb-chip-flat">0</span>';
                        } else if (_MB_NO_SHADE.has(m.key)) {
                            // direction only, no good/bad color
                            chip = '<span class="mb-chip mb-chip-flat">' +
                                (diff > 0 ? '▲' : '▼') + ' ' + _mbDeltaMag(m.type, diff) + '</span>';
                        } else {
                            // arrow = direction of change; color = good/bad for this metric
                            const good  = _MB_INVERSE.has(m.key) ? (diff < 0) : (diff > 0);
                            const arrow = diff > 0 ? '▲' : '▼';
                            chip = '<span class="mb-chip ' + (good ? 'mb-up' : 'mb-down') + '">' +
                                arrow + ' ' + _mbDeltaMag(m.type, diff) + '</span>';
                        }
                    }
                    html += '<td class="mb-delta">' + chip + '</td>';
                }
            });
            html += '</tr>';
        });
    });

    html += '</tbody></table>';
    body.innerHTML = html;
}

// Returns an override CSS class for eBay Health metrics based on absolute thresholds.
// Returns null for non-eBay-health metrics (fall through to best/worst logic).
function _mbEbayThresholdCls(key, val) {
    if (val == null) return null;
    const v = Number(val);
    if (isNaN(v)) return null;
    // Red fires at 80% of the way to the eBay limit (was 100%); warn at 50%.
    if (key === 'defect_rate') {
        if (v >= 0.40) return 'mb-val mb-ebay-bad';
        if (v >= 0.25) return 'mb-val mb-ebay-warn';
        return 'mb-val';
    }
    if (key === 'late_shipment_rate') {
        if (v >= 2.4) return 'mb-val mb-ebay-bad';
        if (v >= 1.5) return 'mb-val mb-ebay-warn';
        return 'mb-val';
    }
    if (key === 'case_no_resolution') {
        if (v >= 0.24) return 'mb-val mb-ebay-bad';
        if (v >= 0.15) return 'mb-val mb-ebay-warn';
        return 'mb-val';
    }
    if (key === 'tracking_uploaded') {
        if (v <= 96.0)  return 'mb-val mb-ebay-bad';
        if (v <= 97.5)  return 'mb-val mb-ebay-warn';
        return 'mb-val';
    }

    return null;
}

// OVERVIEW render: metrics × stores for the most-recent month, with the
// best store per metric flagged green and the worst red (honoring inverse metrics).
function _mbRenderOverview() {
    const body = document.getElementById('mbBody');
    if (!body) return;

    // DM and CEO can edit the current (editable) month across all stores from here
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    const isDM = role === 'district manager';
    const canEdit = (isDM || role === 'ceo' || role === 'owner manager') && !!_mbOverviewEditable;
    const editing = _mbEditing && canEdit;
    // Editing always targets the open window. Otherwise: the month picked in the
    // dropdown, falling back to the most recent one with data.
    const shownMonth = editing ? _mbOverviewEditable : (_mbOverviewPick || _mbOverviewMonth);

    const editBtn = document.getElementById('mbEditBtn');
    if (editBtn) editBtn.style.display = (canEdit && !_mbEditing) ? 'inline-block' : 'none';
    const saveBtn = document.getElementById('mbSaveBtn');
    const cancelBtn = document.getElementById('mbCancelBtn');
    if (saveBtn)   saveBtn.style.display   = (editing) ? 'inline-block' : 'none';
    if (cancelBtn) cancelBtn.style.display = (editing) ? 'inline-block' : 'none';

    if (!shownMonth) { body.innerHTML = '<div class="status-message">No data available.</div>'; return; }

    const sections = [], bySection = {};
    _mbMetrics.forEach(m => {
        if (!bySection[m.section]) { bySection[m.section] = []; sections.push(m.section); }
        bySection[m.section].push(m);
    });

    const totalCols = 1 + MB_STORES.length;
    let head = '<th class="mb-th-metric">Metric</th>';
    MB_STORES.forEach(s => head += '<th class="mb-th-val">' + s + '</th>');

    let html = '<div class="mb-overview-cap">All Stores · ' + _mbMonthLabel(shownMonth) +
        (editing ? '  ·  entering current month' : '') + '</div>';
    html += '<table class="mb-table mb-table-overview"><thead><tr>' + head + '</tr></thead><tbody>';

    sections.forEach(sec => {
        html += '<tr class="mb-section-row"><td colspan="' + totalCols + '">' + sec + '</td></tr>';
        bySection[sec].forEach(m => {
            const raw = MB_STORES.map(s => {
                const x = (_mbOverviewData[s] && _mbOverviewData[s][shownMonth] || {})[m.key];
                return (x == null || isNaN(x)) ? null : Number(x);
            });
            // A CHANGE metric is graded on direction, not on rank. Ranking asks
            // "who has the biggest number" — fine for Buying, wrong for YoY
            // Buying, where every store on the row may have grown. With only two
            // stores holding a prior year, rank-shading is forced to paint one of
            // them red: LEE grew $30,595 (+49%) and was marked worst for trailing
            // OVL by $2,567. Sign is the honest signal — up is green, down is red.
            const changeMetric = _mbIsChangeMetric(m);
            // best / worst store for this metric (only when not editing, ≥2 have data, and they differ)
            let bestIdx = -1, worstIdx = -1;
            if (!editing && !changeMetric && !_MB_NO_SHADE.has(m.key) && raw.filter(x => x != null).length >= 2) {
                const inv = _MB_INVERSE.has(m.key);
                let best = inv ? Infinity : -Infinity, worst = inv ? -Infinity : Infinity;
                raw.forEach((x, idx) => {
                    if (x == null) return;
                    if (inv ? x < best : x > best) { best = x; bestIdx = idx; }
                    if (inv ? x > worst : x < worst) { worst = x; worstIdx = idx; }
                });
                if (best === worst) { bestIdx = worstIdx = -1; }
            }
            html += '<tr class="mb-row"><td class="mb-metric-name" title="' + m.label + '">' + m.label + '</td>';
            MB_STORES.forEach((s, idx) => {
                if (editing) {
                    const step = (m.type === 'int') ? '1' : (m.type === 'rating' ? '0.1' : '0.01');
                    if (_mbIsDerived(m)) {
                        const auto = _MB_DERIVED_KEYS.has(m.key) ? 'Auto-calculated' : 'Calculated from history';
                        html += '<td class="mb-val"><input class="mb-input mb-input-auto" type="number" disabled ' +
                            'title="' + auto + '" placeholder="auto" id="mb-ov-' + s + '-' + m.key + '" value="' + (raw[idx] != null ? raw[idx] : '') + '"></td>';
                    } else {
                        html += '<td class="mb-val"><input class="mb-input" type="number" step="' + step +
                            '" id="mb-ov-' + s + '-' + m.key + '" value="' + (raw[idx] != null ? raw[idx] : '') +
                            '" oninput="_mbLiveDerive(\'mb-ov-' + s + '-\')"></td>';
                    }
                } else {
                    const ebayOverride = _mbEbayThresholdCls(m.key, raw[idx]);
                    let cls;
                    if (ebayOverride !== null) {
                        cls = ebayOverride;
                    } else if (changeMetric) {
                        // Direction, honouring the row's own "lower is better" —
                        // a YoY of refunds should be green when it FALLS. Same
                        // rule the store-view delta chips already use.
                        cls = 'mb-val' + _mbChangeCls(m, raw[idx]);
                    } else {
                        cls = idx === bestIdx ? 'mb-val mb-best' : (idx === worstIdx ? 'mb-val mb-worst' : 'mb-val');
                    }
                    html += '<td class="' + cls + '">' + _mbFmt(m.type, raw[idx]) + '</td>';
                }
            });
            html += '</tr>';
        });
    });
    html += '</tbody></table>';
    body.innerHTML = html;
}

// `months` (oldest → newest) comes from the date-range picker; with no args the
// export falls back to the on-screen window, as it always did.
function mbExportCSV(months, spanTag) {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    const canPickStore = role === 'ceo' || role === 'district manager';
    const sel   = document.getElementById('mbStoreSelect');
    const store = (sel && canPickStore ? sel.value : null) || sessionStorage.getItem('speeksUserStore') || 'STORE';
    const ts    = new Date().toISOString().slice(0, 10);

    const esc = v => { const s = String(v == null ? '' : v); return (s.includes(',') || s.includes('"') || s.includes('\n')) ? '"' + s.replace(/"/g, '""') + '"' : s; };
    const toCSV = rows => rows.map(r => r.map(esc).join(',')).join('\r\n');
    const dl = (csv, name) => {
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
        const url  = URL.createObjectURL(blob);
        const a    = document.createElement('a'); a.href = url; a.download = name; a.style.display = 'none';
        document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
    };

    const sections = {}, secOrder = [];
    _mbMetrics.forEach(m => { if (!sections[m.section]) { sections[m.section] = []; secOrder.push(m.section); } sections[m.section].push(m); });

    const span = spanTag ? spanTag + '_' : '';

    if (_mbView === 'overview') {
        // Multi-month overview pivots to one row per metric PER STORE so every
        // selected month gets its own column; a single month keeps the old
        // stores-across-the-top shape that people are used to.
        const cols = (months && months.length) ? months : (_mbOverviewMonth ? [_mbOverviewMonth] : []);
        if (!cols.length || !_mbMetrics.length) return;

        let rows;
        if (cols.length === 1) {
            rows = [['Section', 'Metric', ...MB_STORES]];
            secOrder.forEach(sec => {
                sections[sec].forEach(m => {
                    const row = [sec, m.label];
                    MB_STORES.forEach(s => { const v = (_mbOverviewData[s] || {})[cols[0]]; row.push(v ? v[m.key] : ''); });
                    rows.push(row);
                });
            });
        } else {
            rows = [['Section', 'Metric', 'Store', ...cols.map(_mbMonthLabelShort)]];
            secOrder.forEach(sec => {
                sections[sec].forEach(m => {
                    MB_STORES.forEach(s => {
                        const row = [sec, m.label, s];
                        cols.forEach(mo => { const v = (_mbOverviewData[s] || {})[mo]; row.push(v && v[m.key] != null ? v[m.key] : ''); });
                        rows.push(row);
                    });
                });
            });
        }
        const tag = cols.length === 1 ? _mbMonthLabelShort(cols[0]).replace(/[^a-zA-Z0-9]/g, '_') + '_' : span;
        dl(toCSV(rows), 'Monthly_Overview_' + tag + ts + '.csv');
    } else {
        const cols = (months && months.length)
            ? months
            : [...new Set(_mbMonths)].sort().reverse().slice(0, MB_MONTH_WINDOW)
                  .filter(mo => _mbData[mo] && Object.keys(_mbData[mo]).length).reverse();
        if (!_mbMetrics.length || !cols.length) return;
        const rows = [['Section', 'Metric', ...cols.map(_mbMonthLabelShort)]];
        secOrder.forEach(sec => {
            sections[sec].forEach(m => {
                const row = [sec, m.label];
                cols.forEach(mo => { const v = (_mbData[mo] || {})[m.key]; row.push(v != null ? v : ''); });
                rows.push(row);
            });
        });
        dl(toCSV(rows), store + '_Monthly_Brief_' + span + ts + '.csv');
    }
}

// --- 11d. MODULE: CSV EXPORT DATE-RANGE PICKER ------------------------------
// The Export buttons used to dump whatever the on-screen window happened to be
// holding — 4 weeks of KPIs, 6 months of Breakdown — even though the backend
// keeps the whole history. This popup lets anyone with an Export button choose a
// span instead (6 weeks, 8 weeks, a year of months…).
//
// Only periods that actually carry saved data are offered, so an empty export
// isn't reachable. Weekly/monthly KPI options come from kpi-manage
// `?mode=available` and the rows themselves from `?mode=range`; monthly-brief
// already returns every month, so the Breakdown picker derives its options from
// data that's already in memory.
let _exCtx = null;   // { kind, unit, opts:[{value,label,count}], picked, preset, busy }

const _EX_PRESETS = {
    weekly:  [{ n: 4, t: '4 weeks' },  { n: 8, t: '8 weeks' },  { n: 12, t: '12 weeks' },  { n: 0, t: 'All' }],
    monthly: [{ n: 3, t: '3 months' }, { n: 6, t: '6 months' }, { n: 12, t: '12 months' }, { n: 0, t: 'All' }],
};

function _exWeekLabel(dateStr) {
    const end = new Date(dateStr + 'T12:00:00');
    const start = new Date(end);
    start.setDate(start.getDate() - 6);
    const mo = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return mo[start.getMonth()] + ' ' + start.getDate() + ' – ' + mo[end.getMonth()] + ' ' + end.getDate();
}

function _exEnsureModal() {
    let el = document.getElementById('exportRangeModal');
    if (el) return el;
    el = document.createElement('div');
    el.id = 'exportRangeModal';
    el.className = 'ex-overlay';
    el.addEventListener('click', function(e) { if (e.target === el) _exClose(); });
    el.innerHTML =
        '<div class="ex-card" role="dialog" aria-modal="true" aria-labelledby="exTitle">' +
          '<div class="ex-head">' +
            '<span class="ex-ico"><svg viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>' +
              '<polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg></span>' +
            '<div class="ex-titles">' +
              '<span class="ex-eyebrow">Export CSV</span>' +
              '<span class="ex-title" id="exTitle">Choose a date range</span>' +
              '<span class="ex-sub" id="exSub"></span>' +
            '</div>' +
            '<button type="button" class="ex-close" onclick="_exClose()" title="Close">&times;</button>' +
          '</div>' +
          '<div class="ex-body" id="exBody"></div>' +
        '</div>';
    document.body.appendChild(el);
    return el;
}

// Months the Breakdown actually has numbers for. Overview counts a month if ANY
// store filled it in; Store View is scoped to the store on screen.
function _exMonthOpts() {
    const tally = {};
    const bump = function(mo, k) { tally[mo] = (tally[mo] || 0) + k; };
    const filledCount = function(obj) { return Object.values(obj || {}).filter(function(v) { return v != null; }).length; };
    if (_mbView === 'overview') {
        MB_STORES.forEach(function(s) {
            const d = _mbOverviewData[s] || {};
            Object.keys(d).forEach(function(mo) { const f = filledCount(d[mo]); if (f) bump(mo, f); });
        });
    } else {
        Object.keys(_mbData || {}).forEach(function(mo) { const f = filledCount(_mbData[mo]); if (f) bump(mo, f); });
    }
    return Object.keys(tally).sort().reverse().map(function(mo) {
        return { value: mo, label: _mbMonthLabelShort(mo), count: tally[mo] };
    });
}

async function _exOpen(kind) {
    const el = _exEnsureModal();
    el.classList.add('open');
    const unit = (kind === 'kpi') ? _kpiCurrentTab : 'monthly';
    _exCtx = { kind: kind, unit: unit, opts: [], picked: [], preset: null, busy: true };

    const sub = document.getElementById('exSub');
    if (sub) {
        sub.textContent = (kind === 'kpi')
            ? 'Store KPIs · ' + (unit === 'weekly' ? 'weekly' : 'monthly') + ' · ' + (_kpiResolveStore() || '')
            : 'Monthly Breakdown · ' + (_mbView === 'overview' ? 'all stores' : (document.getElementById('mbStoreSelect') || {}).value || 'store view');
    }
    _exRender();

    try {
        if (kind === 'kpi') {
            const store = _kpiResolveStore();
            const data = await fetch(KPI_MANAGE_URL + '?store=' + store + '&period_type=' + unit +
                                     '&mode=available&v=' + Date.now()).then(function(r) { return r.json(); });
            _exCtx.opts = (data.periods || []).map(function(p) {
                return {
                    value: p.period_end_date,
                    label: unit === 'weekly' ? _exWeekLabel(p.period_end_date) : (p.period_label || p.period_end_date),
                    count: p.saved_count || 0,
                };
            });
        } else {
            _exCtx.opts = _exMonthOpts();
        }
    } catch (e) {
        _exCtx.opts = [];
    }
    _exCtx.busy = false;
    _exRender();
}

function _exRender() {
    const body = document.getElementById('exBody');
    if (!body || !_exCtx) return;

    if (_exCtx.busy) {
        body.innerHTML = '<div class="ex-status">Checking what’s available…</div>';
        return;
    }
    if (!_exCtx.opts.length) {
        body.innerHTML = '<div class="ex-status">Nothing saved yet — there’s no data in this view to export.</div>' +
            '<div class="ex-actions"><button type="button" class="btn-secondary" onclick="_exClose()">Close</button></div>';
        return;
    }

    const presets = _EX_PRESETS[_exCtx.unit]
        .filter(function(p) { return p.n === 0 || p.n <= _exCtx.opts.length; })
        .map(function(p) { return '<button type="button" class="ex-chip" data-n="' + p.n + '" onclick="_exPreset(' + p.n + ')">' + p.t + '</button>'; })
        .join('');
    // Both selects share one newest-first list; the span is min..max of the two,
    // so picking them "backwards" still works.
    const optsHtml = _exCtx.opts.map(function(x, i) { return '<option value="' + i + '">' + x.label + '</option>'; }).join('');

    body.innerHTML =
        '<div class="ex-presets">' + presets + '</div>' +
        '<div class="ex-fields">' +
          '<label class="ex-field"><span>From</span><select id="exFrom" class="kpi-select" onchange="_exSync()">' + optsHtml + '</select></label>' +
          '<span class="ex-dash" aria-hidden="true">→</span>' +
          '<label class="ex-field"><span>To</span><select id="exTo" class="kpi-select" onchange="_exSync()">' + optsHtml + '</select></label>' +
        '</div>' +
        '<div class="ex-summary" id="exSummary"></div>' +
        '<div class="ex-actions">' +
          '<button type="button" class="btn-secondary" onclick="_exClose()">Cancel</button>' +
          '<button type="button" class="btn-primary" id="exGo" onclick="_exConfirm()">Download CSV</button>' +
        '</div>';

    const want = _exCtx.unit === 'weekly' ? 8 : 6;
    _exPreset(_exCtx.opts.length >= want ? want : 0);
}

function _exPreset(count) {
    if (!_exCtx || !_exCtx.opts.length) return;
    const from = document.getElementById('exFrom'), to = document.getElementById('exTo');
    if (!from || !to) return;
    const last = _exCtx.opts.length - 1;
    to.value   = '0';
    from.value = String(count === 0 ? last : Math.min(count - 1, last));
    _exSync();
}

function _exSync() {
    if (!_exCtx) return;
    const from = document.getElementById('exFrom'), to = document.getElementById('exTo');
    if (!from || !to) return;

    const a = Math.min(Number(from.value), Number(to.value));
    const b = Math.max(Number(from.value), Number(to.value));
    const picked = _exCtx.opts.slice(a, b + 1);      // still newest-first
    _exCtx.picked = picked;

    const unitWord = _exCtx.unit === 'weekly' ? 'week' : 'month';
    const rows = picked.reduce(function(t, x) { return t + (x.count || 0); }, 0);
    const sum = document.getElementById('exSummary');
    if (sum) {
        sum.innerHTML = '<b>' + picked.length + ' ' + unitWord + (picked.length === 1 ? '' : 's') + '</b>' +
            '<span class="ex-sum-range">' + picked[picked.length - 1].label + ' → ' + picked[0].label + '</span>' +
            (rows ? '<span class="ex-sum-rows">' + rows + ' row' + (rows === 1 ? '' : 's') + '</span>' : '');
    }
    // light up whichever preset matches the current span
    const all = _exCtx.opts.length;
    Array.prototype.forEach.call(document.querySelectorAll('#exBody .ex-chip'), function(c) {
        const n = Number(c.dataset.n);
        c.classList.toggle('active', n === 0 ? picked.length === all : picked.length === n);
    });
}

async function _exConfirm() {
    if (!_exCtx || !_exCtx.picked || !_exCtx.picked.length) return;
    const picked = _exCtx.picked;                       // newest-first
    const oldest = picked[picked.length - 1].value;
    const newest = picked[0].value;
    const tag    = oldest + '_to_' + newest;
    const kind   = _exCtx.kind;
    const go     = document.getElementById('exGo');
    if (go) { go.disabled = true; go.textContent = 'Preparing…'; }

    try {
        if (kind === 'kpi') {
            const store = _kpiResolveStore();
            const data = await fetch(KPI_MANAGE_URL + '?store=' + store + '&period_type=' + _kpiCurrentTab +
                                     '&mode=range&from=' + oldest + '&to=' + newest + '&v=' + Date.now())
                                 .then(function(r) { return r.json(); });
            const periods = data.periods || [];
            if (!periods.length) { alert('No KPI rows are saved in that range.'); return; }
            _kpiExportCSV(periods, tag);
        } else {
            mbExportCSV(picked.map(function(x) { return x.value; }).reverse(), tag);   // oldest → newest
        }
        _exClose();
    } catch (e) {
        alert('Export failed — please try again.');
    } finally {
        if (go) { go.disabled = false; go.textContent = 'Download CSV'; }
    }
}

function _exClose() {
    const el = document.getElementById('exportRangeModal');
    if (el) el.classList.remove('open');
    _exCtx = null;
}

// ── Manage Rows: the row catalog editor (DM / CEO / owner-manager) ──────────
// The rows on this report are data, not code — monthly_brief_metrics. Values
// stay in monthly_brief keyed by metric_key, which is already EAV, so adding a
// row here needs no schema change and no deploy.
let _mbmCatalog = [], _mbmInUse = new Set(), _mbmFormulas = [], _mbmEditingKey = null;
// metric_key -> how many stored values it has. Drives how loudly a hard delete
// warns; an empty row is a trivial cleanup, a populated one is irreversible.
let _mbmInUseCounts = {};

// Plain-English names for the calculations, so the dropdown doesn't show raw
// formula keys. An unlisted key falls back to the key itself rather than
// vanishing — a formula the app can run should always be selectable.
const _MBM_FORMULA_LABELS = {
    yoy_pct:   'Year over year — % change',
    yoy_delta: 'Year over year — change in $ (or unit)',
    yoy_prior: 'Year over year — same month last year',
};

function _mbCanManageRows() {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    return role === 'district manager' || role === 'ceo'
        || role === 'owner manager' || role === 'owner (manager)';
}

async function mbOpenManageRows() {
    if (!_mbCanManageRows()) return;
    toggleModal('mbRowsModal');
    _mbmEditingKey = null;
    const form = document.getElementById('mbRowsForm');
    if (form) form.style.display = 'none';
    await _mbmLoad();
}

async function _mbmLoad() {
    const body = document.getElementById('mbRowsBody');
    if (body) body.innerHTML = '<div class="dmx-empty" style="padding:60px 0;">Syncing…</div>';
    try {
        const d = await fetch(MONTHLY_BRIEF_URL + '?catalog=1&v=' + Date.now()).then(r => r.json());
        _mbmCatalog     = d.catalog || [];
        _mbmInUse       = new Set(d.in_use || []);
        _mbmInUseCounts = d.in_use_counts || {};
        _mbmFormulas    = d.formulas || [];
        _mbmRender();
    } catch (e) {
        if (body) body.innerHTML = '<div class="dmx-empty" style="padding:60px 0; color:var(--red-alert);">Could not load the row catalog.</div>';
    }
}

function _mbmRender() {
    const body = document.getElementById('mbRowsBody');
    if (!body) return;
    // Subtitle carries the standing rule (it used to be a footer note) plus the
    // live count — same place every other tool modal explains itself.
    const sub = document.getElementById('mbRowsSub');
    const live = _mbmCatalog.filter(r => r.active).length;
    if (sub) sub.textContent = 'Rows apply to every store. Hiding one keeps its history. · ' +
        live + ' visible' + (_mbmCatalog.length > live ? ' · ' + (_mbmCatalog.length - live) + ' hidden' : '');

    const sections = [], bySection = {};
    _mbmCatalog.forEach(r => {
        if (!bySection[r.section]) { bySection[r.section] = []; sections.push(r.section); }
        bySection[r.section].push(r);
    });
    // Remembered so the section buttons can index into exactly what was drawn —
    // recomputing the order in the handlers is how the two would drift apart.
    _mbmSectionOrder = sections;

    let html = '';
    sections.forEach((sec, si) => {
        // Sections are indexed rather than keyed by name: names contain spaces
        // and ampersands ("Buying & Customers"), which don't survive being
        // dropped into an element id or an inline onclick argument.
        const count = bySection[sec].length;
        html += '<div class="mbm-sec">' +
            '<span class="mbm-sec-name">' + escapeHtml(sec) + '</span>' +
            '<span class="mbm-sec-count">' + count + ' row' + (count === 1 ? '' : 's') + '</span>' +
            '<span class="mbm-sec-actions">' +
              '<button type="button" class="mbm-sec-btn" onclick="_mbmRenameSection(' + si + ')">Rename</button>' +
              // Only offered when there's somewhere to send the rows. With one
              // section left, deleting it would leave every row homeless.
              (sections.length > 1
                ? '<button type="button" class="mbm-sec-btn mbm-danger" onclick="_mbmDeleteSection(' + si + ')">Delete</button>'
                : '') +
            '</span>' +
          '</div>' +
          '<div class="mbm-sec-move" id="mbmSecMove-' + si + '" style="display:none;"></div>';
        bySection[sec].forEach(r => {
            const derived = r.source === 'derived';
            const legacy  = derived && r.formula_key === 'legacy';
            // Label only. The key, type, flags and formula used to sit here as
            // chips, which made the list a wall of grey text — and all of it is
            // already visible (and editable) one click away in the Edit form,
            // which is where it's actually useful.
            html += '<div class="mbm-row' + (r.active ? '' : ' is-retired') + '">' +
                '<div class="mbm-row-main">' +
                  '<span class="mbm-label">' + escapeHtml(r.label) + '</span>' +
                '</div>' +
                '<div class="mbm-row-actions">' +
                  // The 13 spreadsheet formulas are wired to code in _MB_DERIVED;
                  // editing their key or type from here would break that binding,
                  // so they're read-only. Everything else is fair game.
                  (legacy ? '<span class="mbm-locked">Built In</span>'
                          : '<button type="button" class="btn-secondary mbm-btn" onclick="_mbmEdit(\'' + r.metric_key + '\')">Edit</button>') +
                  (r.active
                    ? (legacy ? '' : '<button type="button" class="btn-secondary mbm-btn" onclick="_mbmRetire(\'' + r.metric_key + '\')">Hide</button>')
                    : '<button type="button" class="btn-secondary mbm-btn" onclick="_mbmRestore(\'' + r.metric_key + '\')">Show</button>') +
                  // Hard delete sits beside Hide rather than replacing it: Hide
                  // is the reversible one and stays the default, this is for a
                  // row that shouldn't exist. Built-ins are excluded — they're
                  // bound to code.
                  (legacy ? '' : '<button type="button" class="btn-secondary mbm-btn mbm-danger" onclick="_mbmPurge(\'' + r.metric_key + '\')">Delete</button>') +
                '</div>' +
              '</div>';
        });
    });
    body.innerHTML = html || '<div class="dmx-empty" style="padding:60px 0;">No rows yet.</div>';
}

// ---- sections -------------------------------------------------------------
// A section has no record of its own; it exists only because rows carry its
// name. So renaming and deleting are the same write — point the rows elsewhere —
// and both go through the one `rename_section` action.
let _mbmSectionOrder = [];

async function _mbmSectionWrite(from, to, okMsg) {
    const pin = sessionStorage.getItem('speeksUserPin');
    if (!pin) { alert('Session expired — sign in again.'); return; }
    try {
        const resp = await fetch(MONTHLY_BRIEF_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-user-pin': pin },
            body: JSON.stringify({ action: 'rename_section', from, to }),
        });
        const result = await resp.json();
        if (!resp.ok || result.error) throw new Error(result.error || 'Failed');
        await _mbmLoad();
        await fetchMonthlyBrief();   // the brief behind the modal is now stale
    } catch (e) {
        alert((okMsg || 'Could not update the section') + ': ' + (e.message || e));
    }
}

function _mbmRenameSection(si) {
    const from = _mbmSectionOrder[si];
    if (!from) return;
    const to = prompt('Rename this section.\n\nEvery row in it moves with the name.', from);
    if (to === null) return;                       // cancelled
    const next = String(to).trim();
    if (!next || next === from) return;
    // Renaming ONTO an existing section merges the two — worth saying out loud,
    // because it looks like a rename and behaves like a merge.
    if (_mbmSectionOrder.indexOf(next) !== -1 &&
        !confirm('“' + next + '” already exists. Its rows and this section\'s will be combined.\n\nContinue?')) return;
    _mbmSectionWrite(from, next, 'Could not rename the section');
}

// Delete needs a destination: the rows have to land somewhere, so this opens an
// inline picker rather than a confirm that silently guesses.
function _mbmDeleteSection(si) {
    const sec  = _mbmSectionOrder[si];
    const wrap = document.getElementById('mbmSecMove-' + si);
    if (!sec || !wrap) return;
    if (wrap.style.display !== 'none') { wrap.style.display = 'none'; return; }  // toggle shut
    const others = _mbmSectionOrder.filter(s => s !== sec);
    if (!others.length) return;
    const n = (_mbmCatalog.filter(r => r.section === sec) || []).length;
    wrap.innerHTML =
        '<span class="mbm-sec-move-label">Move ' + n + ' row' + (n === 1 ? '' : 's') + ' to</span>' +
        '<select id="mbmSecMoveTo-' + si + '">' +
          others.map(s => '<option value="' + escapeHtml(s) + '">' + escapeHtml(s) + '</option>').join('') +
        '</select>' +
        '<button type="button" class="mbm-sec-btn mbm-danger" onclick="_mbmDoDeleteSection(' + si + ')">Move &amp; Delete</button>' +
        '<button type="button" class="mbm-sec-btn" onclick="document.getElementById(\'mbmSecMove-' + si + '\').style.display=\'none\'">Cancel</button>';
    wrap.style.display = '';
}

function _mbmDoDeleteSection(si) {
    const from = _mbmSectionOrder[si];
    const sel  = document.getElementById('mbmSecMoveTo-' + si);
    if (!from || !sel || !sel.value) return;
    _mbmSectionWrite(from, sel.value, 'Could not delete the section');
}

function _mbmNew()  { _mbmEditingKey = null; _mbmShowForm(null); }
function _mbmEdit(key) {
    const r = _mbmCatalog.find(x => x.metric_key === key);
    if (!r) return;
    _mbmEditingKey = key;
    _mbmShowForm(r);
}
function _mbmCancel() {
    _mbmEditingKey = null;
    const form = document.getElementById('mbRowsForm');
    if (form) form.style.display = 'none';
}

function _mbmShowForm(r) {
    const form = document.getElementById('mbRowsForm');
    if (!form) return;
    const isNew = !r;
    const v = k => (r && r[k] != null ? String(r[k]) : '');
    const sections = [...new Set(_mbmCatalog.map(x => x.section))];
    // Only manual rows can be compared year over year: a YoY of a YoY is
    // meaningless, and the legacy formulas already recompute per month.
    const sourceable = _mbmCatalog.filter(x => x.source === 'manual' && x.active);

    form.innerHTML =
      '<div class="mbm-form-head">' + (isNew ? 'Add a row' : 'Edit “' + escapeHtml(r.label) + '”') + '</div>' +
      '<div class="mbm-grid">' +
        '<label class="mbm-field"><span>Label</span>' +
          '<input id="mbmLabel" type="text" maxlength="80" value="' + escapeHtml(v('label')) + '" placeholder="YoY Buying"></label>' +
        '<label class="mbm-field"><span>Key</span>' +
          '<input id="mbmKey" type="text" maxlength="60" value="' + escapeHtml(v('metric_key')) + '" placeholder="yoy_buying"' +
          (isNew ? '' : ' disabled title="The key is what every stored value is filed under — it can\'t change"') + '></label>' +
        // A real <select>, not an <input list=...> + <datalist>. The datalist
        // version rendered as a plain text box: Chrome only reveals its arrow on
        // focus and Firefox shows nothing, so the options were invisible unless
        // you already knew to guess at them. Sections still have to be
        // extensible, hence the "+ New section" escape hatch below.
        '<label class="mbm-field"><span>Section</span>' +
          '<select id="mbmSection" onchange="_mbmToggleSection()">' +
            sections.map(s => '<option value="' + escapeHtml(s) + '"' +
              (v('section') === s ? ' selected' : '') + '>' + escapeHtml(s) + '</option>').join('') +
            '<option value="__new">+ New section…</option>' +
          '</select></label>' +
        '<label class="mbm-field" id="mbmSectionNewWrap" style="display:none;"><span>New section name</span>' +
          '<input id="mbmSectionNew" type="text" maxlength="60" placeholder="Marketing"></label>' +
        '<label class="mbm-field"><span>Format</span><select id="mbmType">' +
          ['money', 'pct', 'int', 'rating', 'num'].map(t =>
            '<option value="' + t + '"' + (v('type') === t ? ' selected' : '') + '>' + t + '</option>').join('') +
        '</select></label>' +
        '<label class="mbm-field"><span>Position</span>' +
          '<input id="mbmOrder" type="number" step="1" value="' + (v('sort_order') || '999') + '" title="Lower numbers sort higher. Existing rows are spaced by 10."></label>' +
        '<label class="mbm-field"><span>Value comes from</span><select id="mbmSource" onchange="_mbmToggleFormula()">' +
          '<option value="manual"' + (v('source') !== 'derived' ? ' selected' : '') + '>Typed in each month</option>' +
          '<option value="derived"' + (v('source') === 'derived' ? ' selected' : '') + '>Calculated</option>' +
        '</select></label>' +
      '</div>' +
      '<div id="mbmFormulaWrap" class="mbm-grid" style="display:none;">' +
        '<label class="mbm-field"><span>Calculation</span><select id="mbmFormula">' +
          // Offered straight from what the app can actually evaluate (the fn's
          // KNOWN_FORMULAS), minus 'legacy', which isn't a choice — it's the tag
          // on the 13 built-in spreadsheet formulas.
          _mbmFormulas.filter(f => f !== 'legacy').map(f =>
            '<option value="' + f + '"' + (v('formula_key') === f ? ' selected' : '') + '>' +
            escapeHtml(_MBM_FORMULA_LABELS[f] || f) + '</option>').join('') +
        '</select></label>' +
        '<label class="mbm-field"><span>Compare which row</span><select id="mbmFormulaArg">' +
          sourceable.map(x => '<option value="' + x.metric_key + '"' + (v('formula_arg') === x.metric_key ? ' selected' : '') + '>' +
            escapeHtml(x.label) + '</option>').join('') +
        '</select></label>' +
      '</div>' +
      '<div class="mbm-checks">' +
        '<label><input type="checkbox" id="mbmLower"' + (r && r.lower_is_better ? ' checked' : '') + '> Lower is better ' +
          '<span class="mbm-hint">(green when it falls — refunds, defect rate)</span></label>' +
        '<label><input type="checkbox" id="mbmNoShade"' + (r && r.no_shade ? ' checked' : '') + '> Never colour-grade ' +
          '<span class="mbm-hint">(running totals, external rankings)</span></label>' +
      '</div>' +
      '<div class="mbm-form-foot">' +
        '<span class="mbm-status" id="mbmStatus"></span>' +
        '<button type="button" class="btn-secondary" onclick="_mbmCancel()">Cancel</button>' +
        '<button type="button" class="btn-primary" onclick="_mbmSave()">' + (isNew ? 'Add Row' : 'Save Changes') + '</button>' +
      '</div>';
    form.style.display = 'block';
    // The form is pinned above the list, so clicking Edit on a row 30 deep left
    // the user staring at the same rows with the editor off-screen above them.
    // .manage-content is the scroller (height:60vh), not the window.
    const scroller = form.closest('.manage-content');
    if (scroller) scroller.scrollTo({ top: 0, behavior: 'smooth' });
    _mbmToggleFormula();
    _mbmToggleSection();
    // Auto-suggest a key from the label while adding, so nobody has to invent
    // snake_case by hand — but never touch it once they've typed their own.
    if (isNew) {
        const lab = document.getElementById('mbmLabel'), key = document.getElementById('mbmKey');
        let touched = false;
        key.addEventListener('input', () => { touched = true; });
        lab.addEventListener('input', () => {
            if (touched) return;
            key.value = lab.value.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60);
        });
        lab.focus();
    }
}

function _mbmToggleFormula() {
    const src = document.getElementById('mbmSource');
    const wrap = document.getElementById('mbmFormulaWrap');
    if (src && wrap) wrap.style.display = (src.value === 'derived') ? '' : 'none';
}

// Reveal the free-text box only when "+ New section" is chosen, and put the
// cursor in it — picking that option IS the request to type a name.
function _mbmToggleSection() {
    const sel  = document.getElementById('mbmSection');
    const wrap = document.getElementById('mbmSectionNewWrap');
    if (!sel || !wrap) return;
    const isNew = sel.value === '__new';
    wrap.style.display = isNew ? '' : 'none';
    if (isNew) { const el = document.getElementById('mbmSectionNew'); if (el) el.focus(); }
}

// The section as chosen: either an existing one, or whatever was typed into the
// new-section box. Returns '' when "+ New section" is picked but left blank, so
// the caller can complain rather than silently filing the row under "__new".
function _mbmSectionValue() {
    const sel = document.getElementById('mbmSection');
    if (!sel) return '';
    if (sel.value !== '__new') return sel.value;
    return (document.getElementById('mbmSectionNew') || {}).value?.trim() || '';
}

async function _mbmSave() {
    const pin = sessionStorage.getItem('speeksUserPin');
    const st  = document.getElementById('mbmStatus');
    const set = (msg, cls) => { if (st) { st.textContent = msg; st.className = 'mbm-status' + (cls ? ' ' + cls : ''); } };
    if (!pin) { set('Session expired — sign in again.', 'is-error'); return; }

    const source = document.getElementById('mbmSource').value;
    const payload = {
        action: 'save_metric',
        metric_key: (_mbmEditingKey || document.getElementById('mbmKey').value || '').trim().toLowerCase(),
        label:   document.getElementById('mbmLabel').value.trim(),
        section: _mbmSectionValue(),
        type:    document.getElementById('mbmType').value,
        sort_order: Number(document.getElementById('mbmOrder').value),
        lower_is_better: document.getElementById('mbmLower').checked,
        no_shade:        document.getElementById('mbmNoShade').checked,
        source,
        formula_key: source === 'derived' ? document.getElementById('mbmFormula').value : null,
        formula_arg: source === 'derived' ? document.getElementById('mbmFormulaArg').value : null,
    };
    if (!payload.label) { set('Give the row a label.', 'is-error'); return; }
    if (!payload.metric_key) { set('Give the row a key.', 'is-error'); return; }
    if (!payload.section) { set('Name the new section, or pick an existing one.', 'is-error'); return; }

    set('Saving…');
    try {
        const resp = await fetch(MONTHLY_BRIEF_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-user-pin': pin },
            body: JSON.stringify(payload),
        });
        const result = await resp.json();
        if (!resp.ok || result.error) throw new Error(result.error || 'Save failed');
        _mbmCancel();
        await _mbmLoad();
        // The brief behind the modal is now out of date — it was rendered from
        // the old catalog and won't show the row that was just added.
        await fetchMonthlyBrief();
    } catch (e) {
        set(String(e.message || 'Could not save'), 'is-error');
    }
}

async function _mbmSetActive(key, active) {
    const pin = sessionStorage.getItem('speeksUserPin');
    if (!pin) return;
    const row = _mbmCatalog.find(x => x.metric_key === key) || {};
    const body = active
        ? Object.assign({}, row, { action: 'save_metric', active: true })
        : { action: 'delete_metric', metric_key: key };
    try {
        const resp = await fetch(MONTHLY_BRIEF_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-user-pin': pin },
            body: JSON.stringify(body),
        });
        const result = await resp.json();
        if (!resp.ok || result.error) throw new Error(result.error || 'Failed');
        await _mbmLoad();
        await fetchMonthlyBrief();
    } catch (e) {
        alert('Could not update the row: ' + (e.message || e));
    }
}

function _mbmRetire(key) {
    // Warn only when it would hide real numbers — hiding an unused row is
    // harmless and shouldn't need a confirmation nobody reads.
    const warn = _mbmInUse.has(key)
        ? 'This row has data saved against it. Hiding it removes it from every store\'s report; the history is kept and comes back if you show it again.\n\nHide it?'
        : 'Hide this row? It disappears from every store\'s report.';
    if (!confirm(warn)) return;
    _mbmSetActive(key, false);
}
function _mbmRestore(key) { _mbmSetActive(key, true); }

// Hard delete — the row AND every value stored under it. The confirmation is
// deliberately proportional: a row added by mistake carries nothing and gets a
// one-line check; a row with history has to state the damage in figures, because
// this is the one action here that can't be undone.
async function _mbmPurge(key) {
    const row = _mbmCatalog.find(x => x.metric_key === key);
    if (!row) return;
    const n = _mbmInUseCounts[key] || 0;
    const msg = n
        ? 'DELETE “' + row.label + '” permanently?\n\n' +
          'This also destroys ' + n + ' saved value' + (n === 1 ? '' : 's') + ' across every store and every month. ' +
          'It cannot be undone.\n\nTo keep the history instead, cancel and use Hide.'
        : 'Delete “' + row.label + '” permanently?\n\nIt has no saved data, so nothing else is lost.';
    if (!confirm(msg)) return;
    // A second gate only when history is actually at stake — asking twice for an
    // empty row would just train people to click through both.
    if (n && !confirm('Last check: ' + n + ' value' + (n === 1 ? '' : 's') + ' will be deleted for good.')) return;

    const pin = sessionStorage.getItem('speeksUserPin');
    if (!pin) { alert('Session expired — sign in again.'); return; }
    try {
        const resp = await fetch(MONTHLY_BRIEF_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-user-pin': pin },
            body: JSON.stringify({ action: 'purge_metric', metric_key: key }),
        });
        const result = await resp.json();
        if (!resp.ok || result.error) throw new Error(result.error || 'Delete failed');
        await _mbmLoad();
        await fetchMonthlyBrief();
    } catch (e) {
        alert('Could not delete the row: ' + (e.message || e));
    }
}

function mbStartEdit() {
    _mbEditing = true;
    renderMonthlyBrief();
}

function mbCancelEdit() {
    _mbEditing = false;
    renderMonthlyBrief();
}

// Save dispatcher — Overview saves every store's current month, Store View saves one.
function mbSaveBrief() {
    return (_mbView === 'overview') ? mbSaveOverview() : mbSaveBriefStore();
}

async function mbSaveBriefStore() {
    const store = document.getElementById('mbStoreSelect')?.value || sessionStorage.getItem('speeksUserStore');
    const pin   = sessionStorage.getItem('speeksUserPin');
    if (!pin) { alert('Session expired — please sign in again.'); return; }

    const values = {};
    _mbMetrics.forEach(m => {
        const el = document.getElementById('mb-in-' + m.key);
        if (el) values[m.key] = el.value === '' ? null : Number(el.value);
    });
    _mbApplyDerived(values);

    const saveBtn = document.getElementById('mbSaveBtn');
    if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Saving…'; }
    try {
        const resp = await fetch(MONTHLY_BRIEF_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-user-pin': pin },
            body: JSON.stringify({ store, period_end_date: _mbEditable, values }),
        });
        const result = await resp.json();
        if (!resp.ok || result.error) throw new Error(result.error || 'Save failed');
        // Merge saved values into local cache
        _mbData[_mbEditable] = Object.assign({}, _mbData[_mbEditable] || {}, values);
        if (!_mbMonths.includes(_mbEditable)) { _mbMonths.push(_mbEditable); }
        _mbEditing = false;
        renderMonthlyBrief();
    } catch (e) {
        alert('Could not save: ' + e.message);
    } finally {
        if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = 'Save'; }
    }
}

// OVERVIEW save (DM): posts the current month for every store in parallel.
async function mbSaveOverview() {
    const pin = sessionStorage.getItem('speeksUserPin');
    if (!pin) { alert('Session expired — please sign in again.'); return; }
    const period = _mbOverviewEditable;
    if (!period) return;

    const saveBtn = document.getElementById('mbSaveBtn');
    if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Saving…'; }
    try {
        await Promise.all(MB_STORES.map(async (s) => {
            const values = {};
            _mbMetrics.forEach(m => {
                const el = document.getElementById('mb-ov-' + s + '-' + m.key);
                if (el) values[m.key] = el.value === '' ? null : Number(el.value);
            });
            _mbApplyDerived(values);
            const resp = await fetch(MONTHLY_BRIEF_URL, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'x-user-pin': pin },
                body: JSON.stringify({ store: s, period_end_date: period, values }),
            });
            const result = await resp.json();
            if (!resp.ok || result.error) throw new Error(result.error || ('Save failed for ' + s));
            _mbOverviewData[s] = _mbOverviewData[s] || {};
            _mbOverviewData[s][period] = Object.assign({}, _mbOverviewData[s][period] || {}, values);
        }));
        _mbEditing = false;
        _mbOverviewMonth = period; // the month we just entered is now the most recent with data
        // Drop any earlier month the picker was parked on, so saving lands you on
        // the numbers you just entered rather than bouncing back to the month you
        // happened to be reviewing before you clicked Edit.
        _mbOverviewPick = '';
        renderMonthlyBrief();
    } catch (e) {
        alert('Could not save: ' + e.message);
    } finally {
        if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = 'Save'; }
    }
}

function _kpiRenderMonthly(periods) {
    const body = document.getElementById('kpiModalBody');
    if (!body) return;
    const store = _kpiResolveStore();
    const sub = document.getElementById('kpiModalSubtitle');
    if (sub) sub.textContent = store + ' · Monthly';

    // Always show the current (editable) month plus any past months with saved data.
    // Rendering it even in view mode means clicking Edit just swaps its cells from
    // text to inputs IN PLACE — no new section appears, so nothing on the page shifts.
    // A period with a note but no numbers still has to render, or the note it
    // holds becomes unreachable the moment it exists.
    let visible = (periods || []).filter(function(p) { return p.is_editable || !!(p.note) || p.entries.some(function(e) { return e.id; }); });
    if (_kpiEditingPeriod) {
        const ep = periods.find(function(p) { return p.period_end_date === _kpiEditingPeriod; });
        if (ep && !visible.find(function(p) { return p.period_end_date === ep.period_end_date; })) visible.unshift(ep);
        else if (ep) { visible = visible.filter(function(p) { return p.period_end_date !== ep.period_end_date; }); visible.unshift(ep); }
    }

    _kpiSyncHeaderBtns();
    if (!visible.length) {
        body.innerHTML = '<div class="kpi-empty-state">No monthly KPI data yet. Click ✏️ Edit above to enter the current month.</div>';
        return;
    }
    const moBadges = ['Current Month','Last Month'];
    const moBClass = ['badge-current','badge-prev'];
    let tbody = '';
    visible.forEach(function(p, i) {
        const isEd = _kpiEditingPeriod === p.period_end_date;
        tbody += _kpiSectionDividerHtml('📆 ' + p.period_label, i < 2 ? moBadges[i] : null, i < 2 ? moBClass[i] : '',
            _kpiSectionControls(p.period_end_date, isEd, p.is_editable), '#7c3aed');
        tbody += _kpiHeaderRowsHtml();
        tbody += _kpiEmpRowsHtml(p.entries, p.period_end_date, isEd, false);
        tbody += _kpiAddSelfRowHtml(p, isEd);
        const hasSavedData = p.entries.some(function(e) { return e.id; });
        if (hasSavedData) tbody += _kpiStoreTotalRowHtml(p.entries);
        tbody += _kpiNoteRowHtml(p);   // last: the month's numbers, then the month's notes
    });
    body.innerHTML = '<div class="kpi-grid-scroll-wrapper"><table class="kpi-entry-grid kpi-full-table">' + _kpiColgroupHtml() + '<tbody>' + tbody + '</tbody></table></div>';
}

function _kpiSyncHeaderBtns() {
    const editBtn   = document.getElementById('kpiEditBtn');
    const saveBtn   = document.getElementById('kpiSaveBtn');
    const cancelBtn = document.getElementById('kpiCancelBtn');
    const isEditing   = !!_kpiEditingPeriod;
    const hasEditable = (_kpiPeriodsData || []).some(function(p) { return p.is_editable; });
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    const canEditRole = role === 'district manager' || role === 'ceo' || role === 'owner (manager)' || role === 'owner manager' || role === 'manager' || role === 'assistant manager';
    const hasPeriods  = (_kpiPeriodsData || []).length > 0;
    if (editBtn)   editBtn.style.display   = (!isEditing && canEditRole && (hasEditable || hasPeriods)) ? '' : 'none';
    if (saveBtn)   saveBtn.style.display   = isEditing ? '' : 'none';
    if (cancelBtn) cancelBtn.style.display = isEditing ? '' : 'none';
    _kpiDecorateEditBtn();
}

// ============================================================================
// Weekly-KPI reminder — guides managers Sat 4pm → Sun midnight (America/Chicago)
// Breadcrumb: Analytics nav-link → Store KPIs sub-tab → the Edit button.
// ============================================================================
const _KPI_REMINDER_ROLES = new Set(['manager', 'owner manager', 'owner (manager)', 'assistant manager']);

function _kpiReminderActive() {
    // Read the current wall-clock weekday + hour in Central time
    const parts = new Intl.DateTimeFormat('en-US', {
        timeZone: 'America/Chicago', weekday: 'short', hour: 'numeric', hour12: false,
    }).formatToParts(new Date());
    const wd = (parts.find(p => p.type === 'weekday') || {}).value || '';
    let hr = parseInt((parts.find(p => p.type === 'hour') || {}).value || '0', 10);
    if (hr === 24) hr = 0;                 // midnight edge
    if (wd === 'Sat') return hr >= 16;     // Saturday after 4pm
    return wd === 'Sun';                    // all day Sunday (until Mon 00:00)
}
function _kpiReminderOn() {
    return _kpiReminderActive() && _KPI_REMINDER_ROLES.has((sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim());
}

// add/remove a pulsing dot on an element (idempotent)
function _kpiToggleDot(el, on) {
    if (!el) return;
    el.classList.toggle('kpi-due', on);
    let dot = el.querySelector(':scope > .kpi-due-dot');
    if (on && !dot) { dot = document.createElement('span'); dot.className = 'kpi-due-dot'; el.appendChild(dot); }
    else if (!on && dot) dot.remove();
}

// Step 3: a nudging pill + pulse beside the Edit button (only when it's visible & on the weekly tab)
function _kpiDecorateEditBtn(force) {
    const btn = document.getElementById('kpiEditBtn');
    if (!btn) return;
    const on = (force !== undefined ? force : !!(typeof _kpiDueState === 'object' && _kpiDueState && _kpiDueState.weekly && _kpiDueState.weekly.due));
    const wants = on && btn.style.display !== 'none' && _kpiCurrentTab === 'weekly';
    btn.classList.toggle('kpi-due-pulse', wants);
    let pill = document.getElementById('kpiDuePill');
    if (wants && !pill) {
        pill = document.createElement('span');
        pill.id = 'kpiDuePill';
        pill.className = 'kpi-due-pill';
        pill.innerHTML = "Enter this week’s KPIs 👉";
        btn.parentNode.insertBefore(pill, btn);
    } else if (!wants && pill) {
        pill.remove();
    }
}

// Steps 1 & 2: dots on the Analytics nav-link + the Store KPIs sub-tab + the
// Weekly/Monthly toggles. Now data-aware: driven by _kpiDueState (populated by
// checkKpiDueReminders), so a dot only shows while the period is actually
// UNFILLED — it clears the instant the numbers are saved, not just when the
// Sat→Sun clock window closes.
function applyKpiReminder() {
    const st = (typeof _kpiDueState === 'object' && _kpiDueState) ? _kpiDueState : null;
    const wkOn = !!(st && st.weekly && st.weekly.due);
    const moOn = !!(st && st.monthly && st.monthly.due);
    const on = wkOn || moOn;                 // the Store KPIs tab needs attention if either is due
    // The workspace nav-link dot is shared with Variance Replies + Aging (all
    // live on that page): it pulses if a KPI is due OR either of those needs the
    // manager.
    const vrOn = typeof _vrDotNeeded === 'function' && _vrDotNeeded();
    const agOn = typeof _agDotNeeded === 'function' && _agDotNeeded();
    const bmOn = typeof _bmDotNeeded === 'function' && _bmDotNeeded();
    document.querySelectorAll('.nav-link[href="workspace.html"]').forEach(a => _kpiToggleDot(a, on || vrOn || agOn || bmOn));
    _kpiToggleDot(document.getElementById('ws-tab-mreplies'), bmOn);
    _kpiToggleDot(document.getElementById('ws-tab-kpis'), on);
    _kpiToggleDot(document.getElementById('ws-tab-vreplies'), vrOn);
    _kpiToggleDot(document.getElementById('ws-tab-aging'), agOn);
    _kpiToggleDot(document.getElementById('kpi-tab-weekly'), wkOn);
    _kpiToggleDot(document.getElementById('kpi-tab-monthly'), moOn);
    _kpiDecorateEditBtn(wkOn);
}

// ============================================================================
// KPI DUE REMINDERS — data-aware action-feed nags (Weekly + Monthly)
//   Supersedes the old time-only breadcrumb (_kpiReminderActive/_kpiReminderOn,
//   left defined above but no longer consulted). A store is nagged ONLY while
//   its current period has zero saved entries, and the nag clears the instant
//   any entry is saved — the kpi-manage POST broadcasts "kpi", the realtime
//   registry re-runs checkKpiDueReminders(), the bubble hides, the feed repaints.
//   • Weekly : due once the active Sunday period is editable; flips to "Overdue"
//              after that Sunday passes; persists until filled or the week rolls.
//   • Monthly: due from the FIRST SUNDAY of the month AFTER the reporting month
//              (so a month that ends mid-week is reported the first Sunday — e.g.
//              the 4th); "Overdue" after that Sunday; persists until filled.
//   Roles: manager / owner-manager / MSM. (MSM is scoped to their HOME store —
//   the Store KPIs pane's store picker is DM/CEO-only, so an MSM can only enter
//   their home store here today.)
// ============================================================================
const _KPI_DUE_ROLES = new Set(['manager', 'owner (manager)', 'owner manager']);
// NOTE: Assistant Managers are intentionally excluded. ASM KPI entry is disabled
// for the stores right now; the day it's re-enabled, add 'assistant manager'
// here and ASMs start getting these reminders automatically.

let _kpiDueState = { weekly: { due: false, overdue: false, stores: [] }, monthly: { due: false, overdue: false, stores: [] } };
let _kpiDueStarted = false;

function _kpiDueEligible() {
    return _KPI_DUE_ROLES.has((sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim());
}
// The store(s) whose KPIs THIS user is responsible for. A Multi-Store Manager
// covers BOTH managed stores (they fill each by switching the active store, or
// by clicking the store-specific feed card which routes the pane to that store —
// see _kpiResolveStore); everyone else is their one home store.
function _kpiMyStores() {
    if (typeof isMultiStoreManager === 'function' && isMultiStoreManager()) {
        return [...MULTISTORE_MANAGER_STORES];
    }
    const s = (sessionStorage.getItem('speeksUserStore') || '').toUpperCase();
    return (s && s !== 'ALL' && s !== 'CORP') ? [s] : [];
}

// Which store the Store KPIs pane is currently showing/saving. Preserves the
// existing behaviour for everyone (DM/CEO picker wins; managers = their store),
// and adds one thing: an MSM who arrived via a store-specific KPI feed card is
// routed to THAT store (set on pane-open in switchWorkspaceTab), without
// switching their whole dashboard — mirrors the aging pane's _agViewStore.
let _kpiViewStore = null;
function _kpiResolveStore() {
    const sel = document.getElementById('kpiModalStoreSelect');
    if (sel && sel.offsetParent !== null && sel.value) return sel.value;   // DM / CEO / MOCD picker
    if (_kpiViewStore) return _kpiViewStore;                               // MSM routed store
    return sessionStorage.getItem('speeksUserStore') || '';               // manager default
}
// Today's date in Central time as YYYY-MM-DD — string-comparable with the
// period dates the edge fn returns (both are plain calendar dates).
function _kpiCentralToday() {
    return new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Chicago' }).format(new Date());
}
// Current Central date + wall clock, so we can test the real deadline.
function _kpiCentralParts() {
    const p = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Chicago', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
    const g = t => (p.find(x => x.type === t) || {}).value;
    let hr = parseInt(g('hour'), 10); if (hr === 24) hr = 0;   // some engines emit 24 at midnight
    return { date: g('year') + '-' + g('month') + '-' + g('day'), hour: hr, minute: parseInt(g('minute'), 10) };
}
function _kpiAddDays(dateStr, n) {
    const d = new Date(dateStr + 'T00:00:00Z');
    d.setUTCDate(d.getUTCDate() + n);
    return d.toISOString().slice(0, 10);
}
// Is "now" past the deadline for work done on `sunday`? KPIs are entered Sunday
// and due the FOLLOWING MONDAY at 08:30 Central — so it's only "overdue" once
// that Monday-morning cutoff passes, not at Sunday midnight.
function _kpiPastDeadline(sunday, parts) {
    const mon = _kpiAddDays(sunday, 1);           // the Monday after
    if (parts.date > mon) return true;
    if (parts.date < mon) return false;
    return parts.hour > 8 || (parts.hour === 8 && parts.minute >= 30);
}
// First Sunday (YYYY-MM-DD) of the month FOLLOWING the given period-end date.
// A monthly period ending e.g. 2026-06-30 is reported the first Sunday of July,
// which may be as late as the 7th (your "month ended mid-week → fill it the
// first Sunday, maybe the 4th" case).
function _kpiFirstSundayAfter(periodEndStr) {
    const parts = String(periodEndStr).split('-').map(Number);
    let ny = parts[0], nm = parts[1] + 1;                  // the month it's reported IN
    if (nm > 12) { nm = 1; ny += 1; }
    const dow = new Date(Date.UTC(ny, nm - 1, 1)).getUTCDay();  // 0 = Sunday
    const day = dow === 0 ? 1 : 1 + (7 - dow);
    return ny + '-' + String(nm).padStart(2, '0') + '-' + String(day).padStart(2, '0');
}

// Lazily-created hidden alert bubble for a KPI reminder (weekly|monthly). Like
// the variance/aging bubbles it's a state-carrier only — CSS keeps it
// visibility:hidden; _samGatherReminders reads its display to surface the feed
// card (see the RETIRED FLOATING ALERT TOASTS block in styles.css).
function _kpiDueBubbleEl(which) {
    const id = which === 'monthly' ? 'kpiMonthlyAlertBubble' : 'kpiWeeklyAlertBubble';
    let b = document.getElementById(id);
    if (b) return b;
    const anchor = document.getElementById('claimAlertBubble');
    if (!anchor || !anchor.parentElement) return null;
    b = document.createElement('div');
    b.id = id;
    b.style.cssText = 'display:none; position:fixed; top:116px; right:24px; background:linear-gradient(135deg, #dc2626, #7f1d1d); color:white; padding:11px 14px 11px 16px; border-radius:14px; align-items:flex-start; gap:8px; font-size:13px; box-shadow:0 10px 28px rgba(127, 29, 29, 0.38); max-width:min(380px, calc(100vw - 48px)); z-index:998;';
    b.innerHTML = '<span id="' + id + 'Icon" style="font-size:16px; flex-shrink:0; margin-top:2px;">📈</span>' +
        '<span id="' + id + 'Text" style="white-space:normal; overflow-y:auto; max-height:220px;"></span>' +
        '<button onclick="document.getElementById(\'' + id + '\').style.display=\'none\'" class="daily-bubble-close" title="Dismiss">' +
        '<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>' +
        '</button>';
    anchor.parentElement.appendChild(b);
    return b;
}
function _kpiHideDueBubble(which) {
    const b = document.getElementById(which === 'monthly' ? 'kpiMonthlyAlertBubble' : 'kpiWeeklyAlertBubble');
    if (b) b.style.display = 'none';
}
function _kpiHideDueBubbles() { _kpiHideDueBubble('weekly'); _kpiHideDueBubble('monthly'); }

// Populate + show one KPI due bubble (state-carrier for the feed card).
function _kpiRenderDueBubble(which, show, opts) {
    if (!show) { _kpiHideDueBubble(which); return; }
    const b = _kpiDueBubbleEl(which);
    if (!b) return;
    const id = b.id;
    const textEl = document.getElementById(id + 'Text');
    const overdue = !!(opts && opts.overdue);
    const stores = (opts && opts.stores) || [];
    const monthly = which === 'monthly';
    // You report the month/week that just ended, so an overdue weekly reads
    // "Last week's"; monthly is always the just-ended month ("Last month's").
    const when = monthly ? "Last month's" : (overdue ? "Last week's" : "This week's");
    const tab = monthly ? 'monthly' : 'weekly';
    const title = (monthly ? 'Monthly KPIs' : 'Weekly KPIs') + (overdue ? ' Overdue' : ' Due');
    // Name the outstanding store(s) when the card can cover more than one — an MSM
    // (either store, even when only one is left) or any multi-store list. A plain
    // manager has one store, so naming it is just noise.
    const isMSM = typeof isMultiStoreManager === 'function' && isMultiStoreManager();
    const storeP = ((isMSM || stores.length > 1) && stores.length) ? (' (' + stores.join(' & ') + ')') : '';
    const tail = overdue ? ' are overdue' : ' are due Monday by 8:30am';
    const summary = overdue
        ? (when + ' KPIs' + storeP + ' are overdue — enter them now.')
        : (when + ' KPIs' + storeP + ' are due Monday by 8:30am.');
    const body = when + ' KPIs' + storeP + tail +
        '. Open Workspace → Store KPIs and fill in the ' + tab + ' numbers.';
    if (textEl) {
        textEl.dataset.summary = summary;
        // The feed card's title + badge (Due vs Overdue) read this off the bubble,
        // so the whole card always agrees with the bubble — no split-source drift.
        textEl.dataset.overdue = overdue ? '1' : '';
        // Snooze identity: re-nags if the store list or overdue state changes.
        textEl.dataset.sig = (monthly ? 'm' : 'w') + '|' + [...stores].sort().join(',') + '|' + (overdue ? 'od' : 'due');
        if (stores.length) textEl.dataset.stores = [...new Set(stores)].join(',');
        else delete textEl.dataset.stores;
        textEl.style.display = 'flex';
        textEl.style.flexDirection = 'column';
        textEl.style.gap = '7px';
        textEl.innerHTML =
            '<div style="line-height:1.4;"><strong>' + escapeHtml(title) + '</strong></div>' +
            '<div style="line-height:1.4; opacity:0.96;">' + escapeHtml(body) + '</div>' +
            '<button onclick="document.getElementById(\'' + id + '\').style.display=\'none\'; sessionStorage.setItem(\'speeksKpiTab\',\'' + tab + '\'); window.location.href=\'workspace.html#kpis\';" ' +
            'style="align-self:flex-start; background:rgba(255,255,255,0.18); border:1px solid rgba(255,255,255,0.5); color:#fff; font-weight:800; font-size:12px; border-radius:8px; padding:6px 12px; cursor:pointer;" ' +
            'onmouseover="this.style.background=\'rgba(255,255,255,0.3)\';" onmouseout="this.style.background=\'rgba(255,255,255,0.18)\';">Open Store KPIs</button>';
    }
    b.style.display = 'flex';
}

// The check: fetches the editable weekly + monthly period for the user's store,
// and shows/hides each bubble based on whether it has saved entries. Self-
// installs a 10-min safety poll; realtime pings re-run it instantly on any save.
async function checkKpiDueReminders() {
    if (!_kpiDueEligible()) { _kpiHideDueBubbles(); _kpiDueState = { weekly: { due: false, overdue: false, stores: [] }, monthly: { due: false, overdue: false, stores: [] } }; return; }
    const stores = _kpiMyStores();
    if (!stores.length) { _kpiHideDueBubbles(); return; }
    if (!_kpiDueStarted) { _kpiDueStarted = true; setInterval(checkKpiDueReminders, 10 * 60 * 1000); }
    try {
        const parts = _kpiCentralParts();
        const today = parts.date;
        const wkPending = [], moPending = [];
        let wkEnd = null, moFirstSun = null;
        for (const store of stores) {
            const wUrl = KPI_MANAGE_URL + '?store=' + store + '&period_type=weekly&v=' + Date.now();
            const mUrl = KPI_MANAGE_URL + '?store=' + store + '&period_type=monthly&v=' + Date.now();
            const [wRes, mRes] = await Promise.all([
                fetch(wUrl).then(r => r.json()).catch(() => null),
                fetch(mUrl).then(r => r.json()).catch(() => null),
            ]);
            const wp = wRes && (wRes.periods || []).find(p => p.is_editable);
            if (wp) { wkEnd = wp.period_end_date; if ((wp.saved_count || 0) === 0) wkPending.push(store); }
            const mp = mRes && (mRes.periods || []).find(p => p.is_editable);
            if (mp) {
                const firstSun = _kpiFirstSundayAfter(mp.period_end_date);
                moFirstSun = firstSun;
                if ((mp.saved_count || 0) === 0 && today >= firstSun) moPending.push(store);
            }
        }
        // Overdue once the Monday-08:30-CT deadline after the reporting Sunday passes.
        const wkOverdue = !!(wkEnd && _kpiPastDeadline(wkEnd, parts));
        const moOverdue = !!(moFirstSun && _kpiPastDeadline(moFirstSun, parts));
        _kpiDueState = {
            weekly:  { due: wkPending.length > 0, overdue: wkOverdue, stores: wkPending },
            monthly: { due: moPending.length > 0, overdue: moOverdue, stores: moPending },
        };
        _kpiRenderDueBubble('weekly',  _kpiDueState.weekly.due,  { overdue: wkOverdue, stores: wkPending });
        _kpiRenderDueBubble('monthly', _kpiDueState.monthly.due, { overdue: moOverdue, stores: moPending });
        if (typeof applyKpiReminder === 'function') applyKpiReminder();
        if (typeof renderActionFeed === 'function') renderActionFeed();
    } catch (e) { /* next poll / ping retries */ }
}

function kpiHeaderStartEdit() {
    const ep = (_kpiPeriodsData || []).find(function(p) { return p.is_editable; }) || (_kpiPeriodsData || [])[0];
    if (!ep) return;
    _kpiEditingPeriod = ep.period_end_date;
    if (_kpiCurrentTab === 'weekly') _kpiRenderWeekly(_kpiPeriodsData);
    else _kpiRenderMonthly(_kpiPeriodsData);
}

function kpiHeaderSave() {
    if (_kpiEditingPeriod) _kpiSavePeriod(_kpiEditingPeriod);
}

function kpiHeaderCancel() {
    _kpiEditingPeriod = null;
    _kpiStripUnsavedSelfRows();
    if (_kpiCurrentTab === 'weekly') _kpiRenderWeekly(_kpiPeriodsData);
    else _kpiRenderMonthly(_kpiPeriodsData);
}

async function _kpiLoadAll(tab) {
    const store = _kpiResolveStore();
    if (!store) return;
    const body = document.getElementById('kpiModalBody');
    // Never blank the grid out from under someone who is mid-entry. This used to
    // paint "Loading…" over a half-filled form and then, if the fetch failed,
    // replace it with an error — taking every typed number with it.
    const editing = !!_kpiEditingPeriod;
    if (body && !editing) body.innerHTML = '<div class="kpi-empty-state">Loading…</div>';
    try {
        const resp = await fetch(KPI_MANAGE_URL + '?store=' + store + '&period_type=' + tab + '&v=' + Date.now());
        const data = await resp.json();
        _kpiPeriodsData = data.periods || [];
        if (tab === 'weekly') _kpiRenderWeekly(_kpiPeriodsData);
        else                  _kpiRenderMonthly(_kpiPeriodsData);
    } catch(e) {
        if (body && !editing) {
            body.innerHTML = '<div class="kpi-empty-state" style="color:var(--red-alert)">Failed to load KPI data.</div>';
        }
    }
}

function toggleDmKpiPicker(e) {
    e.stopPropagation();
    const dd = document.getElementById('dmKpiDropdown');
    if (!dd) return;
    const open = dd.classList.toggle('open');
    if (open) {
        const close = () => { dd.classList.remove('open'); document.removeEventListener('click', close); };
        setTimeout(() => document.addEventListener('click', close), 0);
    }
}

async function openKpiEntryPanelForStore(store, tab) {
    const sel = document.getElementById('kpiModalStoreSelect');
    if (sel) sel.value = store;
    await openKpiEntryPanel(tab);
}

async function openKpiEntryPanel(tab) {
    _kpiCurrentTab = tab || 'weekly';
    _kpiEditingPeriod = null;
    // Seed the modal store selector with the user's own store (managers); DMs keep whatever is selected
    const sel = document.getElementById('kpiModalStoreSelect');
    const userStore = sessionStorage.getItem('speeksUserStore');
    if (sel && userStore && sel.offsetParent === null) sel.value = userStore;
    document.getElementById('kpi-tab-weekly') && document.getElementById('kpi-tab-weekly').classList.toggle('active', _kpiCurrentTab === 'weekly');
    document.getElementById('kpi-tab-monthly') && document.getElementById('kpi-tab-monthly').classList.toggle('active', _kpiCurrentTab === 'monthly');
    toggleModal('kpiEntryModal');
    await _kpiLoadAll(_kpiCurrentTab);
}

async function switchKpiTab(tab) {
    _kpiCurrentTab = tab;
    _kpiEditingPeriod = null;
    document.getElementById('kpi-tab-weekly') && document.getElementById('kpi-tab-weekly').classList.toggle('active', tab === 'weekly');
    document.getElementById('kpi-tab-monthly') && document.getElementById('kpi-tab-monthly').classList.toggle('active', tab === 'monthly');
    await _kpiLoadAll(tab);
}

// ============================================================================
// ANALYTICS WORKSPACE (workspace.html) — Monthly Brief / Store KPIs / Variance
// ============================================================================
let _wsBriefLoaded = false;
let _wsKpiLoaded   = false;

// Loads the inline KPI grid (same markup/IDs as the old fullscreen modal, but
// rendered in-page rather than via toggleModal). Loads once per page-init.
async function loadWorkspaceKpis() {
    // A KPI-due feed card can request a specific sub-tab (weekly|monthly) via
    // sessionStorage before deep-linking here. Consume it once.
    let wantTab = 'weekly';
    try {
        const t = sessionStorage.getItem('speeksKpiTab');
        if (t === 'weekly' || t === 'monthly') { wantTab = t; sessionStorage.removeItem('speeksKpiTab'); }
    } catch (e) {}
    if (_wsKpiLoaded) {
        // Already loaded — still honor an explicit tab request from a card.
        if (wantTab !== _kpiCurrentTab && typeof switchKpiTab === 'function') switchKpiTab(wantTab);
        return;
    }
    _wsKpiLoaded = true;
    _kpiCurrentTab = wantTab;
    _kpiEditingPeriod = null;
    // Managers (picker hidden) default to their own store; DMs keep selection
    const sel = document.getElementById('kpiModalStoreSelect');
    const userStore = sessionStorage.getItem('speeksUserStore');
    if (sel && userStore && sel.offsetParent === null) sel.value = userStore;
    document.getElementById('kpi-tab-weekly')?.classList.toggle('active', wantTab === 'weekly');
    document.getElementById('kpi-tab-monthly')?.classList.toggle('active', wantTab === 'monthly');
    await _kpiLoadAll(wantTab);
}

function switchWorkspaceTab(name) {
    document.querySelectorAll('.ws-tab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.ws-pane').forEach(p => p.classList.remove('active'));
    document.getElementById('ws-tab-' + name)?.classList.add('active');
    document.getElementById('ws-pane-' + name)?.classList.add('active');
    try { history.replaceState(null, '', 'workspace.html#' + name); } catch (e) {}

    if (name === 'brief') {
        if (!_wsBriefLoaded) { _wsBriefLoaded = true; if (typeof fetchMonthlyBrief === 'function') fetchMonthlyBrief(); }
    } else if (name === 'kpis') {
        // MSM only: a store-specific KPI feed card routes the pane to that store
        // (consumed once, cleared after), without switching the whole dashboard.
        // No override → their active store. Non-MSM → null (falls back normally).
        _kpiViewStore = (typeof isMultiStoreManager === 'function' && isMultiStoreManager())
            ? (_consumeMsmAlertStore() || null) : null;
        loadWorkspaceKpis();
    } else if (name === 'vreplies') {
        loadVarianceReplies();
    } else if (name === 'mreplies') {
        // Same single-store-alert routing as the other workspace tools: a feed
        // card for one store lands on that store without switching dashboards.
        const bmOverride = _consumeMsmAlertStore();
        if (_bmIsDM()) {
            _bmViewStore = null;
            const sel = document.getElementById('bm-store-select');
            if (bmOverride && sel && [...sel.options].some(o => o.value.toUpperCase() === bmOverride)) {
                sel.value = bmOverride;
            }
        } else {
            _bmViewStore = bmOverride || _msmDefaultStore();
        }
        loadMarginReplies();
    } else if (name === 'aging') {
        // Resolve which store the aging view shows ONCE per open (a single-store /
        // DM-routed alert override wins, else the active dashboard store), so the
        // repeated re-renders after adding items/notes don't re-consume it.
        const agOverride = _consumeMsmAlertStore();
        if (_agIsDM()) {
            // The DM's aging view is driven by the store dropdown, not _agViewStore.
            // Point the dropdown at the routed store so clicking the "replies to
            // review" alert lands on a store that actually replied.
            _agViewStore = null;
            const sel = document.getElementById('ag-store-select');
            if (agOverride && sel && [...sel.options].some(o => o.value.toUpperCase() === agOverride)) {
                sel.value = agOverride;
            }
        } else {
            _agViewStore = agOverride || _msmDefaultStore();
        }
        loadAgingInventory();
    }
    applyKpiReminder();
}

// Detects the workspace page and opens the requested sub-tab (defaults to the
// brief, or honors a #brief / #kpis / #vreplies / #aging deep-link). Safe no-op
// elsewhere. B2B is an Operations tab now, not a workspace one.
function initWorkspace() {
    if (!document.querySelector('.ws-wrap')) return;
    _wsBriefLoaded = false;
    _wsKpiLoaded   = false;
    const hash = (window.location.hash || '').replace('#', '');
    // 'mreplies' is deliberately NOT accepted — Margin Replies is parked, so a
    // #mreplies deep link falls through to the brief. Add it back with the tab.
    let initial = ['brief', 'kpis', 'vreplies', 'aging'].includes(hash) ? hash : 'brief';
    // A tab can be hidden by its role gate or a Feature Access override
    // (applyRoleBasedUI already ran), so never land on one the user can't see —
    // fall back to the first visible tab.
    const tabVisible = id => { const b = document.getElementById(id); return !!b && b.style.display !== 'none' && !b.hidden; };
    if (!tabVisible('ws-tab-' + initial)) {
        const firstVisible = Array.from(document.querySelectorAll('[id^="ws-tab-"]'))
            .find(b => b.style.display !== 'none' && !b.hidden);
        if (firstVisible) initial = firstVisible.id.replace('ws-tab-', '');
    }
    switchWorkspaceTab(initial);
    applyKpiReminder();
}

// ============================================================================
// OPERATIONS PAGE (operations.html) — sub-tab shell for operational tools.
// Mirrors the workspace tab system but keys off .ops-wrap / ops-tab-* / ops-pane-*
// so initWorkspace() never misfires on this page (and vice versa).
// ============================================================================
function switchOperationsTab(name) {
    document.querySelectorAll('.ws-tab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.ws-pane').forEach(p => p.classList.remove('active'));
    document.getElementById('ops-tab-' + name)?.classList.add('active');
    document.getElementById('ops-pane-' + name)?.classList.add('active');
    try { history.replaceState(null, '', 'operations.html#' + name); } catch (e) {}
    // Margin Guide and Customer Call Backs are read-only tools — this tab hook
    // is the ONLY record that anyone ever used them.
    trackUsage('open', 'ops:' + name, _usageLabel('ops:' + name));

    if (name === 'callbacks') {
        cbLoad();
        _startCbSync();
    } else if (name === 'b2b') {
        b2bLoad();
        _startB2bSync();
    } else if (name === 'marginguide') {
        mgLoad();
    } else if (name === 'ebay') {
        ecLoad();
    }
}

/* ========================================================================== *
 * MARGIN GUIDE — the buy ladder, replacing the VBA workbook.
 * --------------------------------------------------------------------------
 * The three percentages are the SHARE OF THE PROJECTION WE PAY, ascending:
 * start is the opening offer, team is as high as a team member goes alone,
 * manager is the ceiling before the DM. The old spreadsheet headers ("Lowest
 * Margin / Highest Margin") read backwards to a new buyer, so the labels here
 * say what the numbers do.
 *
 * The catalog is store-agnostic reference data, so it is fetched once per
 * session and everything after that is local — a buyer changing condition
 * mid-negotiation gets an instant redraw, never a spinner.
 * ========================================================================== */

let _mgCatalog = null;          // { tiers, conditions, devices, help, adjustments }
// `proj` is the typed projection as a raw string and the single source of truth
// for it — the input is re-created on every render, so the value cannot live in
// the DOM. It starts empty and is wiped on sign-out and on every entry to the tab
// (see mgLoad): one buyer's projection must never greet the next one, and a stale
// number that looks like an answer is worse than no number at all. `bandId` is
// derived from it rather than chosen, so no projection means no band and no ladder.
let _mgState = { cat: null, deviceId: null, bandId: null, cond: null, proj: '' };

const _mgEsc = s => String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// opts.keep is for the DM editor's own refetch after a save: it needs the fresh
// catalog without being thrown back to a blank buying screen.
async function mgLoad(opts) {
    const body = document.getElementById('mg-body');
    if (!body) return;
    if (!opts || !opts.keep) {
        // Every entry to the tab is a fresh buy. Leaving and coming back must not
        // carry the last customer's item or projection — or worse, show a ladder
        // built from them to the next one — so the selection is blank each time.
        _mgResetSelection();
        _mgAdmin.open = false;   // and never straight back into the DM editor
        // Unsaved wording from the last visit is not a draft worth keeping: it
        // would reappear over whatever the text says now, which may have moved on.
        _mgTextDrafts = {};
        _mgAdmin.deviceId = '';
        _mgAdmin.cell = null;
        _mgAdmin.pending.clear();
    }
    if (_mgCatalog) { mgRender(); return; }        // already have it — don't refetch
    try {
        const res = await fetch(`${MARGIN_GUIDE_URL}?v=${Date.now()}`);
        const json = await res.json();
        if (!json.success) throw new Error(json.error || 'Could not load the guide');
        _mgCatalog = json;
        if (!(json.devices || []).length) throw new Error('The guide has no devices yet');
        mgRender();
    } catch (e) {
        body.innerHTML = `<div class="mg-error">Couldn't load the margin guide. ${_mgEsc(e.message)}
            <button type="button" class="mg-retry" onclick="_mgCatalog=null;mgLoad()">Try again</button></div>`;
    }
}

const _mgDevices    = () => (_mgCatalog && _mgCatalog.devices) || [];
const _mgDevice     = () => _mgDevices().find(d => d.id === _mgState.deviceId) || null;
const _mgBand       = () => { const d = _mgDevice(); return d ? d.bands.find(b => b.id === _mgState.bandId) || null : null; };
const _mgHelp       = () => { const d = _mgDevice(); return (d && _mgCatalog.help[d.helpKey]) || null; };
const _mgCondOrder  = () => ((_mgCatalog && _mgCatalog.conditions) || []).map(c => c.name);

// Which band a projection falls in. Lower bound inclusive, upper exclusive, so
// $350 on an iPhone is the $350+ band rather than $150-$350. Mirrors the
// mg_resolve_band() SQL function exactly.
function _mgBandForPrice(device, price) {
    const hit = (device.bands || []).find(b => price >= b.min && (b.max === null || price < b.max));
    return hit || device.bands[0] || null;
}

function _mgProjection() {
    const v = parseFloat(String(_mgState.proj).replace(/[^0-9.]/g, ''));
    return isNaN(v) ? 0 : v;
}

const _mgHasProjection = () => _mgProjection() > 0;

// The band is derived, never chosen: it is whichever band the typed projection
// falls in, and nothing while the box is empty.
function _mgSyncBand() {
    const d = _mgDevice();
    _mgState.bandId = (d && _mgHasProjection())
        ? ((_mgBandForPrice(d, _mgProjection()) || {}).id || null)
        : null;
}

// Nothing is chosen for the buyer. The guide opens blank — no category, no device,
// no projection — so it can never show a ladder for whichever item happens to sort
// first, which a buyer mid-conversation could easily read as an answer for the item
// actually in front of them. Everything downstream stays in its waiting state until
// the buyer says what they're looking at.
function _mgResetSelection() {
    _mgState.cat = '';
    _mgState.deviceId = null;
    _mgState.bandId = null;
    _mgState.cond = null;
    _mgState.proj = '';
}

function _mgEnsureSelection() {
    // Only drop a selection that has gone stale (the catalog changed under it) —
    // never fill one in.
    if (_mgState.deviceId && !_mgDevice()) { _mgState.deviceId = null; _mgState.cond = null; }
    _mgSyncBand();
    const band = _mgBand();
    if (band) {
        const avail = _mgCondOrder().filter(c => band.conds[c] !== undefined);
        if (!avail.includes(_mgState.cond)) _mgState.cond = avail[Math.min(1, avail.length - 1)] || null;
    } else {
        _mgState.cond = null;
    }
}

/* The editor is a different place, not a mode of the guide, so the panel header
 * says so: eyebrow, title and instruction line all swap, and the Manage button
 * hands its slot to the way back. */
const _MG_HEAD = {
    guide: {
        eyebrow: 'Buying Reference',
        title: 'Margin Guide',
        sub: 'Pick the item and its condition, enter your resale projection, and work the ladder from the top down.',
    },
    admin: {
        eyebrow: 'Margin Guide',
        title: 'Edit the guide',
        sub: 'Pick an item to set what each condition pays and rewrite what the guide tells your buyers.',
    },
};
function _mgSyncHead(admin) {
    const copy = _MG_HEAD[admin ? 'admin' : 'guide'];
    const set = (id, text) => { const el = document.getElementById(id); if (el) el.textContent = text; };
    set('mg-eyebrow', copy.eyebrow);
    set('mg-title', copy.title);
    set('mg-sub', copy.sub);
    // Class, not an inline style — Feature Access strips inline display from every
    // non-overridden [data-feature] element, which would show this to everyone.
    const manage = document.getElementById('mg-manage-btn');
    if (manage) manage.classList.toggle('mg-can', mgCanEditLadder() && !admin);
    const back = document.getElementById('mg-back-btn');
    if (back) back.classList.toggle('mg-can', admin);

    // Save rides in the header next to Back rather than in a bar at the bottom.
    // The header pins itself while editing so scrolling down to the wording can
    // never put queued cell changes out of reach.
    const host = document.getElementById('mg-head-save');
    if (host) host.innerHTML = admin ? _mgAdminBar() : '';
    const head = document.querySelector('.mg-panel .mg-head');
    if (head) head.classList.toggle('mg-head-stuck', admin);
}

function mgRender() {
    const body = document.getElementById('mg-body');
    if (!body || !_mgCatalog) return;
    const admin = _mgAdmin.open && mgCanEditLadder();
    _mgSyncHead(admin);
    if (admin) { _mgRenderAdmin(body); return; }
    _mgEnsureSelection();

    const device = _mgDevice();
    const band   = _mgBand();
    const cats   = [...new Set(_mgDevices().map(d => d.category))];
    const devsInCat = _mgDevices().filter(d => d.category === _mgState.cat);

    body.innerHTML = `
      <div class="mg-grid">
        <div class="mg-rail">
          <div class="mg-field">
            <label class="mg-lab" for="mg-cat">Category</label>
            <select id="mg-cat" class="mg-select${_mgState.cat ? '' : ' mg-unset'}">
              <option value=""${_mgState.cat ? '' : ' selected'}>Choose a category…</option>
              ${cats.map(c => `<option${c === _mgState.cat ? ' selected' : ''}>${_mgEsc(c)}</option>`).join('')}
            </select>
          </div>
          <div class="mg-field">
            <label class="mg-lab" for="mg-dev">Device</label>
            <select id="mg-dev" class="mg-select${_mgState.deviceId ? '' : ' mg-unset'}" ${_mgState.cat ? '' : 'disabled'}>
              <option value=""${_mgState.deviceId ? '' : ' selected'}>${_mgState.cat ? 'Choose an item…' : 'Pick a category first'}</option>
              ${devsInCat.map(d => `<option value="${d.id}"${d.id === _mgState.deviceId ? ' selected' : ''}>${_mgEsc(d.device)}</option>`).join('')}
            </select>
          </div>
          <!-- The prompt only lights up once it is actually this step's turn: with
               no item chosen the buyer's next move is the category, not the price. -->
          <div class="mg-field mg-field-proj${(!_mgState.proj && device) ? ' mg-needs' : ''}">
            <label class="mg-lab mg-lab-row" for="mg-projection">Projection<span class="mg-cue">Enter yours</span></label>
            <div class="mg-money"><input id="mg-projection" class="mg-input" type="text"
                 inputmode="decimal" autocomplete="off" maxlength="9" spellcheck="false"
                 value="${_mgEsc(_mgState.proj)}"></div>
          </div>
          <!-- No "Price band" readout. It was a locked chip the buyer couldn't touch,
               and the band is already named in the breadcrumb above the ladder — so it
               was a second, non-interactive copy of something already on screen,
               taking a slot in the one column that is meant to be all controls. -->
          <div class="mg-field">
            <span class="mg-lab">Condition</span>
            ${band
                ? `<div class="mg-conds" id="mg-conds">${_mgCondButtons(band)}</div>${_mgNoBuyNote(device, band)}`
                : `<div class="mg-wait">Set by the price band</div>`}
          </div>
          <!-- Sits at the foot of the picker rail because that is the moment the gap
               is discovered — someone scrolling the Device list for something that
               isn't there. Wired to the existing hotbar idea modal rather than a new
               form, so requests land where every other suggestion already goes. -->
          <p class="mg-missing">Item or category missing? Send it over with the
            <button type="button" class="mg-inline-link" onclick="toggleIdeaModal()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18h6"/><path d="M10 22h4"/><path d="M12 2a7 7 0 0 0-4 12.7c.6.5 1 1.3 1 2.1V17h6v-.2c0-.8.4-1.6 1-2.1A7 7 0 0 0 12 2z"/></svg>Have an Idea</button>
            button and we'll add it.</p>
        </div>

        <div class="mg-mid">
          ${device ? `<div class="mg-crumb">
            <b>${_mgEsc(device.device)}</b>
            ${band ? `<i></i><span>${_mgEsc(band.label)}</span>` : ''}
            ${_mgState.cond ? `<i></i><span>${_mgEsc(_mgState.cond)}</span>` : ''}
          </div>` : ''}
          ${_mgGates()}
          ${_mgLadder(band)}
          ${_mgRebuttals()}
        </div>

        <div class="mg-side">
          ${_mgPanel('Reminders', 'reminder', 'rules')}
          ${_mgPanel('Testing Tips', 'testing', 'checks')}
          ${_mgPanel('Condition Help', 'condition', 'grades')}
        </div>
      </div>`;

    _mgBind();
}

function _mgCondButtons(band) {
    if (!band) return '';
    const device = _mgDevice();
    const order = _mgCondOrder();
    const avail = order.filter(c => band.conds[c] !== undefined);
    // A condition this band does not carry but the device does elsewhere is a
    // policy statement ("we don't buy broken accessories"), so show it struck
    // through rather than letting it vanish and look like a missing option.
    const gone = order.filter(c => band.conds[c] === undefined &&
        device.bands.some(b => b.conds[c] !== undefined));
    return avail.map(c =>
        `<button type="button" class="mg-cond" data-cond="${_mgEsc(c)}" aria-pressed="${c === _mgState.cond}">${_mgEsc(c)}</button>`
    ).join('') + gone.map(c =>
        `<button type="button" class="mg-cond" disabled title="We don't buy this condition in this band">${_mgEsc(c)}</button>`
    ).join('');
}

function _mgNoBuyNote(device, band) {
    if (!band) return '';
    const gone = _mgCondOrder().filter(c => band.conds[c] === undefined &&
        device.bands.some(b => b.conds[c] !== undefined));
    if (!gone.length) return '';
    return `<div class="mg-nobuy">We don't buy <strong>${gone.map(_mgEsc).join(', ')}</strong> in this band.</div>`;
}

// Gates are hard preconditions on the purchase, not advice — "no MDM on the
// device", "motherboards must be tested", "have the customer fly the drone".
// They sit above the ladder because getting one wrong voids the deal, and they
// are deliberately absent from the lists below so each rule appears once.
function _mgGates() {
    const help = _mgHelp();
    if (!help || !help.gates.length) return '';
    return `<div class="mg-gates">
        <div class="mg-gates-h">
          <svg viewBox="0 0 24 24"><path d="M12 9v4"/><path d="M12 17h.01"/><path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/></svg>
          Before you buy
        </div>
        <ul>${help.gates.map(g => `<li>${_mgEsc(g.body)}</li>`).join('')}</ul>
      </div>`;
}

function _mgLadder(band) {
    // No projection, no ladder. Defaulting to the lowest band would put three
    // confident percentages on screen for a number the buyer never gave us, which
    // is the one failure mode worse than making them type it.
    if (!band) {
        const step = _mgDevice()
            ? '<b>Enter your resale projection</b> to see the offer ladder.'
            : '<b>Pick the category and item</b> you\'re looking at to get started.';
        return `<div class="mg-wait mg-wait-lad">
            <svg viewBox="0 0 24 24"><path d="M3 3v18h18"/><path d="M7 15l4-5 3 3 5-7"/></svg>
            <span>${step}</span>
          </div>`;
    }
    // Video Games under $20 is flat cash per game, not a percentage of the
    // projection — the workbook carried that rule in its reminders.
    if (band.payMode === 'flat') {
        // Cents matter here and nowhere else in the tool: the under-$10 band pays
        // 50c-$1, and a bare Number renders that as "$0.5", which reads as a typo
        // on a screen that is quoting cash to a customer.
        const cash = v => Number(v) % 1 === 0 ? `$${Number(v)}` : `$${Number(v).toFixed(2)}`;
        return `<div class="mg-flat">
            <span class="mg-flat-lab">Flat pay &mdash; not a percentage</span>
            <span class="mg-flat-val">${cash(band.flatLow)} &ndash; ${cash(band.flatHigh)}</span>
            <span class="mg-flat-note">per item in this band. We don't test these and they don't move fast.</span>
          </div>`;
    }
    // Percentages come from band.pct, not from the tier directly: the function
    // resolves the shared tier plus any scoped adjustment into one finished number
    // per cell. A buyer should never have to know an adjustment exists.
    const pct = (band.pct || {})[_mgState.cond];
    if (!pct) return `<div class="mg-nobuy">Pick a condition to see the ladder.</div>`;
    const rungs = [
        ['start', 'Start here', 'A fair offer, and the store wins', pct.s],
        ['team',  'Your ceiling', 'As high as you can go on your own', pct.t],
        ['mgr',   'Manager ceiling', 'Needs a manager &mdash; above this, get the DM', pct.m],
    ];
    // The PERCENTAGE stays the headline — it's the number the ladder is built on and
    // the one buyers have learned. The dollar figure sits underneath as the saved
    // arithmetic, so nobody has to multiply in front of a customer.
    //
    // data-pct lets _mgSyncMoney() recompute the dollars on every keystroke without
    // a re-render. That matters: mgRender() only runs when the BAND changes, so
    // typing "350" renders once (at "3") and never again — the percentages didn't
    // care, but the dollars very much do. See the input handler in _mgBind.
    const proj = _mgProjection();
    return `<div class="mg-ladder">${rungs.map(([cls, name, sub, val]) => `
        <div class="mg-rung mg-rung-${cls}">
          <div class="mg-rung-stripe"></div>
          <div class="mg-rung-body">
            <span class="mg-rung-name">${name}</span>
            <span class="mg-rung-sub">${sub}</span>
          </div>
          <div class="mg-rung-val" data-pct="${val}">
            <b>${val}%</b>
            <em${proj > 0 ? '' : ' hidden'}>${proj > 0 ? _mgOffer(proj, val) : ''}</em>
          </div>
        </div>`).join('')}
      </div>`;
}

const _mgMoney = (proj, pct) => '$' + Math.round(proj * pct / 100).toLocaleString();
// Labelled, because a bare "$123" under a "35%" invites the question "is that the
// offer or what it's worth?" — the whole point of the line is to be unambiguous.
const _mgOffer = (proj, pct) => `Offer: ${_mgMoney(proj, pct)}`;

// Repaint the ladder's dollar figures from the current projection, in place.
// Called on every keystroke because a full mgRender() only happens when the band
// changes — and re-rendering per keystroke would fight the caret and rebuild the
// rebuttals and help panels for nothing.
function _mgSyncMoney() {
    const proj = _mgProjection();
    document.querySelectorAll('.mg-ladder .mg-rung-val[data-pct]').forEach(el => {
        const em = el.querySelector('em');
        if (!em) return;
        const show = proj > 0;
        em.textContent = show ? _mgOffer(proj, Number(el.dataset.pct)) : '';
        em.hidden = !show;
    });
}

// Only the rebuttals tagged for the selected condition (or tagged for none,
// meaning always) — a Mint iPhone should not be offered the micro-scratches
// line. `say` is the spoken version; rows still awaiting the voice pass fall
// back to `why` so nothing renders empty.
function _mgRebuttals() {
    const help = _mgHelp();
    if (!help || !help.rebuttals.length) return '';
    const shown = help.rebuttals.filter(r => !r.conds.length || r.conds.includes(_mgState.cond));
    return `<div class="mg-hp">
        <div class="mg-hp-h">
          <svg class="mg-ico" viewBox="0 0 24 24"><path d="M21 12a8 8 0 0 1-8 8H8l-5 3v-5.5A8 8 0 0 1 8 4h5a8 8 0 0 1 8 8z"/></svg>
          <h4>Rebuttals</h4>
          <span class="mg-ct">${shown.length} of ${help.rebuttals.length} fit this item</span>
        </div>
        <div class="mg-hp-b"><div class="mg-rb-grid">${shown.map(r => `
          <div class="mg-rb">
            <div class="mg-rb-top">
              <span class="mg-rb-dot"></span>
              <span class="mg-rb-name">${_mgEsc(r.name)}</span>
              <span class="mg-rb-tag">${_mgEsc(r.conds.length ? _mgState.cond : 'Any')}</span>
            </div>
            <div class="mg-rb-say">&ldquo;${_mgEsc(r.say || r.why)}&rdquo;</div>
            ${r.say ? `<div class="mg-rb-why"><b>Why</b> ${_mgEsc(r.why)}</div>` : ''}
          </div>`).join('')}</div></div>
      </div>`;
}

function _mgPanel(title, kind, unit) {
    const help = _mgHelp();
    const items = (help && help[kind]) || [];
    const icons = {
        reminder:  '<rect x="7" y="3" width="10" height="4" rx="1"/><path d="M17 5h2a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2h2"/><path d="M8 13.5l2 2 4-4"/>',
        testing:   '<circle cx="11" cy="11" r="7"/><path d="M20 20l-3.8-3.8"/>',
        condition: '<path d="M12 3l9 5-9 5-9-5 9-5z"/><path d="M3 13l9 5 9-5"/>',
    };
    // With no item chosen there is nothing to be empty ABOUT — saying "nothing
    // recorded for this device" before a device exists reads as missing data
    // rather than a step the buyer hasn't taken yet.
    const waiting = !_mgDevice();
    return `<div class="mg-hp">
        <div class="mg-hp-h">
          <svg class="mg-ico" viewBox="0 0 24 24">${icons[kind]}</svg>
          <h4>${title}</h4>${waiting ? '' : `<span class="mg-ct">${items.length} ${unit}</span>`}
        </div>
        <div class="mg-hp-b"><ul class="mg-bl">${waiting
            ? '<li class="mg-empty">Waiting on the item.</li>'
            : (items.map(i =>
                `<li class="${i.must ? 'mg-must-li' : ''}">${i.must ? '<span class="mg-must">Must</span>' : ''}${_mgEsc(i.body)}</li>`
              ).join('') || '<li class="mg-empty">Nothing recorded for this device yet.</li>')
        }</ul></div>
      </div>`;
}

function _mgBind() {
    const cat = document.getElementById('mg-cat');
    const dev = document.getElementById('mg-dev');
    const proj = document.getElementById('mg-projection');

    // Changing EITHER picker clears the projection. It used to survive a category
    // change (the thinking being that one customer's item has one resale value, so
    // a mis-picked category shouldn't cost a retype) — but a stale number is worse
    // than a retyped one here: the band is derived from it, so a leftover projection
    // silently produces a full ladder, and now dollar offers, for the wrong item.
    // Blank is the honest state; the "Enter yours" cue relights straight away.
    cat && cat.addEventListener('change', function () {
        _mgState.cat = this.value;
        // No auto-pick of the first device either — a category can hold six items
        // and guessing one puts numbers on screen the buyer never asked for.
        _mgState.deviceId = null;
        _mgState.cond = null;
        _mgState.proj = '';
        mgRender();
    });

    dev && dev.addEventListener('change', function () {
        const id = parseInt(this.value, 10);
        _mgState.deviceId = Number.isFinite(id) ? id : null;   // "" = back to unchosen
        _mgState.cond = null;
        _mgState.proj = '';
        // A category AND an item chosen is the moment the guide is actually being
        // used — someone is standing at the counter with something in front of
        // them. Opening the tab proves only that they found it. Clearing the
        // picker back to "" is not a lookup, so only a real id counts, and repeat
        // lookups fold into `opens` — the count of items priced this session.
        if (_mgState.deviceId) trackUsage('open', 'mg:lookup', _usageLabel('mg:lookup'));
        mgRender();
    });

    // Digits and at most one decimal point. Sanitizing on input covers typing,
    // pasting and drag-drop in one place; the keydown guard just stops the
    // stray character from ever appearing.
    proj && proj.addEventListener('keydown', function (e) {
        if (e.ctrlKey || e.metaKey || e.altKey || e.key.length > 1) return;
        if (!/[0-9.]/.test(e.key)) e.preventDefault();
    });
    proj && proj.addEventListener('input', function () {
        let v = this.value.replace(/[^0-9.]/g, '');
        const dot = v.indexOf('.');
        if (dot !== -1) v = v.slice(0, dot + 1) + v.slice(dot + 1).replace(/\./g, '');
        if (v !== this.value) {
            const caret = Math.max(0, this.selectionStart - (this.value.length - v.length));
            this.value = v;
            try { this.setSelectionRange(caret, caret); } catch (err) {}
        }
        _mgState.proj = this.value;
        // The cue follows emptiness directly. Toggled here rather than left to a
        // render, because typing inside one band never re-renders — and clearing
        // the box back to empty has to bring the prompt back.
        const f = this.closest('.mg-field-proj');
        if (f) f.classList.toggle('mg-needs', !this.value);
        // Dollars track the exact number, not just which band it lands in, so they
        // have to be repainted on every keystroke — the band-change re-render below
        // fires far too rarely (never, while typing inside one band).
        _mgSyncMoney();
        const d = _mgDevice();
        const b = (d && _mgHasProjection()) ? _mgBandForPrice(d, _mgProjection()) : null;
        const nextBandId = b ? b.id : null;
        if (nextBandId !== _mgState.bandId) {
            const keep = this.value;
            mgRender();
            // Re-renders replace the input, so put the caret back where it was
            // or the buyer loses their place mid-number.
            const again = document.getElementById('mg-projection');
            if (again) { again.value = keep; again.focus(); again.setSelectionRange(keep.length, keep.length); }
        }
    });

    const conds = document.getElementById('mg-conds');
    conds && conds.addEventListener('click', e => {
        const btn = e.target.closest('[data-cond]');
        if (!btn) return;
        _mgState.cond = btn.getAttribute('data-cond');
        mgRender();
    });

}

// Background refresh (60s) so one store's additions/status changes show up for
// the others without a reload. Skips a tick while the pane is hidden or the
// user is mid-typing/editing, so their input is never wiped by a re-render.
let _cbSyncInterval = null;
function _startCbSync() {
    if (_cbSyncInterval) return;
    _cbSyncInterval = setInterval(() => {
        const pane = document.getElementById('ops-pane-callbacks');
        if (!pane || !pane.classList.contains('active') || document.hidden) return;
        if (_cbEditingId) return;
        const active = document.activeElement;
        if (active && active.closest && active.closest('.cb-quickadd, .cb-row-detail')) return;
        cbLoad();
    }, 60000);
}

/* ========================================================================== *
 * MARGIN GUIDE — DM editor (the "Edit" button)
 * --------------------------------------------------------------------------
 * Two ways to change the numbers, because the DM's two real needs work on
 * different axes:
 *
 *   ADJUST  a slice of cells by +/- points. This is the everyday one. Both of
 *           the edits that prompted it cut ACROSS the shared tiers — "Laptops
 *           can't hold these" spans 9 of the 10 tiers, "all new-in-box up 5"
 *           spans 4 — so neither can be expressed by editing tiers without
 *           forking them. An adjustment is a filter plus a delta; the function
 *           resolves it into each cell's percentages.
 *   TIERS   retune one of the ten shared tiers, which moves every cell using
 *           it. Right for a genuine global change, and it reports its own blast
 *           radius before saving.
 *
 * Nothing here writes percentages into cells directly — mg_band_conditions
 * still just points at a tier. That is what keeps the ladder coherent.
 * ========================================================================== */

const MG_EDIT_ROLES = new Set(['district manager', 'ceo', 'mocd']);
function mgCanEditLadder() {
    return MG_EDIT_ROLES.has((sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim());
}

/* ==========================================================================
 * The DM editor: ONE WORKSPACE PER ITEM.
 *
 * Replaces the old three tabs (Adjust a slice / The ten tiers / What it says).
 * Those modelled the implementation — a shared ladder plus a delta layer — while
 * the DM is almost always thinking about one item. Three tabs meant three units
 * of work, two separate item pickers, and three different save affordances.
 *
 * The lever is mg_band_conditions.tier_id: which tier this (band, condition)
 * cell pays on. The edge fn has always had `assignTier`; nothing ever called it,
 * so the most direct edit in the whole model was unreachable and the only ways
 * to change a number were to retune a shared tier (moves every item using it) or
 * build a scoped delta (never once used — mg_adjustments was empty).
 *
 * The ten tiers are no longer editable here at all. That is deliberate: with
 * assignment as the only lever, NOTHING in this screen can move a cell belonging
 * to another item. Retuning the ladder itself becomes a migration.
 * ========================================================================== */
let _mgAdmin = {
    open: false,
    deviceId: '',        // the item being edited
    busy: false,
    pickOpen: false,     // the item listbox in the header
    cell: null,          // { bandId, cond } — which cell's tier popover is open
    reb: null,           // id of the one expanded rebuttal (accordion, one at a time)
    pending: new Map(),  // "bandId|cond" -> { from, to } queued cell moves
};

const _mgPendKey = (bandId, cond) => bandId + '|' + cond;

function mgOpenAdmin() {
    if (!mgCanEditLadder()) return;
    _mgAdmin.open = true;
    // Always arrive with the rebuttal list shut. Whichever one was open belonged
    // to the last visit, and reopening onto a half-scrolled expanded card reads
    // as the editor having remembered the wrong thing.
    _mgAdmin.reb = null;
    // Inherit whatever the DM was already looking at as a buyer. They almost
    // always get here because something on the screen in front of them read
    // wrong, so preselecting that item saves re-finding it.
    if (!_mgAdmin.deviceId && _mgState.deviceId) _mgAdmin.deviceId = String(_mgState.deviceId);
    mgRender();
}
function mgCloseAdmin() {
    if (!_mgAdminConfirmDiscard()) return;
    _mgAdmin.open = false;
    _mgAdmin.cell = null;
    _mgAdmin.reb = null;
    mgRender();
}

// Queued cell moves live only in memory until Save, so leaving the screen (or
// switching item) has to say so rather than dropping them silently.
function _mgAdminConfirmDiscard() {
    const n = _mgAdmin.pending.size;
    if (!n) return true;
    if (!confirm(`${n} cell change${n === 1 ? '' : 's'} ${n === 1 ? 'has' : 'have'} not been saved.\n\nLeave and lose ${n === 1 ? 'it' : 'them'}?`)) return false;
    _mgAdmin.pending.clear();
    return true;
}

function mgAdminPick(value) {
    if (!_mgAdminConfirmDiscard()) { mgRender(); return; }
    _mgAdmin.deviceId = value;
    _mgAdmin.cell = null;
    mgRender();
}

// The item being edited, and its tier lookup.
const _mgAdminDevice = () => _mgDevices().find(d => String(d.id) === String(_mgAdmin.deviceId)) || null;
const _mgTierById = id => ((_mgCatalog && _mgCatalog.tiers) || []).find(t => Number(t.id) === Number(id)) || null;

// The effective tier for a cell: the queued move if there is one, else what the
// catalog says. Every render path reads through this so a pending change looks
// exactly like a saved one, minus the "was" note.
function _mgCellTier(band, cond) {
    const p = _mgAdmin.pending.get(_mgPendKey(band.id, cond));
    return p ? p.to : (band.conds || {})[cond];
}

// Conditions this item actually has a row for, plus the next one it does NOT —
// an absent condition is meaningful (we don't buy Broken accessories), so it is
// rendered as "Not bought" rather than dropped, and stays one click from being
// added.
// Every condition, always. This used to show the ones in use plus exactly ONE
// unused column, which made the grades a ladder you had to climb in order:
// CHECKOUT was unreachable until you had decided to buy the item Broken, and
// Broken CHECKOUT until CHECKOUT. There is no such dependency between grades —
// an item can be bought through Checkout and not Broken — so every cell is now
// one click from being turned on, independent of every other.
function _mgAdminConds() {
    return _mgCondOrder();
}

async function _mgAdminPost(payload, btn) {
    if (_mgAdmin.busy) return null;
    _mgAdmin.busy = true;
    const label = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
    try {
        const res = await fetch(MARGIN_GUIDE_URL, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                ...payload,
                role: (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim(),
                user: sessionStorage.getItem('speeksUserName') || null,
            }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Save failed');
        // The catalog is cached for the session and every buyer reads it, so a
        // write has to invalidate it or the DM sees stale numbers in the very
        // screen they just edited.
        _mgCatalog = null;
        await mgLoad({ keep: true });
        return json;
    } catch (e) {
        alert(e.message || 'Could not save that.');
        if (btn) { btn.disabled = false; btn.textContent = label; }
        return null;
    } finally {
        _mgAdmin.busy = false;
    }
}

/* ---- cell moves ---------------------------------------------------------- */

// Open / close the tier picker for one cell. Toggling the same cell closes it,
// so the popover behaves like the disclosure it looks like.
function mgCellOpen(bandId, cond) {
    const c = _mgAdmin.cell;
    _mgAdmin.cell = (c && c.bandId === Number(bandId) && c.cond === cond)
        ? null : { bandId: Number(bandId), cond };
    mgRender();
}
function mgCellClose() { _mgAdmin.cell = null; mgRender(); }

// Queue a move rather than writing it: a DM retuning an item usually touches
// several cells, and one confirmation for the set beats one per click.
function mgCellPick(bandId, cond, tierId) {
    const device = _mgAdminDevice();
    const band = device && (device.bands || []).find(b => b.id === Number(bandId));
    if (!band) return;
    const key = _mgPendKey(Number(bandId), cond);
    const prev = _mgAdmin.pending.get(key);
    const from = prev ? prev.from : ((band.conds || {})[cond] ?? null);
    const to = tierId === null ? null : Number(tierId);
    // Back to where it started is not a change.
    if (from === to) _mgAdmin.pending.delete(key);
    else _mgAdmin.pending.set(key, { from, to });
    _mgAdmin.cell = null;
    mgRender();
}

function mgCellsDiscard() {
    if (!_mgAdmin.pending.size) return;
    _mgAdmin.pending.clear();
    mgRender();
}

// Writes each queued cell through assignTier. Sequential rather than parallel so
// a failure stops the run instead of leaving an unknown subset applied, and so
// the error names the cell that actually failed.
async function mgCellsSave(btn) {
    const device = _mgAdminDevice();
    if (!device || !_mgAdmin.pending.size || _mgAdmin.busy) return;
    const entries = [..._mgAdmin.pending.entries()];
    const label = btn ? btn.textContent : '';
    _mgAdmin.busy = true;
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }

    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    const user = sessionStorage.getItem('speeksUserName') || null;
    let done = 0;
    try {
        for (const [key, move] of entries) {
            const [bandId, ...rest] = key.split('|');
            const cond = rest.join('|');
            const res = await fetch(MARGIN_GUIDE_URL, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    action: 'assignTier', band_id: Number(bandId), condition: cond,
                    tier_id: move.to === null ? null : Number(move.to), role, user,
                }),
            });
            const out = await res.json().catch(() => ({}));
            if (!res.ok || out.success === false) throw new Error(out.error || `Could not save ${cond}.`);
            _mgAdmin.pending.delete(key);
            done++;
        }
    } catch (e) {
        alert(`${e.message}\n\n${done} of ${entries.length} saved. The rest are still pending.`);
    } finally {
        _mgAdmin.busy = false;
        if (btn) { btn.disabled = false; btn.textContent = label; }
        // Buyers read the same cached catalog, so a write has to invalidate it or
        // the DM sees stale numbers on the screen they just edited.
        _mgCatalog = null;
        await mgLoad({ keep: true });
        mgRender();
    }
}

// Flat-pay bands hold dollars, not a tier, so they save on their own — there is
// no cell to queue. Until now nothing in the tool could edit them at all.
async function mgSaveFlatBand(bandId, btn) {
    const wrap = document.getElementById(`mg-aflat-${bandId}`);
    if (!wrap) return;
    const low = Number(wrap.querySelector('[data-f="low"]').value);
    const high = Number(wrap.querySelector('[data-f="high"]').value);
    if (![low, high].every(Number.isFinite)) { alert('Both dollar amounts are required.'); return; }
    if (low < 0 || high < low) {
        alert('The high end has to be at least the low end, and neither can be negative.');
        return;
    }
    const out = await _mgAdminPost({ action: 'saveBand', band_id: Number(bandId), flat_low: low, flat_high: high }, btn);
    if (out) mgRender();
}

// A hand-built listbox rather than a <select>. The native one opened UPWARD and
// covered the page: a 40-item, 14-group list is taller than the room under a
// header sitting low in the viewport, and Chrome flips it in that case. Popup
// direction is not stylable on a native select, so the only way to guarantee it
// drops down is to own the menu.
function mgAdminPickToggle() {
    _mgAdmin.pickOpen = !_mgAdmin.pickOpen;
    _mgAdmin.cell = null;      // never two menus open at once
    mgRender();
}
// One dismiss for both this and the cell popover — clicking off either closes it.
function mgAdminDismiss() {
    _mgAdmin.pickOpen = false;
    _mgAdmin.cell = null;
    mgRender();
}

function _mgAdminHead() {
    const cats = [...new Set(_mgDevices().map(d => d.category))];
    const dev = _mgAdminDevice();
    const open = !!_mgAdmin.pickOpen;
    const menu = open ? `<div class="mg-picker-menu" role="listbox">
        ${cats.map(c => `<div class="mg-picker-grp">${_mgEsc(c)}</div>
          ${_mgDevices().filter(d => d.category === c).map(d => {
              const on = String(d.id) === String(_mgAdmin.deviceId);
              return `<button type="button" class="mg-picker-opt${on ? ' on' : ''}" role="option"
                        aria-selected="${on}" onclick="mgAdminPickItem('${d.id}')">${_mgEsc(d.device)}</button>`;
          }).join('')}`).join('')}
      </div>` : '';

    // No back button here — it lives in the panel header, in the slot the Manage
    // button vacates, so entering and leaving happen in the same place.
    return `<div class="mg-adm-head">
        <div class="mg-adm-pick">
          <span class="mg-adm-editing">Editing</span>
          <div class="mg-picker${open ? ' open' : ''}">
            <button type="button" class="mg-picker-btn" aria-haspopup="listbox" aria-expanded="${open}"
                    onclick="mgAdminPickToggle()">
              <span${dev ? '' : ' class="mg-picker-ph"'}>${_mgEsc(dev ? dev.device : 'Pick an item…')}</span>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
            </button>
            ${menu}
          </div>
        </div>
        ${dev ? `<span class="mg-adm-meta">${(dev.bands || []).length} band${(dev.bands || []).length === 1 ? '' : 's'}</span>` : ''}
      </div>`;
}

/* ---- the grid: one row per price band, one column per condition ----------
 * Cell shading tracks how richly a tier pays, so the ladder should visibly drain
 * away as you read right and down. A cell that breaks the gradient is a cell on
 * the wrong tier, readable before any number is.
 */
function _mgTierRank(tierId) {
    const tiers = (_mgCatalog && _mgCatalog.tiers) || [];
    const i = tiers.findIndex(t => Number(t.id) === Number(tierId));
    return i < 0 ? tiers.length : i + 1;
}

function _mgCellBtn(band, cond) {
    const tierId = _mgCellTier(band, cond);
    const key = _mgPendKey(band.id, cond);
    const pend = _mgAdmin.pending.get(key);
    const open = _mgAdmin.cell && _mgAdmin.cell.bandId === band.id && _mgAdmin.cell.cond === cond;
    const call = `mgCellOpen(${band.id}, '${_mgEsc(cond).replace(/'/g, "\\'")}')`;

    if (!tierId) {
        // Absent on purpose: we do not buy this item in this condition. Rendered
        // rather than dropped so the gap is visible, and one click from filled.
        return `<td class="mg-cellw">
            <button type="button" class="mg-cell-none${pend ? ' pending' : ''}${open ? ' open' : ''}" onclick="${call}">
              Not bought${pend ? '<em>was ' + _mgEsc((_mgTierById(pend.from) || {}).name || '—') + '</em>' : ' +'}
            </button>${open ? _mgCellPop(band, cond, null) : ''}</td>`;
    }
    const t = _mgTierById(tierId);
    if (!t) return '<td class="mg-cellw"></td>';
    const adj = ((band.pct || {})[cond] || {}).adj || 0;
    return `<td class="mg-cellw">
        <button type="button" class="mg-cell${pend ? ' pending' : ''}${open ? ' open' : ''}" data-rank="${_mgTierRank(tierId)}" onclick="${call}">
          <span class="mg-cell-tier">${_mgEsc(t.name)}</span>
          <span class="mg-cell-pcts">${t.start_pct} &middot; ${t.team_pct} &middot; ${t.mgr_pct}${adj ? ` <i>${adj > 0 ? '+' : ''}${adj}</i>` : ''}</span>
          ${pend ? `<span class="mg-cell-was">was ${_mgEsc((_mgTierById(pend.from) || {}).name || 'not bought')}</span>` : ''}
        </button>${open ? _mgCellPop(band, cond, tierId) : ''}</td>`;
}

// The tier picker. Rendered inline in the cell rather than appended to <body>:
// it stays put on scroll, needs no coordinate maths, and survives the re-render
// that every pick triggers.
function _mgCellPop(band, cond, current) {
    const tiers = (_mgCatalog && _mgCatalog.tiers) || [];
    const esc = s => _mgEsc(s).replace(/'/g, "\\'");
    return `<div class="mg-pop" role="dialog" aria-label="Pick a tier">
        <div class="mg-pop-h">
          <b>${_mgEsc(band.label)} &middot; ${_mgEsc(cond)}</b>
          <span>Pick the tier this cell pays on</span>
        </div>
        <div class="mg-pop-list">
          ${tiers.map(t => `<button type="button" class="mg-pop-opt${Number(t.id) === Number(current) ? ' on' : ''}"
                onclick="mgCellPick(${band.id}, '${esc(cond)}', ${t.id})">
              <span class="mg-pop-tick">${Number(t.id) === Number(current)
                ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>' : ''}</span>
              <span class="mg-pop-name">${_mgEsc(t.name)}</span>
              <span class="mg-pop-nums">${t.start_pct} &middot; ${t.team_pct} &middot; ${t.mgr_pct}</span>
            </button>`).join('')}
        </div>
        <div class="mg-pop-foot">
          ${current === null
            ? `<span class="mg-pop-note">We do not buy this item in this condition.</span>`
            : `<button type="button" class="mg-pop-clear" onclick="mgCellPick(${band.id}, '${esc(cond)}', null)">
                 Stop buying this condition</button>`}
        </div>
      </div>`;
}

function _mgAdminGrid(device) {
    const cols = _mgAdminConds();
    const head = `<thead><tr><th class="mg-gband">Price band</th>${
        cols.map(c => `<th>${_mgEsc(c)}</th>`).join('')}</tr></thead>`;

    const rows = (device.bands || []).map(b => {
        if (b.payMode === 'flat') {
            const cash = v => (Number(v) % 1 === 0 ? String(Number(v)) : Number(v).toFixed(2));
            return `<tr><td class="mg-gband">
                <div class="mg-gband-n">${_mgEsc(b.label)}</div>
                <div class="mg-gband-s">Flat pay</div></td>
              <td colspan="${cols.length}">
                <div class="mg-aflat" id="mg-aflat-${b.id}">
                  <span class="mg-aflat-lab">Pays a flat amount, not a percentage</span>
                  <span class="mg-aflat-in">$<input type="text" data-f="low" value="${cash(b.flatLow)}" aria-label="Low end"></span>
                  <span class="mg-aflat-in">to&nbsp;$<input type="text" data-f="high" value="${cash(b.flatHigh)}" aria-label="High end"></span>
                  <button type="button" class="mg-btn-go mg-aflat-save" onclick="mgSaveFlatBand(${b.id}, this)">Save</button>
                  <span class="mg-aflat-note">Same in every condition &middot; no tier applies</span>
                </div></td></tr>`;
        }
        return `<tr><td class="mg-gband">
            <div class="mg-gband-n">${_mgEsc(b.label)}</div>
            <div class="mg-gband-s">Start &middot; Yours &middot; Manager</div></td>
          ${cols.map(c => _mgCellBtn(b, c)).join('')}</tr>`;
    }).join('');

    // See .mg-gwrap.popped — the sideways scroll container has to stand down while
    // a tier popover is open, or it clips the popover at the grid's bottom edge.
    return `<div class="mg-gwrap${_mgAdmin.cell ? ' popped' : ''}"><table class="mg-agrid">${head}<tbody>${rows}</tbody></table></div>`;
}

function _mgAdminNumbers() {
    const device = _mgAdminDevice();
    if (!device) return '';
    return `<section class="mg-adm-sec">
        <div class="mg-adm-sech"><h4>The numbers</h4>
          <span class="mg-adm-sechint">Click a cell to move it to another tier</span></div>
        ${_mgAdminGrid(device)}
      </section>`;
}

// Sits at the foot of the screen only while cells are queued. One save for the
// item, rather than a button per row.
function _mgAdminBar() {
    const n = _mgAdmin.pending.size;
    if (!n) return '';
    return `<div class="mg-savebar">
        <span class="mg-savebar-n"><b>${n}</b> unsaved cell change${n === 1 ? '' : 's'}</span>
        <button type="button" class="mg-sb-discard" onclick="mgCellsDiscard()">Discard</button>
        <button type="button" class="mg-sb-save" onclick="mgCellsSave(this)">Save</button>
      </div>`;
}

/* ==========================================================================
 * "What it says" — the coaching TEXT, as opposed to the numbers.
 *
 * Covers everything a buyer reads: the "Before you buy" warning card, the three
 * help lists down the right-hand side (Reminders / Testing Tips / Condition
 * Help), and the rebuttals. These went stale fastest and were the one part of
 * the tool nobody could change without a migration.
 *
 * DIRECT EDITS, no delta layer — the opposite call to the percentages, and for a
 * concrete reason: help_key is all but per-device (2 of 35 keys are shared), so
 * there is no shared-tier problem to avoid. The two shared keys are handled by
 * telling the DM up front how many items the block reaches. See
 * 0008_margin_guide_text.sql.
 * ========================================================================== */

// The four help sections. 'gate' is not a database kind — it's is_gate on a row
// whose kind is still one of the three, which is why promoting a tip to the hero
// card can send it back to exactly the list it came from.
const MG_TEXT_SECTIONS = [
    { key: 'gates',     title: 'Before you buy', kind: 'reminder', icon: 'warn',
      hint: 'Hard preconditions — get one wrong and the deal is void. These render as the warning card above the ladder and are deliberately kept out of the lists below, so each rule is stated exactly once.' },
    { key: 'reminder',  title: 'Reminders', kind: 'reminder', icon: 'list',
      hint: 'General buying guidance for this item.' },
    { key: 'testing',   title: 'Testing Tips', kind: 'testing', icon: 'check',
      hint: 'What to verify on the device before agreeing a price.' },
    { key: 'condition', title: 'Condition Help', kind: 'condition', icon: 'grade',
      hint: 'How to grade this item — what separates Mint from Used-A from Broken.' },
];

// Unsaved edits, keyed by row id ('new:<section>' for the add boxes). Held
// outside the DOM because every successful write re-reads the catalog and
// re-renders this pane — without it, saving one line would silently discard
// every other line the DM had in progress. Same lesson as the audit scorecard.
let _mgTextDrafts = {};

// The item is chosen once, in the workspace header — the wording and the numbers
// on this screen are always the same item's. (It used to be a second, separate
// picker on its own tab.)
const _mgTextDevice = () => _mgAdminDevice();

// Items sharing this device's help_key. Only two keys in the catalog are shared
// (Audio/Home Theatre covers 4 items, Miscellaneous 3), but when they are, a DM
// editing "Speakers" is really editing all four and has to be told before saving.
function _mgTextSiblings() {
    const d = _mgTextDevice();
    if (!d) return [];
    return _mgDevices().filter(x => x.helpKey === d.helpKey);
}

function _mgTextHelp() {
    const d = _mgTextDevice();
    return (d && _mgCatalog.help[d.helpKey]) || null;
}

// Rows for one section, in display order.
function _mgTextRows(sectionKey) {
    const help = _mgTextHelp();
    if (!help) return [];
    const rows = sectionKey === 'gates' ? (help.gates || []) : (help[sectionKey] || []);
    return [...rows].sort((a, b) => (a.sort ?? 0) - (b.sort ?? 0) || a.id - b.id);
}

// Wording drafts belong to the item they were typed against, so switching item
// clears them. Called from the one picker in the workspace header.
function mgAdminPickItem(value) {
    _mgTextDrafts = {};
    _mgAdmin.pickOpen = false;
    _mgAdmin.reb = null;      // the open rebuttal belongs to the item you're leaving
    mgAdminPick(value);
}

// Draft plumbing. oninput only records; nothing is sent until Save is pressed,
// so a half-typed rule never reaches a buyer's screen.
function mgTextDraft(id, field, value) {
    const k = String(id);
    (_mgTextDrafts[k] ||= {})[field] = value;
    // Toggle the row's own Save button rather than re-rendering: re-rendering on
    // every keystroke would move the caret to the end of the textarea.
    const row = document.querySelector(`[data-mgrow="${k}"]`);
    if (row) {
        row.classList.add('mg-dirty');
        // Rebuttals live inside an accordion; mark the bar too so shutting one
        // mid-edit still shows it as unsaved.
        const acc = row.closest('.mg-racc');
        if (acc) acc.classList.add('mg-dirty');
    }
    // Same reason the caret rules out a re-render: patch the accordion bar's
    // label directly so it isn't still reading "Untitled rebuttal" as you name it.
    if (field === 'name') {
        const lab = document.querySelector(`[data-rebname="${k}"]`);
        if (lab) lab.textContent = value || (k.startsWith('new:') ? 'Add a rebuttal' : 'Untitled rebuttal');
    }
}
const _mgTextVal = (id, field, fallback) => {
    const d = _mgTextDrafts[String(id)];
    return d && d[field] !== undefined ? d[field] : fallback;
};
function mgTextDiscard(id) {
    delete _mgTextDrafts[String(id)];
    mgRender();
}

const _MG_TEXT_ICONS = {
    warn:  '<path d="M12 9v4"/><path d="M12 17h.01"/><path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/>',
    list:  '<rect x="7" y="3" width="10" height="4" rx="1"/><path d="M17 5h2a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2h2"/><path d="M8 13.5l2 2 4-4"/>',
    check: '<circle cx="11" cy="11" r="7"/><path d="M20 20l-3.8-3.8"/>',
    grade: '<path d="M12 2l3 6.5 7 1-5 5 1.2 7L12 18.2 5.8 21.5 7 14.5l-5-5 7-1z"/>',
    talk:  '<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>',
};
const _mgTextIcon = k => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${_MG_TEXT_ICONS[k] || ''}</svg>`;

// ---- writes -----------------------------------------------------------------

// Reads the row out of the DOM rather than out of the draft map. A draft only
// exists for fields actually touched, so defaulting a missing draft to ''/false
// would blank the text of an unedited row and quietly clear its Strong flag.
// The DOM always holds the full current state.
const _mgTextRowEl = id => document.querySelector(`[data-mgrow="${String(id).replace(/"/g, '')}"]`);

async function mgSaveHelpItem(id, kind, isGate, btn) {
    const el = _mgTextRowEl(id);
    if (!el) return;
    const text = String((el.querySelector('.mg-tbody') || {}).value || '').trim();
    if (!text) { alert('The text can\'t be empty. Use × if you want the line gone.'); return; }
    const mustBox = el.querySelector('.mg-tmust input');
    const sibs = _mgTextSiblings();
    if (sibs.length > 1 && !confirm(`This wording is shared by ${sibs.length} items:\n\n${sibs.map(s => '· ' + s.device).join('\n')}\n\nSave the change to all of them?`)) return;
    const out = await _mgAdminPost({
        action: 'saveHelpItem',
        id: String(id).startsWith('new:') ? null : id,
        help_key: (_mgTextDevice() || {}).helpKey,
        kind, body: text,
        is_gate: !!isGate,
        is_must: !!(mustBox && mustBox.checked),
    }, btn);
    if (out) { delete _mgTextDrafts[String(id)]; mgRender(); }
}

async function mgDeleteHelpItem(id, btn) {
    if (!confirm('Delete this line?\n\nIt disappears from every buyer\'s screen immediately.')) return;
    const out = await _mgAdminPost({ action: 'deleteHelpItem', id }, btn);
    if (out) { delete _mgTextDrafts[String(id)]; mgRender(); }
}

async function mgPinHelpItem(id, toGate, btn) {
    const out = await _mgAdminPost({ action: 'setHelpGate', id, is_gate: !!toGate }, btn);
    if (out) mgRender();
}

// No mgMoveHelpItem / mgMoveRebuttal: manual reordering was dropped (Ethan,
// 2026-08-01) — what matters is that a line is present, not where it sits in its
// list. sort_order still exists and still orders the lists on read, and Pin /
// Unpin still resequences the group it leaves; new rows just append. The edge
// function's moveHelpItem / moveRebuttal actions are left in place, unused.

/* NAMESPACED KEYS. mg_help_items and mg_rebuttals are separate tables that both
 * start their ids at 1, so all 228 rebuttal ids also name a help item — and on
 * the Apple iPhone screen, rebuttals 1-7 and help items 1-7 both render. Both
 * used the bare id as their data-mgrow and their _mgTextDrafts key, so
 * _mgTextRowEl() returned whichever came first in the DOM (always the help item;
 * help sections render above the rebuttals) and the two shared a draft slot.
 * Saving a rebuttal read the help row's fields, found no .mg-rname, and refused
 * with "Give the rebuttal a name" — no rebuttal was saveable at all. Prefixing
 * the client-side key fixes both; the bare number is what still goes to the
 * server. */
const _mgRebKey = id => String(id).startsWith('new:') ? String(id) : 'reb:' + id;
const _mgRebId  = key => String(key).replace(/^reb:/, '');

async function mgSaveRebuttal(key, btn) {
    const el = _mgTextRowEl(key);
    if (!el) return;
    const field = sel => String((el.querySelector(sel) || {}).value || '').trim();
    const name = field('.mg-rname');
    const why  = field('[data-rf="why"]');
    if (!name) { alert('Give the rebuttal a name — that\'s the heading a buyer scans for mid-conversation.'); return; }
    if (!why)  { alert('A rebuttal needs its line. That\'s the whole thing a buyer reads out.'); return; }
    // Tags live only in the draft (they're buttons, not inputs), so read them
    // from there and fall back to what's on the row today.
    const conds = _mgTextVal(key, 'conds', [...el.querySelectorAll('.mg-ctag.on')].map(b => b.dataset.cond));
    const sibs = _mgTextSiblings();
    if (sibs.length > 1 && !confirm(`This rebuttal is shared by ${sibs.length} items:\n\n${sibs.map(s => '· ' + s.device).join('\n')}\n\nSave to all of them?`)) return;
    const out = await _mgAdminPost({
        action: 'saveRebuttal',
        id: String(key).startsWith('new:') ? null : Number(_mgRebId(key)),
        help_key: (_mgTextDevice() || {}).helpKey,
        name, why,
        // One field now — see _mgRebText. The box already holds `say || why`, so
        // writing it to `why` and clearing `say` collapses the row to what the
        // DM just looked at. The edge fn stores "" as NULL, which is what the
        // buyer's `say || why` needs to fall through cleanly.
        say: '',
        conditions: conds,
    }, btn);
    if (out) {
        delete _mgTextDrafts[String(key)];
        // The add row's fields are now blank, so leaving it open just shows an
        // empty form over the rebuttal it created. Shut it.
        if (String(key).startsWith('new:')) _mgAdmin.reb = null;
        mgRender();
    }
}

async function mgDeleteRebuttal(key, btn) {
    if (!confirm('Delete this rebuttal?')) return;
    const out = await _mgAdminPost({ action: 'deleteRebuttal', id: Number(_mgRebId(key)) }, btn);
    if (out) {
        delete _mgTextDrafts[String(key)];
        if (_mgAdmin.reb === String(key)) _mgAdmin.reb = null;
        mgRender();
    }
}

// A rebuttal with no tags applies to every grade; tagging it narrows it. Toggling
// only touches the draft — nothing is written until Save. The current state is
// looked up from the catalog rather than passed in, which keeps a JSON array out
// of an onclick attribute.
function _mgRebConds(key) {
    const id = _mgRebId(key);
    const row = _mgTextRows('rebuttals').find(r => String(r.id) === id);
    return _mgTextVal(key, 'conds', (row && row.conds) || []);
}
function mgTextTag(key, cond) {
    const list = [..._mgRebConds(key)];
    const at = list.indexOf(cond);
    if (at >= 0) list.splice(at, 1); else list.push(cond);
    (_mgTextDrafts[String(key)] ||= {}).conds = list;
    mgRender();
}

// ---- rendering --------------------------------------------------------------

// Size a textarea to the text already in it. A fixed rows="2" clipped the longer
// seeded rules (several run past 80 characters), which is the one thing an editor
// must not do — you cannot fix wording you cannot see.
function _mgRows(text, perLine, max = 9) {
    return Math.min(max, Math.max(2, Math.ceil((String(text).length || 1) / perLine)));
}

function _mgHelpRow(row, section) {
    const id = row.id;
    const body = _mgTextVal(id, 'body', row.body);
    const must = _mgTextVal(id, 'must', !!row.must);
    const dirty = body !== row.body || must !== !!row.must;
    const isGate = section.key === 'gates';
    // A gate's kind decides which list it returns to when unpinned, so it has to
    // travel with the row rather than being re-derived from the section.
    const kind = isGate ? (row.kind || 'reminder') : section.kind;
    return `<div class="mg-trow${dirty ? ' mg-dirty' : ''}" data-mgrow="${id}">
        <textarea class="mg-tbody" rows="${_mgRows(body, isGate ? 104 : 46)}" oninput="mgTextDraft(${id}, 'body', this.value)">${_mgEsc(body)}</textarea>
        <div class="mg-trow-acts">
          ${isGate
            ? `<button type="button" class="mg-tbtn" title="Move this back into ${_mgEsc(kind === 'reminder' ? 'Reminders' : kind === 'testing' ? 'Testing Tips' : 'Condition Help')}" onclick="mgPinHelpItem(${id}, false, this)">Unpin</button>`
            : `<button type="button" class="mg-tbtn" title="Promote to the Before-you-buy card above the ladder" onclick="mgPinHelpItem(${id}, true, this)">Pin to top</button>
               <label class="mg-tmust" title="Render this line emphasized inside its list"><input type="checkbox"${must ? ' checked' : ''} onchange="mgTextDraft(${id}, 'must', this.checked); mgRender()"> Strong</label>`}
          <button type="button" class="mg-btn-go mg-tsave" onclick="mgSaveHelpItem(${id}, '${kind}', ${isGate}, this)">Save</button>
          ${dirty ? `<button type="button" class="mg-tbtn" onclick="mgTextDiscard(${id})">Undo</button>` : ''}
          <button type="button" class="mg-tdel" title="Delete" onclick="mgDeleteHelpItem(${id}, this)">&#215;</button>
        </div>
      </div>`;
}

function _mgHelpSection(section) {
    const rows = _mgTextRows(section.key);
    const nid = 'new:' + section.key;
    const draft = _mgTextVal(nid, 'body', '');
    const isGate = section.key === 'gates';
    return `<section class="mg-tsec mg-tsec-${section.key}">
        <header class="mg-tsec-h">
          <span class="mg-tsec-ic mg-tsec-${section.icon}">${_mgTextIcon(section.icon)}</span>
          <h4>${_mgEsc(section.title)}</h4>
          <span class="mg-tsec-n">${rows.length}</span>
        </header>
        <p class="mg-tsec-hint">${section.hint}</p>
        ${rows.length
            ? `<div class="mg-trows">${rows.map(r => _mgHelpRow(r, section)).join('')}</div>`
            : `<div class="mg-adm-none">Nothing here yet${isGate ? ' — this item shows no warning card.' : '.'}</div>`}
        <div class="mg-tadd" data-mgrow="${nid}">
          <textarea class="mg-tbody" rows="2" placeholder="${isGate ? 'Add a hard precondition…' : 'Add a line…'}" oninput="mgTextDraft('${nid}', 'body', this.value)">${_mgEsc(draft)}</textarea>
          <button type="button" class="mg-btn-go" onclick="mgSaveHelpItem('${nid}', '${section.kind}', ${isGate}, this)">Add</button>
        </div>
      </section>`;
}

/* ONE PIECE OF TEXT PER REBUTTAL.
 *
 * The table still has two columns: `say` (the scripted line) and `why` (the
 * business reason). 195 of the 228 rebuttals only ever had `why` — the buyer
 * renders `say || why` as the quote, so for those there was one piece of text
 * behind two boxes. The 33 that carry both are near-restatements of each other,
 * with `say` the fuller, customer-facing wording.
 *
 * So the editor shows one box, holding whatever the buyer actually reads
 * (`say || why`), and saving writes it to `why` and clears `say`. Rows migrate as
 * they're edited rather than in one sweep, and nothing on screen is ever lost —
 * what's in the box IS what the buyer sees. The only casualty is the small "Why"
 * sub-line under the quote on the 33, which stops appearing once that rebuttal is
 * next saved. The buyer renderer needs no change: it already handles say = null.
 */
const _mgRebText = row => String(row.say || row.why || '');

// Is this rebuttal's on-screen state different from what's saved?
function _mgRebDirty(row) {
    const key = _mgRebKey(row.id);
    const name = _mgTextVal(key, 'name', row.name || '');
    const text = _mgTextVal(key, 'why', _mgRebText(row));
    const conds = _mgTextVal(key, 'conds', row.conds || []);
    if (String(key).startsWith('new:')) return !!(name || text);
    return name !== (row.name || '') || text !== _mgRebText(row)
        || conds.join('|') !== (row.conds || []).join('|');
}

/* An accordion, one open at a time. Expanded, a rebuttal is a name, its text and
 * six grade tags; a dozen of them ran the editor several screens deep and buried
 * the grid it belongs next to. Collapsing loses nothing — drafts live in
 * _mgTextDrafts, outside the DOM, exactly so a re-render can't drop typing. */
function mgRebToggle(id) {
    const k = String(id);
    _mgAdmin.reb = _mgAdmin.reb === k ? null : k;
    mgRender();
}

function _mgRebuttalBar(row) {
    const key = _mgRebKey(row.id);      // 'reb:<id>' — see the note on _mgRebKey
    const isNew = key.startsWith('new:');
    const open = _mgAdmin.reb === key;
    const dirty = _mgRebDirty(row);
    const name = _mgTextVal(key, 'name', row.name || '');
    const conds = _mgTextVal(key, 'conds', row.conds || []);
    const label = isNew ? 'Add a rebuttal' : (name || 'Untitled rebuttal');
    const meta = isNew ? '' : (conds.length ? conds.join(' · ') : 'Every grade');

    return `<div class="mg-racc${open ? ' open' : ''}${isNew ? ' isnew' : ''}${dirty ? ' mg-dirty' : ''}">
        <div class="mg-rbar">
          <button type="button" class="mg-rbar-t" aria-expanded="${open}" onclick="mgRebToggle('${key}')">
            <span class="mg-rbar-cv"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg></span>
            <span class="mg-rbar-n" data-rebname="${key}">${_mgEsc(label)}</span>
            ${meta ? `<span class="mg-rbar-m">${_mgEsc(meta)}</span>` : ''}
            ${dirty ? '<span class="mg-rbar-d">Unsaved</span>' : ''}
          </button>
          ${isNew ? '' : `<button type="button" class="mg-tdel" title="Delete" onclick="mgDeleteRebuttal('${key}', this)">&#215;</button>`}
        </div>
        ${open ? _mgRebuttalCard(row) : ''}
      </div>`;
}

// The expanded body. Reordering and deleting live on the bar above, so they stay
// reachable while the card is shut.
function _mgRebuttalCard(row) {
    const key = _mgRebKey(row.id);      // NOT row.id — see the note on _mgRebKey
    const name = _mgTextVal(key, 'name', row.name || '');
    const text = _mgTextVal(key, 'why', _mgRebText(row));
    const conds = _mgTextVal(key, 'conds', row.conds || []);
    const isNew = String(key).startsWith('new:');
    const dirty = _mgRebDirty(row);
    return `<div class="mg-rcard${dirty ? ' mg-dirty' : ''}" data-mgrow="${key}">
        <label class="mg-rfield">
          <em>Name <i>&mdash; what the customer is pushing back on</i></em>
          <input class="mg-rname" type="text" placeholder="&ldquo;I can get more on eBay&rdquo;" value="${_mgEsc(name)}" oninput="mgTextDraft('${key}', 'name', this.value)">
        </label>
        <label class="mg-rfield">
          <em>What to say <i>&mdash; read almost verbatim to the customer</i></em>
          <textarea data-rf="why" rows="${_mgRows(text, 108, 7)}" placeholder="The line a buyer reads out when the customer pushes back." oninput="mgTextDraft('${key}', 'why', this.value)">${_mgEsc(text)}</textarea>
        </label>
        <div class="mg-rconds">
          <span class="mg-rconds-l">Shows for${conds.length ? '' : ' <b>every grade</b>'}</span>
          <div class="mg-ctags">
            ${_mgCondOrder().map(c => `<button type="button" class="mg-ctag${conds.includes(c) ? ' on' : ''}" data-cond="${_mgEsc(c)}" onclick="mgTextTag('${key}', '${_mgEsc(c)}')">${_mgEsc(c)}</button>`).join('')}
          </div>
        </div>
        <div class="mg-rcard-acts">
          <button type="button" class="mg-btn-go" onclick="mgSaveRebuttal('${key}', this)">${isNew ? 'Add rebuttal' : 'Save'}</button>
          ${dirty && !isNew ? `<button type="button" class="mg-tbtn" onclick="mgTextDiscard('${key}')">Undo</button>` : ''}
        </div>
      </div>`;
}

function _mgTextPane() {
    const dev = _mgTextDevice();
    if (!dev) return '';

    const sibs = _mgTextSiblings();
    const shared = sibs.length > 1
        ? `<div class="mg-tshared">
             <b>Shared wording.</b> ${dev.category} keeps one set of text for ${sibs.length} items —
             ${sibs.map(s => _mgEsc(s.device)).join(', ')}. Anything you change here changes all of them.
           </div>`
        : '';

    const rebuttals = _mgTextRows('rebuttals');
    const newReb = { id: 'new:reb', name: '', say: '', why: '', conds: [] };

    return `<section class="mg-adm-sec">
        <div class="mg-adm-sech"><h4>What it says</h4>
          <span class="mg-adm-sechint">Saved one row at a time &middot; live for every store immediately</span></div>
        <div class="mg-adm-text">
          ${shared}
          <div class="mg-tsecs">${MG_TEXT_SECTIONS.map(_mgHelpSection).join('')}</div>
          <section class="mg-tsec mg-tsec-reb">
            <header class="mg-tsec-h">
              <span class="mg-tsec-ic mg-tsec-talk">${_mgTextIcon('talk')}</span>
              <h4>Rebuttals</h4>
              <span class="mg-tsec-n">${rebuttals.length}</span>
            </header>
            <p class="mg-tsec-hint">What to say when the customer argues the offer. Tag a rebuttal with the grades it fits,
              or leave it untagged so it shows for all of them. Open one at a time &mdash; anything you've typed is kept while it's shut.</p>
            ${rebuttals.length
              ? `<div class="mg-raccs">${rebuttals.map(r => _mgRebuttalBar(r)).join('')}</div>`
              : '<div class="mg-adm-none">No rebuttals for this item yet.</div>'}
            <div class="mg-radd">${_mgRebuttalBar(newReb)}</div>
          </section>
        </div>
      </section>`;
}

function _mgRenderAdmin(body) {
    const dev = _mgAdminDevice();
    // One transparent layer behind whichever menu is open, so clicking anywhere
    // off it closes it. Sits under both (z-index 30) and above everything else.
    const dismiss = (_mgAdmin.pickOpen || _mgAdmin.cell)
        ? '<div class="mg-dismiss" onclick="mgAdminDismiss()"></div>' : '';
    body.innerHTML = `<div class="mg-adm">
        ${dismiss}
        ${_mgAdminHead()}
        ${dev
          ? `<p class="mg-adm-lead">Everything this item pays and everything it tells your buyers, on one screen.
               Cell moves are queued and saved together; wording saves a row at a time.</p>
             ${_mgAdminNumbers()}
             ${_mgTextPane()}`
          : `<p class="mg-adm-lead">Pick an item to edit what it pays and what it tells your buyers.</p>
             <div class="mg-wait mg-wait-lad">
               <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
               <span><b>Pick an item</b> to get started.</span>
             </div>`}
      </div>`;

    // Open the list on the item you're already editing, not on Accessories.
    // scrollTop rather than scrollIntoView so the page behind never moves.
    if (_mgAdmin.pickOpen) {
        const menu = body.querySelector('.mg-picker-menu');
        const on = menu && menu.querySelector('.mg-picker-opt.on');
        if (on) menu.scrollTop = Math.max(0, on.offsetTop - 64);
    }
}

// Detects the operations page and opens the requested sub-tab (defaults to
// call backs, or honors a #callbacks / #b2b deep-link). Safe no-op elsewhere.
// A tab can be hidden by its role gate or a Feature Access override, so never
// land on one the user can't see -- fall back to the first visible tab.
function initOperations() {
    if (!document.querySelector('.ops-wrap')) return;
    const hash = (window.location.hash || '').replace('#', '');
    // #b2b-sign-<dealId> is the B2B signing QR: open the B2B tab, and park the
    // id for b2bLoad() to act on once the deals are actually here. The deal
    // cannot be looked up yet -- this runs before the first fetch.
    const sign = hash.match(/^b2b-sign-([A-Za-z0-9-]{6,})$/);
    if (sign) _b2bPendingSign = sign[1];
    let initial = sign ? 'b2b'
        : ['marginguide', 'callbacks', 'b2b', 'ebay'].includes(hash) ? hash : 'ebay';
    const tabVisible = id => { const b = document.getElementById(id); return !!b && b.style.display !== 'none' && !b.hidden; };
    if (!tabVisible('ops-tab-' + initial)) {
        const firstVisible = Array.from(document.querySelectorAll('[id^="ops-tab-"]'))
            .find(b => b.style.display !== 'none' && !b.hidden);
        if (firstVisible) initial = firstVisible.id.replace('ops-tab-', '');
    }
    switchOperationsTab(initial);
}

function _kpiStartEdit(periodDate) {
    if (_kpiEditingPeriod === periodDate) return;
    _kpiEditingPeriod = periodDate;
    if (_kpiCurrentTab === 'weekly') _kpiRenderWeekly(_kpiPeriodsData);
    else _kpiRenderMonthly(_kpiPeriodsData);
}

function _kpiCancelEdit() {
    _kpiEditingPeriod = null;
    _kpiStripUnsavedSelfRows();
    if (_kpiCurrentTab === 'weekly') _kpiRenderWeekly(_kpiPeriodsData);
    else _kpiRenderMonthly(_kpiPeriodsData);
}

async function _kpiSavePeriod(periodDate) {
    // Mirror the load/render store resolution (DM/CEO picker → MSM routed store →
    // manager's own store) so the save always targets the store on screen.
    const store = _kpiResolveStore();
    const pin   = sessionStorage.getItem('speeksUserPin');
    if (!store || !pin) return;
    const pk     = periodDate.replace(/-/g, '');
    const period = _kpiPeriodsData.find(function(p) { return p.period_end_date === periodDate; });
    if (!period) return;
    const saveBtn = document.getElementById('kpiSaveBtn');
    if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Saving…'; }

    let failed = 0, saved = 0;
    const failedNames = [];
    try {
        for (let empIdx = 0; empIdx < period.entries.length; empIdx++) {
            const entry   = period.entries[empIdx];
            const reqBody = { store: store, period_type: _kpiCurrentTab, period_end_date: periodDate, employee_name: entry.employee_name };
            // A CLEARED box sends null, it does not go unsent. Omitting it left the
            // column at whatever was there before — so emptying a figure and saving
            // put the old number straight back on the next render, with a green tick
            // claiming it had saved. An empty input is an instruction ("there is no
            // number here"), and the only way to send that is to say it out loud.
            let anyFilled = false;
            _KPI_INPUT_FIELDS.forEach(function(f) {
                const el = document.getElementById('kpi-' + pk + '-' + empIdx + '-' + f);
                // No input on screen for this field — stay silent about it rather
                // than nulling a column the manager was never shown.
                if (!el) return;
                if (el.value === '') { reqBody[f] = null; return; }
                reqBody[f] = _KPI_INT_FIELDS.has(f) ? parseInt(el.value) : parseFloat(el.value);
                anyFilled = true;
            });
            if (!anyFilled) {
                // Every box on the row is empty. Nobody saved for this person yet
                // means there is nothing to do — most of the roster is this, every
                // save, which is why the row is skipped rather than written blank.
                if (!entry.id) continue;
                // But a row that DOES exist and has been emptied is a delete. The
                // grid has no per-row delete control, so clearing the boxes is the
                // only way to take someone off a period they were entered on by
                // mistake, and it used to be skipped here — leaving the entry sitting
                // in the table looking like it had been removed. Same rule the
                // coaching note beside it already follows: emptied means gone.
                reqBody.action = 'delete_entry';
            }
            try {
                const resp   = await _kpiPostEntry(reqBody, pin);
                const result = await resp.json();
                if (!resp.ok) throw new Error(result.error || 'Save failed');
                period.entries[empIdx] = result.entry;
                saved++;
                const s = document.getElementById('kpiS-' + pk + '-' + empIdx);
                if (s) { s.textContent = '✓'; s.style.color = '#16a34a'; s.title = 'Saved'; }
            } catch(e) {
                failed++;
                failedNames.push(entry.employee_name);
                const s = document.getElementById('kpiS-' + pk + '-' + empIdx);
                if (s) { s.textContent = '✗'; s.style.color = 'var(--red-alert)'; s.title = String(e.message); }
            }
        }
    } finally {
        // On the happy path the button is replaced wholesale when _kpiLoadAll
        // re-renders the grid, so nothing here used to reset it. That left one
        // way out: if anything threw — or the reload failed — the button stayed
        // disabled on "Saving…" forever and the only escape was a refresh, which
        // threw away everything typed. Always hand the button back.
        const btn = document.getElementById('kpiSaveBtn');
        if (btn) { btn.disabled = false; btn.textContent = 'Save'; }
    }

    if (failed) {
        // Stay in edit mode and keep what is on screen. Reloading here would pull
        // the grid back from the server and silently discard every row that did
        // not save — the manager would watch their numbers vanish.
        alert(failed + ' row' + (failed === 1 ? '' : 's') + ' could not be saved ('
            + failedNames.join(', ') + ').\n\n'
            + (saved ? saved + ' saved successfully. ' : '')
            + 'Your entries are still on screen — press Save again to retry.');
        return;
    }

    _kpiEditingPeriod = null;
    await _kpiLoadAll(_kpiCurrentTab);
}

// One KPI row POST with a hard timeout. fetch() has no default timeout, so a
// dropped connection mid-request left the save hanging indefinitely — the
// "perpetual saving" the managers hit. An abort surfaces as a normal row
// failure, which now keeps the typed values instead of discarding them.
function _kpiPostEntry(reqBody, pin, ms) {
    const ctl = typeof AbortController === 'function' ? new AbortController() : null;
    const timer = ctl ? setTimeout(() => ctl.abort(), ms || 20000) : null;
    return fetch(KPI_MANAGE_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-user-pin': pin },
        body: JSON.stringify(reqBody),
        signal: ctl ? ctl.signal : undefined,
    }).catch(err => {
        throw new Error(err && err.name === 'AbortError'
            ? 'Timed out — check your connection and press Save again.' : (err.message || 'Network error'));
    }).finally(() => { if (timer) clearTimeout(timer); });
}

function _kpiGetThisSunday() {
    const d = new Date(); d.setHours(0,0,0,0);
    const day = d.getDay(); d.setDate(d.getDate() + (day === 0 ? 0 : 7 - day));
    return d.toISOString().slice(0,10);
}
function _kpiGetLastDayOfMonth() {
    const d = new Date();
    return new Date(d.getFullYear(), d.getMonth()+1, 0).toISOString().slice(0,10);
}


// --- 12. MODULE: HUB DATA & LIVE DASHBOARDS ---

async function fetchHubData() {
    try {
        const response = await fetch(`${HUB_URL}?v=${Date.now()}`);
        const freshData = await response.json();

        hubDataCache = freshData;

        // Used to be gated on #bs-buy-val, which the Buying & Sales tab owned and
        // took with it. renderBuyingSales still fills the Command Center's
        // "Updated as of" stamp and the CEO rings, and every write it makes is
        // element-guarded, so it is now simply called.
        renderBuyingSales();
        // The Live Dashboard's buying half reads hubDataCache directly, and the two
        // feeds arrive independently — whichever lands second has to repaint, or
        // the block sits on "Syncing the buying sheet" until the next sale.
        if (typeof renderLiveDashboard === 'function') renderLiveDashboard();
        renderMonthlyGoalsBanner();
        renderDistrictGoals();

        // Render Live Data globally (Fixes CEO Rings)
        renderLiveData(hubDataCache);

        // Let the Hub power the Leaderboard automatically!
        if (hubDataCache.leaderboard) {
            cachedLeaderboardData = hubDataCache.leaderboard;
            feedLeaderboardToTicker(cachedLeaderboardData);
            // "Updated as of" stamp — set on data refresh only (not on the Rev/GP
            // toggle, which also calls drawLeaderboard), mirroring the Buying &
            // Sales / DM command-center last-updated behaviour.
            const _lbUpd = document.getElementById('lb-last-updated');
            if (_lbUpd) _lbUpd.innerText = new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
            if (document.getElementById('lb-wrapper')) drawLeaderboard();
        } else if (document.getElementById('lb-wrapper')) {
            document.getElementById('lb-wrapper').innerHTML = '<div class="status-message" style="color:var(--red-alert);">Please Deploy "New Version" of Hub App Script!</div>';
        }
        _tickerSourceDone('hub');
    } catch(e) {
        console.error("Hub Sync Failed", e);
        // Delay so a concurrent fetchHubData call (syncAllData vs initDashboardData race)
        // has time to succeed and set the leaderboard before the ticker starts.
        setTimeout(() => _tickerSourceDone('hub'), 2000);
    }
}

function renderBuyingSales() {
    if (!hubDataCache) return; 
    
    const storeSelect = document.getElementById('bsStoreSelect');
    const store = storeSelect ? storeSelect.value.toLowerCase() : 'ovl'; 
    if (!store) return;

    // --- BUYING SIDE MATH ---
    let bV = parseNum(hubDataCache[`${store}BuyVal`]);
    let bP = parseNum(hubDataCache[`${store}BuyProj`]);
    let mN = parseNum(hubDataCache[`${store}BuyMargin`]);
    
    if (String(hubDataCache[`${store}BuyMargin`]).includes('%') === false && mN > 0 && mN <= 1.5) {
        mN = mN * 100;
    }

    document.querySelectorAll('#bs-buy-val').forEach(el => el.innerText = `$${Math.round(bV).toLocaleString()}`);
    document.querySelectorAll('#bs-buy-proj').forEach(el => el.innerText = `$${Math.round(bP).toLocaleString()}`);
    // Airy pace bar: how much of the projected month-end buy value is already purchased.
    document.querySelectorAll('#bs-pace-fill').forEach(fill => {
        const pace = bP > 0 ? Math.max(0, Math.min(100, (bV / bP) * 100)) : 0;
        fill.style.width = pace.toFixed(1) + '%';
    });
    document.querySelectorAll('#bs-buy-margin').forEach(el => {
        el.innerText = mN.toFixed(1) + '%';
        el.className = mN > 0 && mN < 51 ? 'delta-badge delta-neg' : 'delta-badge delta-pos';
    });

    // --- SALES SIDE MATH ---
    let p = parseNum(hubDataCache[`${store}Pct`]); 
    p = Math.round(p > 0 && p <= 1 && !String(hubDataCache[`${store}Pct`]).includes('%') ? p * 100 : p);
    
    const goalAmt = parseNum(hubDataCache[`${store}Goal`]);
    document.querySelectorAll('#bs-pct').forEach(el => el.innerText = p + '%');
    document.querySelectorAll('#bs-goal').forEach(el => el.innerText = `$${Math.round(goalAmt).toLocaleString()}`);
    document.querySelectorAll('#bs-t-gp').forEach(el => el.innerText = `$${Math.round(parseNum(hubDataCache[`${store}TrackGP`])).toLocaleString()}`);

    // GP banked so far. Worth stating outright because the ring and #bs-pct are
    // TRACKING attainment (TrackGP / Goal) — a store reading 99% up there is being
    // told where the month is HEADED, not where it is. No "% of goal" sub-line: the
    // ring directly above already reads as attainment, so it only added noise.
    const gpNow = parseNum(hubDataCache[`${store}GP`]);
    document.querySelectorAll('#bs-gp').forEach(el => el.innerText = `$${Math.round(gpNow).toLocaleString()}`);
    
    document.querySelectorAll('#bs-bar').forEach(bar => {
        bar.style.strokeDashoffset = 402 - (Math.min(p, 100)/100) * 402;
        bar.style.stroke = p < 100 ? "#dc2626" : "#1f9d57";
    });

    // --- SELLING MARGIN MATH ---
    let sellMarginNum = 0;
    const rev = parseNum(hubDataCache[`${store}Rev`]);
    const gp = parseNum(hubDataCache[`${store}GP`]);
    
    if (hubDataCache[`${store}SellMargin`]) {
        let smRaw = parseNum(hubDataCache[`${store}SellMargin`]);
        sellMarginNum = (!String(hubDataCache[`${store}SellMargin`]).includes('%') && smRaw > 0 && smRaw <= 1.5) ? (smRaw * 100) : smRaw;
    } else if (rev > 0) {
        sellMarginNum = (gp / rev) * 100;
    }
    
    document.querySelectorAll('#bs-sell-margin').forEach(smb => {
        smb.innerText = sellMarginNum.toFixed(1) + '%';
        smb.className = sellMarginNum >= 55.0 ? 'delta-badge delta-pos' : 'delta-badge delta-neg';
    });

    document.querySelectorAll('#bs-rev').forEach(el => el.innerText = `$${Math.round(rev).toLocaleString()}`);

    const bsDateEl = document.getElementById('bs-last-updated');
    if (bsDateEl) {
        bsDateEl.innerText = hubDataCache[`${store}BuyDate`] || '—';
    }

    // --- Command Center: plain-text margin strip tiles + header stamp + pace dates ---
    document.querySelectorAll('#cc-buy-margin').forEach(el => {
        el.innerText = mN.toFixed(1) + '%';
        el.classList.toggle('bad', mN > 0 && mN < 51);
        el.classList.toggle('good', !(mN > 0 && mN < 51));
    });
    document.querySelectorAll('#cc-sell-margin').forEach(el => {
        el.innerText = sellMarginNum.toFixed(1) + '%';
        el.classList.toggle('bad', sellMarginNum < 55.0);
        el.classList.toggle('good', sellMarginNum >= 55.0);
    });
    const _buyDate = hubDataCache[`${store}BuyDate`] || '—';
    document.querySelectorAll('#cc-updated').forEach(el => el.innerText = _buyDate);
    document.querySelectorAll('#bs-pace-asof').forEach(el => el.innerText = 'as of ' + _buyDate);
    const _mEnd = new Date(); _mEnd.setMonth(_mEnd.getMonth() + 1, 0); // last day of current month
    const _mEndStr = _mEnd.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    document.querySelectorAll('#bs-pace-end').forEach(el => el.innerText = 'month-end · ' + _mEndStr);

    // --- Command Center: Tracking Buying/Revenue strip tiles + collapsed summary + cue ---
    document.querySelectorAll('#cc-track-buy').forEach(el => el.innerText = `$${Math.round(bP).toLocaleString()}`);
    // Tracking Revenue: no stored field — derive as tracking GP implied at the current sell margin.
    const _trackGp = parseNum(hubDataCache[`${store}TrackGP`]);
    const _trackRev = sellMarginNum > 0 ? (_trackGp / (sellMarginNum / 100)) : 0;
    document.querySelectorAll('#cc-track-rev').forEach(el => el.innerText = `$${Math.round(_trackRev).toLocaleString()}`);
    // The three collapsed-summary cells and the "this tab changed" dot went with
    // the Buying & Sales tab. Everything above still runs: the elements it writes
    // to are all queried, so the ones that no longer exist are silent no-ops, and
    // the ones that do — #cc-updated on the Command Center header, and the CEO
    // rings — still need filling.
}

function renderLiveData(d) {
    if (!d) return;
    
    // Update the progress rings for BOTH standard and CEO views safely
    [
        { base: 'ovl', api: 'ovl' },
        { base: 'lee', api: 'lee' },
        { base: 'wsp', api: 'wsp' },
        { base: 'mpl', api: 'mpl' },
        { base: 'bal', api: 'bal' }
    ].forEach(store => {
        // --- Core Math ---
        let p = Math.round(d[`${store.api}Pct`] || 0);
        let goalTxt = `$${Math.round(d[`${store.api}Goal`] || 0).toLocaleString()}`;
        let tGpTxt = `$${Math.round(d[`${store.api}TrackGP`] || 0).toLocaleString()}`;

        // --- Buying Math ---
        let bV = parseNum(d[`${store.api}BuyVal`]);
        let bP = parseNum(d[`${store.api}BuyProj`]);
        let mN = parseNum(d[`${store.api}BuyMargin`]);
        if (String(d[`${store.api}BuyMargin`]).includes('%') === false && mN > 0 && mN <= 1.5) mN = mN * 100;

        // --- Selling Margin Math ---
        let sellMarginNum = 0;
        const rev = parseNum(d[`${store.api}Rev`]);
        const gp = parseNum(d[`${store.api}GP`]);
        if (d[`${store.api}SellMargin`]) {
            let smRaw = parseNum(d[`${store.api}SellMargin`]);
            sellMarginNum = (!String(d[`${store.api}SellMargin`]).includes('%') && smRaw > 0 && smRaw <= 1.5) ? (smRaw * 100) : smRaw;
        } else if (rev > 0) {
            sellMarginNum = (gp / rev) * 100;
        }

        // 1. Update Main Dropdown Rings (Sales Only)
        if(document.getElementById(`${store.api}-pct`)) document.getElementById(`${store.api}-pct`).innerText = p + '%';
        if(document.getElementById(`${store.api}-goal`)) document.getElementById(`${store.api}-goal`).innerText = `Goal: ${goalTxt}`;
        if(document.getElementById(`${store.api}-t-gp`)) document.getElementById(`${store.api}-t-gp`).innerText = tGpTxt;
        
        // 2. Update CEO Rings (Sales)
        if(document.getElementById(`ceo-${store.base}-pct`)) document.getElementById(`ceo-${store.base}-pct`).innerText = p + '%';
        if(document.getElementById(`ceo-${store.base}-goal`)) document.getElementById(`ceo-${store.base}-goal`).innerText = goalTxt;
        if(document.getElementById(`ceo-${store.base}-rev`)) document.getElementById(`ceo-${store.base}-rev`).innerText = `$${Math.round(rev).toLocaleString()}`;
        if(document.getElementById(`ceo-${store.base}-t-gp`)) document.getElementById(`ceo-${store.base}-t-gp`).innerText = tGpTxt;
        if(document.getElementById(`ceo-${store.base}-sell-margin`)) {
            let el = document.getElementById(`ceo-${store.base}-sell-margin`);
            el.innerText = sellMarginNum.toFixed(1) + '%';
            el.className = sellMarginNum >= 55.0 ? 'ceo-badge badge-pos' : 'ceo-badge badge-neg';
        }

        // 3. Update CEO Rings (Buying)
        if(document.getElementById(`ceo-${store.base}-buy-val`)) document.getElementById(`ceo-${store.base}-buy-val`).innerText = `$${Math.round(bV).toLocaleString()}`;
        if(document.getElementById(`ceo-${store.base}-buy-proj`)) document.getElementById(`ceo-${store.base}-buy-proj`).innerText = `$${Math.round(bP).toLocaleString()}`;
        if(document.getElementById(`ceo-${store.base}-buy-margin`)) {
            let el = document.getElementById(`ceo-${store.base}-buy-margin`);
            el.innerText = mN.toFixed(1) + '%';
            el.className = (mN > 0 && mN < 51) ? 'ceo-badge badge-neg' : 'ceo-badge badge-pos';
        }

        // 4. Update the SVG Bars
        let offset = 402 - (Math.min(p, 100)/100)*402;
        let color = p < 100 ? "var(--red-alert)" : "var(--sage-professional)";
        
        setTimeout(() => {
            let mainBar = document.getElementById(`${store.api}-bar`);
            if(mainBar) { mainBar.style.strokeDashoffset = offset; mainBar.style.stroke = color; }
            
            let ceoBar = document.getElementById(`ceo-${store.base}-bar`);
            if(ceoBar) { ceoBar.style.strokeDashoffset = offset; ceoBar.style.stroke = color; }
        }, 50);
    });

    // Update the Revenue and GP Leaderboards
    if (document.getElementById('rev-list')) {
        const sArr = [
            {n:'OVL', r:d.ovlRev, g:d.ovlGP}, 
            {n:'LEE', r:d.leeRev, g:d.leeGP}, 
            {n:'WSP', r:d.wspRev, g:d.wspGP}
        ];
        
        const buildLbRow = (s, i, val) => `
            <div class="lb-row">
                <div class="lb-rank ${i === 0 ? 'lb-gold' : ''}">#${i + 1}</div>
                <div class="lb-name">${s.n}</div>
                <div class="lb-val">$${Math.round(val).toLocaleString()}</div>
            </div>`;

        document.getElementById('rev-list').innerHTML = [...sArr].sort((a,b) => b.r - a.r).map((s,i) => buildLbRow(s, i, s.r)).join('');
        document.getElementById('gp-list').innerHTML = [...sArr].sort((a,b) => b.g - a.g).map((s,i) => buildLbRow(s, i, s.g)).join('');
        
        const n = new Date(); 
        const formattedTime = `${n.getHours() % 12 || 12}:${String(n.getMinutes()).padStart(2,'0')} ${n.getHours() >= 12 ? 'PM' : 'AM'}`;
        document.getElementById('lastSyncedText').innerText = `Last Synced: ${formattedTime}`;
    }

    const ceoBsDateEl = document.getElementById('ceo-bs-last-updated');
    if (ceoBsDateEl) {
        ceoBsDateEl.innerText = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
    }
}

// --- 13. MODULE: CHARTS & LEADERBOARDS ---
let mainChartInstance = null;
let leaderboardChartInstance = null;
let currentLeaderboardMetric = 'Revenue'; 
let cachedLeaderboardData = null; 
let currentTimeframe = '4-Week'; 
let currentChartMode = 'averages';
let _rawChartCache = JSON.parse(localStorage.getItem('speeksKpiChartCache')) || {};
// Discard any old CSV-format cache entries (they had array data, not {mode, tf, ...})
let kpiChartCache = (_rawChartCache['4-Week']?.mode && _rawChartCache['Monthly']?.mode) ? _rawChartCache : { '4-Week': null, 'Monthly': null };
let _latestPatchKey = null; // title|date of the most recent patch notes group

function switchPageTab(tab) {
    ['trends', 'records'].forEach(t => { 
        document.getElementById('pane-' + t)?.classList.toggle('active', t === tab); 
        document.getElementById('tab-btn-' + t)?.classList.toggle('active', t === tab); 
    });
    if (tab === 'records') renderRecords();
}

// The chart draws itself on page load, so rendering it proves nothing. Every
// hook below is a CONTROL the reader had to reach for — mode, timeframe, metric,
// leaderboard — which is the only honest evidence anyone looked at it. They all
// report one surface: the question is whether the chart gets used, not which
// button. loadKpiData() is deliberately NOT hooked; init calls it too.
function setChartMode(mode) {
    trackUsage('open', 'chart:home', _usageLabel('chart:home'));
    currentChartMode = mode;
    document.getElementById('btn-chart-avg')?.classList.toggle('active', mode === 'averages');
    document.getElementById('btn-chart-emp')?.classList.toggle('active', mode === 'employees');
    loadKpiData(); 
}

function setTimeframe(t) {
    trackUsage('open', 'chart:home', _usageLabel('chart:home'));
    currentTimeframe = t;
    document.getElementById('btn-4week')?.classList.toggle('active', t === '4-Week'); 
    document.getElementById('btn-monthly')?.classList.toggle('active', t === 'Monthly'); 
    loadKpiData(); 
}

function switchLeaderboardMetric(metric) {
    trackUsage('open', 'chart:home', _usageLabel('chart:home'));
    currentLeaderboardMetric = metric;
    
    const revBtn = document.getElementById('lb-tab-rev');
    const gpBtn = document.getElementById('lb-tab-gp');
    
    if (revBtn && gpBtn) {
        revBtn.classList.toggle('active', metric === 'Revenue');
        revBtn.style.color = metric === 'Revenue' ? 'var(--slate-charcoal)' : '#a0aab2';
        
        gpBtn.classList.toggle('active', metric === 'GP');
        gpBtn.style.color = metric === 'GP' ? 'var(--slate-charcoal)' : '#a0aab2';
    }
    
    drawLeaderboard(); 
}

function loadKpiData() {
    const mSelect = document.getElementById('metricSelector');
    if (!mSelect) return;
    const loader = document.getElementById('chartLoading');
    if (loader) { loader.style.display = 'flex'; loader.innerHTML = '<div class="status-message">Syncing Live Data...</div>'; }
    fetchChartData(currentTimeframe);
}

async function fetchChartData(tf) {
    const loader = document.getElementById('chartLoading');
    if (loader) { loader.style.display = 'flex'; loader.innerHTML = '<div class="status-message">Syncing Data...</div>'; }

    const STORES = ['OVL','LEE','WSP','MPL','BAL'];
    const safeJson = (url) => fetch(url).then(r => r.json()).catch(() => null);

    try {
        let payload;
        if (currentChartMode === 'averages') {
            if (tf === 'Monthly') {
                const results = await Promise.all(STORES.map(s => safeJson(`${MONTHLY_KPI_URL}?store=${s}&v=${Date.now()}`)));
                payload = { mode: 'averages', tf, stores: STORES, results };
            } else {
                const results = await Promise.all(STORES.map(s => safeJson(`${KPI_MANAGE_URL}?store=${s}&period_type=weekly&v=${Date.now()}`)));
                payload = { mode: 'averages', tf, stores: STORES, results };
            }
        } else {
            const store = document.getElementById('dmChartStoreSelector')?.value || sessionStorage.getItem('speeksUserStore') || 'OVL';
            const pt = tf === 'Monthly' ? 'monthly' : 'weekly';
            const result = await safeJson(`${KPI_MANAGE_URL}?store=${store}&period_type=${pt}&v=${Date.now()}`);
            payload = { mode: 'employees', tf, store, result };
        }

        kpiChartCache[tf] = payload;
        try { localStorage.setItem('speeksKpiChartCache', JSON.stringify(kpiChartCache)); } catch(e) {}

        if (currentTimeframe === tf) {
            const mSelect = document.getElementById('metricSelector');
            if (mSelect) renderKpiChart(payload, mSelect.value);
        }
    } catch (e) {
        console.error('fetchChartData error:', e);
        if (loader) loader.innerHTML = '<div class="status-message" style="color:var(--red-alert);">Failed to load chart data.</div>';
    }
}

function syncAllData() {
    try {
        const mSelect = document.getElementById('metricSelector');
        const cached = kpiChartCache && kpiChartCache[currentTimeframe];
        if (cached && cached.mode && mSelect) renderKpiChart(cached, mSelect.value);
    } catch (e) {}

    try {
        if (typeof cachedLeaderboardData !== 'undefined' && cachedLeaderboardData) drawLeaderboard();
    } catch (e) {}

    try {
        if (typeof hubDataCache !== 'undefined' && hubDataCache) renderLiveData(hubDataCache);
    } catch (e) {}

    fetchChartData(currentTimeframe);
    fetchHubData();
    if (typeof loadCMS === 'function') loadCMS();
    if (typeof fetchRecordsData === 'function') fetchRecordsData();
}

