// Mirror #pinInput's length onto the four cells. The input itself is invisible,
// so this is the only thing that shows entry progress.
function _authPaintCells() {
    const input = document.getElementById('pinInput');
    const cells = document.querySelectorAll('#pinCells .pin-cell');
    if (!input || !cells.length) return;
    const len = input.value.length;
    cells.forEach((c, i) => c.classList.toggle('filled', i < len));
}

function handleSignOut() {
    // Same reasoning as the comment tracker below: the aging-claim alert fires once
    // per session, so a fresh login should surface it again. Cleared BEFORE the
    // name is dropped, since the key is scoped to the signing-out user.
    try { sessionStorage.removeItem(_seenAgingKey()); } catch (e) { /* non-fatal */ }

    // Every key the login sets has to be cleared here, plus the comment tracker
    // so store comments pop again next login. speeksUserPin and
    // speeksUserOnboardedAt were previously left behind — and the PIN is sent as
    // the credential on several writes (kpi-manage among them), so the outgoing
    // user's PIN stayed readable in the tab until the next login overwrote it.
    ['speeksUnlocked', 'speeksUserName', 'speeksUserRole', 'speeksUserStore',
     'speeksMultiStore', 'speeksUserPin', 'speeksUserOnboardedAt',
     'speeksSeenCommentKeys', 'speeksConnectFeed'].forEach(function (k) { sessionStorage.removeItem(k); });
    // The SPEEKS Connect feed is held in memory as well as in storage, and
    // sign-out does not always end in a reload.
    if (typeof ecClearFeed === 'function') ecClearFeed();

    // Hide authenticated chrome and close any open panels BEFORE reloading, so the
    // teardown/fetch window can't briefly paint role-gated controls (e.g. the green
    // ticker toggles) as the layout collapses.
    document.body.classList.remove('is-authenticated');
    // Closes ALL four side panels, clears their nav-toggle active state and runs
    // their stop callbacks. This used to hand-remove `open` from just the checklist
    // and goals panels, which left the tools and audit panels open for the next
    // person and left the checklist/audit sync polls running after sign-out.
    _closeSidePanels();
    closeAllModals();

    // Drop the outgoing user's feed data. Signing back in as someone else on
    // this tab would otherwise flash their announcements and store notes before
    // the new fetches resolve.
    window._samAnnData = [];
    window._samAnnHidden = new Set();
    window._samStoreNotes = [];

    // Sign-out shows the login overlay rather than reloading, so module state
    // outlives it — the Margin Guide's selection has to be dropped by hand or the
    // next person to sign in on this counter machine inherits the last buyer's item
    // and projection.
    if (typeof _mgResetSelection === 'function') _mgResetSelection();
    if (typeof _mgAdmin === 'object' && _mgAdmin) {
        _mgAdmin.open = false; _mgAdmin.deviceId = ''; _mgAdmin.cell = null;
        if (_mgAdmin.pending) _mgAdmin.pending.clear();
    }
    // Same reasoning for half-typed coaching text: it must not be sitting in the
    // editor for whoever signs in next, still attributed to them when saved.
    if (typeof _mgTextDrafts === 'object') _mgTextDrafts = {};

    // Show the real login overlay. It is fixed at inset 0 with z-index 100000,
    // so it covers the authenticated page outright — nothing behind it needs
    // tearing down, and reusing it means the colour can't drift from .auth-page
    // and the dark-theme filter is already accounted for.
    const overlay = document.getElementById('authOverlay');
    if (overlay) {
        // Back to the top BEFORE the overflow lock. Signing out on the dashboard
        // never navigates, so the page keeps whatever scroll position the outgoing
        // user left it at — and since the login overlay is fixed at inset 0 over a
        // scroll-locked body, there is no way to notice. The next person signs in
        // and lands halfway down the page.
        //
        // Order matters: once body overflow is hidden there may be nothing left to
        // scroll, so this has to happen first. _lockedScrollY is zeroed too, or a
        // later unlockScreen() would restore the outgoing user's position.
        window.scrollTo(0, 0);
        document.documentElement.scrollTop = 0;
        _lockedScrollY = 0;
        overlay.style.display = 'flex';
        document.body.style.overflow = 'hidden';
    }
    try { renderActionFeed(); } catch (_) { /* feed may not exist here */ }

    // Sign out ALWAYS hands off to index.html, which on the dashboard means a
    // reload. It used to sign out in place there — instant, but nothing on the
    // page was actually torn down. The feed's alert bubbles and every tool's
    // cached payload are ordinary DOM and module state that outlive an in-place
    // sign-out, so the next person briefly saw the previous person's
    // notifications, and their data on opening a tool, until their own fetches
    // landed. Clearing that by hand means naming every cache in the app and
    // keeping the list current forever; a reload resets all of them at once,
    // including tools added later. The other four pages already paid this page
    // load — the dashboard was the only exception, which is why it was the only
    // page with the glitch. replace() also keeps a signed-out Back button from
    // returning to an authenticated URL.
    //
    // The teardown above still matters: sessionStorage survives a reload, so
    // those removeItem calls are what actually sign the user out, and the rest
    // is a safety net if navigation is ever blocked.
    location.replace('index.html');
}

