// PayMore-style readiness colors: pass ≥80, watch ≥50, behind below.
function _auditPctColor(pct) {
    if (pct >= 80) return 'var(--green-go, #16a34a)';
    if (pct >= 50) return '#d97706';
    return 'var(--red-alert, #dc2626)';
}



// ============================================================================
// 21. MODULE: EMPLOYEE DASHBOARD WIDGETS
// ============================================================================

async function fetchAndRenderEmployeeGoals() {
    const container = document.getElementById('employee-goals-widget-body');
    const dateLabel = document.getElementById('emp-goals-date');
    const pulseDot = document.getElementById('emp-goals-pulse-dot');
    if (!container) return;

    const userName = sessionStorage.getItem('speeksUserName') || '';
    let store = sessionStorage.getItem('speeksUserStore') || 'OVL';
    if (store === 'ALL' || store === 'CORP') store = 'OVL';

    const todayStr = new Date().toLocaleDateString('en-US', { timeZone: 'America/Chicago' });
    const now = new Date();
    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() + (now.getDay() === 0 ? -6 : 1 - now.getDay()));
    startOfWeek.setHours(0,0,0,0);

    const ctTimeString = now.toLocaleString('en-US', { timeZone: 'America/Chicago', hour: 'numeric', hour12: false });
    const hours = parseInt(ctTimeString, 10);
    
    if (pulseDot) {
        pulseDot.style.display = (hours === 9 || hours === 19) ? 'block' : 'none';
    }

    if (dateLabel) {
        dateLabel.innerText = now.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
    }

    try {
        const res = await fetch(`${GOALS_API_URL}?store=${store}&v=${Date.now()}`);
        const data = await res.json();
        
        const myRecords = data.filter(r => {
            const dbName = String(r.employee).trim().toLowerCase();
            const sessionName = String(userName).trim().toLowerCase();
            
            if (dbName === sessionName) return true; 
            
            const dbFirstName = dbName.split(' ')[0];
            const sessionFirstName = sessionName.split(' ')[0];
            
            if (dbFirstName.length > 2 && sessionFirstName.length > 2) {
                if (dbFirstName.startsWith(sessionFirstName) || sessionFirstName.startsWith(dbFirstName)) return true;
            }
            return false;
        });
        
        let todayGoal = 0;
        let todayRole = '';
        let dailyStats = {};

        myRecords.forEach(r => {
            const recDate = goalDateObj(r.date);
            const g = parseInt(r.goal) || 0;
            const resVal = parseInt(r.result) || 0;

            if (r.date === todayStr) {
                todayGoal = g;
                if (r.role && r.role !== '-') todayRole = r.role;
            }
            
            if (recDate >= startOfWeek) {
                const daysOfWeek = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
                const dayIdx = (recDate.getDay() + 6) % 7;
                dailyStats[daysOfWeek[dayIdx]] = { goal: g, result: resVal, role: r.role };
            }
        });

        const roleTranslations = { 'B1': 'Buyer 1', 'B2': 'Buyer 2', 'L1': 'Lister 1', 'L2': 'Lister 2', 'OFF': 'Off Today' };
        const displayRole = roleTranslations[todayRole] || todayRole;

        const roleDescriptions = {
            'B1': 'You\'re the lead buyer — first up for every customer who walks through the door. When someone comes in, that\'s your call.',
            'B2': 'You\'re the second buyer in rotation. Hang back and jump in the moment a second customer arrives.',
            'L1': 'Dedicated listing only — no buying, no shipping, no exceptions. Your entire focus today is getting items listed and nothing else.',
            'L2': 'You\'re a primary lister throughout the day, but also serve as the emergency buyer when 4 or more separate customers are in the store at once.',
            'OFF': 'You\'re marked off today — no listing goal. Enjoy the day.'
        };
        const roleDesc = roleDescriptions[todayRole] || '';

        const daysOfWeek = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
        const currentDayIdx = (now.getDay() + 6) % 7;
        
        // Personal weekly goal = sum of THIS person's daily goals, across
        // whatever roles they held each day (not tied to one fixed role).
        let weekGoalTotal = 0;
        Object.values(dailyStats).forEach(d => { weekGoalTotal += (d.goal || 0); });

        // Feed the "Listing Goals" action-menu bar: role + today's goal (+ result for its bar).
        const _todayStats = dailyStats[daysOfWeek[currentDayIdx]] || {};
        window._empGoalToday = todayGoal;
        window._empRoleToday = displayRole;
        window._empResultToday = _todayStats.result || 0;
        if (typeof samRefreshListing === 'function') samRefreshListing();

        let dailyBreakdownHtml = '<div class="emp-pill-container">';

        daysOfWeek.forEach((dName, dIdx) => {
            const stat = dailyStats[dName];
            // Friendly role name for the hover tooltip (e.g. B1 → Buyer 1).
            const dRole = (stat && stat.role && stat.role !== '-') ? (roleTranslations[stat.role] || stat.role) : '';
            if (stat && stat.goal > 0) {
                dailyBreakdownHtml += `<div class="emp-daily-pill pill-goal" title="${dRole ? escapeHtml(dRole) : 'Goal set'}">${dName}: ${stat.goal}</div>`;
            } else if (dIdx <= currentDayIdx) {
                // A role can be set with a 0 goal (a day off, or a closed Sunday) —
                // say which rather than the misleading "No role set".
                const t = _isOffRole(stat && stat.role) ? 'Off — no goal'
                        : (dRole ? `${escapeHtml(dRole)} — no goal (store closed)` : 'No role set');
                dailyBreakdownHtml += `<div class="emp-daily-pill pill-null" title="${t}">${dName}</div>`;
            } else {
                dailyBreakdownHtml += `<div class="emp-daily-pill pill-future">${dName}</div>`;
            }
        });
        dailyBreakdownHtml += '</div>';

        container.innerHTML = `
            <div class="emp-goals-top-row">
                <div class="emp-goal-col">
                    <span class="emp-goal-label">TODAY'S TARGET</span>
                    <span class="emp-goal-value">${todayGoal > 0 ? todayGoal : '-'}</span>
                </div>
                <div class="emp-goal-col emp-goal-col-right">
                    <span class="emp-goal-label">MY ROLE</span>
                    <span class="emp-goal-value">${displayRole || '-'}</span>
                </div>
            </div>

            ${roleDesc ? `<div class="emp-role-description">${roleDesc}</div>` : ''}

            <div class="emp-week-section">
                <div class="emp-week-head">
                    <span class="emp-goal-label">THIS WEEK'S GOALS
                        <span class="goals-info-i" data-tip-title="Your weekly goal" data-tip-desc="The sum of your daily listing goals so far this week — across whatever roles you've had each day.">i</span>
                    </span>
                    <span class="emp-week-total" title="Your goal so far this week">${weekGoalTotal || 0}</span>
                </div>
                ${dailyBreakdownHtml}
            </div>

            <div class="goals-levelup" id="emp-goals-levelup"></div>
        `;

        // Store goal in the header + level-up bar (mirrors the manager widget).
        await fetchStoreTarget(store);
        const empTarget = targetFor(store);
        const empStoreTargetEl = document.getElementById('emp-goals-store-target');
        if (empStoreTargetEl) empStoreTargetEl.innerText = `${empTarget} Listings`;
        const empLuEl = document.getElementById('emp-goals-levelup');
        if (empLuEl) empLuEl.innerHTML = levelUpHtml(weeksFor(store), empTarget);
    } catch (e) {
        container.innerHTML = '<div class="status-message" style="color:var(--red-alert);">Failed to sync goals.</div>';
    }
}

async function fetchAndRenderEmployeeKPIs() {
    const container = document.getElementById('employee-kpi-widget-body');
    const periodLabel = document.getElementById('emp-kpi-period');
    if (!container) return;

    const userName = sessionStorage.getItem('speeksUserName') || '';
    let store = sessionStorage.getItem('speeksUserStore') || 'OVL';
    if (store === 'ALL' || store === 'CORP') store = 'OVL';

    try {
        const response = await fetch(`${WEEKLY_KPI_URL}?store=${store}&v=${Date.now()}`);
        const d = await response.json();

        // New clean JSON format: { employees, store_total, period_label }
        const emps   = d.employees   || [];
        const total  = d.store_total || {};
        const pTxt   = d.period_label || '';

        const fmtBuy = v => v != null ? `$${Math.round(Number(v)).toLocaleString()}` : '';
        const fmtPct = v => v != null ? `${Number(v).toFixed(1)}` : '';
        const fmtN   = v => v != null ? String(Math.round(Number(v))) : '';
        const fmtMin = v => v != null ? `${Number(v).toFixed(1)}` : '';

        let sAvg = {
            buyVal:     fmtBuy(total.buying_value),
            buyMargin:  fmtPct(total.gross_margin_pct),
            customers:  fmtN(total.transaction_count),
            conversion: fmtPct(total.customer_conversion_pct),
            time:       fmtMin(total.avg_transaction_time),
            noDeals:    fmtN(total.no_deal_count),
            listed:     fmtN(total.listed_count),
        };

        const sessionName      = String(userName).trim().toLowerCase();
        const sessionFirstName = sessionName.split(' ')[0];
        const myEntry = emps.find(e => {
            const dbName  = String(e.employee_name).trim().toLowerCase();
            if (dbName === sessionName) return true;
            const dbFirst = dbName.split(' ')[0];
            return dbFirst.length > 2 && sessionFirstName.length > 2 &&
                   (dbFirst.startsWith(sessionFirstName) || sessionFirstName.startsWith(dbFirst));
        });

        let myData = {};
        if (myEntry) {
            myData = {
                buyVal:     fmtBuy(myEntry.buying_value),
                buyMargin:  fmtPct(myEntry.gross_margin_pct),
                customers:  fmtN(myEntry.transaction_count),
                conversion: fmtPct(myEntry.customer_conversion_pct),
                time:       fmtMin(myEntry.avg_transaction_time),
                noDeals:    fmtN(myEntry.no_deal_count),
                listed:     fmtN(myEntry.listed_count),
            };
        }

        if (periodLabel) periodLabel.innerText = pTxt;

        // --- NEW: ROBUST VARIANCE FETCH ---
        let formattedMyVar = '-';
        let formattedStoreVar = '-';
        let varRange = '';
        
        let vData = typeof liveVarianceDataCache !== 'undefined' ? liveVarianceDataCache : null;
        
        // If cache isn't ready yet, force an immediate fetch so we don't load a blank widget
        if (!vData || Object.keys(vData).length === 0) {
            try {
                const vRes = await fetch(`${VARIANCE_API_URL}?v=${Date.now()}`);
                vData = await vRes.json();
                if (typeof liveVarianceDataCache !== 'undefined') liveVarianceDataCache = vData;
            } catch(e) { /* fallback variance unavailable */ }
        }

        if (vData && vData[store]) {
            const sVar = vData[store];
            
            // Safe formatting helper to convert decimal to percentage string
            const safeFormatVar = (val) => {
                let n = parseFloat(String(val).replace(/[^0-9.-]/g, ''));
                if (isNaN(n)) return '-';
                return Math.abs(n) < 0.001 ? '0.00%' : `${n < 0 ? '-' : '+'}${Math.abs(n).toFixed(2)}%`;
            };

            formattedStoreVar = safeFormatVar(sVar.total);
            varRange = formatVarianceRange(sVar.dateFrom, sVar.dateTo);

            const sessionName = String(userName).trim().toLowerCase();
            const sessionFirstName = sessionName.split(' ')[0];
            
            if (sVar.employees) {
                const empVarMatch = sVar.employees.find(e => {
                    const dbName = String(e.name).trim().toLowerCase();
                    if (dbName === sessionName) return true; 
                    const dbFirstName = dbName.split(' ')[0];
                    if (dbFirstName.length > 2 && sessionFirstName.length > 2) {
                        return dbFirstName.startsWith(sessionFirstName) || sessionFirstName.startsWith(dbFirstName);
                    }
                    return false;
                });
                
                if (empVarMatch) {
                    formattedMyVar = safeFormatVar(empVarMatch.val);
                }
            }
        }

        if (Object.keys(myData).length === 0) {
            container.innerHTML = '<div class="status-message">No KPI data found for your user this week.</div>';
            return;
        }

        // Airy KPI tile: quiet label, my value (red if the rule flags it), store context line.
        // Two aligned rows — "Mine" over "Store" — so each metric reads top-to-bottom as a
        // me-vs-store comparison and the tab fills the widget height (matches the chart).
        const _kv = (v, pct) => {
            let s = (v == null || v === '') ? '-' : String(v);
            if (s !== '-' && pct && !s.includes('%')) s += '%';
            return s;
        };
        const _kpiMetrics = [
            { t: 'Buying Value', my: myData.buyVal,    st: sAvg.buyVal,       rule: null,         pct: false, tag: 'total' },
            { t: 'Margin',       my: myData.buyMargin, st: sAvg.buyMargin,    rule: 'margin',     pct: true,  tag: 'avg' },
            { t: 'Conversion',   my: myData.conversion, st: sAvg.conversion,  rule: 'conversion', pct: true,  tag: 'avg' },
            { t: 'Variance',     my: formattedMyVar,   st: formattedStoreVar, rule: 'variance',   pct: false, tag: 'total', note: varRange },
            { t: 'No Deals',     my: myData.noDeals,   st: sAvg.noDeals,      rule: 'nodeals',    pct: false, tag: 'total' },
            { t: 'Trans. Time',  my: myData.time,      st: sAvg.time,         rule: 'time',       pct: false, tag: 'avg' },
            { t: 'Listed Dev.',  my: myData.listed,    st: sAvg.listed,       rule: null,         pct: false, tag: 'total' },
        ];
        const _mineTiles = _kpiMetrics.map(m => {
            const hasVal = m.my != null && m.my !== '' && m.my !== '-';
            const bad = m.rule ? checkRule(m.rule, m.my) : false;      // flagged → red
            const good = !!m.rule && hasVal && !bad;                    // rule met → green
            const cls = bad ? ' bad' : (good ? ' good' : '');
            return `<div class="ekpi-tile"><span class="ekpi-k">${m.t}</span><span class="ekpi-v${cls}">${_kv(m.my, m.pct)}</span></div>`;
        }).join('');
        const _storeTiles = _kpiMetrics.map(m =>
            `<div class="ekpi-tile store"><span class="ekpi-k">${m.t} <span class="ekpi-tag">· ${m.tag}</span></span><span class="ekpi-v">${_kv(m.st, m.pct)}</span>${m.note ? `<span class="ekpi-note">${m.note}</span>` : ''}</div>`
        ).join('');
        container.innerHTML = `
            <div class="ekpi-rowlab"><span class="ekpi-pill me">Mine</span><span class="ekpi-rule"></span></div>
            <div class="ekpi-grid">${_mineTiles}</div>
            <div class="ekpi-rowlab ekpi-rowlab-store"><span class="ekpi-pill st">Store</span><span class="ekpi-rule"></span></div>
            <div class="ekpi-grid">${_storeTiles}</div>
        `;
        // Employee widget "Weekly KPIs updated" dot — fires when a new week's numbers land.
        _ccFlagUpdate('kpis', `${pTxt}|${myData.buyVal}|${myData.conversion}|${myData.listed}|${myData.noDeals}`);
    } catch (e) {
        container.innerHTML = '<div class="status-message" style="color:var(--red-alert);">Failed to sync KPIs.</div>';
    }
}

// ============================================================================
// MODULE: B2B DEALS (operations.html #ops-pane-b2b)
// ----------------------------------------------------------------------------
// A business sells us bulk electronics; we collect them, price them, quote the
// client, and once they accept, the goods are our inventory and get listed.
//
// Seven stages, each with exactly ONE owner -- which is what makes the "Needs
// You" queue derivable from the stage alone rather than from a pile of flags:
//
//   pickup            corp    typed-name sign-off + pickup date
//   pricing_location  corp    route to a store, or CORP
//   pricing           store   itemize and price
//   quote             corp    email it; stays editable while the client haggles
//   listing_location  corp    ONLY when CORP did the pricing
//   listing           store   check off / scan each unit
//   completed         --      terminal        (declined is the other terminal)
//
// Accepting a quote is the hinge: offers freeze into cost, SKUs freeze, and the
// deal routes onward. The edge function enforces every transition; this file
// only decides what to *offer* the user. Backed by `b2b-deals` /
// b2b_clients + b2b_deals + b2b_deal_items.
// ============================================================================

const B2B_STAGES = [
    { key: 'pickup',           label: 'Pickup Sign-Off',  tone: 'warn',   svg: '<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>' },
    { key: 'pricing_location', label: 'Pricing Location', tone: 'info',   svg: '<path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/>' },
    { key: 'pricing',          label: 'Pricing',          tone: 'info',   svg: '<path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/>' },
    { key: 'review',           label: 'Awaiting Approval', tone: 'warn',  svg: '<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>' },
    { key: 'quote',            label: 'Out For Quote',    tone: 'violet', svg: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/>' },
    { key: 'listing_location', label: 'Listing Location', tone: 'warn',   svg: '<path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/>' },
    { key: 'listing',          label: 'Listing',          tone: 'teal',   svg: '<line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/>' },
    { key: 'completed',        label: 'Completed',        tone: 'ok',     svg: '<path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/>' },
    { key: 'declined',         label: 'Declined',         tone: 'crit',    svg: '<circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/>' },
];
const B2B_STAGE      = Object.fromEntries(B2B_STAGES.map(s => [s.key, s]));
// The board is work in flight, so neither terminal stage gets a column. A
// Completed one would also lie about its count: only the recent archive tail
// rides along with the board payload, so it would read as "we have completed 40
// deals" no matter how many there really are. The Completed view knows the true
// total and says so.
const B2B_BOARD      = B2B_STAGES.filter(s => s.key !== 'declined' && s.key !== 'completed').map(s => s.key);
const B2B_LOCATIONS  = [...STORE_CODES, 'CORP'];

// What the owner of each stage is being asked to do.
const B2B_ACTIONS = {
    pickup:           { cta: 'Sign Off Pickup', why: 'Pickup needs signing off',        kind: 'pickup'  },
    pricing_location: { cta: 'Assign Pricing',  why: 'Needs somewhere to be priced',    kind: 'assign'  },
    pricing:          { cta: 'Price Items',     why: 'Itemize and price the pickup',    kind: 'pricing' },
    review:           { cta: 'Review & Send',   why: 'Priced — needs approving and sending', kind: 'quote' },
    quote:            { cta: 'Open Quote',      why: 'Out with the client',             kind: 'quote'   },
    listing_location: { cta: 'Assign Listing',  why: 'Accepted — pick a listing store', kind: 'listloc' },
    listing:          { cta: 'Open Listing',    why: 'List the items for resale',       kind: 'listing' },
};

// How the goods got here. The pipeline is identical either way -- same stages,
// same gates, same signature rule (see migration 0038) -- so everything below is
// vocabulary plus which questions the intake screen still has to ask.
//
// A walk-in knows two of the three intake facts before anyone types anything:
// the date is today, and the person who received the goods is the person signing
// for them. Only a collection run has a hand-off worth recording, because only a
// collection run has two ends to it.
//
// What a walk-in does NOT skip is the signature and the name of whoever released
// the items. The client is standing at the counter, which makes that the easiest
// signature we will ever collect and the exact moment their property becomes
// ours to hold -- which is the thing the signature is evidence of.
const B2B_INTAKE = {
    pickup: {
        key:   'pickup',
        stage: 'Pickup Sign-Off',
        title: 'Pickup Sign-Off',
        sub:   'Record what was collected and have the client acknowledge it.',
        cta:   'Sign Off Pickup',
        why:   'Pickup needs signing off',
        go:    'Sign &amp; Mark Picked Up',
        was:   'Picked up',
        items: 'Items Picked Up',
        hint:  'A general description is enough here — the itemized list comes later, at pricing.',
        ack:   'The client confirms the items above were collected by SPEEKS Technology on the date shown.',
    },
    walkin: {
        key:   'walkin',
        stage: 'Walk-In Intake',
        title: 'Walk-In Intake',
        sub:   'They brought it to the counter. Record what came in and have them acknowledge it.',
        cta:   'Sign Off Intake',
        why:   'Walk-in needs signing off',
        go:    'Sign &amp; Take It In',
        was:   'Brought in',
        items: 'What They Brought In',
        hint:  'A general description is enough here — the itemized list comes later, at pricing.',
        ack:   'The client confirms the items above were left with SPEEKS Technology today.',
    },
};
// Anything that isn't explicitly a walk-in is a pickup, which is what every deal
// created before 0038 is and what the column defaults to.
function _b2bIntake(deal) { return B2B_INTAKE[deal?.intake_kind === 'walkin' ? 'walkin' : 'pickup']; }
// B2B_ACTIONS is keyed by stage alone, which is right at every stage but pickup
// -- there the wording depends on how the goods arrived, not on where they are.
function _b2bActionWords(deal, a) {
    if (!a || deal.stage !== 'pickup') return a;
    const i = _b2bIntake(deal);
    return { ...a, cta: i.cta, why: i.why };
}

// PRE-EVALUATIONS
// ---------------
// A client wants a number before we drive out: we price a list they describe,
// and if they accept, that priced list becomes a deal with every line already
// filled in. It is the pricing half of a deal, standing on its own, with no
// goods and therefore no pickup, no SKUs and no serials.
//
// Statuses mirror the deal's own shape closely enough to be learnable at a
// glance and no further -- there is deliberately no separate approval step,
// because sending IS the approval, exactly as it is on a quote.
const B2B_PREVAL_STATUSES = [
    { key: 'draft',     label: 'Draft',        tone: 'neu',    why: 'Still being priced' },
    { key: 'sent',      label: 'With Client',  tone: 'violet', why: 'Waiting on their answer' },
    { key: 'accepted',  label: 'Accepted',     tone: 'ok',     why: 'Ready to become a deal' },
    { key: 'converted', label: 'Converted',    tone: 'info',   why: 'Became a deal' },
    { key: 'declined',  label: 'Declined',     tone: 'crit',   why: 'They passed' },
];
const B2B_PREVAL_STATUS = Object.fromEntries(B2B_PREVAL_STATUSES.map(x => [x.key, x]));
// While the lines may still be edited. They freeze at 'accepted' on purpose:
// changing a figure a client has agreed to and then converting would produce a
// deal built on numbers they never saw.
const B2B_PREVAL_OPEN = ['draft', 'sent'];

const B2B_CORP_ROLES   = ['district manager', 'ceo', 'mocd'];
const B2B_ACCEPT_ROLES = ['ceo', 'mocd', 'district manager'];   // may lock a quote
const B2B_STORE_ROLES  = ['manager', 'owner (manager)', 'owner manager', 'assistant manager'];
// 'For Parts' was renamed to 'Broken' -- same meaning, plainer word. It is gone
// from the picker but still recognised by the reason gate and the tone maps
// below: existing rows were migrated, and a row saved in the window between
// this shipping and that running would otherwise stop asking for a reason,
// silently. Same treatment the retired laptop/desktop item types get.
const B2B_CONDITIONS   = ['New', 'Like New', 'Good', 'Fair', 'Broken'];
const B2B_COND_LEGACY  = ['For Parts'];
// Preset client-facing note tags. Joined with '; ' rather than ',' so a typed
// note containing a comma doesn't get re-parsed into phantom tags on reload.
const B2B_NOTE_TAGS = ['Cracked', 'LCD Damage', 'No RAM', 'No HDD', 'Non-functional',
                       'iCloud Locked', 'Scratched', 'Body Damage', 'Missing Charger'];

// What kind of thing a line is, and which specs that kind carries. A machine
// can't be priced without knowing what's inside it; a box of cables has nothing
// to describe. Mirrors SPECS_FOR in the edge function and the CHECK on the
// table -- all three have to agree or a save fails on the round trip.
// ADDING AN ITEM TYPE
// -------------------
// Item types live in three places that must agree, or a save fails on the round
// trip: (1) here -- B2B_ITEM_TYPES (the picker) + B2B_SPECS_FOR (its spec set);
// (2) the b2b-deals edge function -- ITEM_TYPES + SPECS_FOR; (3) the table's
// b2b_deal_items_item_type_check CHECK constraint. Add the key to all three and
// nothing else needs to change. A type's required specs (req:true below) render
// as inline grid columns; optional specs live in the ⋯ detail sheet.
//
// 'laptop'/'desktop' were merged into 'computer'; the legacy keys stay mapped in
// B2B_SPECS_FOR only so any pre-merge row still renders its specs.
const B2B_ITEM_TYPES = [
    { key: 'computer', label: 'Computer' },
    { key: 'other',    label: 'Other'    },
];
// `pick` is a suggestion list, not a constraint -- these render as <datalist>,
// which is a dropdown you can also type past. A hard <select> was the wrong
// answer here: the field has to stay open to whatever actually walks in, and
// the CHECK on the table is a length limit, not an enum.
//
// The lists come from what the live data already shows people typing. Storage
// held "NO STORAGE" and battery health held "BAD" and "Fair" alongside
// percentages, which is the drift this is meant to stop: one obvious option to
// click beats three spellings of the same idea.
const B2B_SPEC_FIELDS = [
    { key: 'cpu',            label: 'CPU',            req: true,  hint: 'i5-1135G7',
      pick: ['i3', 'i5', 'i7', 'i9', 'Ryzen 3', 'Ryzen 5', 'Ryzen 7', 'Ryzen 9',
             'Apple M1', 'Apple M2', 'Apple M3', 'Celeron', 'Pentium', 'Xeon'] },
    { key: 'ram',            label: 'RAM',            req: true,  hint: '16GB',
      pick: ['4GB', '8GB', '12GB', '16GB', '24GB', '32GB', '64GB', 'NO RAM'] },
    // Ethan: an SSD and an HDD of the same size are not worth the same, so the
    // distinction has to be sayable. Kept in this field rather than given a
    // column of its own -- the sheet is already nineteen wide and the ask was
    // for fewer cramped columns, not more -- but every suggestion now names the
    // drive type, so the bare sizes stop being the path of least resistance.
    { key: 'storage',        label: 'Storage',        req: true,  hint: '512GB SSD',
      pick: ['128GB SSD', '256GB SSD', '512GB SSD', '1TB SSD', '2TB SSD',
             '256GB NVMe', '512GB NVMe', '1TB NVMe', '2TB NVMe',
             '500GB HDD', '1TB HDD', '2TB HDD',
             '64GB eMMC', '128GB eMMC', 'NO STORAGE'] },
    { key: 'gpu',            label: 'GPU',            req: false, hint: 'Iris Xe / RTX 3060',
      pick: ['Integrated', 'Iris Xe', 'UHD Graphics', 'Radeon', 'GTX 1650',
             'RTX 3050', 'RTX 3060', 'RTX 4060', 'Quadro'] },
    { key: 'battery_health', label: 'Battery health', req: false, hint: '88%',
      pick: ['Good', 'Fair', 'Poor', 'Bad', 'No battery', 'Not tested'] },
];
// Brands that keep coming back. Same rule: a suggestion, never a restriction.
const B2B_BRANDS = ['Acer', 'Apple', 'ASUS', 'Dell', 'HP', 'Lenovo', 'LG', 'Microsoft',
    'MSI', 'Razer', 'Samsung', 'Sony', 'Thinkpad', 'Toshiba'];

// One <datalist> per suggestion set, mounted once per grid rather than once per
// row: thirty lines would otherwise repeat the same options thirty times.
function _b2bDatalists() {
    const list = (id, opts) =>
        `<datalist id="${id}">${opts.map(o => `<option value="${escapeHtml(o)}"></option>`).join('')}</datalist>`;
    return list('b2bdl-make', B2B_BRANDS)
        + B2B_SPEC_FIELDS.filter(f => f.pick).map(f => list(`b2bdl-${f.key}`, f.pick)).join('');
}
const B2B_SPECS_FOR = {
    computer: ['cpu', 'ram', 'storage', 'gpu', 'battery_health'],
    laptop:   ['cpu', 'ram', 'storage', 'gpu', 'battery_health'],
    desktop:  ['cpu', 'ram', 'storage', 'gpu'],
    other:    [],
};

// What happens to a line. `recycle` is scrap we dispose of; `no_residual` is
// worth nothing to the CLIENT but may still be worth something to us, so it
// keeps a value and can be listed or recycled unit by unit. Conflating the two
// is what the old recycle_only flag got wrong.
const B2B_DISPOSITIONS = [
    { key: 'purchase',    label: 'Purchase',          short: 'Buy',     tone: 'ok',
      hint: 'We pay the client for these.' },
    { key: 'no_residual', label: 'No residual value', short: 'No value', tone: 'info',
      hint: "Not worth enough to pay the client for, but may still be worth listing. "
          + "Price it out, then decide later whether to list it or recycle it." },
    { key: 'recycle',     label: 'Recycle',           short: 'Recycle', tone: 'neu',
      hint: 'Scrap. Disposed of responsibly, never listed.' },
];
const B2B_DISP = Object.fromEntries(B2B_DISPOSITIONS.map(d => [d.key, d]));
// How the pricing spreadsheet's inline disposition picker labels each option --
// spelled out in full ("No Residual Value") rather than the terse chip `short`,
// which stays in use on the card grid where space is tighter.
// "No Residual" rather than the full "No Residual Value": with Ship and
// Margin added, the full string was the single widest thing on the sheet and was
// costing 22px that Qty needed to show a fourth digit. Nothing is lost -- there
// is only one thing it can mean here, the legend under the sheet spells it out
// in full, and the client-facing chip and the printed label both still say
// "No Residual Value".
const _B2B_DISP_SEL = { purchase: 'Purchase', no_residual: 'No Residual', recycle: 'Recycle' };

// The marker that stands in for a serial when a device has none visible. Counts
// as an entry, so a line still satisfies "one per unit".
const B2B_NO_SERIAL = 'NO SERIAL';

let _b2bDeals        = [];
let _b2bClients      = [];
let _b2bView         = 'queue';     // queue | pipeline | finished | clients | overview
let _b2bStoreFilter  = 'ALL';
let _b2bLoading      = false;
let _b2bModalDeal    = null;        // the deal open in the deal modal
let _b2bModalItems   = [];
let _b2bEditingClient = null;
let _b2bCreateClientId = null;      // client chosen in the new-deal modal
let _b2bAssignPick   = null;        // location picked but not yet submitted
let _b2bPrevals      = [];          // pre-evaluations in scope
let _b2bModalPreval  = null;        // the evaluation open in the editor
let _b2bProofs       = [];          // approval evidence on whatever is open

// --- identity -------------------------------------------------------------

function _b2bRole()  { return (sessionStorage.getItem('speeksUserRole')  || '').toLowerCase().trim(); }
function _b2bStore() { return (sessionStorage.getItem('speeksUserStore') || '').toUpperCase().trim(); }
function _b2bUser()  { return sessionStorage.getItem('speeksUserName') || 'Unknown'; }

// A manager can be lent the corp side of B2B (Feature Access -> Delegation ->
// "B2B Deals (DM)") -- same pattern as cap-aging-dm / cap-variance-dm: while
// delegated they wear the corp hat for routing, quoting and listing hand-off.
function _b2bHasCorpDelegation() {
    if (typeof _featureOverrideFor !== 'function') return false;
    const roleClass = 'role-' + _b2bRole().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, '-');
    return _featureOverrideFor('cap-b2b-corp', roleClass, sessionStorage.getItem('speeksUserName') || '') === true;
}
function _b2bIsCorp()    { return B2B_CORP_ROLES.includes(_b2bRole()) || _b2bHasCorpDelegation(); }
function _b2bIsDM()      { return _b2bRole() === 'district manager' || _b2bHasCorpDelegation(); }
// Accepting a quote is deliberately NOT delegable -- it locks the money.
function _b2bCanAccept()  { return B2B_ACCEPT_ROLES.includes(_b2bRole()); }
function _b2bCanClients() { return ['ceo', 'district manager', 'mocd'].includes(_b2bRole()); }
// Raising a deal. Corp has always been able to; a store manager can too, and
// theirs holds at their own store from the moment it exists (see b2bCreateDeal).
// A store role with no store attached is excluded rather than left to fail at
// the server: there is nowhere to put the goods.
//
// Assistant managers are in B2B_STORE_ROLES and so are included -- they already
// price and list their store's pickups, and creating a deal commits less than
// either. Narrowing this to managers alone is a one-line edit here.
function _b2bCanCreate() {
    if (_b2bIsCorp()) return true;
    return B2B_STORE_ROLES.includes(_b2bRole()) && _b2bMyStores().length > 0;
}
// Raising and pricing an evaluation is the same permission as raising a deal:
// the enquiry usually arrives at whoever picks up the phone or is on the counter.
// Sending it, accepting it and converting it are separately gated below.
function _b2bCanPreval() { return _b2bCanCreate(); }
// The stores this user may raise an evaluation for; empty for corp, who raise
// them unscoped.
function _b2bPrevalStore() {
    if (_b2bIsCorp()) return null;
    const mine = _b2bMyStores();
    return mine.length === 1 ? mine[0] : null;
}

// CRM notification setup (cadences + who gets the reach-out emails) is CEO-only.
function _b2bCanCrm() { return _b2bRole() === 'ceo'; }
function _b2bCanOverview(){ return ['ceo', 'district manager'].includes(_b2bRole()); }
// Employees / trainees help PRICE items but never escalate: no submit, no quote,
// no listing/complete, no accept. Pricing-edit only.
function _b2bIsEmployee(){ return ['employee', 'training'].includes(_b2bRole()); }

// The stores this user acts for. An MSM covers both of theirs.
function _b2bMyStores() {
    if (typeof isMultiStoreManager === 'function' && isMultiStoreManager()) {
        return [...MULTISTORE_MANAGER_STORES];
    }
    const s = _b2bStore();
    return STORE_CODES.includes(s) ? [s] : [];
}

// --- scope + ownership ----------------------------------------------------

function _b2bInScope(deal) {
    if (_b2bIsCorp()) return true;
    const mine = _b2bMyStores();
    return mine.includes(deal.pricing_store) || mine.includes(deal.listing_store);
}

// The one action this user owns on this deal right now, or null.
function _b2bActionFor(deal) {
    const st = deal.stage;
    if (st === 'completed' || st === 'declined') return null;
    const mine = _b2bMyStores();

    // Employees/trainees may only help price their own store's pickups — no escalation.
    if (_b2bIsEmployee()) {
        return (st === 'pricing' && mine.includes(deal.pricing_store)) ? B2B_ACTIONS.pricing : null;
    }

    if (st === 'pickup') {
        // A pickup with a store already on it was raised BY that store, so the
        // sign-off is theirs -- corp neither has the client in front of them nor
        // wants every store's walk-in sitting in their queue. Otherwise it is
        // corp's own pickup and reads exactly as it always has. Same shape as
        // the pricing branch below, deliberately: it is the same question.
        if (deal.pricing_store) {
            if (deal.pricing_store === 'CORP') return _b2bIsCorp() ? B2B_ACTIONS.pickup : null;
            if (mine.includes(deal.pricing_store)) return B2B_ACTIONS.pickup;
            return _b2bIsDM() ? B2B_ACTIONS.pickup : null;   // DM can always step in
        }
        return _b2bIsCorp() ? B2B_ACTIONS.pickup : null;
    }
    if (st === 'pricing') {
        // CORP prices its own pickups; everything else belongs to the store.
        if (deal.pricing_store === 'CORP') return _b2bIsCorp() ? B2B_ACTIONS.pricing : null;
        if (mine.includes(deal.pricing_store)) return B2B_ACTIONS.pricing;
        return _b2bIsDM() ? B2B_ACTIONS.pricing : null;   // DM can always step in
    }
    if (st === 'listing') {
        if (mine.includes(deal.listing_store)) return B2B_ACTIONS.listing;
        return _b2bIsDM() ? B2B_ACTIONS.listing : null;
    }
    if (!_b2bIsCorp()) return null;
    // `review` and `quote` used to be one stage with an ad-hoc action literal
    // spliced in here for the unsent half. They are separate stages now, so both
    // are ordinary B2B_ACTIONS lookups.
    return B2B_ACTIONS[st] || null;
}

// What opening the card should show someone with no queued action.
function _b2bClickKind(deal) {
    const a = _b2bActionFor(deal);
    return a ? a.kind : 'view';
}

// A few stages end in a decision with nothing left to fill in. Those get a
// one-click action on the queue card so the common case doesn't need the full
// screen -- each still confirms first, because both are one-way doors.
// Anything needing input (a store, a name, prices) is deliberately absent.
function _b2bQuickAction(d) {
    if (_b2bIsEmployee()) return null;   // employees never escalate from a card
    // `quote` means sent. "Mark Accepted" on a deal still at `review` would be
    // recording a decision from a client who has never seen it -- and it would
    // skip the send, leaving no quote on record at all. The server refuses it
    // too, now that the two states are separate stages.
    if (d.stage === 'quote' && _b2bCanAccept()) {
        return { label: 'Mark Accepted', call: `b2bQuickAccept('${d.id}',this)` };
    }
    if (d.stage === 'listing' && d.total_units > 0 && _b2bOutstanding(d) === 0) {
        return { label: 'Complete Deal', call: `b2bQuickComplete('${d.id}',this)` };
    }
    return null;
}

async function b2bQuickAccept(id, btn) {
    const d = _b2bDealById(id);
    if (!d) return;
    // The board card has no proof panel, so the check reads the rollup the view
    // carries rather than the rows -- same answer, no extra fetch.
    //
    // `proof_count` being undefined means the board came from a server that does
    // not know about evidence yet, which is not the same as a deal having none.
    // Undefined lets it through; zero does not.
    if (d.proof_count !== undefined && !d.approval_waived_by && !Number(d.proof_count)) {
        return _b2bApprovalGate({ approval_waived_by: null });
    }
    const msg = `Accept ${d.client?.company || 'this'} quote at ${_b2bMoney(_b2bNetOffer(d), 2)}?\n\n`
        + 'The offers lock in as our cost and the items become inventory to list. This cannot be undone.';
    if (!confirm(msg)) return;
    try {
        const out = await _b2bBusy(btn, 'Accepting…', () =>
            _b2bSend({ action: 'accept_quote', id, accepted_by: _b2bUser() }));
        await b2bRefresh();
        // A CORP-priced deal still needs a listing store, so carry straight on.
        if (out.next_stage === 'listing_location' && _b2bIsCorp()) b2bOpenDeal('listloc', id);
    } catch (e) {
        alert(`Couldn't accept the quote: ${e.message}`);
    }
}

async function b2bQuickComplete(id, btn) {
    const d = _b2bDealById(id);
    if (!d) return;
    if (!confirm(`Complete ${d.client?.company || 'this deal'}?\n\n`
        + `All ${d.total_units} unit${d.total_units === 1 ? '' : 's'} are listed or recycled, `
        + 'so the deal closes out for record keeping.')) return;
    try {
        await _b2bBusy(btn, 'Completing…', () => _b2bSend({ action: 'complete', id }));
        await b2bRefresh();
    } catch (e) {
        alert(`Couldn't complete the deal: ${e.message}`);
    }
}

// --- formatting -----------------------------------------------------------

function _b2bMoney(n, dp) {
    const d = dp === undefined ? 0 : dp;
    return '$' + (Number(n) || 0).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
}
function _b2bDate(v) {
    if (!v) return '—';
    const d = new Date(String(v).length <= 10 ? v + 'T00:00:00' : v);
    return isNaN(d) ? '—' : d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}
// Client-facing dates are spelled out. The pickup date is how a client is
// asked to identify their quote, since none of our SKUs go out to them.
function _b2bLongDate(v) {
    if (!v) return '';
    const d = new Date(String(v).length <= 10 ? v + 'T00:00:00' : v);
    return isNaN(d) ? '' : d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
}
function _b2bDaysIn(deal) {
    const t = deal.stage_changed_at || deal.updated_at || deal.created_at;
    if (!t) return 0;
    return Math.max(0, Math.floor((Date.now() - new Date(t).getTime()) / 86400000));
}
function _b2bAgeTone(days) { return days >= 7 ? 'crit' : days >= 4 ? 'warn' : 'ok'; }

// The `deal` argument used to matter here for the quote stage, which covered two
// situations told apart by the send count; those are separate stages now. It
// matters again for `pickup`, which covers two situations that are NOT separate
// stages and shouldn't be: a collection run and a walk-in move through the
// pipeline identically, so splitting the stage would double the state machine to
// change one noun. The chip says which one it is; everything else stays shared.
function _b2bStageChip(stage, deal) {
    const s = B2B_STAGE[stage] || { label: stage, tone: 'neu' };
    const label = stage === 'pickup' ? _b2bIntake(deal).stage : s.label;
    return `<span class="b2b-chip b2b-chip-${s.tone}">${escapeHtml(label)}</span>`;
}
function _b2bStoreTag(code) {
    if (!code) return '<span class="b2b-store b2b-store-none">Unassigned</span>';
    if (code === 'CORP') return '<span class="b2b-store b2b-store-corp">CORP</span>';
    return `<span class="b2b-store"><i class="b2b-dot" style="background:${STORE_TINTS[code] || '#94a3b8'}"></i>${escapeHtml(code)}</span>`;
}
// Stroke attributes go inline rather than relying on an ancestor rule: the
// deal modals sit outside .b2b-panel / .cb-panel, so a bare <svg> there renders
// as a filled blob (paths) or nothing at all (lines).
function _b2bIco(svg, cls) {
    return `<svg viewBox="0 0 24 24" class="${cls || ''}" fill="none" stroke="currentColor"`
         + ` stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${svg}</svg>`;
}
// What we actually pay, and what it actually cost us -- the offer (or the cost
// it froze into) less the certified-wipe charge, never below zero.
//
// EVERY summary of a deal's money goes through these. The quote, the approval
// email and the pricing screen all show the net figure, so a board card showing
// the gross would be the same deal wearing two different prices.
//
// net_offer is computed in the view; net cost is derived here from two columns
// the board already returns, which beats adding a column and redeploying, and
// uses the same clamp so the two cannot drift.
const _b2bNetOffer = (d) => Number(d.net_offer ?? Math.max(0,
    (Number(d.total_offer) || 0) - (Number(d.total_wipe_fee) || 0)));
const _b2bNetCost  = (d) => Math.max(0,
    (Number(d.total_cost) || 0) - (Number(d.total_wipe_fee) || 0));

// Units still needing to be listed or recycled out.
function _b2bOutstanding(deal) { return Number(deal.outstanding_units) || 0; }
function _b2bListedPct(deal) {
    const total = Number(deal.total_units) || 0;
    if (!total) return 0;
    return Math.round(((Number(deal.listed_units) + Number(deal.recycled_units)) / total) * 100);
}

// --- data -----------------------------------------------------------------

let _b2bMeta = null;   // { open, archive_shown, archive_total, archive_truncated }

async function _b2bGet(qs) {
    const res = await fetch(`${B2B_URL}?${qs}&v=${Date.now()}`);
    const json = await res.json().catch(() => ({}));
    if (!res.ok || json.success === false) throw new Error(json.error || `Request failed (HTTP ${res.status})`);
    if (json.meta) _b2bMeta = json.meta;
    return json.data || [];
}

// The list view returns the client's columns flat, since a SQL view can't nest.
// Rebuilding the object here keeps every render site reading deal.client.*
// rather than scattering the two shapes through the module.
function _b2bShapeDeal(d) {
    if (d.client) return d;   // already nested, leave it alone
    return {
        ...d,
        client: {
            id: d.client_id, company: d.company, acronym: d.acronym,
            contact: d.contact, contact_email: d.contact_email, contact_phone: d.contact_phone,
        },
    };
}

// Raw POST. Throws on failure and does NOT alert -- callers decide whether a
// failure deserves a blocking alert or a quiet inline rollback.
async function _b2bSend(payload) {
    const res = await fetch(B2B_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ ...payload, role: _b2bRole(), user: _b2bUser() })
    });
    const out = await res.json().catch(() => ({}));
    if (!res.ok || out.success === false) throw new Error(out.error || `Request failed (HTTP ${res.status})`);
    return out;
}

async function _b2bPost(payload, errLabel) {
    try {
        return await _b2bSend(payload);
    } catch (e) {
        alert(`${errLabel}: ${e.message}`);
        throw e;
    }
}

// --- responsiveness -------------------------------------------------------
// Ticking a unit or toggling a tag used to await the round-trip before
// repainting, so every click felt like it hung. These three helpers let the UI
// commit immediately and reconcile afterwards.

// Serialise writes per key so rapid clicks land in the order they were made.
// A delta-based endpoint is order-sensitive: +1 +1 -1 arriving out of order
// gives the wrong count.
const _b2bQueues = {};
// How many writes are in flight for each line. A realtime sync that arrives
// while a save is still travelling would otherwise read the server's older copy
// as the truth and patch our newer one away -- the edit vanishes from the screen
// having genuinely been made, which is close to the worst failure this module
// can have. Counted rather than a boolean: rapid edits queue several deep.
const _b2bInFlight = new Map();
function _b2bBusyLine(id) { return (_b2bInFlight.get(id) || 0) > 0; }

function _b2bEnqueue(key, fn) {
    _b2bInFlight.set(key, (_b2bInFlight.get(key) || 0) + 1);
    const done = () => {
        const n = (_b2bInFlight.get(key) || 1) - 1;
        if (n > 0) _b2bInFlight.set(key, n); else _b2bInFlight.delete(key);
    };
    const prev = _b2bQueues[key] || Promise.resolve();
    const next = prev.then(fn, fn);
    // Cleared on both paths: a failed save still stops being in flight, and
    // leaving the count up would freeze that line's syncing for the session.
    next.then(done, done);
    _b2bQueues[key] = next.catch(() => {});
    return next;
}

// A quiet line in the modal footer. Optimistic rollbacks report here rather
// than through alert(), which would fight the work the user is mid-flow on.
function _b2bSay(msg, bad) {
    const el = document.getElementById('b2bDealMsg');
    if (!el) { if (bad) alert(msg); return; }
    el.textContent = msg || '';
    el.className = 'b2b-msg' + (bad ? ' bad' : msg ? ' ok' : '');
    if (msg) setTimeout(() => { if (el.textContent === msg) { el.textContent = ''; el.className = 'b2b-msg'; } }, 3200);
}

// For the actions that genuinely must confirm before the screen moves on:
// hold the button in a visible working state instead of appearing dead.
async function _b2bBusy(btn, label, fn) {
    if (!btn) return fn();
    const html = btn.innerHTML, wasOff = btn.disabled;
    btn.disabled = true;
    btn.classList.add('is-busy');
    btn.innerHTML = escapeHtml(label);
    try { return await fn(); }
    finally { btn.disabled = wasOff; btn.classList.remove('is-busy'); btn.innerHTML = html; }
}

// Item writes only change what is already on screen in the modal, so the pane
// behind it is refreshed once on close rather than after every edit.
let _b2bDirty = false;
function b2bCloseDeal() {
    closeAllModals();
    // Asking for the full sheet lasts as long as the deal is open and no longer,
    // so the next quote to be approved starts on the calm screen again.
    _b2bReviewFull = false;
    // Back to the default owner of the item editor, so the next screen to open
    // starts from a known state rather than whatever the last one left behind.
    _b2bItemMode = 'deal';
    _b2bModalPreval = null;
    if (_b2bDirty) { _b2bDirty = false; b2bRefresh(); }
}

// A single-store user only pulls their own store; corp and MSMs pull the lot
// and filter in _b2bInScope (the MSM covers two stores, which the API's
// single-store filter can't express).
function _b2bFetchScope() {
    if (_b2bIsCorp()) return 'ALL';
    const mine = _b2bMyStores();
    return mine.length === 1 ? mine[0] : 'ALL';
}

// The client directory, or as much of it as this user has business seeing.
//
// A store manager needs the list to raise a deal at all -- you cannot pick a
// business off a list you were never sent -- but asks with scope=store, which
// comes back as company + acronym + counts and nothing else. Contact details,
// notes and the outreach cadence stay corp's, the same way the board withholds
// them from a store-scoped fetch.
//
// Anyone who can neither create nor manage clients (employees, trainees) still
// fetches nothing at all.
// Evaluations, scoped the same way the board is: corp sees every one, a store
// sees the enquiries it raised. Anyone who cannot raise one fetches nothing.
function _b2bPrevalsFetch(keep) {
    if (!_b2bCanPreval()) return Promise.resolve(keep || []);
    const store = _b2bIsCorp() ? 'ALL' : (_b2bPrevalStore() || 'ALL');
    return _b2bGet(`prevals=1&store=${encodeURIComponent(store)}`);
}

function _b2bClientsFetch(keep) {
    if (_b2bCanClients() || _b2bIsCorp()) return _b2bGet('clients=1');
    if (_b2bCanCreate()) return _b2bGet('clients=1&scope=store');
    return Promise.resolve(keep || []);
}

async function b2bLoad() {
    const body = document.getElementById('b2bBody');
    if (!body) return;
    if (!_b2bLoading) body.innerHTML = '<div class="status-message">Loading B2B Deals…</div>';
    _b2bLoading = true;
    try {
        const [deals, clients, prevals] = await Promise.all([
            _b2bGet(`store=${encodeURIComponent(_b2bFetchScope())}&archive=${_b2bArchiveDepth}`),
            _b2bClientsFetch(),
            _b2bPrevalsFetch(),
        ]);
        _b2bDeals   = deals.map(_b2bShapeDeal);
        _b2bClients = clients;
        _b2bPrevals = prevals;
        b2bRender();
        // A signing QR was scanned. Consume it before opening, so a refresh
        // doesn't reopen the pad over a deal that has since been signed off.
        if (_b2bPendingSign) {
            const id = _b2bPendingSign;
            _b2bPendingSign = null;
            try { history.replaceState(null, '', location.pathname + '#b2b'); } catch (_) {}
            b2bOpenSign(id);
        }
    } catch (e) {
        body.innerHTML = `<div class="status-message" style="color:var(--red-alert);">Couldn't load B2B deals. ${escapeHtml(e.message)}</div>`;
    } finally {
        _b2bLoading = false;
    }
}

// Background refresh after a write -- no spinner, no scroll jump.
async function b2bRefresh() {
    try {
        const [deals, clients, prevals] = await Promise.all([
            _b2bGet(`store=${encodeURIComponent(_b2bFetchScope())}&archive=${_b2bArchiveDepth}`),
            _b2bClientsFetch(_b2bClients),
            _b2bPrevalsFetch(_b2bPrevals),
        ]);
        _b2bDeals = deals.map(_b2bShapeDeal);
        _b2bClients = clients;
        _b2bPrevals = prevals;
        b2bRender();
        if (typeof crmRefreshBadge === 'function') crmRefreshBadge();
    } catch (_) { /* keep what's on screen */ }
}

function _b2bDealById(id) { return _b2bDeals.find(d => d.id === id) || null; }

// Realtime ping handler. Only refreshes when the pane is actually on screen and
// nobody has a deal modal open -- re-rendering underneath someone mid-edit
// would throw away what they were typing.
function _b2bRealtimeRefresh() {
    const pane = document.getElementById('ops-pane-b2b');
    if (!pane || !pane.classList.contains('active') || document.hidden) return;
    if (document.getElementById('b2bCreateModal')?.classList.contains('show')) return;
    // An open deal used to end the function here, so an inbound change was
    // dropped -- and never picked up afterwards either, because b2bCloseDeal
    // only re-fetches when YOU edited something. Two people pricing one pallet
    // were editing divergent snapshots with last-write-wins per field.
    if (document.getElementById('b2bDealModal')?.classList.contains('show')) {
        return _b2bSyncOpenDeal(typeof _rtLastPing === 'object' ? _rtLastPing : null);
    }
    b2bRefresh();
}

// B2B had no poll at all -- unlike Call Backs right next door -- so a browser
// whose socket never connected learned nothing, ever: no board updates and no
// "needs you" bubble. This is the floor under the realtime path, not a
// replacement for it, which is why a minute is frequent enough.
let _b2bSyncInterval = null;
function _startB2bSync() {
    if (_b2bSyncInterval) return;
    _b2bSyncInterval = setInterval(() => {
        const pane = document.getElementById('ops-pane-b2b');
        if (!pane || !pane.classList.contains('active') || document.hidden) return;
        if (document.getElementById('b2bCreateModal')?.classList.contains('show')) return;
        if (document.getElementById('b2bDealModal')?.classList.contains('show')) {
            // No ping to go on, so no deal filter and no author to skip. That
            // distinction matters: passing the last ping here would compare the
            // open deal against whatever happened to move most recently and
            // usually decide there was nothing to do.
            return _b2bSyncOpenDeal(null);
        }
        b2bRefresh();
    }, 60000);
}

// --- live collaborative pricing -------------------------------------------
// Which cell on the sheet holds each field. The cells carry data-k already (the
// responsive layout uses it for labels), so the grid needs no extra markup for
// this -- and a row can be patched value by value instead of being rebuilt,
// which is what makes it possible to update someone's screen while they type.
const _B2B_SYNC_CELL = {
    item_type: 'Type', make: 'Brand', model: 'Model', condition: 'Condition',
    cpu: 'CPU', ram: 'RAM', storage: 'Storage',
    // Both of these got a column of their own in the sheet rework, and this map
    // is what decides whether an incoming change is PATCHED into the cell (and
    // skipped while you are typing in it) or written blindly into the model.
    // Leaving them off the map after giving them cells meant a sync could
    // overwrite what you were typing and not even repaint it -- so the row and
    // the model disagreed, and the next save posted the stale value back.
    battery_health: 'Battery health', client_notes: 'Client Notes',
    quantity: 'Qty', value: 'Value', offer: 'Offer',
    shipping_cost: 'Ship', disposition: 'Handling',
};
const _B2B_SYNC_FIELDS = Object.keys(_B2B_SYNC_CELL);
const _B2B_CELL_FIELD = Object.fromEntries(
    Object.entries(_B2B_SYNC_CELL).map(([field, k]) => [k, field]));

function _b2bCellFor(itemId, field) {
    const row = document.getElementById(`b2bPline-${itemId}`);
    if (!row) return null;
    const k = _B2B_SYNC_CELL[field];
    return k ? row.querySelector(`.b2b-pcell[data-k="${k}"]`) : null;
}

// Remember the caret well enough to put it back after a full rebuild: which
// line, which field, and where in the text. Losing your place mid-price is
// worse than the stale data this is fixing.
function _b2bFocusSpot() {
    const el = document.activeElement;
    const cell = el && el.closest && el.closest('.b2b-pcell');
    const row = cell && cell.closest('.b2b-pline');
    if (!row || !row.id.startsWith('b2bPline-')) return null;
    const k = cell.getAttribute('data-k');
    return {
        id: row.id.slice('b2bPline-'.length),
        k,
        // The half-typed text itself, so a rebuild can hand it back. Without
        // this the caret survives but the words under it do not.
        field: _B2B_CELL_FIELD[k] || null,
        value: el.value,
        start: el.selectionStart, end: el.selectionEnd,
    };
}
function _b2bRestoreFocus(spot) {
    if (!spot) return;
    const row = document.getElementById(`b2bPline-${spot.id}`);
    const el = row && row.querySelector(`.b2b-pcell[data-k="${spot.k}"] input, .b2b-pcell[data-k="${spot.k}"] select`);
    if (!el) return;
    el.focus();
    try { if (spot.start != null) el.setSelectionRange(spot.start, spot.end); } catch (_) { /* selects have no range */ }
}

function _b2bFlash(cell) {
    if (!cell) return;
    cell.classList.remove('b2b-synced');
    void cell.offsetWidth;          // restart the animation on a repeat change
    cell.classList.add('b2b-synced');
    setTimeout(() => cell.classList.remove('b2b-synced'), 1600);
}

// Pull the line items again and fold them into the open sheet.
//
// `ping` is the realtime payload when one prompted this, and null when the
// safety poll did. Only a real ping carries a deal id and an author, so only a
// real ping gets to skip the work.
async function _b2bSyncOpenDeal(ping) {
    const deal = _b2bModalDeal;
    if (!deal) return;

    // The pickup screen has no grid, but it is the one waiting on a phone: the
    // QR is on screen precisely so someone can sign somewhere else. Reopen it so
    // the signature appears without anybody refreshing.
    if (deal.stage === 'pickup' && document.getElementById('b2bSignQR')) {
        if (ping && ping.deal && ping.deal !== deal.id) return;
        await b2bRefresh();
        const fresh = _b2bDealById(deal.id);
        if (fresh && (fresh.signature_path || fresh.signature_skipped_by)) b2bOpenDeal('pickup', deal.id);
        return;
    }

    const grid = document.getElementById('b2bItemGrid');
    if (!grid) return;                  // not a line-item screen; nothing to sync

    ping = ping || {};
    // A write to some other deal costs nothing, and our own echo is ignored
    // outright -- the edge fn broadcasts to every subscriber, sender included.
    if (ping.deal && ping.deal !== deal.id) return;
    if (ping.by && ping.by === _b2bUser()) return;

    let fresh;
    try { fresh = await _b2bGet(`deal_id=${encodeURIComponent(deal.id)}`); }
    catch (_) { return; }               // transient; the poll will come round again

    const who = ping.by ? ` by ${ping.by}` : '';
    const byId = new Map(fresh.map(i => [i.id, i]));
    const sameLines = fresh.length === _b2bModalItems.length
        && _b2bModalItems.every(i => byId.has(i.id));

    if (!sameLines) {
        // A line arrived or went. There is no patching that -- rebuild, but put
        // the caret AND the half-typed text back. Taking the server's copy
        // wholesale would otherwise discard an edit that has not been saved
        // yet, which is the very thing the value-patch path below protects.
        const spot = _b2bFocusSpot();
        _b2bModalItems = fresh;
        if (spot && spot.field) {
            const mine = _b2bModalItems.find(i => i.id === spot.id);
            if (mine) mine[spot.field] = spot.value;
        }
        _b2bRepaintItems();
        _b2bRestoreFocus(spot);
        return _b2bSay(`Line items updated${who}.`);
    }

    // Same lines, but possibly in a different order -- someone dragged the sheet
    // while we had it open. That is not a value change, so the patch loop below
    // would never notice it, and our copy would stay in the old order until the
    // deal was reopened. Reordering is a rebuild, same as a line arriving.
    const freshIds = fresh.map(i => i.id).join(',');
    if (_b2bModalItems.map(i => i.id).join(',') !== freshIds) {
        const spot = _b2bFocusSpot();
        const byLocal = new Map(_b2bModalItems.map(i => [i.id, i]));
        // Keep OUR objects, in THEIR order: a half-typed field is unsaved and
        // must survive a reorder someone else made.
        _b2bModalItems = fresh.map(r => Object.assign(byLocal.get(r.id) || r, { sort_order: r.sort_order }));
        _b2bRepaintItems();
        _b2bRestoreFocus(spot);
        _b2bPaintQuoteDoc();
        return _b2bSay(`Lines were reordered${who}.`);
    }

    const active = document.activeElement;
    let changed = 0;
    _b2bModalItems.forEach(local => {
        const remote = byId.get(local.id);
        if (!remote) return;
        // Leave a line alone entirely while it has a write in flight. The server
        // copy we just fetched predates that write by definition, so every field
        // on it is a candidate for undoing an edit that was genuinely made.
        if (_b2bBusyLine(local.id)) return;
        // ...and while the cursor is anywhere in it. The per-field guard below
        // only protects the ONE input that has focus, which was enough when
        // every other field lived in a popup. The row now carries an expandable
        // panel -- serials, listing info, staff notes, GPU -- and those are
        // inside the row but outside any .b2b-pcell, so a change landing while
        // someone typed in the panel used to overwrite it silently.
        const rowEl = document.getElementById(`b2bPline-${local.id}`);
        if (rowEl && active && rowEl.contains(active)) return;
        _B2B_SYNC_FIELDS.forEach(f => {
            if (String(remote[f] ?? '') === String(local[f] ?? '')) return;
            const cell = _b2bCellFor(local.id, f);
            const input = cell && cell.querySelector('input, select');
            // The one field they are typing in is left alone -- theirs is the
            // newer edit, and it is about to be saved over this anyway.
            if (input && input === active) return;
            local[f] = remote[f];
            if (input) input.value = remote[f] ?? '';
            _b2bFlash(cell);
            changed++;
        });
        // Fields with no cell of their own still have to track, or the next save
        // from this browser would post them back stale.
        //
        // client_notes and battery_health are NOT in this list any more -- they
        // have columns now and go through the guarded patch above, which checks
        // whether you are typing in them and repaints the input. They were left
        // here after the sheet rework and were being overwritten mid-edit.
        //
        // The panel fields (serials, staff_notes, listing_info, gpu) stay here
        // because they have no .b2b-pcell to patch, and they are safe now only
        // because the whole row is skipped while the cursor is inside it.
        ['serials', 'staff_notes', 'listing_info', 'gpu',
         'wipe_required', 'wipe_fee', 'label_printed_qty',
         'listed_qty', 'recycled_qty', 'wiped_qty'].forEach(f => {
            if (String(remote[f] ?? '') !== String(local[f] ?? '')) { local[f] = remote[f]; changed++; }
        });
    });

    if (!changed) return;
    _b2bPaintTotals();
    _b2bPaintQuoteDoc();
    // A field that lives in the row panel has no cell to patch, so if a panel is
    // open its inputs are still showing the old value. Nobody's cursor is in an
    // open panel here -- the guard above returned early if it were -- so a
    // repaint cannot interrupt anyone.
    if (_b2bModalItems.some(_b2bRowIsOpen)) _b2bRepaintItems();
    _b2bSay(`${changed} change${changed === 1 ? '' : 's'} came in${who}.`);
}

// --- render controller ----------------------------------------------------

function b2bSetView(view) {
    if (view === 'clients'  && !_b2bCanClients())  view = 'queue';
    if (view === 'overview' && !_b2bCanOverview()) view = 'queue';
    if (view === 'prevals'  && !_b2bCanPreval())   view = 'queue';
    _b2bView = view;
    b2bRender();
}

function b2bSetStoreFilter(code) { _b2bStoreFilter = code; b2bRender(); }

function b2bRender() {
    const body = document.getElementById('b2bBody');
    if (!body) return;
    if (_b2bView === 'clients'  && !_b2bCanClients())  _b2bView = 'queue';
    if (_b2bView === 'overview' && !_b2bCanOverview()) _b2bView = 'queue';
    if (_b2bView === 'prevals'  && !_b2bCanPreval())   _b2bView = 'queue';

    const scoped = _b2bDeals.filter(_b2bInScope);
    const queue  = scoped.filter(d => _b2bActionFor(d));

    // Header chrome
    document.querySelectorAll('.b2b-view-toggle .mb-view-btn').forEach(b => b.classList.remove('active'));
    const btn = { queue: 'b2bViewQueueBtn', pipeline: 'b2bViewPipelineBtn', finished: 'b2bViewFinishedBtn',
                  clients: 'b2bViewClientsBtn', overview: 'b2bViewOverviewBtn',
                  prevals: 'b2bViewPrevalsBtn' }[_b2bView];
    document.getElementById(btn)?.classList.add('active');

    // Evaluations waiting on somebody. Not folded into the Needs You queue: that
    // queue derives ownership from a deal's stage, and an evaluation has no
    // stage, no store to own it and no pipeline position. A count on the tab is
    // the honest version of the same signal.
    const pvPip = document.getElementById('b2bPrevalPip');
    if (pvPip) {
        const live = _b2bPrevals.filter(v => !['converted', 'declined'].includes(v.status)).length;
        pvPip.textContent = live;
        pvPip.style.display = live ? 'inline-flex' : 'none';
    }

    const pip = document.getElementById('b2bQueuePip');
    if (pip) {
        pip.textContent = queue.length;
        pip.style.display = queue.length ? 'inline-flex' : 'none';
    }
    const chip = document.getElementById('b2bScopeChip');
    if (chip) {
        if (_b2bIsCorp()) {
            chip.textContent = 'District-wide';
            chip.className = 'b2b-scope-chip b2b-scope-corp';
            chip.style.display = 'inline-flex';
        } else {
            const mine = _b2bMyStores();
            chip.textContent = mine.join(' · ') || 'No store';
            chip.className = 'b2b-scope-chip';
            chip.style.display = mine.length ? 'inline-flex' : 'none';
        }
    }
    // Delete Requests red dot: lit for CORP whenever a store is waiting on a
    // deletion. Drawn from the board we already loaded, so it costs nothing.
    const delBadge = document.getElementById('b2bDelReqBadge');
    if (delBadge) {
        const n = _b2bIsCorp() ? _b2bDeleteRequestRows().length : 0;
        delBadge.textContent = n;
        delBadge.style.display = n ? 'inline-flex' : 'none';
    }
    const sub = document.getElementById('b2bSubtitle');
    if (sub) {
        sub.textContent = _b2bIsCorp()
            ? 'Bulk business deals across every store, from pickup through listing.'
            : _b2bCanCreate()
                ? "Your store's B2B deals — raise them, price them, then list them."
                : "Your store's B2B deals — price them, then list them.";
    }

    if (_b2bView === 'pipeline')      body.innerHTML = _b2bRenderPipeline(scoped);
    else if (_b2bView === 'prevals')  body.innerHTML = _b2bRenderPrevals();
    else if (_b2bView === 'finished') body.innerHTML = _b2bRenderFinished(scoped);
    else if (_b2bView === 'clients')  body.innerHTML = _b2bRenderClients();
    else if (_b2bView === 'overview') body.innerHTML = _b2bRenderOverview(scoped);
    else                              body.innerHTML = _b2bRenderQueue(scoped, queue);
}

// --- view: Needs You ------------------------------------------------------

function _b2bRenderQueue(scoped, queue) {
    const rest = scoped.filter(d => !_b2bActionFor(d) && d.stage !== 'completed' && d.stage !== 'declined');

    const cards = queue.length ? queue.map(d => {
        const a     = _b2bActionWords(d, _b2bActionFor(d));
        const quick = _b2bQuickAction(d);
        const days  = _b2bDaysIn(d);
        const meta = [
            d.total_units ? `${d.total_units} unit${d.total_units === 1 ? '' : 's'}` : null,
            d.total_offer ? `${_b2bMoney(_b2bNetOffer(d))} offer` : null,
            d.pickup_date ? `${_b2bIntake(d).was} ${_b2bDate(d.pickup_date)}` : null,
        ].filter(Boolean).map(t => `<span>${escapeHtml(t)}</span>`).join('');
        const bar = (d.stage === 'listing')
            ? `<div class="b2b-q-bar"><div class="b2b-pace-bar"><i style="width:${_b2bListedPct(d)}%"></i></div>
               <span>${d.listed_units + d.recycled_units} of ${d.total_units} units done</span></div>` : '';
        return `
        <div class="b2b-q-card" onclick="b2bOpenDeal('${a.kind}','${d.id}')">
            <div class="b2b-q-main">
                <div class="b2b-q-top">
                    <span class="b2b-q-ref">${escapeHtml(d.ref)}</span>
                    <span class="b2b-q-co">${escapeHtml(d.client?.company || 'Unknown client')}</span>
                    ${_b2bStageChip(d.stage, d)}
                    ${_b2bStoreTag(d.listing_store || d.pricing_store)}
                </div>
                <div class="b2b-q-meta">${meta}<span class="b2b-age b2b-age-${_b2bAgeTone(days)}">${days}d in stage</span></div>
                ${bar}
            </div>
            <div class="b2b-q-act">
                <span class="b2b-q-why">${escapeHtml(a.why)}</span>
                <div class="b2b-q-btns">
                    ${quick ? `<button class="b2b-btn b2b-btn-quick" onclick="event.stopPropagation();${quick.call}">${escapeHtml(quick.label)}</button>` : ''}
                    <button class="b2b-btn b2b-btn-primary" onclick="event.stopPropagation();b2bOpenDeal('${a.kind}','${d.id}')">${escapeHtml(a.cta)}</button>
                </div>
            </div>
        </div>`;
    }).join('') : `
        <div class="b2b-empty">
            ${_b2bIco('<path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/>')}
            <div class="b2b-empty-t">You're all caught up</div>
            <div class="b2b-empty-s">No B2B deals are waiting on you. Check the Pipeline to see what's in flight.</div>
        </div>`;

    const flight = rest.length ? `
        <div class="b2b-sec">
            <div class="b2b-sec-h"><span>Also In Flight</span><span class="b2b-sec-n">${rest.length}</span></div>
            <div class="b2b-flight">
                ${rest.map(d => `
                <div class="b2b-f-row" onclick="b2bOpenDeal('${_b2bClickKind(d)}','${d.id}')">
                    <span class="b2b-f-ref">${escapeHtml(d.ref)}</span>
                    <span class="b2b-f-co">${escapeHtml(d.client?.company || '')}</span>
                    ${_b2bStageChip(d.stage, d)}
                    ${_b2bStoreTag(d.listing_store || d.pricing_store)}
                    <span class="b2b-f-val">${d.total_offer ? _b2bMoney(_b2bNetOffer(d)) : ''}</span>
                </div>`).join('')}
            </div>
        </div>` : '';

    return `
        <div class="b2b-sec">
            <div class="b2b-sec-h"><span>Needs Your Action</span><span class="b2b-sec-n">${queue.length}</span></div>
            <div class="b2b-queue">${cards}</div>
        </div>
        ${flight}`;
}

// --- view: Pipeline -------------------------------------------------------

function _b2bRenderPipeline(scoped) {
    const live = scoped.filter(d => !_b2bIsTerminal(d));
    let deals = live;
    if (_b2bIsCorp() && _b2bStoreFilter === 'NONE') {
        deals = deals.filter(d => !d.pricing_store && !d.listing_store);
    } else if (_b2bIsCorp() && _b2bStoreFilter !== 'ALL') {
        deals = deals.filter(d => d.pricing_store === _b2bStoreFilter || d.listing_store === _b2bStoreFilter);
    }

    // A row of store bubbles read as clutter, and worse: filtering to a store
    // silently hid every deal with no location assigned yet -- which is exactly
    // the set waiting to be routed. A select keeps the header calm and makes
    // "Unassigned" an explicit, findable choice rather than a blind spot.
    //
    // Counted off `live`, not the filtered set: taken from `deals` the number
    // collapses to zero the moment you filter to a store, so the count vanished
    // exactly when you were somewhere else and might want to jump back to it.
    const unassigned = live.filter(d => !d.pricing_store && !d.listing_store).length;
    const filter = _b2bIsCorp() ? `
        <div class="b2b-filter">
            <label class="b2b-filter-l" for="b2bStoreSelect">Store</label>
            <select id="b2bStoreSelect" class="kpi-select b2b-filter-sel" onchange="b2bSetStoreFilter(this.value)">
                <option value="ALL" ${_b2bStoreFilter === 'ALL' ? 'selected' : ''}>All stores</option>
                <option value="NONE" ${_b2bStoreFilter === 'NONE' ? 'selected' : ''}>Unassigned${unassigned ? ` (${unassigned})` : ''}</option>
                ${B2B_LOCATIONS.map(c => `
                    <option value="${c}" ${_b2bStoreFilter === c ? 'selected' : ''}>${c === 'CORP' ? 'CORP' : c}</option>`).join('')}
            </select>
        </div>` : '';

    const cols = B2B_BOARD.map(key => {
        const s = B2B_STAGE[key];
        const inCol = deals.filter(d => d.stage === key);
        const cards = inCol.length ? inCol.map(d => {
            const days = _b2bDaysIn(d);
            const act  = _b2bActionFor(d);
            const bar  = (key === 'listing')
                ? `<div class="b2b-pace-bar sm"><i style="width:${_b2bListedPct(d)}%"></i></div>` : '';
            return `
            <div class="b2b-card ${act ? 'act' : ''}" onclick="b2bOpenDeal('${_b2bClickKind(d)}','${d.id}')">
                <div class="b2b-card-top">
                    <span class="b2b-card-ref">${escapeHtml(d.ref)}</span>
                    ${_b2bStoreTag(d.listing_store || d.pricing_store)}
                </div>
                <div class="b2b-card-co">${escapeHtml(d.client?.company || '')}</div>
                ${bar}
                <div class="b2b-card-foot">
                    <span>${d.total_offer ? _b2bMoney(_b2bNetOffer(d)) : `${d.line_count || 0} lines`}</span>
                    <span class="b2b-age b2b-age-${_b2bAgeTone(days)}">${days}d</span>
                </div>
                ${act ? '<span class="b2b-card-pill">Needs you</span>' : ''}
            </div>`;
        }).join('') : '<div class="b2b-col-empty">—</div>';

        return `
        <div class="b2b-col b2b-col-${s.tone}">
            <div class="b2b-col-h">
                <span class="b2b-col-t">${_b2bIco(s.svg)}${escapeHtml(s.label)}</span>
                <span class="b2b-col-n">${inCol.length}</span>
            </div>
            <div class="b2b-col-b">${cards}</div>
        </div>`;
    }).join('');

    // The board is a picture of work in flight, so finished deals live in their
    // own view rather than as an eighth column nobody scrolls to.
    const finished = scoped.filter(d => _b2bIsTerminal(d)).length;
    const note = finished
        ? `<div class="b2b-archive-note">${finished} finished deal${finished === 1 ? '' : 's'} `
          + `${finished === 1 ? 'is' : 'are'} kept in <button class="b2b-linkbtn" onclick="b2bSetView('finished')">Completed</button>.</div>`
        : '';
    // Six columns are wider than most laptops, so the board scrolls inside
    // its own wrapper rather than pushing the whole page sideways.
    return `${filter}<div class="b2b-boardwrap"><div class="b2b-board">${cols}</div></div>${note}`;
}

// --- view: Completed ------------------------------------------------------
// Both terminal outcomes, because "what happened to that deal" is the same
// question whether it closed out or fell through.
//
// Only the recent tail of finished deals rides along with the board payload --
// the finished set grows without bound, and pulling all of it on every load to
// service a view most people never open would be the wrong trade. So the tail
// is what you get, and a deeper page is asked for explicitly.

const B2B_ARCHIVE_STEPS = [40, 200, 500];   // last step is ARCHIVE_MAX in the edge fn
let _b2bArchiveDepth = B2B_ARCHIVE_STEPS[0];
let _b2bFinOutcome   = 'all';   // all | completed | declined
let _b2bFinQuery     = '';

function _b2bIsTerminal(d) { return d.stage === 'completed' || d.stage === 'declined'; }

// Closed-out date. stage_changed_at is when it reached its terminal stage.
function _b2bClosedAt(d) { return d.stage_changed_at || d.updated_at || d.created_at; }

function _b2bFinishedRows(rows) {
    if (!rows.length) {
        return `<div class="b2b-doc-empty">${_b2bFinQuery || _b2bFinOutcome !== 'all'
            ? 'No finished deals match that.'
            : 'Nothing has finished yet. Deals land here once they complete or get declined.'}</div>`;
    }
    const body = rows.map(d => {
        const done = (Number(d.listed_units) || 0) + (Number(d.recycled_units) || 0);
        const sub  = d.stage === 'declined' && d.declined_reason
            ? `<div class="b2b-doc-sub">${escapeHtml(d.declined_reason)}</div>` : '';
        return `
        <tr class="b2b-clickrow" onclick="b2bOpenDeal('view','${d.id}')">
            <td><span class="b2b-mono">${escapeHtml(d.ref)}</span></td>
            <td><b>${escapeHtml(d.client?.company || '')}</b>${sub}</td>
            <td>${_b2bStageChip(d.stage, d)}</td>
            <td>${_b2bStoreTag(d.listing_store || d.pricing_store)}</td>
            <td class="c">${d.stage === 'completed' ? `${done} of ${d.total_units || 0}` : '—'}</td>
            <td class="r b">${d.stage === 'completed' ? _b2bMoney(_b2bNetCost(d)) : '—'}</td>
            <td class="r">${_b2bDate(_b2bClosedAt(d))}</td>
        </tr>`;
    }).join('');
    return `<table class="cb-table b2b-ftable">
            <thead><tr><th>Ref</th><th>Client</th><th>Outcome</th><th>Store</th>
                <th class="c">Units</th><th class="r">Cost</th><th class="r">Closed</th></tr></thead>
            <tbody>${body}</tbody>
        </table>`;
}

// Applies the two filters to the scoped terminal set, newest first.
function _b2bFinishedSet(scoped) {
    const q = _b2bFinQuery.toLowerCase().trim();
    return scoped
        .filter(_b2bIsTerminal)
        .filter(d => _b2bFinOutcome === 'all' || d.stage === _b2bFinOutcome)
        .filter(d => !q
            || (d.ref || '').toLowerCase().includes(q)
            || (d.client?.company || '').toLowerCase().includes(q)
            || (d.client?.acronym || '').toLowerCase().includes(q))
        .sort((a, b) => new Date(_b2bClosedAt(b)) - new Date(_b2bClosedAt(a)));
}

function _b2bRenderFinished(scoped) {
    const all  = scoped.filter(_b2bIsTerminal);
    const rows = _b2bFinishedSet(scoped);
    const won  = all.filter(d => d.stage === 'completed');
    const lost = all.filter(d => d.stage === 'declined');

    const tiles = `
        <div class="b2b-tiles">
            <div class="b2b-tile"><span class="b2b-tile-k">Completed</span><span class="b2b-tile-v">${won.length}</span><span class="b2b-tile-c">deals closed out</span></div>
            <div class="b2b-tile"><span class="b2b-tile-k">Cost Locked In</span><span class="b2b-tile-v">${_b2bMoney(won.reduce((s, d) => s + _b2bNetCost(d), 0))}</span><span class="b2b-tile-c">across completed deals</span></div>
            <div class="b2b-tile"><span class="b2b-tile-k">Units Handled</span><span class="b2b-tile-v">${won.reduce((n, d) => n + (Number(d.listed_units) || 0) + (Number(d.recycled_units) || 0), 0)}</span><span class="b2b-tile-c">listed or recycled</span></div>
            <div class="b2b-tile ${lost.length ? 'warn' : ''}"><span class="b2b-tile-k">Declined</span><span class="b2b-tile-v">${lost.length}</span><span class="b2b-tile-c">deals that fell through</span></div>
        </div>`;

    // The search box is written once and only the rows below it repaint, so
    // typing never loses focus.
    const controls = `
        <div class="b2b-filter">
            <label class="b2b-filter-l" for="b2bFinOutcome">Outcome</label>
            <select id="b2bFinOutcome" class="kpi-select b2b-filter-sel" onchange="b2bSetFinOutcome(this.value)">
                <option value="all"       ${_b2bFinOutcome === 'all'       ? 'selected' : ''}>All outcomes</option>
                <option value="completed" ${_b2bFinOutcome === 'completed' ? 'selected' : ''}>Completed${won.length ? ` (${won.length})` : ''}</option>
                <option value="declined"  ${_b2bFinOutcome === 'declined'  ? 'selected' : ''}>Declined${lost.length ? ` (${lost.length})` : ''}</option>
            </select>
            <input id="b2bFinSearch" class="b2b-filter-search" autocomplete="off" placeholder="Search ref or client…"
                value="${escapeHtml(_b2bFinQuery)}" oninput="_b2bPaintFinished()">
        </div>`;

    // The meta counts come from the server, which scopes to one store at most --
    // an MSM covering two pulls ALL and narrows in _b2bInScope, so quoting those
    // numbers at them would count stores they can't see. They get the offer
    // without the arithmetic.
    const exact  = _b2bIsCorp() || _b2bMyStores().length === 1;
    const more   = B2B_ARCHIVE_STEPS.some(s => s > _b2bArchiveDepth)
        ? ' <button class="b2b-linkbtn" onclick="b2bLoadDeeperArchive(this)">Load more</button>' : '';
    const deeper = _b2bMeta?.archive_truncated
        ? `<div class="b2b-archive-note">${exact
            ? `Showing the ${_b2bMeta.archive_shown} most recently finished of ${_b2bMeta.archive_total}.`
            : 'Older finished deals are not loaded yet.'}${more}</div>`
        : '';

    return `${tiles}${controls}
        <div class="b2b-sec">
            <div class="b2b-sec-h"><span>Finished Deals</span><span class="b2b-sec-n">${rows.length}</span></div>
            <div id="b2bFinRows">${_b2bFinishedRows(rows)}</div>
        </div>
        ${deeper}`;
}

function b2bSetFinOutcome(v) { _b2bFinOutcome = v; _b2bPaintFinished(); }

// Repaints only the rows, so the filters keep their focus and caret position.
function _b2bPaintFinished() {
    _b2bFinQuery = document.getElementById('b2bFinSearch')?.value || '';
    const host = document.getElementById('b2bFinRows');
    if (!host) return;
    const rows = _b2bFinishedSet(_b2bDeals.filter(_b2bInScope));
    host.innerHTML = _b2bFinishedRows(rows);
    const n = host.parentElement?.querySelector('.b2b-sec-n');
    if (n) n.textContent = rows.length;
}

// Walks the depth up one step and refetches. Deliberately manual: the deeper
// pages are for looking something up, not for the default load.
async function b2bLoadDeeperArchive(btn) {
    const next = B2B_ARCHIVE_STEPS.find(s => s > _b2bArchiveDepth);
    if (!next) return;
    _b2bArchiveDepth = next;
    await _b2bBusy(btn, 'Loading…', () => b2bRefresh());
}

// --- view: Clients (DM/CEO) ------------------------------------------------

// Which client rows are expanded. A Set rather than a single id so two clients
// can be compared side by side.
const _b2bClientOpen = new Set();

function _b2bRenderClients() {
    const editing = _b2bEditingClient ? _b2bClients.find(c => c.id === _b2bEditingClient) : null;
    const rows = _b2bClients.length ? _b2bClients.map(c => {
        const open = _b2bClientOpen.has(c.id);
        return `
        <tr id="b2bCRow-${c.id}" class="b2b-clickrow${open ? ' open' : ''}" onclick="b2bToggleClient('${c.id}')">
            <td><button class="b2b-cexp" aria-expanded="${open}" aria-label="Show deals and history">${
                _b2bIco('<polyline points="9 18 15 12 9 6"/>')}</button></td>
            <td><span class="b2b-mono b2b-acr">${escapeHtml(c.acronym)}</span></td>
            <td><b>${escapeHtml(c.company)}</b>${c.notes ? `<div class="b2b-doc-sub">${escapeHtml(c.notes)}</div>` : ''}</td>
            <td>${escapeHtml(c.contact || '—')}</td>
            <td>${escapeHtml(c.contact_email || '—')}</td>
            <td>${escapeHtml(c.contact_phone || '—')}</td>
            <td class="c">${c.open_count ? `<span class="b2b-chip b2b-chip-info">${c.open_count} open</span> ` : ''}${c.deal_count || 0}</td>
            <td class="r b2b-rowacts">
                <button class="b2b-mini" onclick="event.stopPropagation();b2bEditClient('${c.id}')">Edit</button>
                <button class="b2b-mini danger" ${c.deal_count ? 'disabled title="Clients with deals on record cannot be deleted"' : ''} onclick="event.stopPropagation();b2bDeleteClient('${c.id}')">Delete</button>
            </td>
        </tr>${open ? _b2bClientDrawer(c.id) : ''}`;
    }).join('')
        : '<tr><td colspan="8" class="b2b-doc-empty">No clients yet — add the first one below.</td></tr>';

    return `
        <div class="b2b-sec">
            <div class="b2b-sec-h"><span>Clients</span><span class="b2b-sec-n">${_b2bClients.length}</span></div>
            <table class="cb-table b2b-ctable">
                <thead><tr><th class="b2b-th-exp"></th><th>Acronym</th><th>Company</th><th>Contact</th><th>Email</th><th>Phone</th><th class="c">Deals</th><th></th></tr></thead>
                <tbody>${rows}</tbody>
            </table>
        </div>
        <div class="b2b-sec">
            <div class="b2b-sec-h"><span>${editing ? 'Edit Client' : 'Add A Client'}</span></div>
            <div class="b2b-cform">
                <div class="b2b-grid2">
                    <div><label class="form-label-caps">Company *</label>
                        <input id="b2bCfCompany" class="form-input-lg" value="${escapeHtml(editing?.company || '')}" placeholder="Acme Corp"></div>
                    <div><label class="form-label-caps">Acronym *</label>
                        <input id="b2bCfAcronym" class="form-input-lg b2b-mono" maxlength="6" value="${escapeHtml(editing?.acronym || '')}" placeholder="ACM" oninput="this.value=this.value.toUpperCase()"></div>
                    <div><label class="form-label-caps">Contact</label>
                        <input id="b2bCfContact" class="form-input-lg" value="${escapeHtml(editing?.contact || '')}"></div>
                    <div><label class="form-label-caps">Email</label>
                        <input id="b2bCfEmail" class="form-input-lg" value="${escapeHtml(editing?.contact_email || '')}"></div>
                    <div><label class="form-label-caps">Phone</label>
                        <input id="b2bCfPhone" class="form-input-lg" type="tel" inputmode="tel" maxlength="20"
                            value="${escapeHtml(editing?.contact_phone || '')}" placeholder="(816) 555-0142"
                            oninput="_b2bPhoneMask(this)"></div>
                    <div><label class="form-label-caps">Notes</label>
                        <input id="b2bCfNotes" class="form-input-lg" value="${escapeHtml(editing?.notes || '')}" placeholder="Anything worth remembering"></div>
                </div>
                <p class="b2b-hint">The acronym leads every SKU printed for this client, so it locks once they have a quoted deal.</p>
                <div class="b2b-cform-acts">
                    ${editing ? '<button class="kpi-cancel-btn" onclick="b2bEditClient(null)">Cancel Edit</button>' : ''}
                    <button class="b2b-btn b2b-btn-primary" onclick="b2bSaveClient()">${editing ? 'Save Changes' : 'Add Client'}</button>
                </div>
            </div>
        </div>`;
}

// Expands in place rather than through b2bRender(), so opening a client doesn't
// wipe whatever is half-typed in the add/edit form below the table.
function b2bToggleClient(id) {
    const row  = document.getElementById(`b2bCRow-${id}`);
    const drop = document.getElementById(`b2bCDrop-${id}`);
    if (drop) {
        drop.remove();
        _b2bClientOpen.delete(id);
        row?.classList.remove('open');
        row?.querySelector('.b2b-cexp')?.setAttribute('aria-expanded', 'false');
        return;
    }
    if (!row) return;
    _b2bClientOpen.add(id);
    row.classList.add('open');
    row.querySelector('.b2b-cexp')?.setAttribute('aria-expanded', 'true');
    row.insertAdjacentHTML('afterend', _b2bClientDrawer(id));
}

// --- outreach (the mini CRM) ----------------------------------------------
// A client can carry a cadence: every N months from a date you set. The daily
// b2b-outreach sweep emails leadership when one comes due.
//
// The reminder goes to US, not to the client. The client-facing note is a mailto
// from here, so it leaves the sender's own mailbox and the reply comes back to
// them -- same reasoning as the quote. Auto-sending to a real business from the
// reports address would put our outreach in a place nobody reads the answer.

// Today in the store's timezone, as YYYY-MM-DD, so "due" means the same thing
// here as it does in the edge function.
function _b2bToday() {
    return new Date().toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
}

function _b2bDueIn(dateStr) {
    if (!dateStr) return null;
    const a = Date.parse(_b2bToday() + 'T00:00:00Z');
    const b = Date.parse(dateStr + 'T00:00:00Z');
    if (Number.isNaN(b)) return null;
    return Math.round((b - a) / 86400000);   // negative = overdue
}

function _b2bDueLabel(dateStr) {
    const d = _b2bDueIn(dateStr);
    if (d === null) return { text: 'Not scheduled', tone: 'neu' };
    if (d < 0)  return { text: `${-d} day${d === -1 ? '' : 's'} overdue`, tone: 'crit' };
    if (d === 0) return { text: 'Due today', tone: 'warn' };
    if (d <= 14) return { text: `Due in ${d} day${d === 1 ? '' : 's'}`, tone: 'warn' };
    return { text: `Due ${_b2bDate(dateStr)}`, tone: 'ok' };
}

// Records that we actually reached out, which is what moves the schedule on.
async function b2bLogTouch(id, btn) {
    const c = _b2bClients.find(x => x.id === id);
    if (!c) return;
    const detail = prompt(`Log a check-in with ${c.company}.\n\n`
        + 'Anything worth remembering? (optional — leave blank and it just records the date)', '');
    if (detail === null) return;
    try {
        await _b2bBusy(btn, 'Saving…', async () => {
            const res = await fetch(B2B_OUTREACH_URL, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action: 'log_touch', client_id: id, detail, user: _b2bUser() }),
            });
            const out = await res.json().catch(() => ({}));
            if (!res.ok || out.success === false) throw new Error(out.error || `Request failed (HTTP ${res.status})`);
        });
        await b2bRefresh();
    } catch (e) {
        alert(`Couldn't log that check-in: ${e.message}`);
    }
}

// Opens a draft in the sender's own mailbox. Plain text, because a mailto body
// is plain text by RFC 6068 -- no markup survives the trip.
function b2bDraftOutreach(id) {
    const c = _b2bClients.find(x => x.id === id);
    if (!c) return;
    if (!c.contact_email) return alert(`${c.company} has no email address on file.`);

    const me   = _b2bUser();
    const who  = (c.contact || '').trim().split(/\s+/)[0];
    const last = c.last_deal_at ? _b2bLongDate(String(c.last_deal_at).slice(0, 10)) : '';
    const body = [
        who ? `Hi ${who},` : 'Hello,',
        '',
        last
            ? `I hope things are going well. We last worked together on a pickup in ${last}, and I wanted to check in and see whether you have any equipment coming out of service.`
            : 'I hope things are going well. I wanted to check in and see whether you have any equipment coming out of service.',
        '',
        'If you do, we can look at it and get you a quote — no obligation either way. Happy to come to you for the pickup, same as before.',
        '',
        'Just let me know and I will get it scheduled.',
        '',
        'Best regards,',
        me,
        'SPEEKS Technology',
    ].join('\n');
    const subject = `Checking In From SPEEKS Technology`;

    if (!confirm(`This opens a draft to ${c.contact_email} in your own email app.\n\n`
        + 'Read it over and edit it before sending — it is a starting point, not a template to fire off.\n\n'
        + `After you send it, use "Mark Reached Out" so the schedule moves on.`)) return;

    window.location.href = `mailto:${encodeURIComponent(c.contact_email)}`
        + `?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

// A client's history. The headline figures come from the server (the view rolls
// them up over every deal on record); the deal list underneath can only show
// what this session actually loaded, which is the open set plus the recent
// finished tail -- so it says so when there is more behind it.
// --- client & deal stat tiles ---------------------------------------------
// One tile renderer + one derivation, shared by the client drawer (fed the
// b2b_client_list rollups) and the per-deal blocks (fed sums computed from the
// loaded line items), so both read identically and the margin/average formula
// lives in exactly one place.
function _b2bStatTile(k, v, sub) {
    return `<div class="b2b-cstat"><span class="b2b-cstat-k">${k}</span>`
         + `<span class="b2b-cstat-v">${v}</span>${sub ? `<span class="b2b-cstat-s">${sub}</span>` : ''}</div>`;
}

// Margin + average from the raw rollup figures. Margin is resale value less what
// we actually paid (cost, minus the wipe charge that came off the client's
// payout) less freight -- the same definition the pricing totals bar uses.
function _b2bStatDerive(o) {
    const items = Number(o.items_purchased) || 0;
    const value = Number(o.value_purchased) || 0;
    const cost  = Number(o.cost_purchased) || 0;
    const wipe  = Number(o.wipe_purchased) || 0;
    const ship  = Number(o.ship_purchased) || 0;
    return {
        items,
        listed: Number(o.listed_value) || 0,
        todo:   Number(o.todo_value) || 0,
        margin: value - (cost - wipe) - ship,
        avg:    items > 0 ? value / items : 0,
    };
}

// Per-deal version of the client rollups, from the loaded line items so it needs
// no round trip. Mirrors the b2b_client_list SQL: purchased figures count only
// purchase-disposition lines on an accepted deal; listed value is resale value
// actually listed; to-do value is resale value still to list once the deal is
// locked into listing (accepted, not yet completed).
// Per-deal figures, unscoped by acceptance so they read as a live estimate
// while pricing/quoting and settle into the real numbers once accepted. Est.
// value is the resale value of everything we'd list (anything not scrapped);
// cost is what we pay the client (purchase lines). Listed / to-do split by
// listing progress -- to-do only once the deal is locked into listing.
function _b2bDealStatRaw(items, deal) {
    const toList = !!(deal && deal.accepted_at) && deal.stage !== 'completed';
    const o = { items_purchased: 0, value_purchased: 0, cost_purchased: 0,
                listed_value: 0, todo_value: 0, total_shipping: 0, est_value: 0 };
    (items || []).forEach(it => {
        const q  = Number(it.quantity) || 0;
        const v  = Number(it.value) || 0;
        const lq = Number(it.listed_qty) || 0;
        const rq = Number(it.recycled_qty) || 0;
        o.total_shipping += (Number(it.shipping_cost) || 0) * q;
        o.listed_value   += v * lq;
        if (toList) o.todo_value += v * Math.max(0, q - lq - rq);
        if (!_b2bIsScrap(it)) o.est_value += v * q;            // resale value of listable goods
        if (_b2bIsBuy(it)) {
            o.items_purchased += q;
            o.value_purchased += v * q;
            o.cost_purchased  += (Number(it.cost != null ? it.cost : it.offer) || 0) * q;  // what we pay
        }
    });
    return o;
}

// The per-deal stat tiles: the client set plus estimated value/cost and total
// shipping. Tiles reconcile: Est. Value − Est. Cost − Total Shipping = Margin.
function _b2bDealStatsInner(items, deal) {
    const o = _b2bDealStatRaw(items, deal);
    const margin = o.est_value - o.cost_purchased - o.total_shipping;
    const avg = o.items_purchased > 0 ? o.value_purchased / o.items_purchased : 0;
    return `
        <div class="b2b-cd-h">Deal Stats</div>
        <div class="b2b-cstats">
            ${_b2bStatTile('Est. Value', _b2bMoney(o.est_value), 'resale value of the goods')}
            ${_b2bStatTile('Est. Cost', _b2bMoney(o.cost_purchased), 'what we pay the client')}
            ${_b2bStatTile('Items Purchased', o.items_purchased, 'units bought')}
            ${_b2bStatTile('Listed Value', _b2bMoney(o.listed_value), 'resale value listed')}
            ${_b2bStatTile('To-Do Value', _b2bMoney(o.todo_value), 'resale value to list')}
            ${_b2bStatTile('Total Margin', _b2bMoney(margin), 'value − cost − shipping')}
            ${_b2bStatTile('Avg Value / Item', _b2bMoney(avg), 'per purchased item')}
            ${_b2bStatTile('Total Shipping', _b2bMoney(o.total_shipping), 'to move the goods')}
        </div>`;
}

function _b2bDealStatsHtml(items, deal) {
    return `<div id="b2bDealStats">${_b2bDealStatsInner(items, deal)}</div>`;
}

// Repaint the block in place -- from the pricing/quote totals pass and the
// listing scan repaint -- so the figures track live edits and listing progress.
function _b2bPaintDealStats() {
    const el = document.getElementById('b2bDealStats');
    if (el && _b2bModalDeal) el.innerHTML = _b2bDealStatsInner(_b2bModalItems, _b2bModalDeal);
}

function _b2bClientDrawer(id) {
    const c = _b2bClients.find(x => x.id === id);
    if (!c) return '';

    const total = Number(c.deal_count) || 0;

    // Six tiles of zeros says nothing a single sentence doesn't say better -- but
    // a client with no deals yet is exactly who you might want to chase, so the
    // outreach panel still belongs here.
    if (!total) {
        return `
        <tr class="b2b-cdrop" id="b2bCDrop-${id}">
            <td colspan="8">
                <div class="b2b-doc-empty">No deals with ${escapeHtml(c.company)} yet.
                    Start one with New Deal.</div>            </td>
        </tr>`;
    }

    const mine = _b2bDeals
        .filter(d => d.client_id === id && _b2bInScope(d))
        .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

    // Purchased/margin figures count accepted deals; listed vs to-do value split
    // by listing progress. All rolled up in the b2b_client_list view.
    const s = _b2bStatDerive(c);
    const stats = `
        <div class="b2b-cstats">
            ${_b2bStatTile('Total Deals', total, `${Number(c.completed_count) || 0} completed`)}
            ${_b2bStatTile('Active Deals', Number(c.open_count) || 0, 'in progress')}
            ${_b2bStatTile('Items Purchased', s.items, 'units bought')}
            ${_b2bStatTile('Listed Value', _b2bMoney(s.listed), 'resale value listed')}
            ${_b2bStatTile('To-Do Value', _b2bMoney(s.todo), 'resale value to list')}
            ${_b2bStatTile('Total Margin', _b2bMoney(s.margin), 'resale − paid − shipping')}
            ${_b2bStatTile('Avg Value / Item', _b2bMoney(s.avg), 'per purchased item')}
        </div>`;

    const dealRows = mine.length ? mine.map(d => `
        <div class="b2b-cd-row" onclick="event.stopPropagation();b2bOpenDeal('${_b2bClickKind(d)}','${d.id}')">
            <span class="b2b-mono b2b-cd-ref">${escapeHtml(d.ref)}</span>
            ${_b2bStageChip(d.stage, d)}
            ${_b2bStoreTag(d.listing_store || d.pricing_store)}
            <span class="b2b-cd-units">${d.total_units ? `${d.total_units} unit${d.total_units === 1 ? '' : 's'}` : `${d.line_count || 0} lines`}</span>
            <span class="b2b-cd-val">${d.stage === 'completed' ? _b2bMoney(_b2bNetCost(d))
                : d.total_offer ? _b2bMoney(_b2bNetOffer(d)) : ''}</span>
            <span class="b2b-cd-date">${_b2bDate(d.created_at)}</span>
        </div>`).join('')
        : '<div class="b2b-doc-empty">None of their deals are loaded right now — '
          + 'open Completed and load more to reach the older ones.</div>';

    const hidden = total > mine.length && mine.length
        ? `<div class="b2b-archive-note">${total - mine.length} older deal${total - mine.length === 1 ? '' : 's'} not loaded.</div>`
        : '';

    return `
        <tr class="b2b-cdrop" id="b2bCDrop-${id}">
            <td colspan="8">
                ${stats}                <div class="b2b-cd-h">Deals</div>
                <div class="b2b-cdeals">${dealRows}</div>
                ${hidden}
            </td>
        </tr>`;
}

// ============================================================================
// CRM SETTINGS (CEO only) — the notification half of the mini CRM.
// Three tabs: per-client cadence (Client List), a queue of unconfigured clients
// (New Clients + badge), and the single email address all reach-out reminders
// are sent to (Notifications). Cadence + email persist through b2b-outreach.
// ============================================================================
let _crmTab      = 'clients';
let _crmSearch   = '';
let _crmSettings = { notify_email: '', enabled: true,
                     quote_ready_enabled: true, wipe_fee: 8 };
const CRM_UNITS  = ['day', 'week', 'month'];

function _crmNewClients() { return _b2bClients.filter(c => !c.outreach_reviewed_at); }

// Badge on the gear button + the New Clients tab. Safe anywhere: no-ops when the
// elements aren't present (e.g. other pages).
function crmRefreshBadge() {
    const n = _crmNewClients().length;
    ['crmGearBadge', 'crmTabBadge'].forEach(id => {
        const el = document.getElementById(id);
        if (el) { el.textContent = n; el.style.display = n > 0 ? '' : 'none'; }
    });
}

async function crmLoadSettings() {
    try {
        const res = await fetch(`${B2B_OUTREACH_URL}?settings=1&v=${Date.now()}`);
        const j = await res.json();
        if (j && j.settings) _crmSettings = {
            notify_email: j.settings.notify_email || '',
            enabled: j.settings.enabled !== false,
            quote_ready_enabled: j.settings.quote_ready_enabled !== false,
            wipe_fee: Number(j.settings.wipe_fee ?? 8),
        };
    } catch (_) { /* keep what we have */ }
}

async function crmOpen() {
    if (!_b2bCanCrm()) return;
    const modal = document.getElementById('crmModal');
    if (!modal) return;
    _crmTab = 'clients'; _crmSearch = '';
    document.getElementById('crmBody').innerHTML = '<div class="status-message">Loading…</div>';
    closeAllModals();
    modal.classList.add('show');
    lockAndBlurScreen();
    await crmLoadSettings();
    if (!_b2bClients.length) { try { _b2bClients = await _b2bGet('clients=1'); } catch (_) {} }
    crmSyncTabs();
    crmRender();
}

function crmSyncTabs() {
    document.querySelectorAll('#crmTabs .crm-tab').forEach(b => b.classList.toggle('active', b.dataset.tab === _crmTab));
    const n = _crmNewClients().length;
    const tb = document.getElementById('crmTabBadge');
    if (tb) { tb.textContent = n; tb.style.display = n > 0 ? '' : 'none'; }
}

function crmTab(t) { _crmTab = t; crmSyncTabs(); crmRender(); }

function crmRender() {
    const body = document.getElementById('crmBody');
    if (!body) return;
    if (_crmTab === 'settings') body.innerHTML = _crmSettingsHtml();
    else if (_crmTab === 'new') body.innerHTML = _crmNewHtml();
    else body.innerHTML = _crmClientsHtml();
}

function _crmFilter(list) {
    const q = _crmSearch.trim().toLowerCase();
    if (!q) return list;
    return list.filter(c => (c.company || '').toLowerCase().includes(q)
        || (c.acronym || '').toLowerCase().includes(q)
        || (c.contact || '').toLowerCase().includes(q));
}

function _crmClientsHtml() {
    const list = _crmFilter(_b2bClients.slice().sort((a, b) => String(a.company).localeCompare(String(b.company))));
    const rows = list.length ? list.map(_crmClientRow).join('') : '<div class="b2b-doc-empty">No clients match.</div>';
    return `
        <p class="crm-help">Set how often each client should get a check-in reminder and the day it starts from. Reminders email the address on the Notifications tab — nothing shows in the app.</p>
        <input class="form-input-lg crm-search" placeholder="Search clients…" value="${escapeHtml(_crmSearch)}" oninput="_crmSearch=this.value;_crmRenderList()">
        <div class="crm-clist" id="crmClist">${rows}</div>`;
}
// Re-render just the list on search so the search box keeps focus.
function _crmRenderList() {
    const el = document.getElementById('crmClist');
    if (!el) return;
    const list = _crmFilter(_b2bClients.slice().sort((a, b) => String(a.company).localeCompare(String(b.company))));
    el.innerHTML = list.length ? list.map(_crmClientRow).join('') : '<div class="b2b-doc-empty">No clients match.</div>';
}

function _crmNewHtml() {
    const list = _crmNewClients().sort((a, b) => String(a.company).localeCompare(String(b.company)));
    if (!list.length) return `<div class="crm-clear"><div class="crm-clear-em">✓</div><h4>All caught up</h4>
        <p>Every client has been set up. New clients you add show up here to configure their reminders.</p></div>`;
    return `<p class="crm-help">New clients that haven't been set up yet. Give them a reminder cadence, or mark that they don't need one — either clears them from this list.</p>
        <div class="crm-clist">${list.map(_crmClientRow).join('')}</div>`;
}

function _crmClientRow(c) {
    const on = !!c.outreach_active;
    const every = c.outreach_every || 1;
    const unit = c.outreach_unit || 'week';
    const due = on ? _b2bDueLabel(c.outreach_next_due) : null;
    const newTag = !c.outreach_reviewed_at ? '<span class="crm-newtag">NEW</span>' : '';
    return `
    <div class="crm-crow" id="crmRow-${c.id}">
        <div class="crm-crow-top">
            <span class="crm-co"><b>${escapeHtml(c.company)}</b> <span class="b2b-mono b2b-acr">${escapeHtml(c.acronym)}</span>${newTag}</span>
            <span class="crm-when">${on && due
                ? `<span class="b2b-age b2b-age-${due.tone === 'crit' ? 'crit' : due.tone === 'warn' ? 'warn' : 'ok'}">${escapeHtml(due.text)}</span>`
                : '<span class="crm-off">No reminders</span>'}</span>
        </div>
        <label class="crm-toggle"><input type="checkbox" id="crmOn-${c.id}" ${on ? 'checked' : ''} onchange="_crmToggle('${c.id}',this.checked)"> Remind me to check in on this client</label>
        <div class="crm-fields" id="crmFields-${c.id}" ${on ? '' : 'style="display:none;"'}>
            <span class="crm-inline">Every
                <input type="number" min="1" max="365" id="crmEvery-${c.id}" value="${every}" class="crm-num">
                <select id="crmUnit-${c.id}" class="crm-sel">${CRM_UNITS.map(u => `<option value="${u}" ${unit === u ? 'selected' : ''}>${u}s</option>`).join('')}</select>
                starting <input type="date" id="crmStart-${c.id}" value="${escapeHtml(c.outreach_start || _b2bToday())}" class="crm-date">
            </span>
            <input id="crmNote-${c.id}" class="form-input-lg crm-note" placeholder="What to bring up (goes in the reminder email)" value="${escapeHtml(c.outreach_note || '')}">
        </div>
        <div class="crm-crow-acts">
            <button class="b2b-btn b2b-btn-primary b2b-mini" onclick="crmSaveSchedule('${c.id}',this)">Save</button>
            ${!c.outreach_reviewed_at ? `<button class="b2b-mini" onclick="crmMarkReviewed('${c.id}',this)">No reminders needed</button>` : ''}
            ${on && c.contact_email ? `<button class="b2b-mini" onclick="b2bDraftOutreach('${c.id}')">Draft Email</button>` : ''}
            ${on ? `<button class="b2b-mini" onclick="b2bLogTouch('${c.id}',this)">Mark Reached Out</button>` : ''}
        </div>
    </div>`;
}
function _crmToggle(id, on) { const f = document.getElementById('crmFields-' + id); if (f) f.style.display = on ? '' : 'none'; }

async function crmSaveSchedule(id, btn) {
    const on    = document.getElementById('crmOn-' + id)?.checked || false;
    const every = document.getElementById('crmEvery-' + id)?.value || '';
    const unit  = document.getElementById('crmUnit-' + id)?.value || 'month';
    const start = document.getElementById('crmStart-' + id)?.value || '';
    const note  = document.getElementById('crmNote-' + id)?.value || '';
    if (on && !start) return alert('Pick the date the schedule should start from.');
    if (on && (!every || Number(every) < 1)) return alert('Set how often the reminder should repeat.');
    try {
        await _b2bBusy(btn, 'Saving…', async () => {
            const res = await fetch(B2B_OUTREACH_URL, {
                method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action: 'set_schedule', client_id: id, active: on, start, every, unit, note }),
            });
            const out = await res.json().catch(() => ({}));
            if (!res.ok || out.success === false) throw new Error(out.error || `Request failed (HTTP ${res.status})`);
        });
        await b2bRefresh();
        crmSyncTabs(); crmRender();
    } catch (e) { alert(`Couldn't save the schedule: ${e.message}`); }
}

async function crmMarkReviewed(id, btn) {
    try {
        await _b2bBusy(btn, 'Saving…', async () => {
            const res = await fetch(B2B_OUTREACH_URL, {
                method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action: 'mark_reviewed', client_id: id }),
            });
            const out = await res.json().catch(() => ({}));
            if (!res.ok || out.success === false) throw new Error(out.error || `Request failed (HTTP ${res.status})`);
        });
        await b2bRefresh();
        crmSyncTabs(); crmRender();
    } catch (e) { alert(`Couldn't update that client: ${e.message}`); }
}

function _crmSettingsHtml() {
    const s = _crmSettings;
    return `
    <p class="crm-help">Where every B2B notification is sent. Reach-out reminders and quote approvals both go to this one address — nothing appears inside the website.</p>
    <div class="crm-settings">
        <label class="form-label-caps">Notification email</label>
        <input id="crmEmail" class="form-input-lg" type="email" value="${escapeHtml(s.notify_email || '')}" placeholder="ceo@speekstechnology.com">
        <label class="crm-toggle" style="margin-top:16px;"><input type="checkbox" id="crmEnabled" ${s.enabled ? 'checked' : ''}> Send reach-out reminders</label>
        <label class="crm-toggle"><input type="checkbox" id="crmQuoteReady" ${s.quote_ready_enabled !== false ? 'checked' : ''}> Email me when a quote is priced and ready to send</label>

        <div class="crm-sec">Pricing</div>
        <label class="form-label-caps">Certified data wipe, per device</label>
        <div class="crm-fee">
            <span class="crm-fee-$">$</span>
            <input id="crmWipeFee" class="form-input-lg" type="number" min="0" step="0.01"
                value="${Number(s.wipe_fee ?? 8).toFixed(2)}">
        </div>
        <p class="crm-help">Taken off what we pay the client, never billed to them. Changing this
            only affects lines flagged from now on — a quote already priced keeps the figure it was quoted at.</p>

        <div class="crm-settings-acts">
            <button class="b2b-btn b2b-btn-primary" onclick="crmSaveSettings(this)">Save Settings</button>
            <span class="crm-msg" id="crmSetMsg"></span>
        </div>
    </div>`;
}

async function crmSaveSettings(btn) {
    const notify_email = document.getElementById('crmEmail')?.value.trim() || '';
    const enabled      = document.getElementById('crmEnabled')?.checked !== false;
    const quote_ready_enabled = document.getElementById('crmQuoteReady')?.checked !== false;
    const wipe_fee     = parseFloat(document.getElementById('crmWipeFee')?.value) || 0;
    if (wipe_fee < 0) return alert("A wipe charge can't be negative — it comes off what we pay, not what they pay.");
    try {
        await _b2bBusy(btn, 'Saving…', async () => {
            const res = await fetch(B2B_OUTREACH_URL, {
                method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action: 'set_crm_settings', notify_email, enabled,
                    quote_ready_enabled, wipe_fee, user: _b2bUser() }),
            });
            const out = await res.json().catch(() => ({}));
            if (!res.ok || out.success === false) throw new Error(out.error || `Request failed (HTTP ${res.status})`);
        });
        _crmSettings = { notify_email, enabled, quote_ready_enabled, wipe_fee };
        // The pricing screen reads the fee off the board payload, so refresh it
        // rather than leaving a stale figure on the next line someone flags.
        if (_b2bMeta) _b2bMeta.wipe_fee = wipe_fee;
        const m = document.getElementById('crmSetMsg');
        if (m) { m.textContent = 'Saved.'; setTimeout(() => { const e = document.getElementById('crmSetMsg'); if (e) e.textContent = ''; }, 2500); }
    } catch (e) { alert(`Couldn't save settings: ${e.message}`); }
}

function b2bEditClient(id) { _b2bEditingClient = id; b2bRender(); }

// Digits only, formatted as a US number and capped at 10 digits. A phone field
// that accepts prose is a phone field nobody can dial from.
function _b2bPhoneMask(el) {
    const d = el.value.replace(/\D/g, '').slice(0, 10);
    el.value = d.length > 6 ? `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`
             : d.length > 3 ? `(${d.slice(0, 3)}) ${d.slice(3)}`
             : d.length     ? `(${d}`
             : '';
}

async function b2bSaveClient() {
    const company = document.getElementById('b2bCfCompany')?.value.trim();
    const acronym = document.getElementById('b2bCfAcronym')?.value.trim().toUpperCase();
    if (!company) return alert('A company name is required.');
    if (!/^[A-Z0-9]{2,6}$/.test(acronym)) return alert('The acronym must be 2-6 letters or digits.');
    await _b2bPost({
        action: _b2bEditingClient ? 'update_client' : 'create_client',
        id: _b2bEditingClient || undefined,
        company, acronym,
        contact:       document.getElementById('b2bCfContact')?.value.trim(),
        contact_email: document.getElementById('b2bCfEmail')?.value.trim(),
        contact_phone: document.getElementById('b2bCfPhone')?.value.trim(),
        notes:         document.getElementById('b2bCfNotes')?.value.trim(),
    }, "Couldn't save the client");
    _b2bEditingClient = null;
    await b2bRefresh();
}

async function b2bDeleteClient(id) {
    const c = _b2bClients.find(x => x.id === id);
    if (!c) return;
    if (!confirm(`Delete "${c.company}"? This only works while they have no deals on record.`)) return;
    await _b2bPost({ action: 'delete_client', id }, "Couldn't delete the client");
    await b2bRefresh();
}

// --- view: Overview (DM/CEO) -----------------------------------------------

function _b2bRenderOverview(scoped) {
    const live = scoped.filter(d => d.stage !== 'completed' && d.stage !== 'declined');

    const card = (title, sub, head, body, empty) => `
        <div class="b2b-ov">
            <div class="b2b-ov-h"><div><span class="b2b-ov-t">${title}</span><span class="b2b-ov-s">${sub}</span></div></div>
            ${body ? `<table class="cb-table"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>`
                   : `<div class="b2b-doc-empty">${empty}</div>`}
        </div>`;

    // Stalled: nothing has moved in a week.
    const stalled = live.filter(d => _b2bDaysIn(d) >= 7).sort((a, b) => _b2bDaysIn(b) - _b2bDaysIn(a));
    const stalledRows = stalled.map(d => `
        <tr onclick="b2bOpenDeal('${_b2bClickKind(d)}','${d.id}')" class="b2b-clickrow">
            <td><span class="b2b-mono">${escapeHtml(d.ref)}</span></td>
            <td><b>${escapeHtml(d.client?.company || '')}</b></td>
            <td>${_b2bStageChip(d.stage, d)}</td>
            <td>${_b2bStoreTag(d.listing_store || d.pricing_store)}</td>
            <td class="r"><span class="b2b-age b2b-age-${_b2bAgeTone(_b2bDaysIn(d))}">${_b2bDaysIn(d)}d</span></td>
        </tr>`).join('');

    // Two stages, oldest first. The tile used to add both together and call the
    // total "awaiting a decision", which claimed the client was sitting on money
    // nobody had sent them -- while the table below said "not sent" about those
    // same deals. They are separate stages now, so the split is just a filter.
    const byAge = (a, b) => _b2bDaysIn(b) - _b2bDaysIn(a);
    const toApprove  = live.filter(d => d.stage === 'review').sort(byAge);
    const withClient = live.filter(d => d.stage === 'quote').sort(byAge);
    const quotes = [...toApprove, ...withClient];
    const quoteRows = quotes.map(d => `
        <tr onclick="b2bOpenDeal('${_b2bClickKind(d)}','${d.id}')" class="b2b-clickrow">
            <td><span class="b2b-mono">${escapeHtml(d.ref)}</span></td>
            <td><b>${escapeHtml(d.client?.company || '')}</b></td>
            <td>${escapeHtml(d.client?.contact_email || '—')}</td>
            <td class="c">${d.stage === 'review'
                ? '<span class="b2b-age b2b-age-warn">to approve</span>'
                : `sent ${d.quote_send_count || 1}×`}</td>
            <td class="r b">${_b2bMoney(_b2bNetOffer(d))}</td>
        </tr>`).join('');

    // Inventory bought and paid for that is not yet earning.
    const unlisted = live.filter(d => d.stage === 'listing' && _b2bOutstanding(d) > 0)
        .sort((a, b) => _b2bOutstanding(b) - _b2bOutstanding(a));
    const unlistedTotal = unlisted.reduce((s, d) => s + _b2bNetCost(d), 0);
    const unlistedRows = unlisted.map(d => `
        <tr onclick="b2bOpenDeal('${_b2bClickKind(d)}','${d.id}')" class="b2b-clickrow">
            <td><span class="b2b-mono">${escapeHtml(d.ref)}</span></td>
            <td><b>${escapeHtml(d.client?.company || '')}</b></td>
            <td>${_b2bStoreTag(d.listing_store)}</td>
            <td class="c">${_b2bOutstanding(d)} of ${d.total_units}</td>
            <td class="r b">${_b2bMoney(_b2bNetCost(d))}</td>
        </tr>`).join('');

    // Certified wipes across everything in flight. A wipe promised at pricing is
    // a debt from that moment: we have discounted the client for it, and the
    // units cannot be listed until someone certifies it.
    const wipesSold = live.reduce((n, d) => n + (Number(d.wipe_units) || 0), 0);
    const wipesDone = live.reduce((n, d) => n + (Number(d.wiped_units) || 0), 0);
    const wipesOwed = Math.max(0, wipesSold - wipesDone);
    const wipeFees  = live.reduce((s, d) => s + (Number(d.total_wipe_fee) || 0), 0);

    const tiles = `
        <div class="b2b-tiles">
            <div class="b2b-tile"><span class="b2b-tile-k">In Flight</span><span class="b2b-tile-v">${live.length}</span><span class="b2b-tile-c">deals moving</span></div>
            <div class="b2b-tile"><span class="b2b-tile-k">Out For Quote</span><span class="b2b-tile-v">${_b2bMoney(withClient.reduce((s, d) => s + _b2bNetOffer(d), 0))}</span><span class="b2b-tile-c">${withClient.length} awaiting a client decision${toApprove.length ? ` · ${toApprove.length} still to approve` : ''}</span></div>
            <div class="b2b-tile"><span class="b2b-tile-k">Unlisted Stock</span><span class="b2b-tile-v">${_b2bMoney(unlistedTotal)}</span><span class="b2b-tile-c">${unlisted.reduce((n, d) => n + _b2bOutstanding(d), 0)} units to list</span></div>
            <div class="b2b-tile ${stalled.length ? 'warn' : ''}"><span class="b2b-tile-k">Stalled</span><span class="b2b-tile-v">${stalled.length}</span><span class="b2b-tile-c">no movement in 7+ days</span></div>
            <!-- Certified wipes, which we charge for and therefore owe. Counted
                 across everything in flight, since a wipe promised at pricing is
                 outstanding until someone certifies it during listing. -->
            <div class="b2b-tile ${wipesOwed ? 'warn' : ''}"><span class="b2b-tile-k">Certified Wipes</span><span class="b2b-tile-v">${wipesDone}<span class="b2b-tile-of"> / ${wipesSold}</span></span><span class="b2b-tile-c">${wipesOwed ? `${wipesOwed} still to certify` : 'all certified'} · ${_b2bMoney(wipeFees)} discounted</span></div>
        </div>`;

    return tiles
        + card('Stalled Deals', 'No movement in a week or more',
               '<th>Ref</th><th>Client</th><th>Stage</th><th>Store</th><th class="r">In stage</th>',
               stalledRows, 'Everything is moving')
        + card('Open Quotes', 'Waiting on approval, or out with the client',
               '<th>Ref</th><th>Client</th><th>Email</th><th class="c">Sent</th><th class="r">Offer</th>',
               quoteRows, 'No quotes are open right now')
        + card('Bought But Not Listed', 'Inventory paid for and not yet earning',
               '<th>Ref</th><th>Client</th><th>Store</th><th class="c">Outstanding</th><th class="r">Cost</th>',
               unlistedRows, 'Everything accepted has been listed');
}

// ---------------------------------------------------------------------------
// NEW DEAL
// ---------------------------------------------------------------------------

// Raise an evaluation instead of a deal. Same modal, same picker.
function b2bOpenPrevalCreate() { b2bOpenCreate('preval'); }

function b2bOpenCreate(kind) {
    // The header button is role-gated in the markup, but the markup gate is a
    // CSS class -- this is what makes it true. The one way a permitted role gets
    // here and still can't create is having no store on their profile, which is
    // worth saying out loud rather than opening a modal that cannot be finished.
    if (!_b2bCanCreate()) {
        if (B2B_STORE_ROLES.includes(_b2bRole())) {
            alert("Your profile has no store on it, so there's nowhere to hold a new deal.\n\n"
                + 'Ask a DM to set your store, or have them raise the deal.');
        }
        return;
    }
    _b2bCreateKind = kind === 'preval' ? 'preval' : 'deal';
    _b2bCreateClientId = null;
    // Corp routes its pickups at pricing_location, so it picks nothing here. A
    // store is raising the deal for itself: one store means there is nothing to
    // decide, two (an MSM covers both of theirs) means there is.
    const mine = _b2bIsCorp() ? [] : _b2bMyStores();
    _b2bCreateStore = mine.length === 1 ? mine[0] : null;
    // A collection run is still the common case, and it is the one that asks for
    // the most, so it is the safe default: nobody is landed on a shorter form
    // than the situation deserves by not reading the screen.
    _b2bCreateIntake = 'pickup';
    _b2bRenderCreate();
    toggleModal('b2bCreateModal');
}

// Where a store-raised deal will be held. Null for corp, whose deals are routed
// a stage later by whoever assigns the pricing location.
let _b2bCreateStore = null;
// Which thing the create modal is raising. The client picker, the search box and
// the inline add-client form are identical either way -- only the fields below
// them and the button differ -- so the modal is shared rather than cloned.
let _b2bCreateKind = 'deal';
const _b2bCreatingPreval = () => _b2bCreateKind === 'preval';
// How it arrived -- see B2B_INTAKE. Set once here and never derived afterwards.
let _b2bCreateIntake = 'pickup';

function b2bPickCreateStore(code) {
    _b2bCreateStore = code;
    document.querySelectorAll('#b2bCreateStorePick .b2b-loc')
        .forEach(b => b.classList.toggle('on', b.dataset.loc === code));
    _b2bPaintPicklist();   // the Create button waits on this
}

function b2bPickCreateIntake(kind) {
    _b2bCreateIntake = B2B_INTAKE[kind] ? kind : 'pickup';
    document.querySelectorAll('#b2bCreateIntakePick .b2b-intake')
        .forEach(b => b.classList.toggle('on', b.dataset.kind === _b2bCreateIntake));
    _b2bPaintPicklist();   // the selection line spells out what will happen
}

// Offered to everyone who can create, not just stores: a store gets walk-ins at
// the counter, and corp gets the business that would rather drive to CORP than
// wait for a collection. Neither is rare enough to have no way of saying so.
function _b2bCreateIntakeBlock() {
    const opt = (key, title, sub) => `
        <button class="b2b-intake ${_b2bCreateIntake === key ? 'on' : ''}" data-kind="${key}"
            onclick="b2bPickCreateIntake('${key}')">
            <span class="b2b-intake-t">${title}</span>
            <span class="b2b-intake-s">${sub}</span>
        </button>`;
    return `
        <label class="form-label-caps" style="margin-top:14px;">How It Came In</label>
        <div class="b2b-intake-pick" id="b2bCreateIntakePick">
            ${opt('pickup', 'We collect it',
                  'A pickup run — records the date, who handed it over and who took it in.')}
            ${opt('walkin', 'In-store walk-in',
                  'They are at the counter now. No pickup date and no hand-off to record — describe it, sign for it, done.')}
        </div>`;
}

// The store half of the new-deal screen. Corp gets nothing: it has always
// chosen the location at the next stage, and asking twice would let the two
// answers disagree.
function _b2bCreateStoreBlock() {
    const mine = _b2bIsCorp() ? [] : _b2bMyStores();
    if (!mine.length) return '';
    if (mine.length === 1) {
        return `<div class="b2b-note">
            <span class="b2b-note-k">Holding at ${escapeHtml(mine[0])}</span>
            The goods stay with you to itemize and price. A DM, MOCD or the CEO
            can move it to another store at any point.</div>`;
    }
    return `
        <label class="form-label-caps" style="margin-top:14px;">Holding At</label>
        <div class="b2b-loc-pick" id="b2bCreateStorePick">
            ${mine.map(c => `
                <button class="b2b-loc ${c === _b2bCreateStore ? 'on' : ''}" data-loc="${c}"
                    onclick="b2bPickCreateStore('${c}')">
                    <span class="b2b-loc-dot" style="background:${STORE_TINTS[c] || '#94a3b8'}"></span>
                    <span class="b2b-loc-c">${c}</span>
                </button>`).join('')}
        </div>
        <p class="b2b-hint">Which of your stores is taking these in — it is where they
            will be priced.</p>`;
}

function _b2bRenderCreate() {
    const body = document.getElementById('b2bCreateBody');
    if (!body) return;
    // Anyone who may raise a deal may add the business it is for: a walk-in is
    // usually a company we have never dealt with, and a deal you cannot name the
    // client of is not one you can raise. The directory itself, the contact
    // details and the outreach cadence stay corp's.
    const addForm = _b2bCanCreate() ? `
        <details class="b2b-newclient" ${_b2bClients.length ? '' : 'open'}>
            <summary>Add a new client</summary>
            <div class="b2b-grid2">
                <div><label class="form-label-caps">Company *</label><input id="b2bNcCompany" class="form-input-lg" placeholder="Acme Corp"></div>
                <div><label class="form-label-caps">Acronym *</label><input id="b2bNcAcronym" class="form-input-lg b2b-mono" maxlength="6" placeholder="ACM" oninput="this.value=this.value.toUpperCase()"></div>
                <div><label class="form-label-caps">Contact</label><input id="b2bNcContact" class="form-input-lg" placeholder="Dana Reyes"></div>
                <div><label class="form-label-caps">Email</label><input id="b2bNcEmail" class="form-input-lg" placeholder="dana@acme.com"></div>
                <div><label class="form-label-caps">Phone</label><input id="b2bNcPhone" class="form-input-lg" placeholder="(816) 555-0142"></div>
            </div>
            <p class="b2b-hint">The acronym leads every SKU we print for this client, so it locks once they have a quoted deal.</p>
            <button class="b2b-btn b2b-btn-secondary" onclick="b2bCreateClientInline()">Add Client</button>
        </details>` : '';

    // The search box is written once and never re-rendered -- only the list and
    // the selection line below it repaint, so typing never loses focus.
    body.innerHTML = `
        <label class="form-label-caps">Client</label>
        <input id="b2bClientSearch" class="form-input-lg" autocomplete="off"
            placeholder="Search by company, acronym${_b2bIsCorp() ? ' or contact' : ''}…" oninput="_b2bPaintPicklist()">
        <div class="b2b-picklist" id="b2bPickList"></div>
        <div id="b2bPickSel"></div>
        ${_b2bCreatingPreval() ? _b2bCreatePrevalBlock() : _b2bCreateIntakeBlock() + _b2bCreateStoreBlock()}
        ${addForm}`;
    _b2bPaintPicklist();
}

// The evaluation half of the create modal. No intake kind and no holding store:
// nothing has been collected, so there is nothing to say about how it arrived or
// where it is sitting. Both questions get asked at conversion instead, when they
// have answers.
function _b2bCreatePrevalBlock() {
    const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
    return `
        <div class="b2b-grid2" style="margin-top:14px;">
            <div>
                <label class="form-label-caps">Evaluated On *</label>
                <input id="b2bPvDate" type="date" class="form-input-lg" value="${today}">
            </div>
            <div>
                <label class="form-label-caps">Good Until</label>
                <input id="b2bPvUntil" type="date" class="form-input-lg">
            </div>
        </div>
        <p class="b2b-hint">The date the figures are good as of — it prints on what the client
            sees. Leave "good until" blank if the quote does not expire.</p>
        <label class="form-label-caps" style="margin-top:14px;">Reference</label>
        <input id="b2bPvTitle" class="form-input-lg" placeholder="e.g. Q3 laptop refresh" maxlength="160">
        <label class="form-label-caps" style="margin-top:14px;">What They Say They Have</label>
        <textarea id="b2bPvSummary" class="form-input-lg" rows="3"
            placeholder="e.g. ~40 laptops, 12 monitors, a pallet of misc peripherals"></textarea>
        <p class="b2b-hint">Their own description, before anyone has seen it. This carries over
            to become the pickup description if the evaluation turns into a deal.</p>`;
}

// Corp answers "where" a stage later; a store answers it here, and until it has
// there is nothing to create.
function _b2bCreateReady() {
    if (!_b2bCreateClientId) return false;
    // An evaluation holds nothing, so there is no store to choose yet.
    if (_b2bCreatingPreval()) return true;
    if (_b2bIsCorp()) return true;
    return !!_b2bCreateStore;
}

function _b2bPaintPicklist() {
    const list = document.getElementById('b2bPickList');
    const sel  = document.getElementById('b2bPickSel');
    if (!list) return;
    const q = (document.getElementById('b2bClientSearch')?.value || '').toLowerCase().trim();
    const matches = _b2bClients.filter(c => !q
        || (c.company || '').toLowerCase().includes(q)
        || (c.acronym || '').toLowerCase().includes(q)
        || (c.contact || '').toLowerCase().includes(q)
        || (c.contact_email || '').toLowerCase().includes(q)).slice(0, 40);

    list.innerHTML = matches.length ? matches.map(c => `
        <button class="b2b-pick ${c.id === _b2bCreateClientId ? 'on' : ''}" onclick="b2bPickClient('${c.id}')">
            <span class="b2b-pick-ac">${escapeHtml(c.acronym)}</span>
            <span class="b2b-pick-co">${escapeHtml(c.company)}</span>
            <span class="b2b-pick-sub">${_b2bIsCorp() ? escapeHtml([c.contact, c.contact_email].filter(Boolean).join(' · ')) : ''}</span>
            ${c.open_count ? `<span class="b2b-pick-n">${c.open_count} open</span>` : ''}
        </button>`).join('')
        : `<div class="b2b-pick-empty">No clients match${_b2bCanCreate() ? ' — add one below.' : ' — ask a DM or CEO to add one.'}</div>`;

    const chosen = _b2bClients.find(c => c.id === _b2bCreateClientId);
    if (sel) {
        sel.innerHTML = chosen
            ? (_b2bCreatingPreval()
                ? `<div class="b2b-selected"><b>${escapeHtml(chosen.acronym)}</b> · ${escapeHtml(chosen.company)} — this will be evaluation <b class="b2b-mono">${escapeHtml(chosen.acronym)}-PE-${String(_b2bNextEvalNo(chosen.id)).padStart(3, '0')}</b></div>`
                : `<div class="b2b-selected"><b>${escapeHtml(chosen.acronym)}</b> · ${escapeHtml(chosen.company)} — this will be deal <b class="b2b-mono">${escapeHtml(chosen.acronym)}-${String((chosen.deal_count || 0) + 1).padStart(3, '0')}</b>${
                _b2bCreateStore ? `, held at <b>${escapeHtml(_b2bCreateStore)}</b>` : ''}${
                _b2bCreateIntake === 'walkin' ? ', taken in over the counter' : ''}</div>`)
            : '';
    }
    const foot = document.getElementById('b2bCreateFooter');
    if (foot) {
        foot.innerHTML = `
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Cancel</button>
            <button class="b2b-btn b2b-btn-primary" ${_b2bCreateReady() ? '' : 'disabled'} onclick="b2bCreateDeal()">${
                _b2bCreatingPreval() ? 'Create Evaluation' : 'Create Deal'}</button>`;
    }
}

function b2bPickClient(id) {
    _b2bCreateClientId = (_b2bCreateClientId === id) ? null : id;
    _b2bPaintPicklist();
}

async function b2bCreateClientInline() {
    const company = document.getElementById('b2bNcCompany')?.value.trim();
    const acronym = document.getElementById('b2bNcAcronym')?.value.trim().toUpperCase();
    if (!company) return alert('A company name is required.');
    if (!/^[A-Z0-9]{2,6}$/.test(acronym)) return alert('The acronym must be 2-6 letters or digits.');
    const out = await _b2bPost({
        action: 'create_client', company, acronym,
        contact: document.getElementById('b2bNcContact')?.value.trim(),
        contact_email: document.getElementById('b2bNcEmail')?.value.trim(),
        contact_phone: document.getElementById('b2bNcPhone')?.value.trim(),
    }, "Couldn't add the client");
    // Through the same scope gate as every other read, so a store manager who
    // just added a client gets it back stripped rather than in full.
    _b2bClients = await _b2bClientsFetch(_b2bClients);
    _b2bCreateClientId = out.id;
    _b2bRenderCreate();
}

async function b2bCreateDeal() {
    if (!_b2bCreateReady()) return;
    if (_b2bCreatingPreval()) return _b2bCreatePreval();
    const out = await _b2bPost({
        action: 'create', client_id: _b2bCreateClientId, created_by: _b2bUser(),
        // Corp sends nothing and the deal routes at pricing_location as it
        // always has. A store names itself, and the deal is holding there from
        // the moment it exists -- which is also what puts it on that store's
        // board, since scope is read off pricing_store.
        pricing_store: _b2bCreateStore || undefined,
        intake_kind: _b2bCreateIntake,
    }, "Couldn't create the deal");
    closeAllModals();
    await b2bRefresh();
    // Straight into the pickup form -- that's the whole point of creating it.
    b2bOpenDeal('pickup', out.id);
}


// ===========================================================================
// PRE-EVALUATIONS
// ---------------------------------------------------------------------------
// A client wants a number before we drive out. We price the list they describe;
// if they accept, it converts into a real deal with every line already filled
// in and a reference back to where those figures came from.
//
// The line editor is not rebuilt here. _b2bItemMode hands the existing pricing
// spreadsheet -- the inline saves, the totals, the margin, the detail sheet --
// straight to an evaluation, so the two screens cannot drift apart. What lives
// below is only what an evaluation has that a deal does not: a status, a pair of
// dates, and the conversion.
// ===========================================================================

function _b2bPrevalById(id) { return _b2bPrevals.find(v => v.id === id) || null; }
function _b2bPrevalMeta(v)  { return B2B_PREVAL_STATUS[v?.status] || B2B_PREVAL_STATUS.draft; }
function _b2bPrevalOpen(v)  { return B2B_PREVAL_OPEN.includes(v?.status); }

// Expired is derived, never stored: a stored flag would need a nightly job to
// stay true and would then have to argue with 'accepted' about which one the row
// is really in. Only meaningful while the client could still act on it.
function _b2bPrevalExpired(v) {
    if (!v?.valid_until) return false;
    if (['converted', 'declined'].includes(v.status)) return false;
    return v.valid_until < new Date().toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
}

// What the next evaluation for this client will be called. Counted off what is
// already on screen -- it is a preview for the create modal, and the server
// mints the real one.
function _b2bNextEvalNo(clientId) {
    const mine = _b2bPrevals.filter(v => v.client_id === clientId);
    return mine.reduce((n, v) => Math.max(n, Number(v.eval_no) || 0), 0) + 1;
}

async function _b2bCreatePreval() {
    const date = document.getElementById('b2bPvDate')?.value;
    if (!date) return alert('Pick the date this evaluation is good as of.');
    const until = document.getElementById('b2bPvUntil')?.value || '';
    if (until && until < date) return alert('"Good until" can\'t be before the evaluation date.');
    const out = await _b2bPost({
        action: 'preval_create',
        client_id: _b2bCreateClientId,
        eval_date: date,
        valid_until: until || undefined,
        title: document.getElementById('b2bPvTitle')?.value.trim(),
        summary: document.getElementById('b2bPvSummary')?.value.trim(),
        // Store users raise it for their own store, exactly as they raise a
        // deal; corp raises it unscoped.
        store: _b2bPrevalStore() || undefined,
        created_by: _b2bUser(),
    }, "Couldn't create the evaluation");
    closeAllModals();
    await b2bRefresh();
    // Straight into pricing it -- that is the whole point of raising one.
    b2bOpenPreval(out.id);
}

// --- view: Evaluations ------------------------------------------------------

function _b2bRenderPrevals() {
    const rows = _b2bPrevals;
    const live = rows.filter(v => !['converted', 'declined'].includes(v.status));
    const done = rows.filter(v => ['converted', 'declined'].includes(v.status));

    const card = (v) => {
        const meta    = _b2bPrevalMeta(v);
        const expired = _b2bPrevalExpired(v);
        const bits = [
            v.line_count ? `${v.line_count} line${v.line_count === 1 ? '' : 's'}` : 'No lines yet',
            v.total_units ? `${v.total_units} unit${v.total_units === 1 ? '' : 's'}` : null,
            `Evaluated ${_b2bDate(v.eval_date)}`,
            v.valid_until ? `${expired ? 'Expired' : 'Good until'} ${_b2bDate(v.valid_until)}` : null,
        ].filter(Boolean).map(t => `<span>${escapeHtml(t)}</span>`).join('');
        return `
        <div class="b2b-q-card" onclick="b2bOpenPreval('${v.id}')">
            <div class="b2b-q-main">
                <div class="b2b-q-top">
                    <span class="b2b-q-ref">${escapeHtml(v.ref)}</span>
                    <span class="b2b-q-co">${escapeHtml(v.company || 'Unknown client')}</span>
                    <span class="b2b-chip b2b-chip-${meta.tone}">${escapeHtml(meta.label)}</span>
                    ${expired ? '<span class="b2b-chip b2b-chip-crit">Expired</span>' : ''}
                    ${v.store ? _b2bStoreTag(v.store) : ''}
                </div>
                <div class="b2b-q-meta">${bits}${
                    v.title ? `<span>${escapeHtml(v.title)}</span>` : ''}</div>
            </div>
            <div class="b2b-q-act">
                <span class="b2b-q-why">${escapeHtml(
                    v.status === 'converted' && v.deal_ref ? `Became ${v.deal_ref}` : meta.why)}</span>
                <div class="b2b-q-btns">
                    <span class="b2b-pv-money">${_b2bMoney(v.net_offer)}</span>
                </div>
            </div>
        </div>`;
    };

    const empty = `
        <div class="b2b-empty">
            ${_b2bIco('<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>')}
            <div class="b2b-empty-t">No evaluations yet</div>
            <div class="b2b-empty-s">When a business wants a number before we collect anything,
                raise one here. Price their list, send it, and if they accept it becomes a deal
                with every line already filled in.</div>
        </div>`;

    return `
        <div class="b2b-sec">
            <div class="b2b-sec-h">
                <span>Open Evaluations</span><span class="b2b-sec-n">${live.length}</span>
                ${_b2bCanPreval() ? `<button class="b2b-btn b2b-btn-primary b2b-mini b2b-pv-new"
                    onclick="b2bOpenPrevalCreate()">＋ New Evaluation</button>` : ''}
            </div>
            <div class="b2b-queue">${live.length ? live.map(card).join('') : empty}</div>
        </div>
        ${done.length ? `
        <div class="b2b-sec">
            <div class="b2b-sec-h"><span>Closed</span><span class="b2b-sec-n">${done.length}</span></div>
            <div class="b2b-queue">${done.map(card).join('')}</div>
        </div>` : ''}`;
}

// --- the editor -------------------------------------------------------------

async function b2bOpenPreval(id) {
    const v = _b2bPrevalById(id);
    if (!v) return;
    // Claim the shared item editor before anything renders, so every inline save
    // on this screen posts preval_* rather than the deal actions.
    _b2bItemMode = 'preval';
    _b2bModalPreval = v;
    _b2bModalDeal = null;
    _b2bModalItems = [];
    _b2bProofs = [];
    await _b2bLoadProofs(id);
    try {
        _b2bModalItems = await _b2bGet(`preval_id=${encodeURIComponent(id)}`);
    } catch (e) {
        _b2bItemMode = 'deal';
        return alert(`Couldn't load the evaluation: ${e.message}`);
    }
    _b2bStagePreval(v);
}

function _b2bStagePreval(v) {
    _b2bGridMode = 'sheet';
    const meta    = _b2bPrevalMeta(v);
    const open    = _b2bPrevalOpen(v);
    const expired = _b2bPrevalExpired(v);
    const canMove = _b2bCanAccept();

    const dates = `
        <div class="b2b-grid2" style="margin-top:4px;">
            <div>
                <label class="form-label-caps">Evaluated On</label>
                <input id="b2bPvDate" type="date" class="form-input-lg" value="${escapeHtml(v.eval_date || '')}"
                    ${open ? '' : 'disabled'} onchange="b2bPrevalSaveMeta('${v.id}')">
            </div>
            <div>
                <label class="form-label-caps">Good Until</label>
                <input id="b2bPvUntil" type="date" class="form-input-lg" value="${escapeHtml(v.valid_until || '')}"
                    ${open ? '' : 'disabled'} onchange="b2bPrevalSaveMeta('${v.id}')">
            </div>
        </div>
        <label class="form-label-caps" style="margin-top:12px;">Reference</label>
        <input id="b2bPvTitle" class="form-input-lg" maxlength="160" value="${escapeHtml(v.title || '')}"
            placeholder="e.g. Q3 laptop refresh" ${open ? '' : 'disabled'}
            onchange="b2bPrevalSaveMeta('${v.id}')">
        <label class="form-label-caps" style="margin-top:12px;">What They Say They Have</label>
        <textarea id="b2bPvSummary" class="form-input-lg" rows="2" ${open ? '' : 'disabled'}
            placeholder="Their own description, before anyone has seen it"
            onchange="b2bPrevalSaveMeta('${v.id}')">${escapeHtml(v.summary || '')}</textarea>`;

    // Why the sheet is read-only, when it is. Said once and plainly, because the
    // alternative is a screen full of disabled inputs with no explanation.
    const frozen = open ? '' : `
        <div class="b2b-note ${v.status === 'declined' ? '' : 'ok'}">
            <span class="b2b-note-k">${escapeHtml(meta.label)}${
                v.status === 'converted' && v.deal_ref ? ` — became ${escapeHtml(v.deal_ref)}` : ''}</span>
            ${v.status === 'accepted'
                ? 'The client has agreed to these figures, so the lines are locked. Reopen it as a draft if something has to change before it becomes a deal.'
                : v.status === 'converted'
                ? 'This became a deal. Change the lines on the deal itself — this record is what says where its prices came from.'
                : escapeHtml(v.declined_reason || 'This evaluation is closed.')}
        </div>`;

    const expiredNote = expired ? `
        <div class="b2b-note warn">
            <span class="b2b-note-k">Past its date</span>
            This was only good until ${escapeHtml(_b2bDate(v.valid_until))}. Re-price it or move
            the date before treating it as live.
        </div>` : '';

    _b2bShowDeal({
        stage: 'pricing',
        noPrint: true,
        eyebrow: v.ref,
        title: 'Pre-Evaluation',
        sub: `${v.company || 'Client'} — priced before we collect anything.`,
        full: true,
        body: `
            ${frozen}${expiredNote}
            ${dates}
            ${_b2bTotalsBar(true)}
            ${_b2bCustPanel(_b2bQuoteSubject_src())}
            <div id="b2bItemGrid" class="b2b-items b2b-ss">${_b2bItemSheet()}</div>
            ${_b2bDispLegend()}
            ${open ? `<button class="b2b-btn b2b-btn-secondary b2b-add"
                onclick="b2bAddItem('${v.id}',this)">＋ Add Line Item</button>` : ''}`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            ${_b2bPrevalActions(v, canMove)}
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Close</button>`,
        after: _b2bPaintTotals,
    });
}

// The one action this evaluation is waiting on, plus the way back. Mirrors the
// deal footers: the forward move is primary, the way back is quiet.
function _b2bPrevalActions(v, canMove) {
    const id = v.id;
    if (v.status === 'converted') {
        return v.converted_deal_id
            ? `<button class="b2b-btn b2b-btn-primary" onclick="b2bOpenPrevalDeal('${id}')">Open ${escapeHtml(v.deal_ref || 'Deal')}</button>`
            : '';
    }
    if (!canMove) {
        return `<span class="b2b-msg" style="color:var(--cb-muted);font-weight:600;">A CEO, MOCD or DM sends and accepts evaluations.</span>`;
    }
    if (v.status === 'draft') {
        return `<button class="b2b-btn b2b-btn-primary" onclick="b2bPrevalStatus('${id}','sent',this)">Send To Client</button>`;
    }
    if (v.status === 'sent') {
        return `
            <button class="b2b-btn b2b-btn-secondary" onclick="b2bPrevalStatus('${id}','draft',this)">Back To Draft</button>
            <button class="b2b-btn b2b-btn-danger" onclick="b2bPrevalStatus('${id}','declined',this)">They Passed</button>
            <button class="b2b-btn b2b-btn-primary" onclick="b2bPrevalStatus('${id}','accepted',this)">They Accepted</button>`;
    }
    if (v.status === 'accepted') {
        return `
            <button class="b2b-btn b2b-btn-secondary" onclick="b2bPrevalStatus('${id}','draft',this)">Reopen For Changes</button>
            <button class="b2b-btn b2b-btn-primary" onclick="b2bOpenPrevalConvert('${id}')">Turn Into A Deal</button>`;
    }
    // declined
    return `<button class="b2b-btn b2b-btn-secondary" onclick="b2bPrevalStatus('${id}','draft',this)">Reopen</button>`;
}

function b2bOpenPrevalDeal(id) {
    const v = _b2bPrevalById(id);
    if (!v?.converted_deal_id) return;
    const deal = _b2bDealById(v.converted_deal_id);
    if (!deal) return alert('That deal is not on your board — it may belong to another store.');
    b2bOpenDeal(_b2bClickKind(deal), deal.id);
}

// Header fields save on blur, the same fire-and-forget the line grid uses.
async function b2bPrevalSaveMeta(id) {
    const date  = document.getElementById('b2bPvDate')?.value;
    const until = document.getElementById('b2bPvUntil')?.value || '';
    if (until && date && until < date) {
        return _b2bSay('"Good until" can\'t be before the evaluation date.', true);
    }
    try {
        await _b2bSend({
            action: 'preval_update', id,
            eval_date: date,
            valid_until: until || undefined,
            title: document.getElementById('b2bPvTitle')?.value.trim(),
            summary: document.getElementById('b2bPvSummary')?.value.trim(),
            evaluated_by: _b2bUser(),
        });
        _b2bDirty = true;
    } catch (e) {
        _b2bSay(`Couldn't save that: ${e.message}`, true);
    }
}

async function b2bPrevalStatus(id, to, btn) {
    const v = _b2bPrevalById(id);
    if (!v) return;
    let reason = null;
    if (to === 'declined') {
        reason = prompt('Why did they pass?\n\nThis is recorded against the evaluation so the '
            + 'next conversation with this client starts from what happened last time.');
        if (reason === null) return;
        if (!reason.trim()) return alert('A reason is required.');
    }
    if (to === 'accepted' && !confirm(
        `Mark ${v.ref} accepted?\n\nThe lines lock at these figures — they are what will convert `
        + 'into the deal. You can reopen it as a draft if something has to change.')) return;
    if (to === 'sent' && !confirm(
        `Send ${v.ref} to the client?\n\nThis records that the figures went out. `
        + 'The lines stay editable while they think about it.')) return;

    try {
        await _b2bBusy(btn, 'Saving…', () =>
            _b2bSend({ action: 'preval_status', id, status: to, reason: reason || undefined }));
        await b2bRefresh();
        const fresh = _b2bPrevalById(id);
        if (fresh) b2bOpenPreval(id); else closeAllModals();
    } catch (e) {
        alert(`Couldn't update the evaluation: ${e.message}`);
    }
}

// --- conversion -------------------------------------------------------------
// The same two questions New Deal asks, asked here for the first time: an
// evaluation had no goods, so where they will sit and how they will arrive only
// become answerable now.

let _b2bConvStore  = null;
let _b2bConvIntake = 'pickup';

function b2bOpenPrevalConvert(id) {
    const v = _b2bPrevalById(id);
    if (!v) return;
    const mine = _b2bIsCorp() ? [] : _b2bMyStores();
    _b2bConvStore  = v.store || (mine.length === 1 ? mine[0] : null);
    _b2bConvIntake = 'pickup';
    const options = _b2bIsCorp() ? STORE_CODES : (mine.length ? mine : STORE_CODES);

    _b2bShowDeal({
        stage: 'pickup',
        noPrint: true,
        eyebrow: v.ref,
        title: 'Turn Into A Deal',
        sub: `${v.line_count} line${v.line_count === 1 ? '' : 's'} carry straight over, already priced.`,
        body: `
            <div class="b2b-note ok">
                <span class="b2b-note-k">What happens</span>
                A new deal opens at pickup for ${escapeHtml(v.company || 'this client')} with every
                line from this evaluation already on it, priced as quoted. It still needs collecting
                and signing for — and the lines stay editable once it reaches pricing, so anything
                that turns out different in person can be corrected there.
            </div>
            <label class="form-label-caps" style="margin-top:14px;">Holding At</label>
            <div class="b2b-loc-pick" id="b2bConvStorePick">
                ${options.map(c => `
                    <button class="b2b-loc ${c === _b2bConvStore ? 'on' : ''}" data-loc="${c}"
                        onclick="b2bPickConvStore('${c}')">
                        <span class="b2b-loc-dot" style="background:${STORE_TINTS[c] || '#94a3b8'}"></span>
                        <span class="b2b-loc-c">${c}</span>
                    </button>`).join('')}
            </div>
            <p class="b2b-hint">Which store takes these in. ${_b2bIsCorp()
                ? 'Leave it unpicked and the deal routes at the pricing-location stage as usual.'
                : 'This is where the goods will be priced.'}</p>
            ${_b2bConvIntakeBlock()}`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            <button class="kpi-cancel-btn" onclick="b2bOpenPreval('${v.id}')">Cancel</button>
            <button class="b2b-btn b2b-btn-primary" onclick="b2bDoPrevalConvert('${v.id}',this)">Create The Deal</button>`,
    });
}

function _b2bConvIntakeBlock() {
    const opt = (key, title, sub) => `
        <button class="b2b-intake ${_b2bConvIntake === key ? 'on' : ''}" data-kind="${key}"
            onclick="b2bPickConvIntake('${key}')">
            <span class="b2b-intake-t">${title}</span>
            <span class="b2b-intake-s">${sub}</span>
        </button>`;
    return `
        <label class="form-label-caps" style="margin-top:14px;">How It Will Come In</label>
        <div class="b2b-intake-pick" id="b2bConvIntakePick">
            ${opt('pickup', 'We collect it', 'A pickup run — records the date and the hand-off.')}
            ${opt('walkin', 'They bring it in', 'Straight to a counter. No pickup date, no hand-off.')}
        </div>`;
}

function b2bPickConvStore(code) {
    _b2bConvStore = (_b2bConvStore === code) ? null : code;
    document.querySelectorAll('#b2bConvStorePick .b2b-loc')
        .forEach(b => b.classList.toggle('on', b.dataset.loc === _b2bConvStore));
}
function b2bPickConvIntake(kind) {
    _b2bConvIntake = kind;
    document.querySelectorAll('#b2bConvIntakePick .b2b-intake')
        .forEach(b => b.classList.toggle('on', b.dataset.kind === kind));
}

async function b2bDoPrevalConvert(id, btn) {
    const v = _b2bPrevalById(id);
    if (!v) return;
    // A store user has to say where, for the same reason they do on a new deal:
    // without a store the deal is invisible to the people holding the goods.
    if (!_b2bIsCorp() && !_b2bConvStore) {
        return _b2bSay('Pick which store is taking these in.', true);
    }
    try {
        const out = await _b2bBusy(btn, 'Creating…', () => _b2bSend({
            action: 'preval_convert', id,
            pricing_store: _b2bConvStore || undefined,
            intake_kind: _b2bConvIntake,
        }));
        _b2bDirty = false;
        closeAllModals();
        await b2bRefresh();
        alert(`${v.ref} is now deal ${out.ref} — ${out.lines} line${out.lines === 1 ? '' : 's'} carried over.`);
        const deal = _b2bDealById(out.deal_id);
        if (deal) b2bOpenDeal('pickup', deal.id);
    } catch (e) {
        alert(`Couldn't turn that into a deal: ${e.message}`);
    }
}

// ===========================================================================
// APPROVAL EVIDENCE
// ---------------------------------------------------------------------------
// The dispute this exists for: a client says they never agreed to the price, and
// the only thing on file is that somebody here ticked "accepted". That tick is
// our word. This holds theirs -- their email, or a screenshot of it.
//
// Modelled on the pickup signature, which answers the same question one stage
// earlier: evidence, or an attributed reason for going without, never silently
// neither. Accepting a quote now checks for one of the two.
//
// Attaches to a deal OR an evaluation. An accepted evaluation converts into a
// deal at exactly its prices, so it carries the same argument.
// ===========================================================================

const B2B_PROOF_KINDS = [
    { key: 'email',      label: 'Their email',   hint: 'Paste it whole, headers and all — that is the strongest version of it' },
    { key: 'screenshot', label: 'Screenshot',    hint: 'A picture of the email, or of a text message' },
    { key: 'document',   label: 'Document',      hint: 'A signed PDF, a purchase order' },
    { key: 'note',       label: 'Written note',  hint: 'Approved over the phone or across the counter — say who, when and what they said' },
];
const _b2bProofKind = (k) => B2B_PROOF_KINDS.find(x => x.key === k) || B2B_PROOF_KINDS[0];

// Live evidence only. A withdrawn entry stays on the record so the removal is
// visible, but it stops counting toward "is this approved".
function _b2bLiveProofs() { return _b2bProofs.filter(p => !p.removed_at); }
function _b2bApprovalOnRecord(owner) {
    return !!owner?.approval_waived_by || _b2bLiveProofs().length > 0;
}

// Whether the last fetch actually told us anything. This is not bookkeeping for
// its own sake -- the acceptance gate reads it, and a gate that cannot tell
// "there is no approval on file" from "I could not find out" is a gate that
// stops the business every time the network hiccups.
let _b2bProofsOk = false;

async function _b2bLoadProofs(ownerId) {
    _b2bProofs = [];
    _b2bProofsOk = false;
    try {
        const rows = await _b2bGet(`proofs=${encodeURIComponent(ownerId)}`);
        // Shape-checked, not just awaited. A server that predates this feature
        // does not 404 on ?proofs= -- the parameter is simply unrecognised and
        // the request falls through to the board read, which answers 200 with a
        // list of DEALS. Taking that at face value would paint deals as
        // evidence. Every real proof row carries added_by.
        if (!Array.isArray(rows)) return;
        if (rows.length && !('added_by' in rows[0])) return;
        _b2bProofs = rows;
        _b2bProofsOk = true;
    } catch (_) {
        // Left as "we do not know", which the gate treats as permission to
        // proceed rather than as an absence of approval.
    }
}

// The panel that sits on the quote and review screens, and stays on the deal
// forever afterwards -- the argument it exists for happens months later.
function _b2bProofPanel(owner) {
    if (!owner) return '';
    const live = _b2bLiveProofs();
    const gone = _b2bProofs.filter(p => p.removed_at);
    const waived = owner.approval_waived_by;
    const ok = live.length > 0 || waived;

    const row = (p) => {
        const k = _b2bProofKind(p.kind);
        const who = [p.from_addr, p.sent_on ? _b2bDate(p.sent_on) : ''].filter(Boolean).join(' · ');
        return `
        <div class="b2b-proof ${p.removed_at ? 'gone' : ''}">
            <div class="b2b-proof-main">
                <div class="b2b-proof-t">
                    <span class="b2b-chip b2b-chip-${p.removed_at ? 'neu' : 'ok'}">${escapeHtml(k.label)}</span>
                    ${p.label ? `<b>${escapeHtml(p.label)}</b>` : ''}
                    ${who ? `<span class="b2b-proof-from">${escapeHtml(who)}</span>` : ''}
                </div>
                ${p.body_text ? `<pre class="b2b-proof-body">${escapeHtml(p.body_text)}</pre>` : ''}
                <div class="b2b-proof-meta">
                    Added by ${escapeHtml(p.added_by)} · ${escapeHtml(_b2bDate(p.added_at))}
                    ${p.removed_at ? ` · withdrawn by ${escapeHtml(p.removed_by || '')}: ${escapeHtml(p.removed_reason || '')}` : ''}
                </div>
            </div>
            <div class="b2b-proof-acts">
                ${p.file_path ? `<a class="b2b-mini" target="_blank" rel="noopener"
                    href="${B2B_URL}?proof_file=${encodeURIComponent(p.id)}">Open file</a>` : ''}
                ${!p.removed_at && _b2bCanAccept()
                    ? `<button class="b2b-mini" onclick="b2bRemoveProof('${p.id}')">Withdraw</button>` : ''}
            </div>
        </div>`;
    };

    const ownerAttr = owner.eval_no !== undefined
        ? `'${owner.id}','preval'` : `'${owner.id}','deal'`;

    return `
        <div class="b2b-note b2b-proofwrap ${ok ? 'ok' : 'warn'}">
            <span class="b2b-note-k">${ok ? "The client's approval is on record" : "No approval on record yet"}</span>
            ${waived ? `<div class="b2b-proof-waived">Accepted without written approval by
                ${escapeHtml(waived)} — ${escapeHtml(owner.approval_waived_reason || '')}</div>` : ''}
            ${!ok ? `<div>Attach the client's email or a screenshot of it before this is accepted.
                It is what answers them later if they say they never agreed to the price.</div>` : ''}
            ${live.map(row).join('')}
            ${gone.length ? `<details class="b2b-proof-gone"><summary>${gone.length} withdrawn</summary>${gone.map(row).join('')}</details>` : ''}
            <div class="b2b-proof-add">
                <button class="b2b-btn b2b-btn-secondary b2b-mini" onclick="b2bOpenProofAdd(${ownerAttr})">＋ Attach approval</button>
                ${!ok && _b2bCanAccept()
                    ? `<button class="b2b-mini" onclick="b2bWaiveApproval(${ownerAttr})">No written approval — record why</button>` : ''}
            </div>
        </div>`;
}

// --- attaching -------------------------------------------------------------

let _b2bProofOwner = null;      // { id, kind: 'deal' | 'preval' }
let _b2bProofKindPick = 'email';
let _b2bProofFile = null;       // { name, mime, dataUri, bytes }

function b2bOpenProofAdd(ownerId, ownerKind) {
    _b2bProofOwner = { id: ownerId, kind: ownerKind };
    _b2bProofKindPick = 'email';
    _b2bProofFile = null;
    _b2bPaintProofModal();
    toggleModal('b2bProofModal');
}

function b2bPickProofKind(k) {
    _b2bProofKindPick = k;
    _b2bPaintProofModal();
}

function _b2bPaintProofModal() {
    const body = document.getElementById('b2bProofBody');
    if (!body) return;
    const k = _b2bProofKind(_b2bProofKindPick);
    // Kept: whatever has been typed already, so switching kind mid-entry does
    // not throw the work away.
    const keepLabel = document.getElementById('b2bPfLabel')?.value || '';
    const keepFrom  = document.getElementById('b2bPfFrom')?.value || '';
    const keepDate  = document.getElementById('b2bPfDate')?.value || '';
    const keepBody  = document.getElementById('b2bPfBody')?.value || '';

    body.innerHTML = `
        <label class="form-label-caps">What is it</label>
        <div class="b2b-intake-pick" id="b2bPfKinds">
            ${B2B_PROOF_KINDS.map(x => `
                <button class="b2b-intake ${x.key === _b2bProofKindPick ? 'on' : ''}" data-kind="${x.key}"
                    onclick="b2bPickProofKind('${x.key}')">
                    <span class="b2b-intake-t">${escapeHtml(x.label)}</span>
                    <span class="b2b-intake-s">${escapeHtml(x.hint)}</span>
                </button>`).join('')}
        </div>
        <div class="b2b-grid2" style="margin-top:14px;">
            <div><label class="form-label-caps">From</label>
                <input id="b2bPfFrom" class="form-input-lg" placeholder="dana@acme.com" value="${escapeHtml(keepFrom)}"></div>
            <div><label class="form-label-caps">Dated</label>
                <input id="b2bPfDate" type="date" class="form-input-lg" value="${escapeHtml(keepDate)}"></div>
        </div>
        <label class="form-label-caps" style="margin-top:12px;">Label</label>
        <input id="b2bPfLabel" class="form-input-lg" maxlength="200" value="${escapeHtml(keepLabel)}"
            placeholder="e.g. Dana confirming the revised numbers">
        <label class="form-label-caps" style="margin-top:12px;">${
            _b2bProofKindPick === 'note' ? 'What was said' : 'Paste the email'}</label>
        <textarea id="b2bPfBody" class="form-input-lg" rows="7" placeholder="${
            _b2bProofKindPick === 'note'
                ? 'Who approved it, when, and what they actually said.'
                : 'Paste the whole thing including the From / Sent / Subject lines — the headers are the part that proves it came from them.'
        }">${escapeHtml(keepBody)}</textarea>
        <p class="b2b-hint">${escapeHtml(k.hint)}</p>
        <label class="form-label-caps" style="margin-top:12px;">Or attach a file</label>
        <input id="b2bPfFile" type="file" class="form-input-lg"
            accept="image/png,image/jpeg,image/webp,application/pdf,message/rfc822,.eml,text/plain"
            onchange="b2bProofFilePicked(this)">
        <p class="b2b-hint">PNG, JPEG, PDF or a saved .eml, up to 6MB. You can paste the text, attach
            a file, or both — one of the two is enough.</p>
        <div id="b2bPfFileState"></div>`;

    const foot = document.getElementById('b2bProofFooter');
    if (foot) {
        foot.innerHTML = `
            <span class="b2b-msg" id="b2bPfMsg"></span>
            <button class="kpi-cancel-btn" onclick="closeAllModals()">Cancel</button>
            <button class="b2b-btn b2b-btn-primary" onclick="b2bSaveProof(this)">Attach</button>`;
    }
    if (_b2bProofFile) _b2bPaintProofFile();
}

function _b2bPaintProofFile() {
    const el = document.getElementById('b2bPfFileState');
    if (!el) return;
    el.innerHTML = _b2bProofFile
        ? `<div class="b2b-note ok"><span class="b2b-note-k">Attached</span>
             ${escapeHtml(_b2bProofFile.name)} · ${Math.max(1, Math.round(_b2bProofFile.bytes / 1024))} KB</div>`
        : '';
}

// Read once, here, rather than at save time: a file input's contents can be
// gone by the time an async save runs if the dialog has been touched since.
function b2bProofFilePicked(input) {
    const f = input.files && input.files[0];
    if (!f) { _b2bProofFile = null; _b2bPaintProofFile(); return; }
    if (f.size > 6_000_000) {
        _b2bProofFile = null;
        _b2bPaintProofFile();
        return alert(`That file is ${Math.round(f.size / 1e6)}MB — the limit is 6MB.\n\n`
            + 'A screenshot of the relevant part is usually enough.');
    }
    const r = new FileReader();
    r.onload = () => {
        _b2bProofFile = { name: f.name, mime: f.type || 'application/octet-stream',
                          dataUri: String(r.result || ''), bytes: f.size };
        _b2bPaintProofFile();
    };
    r.onerror = () => { _b2bProofFile = null; alert("Couldn't read that file."); };
    r.readAsDataURL(f);
}

async function b2bSaveProof(btn) {
    if (!_b2bProofOwner) return;
    const text = document.getElementById('b2bPfBody')?.value.trim() || '';
    if (!text && !_b2bProofFile) {
        return _b2bSay('Paste the email or attach a file — one or the other.', true);
    }
    const payload = {
        action: 'add_proof',
        kind: _b2bProofKindPick,
        label: document.getElementById('b2bPfLabel')?.value.trim(),
        from_addr: document.getElementById('b2bPfFrom')?.value.trim(),
        sent_on: document.getElementById('b2bPfDate')?.value || undefined,
        body_text: text || undefined,
        file: _b2bProofFile?.dataUri,
    };
    payload[_b2bProofOwner.kind === 'preval' ? 'preval_id' : 'deal_id'] = _b2bProofOwner.id;
    try {
        await _b2bBusy(btn, 'Attaching…', () => _b2bSend(payload));
        const owner = _b2bProofOwner;
        closeAllModals();
        await _b2bLoadProofs(owner.id);
        await b2bRefresh();
        // Straight back to whatever it was attached to, so the panel shows it.
        if (owner.kind === 'preval') b2bOpenPreval(owner.id);
        else { const d = _b2bDealById(owner.id); if (d) b2bOpenDeal(_b2bClickKind(d), d.id); }
    } catch (e) {
        alert(`Couldn't attach that: ${e.message}`);
    }
}

async function b2bRemoveProof(id) {
    const reason = prompt('Withdraw this piece of evidence.\n\nSay why — the entry stays on the '
        + 'record with your name against it, because an evidence log that can be quietly '
        + 'pruned is worth much less in the argument it exists for.');
    if (reason === null) return;
    if (!reason.trim()) return alert('A reason is required.');
    try {
        await _b2bSend({ action: 'remove_proof', id, reason: reason.trim() });
        const owner = _b2bEditParent();
        if (owner) { await _b2bLoadProofs(owner.id); }
        await b2bRefresh();
        if (_b2bModalPreval) b2bOpenPreval(_b2bModalPreval.id);
        else if (_b2bModalDeal) b2bOpenDeal(_b2bClickKind(_b2bModalDeal), _b2bModalDeal.id);
    } catch (e) {
        alert(`Couldn't withdraw that: ${e.message}`);
    }
}

async function b2bWaiveApproval(ownerId, ownerKind) {
    const reason = prompt('Accept WITHOUT the client\'s written approval.\n\n'
        + 'Say how they approved — who said it, when, and by what means. This is recorded '
        + 'against your name and it is what stands in for their email if they ever say '
        + 'they never agreed.');
    if (reason === null) return;
    if (!reason.trim()) return alert('A reason is required.');
    const payload = { action: 'waive_approval', reason: reason.trim() };
    payload[ownerKind === 'preval' ? 'preval_id' : 'deal_id'] = ownerId;
    try {
        await _b2bSend(payload);
        await b2bRefresh();
        if (ownerKind === 'preval') b2bOpenPreval(ownerId);
        else { const d = _b2bDealById(ownerId); if (d) b2bOpenDeal(_b2bClickKind(d), d.id); }
    } catch (e) {
        alert(`Couldn't record that: ${e.message}`);
    }
}

// The one gate, shared by every path that accepts. Returns true when it is safe
// to go ahead; otherwise it has already told the user what is missing.
function _b2bApprovalGate(owner) {
    // Fail OPEN when we could not read the evidence. The server enforces this
    // too, and it is the authority; this copy exists to explain the rule before
    // somebody hits it, not to be the thing that stops them. Blocking on a
    // failed fetch would mean a deploy window, or one bad request, halts every
    // acceptance in the company.
    if (!_b2bProofsOk) return true;
    if (_b2bApprovalOnRecord(owner)) return true;
    alert("The client's approval isn't on record yet.\n\n"
        + 'Open the deal and attach their email or a screenshot of it — or, if they approved '
        + 'by phone or in person, record that instead. This is what answers them later if '
        + 'they say they never agreed to the price.');
    return false;
}

// ---------------------------------------------------------------------------
// DEAL MODAL -- one shell, one renderer per stage
// ---------------------------------------------------------------------------

function _b2bShowDeal(cfg) {
    const stage = B2B_STAGE[cfg.stage] || B2B_STAGE.pickup;
    document.getElementById('b2bDealIco').innerHTML     = _b2bIco(cfg.svg || stage.svg);
    document.getElementById('b2bDealEyebrow').textContent = cfg.eyebrow || 'B2B';
    document.getElementById('b2bDealTitle').textContent   = cfg.title || 'Deal';
    document.getElementById('b2bDealSub').textContent     = cfg.sub || '';
    document.getElementById('b2bDealBody').innerHTML      = cfg.body || '';
    document.getElementById('b2bDealFooter').innerHTML    = cfg.footer || '';
    // SKU label print becomes available once the pickup is dropped at its
    // assigned pricing location — i.e. from the pricing stage onward.
    // ...and never on a screen that has no deal behind it: b2bPrintPickup reads
    // _b2bModalDeal, so an evaluation borrowing this shell would print the last
    // deal somebody happened to open.
    const pb = document.getElementById('b2bDealPrintBtn');
    if (pb) {
        pb.style.display = (!cfg.noPrint
            && ['pricing', 'review', 'quote', 'listing_location', 'listing', 'completed'].includes(cfg.stage))
            ? '' : 'none';
    }
    // The deletion trashcan -- shown on every deal screen (cfg.delDeal), hidden on
    // non-deal modals (the decline form, the Delete Requests queue, evaluations).
    // Not pending -> a request button; pending -> an amber 'Delete requested' that
    // opens the queue so CORP can approve or deny.
    const db = document.getElementById('b2bDealDeleteBtn');
    if (db) {
        const dd = cfg.delDeal;
        if (dd && dd.id) {
            const pending = !!dd.delete_requested_at;
            db.style.display = '';
            db.classList.toggle('pending', pending);
            db.title = pending
                ? `Delete requested${dd.delete_requested_by ? ' by ' + dd.delete_requested_by : ''} — a CEO, MOCD or DM approves it in Delete Requests`
                : 'Request this deal be deleted — a CEO, MOCD or DM must approve';
            const lbl = document.getElementById('b2bDealDeleteLbl');
            if (lbl) lbl.textContent = pending ? 'Delete requested' : 'Request deletion';
        } else {
            db.style.display = 'none';
            db.classList.remove('pending');
        }
    }
    const modal = document.getElementById('b2bDealModal');
    modal.classList.toggle('b2b-modal-wide', !!cfg.wide);
    // Pricing runs near-full-screen so a long pickup reads as one dense sheet.
    modal.classList.toggle('b2b-modal-full', !!cfg.full);
    closeAllModals();
    modal.classList.add('show');
    lockAndBlurScreen();
    if (cfg.after) cfg.after();
}

async function b2bOpenDeal(kind, id) {
    const deal = _b2bDealById(id);
    if (!deal) return;
    // Claim the shared item editor for deals. Never inherited: an evaluation
    // opened earlier in the session would otherwise still own it, and every save
    // on this screen would go to the wrong table.
    _b2bItemMode = 'deal';
    _b2bModalPreval = null;
    _b2bModalDeal = deal;
    _b2bModalItems = [];
    // Default every screen to the card grid; only pricing opts into the sheet.
    _b2bGridMode = 'cards';
    // The approval evidence rides along with the deal from the quote stage on:
    // that is where it is captured, and it stays visible forever afterwards
    // because the argument it exists for happens months later.
    _b2bProofs = [];
    if (['quote', 'listing', 'view'].includes(kind)) await _b2bLoadProofs(deal.id);
    // Every stage past pricing needs the line items; fetch once up front.
    if (['pricing', 'quote', 'listing', 'view'].includes(kind)) {
        try {
            _b2bModalItems = await _b2bGet(`deal_id=${encodeURIComponent(id)}`);
        } catch (e) {
            return alert(`Couldn't load the line items: ${e.message}`);
        }
    }
    if (kind === 'pickup')       return _b2bStagePickup(deal);
    if (kind === 'assign')       return _b2bStageAssign(deal);
    if (kind === 'pricing')      return _b2bStagePricing(deal);
    if (kind === 'quote')        return _b2bStageQuote(deal);
    if (kind === 'listloc')      return _b2bStageListingLocation(deal);
    if (kind === 'listing')      return _b2bStageListing(deal);
    return _b2bStageView(deal);
}

// The identity block every stage screen opens with. A store prices and lists
// the goods; talking to the client is corp's job, so the contact details are
// corp-only -- a store never needs them and shouldn't be the one reaching out.
function _b2bSummary(deal) {
    const rows = [
        ['Client',    escapeHtml(deal.client?.company || '—')],
        ['Reference', `<span class="b2b-mono">${escapeHtml(deal.ref)}</span>`],
    ];
    if (_b2bIsCorp()) {
        // One fact per cell. The phone was already being fetched and never shown,
        // so anyone needing to ring the client went back out to the Clients list.
        // Adding it also forced the email out of the Contact cell: name and email
        // were joined with a "·", and in a cell this narrow that wrapped and left
        // a separator dangling at the end of the line.
        rows.push(['Contact', escapeHtml(deal.client?.contact || '—')]);
        if (deal.client?.contact_email) rows.push(['Email', escapeHtml(deal.client.contact_email)]);
        if (deal.client?.contact_phone) rows.push(['Phone', escapeHtml(deal.client.contact_phone)]);
    }
    rows.push(
        [_b2bIntake(deal).was, deal.pickup_date ? _b2bDate(deal.pickup_date) : 'Not yet'],
        ['Pricing',   _b2bStoreTag(deal.pricing_store)],
    );
    if (deal.listing_store) rows.push(['Listing', _b2bStoreTag(deal.listing_store)]);
    if (deal.signed_by)     rows.push(['Signed by', escapeHtml(deal.signed_by)]);
    if (deal.delivered_by || deal.received_by) {
        // Reads in the order it happened: who handed it over, then who took it in.
        // A walk-in has no first half -- nobody collected it -- so it only ever
        // shows the second, and the label for a hand-off that never happened
        // would be a small lie on every one of them.
        const handoff = _b2bIntake(deal).key === 'walkin' ? 'Brought in by'
            : deal.pricing_store === 'CORP' ? 'Dropped off by' : 'Picked up by';
        rows.push(['Custody', escapeHtml([deal.delivered_by ? `${handoff} ${deal.delivered_by}` : '',
                                          deal.received_by ? `received by ${deal.received_by}` : ''].filter(Boolean).join(', '))]);
    }
    return `<div class="b2b-summary">${rows.map(([k, v]) =>
        `<div class="b2b-sum-cell"><span class="b2b-sum-k">${k}</span><span class="b2b-sum-v">${v}</span></div>`).join('')}</div>`;
}

// --- stage 1: pickup sign-off ---------------------------------------------

function _b2bStagePickup(deal) {
    const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
    // Restore anything typed before a same-device signing round-trip.
    const draft = (_b2bPickupDraft && _b2bPickupDraft.id === deal.id) ? _b2bPickupDraft : null;
    const puDesc = draft ? (draft.desc || '') : (deal.pickup_desc || '');
    const puName = draft ? (draft.name || '') : (deal.signed_by || '');
    const recv   = draft ? (draft.recv || '') : (deal.received_by || '');
    // A pickup that already knows where it is holding was raised by that store,
    // and signing it off drops it straight into pricing there -- there is no
    // routing stage in between, so this screen is the only place its custody
    // gets recorded.
    const holding = deal.pricing_store;
    const w = _b2bIntake(deal);
    const walkIn = w.key === 'walkin';
    _b2bShowDeal({
        delDeal: deal,
        stage: 'pickup',
        eyebrow: deal.ref,
        title: w.title,
        sub: holding ? `${w.sub.replace(/\.$/, '')} — then straight into pricing at ${holding}.` : w.sub,
        body: `
            ${_b2bSummary(deal)}
            ${_b2bPrevalOriginNote(deal)}
            <label class="form-label-caps">${w.items}</label>
            <textarea id="b2bPuDesc" class="form-input-lg" rows="3"
                placeholder="e.g. ~40 laptops, 12 monitors, 3 pallets of misc peripherals">${escapeHtml(puDesc)}</textarea>
            <p class="b2b-hint">${w.hint}</p>
            <div class="${walkIn ? '' : 'b2b-grid2'}" style="margin-top:14px;">
                <div>
                    <label class="form-label-caps">Client Name *</label>
                    <input id="b2bPuSigned" class="form-input-lg" value="${escapeHtml(puName)}" placeholder="Full name of whoever released the items">
                </div>
                ${walkIn ? '' : `
                <div>
                    <label class="form-label-caps">Pickup Date *</label>
                    <!-- Deliberately NOT pre-filled with today. It used to be, and a
                         collection that happened last week got silently recorded as
                         today by anyone who did not think to change it -- a wrong
                         answer that looks like a considered one. Blank forces the
                         choice; the required check below catches it. max stops a
                         collection being dated into the future. -->
                    <input id="b2bPuDate" type="date" class="form-input-lg" max="${today}">
                </div>`}
            </div>
            ${walkIn ? `
            <p class="b2b-hint">Dated today, ${escapeHtml(_b2bDate(today))}, and recorded as received
                by you — they are standing at the counter, so there is nothing to ask.</p>`
            : holding ? `
            <div style="margin-top:14px;">
                <label class="form-label-caps">Received By</label>
                <input id="b2bPuRecv" class="form-input-lg" value="${escapeHtml(recv)}"
                    placeholder="Who took these in at ${escapeHtml(holding)}">
                <p class="b2b-hint">A deal picked up by corp records this when it is dropped at
                    its pricing location. This one never leaves ${escapeHtml(holding)}, so it is
                    recorded here instead.</p>
            </div>` : ''}
            ${_b2bSignBlock(deal)}
            <label class="b2b-ack">
                <input type="checkbox" id="b2bPuAck" onchange="document.getElementById('b2bPuGo').disabled=!this.checked">
                <span>${w.ack}</span>
            </label>`,
        after: () => {
            // Only worth drawing when there is nothing signed yet.
            if (!deal.signature_path && !deal.signature_skipped_by) {
                _b2bPaintQR(document.getElementById('b2bSignQR'), _b2bSignUrl(deal.id));
            }
            _b2bPickupDraft = null;   // consumed into the inputs above
        },
        footer: `
            <button class="b2b-btn b2b-btn-secondary" style="margin-right:auto;"
                onclick="b2bPrintHoldingLabel('${deal.id}')">Print Holding Label</button>
            ${_b2bMoveBtn(deal)}
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Cancel</button>
            <button class="b2b-btn b2b-btn-primary" id="b2bPuGo" disabled onclick="b2bSignPickup('${deal.id}',this)">${w.go}</button>`,
    });
}

async function b2bSignPickup(id) {
    const signed = document.getElementById('b2bPuSigned')?.value.trim();
    // A walk-in renders no date field at all, so the requirement is on the field
    // existing rather than on the stage: the server dates it today for exactly
    // the deals this screen doesn't ask about, and demanding a value the form
    // never offered would make the button dead on those.
    const dateEl = document.getElementById('b2bPuDate');
    if (!signed) return alert("Enter the name of the person releasing the items.");
    if (dateEl && !dateEl.value) return alert('Pick the date the items were collected.');
    await _b2bPost({
        action: 'sign_pickup', id, signed_by: signed, pickup_date: dateEl?.value,
        pickup_desc: document.getElementById('b2bPuDesc')?.value.trim(),
        // Only rendered on a store-origin pickup; absent everywhere else, and
        // the server fills it (walk-in) or leaves the column alone (corp pickup).
        received_by: document.getElementById('b2bPuRecv')?.value.trim(),
    }, "Couldn't sign off the pickup");
    closeAllModals();
    await b2bRefresh();
}

// --- stage 2: pricing location --------------------------------------------

function _b2bStageAssign(deal) {
    _b2bAssignPick = null;
    _b2bShowDeal({
        delDeal: deal,
        stage: 'pricing_location',
        eyebrow: deal.ref,
        title: 'Assign Pricing Location',
        sub: 'Pick who itemizes and prices this pickup, and record the hand-off.',
        body: `
            ${_b2bSummary(deal)}
            ${deal.pickup_desc ? `<div class="b2b-note"><span class="b2b-note-k">${_b2bIntake(deal).was}</span>${escapeHtml(deal.pickup_desc)}</div>` : ''}
            <label class="form-label-caps" style="margin-top:14px;">Price It At</label>
            <div class="b2b-loc-pick">
                ${B2B_LOCATIONS.map(c => `
                    <button class="b2b-loc" data-loc="${c}" onclick="b2bPickLocation('${c}')">
                        <span class="b2b-loc-dot" style="background:${STORE_TINTS[c] || '#94a3b8'}"></span>
                        <span class="b2b-loc-c">${c}</span>
                    </button>`).join('')}
            </div>
            <p class="b2b-hint">Pricing at CORP means the listing store gets chosen separately once the client accepts.</p>
            <div class="b2b-grid2" style="margin-top:14px;">
                <div><label class="form-label-caps">Handed Over By</label><input id="b2bAsDeliv" class="form-input-lg" placeholder="Who picked it up or dropped it off"></div>
                <div><label class="form-label-caps">Received By</label><input id="b2bAsRecv" class="form-input-lg" placeholder="Who took it in at the location"></div>
            </div>`,
        footer: `
            <button class="b2b-btn b2b-btn-secondary" style="margin-right:auto;"
                onclick="b2bPrintHoldingLabel('${deal.id}')">Print Holding Label</button>
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Cancel</button>
            <button class="b2b-btn b2b-btn-primary" id="b2bAsGo" disabled onclick="b2bAssignPricing('${deal.id}',this)">Send To Pricing</button>`,
    });
}

function b2bPickLocation(code) {
    _b2bAssignPick = code;
    document.querySelectorAll('.b2b-loc').forEach(b => b.classList.toggle('on', b.dataset.loc === code));
    const go = document.getElementById('b2bAsGo');
    if (go) { go.disabled = false; go.textContent = `Send To ${code}`; }
}

async function b2bAssignPricing(id) {
    if (!_b2bAssignPick) return;
    await _b2bPost({
        action: 'assign_pricing', id, pricing_store: _b2bAssignPick,
        delivered_by: document.getElementById('b2bAsDeliv')?.value.trim(),
        received_by:  document.getElementById('b2bAsRecv')?.value.trim(),
    }, "Couldn't assign the pricing location");
    closeAllModals();
    await b2bRefresh();
}

// --- line item helpers (shared by pricing + quote) ------------------------

function _b2bTagsOf(str)  { return String(str || '').split(';').map(s => s.trim()).filter(Boolean); }
// client_notes is one semicolon-joined string. Split it back into the preset
// tags (which drive the chips) and anything typed by hand (which drives the
// free-text box) so the two controls never show each other's content.
function _b2bPresetNotes(it) { return _b2bTagsOf(it.client_notes).filter(t => B2B_NOTE_TAGS.includes(t)); }
function _b2bCustomNotes(it) { return _b2bTagsOf(it.client_notes).filter(t => !B2B_NOTE_TAGS.includes(t)).join('; '); }

// Anything downgraded to Fair or Broken has to say why: that note prints on
// the quote and is the only thing standing between a low offer and an argument
// with the client later. Keeps the legacy 'For Parts' spelling so the gate can
// never quietly stop firing on an older row -- see B2B_COND_LEGACY.
const B2B_REASON_CONDITIONS = ['Fair', 'Broken', ...B2B_COND_LEGACY];
function _b2bNeedsReason(it)   { return B2B_REASON_CONDITIONS.includes(it.condition); }
function _b2bMissingReason(it) { return _b2bNeedsReason(it) && !String(it.client_notes || '').trim(); }
// Deliberately no `unreasoned()` helper: a second, weaker gate alongside
// _b2bNotReady() is one someone will reach for by mistake, and it is how the
// accept path came to check reasons but not serials or specs.
function _b2bItemName(it) { return [it.make, it.model].filter(Boolean).join(' ') || 'Untitled item'; }

// Labels are printed per line, wherever a line is shown -- pricing, quoting,
// the listing checklist and the read-only view all get the same button, so a
// lost or damaged label can be reprinted from whichever screen you're on.
const B2B_ICO_BARCODE = '<path d="M3 5v14"/><path d="M7 5v14"/><path d="M11 5v14"/>'
                      + '<path d="M14 5v14"/><path d="M18 5v14"/><path d="M21 5v14"/>';

function _b2bLabelBtn(it, cls) {
    if (!it.sku) return '';
    const n = Number(it.quantity) || 1;
    return `<button class="b2b-linelabel ${cls || ''}" onclick="event.stopPropagation();b2bPrintLabels('${_b2bModalDeal?.id}','${it.id}')"
        aria-label="Print labels for ${escapeHtml(it.sku)}"
        data-tip="${n === 1 ? `Print the label for ${escapeHtml(it.sku)}`
                            : `Print labels for ${escapeHtml(it.sku)} — it asks how many`}">${_b2bIco(B2B_ICO_BARCODE)}</button>`;
}
// WHAT THE ITEM EDITOR IS EDITING
// -------------------------------
// Everything below -- the inline saves, the totals, the margin, the detail
// sheet, the spreadsheet itself -- was already generic over _b2bModalItems. The
// only thing that was ever deal-specific was the name of the action it posted.
// So a pre-evaluation reuses the whole editor and differs by three strings,
// rather than getting a second renderer that would drift from this one within a
// release.
//
// The handful of places that genuinely differ (no SKU, no drag-to-reorder, no
// serials -- we have not seen these units) each test _b2bItemMode explicitly.
const B2B_ITEM_CTX = {
    deal:   { add: 'add_item',        update: 'update_item',        del: 'delete_item',
              parent: 'deal_id',   fetch: 'deal_id' },
    preval: { add: 'preval_add_item', update: 'preval_update_item', del: 'preval_delete_item',
              parent: 'preval_id', fetch: 'preval_id' },
};
let _b2bItemMode = 'deal';
function _b2bCtx() { return B2B_ITEM_CTX[_b2bItemMode] || B2B_ITEM_CTX.deal; }
function _b2bIsPreval() { return _b2bItemMode === 'preval'; }
// Whichever record the open editor belongs to.
function _b2bEditParent() { return _b2bIsPreval() ? _b2bModalPreval : _b2bModalDeal; }

function _b2bLocalItem(id){ return _b2bModalItems.find(i => i.id === id); }

// --- item shape helpers ----------------------------------------------------
// Each of these has a twin in the edge function. Keep them in step: the server
// re-checks everything, so a disagreement shows up as a save that fails after
// the UI already said it was fine.

const _b2bDispOf  = (it) => it.disposition || 'purchase';
const _b2bIsBuy   = (it) => _b2bDispOf(it) === 'purchase';
const _b2bIsScrap = (it) => _b2bDispOf(it) === 'recycle';
const _b2bIsNrv   = (it) => _b2bDispOf(it) === 'no_residual';

// What the Total column shows for one line, in one place because three screens
// render it and a fourth repaints it -- the last time money was expressed
// independently in several spots, half of them ended up showing gross where the
// rest showed net.
//
// A purchase line shows what we pay. Recycle is worth nothing to anyone, so it
// stays a dash. No-residual costs us nothing but still carries resale value,
// and dashing that out hid a real number: six monitors worth $270 to us read as
// an empty row, which is what prompted the report. It renders in the same blue
// as the row's bar and the client-facing chip so it cannot be misread as money
// owed to the client.
function _b2bLineTotal(it) {
    const q = Number(it.quantity) || 1;
    if (_b2bIsBuy(it)) {
        return { cls: 'b2b-f-calc', text: _b2bMoney((Number(it.offer) || 0) * q, 2),
                 tip: 'What we pay the client for this line' };
    }
    if (_b2bIsScrap(it)) {
        return { cls: 'b2b-f-off', text: '—', tip: 'Scrapped — no value to us or to the client' };
    }
    const resale = (Number(it.value) || 0) * q;
    return { cls: 'b2b-f-resale', text: resale ? _b2bMoney(resale, 2) : '—',
             tip: 'Resale value to us — the client is paid nothing for this line' };
}
function _b2bLineTotalHtml(it) {
    const t = _b2bLineTotal(it);
    return `<span class="${t.cls}" id="b2bLn-${it.id}" title="${escapeHtml(t.tip)}">${t.text}</span>`;
}

// Margin on one line: what we keep of its resale value after paying for it.
// The deal-level figure was already on the totals bar, but that averages a good
// buy and a bad one into something that looks fine -- and the decision being
// made on this screen is per line, not per pallet.
//
// A no-residual line is 100% by construction: it has resale value and we pay
// nothing for it. Recycle has neither, so there is no ratio to show.
//
// Deliberately no "good / bad" thresholds. What counts as an acceptable margin
// is a buying decision this code has no business asserting -- and there is a
// Margin Guide tool that owns that question. The one thing flagged is a NEGATIVE
// margin, which isn't a judgement call: it means the offer exceeds what the
// thing is worth to us.
function _b2bLineMargin(it) {
    const q = Number(it.quantity) || 1;
    const value = _b2bIsScrap(it) ? 0 : (Number(it.value) || 0) * q;
    const offer = _b2bIsBuy(it) ? (Number(it.offer) || 0) * q : 0;
    // Same definition as the deal-level figure in _b2bItemTotals: what the line
    // costs us, which is the offer plus the freight. If these two used different
    // definitions the sheet would disagree with its own totals bar.
    const ship = (Number(it.shipping_cost) || 0) * q;
    // The marketplace takes its cut before we see any of it, so it belongs in
    // what the line costs us alongside the offer and the freight.
    const fee = _b2bFeeOn(value);
    const outlay = offer + ship + fee;
    if (value <= 0) {
        return { cls: 'b2b-f-off', text: '—',
                 tip: _b2bIsScrap(it) ? 'Recycled — no resale value to measure against'
                                      : 'Set a unit value to see the margin' };
    }
    const pct = Math.round(((value - outlay) / value) * 100);
    const parts = [
        ship ? `${_b2bMoney(ship, 2)} shipping` : '',
        fee  ? `${_b2bMoney(fee, 2)} marketplace fee` : '',
    ].filter(Boolean);
    const note = parts.length ? ` (incl. ${parts.join(' + ')})` : '';
    return {
        cls: pct < 0 ? 'b2b-f-mgn bad' : 'b2b-f-mgn',
        text: `${pct}%`,
        tip: pct < 0
            ? `This line costs us ${_b2bMoney(outlay, 2)}${note} and is worth ${_b2bMoney(value, 2)}`
            : `${_b2bMoney(value - outlay, 2)} of ${_b2bMoney(value, 2)} resale value${note}`,
    };
}
function _b2bLineMarginHtml(it) {
    const m = _b2bLineMargin(it);
    return `<span class="${m.cls}" id="b2bMg-${it.id}" title="${escapeHtml(m.tip)}">${m.text}</span>`;
}

// A one-line preview of whatever was written about this line.
//
// Client notes print on the client's quote; staff notes never leave the
// building. Both sit behind the ⋯ sheet, so scanning a thirty-line pallet for
// "which lines did the client say something about" meant opening thirty
// sheets -- which is what was reported. An earlier version of this always
// rendered, including a "No details yet" placeholder, and that is what made it
// cost height on every row; this one returns nothing when there is nothing to
// say, so only the handful of annotated lines pay for it.
//
// Client leads, because that is the half that reaches the client.
//
// Named apart from _b2bNoteHint, which already exists and returns a plain-text
// summary for the card grid's tooltip. Two `function` declarations of one name
// do not collide loudly -- the later simply wins -- so this would have rendered
// that tooltip string, unwrapped, into the row.
function _b2bNoteLine(it) {
    const client = String(it.client_notes || '').trim();
    const staff  = String(it.staff_notes || '').trim();
    if (!client && !staff) return '';
    const part = (cls, label, text) =>
        `<span class="${cls}" title="${escapeHtml(label + ': ' + text)}"><b>${label}</b>${escapeHtml(text)}</span>`;
    return `<div class="b2b-pnote-hint">`
        + (client ? part('b2b-nh-c', 'Client', client) : '')
        + (staff  ? part('b2b-nh-s', 'Staff',  staff)  : '')
        + `</div>`;
}

// What the pickup screen shows for the signature: the QR to collect one, the
// signature once collected, or the bypass once someone has recorded why there
// isn't going to be one.
function _b2bSignBlock(deal) {
    if (deal.signature_path) {
        const who = [deal.signature_by, deal.signature_at ? _b2bDate(deal.signature_at) : '']
            .filter(Boolean).join(' · ');
        return `
            <div class="b2b-note ok b2b-signed">
                <span class="b2b-note-k">Signed by the client${who ? ` — captured by ${escapeHtml(who)}` : ''}</span>
                <img class="b2b-sig-img" alt="Client signature"
                    src="${B2B_URL}?signature=${encodeURIComponent(deal.id)}&v=${encodeURIComponent(deal.signature_at || '')}">
                <button class="b2b-mini" onclick="b2bRetakeSign('${deal.id}')">Take it again</button>
            </div>`;
    }
    if (deal.signature_skipped_by) {
        return `
            <div class="b2b-note warn">
                <span class="b2b-note-k">Signed off without a signature — ${escapeHtml(deal.signature_skipped_by)}</span>
                ${escapeHtml(deal.signature_skipped_reason || '')}
            </div>`;
    }
    return `
        <div class="b2b-signq">
            <div class="b2b-signq-qr" id="b2bSignQR"><span class="b2b-signq-wait">Drawing code…</span></div>
            <div class="b2b-signq-txt">
                <b>Have the client sign</b>
                <p>Sign right here on this device — hand it to the client — or scan the
                   code to sign on a phone instead.</p>
                <div class="b2b-signq-acts">
                    <button class="b2b-btn b2b-btn-primary" onclick="b2bSignHere('${deal.id}')">Sign on this device</button>
                    ${_b2bCanAccept() ? `<button class="b2b-mini" onclick="b2bSkipSign('${deal.id}')">Continue without a signature</button>`
                                      : '<span class="b2b-signq-note">A CEO, MOCD or DM can sign off without one.</span>'}
                </div>
            </div>
        </div>`;
}

// Reopening the pad on the desktop is not useful -- it is the phone that has the
// client in front of it -- so this just clears the way for another scan.
function b2bRetakeSign(id) {
    if (!confirm('Take the signature again?\n\nYou can re-sign on this device or with the phone. '
        + 'The signature already on file stays until a new one replaces it.')) return;
    const deal = _b2bDealById(id);
    if (deal) { deal.signature_path = null; b2bOpenDeal('pickup', id); }
}

async function b2bSkipSign(id) {
    if (!_b2bCanAccept()) return;
    const reason = prompt('Sign off this pickup WITHOUT a client signature.\n\n'
        + 'Say why — this is recorded against your name and is what the signature '
        + 'would otherwise have proved.');
    if (reason === null) return;
    if (!reason.trim()) return alert('A reason is required to skip the signature.');
    try {
        // Hold what is on the form. Recording the skip round-trips to the
        // server and reopens the pickup screen from the stored row, so the
        // description, the client's name and the received-by all vanished --
        // typed, unsaved, and gone the moment you explained why there was no
        // signature. b2bSignHere has always done this for the same reason.
        _b2bPickupDraft = {
            id,
            desc: document.getElementById('b2bPuDesc')?.value,
            name: document.getElementById('b2bPuSigned')?.value,
            recv: document.getElementById('b2bPuRecv')?.value,
        };
        await _b2bSend({ action: 'skip_signature', id, reason: reason.trim() });
        await b2bRefresh();
        b2bOpenDeal('pickup', id);
    } catch (e) {
        alert(`Couldn't record that: ${e.message}`);
    }
}

// --- signature capture -----------------------------------------------------
// The pickup screen shows a QR. A staff member scans it with their own phone,
// which opens THIS app at #b2b-sign-<dealId>, signs in with their PIN if the
// phone hasn't already, and hands the phone to the client to sign.
//
// Nothing here is public. The phone is an ordinary signed-in session, which is
// why there is no token to mint, no anonymous write path, and no second shell
// to keep in step with this one.

// A deal id waiting for the pane to finish loading. The deep link arrives before
// _b2bDeals exists, so the hash is parked here and b2bLoad() picks it up.
let _b2bPendingSign = null;

// qrcode-generator from CDN, the same way _rtEnsureClient loads supabase-js and
// the XLSX loader loads its own. Hand-rolling this is not the same proposition
// as the Code 128 encoder next door -- QR needs Reed-Solomon and mask selection,
// and getting either subtly wrong produces a code that scans on your phone and
// not on someone else's.
let _b2bQrLoading = null;
function _b2bEnsureQR() {
    if (typeof window.qrcode === 'function') return Promise.resolve(window.qrcode);
    if (_b2bQrLoading) return _b2bQrLoading;
    const srcs = [
        'https://cdn.jsdelivr.net/npm/qrcode-generator@1.4.4/qrcode.js',
        'https://unpkg.com/qrcode-generator@1.4.4/qrcode.js',
    ];
    _b2bQrLoading = new Promise((resolve, reject) => {
        const tryNext = (i) => {
            if (i >= srcs.length) { _b2bQrLoading = null; return reject(new Error('QR library unavailable')); }
            const s = document.createElement('script');
            s.src = srcs[i];
            s.onload = () => typeof window.qrcode === 'function' ? resolve(window.qrcode) : tryNext(i + 1);
            s.onerror = () => tryNext(i + 1);
            document.head.appendChild(s);
        };
        tryNext(0);
    });
    return _b2bQrLoading;
}

function _b2bSignUrl(dealId) {
    const base = location.href.replace(/#.*$/, '').replace(/[^/]*$/, '');
    return `${base}operations.html#b2b-sign-${dealId}`;
}

// Draws into whatever element is passed, so the caller owns the layout.
async function _b2bPaintQR(el, text) {
    if (!el) return;
    try {
        const qrcode = await _b2bEnsureQR();
        // Type 0 = pick the smallest version that fits; M correction survives a
        // phone camera at an angle without bloating the code.
        const qr = qrcode(0, 'M');
        qr.addData(text);
        qr.make();
        el.innerHTML = qr.createSvgTag({ cellSize: 4, margin: 8, scalable: true });
    } catch (_) {
        // The link is the fallback, and it is a real one: it can be typed, or
        // sent to the phone another way.
        el.innerHTML = `<div class="b2b-qr-fail">Couldn't draw the QR code.<br>
            <span class="b2b-mono">${escapeHtml(text)}</span></div>`;
    }
}

// --- the phone's side ------------------------------------------------------

let _b2bSigCtx = null, _b2bSigDrawn = false;
// True when the pad was opened straight on the pickup device (not the phone
// deep-link), so saving returns to the pickup screen instead of the phone's
// "hand it back" dead-end.
let _b2bSignOnDevice = false;

// Whatever's typed on the pickup screen, kept across the sign-pad round-trip so
// signing on this device doesn't wipe an already-entered name/description.
let _b2bPickupDraft = null;
function b2bSignHere(id) {
    _b2bPickupDraft = {
        id,
        desc: document.getElementById('b2bPuDesc')?.value,
        name: document.getElementById('b2bPuSigned')?.value,
        recv: document.getElementById('b2bPuRecv')?.value,
    };
    b2bOpenSign(id, true);
}

function b2bOpenSign(dealId, onDevice) {
    const deal = _b2bDealById(dealId);
    if (!deal) return alert("That deal is no longer open for signing.");
    if (deal.stage !== 'pickup') {
        return alert(`${deal.ref} has already been signed off.`);
    }
    _b2bModalDeal = deal;
    _b2bSigDrawn = false;
    _b2bSignOnDevice = !!onDevice;
    _b2bShowDeal({
        stage: 'pickup',
        eyebrow: deal.ref,
        title: 'Client Signature',
        sub: onDevice ? 'Hand the device to the client to sign.' : 'Hand the phone to the client.',
        wide: true,
        body: `
            <div class="b2b-sign-who">
                <b>${escapeHtml(deal.client?.company || '')}</b>
                ${deal.pickup_date ? `<span>Collected ${escapeHtml(_b2bDate(deal.pickup_date))}</span>` : ''}
            </div>
            ${deal.pickup_desc ? `<div class="b2b-note"><span class="b2b-note-k">Items collected</span>${escapeHtml(deal.pickup_desc)}</div>` : ''}
            <!-- Word for word the acknowledgement the pickup screen already
                 asks staff to tick. The client is signing that sentence, so it
                 has to be the sentence, not a paraphrase of it. -->
            <p class="b2b-sign-ack">The client confirms the items above were collected by
                SPEEKS Technology on the date shown.</p>
            <div class="b2b-sign-pad">
                <canvas id="b2bSigPad" width="900" height="320"></canvas>
                <span class="b2b-sign-hint" id="b2bSigHint">Sign here</span>
            </div>
            <div class="b2b-sign-name">${escapeHtml(deal.signed_by || 'Signature')}</div>`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            <button class="kpi-cancel-btn" onclick="b2bClearSign()">Clear</button>
            <button class="b2b-btn b2b-btn-primary" id="b2bSigSave"
                onclick="b2bSaveSign('${deal.id}',this)">Save Signature</button>`,
        after: _b2bInitSigPad,
    });
}

// Pointer events, not mouse+touch: one code path covers a finger, a stylus and
// a mouse, and it is the only one that gets pressure-less styluses right.
function _b2bInitSigPad() {
    const cv = document.getElementById('b2bSigPad');
    if (!cv) return;
    // Draw at the canvas's own resolution regardless of how CSS sizes it, so a
    // signature captured on a small phone is not a blurry upscale.
    const ctx = cv.getContext('2d');
    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, cv.width, cv.height);
    ctx.lineWidth = 3.5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#111';
    _b2bSigCtx = ctx;

    let drawing = false;
    const at = (ev) => {
        const r = cv.getBoundingClientRect();
        return [(ev.clientX - r.left) * (cv.width / r.width),
                (ev.clientY - r.top) * (cv.height / r.height)];
    };
    cv.addEventListener('pointerdown', (ev) => {
        drawing = true;
        cv.setPointerCapture(ev.pointerId);
        const [x, y] = at(ev);
        ctx.beginPath(); ctx.moveTo(x, y);
        // A tap with no drag is still a mark, and some people "sign" with one.
        ctx.lineTo(x + 0.01, y); ctx.stroke();
        _b2bSigDrawn = true;
        document.getElementById('b2bSigHint')?.classList.add('gone');
        ev.preventDefault();
    });
    cv.addEventListener('pointermove', (ev) => {
        if (!drawing) return;
        const [x, y] = at(ev);
        ctx.lineTo(x, y); ctx.stroke();
        ev.preventDefault();
    });
    const stop = (ev) => { drawing = false; if (ev) ev.preventDefault(); };
    cv.addEventListener('pointerup', stop);
    cv.addEventListener('pointercancel', stop);
    cv.addEventListener('pointerleave', stop);
}

function b2bClearSign() {
    const cv = document.getElementById('b2bSigPad');
    if (!cv || !_b2bSigCtx) return;
    _b2bSigCtx.fillStyle = '#fff';
    _b2bSigCtx.fillRect(0, 0, cv.width, cv.height);
    _b2bSigDrawn = false;
    document.getElementById('b2bSigHint')?.classList.remove('gone');
}

async function b2bSaveSign(id, btn) {
    if (!_b2bSigDrawn) return _b2bSay('Ask the client to sign first.', true);
    const cv = document.getElementById('b2bSigPad');
    if (!cv) return;
    await _b2bBusy(btn, 'Saving…', async () => {
        await _b2bPost({ action: 'capture_signature', id, image: cv.toDataURL('image/png') },
            "Couldn't save the signature");
        closeAllModals();
        await b2bRefresh();
        if (_b2bSignOnDevice) {
            // Signed on the pickup device itself -- go straight back to the pickup
            // screen, where the signature now shows and the sign-off can finish.
            _b2bSignOnDevice = false;
            b2bOpenDeal('pickup', id);
        } else {
            // The phone's job is done in one screen; say so rather than dropping the
            // person back onto a board they did not come here for.
            alert('Signature saved. You can hand the phone back.');
        }
    });
}

// --- moving a deal between stores ------------------------------------------
// Corp only, and only while the goods are somewhere a move makes sense. The
// button says which hand-off it is about, because "Move" alone is ambiguous on
// a deal that has both a pricing store and a listing store.
function _b2bTransferKind(deal) {
    // A pickup a store raised for itself already has a store on it, and moving
    // it is how corp overrides that choice -- before it is signed off as much as
    // after. A corp-created pickup has no store to move it off: it gets one at
    // pricing_location, which is an assignment, not a move.
    if (deal.stage === 'pickup') return deal.pricing_store ? 'pricing' : null;
    if (['pricing', 'review', 'quote'].includes(deal.stage)) return 'pricing';
    if (['listing_location', 'listing'].includes(deal.stage)) return 'listing';
    return null;
}
function _b2bMoveBtn(deal) {
    if (!_b2bCanAccept()) return '';
    const kind = _b2bTransferKind(deal);
    if (!kind) return '';
    return `<button class="b2b-btn b2b-btn-secondary" onclick="b2bOpenTransfer('${deal.id}')">
        Move ${kind === 'pricing' ? 'Pricing' : 'Listing'} Store</button>`;
}

function b2bOpenTransfer(id) {
    const deal = _b2bDealById(id) || _b2bModalDeal;
    if (!deal || !_b2bCanAccept()) return;
    const kind = _b2bTransferKind(deal);
    if (!kind) return;
    const at = kind === 'pricing' ? deal.pricing_store : deal.listing_store;
    // Listing can only land on a real store; pricing may also sit at CORP.
    const options = kind === 'pricing' ? B2B_LOCATIONS : STORE_CODES;
    const listed = Number(deal.listed_units) || 0;

    _b2bTransferPick = null;
    _b2bShowDeal({
        stage: deal.stage,
        eyebrow: deal.ref,
        title: kind === 'pricing' ? 'Move Pricing Store' : 'Move Listing Store',
        sub: kind === 'pricing'
            ? 'Send this pickup somewhere else to be priced.'
            : 'Move the remaining units to another store to be listed.',
        wide: true,
        body: `
            ${_b2bSummary(deal)}
            ${_b2bWhereLine(deal)}
            ${listed && kind === 'listing' ? `
                <div class="b2b-note warn">
                    <span class="b2b-note-k">${listed} unit${listed === 1 ? '' : 's'} already listed</span>
                    Those stay recorded against their Shopify barcodes and do not move.
                    Only what is left to list follows the deal.
                </div>` : ''}
            <label class="form-label-caps" style="margin-top:14px;">Move To</label>
            <div class="b2b-loc-pick">
                ${options.filter(c => c !== at).map(c => `
                    <button class="b2b-loc" data-loc="${c}" onclick="b2bPickTransfer('${c}')">
                        <span class="b2b-loc-dot" style="background:${STORE_TINTS[c] || '#94a3b8'}"></span>
                        <span class="b2b-loc-c">${c}</span>
                    </button>`).join('')}
            </div>
            <label class="form-label-caps" style="margin-top:14px;">Why (optional)</label>
            <input id="b2bMoveNote" class="form-input-lg" placeholder="e.g. LEE is backed up until Friday">
            <p class="b2b-hint">The move is recorded with your name against it, so the trail
                survives the deal being reopened later.</p>`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            <button class="kpi-cancel-btn" onclick="b2bOpenDeal('${_b2bClickKind(deal)}','${deal.id}')">Cancel</button>
            <button class="b2b-btn b2b-btn-primary" id="b2bMoveGo" disabled
                onclick="b2bDoTransfer('${deal.id}',this)">Move</button>`,
    });
}

let _b2bTransferPick = null;
function b2bPickTransfer(code) {
    _b2bTransferPick = code;
    document.querySelectorAll('.b2b-loc').forEach(b => b.classList.toggle('on', b.dataset.loc === code));
    const go = document.getElementById('b2bMoveGo');
    if (go) { go.disabled = false; go.textContent = `Move To ${code}`; }
}

async function b2bDoTransfer(id, btn) {
    if (!_b2bTransferPick) return;
    const to = _b2bTransferPick;
    await _b2bBusy(btn, 'Moving…', async () => {
        await _b2bPost({
            action: 'transfer_location', id, to_store: to,
            note: document.getElementById('b2bMoveNote')?.value.trim(),
        }, "Couldn't move the deal");
        closeAllModals();
        await b2bRefresh();
    });
}

// --- reordering the sheet --------------------------------------------------
// Drag a line by its number. The Line cell is the handle rather than the whole
// row, because the row is fifteen editable fields and dragging must not start
// when someone selects text in one of them.
//
// The order is stored on the item (sort_order) rather than derived from line_no:
// line_no is baked into printed SKUs. And because the quote renderers walk the
// same _b2bModalItems array, arranging the sheet arranges the client's quote --
// grouping the laptops together reads better to them too.
let _b2bDragId = null;

function b2bDragStart(ev, id) {
    _b2bDragId = id;
    try { ev.dataTransfer.effectAllowed = 'move'; ev.dataTransfer.setData('text/plain', id); } catch (_) {}
    document.getElementById(`b2bPline-${id}`)?.classList.add('b2b-dragging');
}
function b2bDragEnd() {
    document.querySelectorAll('.b2b-pline.b2b-dragging, .b2b-pline.b2b-dropto')
        .forEach(r => r.classList.remove('b2b-dragging', 'b2b-dropto'));
    _b2bDragId = null;
}
function b2bDragOver(ev, id) {
    if (!_b2bDragId || _b2bDragId === id) return;
    ev.preventDefault();                       // without this the drop never fires
    try { ev.dataTransfer.dropEffect = 'move'; } catch (_) {}
    const row = document.getElementById(`b2bPline-${id}`);
    document.querySelectorAll('.b2b-pline.b2b-dropto').forEach(r => {
        if (r !== row) r.classList.remove('b2b-dropto');
    });
    row?.classList.add('b2b-dropto');
}
async function b2bDrop(ev, id) {
    ev.preventDefault();
    const from = _b2bDragId;
    b2bDragEnd();
    if (!from || from === id) return;
    const items = _b2bModalItems;
    const a = items.findIndex(i => i.id === from);
    const b = items.findIndex(i => i.id === id);
    if (a < 0 || b < 0) return;

    const before = items.slice();
    items.splice(b, 0, items.splice(a, 1)[0]);
    _b2bRepaintItems();
    _b2bPaintQuoteDoc();                       // the quote follows the sheet

    try {
        await _b2bSend({ action: 'reorder_items', deal_id: _b2bModalDeal.id,
                         order: items.map(i => i.id) });
        _b2bDirty = true;
    } catch (e) {
        // Put it back rather than leaving the screen showing an order the server
        // rejected -- the next person to open this deal would see the old one.
        _b2bModalItems = before;
        _b2bRepaintItems();
        _b2bPaintQuoteDoc();
        _b2bSay(`Couldn't save the new order: ${e.message}`, true);
    }
}

// The key to the coloured bars down the left of the sheet. Always rendered
// rather than only when a non-purchase line exists: the grid repaints on its
// own (_b2bRepaintItems touches #b2bItemGrid alone), so a legend that appeared
// and disappeared with the data would go stale the moment someone changed a
// line's handling without a full redraw.
function _b2bDispLegend() {
    return `<div class="b2b-disp-key">
        <b>Row colours</b>
        <span class="k-nrv"><i></i><em>No residual value</em> — nothing to the client, may still be resold</span>
        <span class="k-scrap"><i></i><em>Recycle</em> — scrapped, never listed</span>
        <span class="k-block"><i></i><em>Not ready</em> — something on the line is still missing</span>
    </div>`;
}

// One entry per unit. Split on comma, drop the blanks -- so trailing commas and
// double commas while typing don't count as units.
function _b2bSerials(it)     { return String(it.serials || '').split(',').map(s => s.trim()).filter(Boolean); }
function _b2bSerialsOk(it)   { return _b2bSerials(it).length === (Number(it.quantity) || 1); }

function _b2bSpecsFor(it)    { return B2B_SPEC_FIELDS.filter(f => (B2B_SPECS_FOR[it.item_type || 'other'] || []).includes(f.key)); }
function _b2bMissingSpecs(it) {
    return _b2bSpecsFor(it).filter(f => f.req && !String(it[f.key] ?? '').trim());
}
// Everything blocking this line from being submitted, in one place, so the row
// badge, the drawer and the submit button all agree on what "ready" means.
function _b2bItemBlocked(it) {
    const why = [];
    if (_b2bMissingReason(it))     why.push(`${it.condition} needs a reason`);
    if (_b2bMissingSpecs(it).length) why.push(_b2bMissingSpecs(it).map(f => f.label).join(', ') + ' missing');
    // Serials are per physical unit, and a pre-evaluation has no units -- the
    // client has described what they have, nobody has held it. Demanding them
    // here would make every evaluation permanently unsendable.
    if (!_b2bIsPreval() && !_b2bSerialsOk(it)) {
        why.push(`${_b2bSerials(it).length} of ${Number(it.quantity) || 1} serials`);
    }
    return why;
}
function _b2bNotReady() { return _b2bModalItems.filter(it => _b2bItemBlocked(it).length); }

// What a marketplace takes out of a sale, as a share of the resale value.
//
// Ethan: "eBay fees should also be calculated on pricing. It can just be a
// formula of 8% of revenue, so we get accurate assume net margin." Applied to
// every line rather than only the ones bound for eBay, because at pricing time
// nobody knows yet where a unit will sell -- and a margin that flatters half the
// pallet is worse than one that is evenly, knowably conservative.
//
// A named constant, not a literal in two formulas: the line margin and the deal
// margin have to agree, and the last time those two drifted apart the sheet
// disagreed with its own totals bar.
const B2B_MARKETPLACE_FEE = 0.08;
// Charged on what the goods SELL for, so a line with no resale value owes
// nothing -- recycle contributes no fee, and neither does an unpriced line.
function _b2bFeeOn(value) { return Math.round(value * B2B_MARKETPLACE_FEE * 100) / 100; }

// How many units on this line still have no label. Clamped at zero: reprinting
// a torn tag is normal, so a line can legitimately have had more labels than it
// has units, and that is not a negative shortfall -- it is nothing owed.
//
// An evaluation has no labels at all; nothing has been seen, let alone tagged.
function _b2bLabelsShort(it) {
    if (_b2bIsPreval()) return 0;
    return Math.max(0, (Number(it.quantity) || 1) - (Number(it.label_printed_qty) || 0));
}
function _b2bUnlabelled() { return _b2bModalItems.filter(it => _b2bLabelsShort(it) > 0); }

// What a line costs us in certified wipes.
function _b2bWipeTotal(it) {
    return it.wipe_required ? (Number(it.wipe_fee) || 0) * (Number(it.quantity) || 1) : 0;
}

function _b2bItemTotals() {
    let value = 0, offer = 0, units = 0, wipe = 0, ship = 0;
    _b2bModalItems.forEach(it => {
        const q = Number(it.quantity) || 1;
        units += q;
        // Only a purchase carries resale value into the deal total. Recycle is
        // worthless; a no-residual line's value is speculative -- we realise it
        // only if we later choose to list it -- so it stays on the line but off
        // the total (and its freight comes off with it, below).
        if (_b2bIsBuy(it)) value += (Number(it.value) || 0) * q;
        offer += (Number(it.offer) || 0) * q;
        wipe  += _b2bWipeTotal(it);
        // Shipping is the cost of moving goods we are committed to -- bought, or
        // being scrapped. A no-residual line isn't committed to anything yet, so
        // its freight stays off the total until we decide to sell it. Scrap still
        // costs the same to haul, so it keeps counting.
        if (!_b2bIsNrv(it)) ship += (Number(it.shipping_cost) || 0) * q;
    });
    // Clamped at the deal, not the line: a wipe on a $0 item still discounts
    // against the rest, and we never end up charging the client money.
    //
    // `net` is what the CLIENT gets and shipping is deliberately absent from it:
    // what it costs us to move the goods is not their business and must never
    // move their number. `outlay` is what the deal costs US, which is the figure
    // margin is measured against.
    const net = Math.max(0, offer - wipe);
    // Same definition as the per-line margin, deliberately: the fee is charged
    // on resale value, and `value` here already excludes recycle and
    // no-residual lines, so the deal-level fee lands on exactly the units the
    // line-level one did.
    const fee = _b2bFeeOn(value);
    return { value, offer, wipe, ship, fee, net, outlay: net + ship + fee,
             units, lines: _b2bModalItems.length };
}

// Repaint just the numbers -- retyping the whole grid would eat focus.
function _b2bPaintTotals() {
    const t = _b2bItemTotals();
    const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    set('b2bTotValue', _b2bMoney(t.value, 2));
    set('b2bTotOffer', _b2bMoney(t.net, 2));
    set('b2bTotUnits', `${t.units} unit${t.units === 1 ? '' : 's'} · ${t.lines} line${t.lines === 1 ? '' : 's'}`);
    // Margin is against what the deal actually costs us: the wipe discount
    // improves it, shipping and the marketplace fee erode it. Measuring against
    // the offer alone was fine until shipping existed, and would now overstate
    // every deal we pay freight on -- which is the number Paul asked to see.
    const margin = t.value - t.outlay;
    const pct = t.value > 0 ? Math.round((margin / t.value) * 100) : 0;
    set('b2bTotMargin', `${_b2bMoney(margin, 2)} (${pct}%)`);
    const wipeEl = document.getElementById('b2bTotWipe');
    if (wipeEl) {
        wipeEl.textContent = t.wipe ? `−${_b2bMoney(t.wipe, 2)}` : '—';
        wipeEl.closest('.b2b-tot')?.classList.toggle('muted', !t.wipe);
    }
    const shipEl = document.getElementById('b2bTotShip');
    if (shipEl) {
        // "+" because it adds to what the deal costs us, where the wipe line
        // above reads "−". The two sit next to each other and pull opposite ways.
        shipEl.textContent = t.ship ? `+${_b2bMoney(t.ship, 2)}` : '—';
        shipEl.closest('.b2b-tot')?.classList.toggle('muted', !t.ship);
    }
    const feeEl = document.getElementById('b2bTotFee');
    if (feeEl) {
        // "+" like shipping: another cost between us and the resale value.
        feeEl.textContent = t.fee ? `+${_b2bMoney(t.fee, 2)}` : '—';
        feeEl.closest('.b2b-tot')?.classList.toggle('muted', !t.fee);
    }
    _b2bModalItems.forEach(it => {
        const el = document.getElementById(`b2bLn-${it.id}`);
        if (!el) return;
        // Class and title move with the text: changing a line's handling changes
        // which of the three meanings this cell has, and a repaint that updated
        // only the number would leave the previous meaning's styling behind.
        const t = _b2bLineTotal(it);
        el.className = t.cls;
        el.title = t.tip;
        el.textContent = t.text;
        // Margin moves with value and offer, so it repaints on the same pass.
        const mel = document.getElementById(`b2bMg-${it.id}`);
        if (mel) {
            const m = _b2bLineMargin(it);
            mel.className = m.cls;
            mel.title = m.tip;
            mel.textContent = m.text;
        }
    });
    const submit = document.getElementById('b2bPrSubmit');
    if (submit) submit.disabled = _b2bModalItems.length === 0 || _b2bNotReady().length > 0;
    // The deal-stats block (pricing/quote) tracks the same live edits.
    _b2bPaintDealStats();
    // On the quote screen the preview sits below the grid, so it can be redrawn
    // on every keystroke without touching whichever field has focus.
    _b2bPaintQuoteDoc();
}

// Local edit -> repaint. Text/number fields post on change (blur), so typing
// stays smooth and we don't fire a request per keystroke.
function b2bItemInput(id, field, value) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    it[field] = (field === 'quantity') ? Math.max(1, parseInt(value, 10) || 1)
              : (field === 'value' || field === 'offer' || field === 'shipping_cost') ? (parseFloat(value) || 0)
              : value;
    // Quantity is the one field here that changes whether the LINE is ready:
    // five units need five serials. _b2bSyncReady owns that badge and the
    // blocked flags, so without this the row went on claiming it was fine and
    // the requirement only appeared once some other edit happened to sync it.
    if (field === 'quantity') _b2bSyncReady(it);
    _b2bPaintTotals();
}

// Fire-and-forget: the local object is already the source of truth for what is
// on screen, so the save runs behind the user instead of in front of them.
function b2bItemSave(id) {
    const it = _b2bLocalItem(id);
    if (!it) return Promise.resolve();
    _b2bDirty = true;
    return _b2bEnqueue(id, () => _b2bSend({
        action: _b2bCtx().update, id,
        make: it.make, model: it.model, condition: it.condition,
        staff_notes: it.staff_notes, client_notes: it.client_notes,
        listing_info: it.listing_info,
        quantity: it.quantity, value: it.value, offer: it.offer, shipping_cost: it.shipping_cost || 0,
        item_type: it.item_type || 'other',
        cpu: it.cpu, ram: it.ram, storage: it.storage, gpu: it.gpu, battery_health: it.battery_health,
        serials: it.serials,
        disposition: _b2bDispOf(it),
        wipe_required: !!it.wipe_required,
        // Hand the existing fee back so an unrelated edit can't re-snapshot the
        // line at today's rate and move a price the client has already seen.
        keep_wipe_fee: it.wipe_fee || 0,
    })).catch(e => _b2bSay(`Couldn't save that change: ${e.message}`, true));
}

// Changing the type changes which spec fields exist, so the row is rebuilt --
// safe, because a <select> has already blurred by the time this runs.
function b2bItemType(id, value) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    it.item_type = value;
    // Drop specs the new type doesn't carry, mirroring what the server does. It
    // would refuse the save otherwise, and the row would lie until a refresh.
    const keep = B2B_SPECS_FOR[value] || [];
    B2B_SPEC_FIELDS.forEach(f => { if (!keep.includes(f.key)) it[f.key] = null; });
    if (keep.length) _b2bNotesOpen.add(id);   // the specs live in the drawer
    _b2bRepaintItems();
    b2bItemSave(id);
}

function b2bItemDisposition(id, value) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    it.disposition = value;
    // Only a purchase pays the client; only recycle is worthless to us as well.
    if (value !== 'purchase') it.offer = 0;
    if (value === 'recycle')  { it.value = 0; it.shipping_cost = 0; }
    _b2bRepaintItems();
    b2bItemSave(id);
}

async function b2bItemWipe(id, on) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    it.wipe_required = on;
    // Take today's rate from the board payload; the server resolves it again
    // and its answer wins, so this is only so the number appears immediately.
    it.wipe_fee = on ? (it.wipe_fee || _b2bWipeFee()) : 0;
    if (!on) it.wipe_fee = 0;
    _b2bRepaintItems();
    await b2bItemSave(id);
    // Reconcile: the fee the server actually stored may differ from the guess.
    _b2bRefreshItemFee(id);
}

// The global certified-wipe charge, as of the last board load.
function _b2bWipeFee() { return Number(_b2bMeta?.wipe_fee ?? 8); }

async function _b2bRefreshItemFee(id) {
    const parent = _b2bEditParent();
    if (!parent) return;
    try {
        const rows = await _b2bGet(`${_b2bCtx().fetch}=${encodeURIComponent(parent.id)}`);
        const fresh = rows.find(r => r.id === id);
        const it = _b2bLocalItem(id);
        if (!fresh || !it) return;
        if (Number(fresh.wipe_fee) !== Number(it.wipe_fee)) {
            it.wipe_fee = fresh.wipe_fee;
            _b2bRepaintItems();
        }
    } catch (_) { /* the optimistic figure stands until the next load */ }
}

// Serials, one per unit. The button is the escape hatch for kit with no visible
// serial -- without it a box of 50 cables would be 50 refusals to submit.
function b2bItemSerials(id, value) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    it.serials = value;
    _b2bSyncReady(it);
}

function b2bNoSerial(id, all) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    const have = _b2bSerials(it);
    const need = (Number(it.quantity) || 1) - have.length;
    if (need <= 0) return;
    it.serials = [...have, ...Array(all ? need : 1).fill(B2B_NO_SERIAL)].join(', ');
    _b2bRepaintItems();
    b2bItemSave(id);
}

function b2bItemSpec(id, field, value) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    it[field] = value;
    _b2bSyncReady(it);
}

// One-tap "None" for a required spec: stamps NO CPU / NO RAM / NO STORAGE so a
// machine with the part pulled clears the gate without typing. Updates the inline
// cell in place (no full repaint, so nothing steals focus) and re-validates.
function b2bItemSpecNone(id, field, label) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    it[field] = 'NO ' + String(label).toUpperCase();
    const inp = document.getElementById(`b2bPline-${id}`)?.querySelector(`[data-req-spec="${field}"]`);
    if (inp) inp.value = it[field];
    _b2bSyncReady(it);
    b2bItemSave(id);
}

function b2bItemToggleTag(id, tag) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    const tags = _b2bTagsOf(it.client_notes);
    const i = tags.indexOf(tag);
    if (i >= 0) tags.splice(i, 1); else tags.push(tag);
    it.client_notes = tags.join('; ');
    _b2bRepaintItems();
    b2bItemSave(id);
}

// The free-text box owns only the hand-typed part; the chips own the presets.
// Recombine both into client_notes on every edit. (Used by the card grid, which
// keeps the tag chips.)
function b2bItemCustomNote(id, value) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    const custom = String(value || '').split(';').map(s => s.trim()).filter(Boolean);
    it.client_notes = [..._b2bPresetNotes(it), ...custom].join('; ');
    _b2bSyncReady(it);
    _b2bPaintTotals();
}

// The pricing sheet dropped the tag chips: its client-notes field is the whole
// note, edited straight into client_notes.
function b2bItemClientNote(id, value) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    it.client_notes = value;
    _b2bSyncReady(it);
    _b2bPaintTotals();
}

// Changing the condition can make a reason newly required (or no longer), so
// the card is re-rendered -- a select has already lost focus by then.
function b2bItemCondition(id, value) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    it.condition = value;
    _b2bRepaintItems();
    b2bItemSave(id);
}

// Typing is different: repainting mid-keystroke would steal focus, so the
// readiness warnings are flipped in place instead. Covers all three gates --
// reason, specs and serials -- because they share one badge and one submit
// button, and updating only some of them would leave the row contradicting
// itself mid-keystroke.
function _b2bSyncReady(it) {
    const line = document.getElementById(`b2bPline-${it.id}`);
    const blocked = _b2bItemBlocked(it);

    // Row-level state lives on the grid line either way (cards or spreadsheet):
    // the inset "needs a reason" bar, the flagged detail button, the one-line
    // summary of what's blocking it.
    line?.classList.toggle('needs-reason', blocked.length > 0);
    line?.querySelector('.b2b-notes-btn')?.classList.toggle('req', blocked.length > 0);
    const chip = line?.querySelector('.b2b-ready');
    if (chip) {
        chip.textContent = blocked.length ? blocked.join(' · ') : '';
        chip.style.display = blocked.length ? '' : 'none';
    }
    // Inline required-spec cells (spreadsheet): flag each one that's still empty,
    // so a cell clears its warning the moment it's filled.
    line?.querySelectorAll('[data-req-spec]').forEach(inp => {
        const k = inp.getAttribute('data-req-spec');
        inp.classList.toggle('b2b-spec-miss', !String(it[k] ?? '').trim());
    });

    // The note fields themselves live in the cards drawer (inside the line) OR in
    // the spreadsheet's detail sheet -- update wherever they actually are.
    const scope = document.getElementById('b2bItemSheet') || line;
    const reason = _b2bMissingReason(it);
    scope?.querySelector('.b2b-tag-free')?.classList.toggle('miss', reason);
    const note = scope?.querySelector('.b2b-req-note');
    if (note) note.style.display = reason ? '' : 'none';
    const count = scope?.querySelector('.b2b-serial-count');
    if (count) {
        const have = _b2bSerials(it).length, need = Number(it.quantity) || 1;
        count.textContent = `${have} of ${need}`;
        count.classList.toggle('miss', have !== need);
    }
    const submit = document.getElementById('b2bPrSubmit');
    if (submit) submit.disabled = _b2bModalItems.length === 0 || _b2bNotReady().length > 0;
}

// The server owns the line number and SKU, so this one has to wait -- but the
// button says so rather than just sitting there.
async function b2bAddItem(dealId, btn) {
    await _b2bBusy(btn, 'Adding…', async () => {
        const ctx = _b2bCtx();
        const out = await _b2bPost({
            action: ctx.add, [ctx.parent]: dealId, quantity: 1, value: 0, offer: 0,
        }, "Couldn't add a line");
        // Must carry every field the grid reads: the optimistic row is what gets
        // painted, and anything missing here reads as undefined until a refetch.
        _b2bModalItems.push({
            id: out.id, line_no: out.line_no, sku: out.sku, make: '', model: '', condition: '',
            staff_notes: '', client_notes: '', quantity: 1, value: 0, offer: 0,
            item_type: 'other', cpu: null, ram: null, storage: null, gpu: null, battery_health: null, shipping_cost: 0,
            listing_info: '', label_printed_qty: 0,
            sort_order: out.sort_order,
            serials: '', disposition: 'purchase',
            wipe_required: false, wipe_fee: 0, wiped_qty: 0,
            listed_qty: 0, recycled_qty: 0, listings: [],
        });
        _b2bDirty = true;
        _b2bRepaintItems();
        document.getElementById(`b2bMake-${out.id}`)?.focus();
    });
}

// Duplicate a line. A pallet is usually twenty near-identical machines, so
// re-typing brand, model, specs, condition and price for each one was the single
// slowest thing about pricing.
//
// Copies everything that describes the KIND of thing, and nothing that
// identifies a particular unit or records what has happened to it:
//   * the SKU and line number come from the server, which mints fresh ones
//   * serials are per unit, so a copied serial would be a lie -- and a wrong one
//     that reads as real, which is worse than a blank
//   * listing, recycling and wipe progress belong to the original units
// The wipe FLAG copies (it is a property of the kit) but the fee is re-snapshotted
// by the server rather than carried over, the same as any other new line.
async function b2bCopyItem(id, btn) {
    const src = _b2bLocalItem(id);
    if (!src) return;
    // MOCD: finishing a line and hitting copy drops you straight into the next
    // one, and the unit you just described walks off the bench untagged. Offered
    // here rather than enforced -- a printer that is down must not stop pricing.
    const short = _b2bLabelsShort(src);
    if (short > 0 && !_b2bIsPreval() && src.sku) {
        if (confirm(`Print ${short} label${short === 1 ? '' : 's'} for "${_b2bItemName(src)}" first?\n\n`
            + 'Tag it now and it cannot be the box nobody can identify later. '
            + 'Cancel to carry on without printing.')) {
            b2bPrintLabels(_b2bEditParent()?.id, id, short);
        }
    }
    await _b2bBusy(btn, '', async () => {
        const copy = {
            make: src.make, model: src.model, condition: src.condition,
            staff_notes: src.staff_notes, client_notes: src.client_notes,
            listing_info: src.listing_info,
            quantity: src.quantity, value: src.value, offer: src.offer, shipping_cost: src.shipping_cost || 0,
            item_type: src.item_type || 'other',
            cpu: src.cpu, ram: src.ram, storage: src.storage,
            gpu: src.gpu, battery_health: src.battery_health,
            disposition: _b2bDispOf(src), wipe_required: !!src.wipe_required,
        };
        const ctx = _b2bCtx();
        const out = await _b2bPost({ action: ctx.add, [ctx.parent]: _b2bEditParent().id, ...copy },
            "Couldn't copy that line");
        // Same rule as b2bAddItem: the optimistic row is what gets painted, so it
        // has to carry every field the grid reads.
        _b2bModalItems.push({
            ...copy, id: out.id, line_no: out.line_no, sku: out.sku, sort_order: out.sort_order,
            serials: '', wipe_fee: src.wipe_required ? (src.wipe_fee || _b2bWipeFee()) : 0,
            wiped_qty: 0, listed_qty: 0, recycled_qty: 0, listings: [],
        });
        _b2bDirty = true;
        _b2bRepaintItems();
        _b2bPaintTotals();
        // Straight to the serials, because that is the one thing a copy cannot
        // fill in and the one thing that blocks submitting. An evaluation has no
        // serials, so a copy there is already complete and the sheet would open
        // on nothing.
        if (!_b2bIsPreval()) b2bItemDetail(out.id);
    });
}

function b2bDeleteItem(id) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    if (!confirm(`Remove "${_b2bItemName(it)}" from this deal?`)) return;
    const at = _b2bModalItems.indexOf(it);
    _b2bModalItems.splice(at, 1);
    _b2bDirty = true;
    _b2bRepaintItems();
    _b2bEnqueue(id, () => _b2bSend({ action: _b2bCtx().del, id }))
        .catch(e => {
            _b2bModalItems.splice(at, 0, it);   // put it back where it was
            _b2bRepaintItems();
            _b2bSay(`Couldn't remove that line: ${e.message}`, true);
        });
}

// Pricing renders the dense spreadsheet; quote (and the read-only views) keep the
// card/drawer grid. _b2bRepaintItems is shared, so one flag picks the renderer.
let _b2bGridMode = 'cards';
// The line whose detail sheet is open over the spreadsheet, if any.
let _b2bSheetId = null;

function _b2bRepaintItems() {
    const wrap = document.getElementById('b2bItemGrid');
    if (wrap) wrap.innerHTML = _b2bGridMode === 'sheet' ? _b2bItemSheet() : _b2bItemCards();
    _b2bPaintTotals();
    // Keep an open detail sheet in step with the grid it hangs off -- a tag or
    // disposition change repaints both. If the line it belongs to is gone, so is
    // the sheet.
    if (_b2bSheetId != null) {
        if (_b2bLocalItem(_b2bSheetId)) _b2bPaintItemSheet();
        else b2bCloseItemSheet();
    }
}

// Which lines have their notes open. Notes are the bulky part and most lines
// never need them, so they fold away -- but a line still missing a required
// reason is forced open, because hiding the thing blocking submission would be
// the one case where collapsing costs more than it saves.
const _b2bNotesOpen = new Set();
// Which spreadsheet rows have their inline panel expanded. Separate from
// _b2bNotesOpen, which belongs to the card grid: the two grids are different
// shapes and sharing the set made a line opened in one appear open in the other.
const _b2bRowOpen = new Set();
// Explicitly collapsed, which has to outrank "blocked, so opened for you".
// Without it the auto-open won every render and the + was inert on exactly the
// rows people most want to tidy away.
const _b2bRowShut = new Set();

// One answer, shared by the renderer and the toggle. When these two disagreed
// about whether a row was open, the button toggled a state the sheet ignored.
function _b2bRowIsOpen(it) {
    if (_b2bRowShut.has(it.id)) return false;
    if (_b2bRowOpen.has(it.id)) return true;
    return _b2bItemBlocked(it).length > 0 && !_b2bIsPreval();
}

function b2bToggleRow(id) {
    const it = _b2bLocalItem(id);
    if (!it) return;
    const open = _b2bRowIsOpen(it);
    if (open) { _b2bRowOpen.delete(id); _b2bRowShut.add(id); }
    else      { _b2bRowShut.delete(id); _b2bRowOpen.add(id); }
    _b2bRepaintItems();
    if (!open) document.querySelector(`#b2bPline-${id} .b2b-rowpanel textarea`)?.focus();
}

function b2bToggleNotes(id) {
    if (_b2bNotesOpen.has(id)) _b2bNotesOpen.delete(id); else _b2bNotesOpen.add(id);
    _b2bRepaintItems();
}

// A one-line summary of what is folded away, so a closed row still says whether
// there is anything in there worth opening.
function _b2bNoteHint(it) {
    const bits = [];
    const specs = _b2bSpecsFor(it).map(f => String(it[f.key] ?? '').trim()).filter(Boolean);
    if (specs.length) bits.push(specs.join(' · '));
    const ser = _b2bSerials(it);
    if (ser.length) bits.push(ser.length === 1 ? ser[0] : `${ser.length} serials`);
    const client = String(it.client_notes || '').trim();
    const staff  = String(it.staff_notes || '').trim();
    if (client) bits.push(client);
    if (staff)  bits.push(`internal: ${staff}`);
    return bits.length ? bits.join(' · ') : 'No details yet';
}

// Just the line's own number in the grid. Every SKU on a deal shares the same
// ACM-007- prefix and the deal ref is already in the modal header, so repeating
// it down thirty rows spends the column on nothing. The full SKU is the cell's
// tooltip, and it is what prints on the label.
function _b2bLineNo(it) {
    const parts = String(it.sku || '').split('-');
    return parts.length > 1 ? parts[parts.length - 1] : String(it.line_no).padStart(4, '0');
}

// Rendered as a grid rather than a stack of cards: one row per line with the
// columns aligned, the way anyone pricing a pallet expects to read it.
function _b2bItemCards() {
    if (!_b2bModalItems.length) {
        return `<div class="b2b-empty sm">
            <div class="b2b-empty-t">No lines yet</div>
            <div class="b2b-empty-s">Add the first item to start pricing this pickup.</div>
        </div>`;
    }

    const head = `
        <div class="b2b-prow b2b-phead">
            <span>Line</span><span>Type</span><span>Brand</span><span>Model</span><span>Condition</span>
            <span class="r">Qty</span><span class="r">Unit value</span><span class="r">Unit offer</span>
            <span class="r">Line total</span><span></span>
        </div>`;

    const rows = _b2bModalItems.map(it => {
        const disp    = _b2bDispOf(it);
        const buy     = _b2bIsBuy(it);
        const scrap   = _b2bIsScrap(it);
        const tags    = _b2bPresetNotes(it);
        const needs   = _b2bNeedsReason(it);
        const missing = _b2bMissingReason(it);
        const blocked = _b2bItemBlocked(it);
        // Forced open whenever something is blocking submission: hiding the thing
        // you have to fix is the one case where folding costs more than it saves.
        const open    = _b2bNotesOpen.has(it.id) || blocked.length > 0;
        const free    = B2B_NOTE_TAGS.filter(t => !tags.includes(t));
        const specs   = _b2bSpecsFor(it);
        const serials = _b2bSerials(it);
        const need    = Number(it.quantity) || 1;
        const left    = need - serials.length;

        const specBlock = specs.length ? `
            <div class="b2b-specs">
                ${specs.map(f => `
                <div class="b2b-f b2b-spec">
                    <label>${f.label}${f.req ? ' <span class="b2b-tag-req">required</span>' : ''}</label>
                    <input value="${escapeHtml(it[f.key] || '')}" placeholder="${escapeHtml(f.hint)}"
                        oninput="b2bItemSpec('${it.id}','${f.key}',this.value)" onchange="b2bItemSave('${it.id}')">
                </div>`).join('')}
            </div>` : '';

        // Disposition and the wipe flag live here rather than in the row's action
        // cluster: they are pricing decisions, not per-click controls, and five
        // controls in one grid cell overflowed it. The row still reports their
        // state through the chips beside the SKU.
        const handling = `
            <div class="b2b-handling">
                <div class="b2b-f">
                    <label>What happens to it</label>
                    <select class="b2b-dispsel" onchange="b2bItemDisposition('${it.id}',this.value)">
                        ${B2B_DISPOSITIONS.map(d => `<option value="${d.key}" ${disp === d.key ? 'selected' : ''}>${d.label}</option>`).join('')}
                    </select>
                    <span class="b2b-hint sm">${escapeHtml(B2B_DISP[disp].hint)}</span>
                </div>
                <div class="b2b-f">
                    <label>Certified data wipe</label>
                    <div class="b2b-wipewrap">
                        <label class="b2b-rec-toggle b2b-wipetog">
                            <input type="checkbox" ${it.wipe_required ? 'checked' : ''} onchange="b2bItemWipe('${it.id}',this.checked)">
                            <span>${_b2bMoney(it.wipe_fee || _b2bWipeFee(), 2)} per unit${it.wipe_required && need > 1 ? ` · ${_b2bMoney(_b2bWipeTotal(it), 2)} total` : ''}</span>
                        </label>
                    </div>
                    <span class="b2b-hint sm">Comes off what we pay them. They are never charged for it.</span>
                </div>
            </div>`;

        const drawer = open ? `
            <div class="b2b-pdrawer">
                ${handling}
                ${specBlock}
                <div class="b2b-f b2b-serialf">
                    <label>Serial numbers
                        <span class="b2b-serial-count ${serials.length === need ? '' : 'miss'}">${serials.length} of ${need}</span>
                        <span class="b2b-tag-int">one per unit, comma separated</span></label>
                    <div class="b2b-serialrow">
                        <input value="${escapeHtml(it.serials || '')}" placeholder="C02X1234, C02X5678"
                            oninput="b2bItemSerials('${it.id}',this.value)" onchange="b2bItemSave('${it.id}')">
                        ${left > 0 ? `<button class="b2b-mini" onclick="b2bNoSerial('${it.id}',false)"
                            title="This unit has no serial you can read">No Visible Serial</button>` : ''}
                        ${left > 1 ? `<button class="b2b-mini" onclick="b2bNoSerial('${it.id}',true)"
                            title="Fill every remaining slot">Fill All ${left}</button>` : ''}
                    </div>
                </div>
                <div class="b2b-pnote">
                    <div class="b2b-f"><label>Staff notes <span class="b2b-tag-int">internal</span></label>
                        <input value="${escapeHtml(it.staff_notes || '')}" placeholder="Anything the team should know"
                            oninput="b2bItemInput('${it.id}','staff_notes',this.value)" onchange="b2bItemSave('${it.id}')"></div>
                    <div class="b2b-f"><label>Client notes
                        ${needs ? '<span class="b2b-tag-req">reason required</span>' : '<span class="b2b-tag-ext">prints on the quote</span>'}</label>
                        <div class="b2b-chiprow">
                            ${tags.map(t => `<span class="b2b-chip-tag">${escapeHtml(t)}<button title="Remove"
                                onclick="b2bItemToggleTag('${it.id}','${escapeHtml(t)}')">×</button></span>`).join('')}
                            ${free.length ? `
                            <select class="b2b-tagsel" onchange="b2bItemToggleTag('${it.id}',this.value)">
                                <option value="">${tags.length ? '＋ Another tag…' : '＋ Add a tag…'}</option>
                                ${free.map(t => `<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join('')}
                            </select>` : ''}
                        </div>
                        <input class="b2b-tag-free ${missing ? 'miss' : ''}" value="${escapeHtml(_b2bCustomNotes(it))}"
                            placeholder="${needs ? 'Why is it ' + escapeHtml(it.condition) + '? Pick a tag or type it here' : "Anything the tags don't cover"}"
                            oninput="b2bItemCustomNote('${it.id}',this.value)" onchange="b2bItemSave('${it.id}')">
                        <span class="b2b-req-note" style="${missing ? '' : 'display:none;'}">${escapeHtml(it.condition || '')} items need a reason before this can be quoted.</span></div>
                </div>
            </div>` : '';

        return `
        <div class="b2b-pline ${scrap ? 'b2b-scrap' : ''} ${_b2bIsNrv(it) ? 'b2b-nrv' : ''} ${blocked.length ? 'needs-reason' : ''}" id="b2bPline-${it.id}">
            <div class="b2b-prow">
                <span class="b2b-pcell b2b-pc-sku" title="${escapeHtml(it.sku || '')}">
                    <span class="b2b-mono">${escapeHtml(_b2bLineNo(it))}</span>
                    ${!buy ? `<span class="b2b-doc-rec ${scrap ? '' : 'nrv'}">${escapeHtml(B2B_DISP[disp].short)}</span>` : ''}
                    ${it.wipe_required ? '<span class="b2b-doc-rec wipe" title="Certified data wipe">Wipe</span>' : ''}
                </span>
                <span class="b2b-pcell" data-k="Type">
                    <select onchange="b2bItemType('${it.id}',this.value)">
                        ${B2B_ITEM_TYPES.map(t => `<option value="${t.key}" ${(it.item_type || 'other') === t.key ? 'selected' : ''}>${t.label}</option>`).join('')}
                    </select></span>
                <span class="b2b-pcell" data-k="Brand">
                    <input id="b2bMake-${it.id}" value="${escapeHtml(it.make || '')}" placeholder="Apple" list="b2bdl-make"
                        oninput="b2bItemInput('${it.id}','make',this.value)" onchange="b2bItemSave('${it.id}')"></span>
                <span class="b2b-pcell" data-k="Model">
                    <input value="${escapeHtml(it.model || '')}" placeholder="MacBook Air M2"
                        oninput="b2bItemInput('${it.id}','model',this.value)" onchange="b2bItemSave('${it.id}')"></span>
                <span class="b2b-pcell" data-k="Condition">
                    <select onchange="b2bItemCondition('${it.id}',this.value)">
                        <option value="">—</option>
                        ${B2B_CONDITIONS.map(c => `<option ${it.condition === c ? 'selected' : ''}>${c}</option>`).join('')}
                    </select></span>
                <span class="b2b-pcell n" data-k="Qty">
                    <input type="number" min="1" step="1" value="${need}"
                        oninput="b2bItemInput('${it.id}','quantity',this.value)" onchange="b2bItemSave('${it.id}')"></span>
                <span class="b2b-pcell n" data-k="Unit value">
                    ${scrap ? '<span class="b2b-f-off">—</span>'
                          : `<input type="number" min="0" step="0.01" value="${Number(it.value) || 0}"
                        oninput="b2bItemInput('${it.id}','value',this.value)" onchange="b2bItemSave('${it.id}')">`}</span>
                <span class="b2b-pcell n" data-k="Unit offer">
                    ${buy ? `<input type="number" min="0" step="0.01" value="${Number(it.offer) || 0}"
                        oninput="b2bItemInput('${it.id}','offer',this.value)" onchange="b2bItemSave('${it.id}')">`
                          : '<span class="b2b-f-off">—</span>'}</span>
                <span class="b2b-pcell n b2b-pc-tot" data-k="Line total">
                    ${_b2bLineTotalHtml(it)}</span>
                <span class="b2b-pcell b2b-pc-acts">
                    <!-- Print leads, delete trails, and the two are never
                         neighbours: they were one misclick apart and only one of
                         them can be undone. -->
                    ${_b2bLabelBtn(it)}
                    <button class="b2b-notes-btn ${open ? 'on' : ''} ${blocked.length ? 'req' : ''}"
                        title="${blocked.length ? 'Not ready yet — ' + escapeHtml(blocked.join(', ')) : escapeHtml(_b2bNoteHint(it))}"
                        onclick="b2bToggleNotes('${it.id}')">
                        ${_b2bIco('<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/>')}
                        ${(it.client_notes || it.staff_notes || it.serials) ? '<i class="b2b-notes-dot"></i>' : ''}
                    </button>
                    <button class="b2b-x" title="Remove line" onclick="b2bDeleteItem('${it.id}')">
                        ${_b2bIco('<line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>')}
                    </button>
                </span>
            </div>
            ${open ? '' : _b2bNoteLine(it)}
            <div class="b2b-ready" style="${blocked.length ? '' : 'display:none;'}">${escapeHtml(blocked.join(' · '))}</div>
            ${drawer}
        </div>`;
    }).join('');

    // Mounted once for the whole grid, not per row -- thirty lines would
    // otherwise repeat the same option lists thirty times.
    return _b2bDatalists() + head + rows;
}

// --- pricing spreadsheet ---------------------------------------------------
// Same data as _b2bItemCards, but every line stays a single dense row: the
// disposition and the wipe flag are their own columns, and the bulky per-line
// detail (specs, serials, notes) opens behind the ⋯ in a focused sheet rather
// than an inline drawer that grows the row. Quote keeps _b2bItemCards untouched.
const _B2B_ICO_DETAIL = '<line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/>'
    + '<line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/>'
    + '<line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/>';
const _B2B_ICO_X = '<line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>';
// Feather "copy": two offset sheets. Reads as duplicate rather than as the
// clipboard sense of copy, which is what this does.
const _B2B_ICO_COPY = '<rect x="9" y="9" width="13" height="13" rx="2" ry="2"/>'
    + '<path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>';

// Everything a line needs that will not fit on the row, in flow underneath it
// rather than in a modal on top of it. Wide boxes, because these are sentences:
// the old popup gave them a single-line input in a 260px drawer.
//
// Serials are absent on an evaluation -- nobody has held these units -- and so is
// the label, which is minted at conversion.
function _b2bRowPanel(it) {
    const need    = Number(it.quantity) || 1;
    const serials = _b2bSerials(it);
    const left    = need - serials.length;
    const gpu     = B2B_SPEC_FIELDS.find(f => f.key === 'gpu');
    const carries = (B2B_SPECS_FOR[it.item_type || 'other'] || []).includes('gpu');
    return `
        <div class="b2b-rowpanel">
            ${_b2bIsPreval() ? '' : `
            <div class="b2b-rp-f b2b-rp-serials">
                <label>Serials
                    <span class="b2b-serial-count ${serials.length === need ? '' : 'miss'}">${serials.length} of ${need}</span>
                </label>
                <div class="b2b-rp-serialrow">
                    <input value="${escapeHtml(it.serials || '')}" placeholder="C02X1234, C02X5678 — one per unit, comma separated"
                        oninput="b2bItemSerials('${it.id}',this.value)" onchange="b2bItemSave('${it.id}')">
                    ${left > 0 ? `<button class="b2b-mini" onclick="b2bNoSerial('${it.id}',false)" title="This unit has no serial you can read">No Visible Serial</button>` : ''}
                    ${left > 1 ? `<button class="b2b-mini" onclick="b2bNoSerial('${it.id}',true)" title="Fill every remaining slot">Fill All ${left}</button>` : ''}
                </div>
            </div>`}
            ${carries ? `
            <div class="b2b-rp-f b2b-rp-gpu">
                <label>${escapeHtml(gpu.label)}</label>
                <input value="${escapeHtml(it.gpu || '')}" placeholder="${escapeHtml(gpu.hint)}" list="b2bdl-gpu"
                    oninput="b2bItemSpec('${it.id}','gpu',this.value)" onchange="b2bItemSave('${it.id}')">
            </div>` : ''}
            <div class="b2b-rp-f">
                <label>Listing info <span class="b2b-tag-int">for whoever lists it</span></label>
                <textarea rows="2" placeholder="Anything the lister needs that no other field covers — a missing charger, a cracked bezel, which port is dead"
                    oninput="b2bItemInput('${it.id}','listing_info',this.value)" onchange="b2bItemSave('${it.id}')">${escapeHtml(it.listing_info || '')}</textarea>
            </div>
            <div class="b2b-rp-f">
                <label>Staff notes <span class="b2b-tag-int">internal</span></label>
                <textarea rows="2" placeholder="Anything the team should know — never leaves the building"
                    oninput="b2bItemInput('${it.id}','staff_notes',this.value)" onchange="b2bItemSave('${it.id}')">${escapeHtml(it.staff_notes || '')}</textarea>
            </div>
            ${_b2bIsPreval() ? '' : `<div class="b2b-rp-foot">${_b2bLabelBtn(it, 'b2b-mini')}</div>`}
        </div>`;
}

function _b2bItemSheet() {
    if (!_b2bModalItems.length) {
        return `<div class="b2b-empty sm">
            <div class="b2b-empty-t">No lines yet</div>
            <div class="b2b-empty-s">Add the first item to start pricing this pickup.</div>
        </div>`;
    }

    // The three required specs (CPU / RAM / Storage) are columns, not a detail
    // view -- a keyboard pricer tabs straight across them. GPU and battery stay
    // optional, so they live behind the ⋯ with serials and notes.
    // Battery health joins CPU/RAM/Storage on the row. It is not required -- a
    // dead battery reports nothing -- but it changes what a machine is worth, and
    // hiding it behind the ⋯ meant you could not tell at a glance whether a
    // quantity line was worth having.
    const sheetSpecs = B2B_SPEC_FIELDS.filter(f => f.req || f.key === 'battery_health');

    const head = `
        <div class="b2b-prow b2b-phead">
            <span>Line</span><span>Type</span><span>Brand</span><span>Model</span>
            ${sheetSpecs.map(f => `<span>${escapeHtml(f.label)}${
                f.req ? '<i class="b2b-req-star" title="Required before this can be quoted">*</i>' : ''}</span>`).join('')}
            <span>Condition</span>
            <span class="r">Qty</span><span class="r">Value</span><span class="r">Offer</span>
            <span class="r" title="What it costs us to move one of these, per unit. Never shown to the client.">Ship</span>
            <span class="r">Margin</span>
            <span>Handling</span><span class="c">Wipe</span>
            <span title="Prints on the client's quote. Required on a Fair or Broken line.">Client Notes</span>
            <span class="r">Total</span><span></span>
        </div>`;

    const rows = _b2bModalItems.map(it => {
        const disp    = _b2bDispOf(it);
        const buy     = _b2bIsBuy(it);
        const scrap   = _b2bIsScrap(it);
        const need    = Number(it.quantity) || 1;
        const blocked = _b2bItemBlocked(it);
        const fee     = it.wipe_fee || _b2bWipeFee();
        const carries = _b2bSpecsFor(it);
        // A line "has detail" if the ⋯ sheet holds anything worth reopening for --
        // serials, notes, or an optional spec (GPU/battery). The required specs
        // are inline now, so they don't count toward the dot.
        const hasDetail = !!(String(it.staff_notes || '').trim() || String(it.listing_info || '').trim()
            || _b2bSerials(it).length || String(it.gpu || '').trim());
        // Anything blocking the line pops its panel open unasked -- the point of
        // the flag is that you can see what to fix, not hunt for it -- unless it
        // has been collapsed by hand, which outranks that.
        const rowOpen = _b2bRowIsOpen(it);

        // CPU / RAM / Storage cells: an editable field for a type that carries
        // them, a dash for one that doesn't (e.g. Other), each with a one-tap ∅
        // that stamps NO CPU / NO RAM / NO STORAGE.
        const specCells = sheetSpecs.map(f => {
            if (!carries.some(s => s.key === f.key)) {
                return `<span class="b2b-pcell b2b-pc-spec" data-k="${escapeHtml(f.label)}"><span class="b2b-f-off">—</span></span>`;
            }
            // Only a REQUIRED spec can be missing. Battery health left blank is a
            // fact about the battery, not a gap in the pricing, so it never gets
            // flagged and never blocks a submit.
            const miss = f.req && !String(it[f.key] ?? '').trim();
            return `<span class="b2b-pcell b2b-pc-spec" data-k="${escapeHtml(f.label)}">
                <input ${f.req ? `data-req-spec="${f.key}"` : ''} class="${miss ? 'b2b-spec-miss' : ''}" value="${escapeHtml(it[f.key] || '')}" placeholder="${escapeHtml(f.hint)}"
                    ${f.pick ? `list="b2bdl-${f.key}"` : ''}
                    oninput="b2bItemSpec('${it.id}','${f.key}',this.value)" onchange="b2bItemSave('${it.id}')">
                <button class="b2b-spec-none" tabindex="-1" title="No ${escapeHtml(f.label)} — fills NO ${escapeHtml(f.label.toUpperCase())}"
                    onclick="b2bItemSpecNone('${it.id}','${f.key}','${escapeHtml(f.label)}')">∅</button>
            </span>`;
        }).join('');

        return `
        <div class="b2b-pline ${scrap ? 'b2b-scrap' : ''} ${_b2bIsNrv(it) ? 'b2b-nrv' : ''} ${blocked.length ? 'needs-reason' : ''}" id="b2bPline-${it.id}">
            <div class="b2b-prow">
                <span class="b2b-pcell b2b-pc-sku ${_b2bIsPreval() ? '' : 'b2b-pc-grab'}" ${_b2bIsPreval() ? '' : 'draggable="true"'}
                    title="${_b2bIsPreval() ? 'Line ' + escapeHtml(String(it.line_no)) : escapeHtml(it.sku || '') + ' — drag to reorder'}"
                    ${_b2bIsPreval() ? '' : `ondragstart="b2bDragStart(event,'${it.id}')" ondragend="b2bDragEnd()"
                    ondragover="b2bDragOver(event,'${it.id}')" ondrop="b2bDrop(event,'${it.id}')"`}>
                    <span class="b2b-mono">${escapeHtml(_b2bIsPreval() ? String(it.line_no) : _b2bLineNo(it))}</span>
                    ${blocked.length ? `<i class="b2b-ss-flag" title="${escapeHtml(blocked.join(', '))}"></i>` : ''}
                    ${_b2bLabelsShort(it) ? `<i class="b2b-ss-untagged" title="${
                        _b2bLabelsShort(it)} unit${_b2bLabelsShort(it) === 1 ? '' : 's'} on this line still have no label printed"></i>` : ''}
                </span>
                <span class="b2b-pcell" data-k="Type">
                    <select onchange="b2bItemType('${it.id}',this.value)">
                        ${B2B_ITEM_TYPES.map(t => `<option value="${t.key}" ${(it.item_type || 'other') === t.key ? 'selected' : ''}>${t.label}</option>`).join('')}
                    </select></span>
                <!-- title as well as value: these two are the narrowest text
                     columns on the sheet and "OptiPlex 7080 Micro" does not fit
                     in one, so hovering has to be able to tell you the rest. -->
                <span class="b2b-pcell" data-k="Brand">
                    <input id="b2bMake-${it.id}" value="${escapeHtml(it.make || '')}" placeholder="Apple" list="b2bdl-make"
                        title="${escapeHtml(it.make || '')}"
                        oninput="b2bItemInput('${it.id}','make',this.value)" onchange="b2bItemSave('${it.id}')"></span>
                <span class="b2b-pcell" data-k="Model">
                    <input value="${escapeHtml(it.model || '')}" placeholder="MacBook Air M2"
                        title="${escapeHtml(it.model || '')}"
                        oninput="b2bItemInput('${it.id}','model',this.value)" onchange="b2bItemSave('${it.id}')"></span>
                ${specCells}
                <span class="b2b-pcell" data-k="Condition">
                    <select onchange="b2bItemCondition('${it.id}',this.value)">
                        <option value="">—</option>
                        ${B2B_CONDITIONS.map(c => `<option ${it.condition === c ? 'selected' : ''}>${c}</option>`).join('')}
                    </select></span>
                <span class="b2b-pcell n" data-k="Qty">
                    <input type="number" min="1" step="1" value="${need}"
                        oninput="b2bItemInput('${it.id}','quantity',this.value)" onchange="b2bItemSave('${it.id}')"></span>
                <span class="b2b-pcell n" data-k="Value">
                    ${scrap ? '<span class="b2b-f-off">—</span>'
                          : `<input type="number" min="0" step="0.01" value="${Number(it.value) || 0}"
                        oninput="b2bItemInput('${it.id}','value',this.value)" onchange="b2bItemSave('${it.id}')">`}</span>
                <span class="b2b-pcell n" data-k="Offer">
                    ${buy ? `<input type="number" min="0" step="0.01" value="${Number(it.offer) || 0}"
                        oninput="b2bItemInput('${it.id}','offer',this.value)" onchange="b2bItemSave('${it.id}')">`
                          : '<span class="b2b-f-off">—</span>'}</span>
                <!-- Blank on a recycle line, like Value and Offer: we do not pay
                     to ship scrap, so zero is the true figure rather than a
                     rounding of one. All three money columns now agree that a
                     recycle line costs nothing and earns nothing. -->
                <span class="b2b-pcell n" data-k="Ship">
                    ${scrap ? '<span class="b2b-f-off">—</span>'
                          : `<input type="number" min="0" step="0.01" value="${Number(it.shipping_cost) || 0}"
                        title="Our freight cost per unit — never shown to the client"
                        oninput="b2bItemInput('${it.id}','shipping_cost',this.value)" onchange="b2bItemSave('${it.id}')">`}</span>
                <span class="b2b-pcell n b2b-pc-mgn" data-k="Margin">
                    ${_b2bLineMarginHtml(it)}</span>
                <span class="b2b-pcell b2b-pc-disp" data-k="Handling">
                    <select data-tip="${escapeHtml(B2B_DISP[disp].hint)}" onchange="b2bItemDisposition('${it.id}',this.value)">
                        ${B2B_DISPOSITIONS.map(d => `<option value="${d.key}" ${disp === d.key ? 'selected' : ''}>${_B2B_DISP_SEL[d.key]}</option>`).join('')}
                    </select></span>
                <span class="b2b-pcell b2b-pc-wipe" data-k="Wipe">
                    <label class="b2b-ss-wipe" title="Certified data wipe · ${_b2bMoney(fee, 2)}/unit">
                        <input type="checkbox" ${it.wipe_required ? 'checked' : ''} onchange="b2bItemWipe('${it.id}',this.checked)"></label></span>
                <!-- The one note that reaches the client, on the row rather than
                     two clicks away. It is required on a Fair or Broken line, and
                     a required field you cannot see is the reason lines kept
                     reaching the approver unready. -->
                <span class="b2b-pcell b2b-pc-note" data-k="Client Notes">
                    <input class="${_b2bMissingReason(it) ? 'b2b-note-miss' : ''}"
                        value="${escapeHtml(it.client_notes || '')}"
                        title="${escapeHtml(it.client_notes || '')}"
                        placeholder="${_b2bNeedsReason(it) ? 'Why is it ' + escapeHtml(it.condition) + '?' : 'Prints on the quote'}"
                        oninput="b2bItemClientNote('${it.id}',this.value)" onchange="b2bItemSave('${it.id}')"></span>
                <span class="b2b-pcell n b2b-pc-tot" data-k="Total">
                    ${_b2bLineTotalHtml(it)}</span>
                <span class="b2b-pcell b2b-pc-acts">
                    <button class="b2b-notes-btn b2b-ss-copy" title="Copy this line — everything but the serials"
                        onclick="b2bCopyItem('${it.id}',this)">${_b2bIco(_B2B_ICO_COPY)}</button>
                    <!-- Expands in place. It used to open a modal over the sheet,
                         which is the "separate button" nobody liked: it covered
                         the row you were working on, trapped focus, and threw
                         itself away if a drag-select strayed past its edge. -->
                    <button class="b2b-notes-btn b2b-ss-more ${hasDetail ? 'has' : ''} ${blocked.length ? 'req' : ''} ${rowOpen ? 'on' : ''}"
                        title="${blocked.length ? 'Not ready — ' + escapeHtml(blocked.join(', ')) : 'Serials, listing info & staff notes'}"
                        aria-expanded="${rowOpen ? 'true' : 'false'}"
                        onclick="b2bToggleRow('${it.id}')">
                        <span class="b2b-rowtoggle">${rowOpen ? '−' : '+'}</span>
                        ${hasDetail ? '<i class="b2b-notes-dot"></i>' : ''}
                    </button>
                    <button class="b2b-x" title="Remove line" onclick="b2bDeleteItem('${it.id}')">${_b2bIco(_B2B_ICO_X)}</button>
                </span>
            </div>
            ${rowOpen ? _b2bRowPanel(it) : ''}
            <div class="b2b-ready" style="${blocked.length ? '' : 'display:none;'}">${escapeHtml(blocked.join(' · '))}</div>
        </div>`;
    }).join('');

    // Mounted once for the whole grid, not per row -- thirty lines would
    // otherwise repeat the same option lists thirty times.
    return _b2bDatalists() + head + rows;
}

// --- pricing detail sheet --------------------------------------------------
// The spreadsheet's ⋯ opens this over the grid: the type's spec fields, the
// per-unit serials, and the staff / client notes -- everything that would make a
// row tall. It reuses the very same per-field handlers as the cards drawer, so
// edits save and re-validate identically; _b2bRepaintItems repaints it in step.
function b2bItemDetail(id) {
    if (!_b2bLocalItem(id)) return;
    _b2bSheetId = id;
    let el = document.getElementById('b2bItemSheet');
    if (!el) {
        el = document.createElement('div');
        el.id = 'b2bItemSheet';
        document.body.appendChild(el);
        // Click the dimmed area (never the panel) to close.
        //
        // Both ends of the click have to land on the backdrop. `click` fires on
        // the nearest common ancestor of mousedown and mouseup, so dragging to
        // select text inside a field and releasing beyond the panel edge -- which
        // is what anyone highlighting a serial does -- reported the backdrop as
        // the target and threw the sheet away mid-edit.
        let pressedOnBackdrop = false;
        el.addEventListener('mousedown', e => { pressedOnBackdrop = e.target === el; });
        el.addEventListener('click', e => {
            if (e.target === el && pressedOnBackdrop) b2bCloseItemSheet();
            pressedOnBackdrop = false;
        });
    }
    _b2bPaintItemSheet();
    // Land the cursor on whatever is blocking the line, else the first field.
    const focus = el.querySelector('.b2b-tag-free.miss, .b2b-spec-miss')
        || el.querySelector('.b2b-isheet-body input, .b2b-isheet-body textarea');
    focus?.focus();
}

function b2bCloseItemSheet() {
    const wasOpen = _b2bSheetId != null;
    document.getElementById('b2bItemSheet')?.remove();
    _b2bSheetId = null;
    // Repaint the grid so the row reflects anything changed in the sheet -- the
    // ⋯ "has detail" dot, a serial count, a cleared block. Safe on close: no
    // field is focused. Only the spreadsheet uses this sheet.
    if (wasOpen && _b2bGridMode === 'sheet') _b2bRepaintItems();
}

function _b2bPaintItemSheet() {
    const el = document.getElementById('b2bItemSheet');
    const it = _b2bSheetId != null ? _b2bLocalItem(_b2bSheetId) : null;
    if (!el || !it) return;
    el.innerHTML = `<div class="b2b-isheet-panel" role="dialog" aria-modal="true" aria-label="Line detail">${_b2bItemSheetBody(it)}</div>`;
}

function _b2bItemSheetBody(it) {
    const needs   = _b2bNeedsReason(it);
    const missing = _b2bMissingReason(it);
    // Required specs (CPU/RAM/Storage) are inline columns on the grid now; the
    // sheet only carries the optional ones (GPU, battery health) alongside
    // serials and notes.
    const specs   = _b2bSpecsFor(it).filter(f => !f.req);
    const serials = _b2bSerials(it);
    const need    = Number(it.quantity) || 1;
    const left    = need - serials.length;
    const blocked = _b2bItemBlocked(it);
    const typeLabel = (B2B_ITEM_TYPES.find(t => t.key === (it.item_type || 'other')) || {}).label || 'Other';

    const specBlock = specs.length ? `
        <div class="b2b-isheet-sec">
            <h5>Optional specs</h5>
            <div class="b2b-specs">
                ${specs.map(f => `
                    <div class="b2b-f b2b-spec">
                        <label>${f.label}</label>
                        <input value="${escapeHtml(it[f.key] || '')}" placeholder="${escapeHtml(f.hint)}"
                            oninput="b2bItemSpec('${it.id}','${f.key}',this.value)" onchange="b2bItemSave('${it.id}')">
                    </div>`).join('')}
            </div>
        </div>` : '';

    return `
        <div class="b2b-isheet-head">
            <div class="b2b-isheet-id">
                <span class="b2b-isheet-sku b2b-mono">${escapeHtml(_b2bIsPreval() ? 'Line ' + it.line_no : (it.sku || _b2bLineNo(it)))}</span>
                <div>
                    <div class="b2b-isheet-name">${escapeHtml(_b2bItemName(it))}</div>
                    <div class="b2b-isheet-meta">${escapeHtml(typeLabel)} · Qty ${need}${it.condition ? ' · ' + escapeHtml(it.condition) : ''} · ${escapeHtml(B2B_DISP[_b2bDispOf(it)].label)}</div>
                </div>
            </div>
            <div class="b2b-isheet-actions">
                ${_b2bIsPreval() ? '' : _b2bLabelBtn(it)}
                <button class="modal-close-btn" onclick="b2bCloseItemSheet()" aria-label="Close">${_b2bIco(_B2B_ICO_X)}</button>
            </div>
        </div>
        ${blocked.length ? `<div class="b2b-note warn b2b-isheet-block"><span class="b2b-note-k">Not ready</span>${escapeHtml(blocked.join(' · '))}</div>` : ''}
        <div class="b2b-isheet-body">
            ${specBlock}
            ${_b2bIsPreval() ? '' : `
            <div class="b2b-isheet-sec">
                <h5>Serial numbers <span class="b2b-serial-count ${serials.length === need ? '' : 'miss'}">${serials.length} of ${need}</span> <span class="b2b-tag-int">one per unit</span></h5>
                <div class="b2b-f b2b-serialf">
                    <div class="b2b-serialrow">
                        <input value="${escapeHtml(it.serials || '')}" placeholder="C02X1234, C02X5678 — comma separated"
                            oninput="b2bItemSerials('${it.id}',this.value)" onchange="b2bItemSave('${it.id}')">
                        ${left > 0 ? `<button class="b2b-mini" onclick="b2bNoSerial('${it.id}',false)" title="This unit has no serial you can read">No Visible Serial</button>` : ''}
                        ${left > 1 ? `<button class="b2b-mini" onclick="b2bNoSerial('${it.id}',true)" title="Fill every remaining slot">Fill All ${left}</button>` : ''}
                    </div>
                </div>
            </div>`}
            <!-- Present here as well as in the spreadsheet's row panel: the card
                 grid is what the quote and view screens use, and a field you can
                 only reach from one of the two grids is a field people will
                 swear does not exist. -->
            <div class="b2b-isheet-sec">
                <h5>Listing info <span class="b2b-tag-int">for whoever lists it</span></h5>
                <div class="b2b-f">
                    <textarea class="b2b-tag-free" rows="2"
                        placeholder="Anything the lister needs that no other field covers"
                        oninput="b2bItemInput('${it.id}','listing_info',this.value)"
                        onchange="b2bItemSave('${it.id}')">${escapeHtml(it.listing_info || '')}</textarea>
                </div>
            </div>
            <div class="b2b-isheet-sec">
                <h5>Staff notes <span class="b2b-tag-int">internal</span></h5>
                <div class="b2b-f">
                    <input value="${escapeHtml(it.staff_notes || '')}" placeholder="Anything the team should know"
                        oninput="b2bItemInput('${it.id}','staff_notes',this.value)" onchange="b2bItemSave('${it.id}')"></div>
            </div>
            <div class="b2b-isheet-sec">
                <h5>Client notes ${needs ? '<span class="b2b-tag-req">reason required</span>' : '<span class="b2b-tag-ext">prints on the quote</span>'}</h5>
                <div class="b2b-f">
                    <textarea class="b2b-tag-free ${missing ? 'miss' : ''}" rows="2"
                        placeholder="${needs ? 'Why is it ' + escapeHtml(it.condition) + '? This prints on the client quote' : 'Anything the client should see — prints on the quote'}"
                        oninput="b2bItemClientNote('${it.id}',this.value)" onchange="b2bItemSave('${it.id}')">${escapeHtml(it.client_notes || '')}</textarea>
                    <span class="b2b-req-note" style="${missing ? '' : 'display:none;'}">${escapeHtml(it.condition || '')} items need a reason before this can be quoted.</span>
                </div>
            </div>
        </div>
        <div class="b2b-isheet-foot">
            <span class="b2b-isheet-hint">Changes save as you go.</span>
            <button class="b2b-btn b2b-btn-primary" onclick="b2bCloseItemSheet()">Done</button>
        </div>`;
}

function _b2bTotalsBar(showMargin) {
    return `
    <div class="b2b-totals">
        <div class="b2b-tot"><span class="b2b-tot-k">Items</span><span class="b2b-tot-v" id="b2bTotUnits">—</span></div>
        <div class="b2b-tot"><span class="b2b-tot-k">Resale value</span><span class="b2b-tot-v" id="b2bTotValue">—</span></div>
        <div class="b2b-tot muted"><span class="b2b-tot-k">Data wipes</span><span class="b2b-tot-v" id="b2bTotWipe">—</span></div>
        <div class="b2b-tot"><span class="b2b-tot-k">We pay</span><span class="b2b-tot-v accent" id="b2bTotOffer">—</span></div>
        <!-- Sits after "We pay" deliberately: it is a cost of ours that lands
             on top of the offer, not a deduction from it like the wipes. -->
        <div class="b2b-tot muted"><span class="b2b-tot-k">Shipping</span><span class="b2b-tot-v" id="b2bTotShip">—</span></div>
        <!-- Sits with shipping, not with the wipe: both are costs that stand
             between the resale value and us, where the wipe is money the client
             does not receive. -->
        <div class="b2b-tot muted" title="Assumed marketplace cut, ${Math.round(B2B_MARKETPLACE_FEE * 100)}% of resale value">
            <span class="b2b-tot-k">Selling fees</span><span class="b2b-tot-v" id="b2bTotFee">—</span></div>
        ${showMargin ? '<div class="b2b-tot"><span class="b2b-tot-k">Gross margin</span><span class="b2b-tot-v" id="b2bTotMargin">—</span></div>' : ''}
    </div>`;
}

// --- stage 3: pricing ------------------------------------------------------

// A deal that came back from the approver leads with why. Whoever re-prices it
// may not be whoever priced it the first time, so this has to be the first thing
// on the screen rather than a line in a history somewhere.
// A deal that came from an evaluation was priced before anyone saw the goods,
// and the client has already agreed to those figures. Whoever prices it now is
// often not whoever quoted it, so this has to be on the screen rather than
// buried in a field: changing a number here changes a number they accepted.
function _b2bPrevalOriginNote(deal) {
    if (!deal.preval_ref) return '';
    return `
        <div class="b2b-note b2b-from-pv">
            <span class="b2b-note-k">Priced in advance — evaluation ${escapeHtml(deal.preval_ref)}</span>
            These lines came from an evaluation the client accepted. Correct anything that turns
            out different in person, but a change here is a change to a figure they were quoted.
        </div>`;
}

function _b2bSendbackNote(deal) {
    if (!deal.sendback_note) return '';
    const who = [deal.sendback_by, deal.sendback_at ? _b2bDate(deal.sendback_at) : '']
        .filter(Boolean).join(' · ');
    return `
        <div class="b2b-note warn b2b-sentback">
            <span class="b2b-note-k">Sent back for changes${who ? ` — ${escapeHtml(who)}` : ''}</span>
            ${escapeHtml(deal.sendback_note)}
        </div>`;
}

function _b2bStagePricing(deal) {
    _b2bGridMode = 'sheet';
    _b2bShowDeal({
        delDeal: deal,
        stage: 'pricing',
        eyebrow: deal.ref,
        title: 'Price The Pickup',
        sub: 'Itemize what came in. Every change saves as you go.',
        full: true,
        body: `
            ${_b2bSummary(deal)}
            ${_b2bSendbackNote(deal)}
            ${_b2bPrevalOriginNote(deal)}
            ${deal.pickup_desc ? `<div class="b2b-note"><span class="b2b-note-k">${_b2bIntake(deal).was}</span>${escapeHtml(deal.pickup_desc)}</div>` : ''}
            ${_b2bTotalsBar(true)}
            ${_b2bCustPanel(deal)}
            <div id="b2bItemGrid" class="b2b-items b2b-ss">${_b2bItemSheet()}</div>
            ${_b2bDispLegend()}
            <button class="b2b-btn b2b-btn-secondary b2b-add" onclick="b2bAddItem('${deal.id}',this)">＋ Add Line Item</button>
            ${_b2bDealStatsHtml(_b2bModalItems, deal)}`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            ${_b2bMoveBtn(deal)}
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Close</button>
            ${_b2bIsEmployee()
                ? '<span class="b2b-msg" style="color:var(--cb-muted);font-weight:600;">Prices save automatically — a manager or DM submits this for quoting.</span>'
                : `<button class="b2b-btn b2b-btn-primary" id="b2bPrSubmit" ${_b2bModalItems.length ? '' : 'disabled'}
                onclick="b2bSubmitPricing('${deal.id}',this)">Submit For Quoting</button>`}`,
        after: _b2bPaintTotals,
    });
}

async function b2bSubmitPricing(id, btn) {
    if (_b2bIsEmployee()) return _b2bSay('Only a manager or DM can submit pricing for quoting.', true);
    if (!_b2bModalItems.length) return;
    // Named per line rather than a bare count -- "3 lines aren't ready" makes you
    // hunt for them, and the server would refuse anyway.
    const gaps = _b2bNotReady();
    if (gaps.length) {
        if (_b2bGridMode === 'sheet') {
            _b2bRepaintItems();
            // Put the cursor on the first gap: a missing spec is an inline cell, a
            // missing serial or condition reason lives in the ⋯ detail sheet.
            const g = gaps[0];
            const line = document.getElementById(`b2bPline-${g.id}`);
            line?.scrollIntoView({ block: 'center' });
            const missSpec = _b2bMissingSpecs(g)[0];
            if (missSpec) {
                line?.querySelector(`[data-req-spec="${missSpec.key}"]`)?.focus();
            } else if (_b2bMissingReason(g)) {
                // The client note is a column now, so the reason is right there.
                line?.querySelector('.b2b-pc-note input')?.focus();
            } else {
                // Serials, which live in the row panel.
                _b2bRowOpen.add(g.id);
                _b2bRowShut.delete(g.id);
                _b2bRepaintItems();
                document.querySelector(`#b2bPline-${g.id} .b2b-rp-serialrow input`)?.focus();
            }
        } else {
            // Cards mode fixes lines in the inline drawer.
            gaps.forEach(it => _b2bNotesOpen.add(it.id));
            _b2bRepaintItems();
        }
        return _b2bSay(gaps.map(it => `${_b2bItemName(it)} (${_b2bItemBlocked(it).join(', ')})`).join(' · '), true);
    }
    // Warn about untagged units, and let it through anyway. Ethan asked for the
    // print to be REQUIRED; a hard block was rejected because a printer that is
    // down would strand the whole pallet. So this is the last moment it can be
    // said, said plainly, with the count -- and the decision stays with whoever
    // is holding the goods.
    const short = _b2bUnlabelled();
    const shortNote = short.length
        ? `\n\n${short.reduce((n, it) => n + _b2bLabelsShort(it), 0)} unit${
            short.reduce((n, it) => n + _b2bLabelsShort(it), 0) === 1 ? '' : 's'} across ${
            short.length} line${short.length === 1 ? '' : 's'} have no label printed yet:\n  · ${
            short.slice(0, 8).map(it => `${_b2bItemName(it)} (${_b2bLabelsShort(it)})`).join('\n  · ')}${
            short.length > 8 ? `\n  · …and ${short.length - 8} more` : ''}\n\nYou can still submit.`
        : '';
    if (!confirm('Submit this pricing? SKUs get assigned now so labels can be printed, '
        + 'and the approver is emailed that a quote is ready to send.' + shortNote)) return;
    await _b2bBusy(btn, 'Submitting…', async () => {
        await _b2bPost({ action: 'submit_pricing', id, priced_by: _b2bUser() }, "Couldn't submit the pricing");
        _b2bDirty = false;
        closeAllModals();
        await b2bRefresh();
    });
}

// --- stage 4: quote --------------------------------------------------------
// The quote stays fully editable while the client negotiates. Accepting is the
// one-way door: offers freeze into cost and the goods become our inventory.

// Waiting on the approver rather than on the client. This was derived from
// quote_send_count in five places; it is a stage now, and this reads it in one.
function _b2bAwaitingApproval(deal) {
    return deal.stage === 'review';
}

// Deals whose send step has already been offered this session, so re-opening one
// to re-read it doesn't trap you in the same dialog every time.
const _b2bSendPrompted = new Set();

// Where the goods physically are, and where they are going.
//
// Paul, reviewing a quote: "Need to show what location the product is at ... I
// need to know where it's at and where it's going to go." Both facts were
// already in _b2bSummary, but that is a grid of eight small cells you scan past;
// this is a question asked once per deal and it should answer itself.
//
// The interesting case is CORP: pricing there means the listing store is chosen
// separately after the client accepts, so there genuinely is no answer to the
// second half yet, and saying so is better than showing "Unassigned".
function _b2bWhereLine(deal) {
    if (!deal.pricing_store) return '';
    const at = deal.pricing_store;
    const to = deal.listing_store || (at === 'CORP' ? null : at);
    const going = to
        ? (to === at ? 'lists where it already is' : `lists at ${_b2bStoreTag(to)}`)
        : 'listing store is chosen once the client accepts';
    return `
        <div class="b2b-note b2b-where">
            <span class="b2b-note-k">Where it is</span>
            ${_b2bStoreTag(at)} <span class="b2b-where-go">— ${going}</span>
        </div>`;
}

// Approving a quote is not the same job as pricing one, and it had the same
// screen. MOCD, on Paul's behalf: only the essential context, easy on the eyes,
// "instead of being able to change each and everything. Especially if something
// is wrong he is just going to send it back to the previous phase anyways. Still
// make it so he can adjust pricing of course though."
//
// So: the client-facing document is the main object on the screen, the lines
// below it are read-only EXCEPT the offer, and everything else that could be
// wrong is a reason to send it back rather than a field to fix here. The full
// sheet is one click away for the times that judgement is wrong.
let _b2bReviewFull = false;
function b2bReviewFull(on) { _b2bReviewFull = !!on; b2bOpenDeal('quote', _b2bModalDeal.id); }

// The lines, as something to check rather than something to fill in. Offer is
// the one editable cell -- it is the number being approved, and a typo there is
// the one correction not worth a whole round trip through pricing.
function _b2bReviewLines() {
    if (!_b2bModalItems.length) {
        return '<div class="b2b-empty sm"><div class="b2b-empty-t">No lines on this quote</div></div>';
    }
    const rows = _b2bModalItems.map(it => {
        const qty  = Number(it.quantity) || 1;
        const buy  = _b2bIsBuy(it);
        const disp = _b2bDispOf(it);
        const spec = _b2bQuoteDesc(it);
        return `
        <div class="b2b-rvw-row ${_b2bIsScrap(it) ? 'b2b-scrap' : ''} ${_b2bIsNrv(it) ? 'b2b-nrv' : ''}" data-rvw="${it.id}">
            <div class="b2b-rvw-what">
                <div class="b2b-rvw-name">${escapeHtml(_b2bItemName(it))}
                    ${it.condition ? `<span class="b2b-chip b2b-chip-${_b2bCondChip(it.condition)}">${escapeHtml(it.condition)}</span>` : ''}
                    ${!buy ? `<span class="b2b-chip b2b-chip-neu">${escapeHtml(B2B_DISP[disp].label)}</span>` : ''}
                    ${it.wipe_required ? '<span class="b2b-chip b2b-chip-info">Certified wipe</span>' : ''}
                </div>
                ${spec ? `<div class="b2b-rvw-spec">${escapeHtml(spec)}</div>` : ''}
                ${it.client_notes ? `<div class="b2b-rvw-note">${escapeHtml(it.client_notes)}</div>` : ''}
            </div>
            <div class="b2b-rvw-qty">×${qty}</div>
            <div class="b2b-rvw-mgn">${_b2bLineMarginHtml(it)}</div>
            <div class="b2b-rvw-offer">
                ${buy ? `<input type="number" min="0" step="0.01" value="${Number(it.offer) || 0}"
                        aria-label="Offer per unit"
                        oninput="b2bItemInput('${it.id}','offer',this.value)"
                        onchange="b2bReviewOffer('${it.id}')">`
                      : '<span class="b2b-f-off">—</span>'}
            </div>
            <div class="b2b-rvw-tot">${buy ? _b2bMoney((Number(it.offer) || 0) * qty, 2) : '—'}</div>
        </div>`;
    }).join('');
    return `
        <div class="b2b-rvw">
            <div class="b2b-rvw-head">
                <span>Item</span><span class="c">Qty</span><span class="r">Margin</span>
                <span class="r">Offer ea.</span><span class="r">Line total</span>
            </div>
            ${rows}
        </div>`;
}

// Repaint the list in place after a price edit, so the line total and the margin
// beside it move with the number that was just typed.
// A price changed: save it, move the client's copy with it, and redraw the row
// so the line total and the margin beside it agree with the number just typed.
function b2bReviewOffer(id) {
    // The local model is already current (oninput), so redraw first and let the
    // save travel behind it -- the same order the spreadsheet uses.
    b2bItemSave(id);
    _b2bPaintQuoteDoc();
    _b2bRepaintReview(id);
}

function _b2bRepaintReview(focusId) {
    const el = document.getElementById('b2bReviewLines');
    if (!el) return;
    el.innerHTML = _b2bReviewLines();
    _b2bPaintTotals();
    // Found by id, never by position: a recycle or no-residual line renders a
    // dash instead of a field, so the inputs and the items are different-length
    // lists and any index into one is the wrong line in the other.
    if (focusId) el.querySelector(`[data-rvw="${focusId}"] input`)?.focus();
}

function _b2bStageReview(deal) {
    const canAccept = _b2bCanAccept();
    const sent = deal.quote_send_count
        ? `Sent ${deal.quote_send_count}× · last ${_b2bDate(deal.quote_sent_at)}`
        : 'Not sent yet';
    _b2bShowDeal({
        stage: deal.stage,
        eyebrow: deal.ref,
        title: 'Approve & Send',
        sub: 'Everything the client will see. Adjust a price if you need to — anything else goes back to pricing.',
        full: true,
        body: `
            ${_b2bSummary(deal)}
            ${_b2bWhereLine(deal)}
            ${_b2bPrevalOriginNote(deal)}
            <div class="b2b-note warn b2b-approve">
                <span class="b2b-note-k">Waiting on you</span>
                ${canAccept
                    ? 'Nothing has gone to the client yet. Send it from your own mailbox, or send it back to pricing with a note.'
                    : 'A CEO, MOCD or District Manager sends it out.'}
            </div>
            ${_b2bProofPanel(deal)}
            ${_b2bTotalsBar(true)}
            <div class="b2b-rvw-wrap">
                <div class="b2b-rvw-lines">
                    <div class="b2b-rvw-cap">
                        <span>What you're approving</span>
                        <button class="b2b-mini" onclick="b2bReviewFull(true)">Open the full pricing sheet</button>
                    </div>
                    <div id="b2bReviewLines">${_b2bReviewLines()}</div>
                </div>
                <div class="b2b-rvw-doc">
                    <div class="b2b-rvw-cap"><span>What the client sees</span></div>
                    <div id="b2bQuoteDoc">${_b2bQuoteDoc(deal, _b2bModalItems)}</div>
                </div>
            </div>`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            ${_b2bMoveBtn(deal)}
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Close</button>
            ${canAccept ? `
                <button class="b2b-btn b2b-btn-danger" onclick="b2bSendBack('${deal.id}')">Send Back For Changes</button>
                <input id="b2bQuoteTo" class="form-input-lg b2b-sendbar-i" placeholder="client@company.com"
                    value="${escapeHtml(deal.client?.contact_email || '')}">
                <button class="b2b-btn b2b-btn-secondary" onclick="b2bCopyQuote()">Copy</button>
                <button class="b2b-btn b2b-btn-primary" onclick="b2bSendQuote('${deal.id}',this)">Open In Email</button>`
                : `<span class="b2b-msg" style="color:var(--cb-muted);font-weight:600;">${escapeHtml(sent)}</span>`}`,
        after: _b2bPaintTotals,
    });
}

function _b2bStageQuote(deal) {
    // A quote still awaiting approval gets the calm review screen instead of the
    // full spreadsheet -- see _b2bStageReview. Opening the sheet explicitly is
    // the way past it, and re-entering resets that so the next deal starts calm.
    if (_b2bAwaitingApproval(deal) && !_b2bReviewFull) return _b2bStageReview(deal);
    // Same dense spreadsheet as pricing for editing the lines; the client-facing
    // quote preview below it is what they review before emailing.
    _b2bGridMode = 'sheet';
    const canAccept = _b2bCanAccept();
    const unsent = _b2bAwaitingApproval(deal);
    const sent = deal.quote_send_count
        ? `Sent ${deal.quote_send_count}× · last ${_b2bDate(deal.quote_sent_at)}`
        : 'Not sent yet';

    const banner = unsent ? `
        <div class="b2b-note warn b2b-approve">
            <span class="b2b-note-k">Awaiting approval</span>
            This quote hasn't gone to the client yet.
            ${canAccept ? 'Send it from your own mailbox, or send it back to pricing if something needs changing.'
                        : 'A CEO, MOCD or District Manager sends it out.'}
        </div>` : '';

    _b2bShowDeal({
        delDeal: deal,
        // The deal's own stage, so the header icon matches and the print
        // whitelist sees review as well as quote.
        stage: deal.stage,
        eyebrow: deal.ref,
        title: unsent ? 'Quote — Awaiting Approval' : 'Quote',
        sub: unsent
            ? 'Check it over, then send it to the client or send it back for changes.'
            : 'Edit freely while the client decides. Accepting locks the offers in as our cost.',
        full: true,
        body: `
            ${_b2bSummary(deal)}
            ${_b2bWhereLine(deal)}
            ${banner}
            <div class="b2b-sendbar${unsent ? ' urgent' : ''}">
                <span class="b2b-sendbar-s">${escapeHtml(sent)}</span>
                <input id="b2bQuoteTo" class="form-input-lg b2b-sendbar-i" placeholder="client@company.com"
                    value="${escapeHtml(deal.client?.contact_email || '')}">
                <button class="b2b-btn b2b-btn-secondary" onclick="b2bCopyQuote()">Copy</button>
                <button class="b2b-btn b2b-btn-primary" onclick="b2bSendQuote('${deal.id}',this)">Open In Email</button>
                <span class="b2b-sendbar-hint">Opens a draft in your mail app with the quote on your clipboard — paste it in and send.</span>
            </div>
            ${_b2bProofPanel(deal)}
            ${_b2bTotalsBar(true)}
            <div id="b2bItemGrid" class="b2b-items b2b-ss">${_b2bItemSheet()}</div>
            ${_b2bDispLegend()}
            <button class="b2b-btn b2b-btn-secondary b2b-add" onclick="b2bAddItem('${deal.id}',this)">＋ Add Line Item</button>
            ${_b2bDealStatsHtml(_b2bModalItems, deal)}
            <details class="b2b-preview" open>
                <summary>Quote preview — this is what the client sees</summary>
                <div id="b2bQuoteDoc">${_b2bQuoteDoc(deal, _b2bModalItems)}</div>
            </details>`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            ${_b2bMoveBtn(deal)}
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Close</button>
            ${_b2bIsCorp() ? `<button class="b2b-btn b2b-btn-danger" onclick="b2bDeclineDeal('${deal.id}')">Decline Deal</button>` : ''}
            ${canAccept ? `<button class="b2b-btn b2b-btn-secondary" onclick="b2bSendBack('${deal.id}')">Send Back For Changes</button>` : ''}
            ${canAccept
                ? `<button class="b2b-btn b2b-btn-primary" onclick="b2bAcceptQuote('${deal.id}',this)">Mark Accepted</button>`
                : '<span class="b2b-foot-note">Only a CEO, MOCD or District Manager can accept a quote.</span>'}`,
        after: () => {
            _b2bPaintTotals();
            _b2bPaintQuoteDoc();
            // The whole point of the approval step is that the quote goes out, so
            // an approver opening an unsent one gets the send step put in front
            // of them -- once, with a way straight back to reviewing it.
            if (unsent && canAccept && !_b2bSendPrompted.has(deal.id)) {
                _b2bSendPrompted.add(deal.id);
                setTimeout(() => b2bSendQuote(deal.id, null, true), 260);
            }
        },
    });
}

// Send a quote back to pricing with a note. Same authority as accepting: saying
// a quote isn't good enough is the same call as saying it is.
function b2bSendBack(id) {
    const deal = _b2bModalDeal;
    if (!deal || !_b2bCanAccept()) return;
    _b2bShowDeal({
        // The deal's own stage, so the header icon matches and the print
        // whitelist sees review as well as quote.
        stage: deal.stage,
        eyebrow: deal.ref,
        title: 'Send Back For Changes',
        sub: 'It returns to pricing with your note attached.',
        body: `
            <div class="b2b-note"><span class="b2b-note-k">What happens</span>
                ${escapeHtml(deal.client?.company || 'This deal')} goes back to
                ${escapeHtml(deal.pricing_store || 'the pricing store')} and drops off the approval queue.
                Whoever picks it up sees your note before anything else.</div>
            <label class="form-label-caps" style="margin-top:14px;">What needs changing? *</label>
            <textarea id="b2bSendbackNote" class="form-input-lg" rows="4"
                placeholder="The Latitudes look underpriced against recent comps — please recheck those two lines."></textarea>`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            <button class="kpi-cancel-btn" onclick="b2bOpenDeal('quote','${deal.id}')">Back</button>
            <button class="b2b-btn b2b-btn-danger" onclick="b2bConfirmSendBack('${deal.id}',this)">Send It Back</button>`,
        after: () => document.getElementById('b2bSendbackNote')?.focus(),
    });
}

async function b2bConfirmSendBack(id, btn) {
    const note = document.getElementById('b2bSendbackNote')?.value.trim();
    if (!note) return _b2bSay('Say what needs changing — that note is the whole point.', true);
    try {
        await _b2bBusy(btn, 'Sending back…', () =>
            _b2bSend({ action: 'request_changes', id, note, sent_back_by: _b2bUser() }));
        _b2bDirty = false;
        closeAllModals();
        await b2bRefresh();
    } catch (e) {
        _b2bSay(`Couldn't send it back: ${e.message}`, true);
    }
}

// Keep the preview in step with the grid without stealing focus from it.
//
// Now painted on the pricing screen as well as the quote, and on an evaluation
// as well as a deal -- MOCD asked to watch the client-facing side build itself
// in real time while filling the sheet in, rather than pricing blind and finding
// out what it looks like a stage later.
function _b2bPaintQuoteDoc() {
    const el = document.getElementById('b2bQuoteDoc');
    const src = _b2bQuoteSubject_src();
    if (el && src) el.innerHTML = _b2bQuoteDoc(src, _b2bModalItems);
}

// _b2bQuoteDoc was written against a deal. An evaluation is the same document
// with a different name on it and no pickup yet, so it is adapted here rather
// than teaching the document about a second shape -- one renderer means the
// client sees the same layout whether the figures came from an evaluation or a
// deal, which is the whole point of previewing it.
function _b2bQuoteSubject_src() {
    if (_b2bModalDeal) return _b2bModalDeal;
    const v = _b2bModalPreval;
    if (!v) return null;
    return {
        ...v,
        client: { company: v.company, acronym: v.acronym,
                  contact: v.contact, contact_email: v.contact_email },
        // An evaluation has collected nothing, so the document's "equipment
        // collected" line has no date to show and says so rather than inventing
        // one.
        pickup_date: null,
    };
}

// The client-facing side, foldable, wherever lines are being edited. <details>
// rather than a hand-rolled toggle so it is keyboard-operable for free; the open
// state is remembered across repaints because collapsing it every time a cell
// changed would make it useless.
let _b2bCustOpen = true;
function b2bToggleCust(el) { _b2bCustOpen = !!el.open; }
function _b2bCustPanel(subject) {
    // Nothing open, nothing to preview. Reachable only if a screen renders the
    // panel before claiming the editor, which is a bug -- but it should surface
    // as a missing panel, not as a thrown render that blanks the whole modal.
    if (!subject) return '';
    return `
        <details class="b2b-cust" ${_b2bCustOpen ? 'open' : ''} ontoggle="b2bToggleCust(this)">
            <summary>
                <span class="b2b-cust-t">What the client will see</span>
                <span class="b2b-cust-s">Updates as you price</span>
            </summary>
            <div class="b2b-cust-body"><div id="b2bQuoteDoc">${_b2bQuoteDoc(subject, _b2bModalItems)}</div></div>
        </details>`;
}

// Condition earns a tinted chip on the quote, using the same semantic tones as
// the rest of the app: emerald for sound, amber for Fair, red for Broken.
// The client can read the state of their equipment down the column at a glance.
// 'For Parts' is the retired spelling of Broken and keeps its tone, so a row
// written before the rename still reads red rather than falling to the grey
// default.
const B2B_COND_TONE = {
    'New':       { bg: '#e8f7ee', fg: '#178048' },
    'Like New':  { bg: '#e8f7ee', fg: '#178048' },
    'Good':      { bg: '#e8f7ee', fg: '#178048' },
    'Fair':      { bg: '#fdf3e1', fg: '#b7791f' },
    'Broken':    { bg: '#fcecec', fg: '#d1443b' },
    'For Parts': { bg: '#fcecec', fg: '#d1443b' },
};
const _b2bCondTone = c => B2B_COND_TONE[c] || { bg: '#f1f5f9', fg: '#647082' };
// _b2bCondClass speaks the quote document dialect (ok/warn/bad/neu) and the
// chips speak the app dialect (ok/warn/crit/neu). One word differs, so it is
// translated once here rather than a second condition map being written that
// would drift the first time a condition is added.
const _b2bCondChip = c => ({ bad: 'crit' }[_b2bCondClass(c)] || _b2bCondClass(c));

const _b2bCondClass = c => ({
    'New': 'ok', 'Like New': 'ok', 'Good': 'ok', 'Fair': 'warn',
    'Broken': 'bad', 'For Parts': 'bad',
}[c] || 'neu');

// --- shared quote maths and wording ----------------------------------------
// All three renderers (screen, email HTML, plain text) go through these, so the
// client cannot be shown three different numbers or three different stories
// about what happens to their kit.

function _b2bQuoteTotals(items) {
    let subtotal = 0, wipe = 0, wipeUnits = 0;
    items.forEach(it => {
        const q = Number(it.quantity) || 1;
        subtotal += (Number(it.offer) || 0) * q;
        if (it.wipe_required) { wipe += (Number(it.wipe_fee) || 0) * q; wipeUnits += q; }
    });
    // Never negative: a wipe is a deduction from what we pay, never a bill.
    return { subtotal, wipe, wipeUnits, net: Math.max(0, subtotal - wipe) };
}

// The specs go on the client's copy too. They are the justification for the
// number beside them, so hiding them would make the quote harder to argue with
// in the wrong direction.
function _b2bQuoteDesc(it) {
    return _b2bSpecsFor(it).map(f => String(it[f.key] ?? '').trim()).filter(Boolean).join(' · ');
}

// Only mention the outcomes actually present, so a straightforward purchase
// quote doesn't carry two paragraphs of explanation it doesn't need.
function _b2bQuoteFootNotes(items) {
    const notes = ['Reply to this email to accept the quote or ask about any line.'];
    if (items.some(it => _b2bDispOf(it) === 'no_residual')) {
        notes.push('Items marked no residual value carry no offer — we take them away at no cost to you '
            + 'and either refurbish them for resale or recycle them responsibly.');
    }
    if (items.some(_b2bIsScrap)) {
        notes.push('Recycle items carry no offer and are disposed of responsibly at no cost to you.');
    }
    if (items.some(it => it.wipe_required)) {
        notes.push('Certified data wipes are performed in-house to NIST 800-88 standards, with the charge '
            + 'deducted from your payment — never billed separately.');
    }
    return notes;
}

// The client-facing quote. Deliberately carries no SKUs and no deal reference
// -- those are ours, for labels and the floor. A client identifies their quote
// by the date we collected their equipment.
function _b2bQuoteDoc(deal, items) {
    const c = deal.client || {};
    const t = _b2bQuoteTotals(items);
    const today = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'America/Chicago' });
    const picked = _b2bLongDate(deal.pickup_date);

    const rows = items.length ? items.map(it => {
        const qty = Number(it.quantity) || 1;
        const buy = _b2bIsBuy(it);
        const disp = _b2bDispOf(it);
        const spec = _b2bQuoteDesc(it);
        return `<tr>
            <td>
                <b>${escapeHtml(_b2bItemName(it))}</b>
                ${it.condition ? `<span class="b2b-doc-cond ${_b2bCondClass(it.condition)}">${escapeHtml(it.condition)}</span>` : ''}
                ${!buy ? `<span class="b2b-doc-rec ${disp === 'recycle' ? '' : 'nrv'}">${escapeHtml(B2B_DISP[disp].label)}</span>` : ''}
                ${it.wipe_required ? '<span class="b2b-doc-rec wipe">Certified wipe</span>' : ''}
                ${spec ? `<div class="b2b-doc-sub">${escapeHtml(spec)}</div>` : ''}
                ${it.client_notes ? `<div class="b2b-doc-sub">${escapeHtml(it.client_notes)}</div>` : ''}
            </td>
            <td class="c">${qty}</td>
            <td class="r">${buy ? _b2bMoney(it.offer, 2) : '—'}</td>
            <td class="r b">${buy ? _b2bMoney((Number(it.offer) || 0) * qty, 2) : '—'}</td>
        </tr>`;
    }).join('') : '<tr><td colspan="4" class="b2b-doc-empty">No line items yet.</td></tr>';

    // Only shown when there is a deduction: an unnecessary "$0.00 of wipes" line
    // invites a question about a service they didn't ask for.
    const wipeRows = t.wipe ? `
        <div class="b2b-doc-sub2">
            <span>Subtotal</span><b>${_b2bMoney(t.subtotal, 2)}</b>
        </div>
        <div class="b2b-doc-sub2 minus">
            <span>Certified data wipe · ${t.wipeUnits} device${t.wipeUnits === 1 ? '' : 's'}</span>
            <b>−${_b2bMoney(t.wipe, 2)}</b>
        </div>` : '';

    return `
    <div class="b2b-doc">
        <div class="b2b-doc-head">
            <div class="b2b-doc-brand">Pay<span>More</span><div>Buy · Sell · Recycle Electronics</div></div>
            <div class="b2b-doc-meta">
                <span class="b2b-doc-kind">Quote</span>
                <div>Issued ${escapeHtml(today)}</div>
            </div>
        </div>
        <div class="b2b-doc-parties">
            <div><span class="b2b-doc-k">Prepared for</span><b>${escapeHtml(c.company || '')}</b>${c.contact ? `<div>${escapeHtml(c.contact)}</div>` : ''}</div>
            <div class="r"><span class="b2b-doc-k">Equipment collected</span><b>${escapeHtml(picked || 'Not recorded')}</b><div>By SPEEKS Technology, authorized PayMore franchisee</div></div>
        </div>
        <table class="b2b-doc-t">
            <thead><tr><th>Description</th><th class="c">Qty</th><th class="r">Unit offer</th><th class="r">Line total</th></tr></thead>
            <tbody>${rows}</tbody>
        </table>
        ${wipeRows}
        <div class="b2b-doc-total">
            <span>${t.wipe ? 'Total payable to you' : 'Total offer'}</span>
            <b>${_b2bMoney(t.net, 2)}</b>
        </div>
        <div class="b2b-doc-foot">
            ${_b2bQuoteFootNotes(items).map(escapeHtml).join(' ')}
        </div>
    </div>`;
}

// The version the client actually receives: a faithful, email-safe copy of the
// on-screen quote. Tables and inline styles only -- Gmail strips <style>
// blocks and Outlook ignores flexbox, so everything is spelled out per cell.
// No SKUs, no deal reference; the pickup date is the client's handle on it.
function _b2bQuoteInlineHtml(deal, items) {
    const c = deal.client || {};
    const t = _b2bQuoteTotals(items);
    const today = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'America/Chicago' });
    const picked = _b2bLongDate(deal.pickup_date);
    const TH = 'padding:10px 12px;background:#e8f7ee;border-bottom:2px solid #1f9d57;'
             + 'font-size:10px;font-weight:bold;letter-spacing:.07em;white-space:nowrap;'
             + 'text-transform:uppercase;color:#178048;';
  // the band is inset inside a rounded card, so its own outer corners have to
  // be rounded too or they sit square against the curve
  const THL = TH + 'border-top-left-radius:10px;';
  const THR = TH + 'border-top-right-radius:10px;';
    const TD = 'padding:11px 12px;border-bottom:1px solid #eef2f6;font-size:13px;color:#1a1c1e;';

    const CHIP = 'display:inline-block;margin-left:7px;padding:2px 8px;border-radius:10px;'
               + 'font-size:9.5px;font-weight:bold;letter-spacing:.05em;text-transform:uppercase;';
    const rows = items.map((it, i) => {
        const qty = Number(it.quantity) || 1;
        const tone = _b2bCondTone(it.condition);
        const buy = _b2bIsBuy(it);
        const disp = _b2bDispOf(it);
        const spec = _b2bQuoteDesc(it);
        // Scrap reads teal, no-residual reads blue: two different outcomes, and
        // the client should be able to tell them apart at a glance.
        const dispChip = disp === 'recycle' ? 'background:#e3f6f3;color:#0d8a7d;'
                                            : 'background:#eaf1fb;color:#3a6ea8;';
        // Zebra has to be per-row inline; Gmail drops <style> blocks entirely.
        const zebra = i % 2 ? 'background:#fbfdfc;' : '';
        return `<tr style="${zebra}">
            <td style="${TD}">
                <b>${escapeHtml(_b2bItemName(it))}</b>
                ${it.condition ? `<span style="${CHIP}background:${tone.bg};color:${tone.fg};">${escapeHtml(it.condition)}</span>` : ''}
                ${!buy ? `<span style="${CHIP}${dispChip}">${escapeHtml(B2B_DISP[disp].label)}</span>` : ''}
                ${it.wipe_required ? `<span style="${CHIP}background:#f1ebfd;color:#6b46c1;">Certified wipe</span>` : ''}
                ${spec ? `<div style="margin-top:4px;font-size:11.5px;color:#647082;">${escapeHtml(spec)}</div>` : ''}
                ${it.client_notes ? `<div style="margin-top:4px;font-size:11.5px;color:#647082;">${escapeHtml(it.client_notes)}</div>` : ''}
            </td>
            <td style="${TD}text-align:center;">${qty}</td>
            <td style="${TD}text-align:right;">${buy ? _b2bMoney(it.offer, 2) : '&mdash;'}</td>
            <td style="${TD}text-align:right;font-weight:bold;color:#178048;">${buy ? _b2bMoney((Number(it.offer) || 0) * qty, 2) : '&mdash;'}</td>
        </tr>`;
    }).join('');

    const SUB = 'padding:7px 12px;font-size:12.5px;color:#647082;';
    const wipeRows = t.wipe ? `
      <tr><td style="${SUB}">Subtotal</td><td style="${SUB}text-align:right;font-weight:bold;color:#1a1c1e;">${_b2bMoney(t.subtotal, 2)}</td></tr>
      <tr><td style="${SUB}">Certified data wipe &middot; ${t.wipeUnits} device${t.wipeUnits === 1 ? '' : 's'}</td>
          <td style="${SUB}text-align:right;font-weight:bold;color:#6b46c1;">&minus;${_b2bMoney(t.wipe, 2)}</td></tr>` : '';

    return `<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:100%;font-family:'Segoe UI',Helvetica,Arial,sans-serif;background:#ffffff;border:1px solid #e6ebf1;border-top:3px solid #1f9d57;border-radius:14px;">
  <tr><td style="padding:22px 24px;border-bottom:1px solid #eef2f6;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
      <td style="font-size:21px;font-weight:bold;color:#1a1c1e;letter-spacing:-.4px;">Pay<span style="color:#1f9d57;">More</span>
        <div style="margin-top:3px;font-size:11px;font-weight:normal;color:#647082;">Buy &middot; Sell &middot; Recycle Electronics</div></td>
      <td align="right" style="font-size:12px;color:#647082;">
        <div style="display:inline-block;padding:4px 12px;border-radius:999px;background:#e8f7ee;color:#178048;font-size:12px;font-weight:bold;letter-spacing:.06em;text-transform:uppercase;">Quote</div>
        <div style="margin-top:6px;">Issued ${escapeHtml(today)}</div></td>
    </tr></table></td></tr>
  <tr><td style="padding:16px 24px;background:#f4faf6;border-top:1px solid #dcefe4;border-bottom:1px solid #dcefe4;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
      <td style="font-size:12.5px;color:#1a1c1e;vertical-align:top;">
        <div style="font-size:10px;font-weight:bold;letter-spacing:.09em;text-transform:uppercase;color:#178048;">Prepared for</div>
        <div style="margin-top:4px;font-size:14px;font-weight:bold;">${escapeHtml(c.company || '')}</div>
        ${c.contact ? `<div style="margin-top:2px;color:#647082;">${escapeHtml(c.contact)}</div>` : ''}</td>
      <td align="right" style="font-size:12.5px;color:#1a1c1e;vertical-align:top;">
        <div style="font-size:10px;font-weight:bold;letter-spacing:.09em;text-transform:uppercase;color:#178048;">Equipment collected</div>
        <div style="margin-top:4px;font-size:14px;font-weight:bold;">${escapeHtml(picked || 'Not recorded')}</div>
        <div style="margin-top:2px;color:#647082;">By SPEEKS Technology, authorized PayMore franchisee</div></td>
    </tr></table></td></tr>
  <tr><td style="padding:14px 24px 0;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
      <tr><th align="left" style="${THL}">Description</th>
          <th align="center" style="${TH}">Qty</th>
          <th align="right" style="${TH}">Unit offer</th>
          <th align="right" style="${THR}">Line total</th></tr>
      ${rows}
      ${wipeRows}
    </table></td></tr>
  <tr><td style="padding:14px 24px 0;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#e8f7ee;border-radius:12px;"><tr>
      <td style="padding:14px 18px;font-size:11px;font-weight:bold;letter-spacing:.09em;text-transform:uppercase;color:#178048;">${t.wipe ? 'Total payable to you' : 'Total offer'}</td>
      <td align="right" style="padding:14px 18px;font-size:22px;font-weight:bold;color:#178048;">${_b2bMoney(t.net, 2)}</td>
    </tr></table></td></tr>
  <tr><td style="padding:16px 24px;background:#f6f8fa;border-top:1px solid #eef2f6;font-size:11.5px;color:#647082;line-height:1.6;border-bottom-left-radius:13px;border-bottom-right-radius:13px;">
    <b style="color:#178048;">Reply to this email to accept the quote</b> or ask about any line.
    ${_b2bQuoteFootNotes(items).slice(1).map(escapeHtml).join(' ')}
  </td></tr>
</table>`;
}

// Plain-text fallback, for a client whose mail reads text-only. Same content,
// same omissions: no SKUs, no deal reference.
function _b2bQuoteText(deal, items) {
    const lines = items.map(it => {
        const qty = Number(it.quantity) || 1;
        const amt = _b2bIsBuy(it)
            ? _b2bMoney((Number(it.offer) || 0) * qty, 2)
            : `${B2B_DISP[_b2bDispOf(it)].label.toLowerCase()}, no offer`;
        const bits = [_b2bQuoteDesc(it), it.condition, it.client_notes,
                      it.wipe_required ? 'certified data wipe' : ''].filter(Boolean).join(' · ');
        return `  - ${_b2bItemName(it)} x${qty} — ${amt}${bits ? `\n      (${bits})` : ''}`;
    });
    const t = _b2bQuoteTotals(items);
    const picked = _b2bLongDate(deal.pickup_date);
    // null drops a line that doesn't apply; '' is a deliberate blank.
    return [
        'PayMore — Buy · Sell · Recycle Electronics',
        '',
        `Prepared for: ${deal.client?.company || ''}`,
        picked ? `Equipment collected: ${picked}` : null,
        '',
        ...lines,
        '',
        t.wipe ? `Subtotal: ${_b2bMoney(t.subtotal, 2)}` : null,
        t.wipe ? `Certified data wipe (${t.wipeUnits} device${t.wipeUnits === 1 ? '' : 's'}): -${_b2bMoney(t.wipe, 2)}` : null,
        `${t.wipe ? 'Total payable to you' : 'Total offer'}: ${_b2bMoney(t.net, 2)}`,
        '',
        ..._b2bQuoteFootNotes(items),
        '',
        'Issued by SPEEKS Technology — authorized PayMore franchisee.',
    ].filter(l => l !== null).join('\n');
}

async function b2bCopyQuote() {
    const deal = _b2bModalDeal;
    if (!deal) return;
    const html = _b2bQuoteInlineHtml(deal, _b2bModalItems);
    const text = _b2bQuoteText(deal, _b2bModalItems);
    try {
        await navigator.clipboard.write([new ClipboardItem({
            'text/html':  new Blob([html], { type: 'text/html' }),
            'text/plain': new Blob([text], { type: 'text/plain' }),
        })]);
        alert('Quote copied — paste it into Gmail or Outlook.');
    } catch (_) {
        try {
            await navigator.clipboard.writeText(text);
            alert('Quote copied as plain text.');
        } catch (e) {
            alert(`Couldn't copy the quote: ${e.message}`);
        }
    }
}

// Smart punctuation survives a clipboard paste but mangles in a mailto body,
// so the plain-text rendition gets flattened to ASCII on the way out.
function _b2bAscii(s) {
    return String(s || '')
        .replace(/[—–]/g, '-').replace(/[‘’]/g, "'")
        .replace(/[“”]/g, '"').replace(/·/g, '-').replace(/…/g, '...')
        .replace(/[^\x00-\x7F]/g, '');
}

// Opens the quote in the user's own mail client rather than sending it from
// the reports mailbox, so the client's reply lands with whoever quoted them --
// same reason the Recycle report went back to mailto.
//
// A mailto body is plain text by definition (RFC 6068), so the styled quote
// cannot ride in the URL. Instead it goes on the clipboard as rich HTML and
// the draft opens empty: one paste and the client gets the same document they
// would see here. The plain-text rendition is attached as the clipboard's
// alternate flavour, so a paste into a plain-text composer still reads well,
// and it is what fills the body if the clipboard is unavailable.
function _b2bQuoteSubject(deal) {
    const picked = _b2bLongDate(deal.pickup_date);
    return picked ? `Your PayMore Quote — Equipment Collected ${picked}` : 'Your PayMore Quote';
}

// Step one: put the quote on the clipboard and explain the paste, so nobody
// lands in an empty draft wondering where the quote went.
// `auto` marks the copy that opens by itself when an approver lands on an unsent
// quote. It stays quiet about a missing address and offers a way back to the
// quote, because the user didn't ask for it.
async function b2bSendQuote(id, btn, auto) {
    const to = document.getElementById('b2bQuoteTo')?.value.trim();
    if (!to) {
        if (auto) return;
        return _b2bSay('Enter an email address to open the quote against.', true);
    }
    const deal = _b2bModalDeal;
    if (!deal) return;

    await _b2bBusy(btn, 'Preparing…', async () => {
        const html = _b2bQuoteInlineHtml(deal, _b2bModalItems);
        const text = _b2bQuoteText(deal, _b2bModalItems);
        let copied = false;
        try {
            await navigator.clipboard.write([new ClipboardItem({
                'text/html':  new Blob([html], { type: 'text/html' }),
                'text/plain': new Blob([text], { type: 'text/plain' }),
            })]);
            copied = true;
        } catch (_) {
            try { await navigator.clipboard.writeText(text); copied = true; } catch (_) { /* no clipboard */ }
        }
        _b2bShowSendStep(deal, to, copied, auto);
    });
}

const _b2bIsMac = () => /Mac|iP(hone|ad|od)/.test(navigator.platform || navigator.userAgent || '');

function _b2bShowSendStep(deal, to, copied, auto) {
    const paste = _b2bIsMac() ? 'Cmd + V' : 'Ctrl + V';
    const steps = copied ? [
        `Your email app opens a new draft to <b>${escapeHtml(to)}</b> with the subject already filled in.`,
        `Click into the message body and press <kbd>${paste}</kbd> — the full quote is already on your clipboard.`,
        'Check it over, add anything you want to say, and send.',
    ] : [
        `Your email app opens a new draft to <b>${escapeHtml(to)}</b>.`,
        'The quote is in the body as plain text — your browser blocked the clipboard, so the formatted version could not be copied.',
        'Check it over and send.',
    ];

    _b2bShowDeal({
        // The deal's own stage, so the header icon matches and the print
        // whitelist sees review as well as quote.
        stage: deal.stage,
        eyebrow: deal.ref,
        title: auto ? 'This Quote Is Ready To Send' : 'Send This Quote',
        sub: auto ? 'It has been priced and approved for sending. Review it first if you would rather.'
             : copied ? 'The quote is copied and ready to paste.' : 'The quote will be in the draft as plain text.',
        body: `
            <div class="b2b-sendstep">
                <div class="b2b-sendstep-ico">${_b2bIco('<path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/>')}</div>
                <div class="b2b-sendstep-t">What happens next</div>
                <ol class="b2b-sendsteps">${steps.map(s => `<li>${s}</li>`).join('')}</ol>
                ${copied ? '<div class="b2b-sendstep-note">Nothing has been emailed yet — you send it yourself from your own mailbox, so the client\'s reply comes back to you.</div>' : ''}
            </div>`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            <button class="kpi-cancel-btn" onclick="b2bBackToQuote('${deal.id}')">${auto ? 'Review The Quote First' : 'Back'}</button>
            <button class="b2b-btn b2b-btn-primary" onclick="b2bOpenDraft('${deal.id}','${escapeHtml(to).replace(/'/g, "\\'")}',${copied})">Open Email Draft</button>`,
    });
}

function b2bBackToQuote(id) {
    const deal = _b2bDealById(id) || _b2bModalDeal;
    if (deal) { _b2bModalDeal = deal; _b2bStageQuote(deal); }
}

// Step two. The mailto fires first and synchronously, straight off this click:
// an external protocol handler needs user activation, and awaiting anything
// first would spend it.
async function b2bOpenDraft(id, to, copied) {
    const deal = _b2bDealById(id) || _b2bModalDeal;
    if (!deal) return;

    let href = `mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(_b2bAscii(_b2bQuoteSubject(deal)))}`;
    if (!copied) {
        const ascii = _b2bAscii(_b2bQuoteText(deal, _b2bModalItems));
        const withBody = `${href}&body=${encodeURIComponent(ascii)}`;
        href = withBody.length > 1900
            ? `${href}&body=${encodeURIComponent(ascii.slice(0, 1200) + '\n\n[quote truncated - use Copy instead]')}`
            : withBody;
    }
    window.location.href = href;

    await _b2bPost({ action: 'send_quote', id, to }, "Couldn't record the send");
    await b2bRefresh();
    const next = _b2bDealById(id);
    if (next) { _b2bModalDeal = next; _b2bStageQuote(next); }
    _b2bSay(`Draft opened for ${to}.`);
}

async function b2bAcceptQuote(id, btn) {
    if (!_b2bApprovalGate(_b2bDealById(id) || _b2bModalDeal)) return;
    // The same readiness gate as submitting, because the server runs the same
    // one here -- checking only the reasons would let a line with two of five
    // serials get all the way to a 400 from the accept call.
    const gaps = _b2bNotReady();
    if (gaps.length) {
        gaps.forEach(it => _b2bNotesOpen.add(it.id));
        _b2bRepaintItems();
        return _b2bSay(gaps.map(it => `${_b2bItemName(it)} (${_b2bItemBlocked(it).join(', ')})`).join(' · '), true);
    }
    const t = _b2bItemTotals();
    const unsent = _b2bModalDeal && _b2bAwaitingApproval(_b2bModalDeal);
    const msg = `Accept this quote at ${_b2bMoney(t.net, 2)}?\n\n`
        // Not blocked: a client can accept over the phone. But accepting a quote
        // that was never sent leaves no record of what they agreed to, so it
        // should be a deliberate choice rather than a slip.
        + (unsent ? 'This quote has never been emailed, so there is no record of what the client saw. '
                  + 'Send it first unless they have already agreed to these numbers.\n\n' : '')
        + 'The offers lock in as our cost, the SKUs freeze, and the items become inventory to list. '
        + 'This cannot be undone.';
    if (!confirm(msg)) return;
    const out = await _b2bBusy(btn, 'Accepting…', () =>
        _b2bPost({ action: 'accept_quote', id, accepted_by: _b2bUser() }, "Couldn't accept the quote"));
    _b2bDirty = false;
    closeAllModals();
    await b2bRefresh();
    const next = _b2bDealById(id);
    if (!next) return;
    // CORP-priced deals still need a listing store before anyone can tick items.
    if (out.next_stage === 'listing_location' && _b2bIsCorp()) b2bOpenDeal('listloc', id);
    else if (_b2bActionFor(next))                              b2bOpenDeal(_b2bClickKind(next), id);
}

// --- stage 5: listing location (CORP-priced deals only) --------------------

function _b2bStageListingLocation(deal) {
    _b2bAssignPick = null;
    _b2bShowDeal({
        delDeal: deal,
        stage: 'listing_location',
        eyebrow: deal.ref,
        title: 'Assign Listing Store',
        sub: 'CORP priced this one, so pick the store that will list the items.',
        body: `
            ${_b2bSummary(deal)}
            <div class="b2b-note ok"><span class="b2b-note-k">Accepted</span>
                ${escapeHtml(deal.client?.company || '')} accepted ${_b2bMoney(_b2bNetOffer(deal), 2)} across ${deal.total_units} unit${deal.total_units === 1 ? '' : 's'}.</div>
            <label class="form-label-caps" style="margin-top:14px;">List At</label>
            <div class="b2b-loc-pick">
                ${STORE_CODES.map(c => `
                    <button class="b2b-loc" data-loc="${c}" onclick="b2bPickLocation('${c}')">
                        <span class="b2b-loc-dot" style="background:${STORE_TINTS[c] || '#94a3b8'}"></span>
                        <span class="b2b-loc-c">${c}</span>
                    </button>`).join('')}
            </div>`,
        footer: `
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Cancel</button>
            <button class="b2b-btn b2b-btn-primary" id="b2bAsGo" disabled onclick="b2bAssignListing('${deal.id}',this)">Send To Listing</button>`,
    });
}

async function b2bAssignListing(id) {
    if (!_b2bAssignPick) return;
    await _b2bPost({ action: 'assign_listing', id, listing_store: _b2bAssignPick }, "Couldn't assign the listing store");
    closeAllModals();
    await b2bRefresh();
}

// --- stage 6: listing ------------------------------------------------------

function _b2bDone(it)      { return (Number(it.listed_qty) || 0) + (Number(it.recycled_qty) || 0); }
function _b2bSatisfied(it) { return _b2bDone(it) >= (Number(it.quantity) || 1); }
function _b2bAllSatisfied(){ return _b2bModalItems.length > 0 && _b2bModalItems.every(_b2bSatisfied); }

// Listing a unit is a two-scan handshake: our label identifies WHICH unit, then
// the Shopify barcode records what it became. The id of the line waiting on its
// second scan lives here.
let _b2bPendingUnit = null;

const B2B_SCAN_SVG = '<path d="M3 7V5a2 2 0 0 1 2-2h2"/><path d="M17 3h2a2 2 0 0 1 2 2v2"/>'
    + '<path d="M21 17v2a2 2 0 0 1-2 2h-2"/><path d="M7 21H5a2 2 0 0 1-2-2v-2"/>'
    + '<line x1="7" y1="12" x2="7" y2="12"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="17" y1="8" x2="17" y2="16"/>';

// Ethan: "on the listing side, we should throw a disclaimer that we should
// review pricing because we play conservative."
//
// On the listing screen rather than at pricing, because it is advice for the
// person about to put a price on Shopify, and it is only true at that moment:
// what a line was valued at during pricing was a buying decision made to protect
// the deal, not a resale price anyone committed to.
function _b2bConservativeNote() {
    return `
        <div class="b2b-note warn">
            <span class="b2b-note-k">Check the price before you list</span>
            The values on this deal were set to price the BUY, and we deliberately
            price a buy conservatively. They are a floor, not a resale price —
            look each line up before it goes live.
        </div>`;
}

function _b2bStageListing(deal) {
    _b2bPendingUnit = null;
    _b2bShowDeal({
        delDeal: deal,
        stage: 'listing',
        eyebrow: deal.ref,
        title: 'Listing',
        sub: 'Scan our label, then the Shopify barcode it went live under.',
        full: true,
        body: `
            ${_b2bSummary(deal)}
            ${_b2bConservativeNote()}
            ${_b2bModalItems.length ? _b2bDealStatsHtml(_b2bModalItems, deal) : ''}
            <div id="b2bScanWrap">${_b2bScanBar(deal)}</div>
            <div id="b2bListProg">${_b2bListProgress()}</div>
            <div id="b2bListRows" class="b2b-items b2b-ss b2b-lgrid">${_b2bListRows()}</div>`,
        footer: `
            ${_b2bMoveBtn(deal)}
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Close</button>
            <button class="b2b-btn b2b-btn-primary" id="b2bListDone" ${_b2bAllSatisfied() ? '' : 'disabled'}
                onclick="b2bCompleteDeal('${deal.id}',this)">Complete Deal</button>`,
        after: () => document.getElementById('b2bScanIn')?.focus(),
    });
}

// Two modes in one bar rather than a modal over the checklist: a hardware
// scanner is a keyboard, so the operator's hands never leave it and the second
// scan lands in the same always-focused field the first one did.
function _b2bScanBar(deal) {
    const it = _b2bPendingUnit ? _b2bLocalItem(_b2bPendingUnit) : null;
    if (it) {
        const unit = _b2bDone(it) + 1;
        return `
        <div class="b2b-scanbar pending">
            <span class="b2b-scan-ico">${_b2bIco(B2B_SCAN_SVG)}</span>
            <div class="b2b-scan-ask">
                <span class="b2b-scan-ask-t">Now scan the Shopify barcode</span>
                <span class="b2b-scan-ask-s">${escapeHtml(_b2bItemName(it))} · unit ${unit} of ${Number(it.quantity) || 1}</span>
            </div>
            <input id="b2bScanIn" class="form-input-lg b2b-scan-num" autocomplete="off" inputmode="numeric" maxlength="8"
                placeholder="8-digit barcode"
                oninput="_b2bScanTyped(this,'${deal.id}')"
                onkeydown="if(event.key==='Enter'){event.preventDefault();b2bScan('${deal.id}');}
                           if(event.key==='Escape'){b2bCancelPending();}">
            <button class="b2b-btn b2b-btn-secondary" onclick="b2bCancelPending()">Cancel</button>
            <span class="b2b-scan-msg" id="b2bScanMsg"></span>
        </div>`;
    }
    return `
        <div class="b2b-scanbar">
            <span class="b2b-scan-ico">${_b2bIco(B2B_SCAN_SVG)}</span>
            <input id="b2bScanIn" class="form-input-lg" autocomplete="off" placeholder="Scan one of our labels, or type a SKU and press Enter"
                onkeydown="if(event.key==='Enter'){event.preventDefault();b2bScan('${deal.id}');}">
            <span class="b2b-scan-msg" id="b2bScanMsg"></span>
        </div>`;
}

// Repaints the bar and puts the caret back. Kept out of _b2bRepaintListing so a
// half-typed barcode survives the row repaint that follows every tick.
function _b2bRepaintScanBar() {
    const wrap = document.getElementById('b2bScanWrap');
    if (!wrap || !_b2bModalDeal) return;
    wrap.innerHTML = _b2bScanBar(_b2bModalDeal);
    document.getElementById('b2bScanIn')?.focus();
}

// Scanners vary on whether they send a terminating Enter. A Shopify barcode is
// exactly 8 digits, so the field can submit itself the moment it has 8 -- which
// also means the operator never has to reach for the keyboard.
function _b2bScanTyped(el, dealId) {
    el.value = el.value.replace(/\D/g, '').slice(0, 8);
    if (el.value.length === 8) b2bScan(dealId);
}

function b2bCancelPending() {
    _b2bPendingUnit = null;
    _b2bRepaintScanBar();
}

function _b2bListProgress() {
    const total = _b2bModalItems.reduce((n, it) => n + (Number(it.quantity) || 1), 0);
    const done  = _b2bModalItems.reduce((n, it) => n + _b2bDone(it), 0);
    const pct   = total ? Math.round((done / total) * 100) : 0;
    return `
        <div class="b2b-prog">
            <div class="b2b-prog-h"><span>Listing progress</span><span><b>${done}</b> of ${total} units · ${pct}%</span></div>
            <div class="b2b-pace-bar"><i style="width:${pct}%"></i></div>
        </div>`;
}

// The listing sheet is the pricing grid's read-only twin: one dense row per
// line showing everything the lister needs to build the Shopify listing --
// specs, serials, condition, value and cost -- with the list / recycle / label
// actions where the fields would be. Wipe certification and the recorded
// barcodes drop to a strip under the row.
function _b2bListRows() {
    if (!_b2bModalItems.length) {
        return `<div class="b2b-empty sm"><div class="b2b-empty-t">Nothing to list</div></div>`;
    }
    // The three required specs get their own columns (as on the pricing sheet);
    // the optional ones (GPU, battery) ride under the item name.
    const reqSpecs = B2B_SPEC_FIELDS.filter(f => f.req);
    const head = `
        <div class="b2b-prow b2b-phead">
            <span>Line</span><span>Item</span>
            ${reqSpecs.map(f => `<span>${escapeHtml(f.label)}</span>`).join('')}
            <span>Serials</span>
            <span class="r">Value</span><span class="r">Cost</span>
            <span class="c">Listed</span><span></span>
        </div>`;

    const rows = _b2bModalItems.map(it => {
        const qty = Number(it.quantity) || 1;
        const listed = Number(it.listed_qty) || 0;
        const recycled = Number(it.recycled_qty) || 0;
        const ok = _b2bSatisfied(it);
        const waiting = _b2bPendingUnit === it.id;
        const scrap = _b2bIsScrap(it);
        const disp  = _b2bDispOf(it);
        const wiped = Number(it.wiped_qty) || 0;
        const carries = _b2bSpecsFor(it);
        const serials = _b2bSerials(it);
        const extra = _b2bSpecsFor(it).filter(f => !f.req).map(f => it[f.key]).filter(Boolean);
        const lineValue = scrap ? 0 : (Number(it.value) || 0) * qty;
        const lineCost  = _b2bIsBuy(it) ? (Number(it.cost != null ? it.cost : it.offer) || 0) * qty : 0;

        // You may list exactly as many units as have been certified wiped. The
        // server enforces the same rule; this is so the button says why.
        const needsWipe = !!it.wipe_required && listed >= wiped;
        const blockTitle = scrap ? 'Recycle lines are never listed'
            : needsWipe ? `Certify a data wipe first — ${wiped} of ${qty} wiped`
            : 'List one unit — asks for its Shopify barcode';

        // Corp-only wipe certification; the store still sees the flag/count so a
        // disabled "+" is never inexplicable.
        const wipeStrip = it.wipe_required ? `
            <div class="b2b-lwipe ${wiped >= qty ? 'done' : ''}">
                ${_b2bIco('<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><polyline points="9 12 11 14 15 10"/>')}
                <span><b>${wiped}</b> of ${qty} certified wiped</span>
                ${wiped >= qty ? ''
                  : _b2bIsCorp() ? `<button class="b2b-mini" onclick="b2bMarkWiped('${it.id}')">Mark Wiped</button>`
                  : '<span class="b2b-lwipe-note">Corp records the certification</span>'}
            </div>` : '';

        // The barcodes are the evidence the units went live -- each individually
        // removable, because a wrong one recorded is worse than one missing.
        const codes = (it.listings || []).length ? `
            <div class="b2b-lcodes">
                ${it.listings.map(l => `
                <span class="b2b-lcode" title="Listed by ${escapeHtml(l.listed_by || 'unknown')}">
                    <span class="b2b-mono">${escapeHtml(l.shopify_barcode)}</span>
                    <button class="b2b-lcode-x" title="Remove this barcode"
                        onclick="b2bUnlistUnit('${it.id}','${l.id}')">×</button>
                </span>`).join('')}
            </div>` : '';

        return `
        <div class="b2b-pline b2b-lline ${ok ? 'b2b-lok' : ''} ${scrap ? 'b2b-scrap' : ''} ${waiting ? 'b2b-lwait' : ''}" id="b2bLrow-${it.id}">
            <div class="b2b-prow">
                <span class="b2b-pcell b2b-pc-sku" title="${escapeHtml(it.sku || '')}">
                    ${ok ? `<span class="b2b-lcheck">${_b2bIco('<polyline points="20 6 9 17 4 12"/>')}</span>` : ''}
                    <span class="b2b-mono">${escapeHtml(_b2bLineNo(it))}</span>
                </span>
                <span class="b2b-pcell b2b-lc-item">
                    <span class="b2b-lc-name"><b>${escapeHtml(_b2bItemName(it))}</b>
                        ${it.condition ? `<span class="b2b-lcond">${escapeHtml(it.condition)}</span>` : ''}
                        ${!_b2bIsBuy(it) ? `<span class="b2b-doc-rec ${scrap ? '' : 'nrv'}">${escapeHtml(B2B_DISP[disp].label)}</span>` : ''}</span>
                    ${extra.length ? `<span class="b2b-lc-sub">${escapeHtml(extra.join(' · '))}</span>` : ''}
                </span>
                ${reqSpecs.map(f => `<span class="b2b-pcell b2b-lc-spec">${carries.some(s => s.key === f.key) && String(it[f.key] || '').trim() ? escapeHtml(it[f.key]) : '<span class="b2b-f-off">—</span>'}</span>`).join('')}
                <span class="b2b-pcell b2b-lc-serials">${serials.length ? escapeHtml(serials.join(', ')) : '<span class="b2b-f-off">—</span>'}</span>
                <span class="b2b-pcell n">${scrap ? '<span class="b2b-f-off">—</span>' : _b2bMoney(lineValue)}</span>
                <span class="b2b-pcell n">${_b2bIsBuy(it) ? _b2bMoney(lineCost) : '<span class="b2b-f-off">—</span>'}</span>
                <span class="b2b-pcell b2b-lc-prog">
                    <button class="b2b-step" ${listed <= 0 ? 'disabled' : ''} title="Undo the last one" onclick="b2bUnlistUnit('${it.id}')">−</button>
                    <span class="b2b-lc-count"><b>${listed}</b>/${qty}${recycled ? `<i>+${recycled} rec</i>` : ''}</span>
                    <button class="b2b-step up" ${ok || scrap || needsWipe ? 'disabled' : ''} title="${escapeHtml(blockTitle)}" onclick="b2bAskShopify('${it.id}')">+</button>
                </span>
                <span class="b2b-pcell b2b-pc-acts">
                    <button class="b2b-recycle" ${ok ? 'disabled' : ''} title="Recycle units out" onclick="b2bRecycleUnits('${it.id}')">Recycle</button>
                    ${_b2bLabelBtn(it)}
                </span>
            </div>
            ${(wipeStrip || codes) ? `<div class="b2b-lextra">${wipeStrip}${codes}</div>` : ''}
        </div>`;
    }).join('');

    return head + rows;
}

// Certify N units wiped. Same optimistic-then-reconcile shape as recycling, and
// on the same per-item queue -- the endpoint takes a delta, so order matters.
function b2bMarkWiped(itemId) {
    const it = _b2bLocalItem(itemId);
    if (!it || !it.wipe_required) return;
    // Corp only. The button is already hidden for a store, so this is the guard
    // against a stale tab whose role changed under it.
    if (!_b2bIsCorp()) return _b2bSay('Only corp can certify a data wipe.', true);
    const qty = Number(it.quantity) || 1;
    const room = qty - (Number(it.wiped_qty) || 0);
    if (room <= 0) return;
    const raw = room === 1 ? '1' : prompt(
        `How many "${_b2bItemName(it)}" units have been certified wiped?\n\n${room} still to do.`, String(room));
    if (raw === null) return;
    const units = Math.min(room, Math.max(1, parseInt(raw, 10) || 0));
    if (!units) return;

    const before = Number(it.wiped_qty) || 0;
    it.wiped_qty = before + units;
    _b2bDirty = true;
    _b2bRepaintListing();

    _b2bEnqueue(it.id, () => _b2bSend({ action: 'mark_wiped', id: it.id, units }))
        .then(out => {
            if (!out) return;
            it.wiped_qty = out.wiped_qty;
            _b2bRepaintListing();
        })
        .catch(e => {
            it.wiped_qty = before;
            _b2bRepaintListing();
            _b2bScanFlash(e.message, true, it.id);
        });
}

function _b2bRepaintListing() {
    const rows = document.getElementById('b2bListRows');
    const prog = document.getElementById('b2bListProg');
    if (rows) rows.innerHTML = _b2bListRows();
    if (prog) prog.innerHTML = _b2bListProgress();
    // Listed / to-do value shift as units go up, so the stat block moves with them.
    _b2bPaintDealStats();
    const done = document.getElementById('b2bListDone');
    if (done) done.disabled = !_b2bAllSatisfied();
}

function _b2bScanFlash(msg, bad, itemId) {
    const el = document.getElementById('b2bScanMsg');
    if (el) {
        el.textContent = msg;
        el.className = `b2b-scan-msg ${bad ? 'bad' : 'ok'}`;
        setTimeout(() => { if (el.textContent === msg) { el.textContent = ''; el.className = 'b2b-scan-msg'; } }, 2600);
    }
    if (itemId) {
        const row = document.getElementById(`b2bLrow-${itemId}`);
        if (row) { row.classList.add('hit'); setTimeout(() => row.classList.remove('hit'), 700); }
    }
}

// A barcode scanner is a keyboard: the whole code arrives as fast keystrokes,
// so this handles a scan and typed input identically. Which of the two scans is
// being read depends only on whether a line is already waiting.
//
// Everything needed to validate the first scan is in memory, so an unknown or
// already-full SKU is rejected instantly and only real scans hit the network.
function b2bScan(dealId) {
    const input = document.getElementById('b2bScanIn');
    const raw = (input?.value || '').trim();
    if (input) input.value = '';
    if (!raw) return;

    // Second scan: the Shopify barcode for the unit we are holding.
    if (_b2bPendingUnit) {
        const it = _b2bLocalItem(_b2bPendingUnit);
        if (!it) { _b2bPendingUnit = null; return _b2bRepaintScanBar(); }
        if (!/^\d{8}$/.test(raw)) {
            // Nearly always our own label scanned twice by mistake. Say which
            // mistake it was, because "invalid barcode" would not.
            const mine = _b2bModalItems.some(i => (i.sku || '').toUpperCase() === raw.toUpperCase());
            return _b2bScanFlash(mine
                ? "That's one of our labels — scan the Shopify listing's barcode instead."
                : `A Shopify barcode is 8 digits; that was ${raw.length}.`, true, it.id);
        }
        if (it.listings?.some(l => l.shopify_barcode === raw)) {
            return _b2bScanFlash(`${raw} is already recorded on this line.`, true, it.id);
        }
        return _b2bListUnit(it, raw);
    }

    // First scan: which line is this?
    const sku = raw.toUpperCase();
    const it = _b2bModalItems.find(i => (i.sku || '').toUpperCase() === sku);
    if (!it)               return _b2bScanFlash(`${sku} isn't a line on this deal.`, true);
    if (_b2bIsScrap(it))   return _b2bScanFlash(`${sku} is a recycle line — use Recycle instead of listing it.`, true, it.id);
    if (it.wipe_required && (Number(it.listed_qty) || 0) >= (Number(it.wiped_qty) || 0)) {
        return _b2bScanFlash(`${sku} needs a certified data wipe first — `
            + `${Number(it.wiped_qty) || 0} of ${Number(it.quantity) || 1} wiped.`, true, it.id);
    }
    if (_b2bSatisfied(it)) return _b2bScanFlash(`${sku} is already fully accounted for.`, true, it.id);
    b2bAskShopify(it.id);
}

// Both routes into the second scan -- the scanned label and the manual "+" --
// come through here, so a unit can never be ticked up without a barcode.
function b2bAskShopify(itemId) {
    const it = _b2bLocalItem(itemId);
    if (!it || _b2bIsScrap(it) || _b2bSatisfied(it)) return;
    if (it.wipe_required && (Number(it.listed_qty) || 0) >= (Number(it.wiped_qty) || 0)) return;
    _b2bPendingUnit = itemId;
    _b2bRepaintScanBar();
    _b2bRepaintListing();   // rows read _b2bPendingUnit to mark which one is waiting
}

// Apply locally, repaint now, then reconcile with the server. On failure the
// line snaps back and says why, rather than the click having felt ignored.
function _b2bListUnit(it, code) {
    const qty = Number(it.quantity) || 1;
    const before = { listed: Number(it.listed_qty) || 0, listings: (it.listings || []).slice() };
    if (before.listed + (Number(it.recycled_qty) || 0) >= qty) return;

    // A temp id so an undo landing before the server replies still targets the
    // right row; the reconcile below swaps in the real one.
    it.listings = [...before.listings, { id: `tmp-${code}`, shopify_barcode: code, listed_by: _b2bUser() }];
    it.listed_qty = before.listed + 1;
    _b2bPendingUnit = null;
    _b2bDirty = true;
    _b2bRepaintScanBar();
    _b2bRepaintListing();
    _b2bScanFlash(`${code} → ${it.sku || 'line'} · ${it.listed_qty} of ${qty} listed`, false, it.id);
    const done = _b2bAllSatisfied();

    _b2bEnqueue(it.id, () => _b2bSend({ action: 'list_unit', id: it.id, shopify_barcode: code }))
        .then(out => {
            if (!out) return;
            it.listed_qty = out.listed_qty;
            it.recycled_qty = out.recycled_qty;
            it.listings = out.listings || it.listings;
            _b2bRepaintListing();
        })
        .catch(e => {
            it.listed_qty = before.listed;
            it.listings = before.listings;
            _b2bRepaintListing();
            _b2bScanFlash(e.message, true, it.id);
        });

    if (done) _b2bCelebrate(_b2bModalDeal?.id);
}

// Undo one listed unit. Named barcodes come off individually; the bare "−"
// takes the most recent, which is what "I just scanned that wrong" means.
function b2bUnlistUnit(itemId, listingId) {
    const it = _b2bLocalItem(itemId);
    if (!it) return;
    const list = it.listings || [];
    const target = listingId ? list.find(l => l.id === listingId) : list[list.length - 1];
    if (!target) return;
    if (listingId && !confirm(`Remove Shopify barcode ${target.shopify_barcode} from this line?\n\n`
        + 'The unit goes back on the checklist to be listed again.')) return;

    const before = { listed: Number(it.listed_qty) || 0, listings: list.slice() };
    it.listings = list.filter(l => l !== target);
    it.listed_qty = Math.max(0, before.listed - 1);
    _b2bDirty = true;
    _b2bRepaintListing();

    // A temp id means the insert is still in flight; the queue serialises them,
    // so by the time this runs the server has a real row -- and no listing_id
    // means "the most recent", which is that same row.
    const realId = String(target.id).startsWith('tmp-') ? null : target.id;
    _b2bEnqueue(it.id, () => _b2bSend({ action: 'unlist_unit', id: it.id, listing_id: realId || undefined }))
        .then(out => {
            if (!out) return;
            it.listed_qty = out.listed_qty;
            it.recycled_qty = out.recycled_qty;
            it.listings = out.listings || it.listings;
            _b2bRepaintListing();
        })
        .catch(e => {
            it.listed_qty = before.listed;
            it.listings = before.listings;
            _b2bRepaintListing();
            _b2bScanFlash(e.message, true, it.id);
        });
}

function b2bRecycleUnits(itemId) {
    const it = _b2bLocalItem(itemId);
    if (!it) return;
    const room = (Number(it.quantity) || 1) - _b2bDone(it);
    if (room <= 0) return;
    const raw = prompt(`How many "${_b2bItemName(it)}" units are being recycled out?\n\n${room} unit${room === 1 ? '' : 's'} still outstanding.`, String(room));
    if (raw === null) return;
    const units = Math.min(room, Math.max(1, parseInt(raw, 10) || 0));
    if (!units) return;
    if (!confirm(`Recycle ${units} unit${units === 1 ? '' : 's'} of "${_b2bItemName(it)}"?\n\nThey come off the listing checklist for good and won't be listed for resale. This can't be undone.`)) return;

    const before = Number(it.recycled_qty) || 0;
    it.recycled_qty = before + units;
    _b2bDirty = true;
    _b2bRepaintListing();
    const done = _b2bAllSatisfied();

    _b2bEnqueue(it.id, () => _b2bSend({ action: 'recycle_units', id: it.id, units }))
        .then(out => {
            if (!out) return;
            it.listed_qty = out.listed_qty;
            it.recycled_qty = out.recycled_qty;
            _b2bRepaintListing();
        })
        .catch(e => {
            it.recycled_qty = before;
            _b2bRepaintListing();
            _b2bScanFlash(e.message, true, it.id);
        });

    if (done) _b2bCelebrate(_b2bModalDeal?.id);
}

// Every unit is accounted for -- say so properly before closing the deal out.
function _b2bCelebrate(dealId) {
    const deal = _b2bDealById(dealId) || _b2bModalDeal;
    if (!deal) return;
    const units = _b2bModalItems.reduce((n, it) => n + (Number(it.quantity) || 1), 0);
    const recycled = _b2bModalItems.reduce((n, it) => n + (Number(it.recycled_qty) || 0), 0);
    document.getElementById('b2bDealBody').innerHTML = `
        <div class="b2b-celebrate">
            <div class="b2b-cel-ring">${_b2bIco('<polyline points="20 6 9 17 4 12"/>')}</div>
            <div class="b2b-cel-t">Every unit is accounted for</div>
            <div class="b2b-cel-s">${escapeHtml(deal.ref)} · ${escapeHtml(deal.client?.company || '')}</div>
            <div class="b2b-cel-stats">
                <div><b>${units - recycled}</b><span>listed</span></div>
                ${recycled ? `<div><b>${recycled}</b><span>recycled</span></div>` : ''}
                <div><b>${_b2bMoney(deal.total_cost ? _b2bNetCost(deal) : _b2bNetOffer(deal))}</b><span>inventory cost</span></div>
            </div>
        </div>`;
    document.getElementById('b2bDealFooter').innerHTML = `
        <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Not Yet</button>
        <button class="b2b-btn b2b-btn-primary" onclick="b2bCompleteDeal('${deal.id}',this)">Complete Deal</button>`;
}

async function b2bCompleteDeal(id) {
    await _b2bPost({ action: 'complete', id }, "Couldn't complete the deal");
    closeAllModals();
    await b2bRefresh();
}

// --- read-only view --------------------------------------------------------

function _b2bStageView(deal) {
    const t = _b2bItemTotals();
    const rows = _b2bModalItems.map(it => {
        const qty = Number(it.quantity) || 1;
        const buy = _b2bIsBuy(it);
        const disp = _b2bDispOf(it);
        const spec = _b2bQuoteDesc(it);
        const ser = _b2bSerials(it);
        return `<tr>
            <td><b>${escapeHtml(_b2bItemName(it))}</b>
                ${!buy ? `<span class="b2b-doc-rec ${_b2bIsScrap(it) ? '' : 'nrv'}">${escapeHtml(B2B_DISP[disp].label)}</span>` : ''}
                ${it.wipe_required ? `<span class="b2b-doc-rec wipe">Wipe ${Number(it.wiped_qty) || 0}/${qty}</span>` : ''}
                ${spec ? `<div class="b2b-doc-sub">${escapeHtml(spec)}</div>` : ''}
                ${it.client_notes ? `<div class="b2b-doc-sub">${escapeHtml(it.client_notes)}</div>` : ''}
                ${it.staff_notes ? `<div class="b2b-doc-sub int">Internal: ${escapeHtml(it.staff_notes)}</div>` : ''}
                ${ser.length ? `<div class="b2b-doc-sku b2b-mono">${escapeHtml(ser.join(', '))}</div>` : ''}
                <div class="b2b-doc-sku b2b-mono">${escapeHtml(it.sku || '')}</div></td>
            <td class="c">${escapeHtml(it.condition || '—')}</td>
            <td class="c">${qty}</td>
            <td class="c">${_b2bDone(it)}/${qty}</td>
            <td class="r">${buy ? _b2bMoney(it.cost != null ? it.cost : it.offer, 2) : '—'}</td>
            <td class="r b">${buy ? _b2bMoney((Number(it.cost != null ? it.cost : it.offer) || 0) * qty, 2) : '—'}</td>
            <td class="r">${_b2bLabelBtn(it)}</td>
        </tr>`;
    }).join('');

    const canDecline = _b2bIsCorp() && !['listing', 'completed', 'declined'].includes(deal.stage);
    // Reopen is gone -- a declined deal is final (see the edge fn). Deletion is
    // the only way a deal leaves the record now; the trashcan in the modal header
    // (every stage, via delDeal) raises the request and CORP approves it.
    _b2bShowDeal({
        stage: deal.stage,
        delDeal: deal,
        eyebrow: deal.ref,
        title: deal.client?.company || 'Deal',
        sub: `${B2B_STAGE[deal.stage]?.label || deal.stage}${deal.accepted_at ? ` · accepted ${_b2bDate(deal.accepted_at)}` : ''}`,
        wide: true,
        body: `
            ${_b2bSummary(deal)}
            ${_b2bModalItems.length ? _b2bDealStatsHtml(_b2bModalItems, deal) : ''}
            ${deal.pickup_desc ? `<div class="b2b-note"><span class="b2b-note-k">${_b2bIntake(deal).was}</span>${escapeHtml(deal.pickup_desc)}</div>` : ''}
            ${deal.declined_reason ? `<div class="b2b-note bad">
                <span class="b2b-note-k">Declined</span>
                <span>${escapeHtml(deal.declined_reason)}
                    <div class="b2b-note-sub">${escapeHtml([
                        B2B_DECLINE_REASONS.find(r => r.key === deal.declined_category)?.label,
                        deal.declined_by ? `marked by ${deal.declined_by}` : '',
                        deal.declined_at ? _b2bDate(deal.declined_at) : '',
                    ].filter(Boolean).join(' · '))}</div></span>
            </div>` : ''}
            ${_b2bModalItems.length ? `
            <table class="cb-table b2b-vtable">
                <thead><tr><th>Item</th><th class="c">Condition</th><th class="c">Qty</th><th class="c">Done</th><th class="r">Unit</th><th class="r">Line</th><th></th></tr></thead>
                <tbody>${rows}</tbody>
                <tfoot><tr><td colspan="5" class="r">Total</td><td class="r accent">${_b2bMoney(t.offer, 2)}</td><td></td></tr></tfoot>
            </table>` : '<div class="b2b-empty sm"><div class="b2b-empty-t">No line items yet</div></div>'}`,
        footer: `
            ${canDecline ? `<button class="b2b-btn b2b-btn-danger" onclick="b2bDeclineDeal('${deal.id}')">Decline Deal</button>` : ''}
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Close</button>`,
    });
}

// A deal that dies. Categorised as well as explained, so the Overview can say
// why deals are being lost rather than just how many.
const B2B_DECLINE_REASONS = [
    { key: 'client_declined',     label: 'Client turned the offer down' },
    { key: 'client_unresponsive', label: 'Client went quiet' },
    { key: 'withdrawn',           label: 'Client withdrew the equipment' },
    { key: 'not_viable',          label: 'Not worth doing on our side' },
    { key: 'other',               label: 'Something else' },
];

function b2bDeclineDeal(id) {
    const deal = _b2bDealById(id) || _b2bModalDeal;
    if (!deal) return;
    _b2bShowDeal({
        stage: 'declined',
        eyebrow: deal.ref,
        title: 'Decline This Deal',
        sub: 'Records the deal as dead, with why, and takes it off the board.',
        body: `
            ${_b2bSummary(deal)}
            <label class="form-label-caps">What happened?</label>
            <div class="b2b-reasons">
                ${B2B_DECLINE_REASONS.map((r, i) => `
                    <label class="b2b-reason">
                        <input type="radio" name="b2bDeclineCat" value="${r.key}" ${i === 0 ? 'checked' : ''}>
                        <span>${escapeHtml(r.label)}</span>
                    </label>`).join('')}
            </div>
            <label class="form-label-caps" style="margin-top:16px;">Details *</label>
            <textarea id="b2bDeclineWhy" class="form-input-lg" rows="3"
                placeholder="A sentence for whoever reads this in six months"></textarea>
            <div class="b2b-note bad" style="margin-top:14px;">
                <span class="b2b-note-k">Note</span>
                The deal stays on record and can be reopened if the client comes back —
                it just stops appearing as work in flight.
            </div>`,
        footer: `
            <span class="b2b-msg" id="b2bDealMsg"></span>
            <button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Back</button>
            <button class="b2b-btn b2b-btn-danger" style="margin-right:0;" onclick="b2bConfirmDecline('${deal.id}',this)">Mark Declined</button>`,
    });
}

async function b2bConfirmDecline(id, btn) {
    const reason = document.getElementById('b2bDeclineWhy')?.value.trim();
    if (!reason) return _b2bSay('Add a short reason before declining.', true);
    const category = document.querySelector('input[name="b2bDeclineCat"]:checked')?.value;
    try {
        await _b2bBusy(btn, 'Declining…', () =>
            _b2bSend({ action: 'decline', id, reason, category, declined_by: _b2bUser() }));
        closeAllModals();
        await b2bRefresh();
    } catch (e) {
        _b2bSay(`Couldn't decline the deal: ${e.message}`, true);
    }
}

// ---------------------------------------------------------------------------
// DELETION REQUESTS
// ---------------------------------------------------------------------------
// Reopen is gone: a declined deal is final. Deletion is now the only way a deal
// leaves the record, and it always goes through CORP. Anyone at a deal raises a
// request from the trashcan (any stage); a CEO/MOCD/DM approves or denies it,
// either on the deal itself or from the Delete Requests modal off the B2B tab.
// Same shape as the claims / recycle delete flow.
// The header trashcan. With no request pending it raises one; once one is
// pending it opens the Delete Requests queue, where CORP approves or denies.
function b2bDealDeleteClick() {
    const deal = _b2bModalDeal;
    if (!deal) return;
    if (deal.delete_requested_at) b2bDeleteRequests();
    else b2bRequestDelete(deal.id);
}

async function b2bRequestDelete(id) {
    const deal = _b2bDealById(id) || _b2bModalDeal;
    const ref = deal?.ref || 'this deal';
    if (!confirm(`Request that ${ref} be deleted?\n\nThis asks a CEO, MOCD or DM to approve — nothing is removed until they do. Once approved, the deal and everything on it is gone for good.`)) return;
    try {
        await _b2bSend({ action: 'request_delete', id, requested_by: _b2bUser() });
        closeAllModals();
        await b2bRefresh();
        alert('Delete request sent — a CEO, MOCD or DM will review it.');
    } catch (e) {
        alert(`Couldn't send the request: ${e.message}`);
    }
}

// CORP approves: the deal and everything under it is permanently removed.
async function b2bApproveDelete(id, btn) {
    const deal = _b2bDealById(id) || _b2bModalDeal;
    const ref = deal?.ref || 'this deal';
    if (!confirm(`Permanently delete ${ref}?\n\nThe deal, its line items, listings, transfers and approval evidence are all removed. This cannot be undone.`)) return;
    try {
        await _b2bBusy(btn, 'Deleting…', () => _b2bSend({ action: 'approve_delete', id, role: _b2bRole(), user: _b2bUser() }));
        await b2bRefresh();
        _b2bAfterDeleteAction();
    } catch (e) {
        alert(`Couldn't delete the deal: ${e.message}`);
    }
}

// CORP denies: the request clears and the deal carries on.
async function b2bDenyDelete(id, btn) {
    try {
        await _b2bBusy(btn, 'Denying…', () => _b2bSend({ action: 'deny_delete', id, role: _b2bRole(), user: _b2bUser() }));
        await b2bRefresh();
        _b2bAfterDeleteAction();
    } catch (e) {
        alert(`Couldn't deny the request: ${e.message}`);
    }
}

// After approving/denying: if the Delete Requests modal is open, re-render it so
// CORP can work through the rest; otherwise close the deal modal it came from.
function _b2bAfterDeleteAction() {
    if (document.getElementById('b2bDelReqList')) b2bDeleteRequests();
    else closeAllModals();
}

// The pending delete requests, drawn from whatever the board already loaded --
// no extra fetch. CORP-only surface: opened from the trashcan button on the B2B
// tab, and the red dots point here.
function _b2bDeleteRequestRows() {
    return (_b2bDeals || [])
        .filter(d => d.delete_requested_at)
        .sort((a, b) => new Date(a.delete_requested_at) - new Date(b.delete_requested_at));
}

function b2bDeleteRequests() {
    const rows = _b2bDeleteRequestRows();
    const canAct = _b2bCanAccept();
    const body = rows.length ? rows.map(d => `
        <div class="b2b-delreq-row">
            <div class="b2b-delreq-meta">
                <b>${escapeHtml(d.ref || '')}</b> · ${escapeHtml(d.company || 'Client')}
                <div class="b2b-delreq-sub">${escapeHtml(B2B_STAGE[d.stage]?.label || d.stage)} · asked by ${escapeHtml(d.delete_requested_by || 'someone')} · ${_b2bDate(d.delete_requested_at)}</div>
            </div>
            <div class="b2b-delreq-acts">
                <button class="b2b-btn b2b-btn-secondary b2b-mini" onclick="b2bOpenDeal('${d.stage}','${d.id}')">Open</button>
                ${canAct ? `<button class="b2b-btn b2b-btn-danger b2b-mini" onclick="b2bApproveDelete('${d.id}',this)">Delete</button>
                            <button class="b2b-btn b2b-btn-secondary b2b-mini" onclick="b2bDenyDelete('${d.id}',this)">Keep</button>` : ''}
            </div>
        </div>`).join('')
        : '<div class="b2b-empty sm"><div class="b2b-empty-t">No pending delete requests</div></div>';
    _b2bShowDeal({
        stage: '',
        noPrint: true,
        svg: '<polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/>',
        eyebrow: 'B2B',
        title: 'Delete Requests',
        sub: canAct
            ? 'A store asked for these deals to be removed. Deleting is permanent.'
            : 'Deals a store has asked to remove. A CEO, MOCD or DM approves them.',
        body: `<div id="b2bDelReqList" class="b2b-delreq-list">${body}</div>`,
        footer: `<button class="kpi-cancel-btn" onclick="b2bCloseDeal()">Close</button>`,
    });
}

// ---------------------------------------------------------------------------
// BARCODE LABELS
// ---------------------------------------------------------------------------
// Code 128B, encoded here rather than pulled from a library: the page has no
// build step and no CDN access, and hand-rolling it means the barcode is a
// vector SVG that stays crisp on both label sizes instead of a fixed-DPI
// canvas. SKUs are uppercase alphanumerics with hyphens, all of which sit in
// the plain Code 128B character set.

// One entry per code value 0-106. Each is bar/space module widths, alternating
// bar-first. 103 = Start A, 104 = Start B, 105 = Start C, 106 = Stop.
const _B2B_C128 = [
    '212222','222122','222221','121223','121322','131222','122213','122312','132212','221213',
    '221312','231212','112232','122132','122231','113222','123122','123221','223211','221132',
    '221231','213212','223112','312131','311222','321122','321221','312212','322112','322211',
    '212123','212321','232121','111323','131123','131321','112313','132113','132311','211313',
    '231113','231311','112133','112331','132131','113123','113321','133121','313121','211331',
    '231131','213113','213311','213131','311123','311321','331121','312113','312311','332111',
    '314111','221411','431111','111224','111422','121124','121421','141122','141221','112214',
    '112412','122114','122411','142112','142211','241211','221114','413111','241112','134111',
    '111242','121142','121241','114212','124112','124211','411212','421112','421211','212141',
    '214121','412121','111143','111341','131141','114113','114311','411113','411311','113141',
    '114131','311141','411131','211412','211214','211232','2331112'
];

// Returns the bar rectangles plus the total module width, quiet zones included.
function _b2bCode128B(data) {
    const QUIET = 10;
    const values = [104];                       // Start B
    for (const ch of String(data)) {
        const v = ch.charCodeAt(0) - 32;
        if (v < 0 || v > 94) throw new Error(`"${ch}" can't be encoded in Code 128B`);
        values.push(v);
    }
    // Checksum: start value plus each data value times its 1-based position.
    let sum = 104;
    for (let i = 1; i < values.length; i++) sum += values[i] * i;
    values.push(sum % 103);
    values.push(106);                           // Stop

    const bars = [];
    let x = QUIET;
    values.forEach(v => {
        const pattern = _B2B_C128[v];
        for (let i = 0; i < pattern.length; i++) {
            const w = Number(pattern[i]);
            if (i % 2 === 0) bars.push({ x, w }); // even index is a bar, odd a space
            x += w;
        }
    });
    return { bars, width: x + QUIET };
}

function _b2bBarcodeSvg(data) {
    let enc;
    try { enc = _b2bCode128B(data); } catch (_) { return ''; }
    const H = 100;
    const rects = enc.bars.map(b => `<rect x="${b.x}" y="0" width="${b.w}" height="${H}"/>`).join('');
    // preserveAspectRatio="none" lets the label CSS set width and height
    // independently -- every bar scales by the same factor, so it stays valid.
    return `<svg class="bc" viewBox="0 0 ${enc.width} ${H}" preserveAspectRatio="none" shape-rendering="crispEdges">${rects}</svg>`;
}

// ---------------------------------------------------------------------------
// FULL-PAGE PALLET TAGS — one standard, two sheets
//
// The holding tag and the SKU tag are the same object at two points in the
// pipeline: a sheet taped to a pallet saying which deal it is. They had drifted
// into two unrelated documents -- one a bordered tag with a barcode, a meta grid
// and a handling note, the other centred type on a fold line with no barcode at
// all -- so the same pallet got identified two different ways depending only on
// how far along it happened to be. Someone reading a stack of them had to learn
// two layouts to read one fact.
//
// The document is built once, by _b2bTagSheet. Each sheet supplies only what is
// genuinely different: the status band, three meta cells, and the sentence at
// the bottom saying what to do with it.
//
// THE STANDARD, top to bottom. Adding a sheet means filling these in, not
// inventing a layout:
//   band      what is happening to this pallet right now
//   company   who it came from
//   barcode   Code 128 of deal.ref -- scannable, and now on BOTH sheets
//   ref       the reference, auto-sized to fill the width; this is the thing
//             read from across a room, so it gets whatever space is left
//   meta      exactly three cells, so the grid never reflows
//   contents  what is on the pallet, when we know
//   note      what NOT to do with it
//
// Both print full-page portrait, and both offer the same 2.25x1in fallback for
// when the label printer is what is to hand. b2bPrintLabels is deliberately not
// part of this: a per-unit device label is a different physical object, not a
// smaller version of the same one.
// ---------------------------------------------------------------------------

// Monospace runs about 0.62em per character and the tracking below adds another
// 0.06em, against ~470pt of usable width inside the tag's padding. Capped at
// both ends so a two-character ref isn't absurd and a long one stays readable.
function _b2bTagRefSize(ref) {
    return Math.max(36, Math.min(90, Math.floor(470 / (Math.max(1, String(ref || '').length) * 0.68))));
}

function _b2bTagSheet(cfg) {
    const ref = String(cfg.ref || '');
    // Always three, padded if a caller has fewer: the grid is a fixed rhythm
    // across both sheets, and a short row would read as a different layout.
    const cells = [...(cfg.meta || []), ['', ''], ['', ''], ['', '']].slice(0, 3);
    return `<!doctype html><html><head><meta charset="utf-8">
<title>${escapeHtml(cfg.docTitle || ref)}</title>
<style id="pageSize">@page { size: letter portrait; margin: 0.4in; }</style>
<style>
  * { box-sizing: border-box; }
  body { margin: 0; font-family: 'Inter','Segoe UI',Arial,sans-serif; background: #f4f7f9; }
  .bar { position: sticky; top: 0; display: flex; gap: 8px; align-items: center;
         padding: 12px 16px; background: #fff; border-bottom: 1px solid #e6ebf1; }
  .bar b { font-size: 13px; font-weight: 800; color: #1a1c1e; margin-right: 6px; }
  .bar span { font-size: 12px; color: #94a3b8; }
  .bar button { font: inherit; font-size: 12px; font-weight: 700; cursor: pointer;
                padding: 7px 13px; border-radius: 9px; border: 1px solid #e6ebf1;
                background: #fff; color: #647082; }
  .bar button.on { background: #e8f7ee; border-color: #1f9d57; color: #178048; }
  .bar button.go { background: #1f9d57; border-color: #1f9d57; color: #fff; margin-left: auto; }
  .sheet { padding: 20px; display: flex; justify-content: center; }

  /* The ref size rides on a custom property rather than an inline font-size, so
     the 2.25in rules below can override it without !important. */
  .tag { width: 7.7in; background: #fff; border: 2px solid #111;
         padding: 0.36in 0.42in; --ref: 60pt; }
  .tag .band { font-size: 14pt; font-weight: 800; letter-spacing: .2em;
               text-transform: uppercase; border-bottom: 2px solid #111; padding-bottom: 0.1in; }
  .tag .co { font-size: 30pt; font-weight: 800; line-height: 1.05; margin-top: 0.16in;
             max-width: 100%; overflow-wrap: anywhere; }
  .tag .bc { display: block; width: 100%; height: 1.15in; fill: #000; margin-top: 0.16in; }
  .tag .rf { font-family: 'Consolas','SFMono-Regular','Menlo',monospace; font-size: var(--ref);
             font-weight: 800; letter-spacing: .06em; line-height: 1; text-align: center;
             margin-top: 0.06in; white-space: nowrap; }
  .tag .gr { display: flex; gap: 0.4in; margin-top: 0.22in;
             border-top: 1px solid #111; padding-top: 0.14in; }
  .tag .gr > div { flex: 1; min-width: 0; }
  .tag .k { font-size: 9pt; font-weight: 800; letter-spacing: .12em;
            text-transform: uppercase; color: #444; }
  .tag .v { font-size: 15pt; font-weight: 700; margin-top: 0.03in; overflow-wrap: anywhere; }
  .tag .ds { font-size: 12pt; margin-top: 0.18in; line-height: 1.35; }
  .tag .ft { font-size: 9.5pt; color: #444; margin-top: 0.2in;
             border-top: 1px solid #ccc; padding-top: 0.1in; }

  /* Label-printer stock: only what identifies the pallet survives the shrink. */
  body.sm .sheet { padding: 16px; }
  body.sm .tag { width: 2.25in; height: 1in; padding: 0.05in 0.07in; border-width: 1px;
                 --ref: 9pt;
                 display: flex; flex-direction: column; align-items: center; justify-content: center; }
  body.sm .tag .band { font-size: 6pt; letter-spacing: .14em; border: 0; padding: 0; }
  body.sm .tag .co { font-size: 7.5pt; margin: 0; max-width: 100%;
                     white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  body.sm .tag .bc { height: 0.34in; margin-top: 0.02in; }
  body.sm .tag .rf { margin: 0; letter-spacing: .04em; }
  body.sm .tag .gr, body.sm .tag .ds, body.sm .tag .ft { display: none; }

  @media print {
    body { background: #fff; }
    .bar { display: none; }
    .sheet { padding: 0; display: block; }
    .tag { width: 100%; }
    body.sm .tag { width: 2.25in; }
  }
</style></head>
<body>
  <div class="bar">
    <b>${escapeHtml(ref)}</b>
    <button id="b1" class="on" onclick="setSize(false)">Full page</button>
    <button id="b2" onclick="setSize(true)">2.25 × 1 in</button>
    ${cfg.hint ? `<span>${escapeHtml(cfg.hint)}</span>` : ''}
    <button class="go" onclick="window.print()">Print</button>
  </div>
  <div class="sheet">
    <div class="tag" style="--ref:${_b2bTagRefSize(ref)}pt;">
      <div class="band">${escapeHtml(cfg.band || 'B2B')}</div>
      <div class="co">${escapeHtml(cfg.company || '—')}</div>
      ${_b2bBarcodeSvg(ref)}
      <div class="rf">${escapeHtml(ref)}</div>
      <div class="gr">
        ${cells.map(([k, v]) => `
        <div><div class="k">${escapeHtml(k)}</div><div class="v">${escapeHtml(k ? (v || '—') : '')}</div></div>`).join('')}
      </div>
      ${cfg.contents ? `<div class="ds"><b>Contents:</b> ${escapeHtml(cfg.contents)}</div>` : ''}
      ${cfg.note ? `<div class="ft">${escapeHtml(cfg.note)}</div>` : ''}
    </div>
  </div>
<script>
  function setSize(small) {
    document.body.classList.toggle('sm', small);
    document.getElementById('b1').className = small ? '' : 'on';
    document.getElementById('b2').className = small ? 'on' : '';
    document.getElementById('pageSize').textContent = small
      ? '@page { size: 2.25in 1in; margin: 0; }'
      : '@page { size: letter portrait; margin: 0.4in; }';
  }
<\/script>
</body></html>`;
}

// Every print path opens the same way, and the only thing that differed was the
// noun in the pop-up warning.
function _b2bOpenSheet(doc, what) {
    const w = window.open('', '_blank');
    if (!w) return alert(`Allow pop-ups for this site to print the ${what}.`);
    w.document.write(doc);
    w.document.close();
}

// Company plus acronym, which is how the tag names a client on both sheets.
function _b2bTagCompany(deal) {
    const co  = deal.client?.company || deal.company || '—';
    const acr = deal.client?.acronym || deal.acronym || '';
    return acr ? `${co} (${acr})` : co;
}

// A tag for the pallet itself, for the stretch between "we took it in" and
// "it has been priced".
//
// The per-unit labels can't cover this: b2bPrintLabels keys off it.sku, and
// SKUs are not minted until a line exists, so a pickup waiting to be routed has
// nothing printable at all -- it sits in a back room identified by nothing.
// deal.ref exists from creation, which is what this prints.
function b2bPrintHoldingLabel(dealId) {
    const deal = _b2bDealById(dealId) || _b2bModalDeal;
    if (!deal) return;
    _b2bOpenSheet(_b2bTagSheet({
        docTitle: `Holding ${deal.ref}`,
        band: 'Holding — Awaiting Pricing',
        ref: deal.ref,
        company: _b2bTagCompany(deal),
        meta: [
            [_b2bIntake(deal).was, deal.pickup_date ? _b2bDate(deal.pickup_date) : '—'],
            ['Price It At', deal.pricing_store || 'Not yet assigned'],
            ['Released By', deal.signed_by || '—'],
        ],
        contents: deal.pickup_desc || 'No description recorded',
        note: 'Do not process or list these items until this deal has been priced and the client '
            + 'has accepted the quote. Look the reference up in Operations → Business-to-Business.',
    }), 'holding label');
}

function b2bPrintLabels(dealId, itemId, count) {
    const deal = _b2bDealById(dealId) || _b2bModalDeal;
    if (!deal) return;
    const source = itemId ? _b2bModalItems.filter(i => i.id === itemId) : _b2bModalItems;
    const labels = [];

    if (itemId) {
        // One line: ask how many. A qty-20 line used to print twenty labels
        // whether you wanted twenty or the one you just tore. The default is the
        // outstanding count, because that is how many are still to be handled --
        // and once a line is fully listed it falls to 1, which is the reprint
        // case. Skipped entirely for a single-unit line; there is nothing to ask.
        const it = source[0];
        if (it && it.sku) {
            const qty  = Math.max(1, Number(it.quantity) || 1);
            const done = (Number(it.listed_qty) || 0) + (Number(it.recycled_qty) || 0);
            // Default to the units that have no tag yet, not to the whole line.
            // Ethan: adding quantity to an existing line and then printing "more
            // labels" reprinted everything, so you either wasted a sheet or
            // hand-counted the difference. Falls back to what is left to handle
            // when the line is fully tagged already, which is the reprint case.
            const short = _b2bLabelsShort(it);
            const left  = Math.max(1, short || (qty - done));
            let n = Number(count) || 0;
            if (!n) {
                if (qty === 1 && !it.label_printed_qty) {
                    n = 1;
                } else {
                    const printed = Number(it.label_printed_qty) || 0;
                    const raw = prompt(
                        `How many labels for "${_b2bItemName(it)}"?\n\n`
                        + `${qty} unit${qty === 1 ? '' : 's'} on the line`
                        + `${printed ? `, ${printed} label${printed === 1 ? '' : 's'} printed so far` : ', none printed yet'}`
                        + `${short ? ` — ${short} still untagged` : ''}.`, String(left));
                    if (raw === null) return;
                    n = parseInt(raw, 10) || 0;
                }
            }
            // Upper bound is generous rather than the line quantity: reprinting
            // a torn tag on a fully-tagged line is a normal thing to want, and
            // clamping to qty silently refused it.
            n = Math.min(1000, Math.max(1, n));
            for (let i = 0; i < n; i++) labels.push(it);
        }
    } else {
        source.forEach(it => {
            if (!it.sku) return;
            const n = Math.max(1, Number(it.quantity) || 1);
            for (let i = 0; i < n; i++) labels.push(it);
        });
    }

    if (!labels.length) {
        return alert('No SKUs to print yet — a line gets one as soon as it is added.');
    }

    // What happens to the unit, on the unit. A recycle line printed labels
    // indistinguishable from a purchase, so once the paperwork was off the pallet
    // there was nothing on the box itself saying "this must not be listed".
    // Styled for a mono thermal printer rather than with colour: recycle is
    // knocked out of solid black, no-residual is boxed, a purchase is plain.
    const DISP_LABEL = { purchase: 'Purchased', no_residual: 'No Residual Value', recycle: 'Recycle' };
    const DISP_CLASS = { purchase: 'buy', no_residual: 'nrv', recycle: 'rec' };
    const cells = labels.map(it => {
        const d = _b2bDispOf(it);
        return `
        <div class="lb">
            ${_b2bBarcodeSvg(it.sku)}
            <div class="sku">${escapeHtml(it.sku)}</div>
            <div class="desc">${escapeHtml(_b2bItemName(it))}</div>
            <div class="disp ${DISP_CLASS[d] || 'buy'}">${escapeHtml(DISP_LABEL[d] || DISP_LABEL.purchase)}</div>
        </div>`;
    }).join('');

    const doc = `<!doctype html><html><head><meta charset="utf-8">
<title>Labels ${escapeHtml(deal.ref)}</title>
<style id="pageSize">@page { size: 2.25in 1in; margin: 0; }</style>
<style>
  * { box-sizing: border-box; }
  body { margin: 0; font-family: 'Inter','Segoe UI',Arial,sans-serif; background: #f4f7f9; }
  .bar { position: sticky; top: 0; display: flex; gap: 8px; align-items: center;
         padding: 12px 16px; background: #fff; border-bottom: 1px solid #e6ebf1; }
  .bar b { font-size: 13px; font-weight: 800; color: #1a1c1e; margin-right: 6px; }
  .bar button { font: inherit; font-size: 12px; font-weight: 700; cursor: pointer;
                padding: 7px 13px; border-radius: 9px; border: 1px solid #e6ebf1;
                background: #fff; color: #647082; }
  .bar button.on { background: #e8f7ee; border-color: #1f9d57; color: #178048; }
  .bar button.go { background: #1f9d57; border-color: #1f9d57; color: #fff; margin-left: auto; }
  .bar span { font-size: 12px; color: #94a3b8; }

  .sheet { padding: 16px; display: flex; flex-wrap: wrap; gap: 8px; }
  .lb { width: 2.25in; height: 1in; padding: 0.05in 0.07in; background: #fff;
        border: 1px dashed #cbd5e1; display: flex; flex-direction: column;
        align-items: center; justify-content: center; overflow: hidden; }
  /* 0.38in, down from 0.42, to pay for the description growing and the handling
     line arriving. Still ~9.5mm of bar height, comfortably over what Code 128
     needs to scan. */
  .lb .bc { display: block; width: 100%; height: 0.38in; fill: #000; }
  .lb .sku { font-family: 'Consolas','SFMono-Regular',monospace; font-size: 10pt;
             font-weight: 700; letter-spacing: .04em; line-height: 1.1; margin-top: 0.03in; }
  /* Was 6.5pt, which the label printers were not reproducing legibly. */
  .lb .desc { font-size: 8pt; color: #000; line-height: 1.1; margin-top: 0.01in;
              max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  /* No colour: these go to a mono thermal printer, so the three outcomes are
     told apart by weight and inversion instead. Recycle is the one that must be
     unmissable -- it means do not list this -- so it takes the solid block. */
  .lb .disp { margin-top: 0.025in; font-size: 7.5pt; font-weight: 800;
              letter-spacing: .06em; text-transform: uppercase; line-height: 1.1;
              max-width: 100%; white-space: nowrap; overflow: hidden; }
  .lb .disp.buy { color: #000; }
  .lb .disp.nrv { color: #000; border: 1pt solid #000; padding: 0 0.045in; border-radius: 2pt; }
  .lb .disp.rec { background: #000; color: #fff; padding: 0.008in 0.055in; border-radius: 2pt; }

  /* The short stock has no room for the description as well, and between the two
     the handling is the one that changes what you DO with the unit -- the SKU
     above it already says exactly which line it is. */
  body.sm .lb { height: 0.75in; }
  body.sm .lb .bc { height: 0.30in; }
  body.sm .lb .sku { font-size: 9pt; }
  body.sm .lb .desc { display: none; }
  body.sm .lb .disp { font-size: 7pt; margin-top: 0.02in; }

  @media print {
    body { background: #fff; }
    .bar { display: none; }
    .sheet { padding: 0; gap: 0; display: block; }
    .lb { border: none; page-break-after: always; break-after: page; }
    .lb:last-child { page-break-after: auto; break-after: auto; }
  }
</style></head>
<body>
  <div class="bar">
    <b>${escapeHtml(deal.ref)}</b>
    <button id="b1" class="on" onclick="setSize(false)">2.25 × 1 in</button>
    <button id="b2" onclick="setSize(true)">2.25 × 0.75 in</button>
    <span>${labels.length} label${labels.length === 1 ? '' : 's'} — one per unit</span>
    <button class="go" onclick="window.print()">Print</button>
  </div>
  <div class="sheet">${cells}</div>
<script>
  function setSize(small) {
    document.body.classList.toggle('sm', small);
    document.getElementById('b1').className = small ? '' : 'on';
    document.getElementById('b2').className = small ? 'on' : '';
    document.getElementById('pageSize').textContent =
      '@page { size: 2.25in ' + (small ? '0.75in' : '1in') + '; margin: 0; }';
  }
<\/script>
</body></html>`;

    _b2bOpenSheet(doc, 'unit labels');

    // Record what was printed. Fire-and-forget on purpose: the labels are
    // already coming out of the printer, and a failed write here must not throw
    // an error over a job that physically happened. Worst case the line still
    // reads as short and somebody prints one more.
    const tally = new Map();
    labels.forEach(it => tally.set(it.id, (tally.get(it.id) || 0) + 1));
    if (tally.size) {
        _b2bSend({ action: 'mark_label_printed',
                   lines: [...tally].map(([id, qty]) => ({ id, qty })) })
            .then(() => {
                // Keep the open sheet honest without a refetch.
                tally.forEach((qty, id) => {
                    const it = _b2bLocalItem(id);
                    if (it) it.label_printed_qty = (Number(it.label_printed_qty) || 0) + qty;
                });
                _b2bRepaintItems();
            })
            .catch(() => {});
    }
}

// The same pallet tag once the deal is being worked: priced, quoted, listed or
// done. It used to be its own document -- centred type on a fold line, no
// barcode -- which meant the pallet that had been scannable while it sat in
// holding stopped being scannable the moment someone priced it. Now it is the
// standard tag with a different band and a different bottom line.
function b2bPrintPickup() {
    const deal = _b2bModalDeal;
    if (!deal) return;
    if (!deal.ref) return alert('This deal has no reference yet.');
    // Where the goods are NOW: the listing store once one is set, otherwise
    // wherever they were priced. Those are the same place for every deal that
    // did not go through CORP, and where they differ the listing store is the
    // one the tag is standing in.
    const listing = !!deal.listing_store;
    _b2bOpenSheet(_b2bTagSheet({
        docTitle: `SKU ${deal.ref}`,
        band: `B2B ${_b2bIntake(deal).key === 'walkin' ? 'Intake' : 'Pickup'}`,
        ref: deal.ref,
        company: _b2bTagCompany(deal),
        meta: [
            [_b2bIntake(deal).was, deal.pickup_date ? _b2bDate(deal.pickup_date) : '—'],
            [listing ? 'Listing At' : 'Priced At', (listing ? deal.listing_store : deal.pricing_store) || 'Not yet assigned'],
            ['Stage', B2B_STAGE[deal.stage]?.label || deal.stage],
        ],
        contents: deal.pickup_desc || '',
        note: 'Every unit on this deal carries its own SKU label — this sheet identifies the '
            + 'pallet they came off. Look the reference up in Operations → Business-to-Business.',
    }), 'label');
}

// ============================================================================
// FEED REMINDER
// ---------------------------------------------------------------------------
// The QuickPortal feed reads its deadline cards off these hidden bubbles: the
// CSS hides them with visibility/opacity, never display, because `display` is
// the signal the feed uses to decide a reminder is live. Removing the element
// would silently kill the card, so it stays in the DOM and just goes invisible.

function _b2bBubbleEl() {
    let b = document.getElementById('b2bAlertBubble');
    if (b) return b;
    // Hangs off the same parent as the shared claim bubble so it inherits the
    // header's stacking context, like the aging bubble does.
    const claim = document.getElementById('claimAlertBubble');
    if (!claim || !claim.parentElement) return null;
    b = document.createElement('div');
    b.id = 'b2bAlertBubble';
    b.style.cssText = 'display:none; position:fixed; top:116px; right:24px; '
        + 'background:linear-gradient(135deg, #1f9d57, #178048); color:white; '
        + 'padding:11px 14px 11px 16px; border-radius:14px; align-items:flex-start; gap:8px; '
        + 'font-size:13px; box-shadow:0 10px 28px rgba(23,128,72,.38); '
        + 'max-width:min(380px, calc(100vw - 48px)); z-index:998;';
    b.innerHTML = `<span style="font-size:16px; flex-shrink:0; margin-top:2px;">📦</span>
        <span id="b2bAlertBubbleText" style="white-space:normal; overflow-y:auto; max-height:220px;"></span>
        <button onclick="closeB2BAlertBubble()" class="daily-bubble-close" title="Dismiss">
            <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
        </button>`;
    claim.parentElement.appendChild(b);
    return b;
}

function closeB2BAlertBubble() {
    const b = document.getElementById('b2bAlertBubble');
    if (b) b.style.display = 'none';
}

// Runs on every page, so it has to be cheap and quiet: one scoped read, and it
// bails immediately for anyone whose role has no B2B duties at all.
async function checkB2BReminders() {
    const role = _b2bRole();
    if (!B2B_CORP_ROLES.includes(role) && !B2B_STORE_ROLES.includes(role) && !_b2bIsEmployee() && !_b2bHasCorpDelegation()) return;
    const b = _b2bBubbleEl();
    if (!b) return;
    try {
        const deals = (await _b2bGet(`store=${encodeURIComponent(_b2bFetchScope())}&archive=0`))
            .map(_b2bShapeDeal).filter(_b2bInScope);
        const mine = deals.filter(_b2bActionFor);
        if (!mine.length) { b.style.display = 'none'; return; }

        // Lead with the oldest, since that's the one actually holding things up.
        const oldest = mine.reduce((a, d) => _b2bDaysIn(d) > _b2bDaysIn(a) ? d : a, mine[0]);
        const stage = B2B_STAGE[oldest.stage]?.label || oldest.stage;
        const t = document.getElementById('b2bAlertBubbleText');
        if (t) {
            const n = mine.length;
            t.innerHTML = `<b>B2B deals need you</b><br>${n} deal${n === 1 ? '' : 's'} waiting`
                + ` — oldest is ${escapeHtml(oldest.ref)} at ${escapeHtml(stage)}, ${_b2bDaysIn(oldest)}d in stage.`;
            // The feed prefers an authored one-liner over scraping the bubble.
            t.dataset.summary = `${n} deal${n === 1 ? '' : 's'} waiting · oldest ${oldest.ref} at ${stage}, ${_b2bDaysIn(oldest)}d`;
        }
        b.style.display = 'flex';
    } catch (_) {
        // a failed poll just leaves the bubble as it was
    }
}

// ============================================================================
// MODULE: CUSTOMER CALL BACKS (operations.html #ops-pane-callbacks)
// Entries live 30 days from date_of_call, then auto-archive (recoverable for
// 90 more days before purge — nightly `callbacks-daily-maintenance` pg_cron job).
// Backed by the `customer-callbacks` edge function / customer_callbacks table.
// Status changes are open to every store (the cross-store "we have this" signal);
// add/edit/delete/restore are store-scoped (MSM covers BAL+MPL, corp covers all).
// ============================================================================
const CB_CORP_ROLES = ['district manager', 'ceo', 'mocd'];   // may create/edit entries for any store
const CB_ACTIVE_DAYS  = 30;   // days an entry stays on the sheet
const CB_PURGE_DAYS   = 120;  // days from date_of_call until permanent deletion

let _cbCache = [];
let _cbView = null;           // 'mine' | 'all' | 'archived'
let _cbExpandedId = null;
let _cbEditingId = null;
let _cbLoading = false;

function _cbDaysAgo(n) {
    const d = new Date(); d.setDate(d.getDate() - n);
    return d.toISOString().slice(0, 10);
}

async function cbFetch(view, store) {
    const res = await fetch(`${CALLBACKS_URL}?view=${view === 'archived' ? 'archived' : 'active'}&store=${store}&v=${Date.now()}`);
    if (!res.ok) throw new Error('Fetch failed');
    return res.json();
}

async function cbPost(payload) {
    const res = await fetch(CALLBACKS_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({
            ...payload,
            user:  sessionStorage.getItem('speeksUserName')  || '',
            role:  (sessionStorage.getItem('speeksUserRole') || '').toLowerCase(),
            store: (sessionStorage.getItem('speeksUserStore') || '').toUpperCase(),
            multi: (typeof isMultiStoreManager === 'function' && isMultiStoreManager())
        })
    });
    const out = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(out.error || 'Request failed');
    return out;
}

// --- Helpers
// Edit/delete/restore: own store only (MSM covers both of theirs, corp covers all).
// Status changes are deliberately NOT gated — any store marking an entry Contacted
// is the cross-store "we've got this" signal, and the change is attributed below.
function cbCanModify(entry) {
    const role  = (sessionStorage.getItem('speeksUserRole')  || '').toLowerCase().trim();
    const store = (sessionStorage.getItem('speeksUserStore') || '').toUpperCase();
    if (CB_CORP_ROLES.includes(role) || store === 'ALL') return true;
    if (typeof isMultiStoreManager === 'function' && isMultiStoreManager()) return MULTISTORE_MANAGER_STORES.includes(entry.store);
    return entry.store === store;
}

// Stores this user may CREATE entries for: corp roles get all stores, the MSM
// gets both of their stores, everyone else is locked to their own (no picker).
function _cbAddStores() {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    if (CB_CORP_ROLES.includes(role)) return STORE_CODES;
    if (typeof isMultiStoreManager === 'function' && isMultiStoreManager()) return [...MULTISTORE_MANAGER_STORES];
    return null;
}

function _cbHomeStore() {
    const s = (sessionStorage.getItem('speeksUserStore') || '').toUpperCase();
    return STORE_CODES.includes(s) ? s : 'OVL';
}

function cbDaysInfo(entry) {
    const called = new Date(entry.date_of_call + 'T00:00:00');
    const today  = new Date(); today.setHours(0, 0, 0, 0);
    const since  = Math.floor((today - called) / 86400000);
    return { since, daysLeft: CB_ACTIVE_DAYS - since, purgeLeft: CB_PURGE_DAYS - since };
}

function cbFormatPhone(p) {
    const d = String(p || '').replace(/\D/g, '');
    if (d.length === 10) return `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`;
    return p || '';
}

// Phone inputs: digits only, max 10. A pasted 11-digit number starting with the
// US country code drops the leading 1 instead of losing the final real digit.
function cbPhoneInput(el) {
    let d = el.value.replace(/\D/g, '');
    if (d.length > 10 && d[0] === '1') d = d.slice(1);
    el.value = d.slice(0, 10);
}

function _cbShortDate(iso) {
    const d = new Date(iso + 'T00:00:00');
    return isNaN(d) ? '' : d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

function _cbDaysBadge(entry) {
    const { daysLeft, purgeLeft } = cbDaysInfo(entry);
    if (_cbView === 'archived' || entry.archived_at || daysLeft <= 0) {
        return `<span class="cb-days cb-days-archived">purges in ${Math.max(purgeLeft, 0)}d</span>`;
    }
    const cls = daysLeft <= 7 ? 'cb-days-urgent' : daysLeft <= 14 ? 'cb-days-warn' : 'cb-days-ok';
    return `<span class="cb-days ${cls}">${daysLeft}d left</span>`;
}

const CB_STATUS_META = {
    open:      { label: 'Open',      next: 'contacted' },
    contacted: { label: 'Contacted', next: 'completed' },
    completed: { label: 'Completed', next: 'open' }
};

// Calm SVG line icons (Feather) — replace the old emoji in the table markup so
// Call Backs matches the Action-Menu aesthetic. Styling comes from `.cb-panel svg`.
const CB_ICONS = {
    plus:    '<svg viewBox="0 0 24 24"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>',
    note:    '<svg viewBox="0 0 24 24"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>',
    edit:    '<svg viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 0 1 3 3L12 15l-4 1 1-4z"/></svg>',
    trash:   '<svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>',
    restore: '<svg viewBox="0 0 24 24"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>',
    save:    '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>',
    cancel:  '<svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>'
};

function _cbIsCorpRole() {
    return CB_CORP_ROLES.includes((sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim());
}

// --- Load & render
async function cbLoad() {
    // Corp roles (DM/CEO/MOCD) watch the whole district — no "My Store" view;
    // they land on All Stores and narrow with the store filter instead.
    if (_cbView === null) _cbView = _cbIsCorpRole() ? 'all' : 'mine';
    _cbSyncControls();   // highlight the right view button before the fetch resolves
    if (_cbLoading) return;
    _cbLoading = true;
    const body = document.getElementById('cbBody');
    if (body && !_cbCache.length) body.innerHTML = '<div class="status-message">Loading Call Backs…</div>';
    try {
        // Fetch everything once; view filtering happens client-side in cbRender.
        _cbCache = await cbFetch(_cbView === 'archived' ? 'archived' : 'active', 'ALL');
        cbRender();
    } catch (e) {
        // Only surface the error when there's nothing on screen — a failed
        // background refresh keeps showing the last good data instead.
        if (body && !_cbCache.length) body.innerHTML = '<div class="status-message">Could not load call backs. Try again in a minute.</div>';
    } finally {
        _cbLoading = false;
    }
}

function cbSetView(view) {
    if (_cbView === view) return;
    _cbView = view;
    _cbExpandedId = null;
    _cbEditingId = null;
    cbLoad();
}

function _cbSyncControls() {
    ['mine', 'all', 'archived'].forEach(v => {
        const btn = document.getElementById('cbView' + v.charAt(0).toUpperCase() + v.slice(1) + 'Btn');
        if (btn) btn.classList.toggle('active', _cbView === v);
    });
    // (The My Store button itself is role-gated in the HTML — applyRoleBasedUI
    // hides it for corp roles before first paint, so no JS display toggling here.)
    const filter = document.getElementById('cbStoreFilter');
    if (filter) filter.style.display = (_cbView === 'mine') ? 'none' : '';
}

function _cbVisibleEntries() {
    const filter = document.getElementById('cbStoreFilter');
    const filterStore = (_cbView === 'mine') ? _cbHomeStore() : (filter ? filter.value : 'ALL');
    const showCompleted = document.getElementById('cbShowCompleted')?.checked;
    return _cbCache
        .filter(e => filterStore === 'ALL' || e.store === filterStore)
        .filter(e => _cbView === 'archived' || showCompleted || e.status !== 'completed')
        .sort((a, b) => (b.date_of_call || '').localeCompare(a.date_of_call || ''));
}

function cbRender() {
    const body = document.getElementById('cbBody');
    if (!body) return;
    _cbSyncControls();
    const entries = _cbVisibleEntries();

    const filterEl = document.getElementById('cbStoreFilter');
    const scopeStore = (_cbView === 'mine') ? _cbHomeStore() : (filterEl ? filterEl.value : 'ALL');
    const scoped = _cbCache.filter(e => scopeStore === 'ALL' || e.store === scopeStore);
    const open = scoped.filter(e => e.status !== 'completed' && !e.archived_at).length;
    const expiring = scoped.filter(e => { const d = cbDaysInfo(e).daysLeft; return e.status !== 'completed' && !e.archived_at && d > 0 && d <= 7; }).length;
    const sub = document.getElementById('cbSubtitle');
    if (sub) sub.textContent = _cbView === 'archived'
        ? `${entries.length} archived`
        : `${open} open${expiring ? ` · ${expiring} expiring soon` : ''}`;

    let html = '';
    if (_cbView !== 'archived') html += _cbQuickAddHtml();

    if (!entries.length) {
        const msgs = {
            mine:     'No call backs yet. When a customer wants something you don\'t have, log it above ↑',
            all:      'No open call backs across stores.',
            archived: 'Nothing archived in the last 90 days.'
        };
        html += `<div class="cb-empty">${msgs[_cbView]}</div>`;
        body.innerHTML = html;
        return;
    }

    const showStore = _cbView !== 'mine';
    html += `<table class="cb-table"><thead><tr>
        ${showStore ? '<th class="cb-col-store">Store</th>' : ''}
        <th class="cb-col-customer">Customer</th><th class="cb-col-phone">Phone</th><th class="cb-col-item">Item Wanted</th>
        <th class="cb-col-status">Status</th><th class="cb-col-timer">Timer</th><th class="cb-col-notes">${CB_ICONS.note}</th><th class="cb-col-logged">Logged</th><th class="cb-col-actions"></th>
    </tr></thead><tbody>`;
    entries.forEach(e => { html += cbRowHtml(e, showStore); });
    html += '</tbody></table>';
    body.innerHTML = html;
}

function _cbQuickAddHtml() {
    const home = _cbHomeStore();
    const addStores = _cbAddStores();
    const dflt = addStores && addStores.includes(home) ? home : (addStores ? addStores[0] : home);
    const storePicker = addStores
        ? `<select id="cbAddStore" class="kpi-select cb-add-store">${addStores.map(s => `<option value="${s}" ${s === dflt ? 'selected' : ''}>${s}</option>`).join('')}</select>`
        : '';
    return `<div class="cb-quickadd">
        ${storePicker}
        <input type="text" id="cbAddName"  placeholder="Customer name" onkeydown="if(event.key==='Enter')cbQuickAdd()">
        <input type="tel"  id="cbAddPhone" placeholder="Phone" inputmode="numeric" oninput="cbPhoneInput(this)" onkeydown="if(event.key==='Enter')cbQuickAdd()">
        <input type="text" id="cbAddItem"  placeholder="Item they're looking for" class="cb-add-item" onkeydown="if(event.key==='Enter')cbQuickAdd()">
        <input type="text" id="cbAddNoteTxt" placeholder="Notes (optional)" onkeydown="if(event.key==='Enter')cbQuickAdd()">
        <button class="btn-primary cb-add-btn" onclick="cbQuickAdd()">${CB_ICONS.plus}Add</button>
    </div>`;
}

function cbRowHtml(e, showStore) {
    const canAct = cbCanModify(e);
    const meta = CB_STATUS_META[e.status] || CB_STATUS_META.open;
    const isArchived = _cbView === 'archived';
    const editing = _cbEditingId === e.id;
    const expanded = _cbExpandedId === e.id || editing;

    // Status is clickable for EVERYONE — another store marking Contacted is the
    // cross-store "we have this item" signal. The change is attributed under the chip.
    // The attribution line always renders (blank when unset) so row heights never shift.
    const statusBy = `<div class="cb-status-by">${(e.status !== 'open' && e.status_by) ? `${escapeHtml(e.status_by)} · ${escapeHtml(e.status_store || '')}` : '&nbsp;'}</div>`;
    const chip = isArchived
        ? `<span class="cb-chip cb-chip-expired">Expired</span>`
        : `<span class="cb-chip cb-chip-${e.status} cb-chip-clickable" onclick="event.stopPropagation();cbCycleStatus('${e.id}')" data-cb-tip="Click to mark ${CB_STATUS_META[meta.next].label}">${meta.label}</span>${statusBy}`;

    const phoneDigits = String(e.phone || '').replace(/\D/g, '');
    const phone = `<a class="cb-phone" href="tel:+1${phoneDigits}" onclick="event.stopPropagation()">${escapeHtml(cbFormatPhone(e.phone))}</a>`;

    let actions = '';
    if (canAct && !editing) {
        actions = isArchived
            ? `<button class="cb-icon-btn" data-cb-tip="Restore to active" onclick="event.stopPropagation();cbRestoreEntry('${e.id}')">${CB_ICONS.restore}</button>`
            : `<button class="cb-icon-btn" data-cb-tip="Edit" onclick="event.stopPropagation();cbEditEntry('${e.id}')">${CB_ICONS.edit}</button>`;
        actions += `<button class="cb-icon-btn cb-btn-danger" data-cb-tip="Delete" onclick="event.stopPropagation();cbDeleteEntry('${e.id}')">${CB_ICONS.trash}</button>`;
    }

    let row;
    if (editing) {
        row = `<tr class="cb-row cb-row-editing" data-id="${e.id}">
            ${showStore ? `<td class="cb-col-store">${escapeHtml(e.store)}</td>` : ''}
            <td><input class="cb-edit-input" id="cbEditName" value="${escapeHtml(e.customer_name)}"></td>
            <td><input class="cb-edit-input" id="cbEditPhone" type="tel" inputmode="numeric" oninput="cbPhoneInput(this)" value="${escapeHtml(String(e.phone || '').replace(/\D/g, '').slice(0, 10))}"></td>
            <td class="cb-col-item"><input class="cb-edit-input" id="cbEditItem" value="${escapeHtml(e.item)}"></td>
            <td class="cb-cell-status">${chip}</td>
            <td class="cb-cell-timer"><input class="cb-edit-input cb-edit-date" id="cbEditDate" type="date" value="${e.date_of_call}" data-cb-tip="Date of call (resets the 30-day timer)"></td>
            <td class="cb-col-notes"></td>
            <td class="cb-logged"></td>
            <td class="cb-col-actions">
                <button class="cb-icon-btn cb-btn-save" data-cb-tip="Save" onclick="event.stopPropagation();cbSaveEdit('${e.id}')">${CB_ICONS.save}</button>
                <button class="cb-icon-btn cb-btn-danger" data-cb-tip="Cancel" onclick="event.stopPropagation();cbCancelEdit()">${CB_ICONS.cancel}</button>
            </td>
        </tr>`;
    } else {
        row = `<tr class="cb-row ${expanded ? 'cb-row-open' : ''} ${e.status === 'completed' ? 'cb-row-done' : ''}" data-id="${e.id}" onclick="cbToggleRow('${e.id}')">
            ${showStore ? `<td class="cb-col-store">${escapeHtml(e.store)}</td>` : ''}
            <td class="cb-customer">${escapeHtml(e.customer_name)}</td>
            <td>${phone}</td>
            <td class="cb-col-item cb-item">${escapeHtml(e.item)}</td>
            <td class="cb-cell-status">${chip}</td>
            <td class="cb-cell-timer">${_cbDaysBadge(e)}</td>
            <td class="cb-col-notes">${e.notes.length ? `<span class="cb-note-count">${CB_ICONS.note}${e.notes.length}</span>` : ''}</td>
            <td class="cb-logged"><span class="cb-logged-date">${_cbShortDate(e.date_of_call)}</span><span class="cb-logged-by">${escapeHtml(e.created_by)}</span></td>
            <td class="cb-col-actions">${actions}</td>
        </tr>`;
    }

    if (expanded && !editing) {
        const noteItems = e.notes.map(n =>
            `<div class="cb-note">${escapeHtml(n.text)} <span class="cb-note-meta">— ${escapeHtml(n.user)} (${escapeHtml(n.store)}) · ${_cbShortDate(n.at)}</span></div>`
        ).join('') || '<div class="cb-note cb-note-none">No notes yet.</div>';
        row += `<tr class="cb-row-detail"><td colspan="${showStore ? 9 : 8}">
            <div class="cb-notes-thread">${noteItems}</div>
            <div class="cb-note-add">
                <input type="text" class="cb-note-input" id="cbNoteInput-${e.id}" placeholder="Details about what they're looking for — condition, budget, timing…"
                       onclick="event.stopPropagation()" onkeydown="if(event.key==='Enter')cbAddNote('${e.id}')">
                <button class="btn-secondary cb-note-btn" onclick="event.stopPropagation();cbAddNote('${e.id}')">Add note</button>
            </div>
        </td></tr>`;
    }
    return row;
}

// --- Actions (optimistic: mutate cache, render, POST in background)
function cbToggleRow(id) {
    if (_cbEditingId) return;
    _cbExpandedId = (_cbExpandedId === id) ? null : id;
    cbRender();
}

async function cbQuickAdd() {
    const name  = document.getElementById('cbAddName')?.value.trim();
    const phone = (document.getElementById('cbAddPhone')?.value || '').replace(/\D/g, '');
    const item  = document.getElementById('cbAddItem')?.value.trim();
    const note  = document.getElementById('cbAddNoteTxt')?.value.trim();
    if (!name || !phone || !item) { alert('Customer name, phone, and item are required.'); return; }
    if (phone.length !== 10) { alert('Phone number must be exactly 10 digits.'); return; }

    const store = document.getElementById('cbAddStore')?.value || _cbHomeStore();
    const user  = sessionStorage.getItem('speeksUserName') || 'Unknown';
    const entry = {
        id: 'tmp-' + Date.now(), store, customer_name: name, phone, item,
        status: 'open', date_of_call: _cbDaysAgo(0), created_by: user,
        archived_at: null,
        notes: note ? [{ text: note, user, store, at: _cbDaysAgo(0) }] : []
    };
    _cbCache.unshift(entry);
    cbRender();
    document.getElementById('cbAddName')?.focus();
    try {
        const out = await cbPost({ action: 'add', entry: { store, customer_name: name, phone, item, note: note || null, created_by: user } });
        // Reconcile the optimistic row with the server's (real uuid, server-side
        // defaults) — row onclick handlers embed the id, so re-render after.
        if (out.entry) { Object.assign(entry, out.entry); cbRender(); }
    } catch (e) {
        _cbCache = _cbCache.filter(x => x.id !== entry.id);
        cbRender();
        alert('Could not save the call back: ' + e.message);
    }
}

function cbCycleStatus(id) {
    const e = _cbCache.find(x => x.id === id);
    if (!e) return;
    e.status = (CB_STATUS_META[e.status] || CB_STATUS_META.open).next;
    e.status_by = sessionStorage.getItem('speeksUserName') || 'Unknown';
    e.status_store = (sessionStorage.getItem('speeksUserStore') || '').toUpperCase();
    cbRender();
    cbPost({ action: 'status', id, status: e.status, status_by: e.status_by, status_store: e.status_store }).catch(() => cbLoad());
}

function cbAddNote(id) {
    const input = document.getElementById('cbNoteInput-' + id);
    const text = input?.value.trim();
    if (!text) return;
    const e = _cbCache.find(x => x.id === id);
    if (!e) return;
    const note = {
        text,
        user:  sessionStorage.getItem('speeksUserName') || 'Unknown',
        store: (sessionStorage.getItem('speeksUserStore') || '').toUpperCase(),
        at: _cbDaysAgo(0)
    };
    e.notes.push(note);
    cbRender();
    cbPost({ action: 'note', id, note }).catch(() => cbLoad());
}

function cbEditEntry(id) {
    _cbEditingId = id;
    _cbExpandedId = null;
    cbRender();
}

function cbCancelEdit() {
    _cbEditingId = null;
    cbRender();
}

function cbSaveEdit(id) {
    const e = _cbCache.find(x => x.id === id);
    if (!e) return;
    const editedPhone = (document.getElementById('cbEditPhone')?.value || '').replace(/\D/g, '');
    if (editedPhone && editedPhone.length !== 10) { alert('Phone number must be exactly 10 digits.'); return; }
    const fields = {
        customer_name: document.getElementById('cbEditName')?.value.trim()  || e.customer_name,
        phone:         editedPhone || e.phone,
        item:          document.getElementById('cbEditItem')?.value.trim()  || e.item,
        date_of_call:  document.getElementById('cbEditDate')?.value         || e.date_of_call
    };
    Object.assign(e, fields);
    _cbEditingId = null;
    cbRender();
    cbPost({ action: 'edit', id, fields }).catch(() => cbLoad());
}

function cbDeleteEntry(id) {
    const e = _cbCache.find(x => x.id === id);
    if (!e) return;
    if (!confirm(`Delete the call back for ${e.customer_name}? This can't be undone.`)) return;
    _cbCache = _cbCache.filter(x => x.id !== id);
    cbRender();
    cbPost({ action: 'delete', id }).catch(() => cbLoad());
}

function cbRestoreEntry(id) {
    const e = _cbCache.find(x => x.id === id);
    if (!e) return;
    e.archived_at = null;
    e.date_of_call = _cbDaysAgo(0);   // restart the 30-day timer
    e.status = 'open';
    _cbCache = _cbCache.filter(x => x.id !== id);   // leaves the archived view
    cbRender();
    cbPost({ action: 'restore', id }).catch(() => cbLoad());
}

// ============================================================================
// 23. MODULE: ROLE-BASED UI & INITIALIZATION
// ============================================================================

// Split out of applyRoleBasedUI so the shop-floor board can greet its user
// without running the rest of it — that function ends by kicking off a
// feature-overrides fetch, and a page with no data-feature elements has nothing
// to gate. One writer, so the wording can't drift between the two callers.
function _setUserGreeting() {
    const el = document.getElementById('userGreeting');
    if (el) el.innerText = `Welcome ${sessionStorage.getItem('speeksUserName') || 'User'}!`;
}

// The one breakpoint the JS has to agree with the stylesheet about. Must stay in
// step with the MOBILE LAYER in styles.css, where <=900px is the compact build.
function _isMobileLayout() {
    try { return window.matchMedia("(max-width: 900px)").matches; } catch (_) { return false; }
}

// Rotating a tablet or dragging a window across 900px changes which surfaces
// belong on screen, and the inline display written by applyRoleBasedUI does not
// re-evaluate on its own. Re-run it on the crossing, not on every resize tick.
try {
    window.matchMedia("(max-width: 900px)").addEventListener("change", function () {
        if (document.body.classList.contains("is-authenticated")) applyRoleBasedUI();
    });
} catch (_) { /* older browsers: the initial pass still applies */ }

function applyRoleBasedUI() {
    const userRole = sessionStorage.getItem('speeksUserRole') || 'employee';
    const userStore = sessionStorage.getItem('speeksUserStore') || 'ALL';
    const userName = sessionStorage.getItem('speeksUserName') || 'User';

    _setUserGreeting();

    const firstName = userName.split(' ')[0];
    // (Analytics Workspace header is a static V4 hero in workspace.html now —
    //  no per-user title injection, matching the Operations / Processes pages.)

    const userRoleClass = `role-${userRole.toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, '-')}`;
    const userStoreClass = `store-${userStore.toLowerCase()}`;

    document.querySelectorAll('.dynamic-module-flex, .dynamic-module-block, .dynamic-module').forEach(module => {
        const classes = Array.from(module.classList);
        const requiredStores = classes.filter(c => c.startsWith('store-'));

        const passesRole = _passesRoleClasses(classes, userRoleClass);
        const passesStore = requiredStores.length === 0 || requiredStores.includes(userStoreClass);

        let visible = passesRole && passesStore;
        // Feature Access override (DM/CEO-managed, feature_overrides table):
        // a user-level override beats a role-level override beats the default above.
        const featureKey = module.getAttribute('data-feature');
        if (featureKey) {
            const ov = _featureOverrideFor(featureKey, userRoleClass, userName);
            // mark cards an override removed (vs. hidden by design) so the
            // dashboard rows know when to rebalance the remaining cards
            if (ov === false && visible) module.setAttribute('data-fa-hidden', '1');
            else module.removeAttribute('data-fa-hidden');
            if (ov !== null) visible = ov;
        }

        // A surface cut from the phone build stays cut even when the role check
        // passes. This CANNOT be done in CSS: the branch below writes an inline
        // display with !important, which outranks every stylesheet rule — so
        // [data-mobile="hide"] silently lost to it on all 11 role-gated elements
        // that were supposed to be hidden (found with scripts/mobile-check.js).
        if (visible && module.getAttribute('data-mobile') === 'hide' && _isMobileLayout()) {
            visible = false;
        }
        if (visible) {
            let displayType = module.classList.contains('dynamic-module-flex') ? 'flex' : 'block';
            module.style.setProperty('display', displayType, 'important');
        } else {
            module.style.setProperty('display', 'none', 'important');
        }
    });

    // Feature overrides on plain (non role-gated) elements — e.g. individual
    // hotbar links, which normally just inherit their bar's visibility.
    _applyFeatureOverridesToPlainEls(userRoleClass, userName);
    // Section nav links (Workspace, Operations) have no toggle of their own —
    // they're derived: show whenever the user can see at least one sub-tab
    // inside, so granting just one tab (e.g. Variance Replies) reveals the
    // section with only that tab in it.
    _applySectionNavVisibility(userRoleClass, userName);
    // Force-enabled hotbar links from bars this user doesn't normally see:
    // a fully-enabled bar shows up as itself; partial picks are collected into
    // a synthetic EXTRAS bar so one borrowed link never drags in a whole
    // foreign hotbar.
    _syncHotbarExtras(userRoleClass, userName);
    // Combined widgets (manager Command Center, employee Buying/KPIs): after per-tab
    // feature overrides, hide a widget whose every tab is off and keep a valid tab active.
    _reconcileCommandWidgets();
    // Dashboard card rows where an override hid a card rebalance so the
    // remaining cards fill the row instead of leaving an empty slot.
    _rebalanceDashboardRows();
    // Tools button / group visibility follows what's actually visible inside
    // the panel, so overrides can add or remove tools for any role without the
    // static role-class unions drifting out of sync.
    _syncToolsPanelChrome();
    // Search chip in the top bar + the pinned row in the tools panel. Runs after
    // the panel chrome so the row lands in a panel that's finished resolving.
    try { _jumpSync(); } catch (_) { /* never let search break the page render */ }
    // Only matters when one user holds both Preferred Purchases entries; the
    // labels are otherwise already correct in the markup.
    try { _plSyncToolLabels(); } catch (_) { /* module may not be loaded on this page */ }
    // Role gating decides how many action items are visible, so square the deck
    // up right after it rather than waiting for the feed's next render.
    try { _samSyncRailFill(); } catch (_) { /* menu not on this page */ }
    // First call kicks off a background refresh of the overrides from Supabase
    // (cached copy applies instantly; a change re-runs this function once).
    _kickFeatureOverridesRefresh();

    // Render/refresh the SPEEKS Action Menu deck now the role is known.
    try { if (typeof samInit === 'function') samInit(); } catch (e) { console.warn('Action Menu init failed:', e); }

    if (userRole === 'employee' || userRole === 'assistant manager') {
        document.querySelectorAll('.manager-only').forEach(el => el.style.setProperty('display', 'none', 'important'));
    }

    // ASM uses the same dashboard layout as the team-member view (no special grid).

    if (userStore !== 'ALL') {
        ['kpiStoreSelect', 'am-kpiStoreSelect', 'weeklyKpiStoreSelect', 'bsStoreSelect', 'vw-primary', 'dmChartStoreSelector', 'mbStoreSelect'].forEach(id => {
            const dropdown = document.getElementById(id);
            if (dropdown && Array.from(dropdown.options).some(opt => opt.value === userStore)) {
                dropdown.value = userStore;
            }
        });
    }

    initMultiStoreSwitcher();
}

// ===== MULTI-STORE MANAGER: global store switcher =====
// A Multi-Store Manager (e.g. Joseph Ortega) oversees more than one store and toggles
// which one the whole dashboard is scoped to. The first entry is the default (and is
// set as their `store` at login). Toggling re-points the session store and reloads, so
// every widget re-scopes through the normal load path. Single-store users never reach
// this code, so their dashboards/feeds are unaffected.
const MULTISTORE_MANAGER_STORES = ['BAL', 'MPL'];

// True if a directory user belongs to a given store's roster. A Multi-Store Manager
// belongs to EVERY store they manage (not just their home store), so they're included
// anywhere a regular store manager would be — variance, listing-goals roster, etc.
// "Is this person part of this store's team?" — every caller is building a staff
// roster (listing goals, the target ladder, the variance employee list), which is
// why the Store role is turned away here rather than in each of them. A Store
// account has a store, but it is a TV on the wall: counted as staff it would ask
// the screen for a listing role every morning, and add a head to the roster that
// moves the weekly target a full ±20 listings.
function userInStore(user, storeCode) {
    if (String(user.role || '').toLowerCase().trim() === 'store') return false;
    const store = String(storeCode || '').toUpperCase();
    if (String(user.store || '').toUpperCase() === store) return true;
    return String(user.role || '').toLowerCase() === 'multi-store manager'
        && MULTISTORE_MANAGER_STORES.includes(store);
}

// Effective role is 'manager', so multi-store status is tracked via this flag (set at login).
function isMultiStoreManager() {
    return sessionStorage.getItem('speeksMultiStore') === 'true';
}

// The store a freshly-opened store-specific TOOL should default to for a
// Multi-Store Manager: the store whose dashboard they're currently on
// (speeksUserStore). Store tools used to default to the first store in the list
// (always BAL), so on the MPL dashboard they'd wrongly populate BAL. Callers keep
// the dropdown switchable — this only sets the INITIAL selection. Returns '' for
// everyone else, whose single store already wins, so callers can `|| fallback`.
function _msmDefaultStore() {
    if (!isMultiStoreManager()) return '';
    const s = (sessionStorage.getItem('speeksUserStore') || '').toUpperCase();
    return MULTISTORE_MANAGER_STORES.includes(s) ? s : '';
}

// One-time store override set by clicking a SINGLE-store MSM alert (e.g. an MPL-only
// variance row while on the BAL dashboard): the tool opens on that store instead of
// the active dashboard, WITHOUT switching the dashboard. Stored in sessionStorage so
// it survives the navigation to workspace.html, and consumed (cleared) on read so
// the next normal open reverts to the active-store default. A both-store alert sets
// nothing, so the active-store default applies. Returns '' for non-MSM users.
function _consumeMsmAlertStore() {
    const s = sessionStorage.getItem('speeksMsmToolStore');
    if (s) sessionStorage.removeItem('speeksMsmToolStore');
    // Validated against every store (not just the MSM's two) so a DM alert can also
    // route to a specific store that needs review, using the same override.
    const up = (s || '').toUpperCase();
    return STORE_CODES.includes(up) ? up : '';
}
// The store a store-specific tool should OPEN on for an MSM: a pending single-store
// alert override wins (cleared after use), else the active dashboard store.
function _msmToolStore() {
    return _consumeMsmAlertStore() || _msmDefaultStore();
}

function setMultiStore(store) {
    const next = String(store || '').toUpperCase();
    if (!next || !MULTISTORE_MANAGER_STORES.includes(next)) return;
    if (next === (sessionStorage.getItem('speeksUserStore') || '').toUpperCase()) return;
    sessionStorage.setItem('speeksUserStore', next);
    location.reload();
}

function initMultiStoreSwitcher() {
    const sw = document.querySelector('.msm-store-switch');
    if (!sw) return;
    if (!isMultiStoreManager()) { sw.style.display = 'none'; return; }
    const current = (sessionStorage.getItem('speeksUserStore') || MULTISTORE_MANAGER_STORES[0]).toUpperCase();
    // Segmented toggle instead of a native <select>: the OS-drawn option list
    // can't be styled to match the nav, and with only two stores a toggle is
    // one click instead of two. setMultiStore() still does the actual switch.
    sw.innerHTML = MULTISTORE_MANAGER_STORES.map(s =>
        `<button type="button" class="msm-seg${s === current ? ' active' : ''}" data-tip="Switch to ${s}" onclick="setMultiStore('${s}')">${s}</button>`
    ).join('');
    sw.style.display = 'flex';
}

function checkInstantNotifCache() {
    const currentUser = sessionStorage.getItem('speeksUserName');
    if (!currentUser) return;
    const cleanUser = String(currentUser).trim().toLowerCase();   // one key spelling everywhere

    const hasAnns   = localStorage.getItem('speeksUnreadAnnouncements_' + cleanUser) === 'true';
    const hasPatch  = localStorage.getItem('speeksUnseenPatchNotes_'     + cleanUser) === 'true';
    if (hasAnns || hasPatch) {
        const badge = document.getElementById('notifBadge');
        if (badge) { badge.style.display = 'block'; badge.classList.add('active'); }
    }
}

// Shows/hides the main bell badge based on BOTH unread announcements AND unseen patch notes
function updateMainBadge() {
    const currentUser = sessionStorage.getItem('speeksUserName');
    const cleanUser   = currentUser ? String(currentUser).trim().toLowerCase() : null;
    const hasAnns  = cleanUser && localStorage.getItem('speeksUnreadAnnouncements_' + cleanUser) === 'true';
    const hasPatch = cleanUser && localStorage.getItem('speeksUnseenPatchNotes_'     + cleanUser) === 'true';
    const show = hasAnns || hasPatch;
    const badge = document.getElementById('notifBadge');
    if (badge) { badge.style.display = show ? 'block' : 'none'; badge.classList.toggle('active', show); }
}

// Called after fetching patch notes — shows/hides the tab dot and main badge
function checkPatchNotesBadge() {
    if (!_latestPatchKey) return;
    const currentUser = sessionStorage.getItem('speeksUserName');
    const cleanUser   = currentUser ? String(currentUser).trim().toLowerCase() : null;
    const seen  = cleanUser ? localStorage.getItem('speeksPatchNotesSeen_' + cleanUser) : null;
    const isNew = seen !== _latestPatchKey;

    if (cleanUser) {
        if (isNew) localStorage.setItem('speeksUnseenPatchNotes_' + cleanUser, 'true');
        else        localStorage.removeItem('speeksUnseenPatchNotes_' + cleanUser);
    }
    const pnBadge = document.getElementById('patchNotesBadge');
    if (pnBadge) { pnBadge.style.display = isNew ? 'block' : 'none'; pnBadge.classList.toggle('active', isNew); }

    if (isNew) {
        const mainBadge = document.getElementById('notifBadge');
        if (mainBadge) { mainBadge.style.display = 'block'; mainBadge.classList.add('active'); }
    } else {
        updateMainBadge();
    }
    // Refresh the Action Menu feed so the compact "new patch notes" row appears/clears.
    try { if (typeof renderActionFeed === 'function') renderActionFeed(); } catch (_) {}
}

// Lightweight background fetch — just checks if there's a new patch notes version
async function checkForNewPatchNotes() {
    try {
        const data = await fetch(`${PATCH_NOTES_URL}?v=${Date.now()}`).then(r => r.json());
        if (!data.entries || !data.entries.length) return;
        const groups = buildPatchGroups(data.entries);
        if (groups.length > 0) {
            _latestPatchKey = groups[0].title + '|' + groups[0].date;

            // Restore read state from server in case browser data was cleared
            const currentUser = sessionStorage.getItem('speeksUserName');
            const cleanUser   = currentUser ? String(currentUser).trim().toLowerCase() : null;
            if (cleanUser) {
                try {
                    const readData = await fetch(`${PATCH_NOTES_URL}?action=getPatchRead&user=${encodeURIComponent(cleanUser)}&v=${Date.now()}`).then(r => r.json());
                    if (readData.lastSeenKey === _latestPatchKey) {
                        localStorage.setItem('speeksPatchNotesSeen_' + cleanUser, _latestPatchKey);
                        localStorage.removeItem('speeksUnseenPatchNotes_' + cleanUser);
                    }
                } catch (e) {}
            }

            checkPatchNotesBadge();
        }
    } catch (e) {}
}

function initDashboardData() { 
    // 1. Instantly check memory for the red dot before any servers are contacted
    checkInstantNotifCache();

    const runInit = () => {
        if (typeof initChecklists === 'function') initChecklists();
        renderMonthlyGoalsBanner();
        renderDistrictGoals();
        syncGoalsFromSheet();
        renderCompanyProjectsBanner();
        renderStoreInitiatives();
        renderDistrictCompanyProjects();
        renderDistrictInitiativesGrid();
        syncInitiativesFromSheet();

        // Re-sync announcements immediately after login so it knows who you are!
        setTimeout(loadCMS, 50);
        setTimeout(checkForNewPatchNotes, 800); // background check for new patch notes
        setTimeout(startReactionPolling, 3000);

        setTimeout(fetchHubData, 100);
        // Early, and NOT because a tab is open on it — no Command Center opens a tab
        // any more. It feeds three of the summary's seven cells, which is the first
        // thing on screen, so it is the one fetch whose delay is most visible.
        setTimeout(fetchLiveDashboard, 150);
        setTimeout(fetchVarianceData, 300);
        setTimeout(fetchWeeklyKPIs, 500);

        setTimeout(fetchScorecardData, 600);
        setTimeout(fetchAlertsData, 650);
        setTimeout(fetchMasterDistrictDashboard, 680);
        setTimeout(fetchKPIData, 700);
        setTimeout(fetchDistrictMonthlyKPIs, 750);
        setTimeout(fetchRecordsData, 800);
        setTimeout(() => { if (document.getElementById('mainKpiChart')) fetchChartData(currentTimeframe); }, 950);
        setTimeout(() => { if (document.getElementById('mbBody')) fetchMonthlyBrief(); }, 1000);
        setTimeout(fetchChampions, 850);
        setTimeout(fetchAwardsData, 900);
        setTimeout(fetchDmGoalsData, 1000);
        setTimeout(fetchDmAuditData, 1050);
        // Monthly goals are localStorage-backed and synced by the calls above this
        // block, so the rail only needs one nudge once they've landed.
        setTimeout(_dmxSyncRail, 1400);
        // Keep audit readiness live while the DM has the dashboard open. Gated on
        // the role now — fetchDmAuditData used to guard on its own dashboard
        // container, which no longer exists.
        if (!window._dmAuditSync) window._dmAuditSync = setInterval(() => {
            if (_dmxIsDistrict()) fetchDmAuditData();
        }, 60000);
        // SAFETY NET for the Command Center dots. Realtime (broadcast-as-ping,
        // see _RT_TOOL_CHECKS: scorecard/ebay/buying/goals) is the PRIMARY path —
        // it lights the pulsing dot the instant a write lands. This slow poll only
        // matters if the realtime socket never connects (CDN blocked, etc.); it
        // re-pulls the sources so a change still surfaces within the interval.
        if (!window._ccDataSync) window._ccDataSync = setInterval(() => {
            // One widget, so each source is polled only if ITS tab is actually
            // present for this user — a role without the Scorecard tab should not be
            // re-pulling the scorecard every ten minutes.
            const has = t => !!document.getElementById('cc-tab-' + t);
            if (has('buying') && typeof fetchHubData === 'function') fetchHubData();
            if (has('scorecard') && typeof fetchScorecardData === 'function') fetchScorecardData();
            if (has('ebay') && typeof fetchAlertsData === 'function') fetchAlertsData();
            if (has('kpis') && typeof fetchAndRenderEmployeeKPIs === 'function') fetchAndRenderEmployeeKPIs();
        }, 10 * 60 * 1000);
        // SAFETY NET for the Live Dashboard, same reasoning as above: realtime is the
        // real path. Skipped while the tab is in the background — a dashboard left open
        // on a back office monitor for a week should not spend a request every five
        // minutes on a panel nobody is looking at — and re-pulled the moment it comes
        // back to the foreground, so returning to the tab never shows a stale number.
        if (!window._lvSync) {
            window._lvSync = setInterval(() => {
                if (document.visibilityState === 'visible') fetchLiveDashboard();
            }, 5 * 60 * 1000);
            document.addEventListener('visibilitychange', () => {
                if (document.visibilityState === 'visible') fetchLiveDashboard();
            });
        }
        setTimeout(fetchAndRenderEmployeeGoals, 1100);
        setTimeout(fetchAndRenderEmployeeKPIs, 1200);
        setTimeout(fetchAndDisplayStoreComment, 1500);
        startStoreCommentPolling();
        // Both feed the SAME red bubble, so run them in sequence, not in parallel:
        // a DM/CEO-pushed reminder wins (it's personal + already states the aging
        // count); the generic aging alert only fires if no reminder claimed the
        // bubble. Awaiting avoids the login flicker of one overwriting the other.
        setTimeout(async () => { await checkClaimReminders(); checkAgingClaims(); checkAgingClaimsDM(); checkVarianceReminders(); checkVarianceDmReminders(); checkMarginReminders(); checkMarginDmReminders(); checkRecycleReminders(); checkAgingInvReminders(); checkAgingInvDmReminders(); checkKpiDueReminders(); checkPreferredReminders(); checkB2BReminders(); checkListingGoalsDailyReminder(); checkExpenseFileReminder(); startGpGoalReminder(); startDailyBriefReminder(); }, 1600);


        // Pre-load checklist in background so chip + glow appear without opening the panel
        const _clRole = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase();
        if (_clRole === 'manager' || _clRole === 'district manager' || _clRole === 'assistant manager') {
            setTimeout(_prefetchChecklistForChip, 1200);
        }
        // Pre-load the store-audit checklist for its chip (managers + ASMs, not DM)
        if (['manager', 'owner (manager)', 'assistant manager'].includes(_clRole)) {
            setTimeout(_prefetchAuditForChip, 1300);
        }


        if (typeof preloadAllStores === 'function') setTimeout(preloadAllStores, 4000);
        if (typeof initListingGoals === 'function') setTimeout(initListingGoals, 200);
    };

    if (typeof Chart === 'undefined') {
        const s1 = document.createElement('script'); 
        s1.src = 'https://cdn.jsdelivr.net/npm/chart.js';
        
        const s2 = document.createElement('script'); 
        s2.src = 'https://cdn.jsdelivr.net/npm/chartjs-plugin-datalabels@2.0.0';
        
        s1.onload = () => { 
            document.head.appendChild(s2); 
            s2.onload = runInit; 
        };
        document.head.appendChild(s1);
    } else {
        runInit();
    }
}

// --- INIT LISTENERS ---
document.addEventListener("DOMContentLoaded", () => {
    setTimeout(() => document.body.classList.remove('preload'), 150);

    if (localStorage.getItem('speeksSidebar') === 'collapsed') { 
        document.querySelector('.sidebar')?.classList.add('collapsed'); 
        document.querySelector('.main-content')?.classList.add('expanded'); 
        document.querySelector('.sidebar-toggle')?.classList.add('collapsed'); 
    }
    
    // Site-wide, except on the shop-floor board. A screen has no announcements to
    // read, no PIN pad to pre-load the user list for, and no idea box — and cms is
    // the very function whose polling had to be walked back once for egress.
    // Running these on five TVs around the clock is that bill again, for nothing.
    if (!_tvOnBoardPage()) {
        loadCMS();
        injectGlobalAuth();
        injectIdeaModal();
        startAuthFetch();
    }

    if (document.getElementById('kbBody')) loadHotkeys();
    if (document.getElementById('content-container') && document.getElementById('docSearch')) { 
        loadDocs(); 
        document.getElementById('docSearch').addEventListener('keyup', filterDocs); 
    }

    if (sessionStorage.getItem('speeksUnlocked') === 'true') {
        // A TV is left on for weeks and reloads on its own — power cut, browser
        // restart, someone's overnight update. Every one of those has to land back
        // on the board, not on a QuickPortal, so the gate runs on load and not
        // only at login. First thing inside the branch: everything below it is
        // page setup that a redirect makes pointless.
        if (_tvGate()) return;
        // Two pages are whole destinations rather than a tool inside one, so the
        // visit IS the usage signal. Recorded here — past the TV gate, inside the
        // signed-in branch — so a board and the login screen never count.
        _trackPageVisit();
        // …and the fact that they were here at all. The PIN path can't carry this
        // on its own: a tab that stays open never returns to it. See _usagePresence.
        _usagePresence();
        document.body.classList.add('is-authenticated');
        const authOverlay = document.getElementById('authOverlay');
        if (authOverlay) authOverlay.style.display = 'none';
        document.body.style.overflow = '';

        // Already on the board: it gets its own small init and nothing else.
        if (_tvOnBoardPage()) { initBoardPage(); return; }

        closeAllModals();
        applyRoleBasedUI();
        // Before anything can open a side panel: sets --panel-top so they hang
        // flush from the nav on every page, not just the dashboard.
        initLayoutSync();
        initDashboardData();
        initTicker();
        initWorkspace();
        initOperations();
        // A #jump=<feature> deep-link from the search box: land, then spotlight
        // the panel that was asked for.
        try { _jumpHandleHash(); } catch (_) { /* not fatal to the page */ }
        applyKpiReminder();
        // re-evaluate the weekly-KPI reminder window each minute so it appears/clears live
        setInterval(applyKpiReminder, 60000);
        if (document.getElementById('mainKpiChart')) syncAllData();
    } else {
        // sessionStorage dies with the browser process, so a TV that power-cycles
        // overnight wakes with no session, on the one page in the site with no PIN
        // pad of its own. It has to go find one.
        //
        // It always did — but only because injectGlobalAuth() put a hidden
        // #authOverlay on every page, which is the condition the line below tests.
        // The board no longer injects it (see the guard at the top of this
        // handler), so the board now has to say where it goes. _tvGate() bounces it
        // straight back here the moment the PIN is accepted.
        if (_tvOnBoardPage()) { window.location.replace('index.html'); return; }
        if (!window.location.href.includes('index.html') && document.getElementById('authOverlay')) {
            window.location.href = "index.html"; 
            return;
        }
        const authOverlay = document.getElementById('authOverlay');
        if (authOverlay) {
            authOverlay.style.display = 'flex'; 
            document.body.style.overflow = 'hidden'; 
            document.getElementById('pinInput')?.focus(); 
        }
    }
    
    ['kpiStoreSelect', 'am-kpiStoreSelect', 'weeklyKpiStoreSelect', 'vw-primary', 'vw-compare'].forEach(id => {
        document.getElementById(id)?.addEventListener('change', () => {
            if (id === 'kpiStoreSelect') {
                fetchKPIData(false);
            } else if (id === 'am-kpiStoreSelect') {
                const origStore = document.getElementById('kpiStoreSelect');
                if (origStore) origStore.value = document.getElementById('am-kpiStoreSelect').value;
                fetchKPIData(false);
            } else if (id === 'weeklyKpiStoreSelect') {
                fetchWeeklyKPIs();
            } else {
                renderVariance();
            }
        });
    });
    
});

// ============================================================================
// 23. CUSTOM TOOLTIP LOGIC
// ============================================================================
const customTooltip = document.createElement('div');
customTooltip.className = 'speeks-tooltip';
document.body.appendChild(customTooltip);

// When true the tooltip is pinned under a top-nav button (with a caret) rather
// than trailing the cursor — see _anchorTipBelow + the mousemove guard.
let _tipAnchored = false;
function _anchorTipBelow(el) {
    // Viewport coordinates throughout — the tooltip is position:fixed, so
    // getBoundingClientRect values are used as-is with no scroll offset.
    const r = el.getBoundingClientRect();
    const tw = customTooltip.offsetWidth;
    let x = r.left + r.width / 2 - tw / 2;
    x = Math.max(10, Math.min(x, window.innerWidth - tw - 10));
    customTooltip.style.left = x + 'px';
    customTooltip.style.top = (r.bottom + 10) + 'px';
}

// Place a trailing (non-anchored) tooltip at the cursor straight away, so it
// doesn't flash at wherever it was last shown before mousemove catches up.
function _tipPlaceAtCursor(e) {
    // Client (viewport) coordinates to match the fixed-position tooltip, so it
    // lands at the cursor whether or not the page is scroll-locked behind a modal.
    let x = e.clientX - customTooltip.offsetWidth - 15;
    if (x < 10) x = 10;
    let y = e.clientY + 15;
    if (y + customTooltip.offsetHeight > window.innerHeight - 20) {
        y = e.clientY - customTooltip.offsetHeight - 10;
    }
    customTooltip.style.left = x + 'px';
    customTooltip.style.top = y + 'px';
}

document.addEventListener('mouseover', function(e) {
    // Reset the anchored state each pass; the top-nav branch re-arms it below.
    customTooltip.classList.remove('anchored'); _tipAnchored = false;
    // Inside the redesigned tool modals (and the Tools side panel), upgrade any
    // native title="" tooltip to the white styled one: move it to data-tip (once)
    // so the branch below renders it, and drop title so the black OS box never
    // shows. Future re-renders recreate title and get re-upgraded on next hover.
    const titledInTool = e.target.closest('.modal-menu.manage-menu [title], .tools-side-panel [title]');
    if (titledInTool) {
        const t = titledInTool.getAttribute('title');
        if (t) { titledInTool.setAttribute('data-tip', t); titledInTool.removeAttribute('title'); }
    }
    // Generic styled tooltip: any element with data-tip gets the site tooltip
    // instead of the plain browser title box. Used by the Action Menu + panels.
    const genTip = e.target.closest('[data-tip]');
    if (genTip) {
        customTooltip.style.setProperty('--tip-color', 'var(--sage-professional)');
        customTooltip.innerHTML = `<span style="font-size: 12.5px; font-weight: 600; color: var(--slate-charcoal); white-space: normal;">${genTip.getAttribute('data-tip')}</span>`;
        customTooltip.classList.add('show');
        // Top-nav buttons: pin the tooltip beneath the button with a caret instead
        // of letting it trail the cursor (matches the Tools button / tab tooltips).
        if (genTip.closest('.top-nav')) { customTooltip.classList.add('anchored'); _tipAnchored = true; _anchorTipBelow(genTip); }
        else { _tipPlaceAtCursor(e); }
        return;
    }

    // Collapsed nav: when the nav shrinks to icons (.nav-compact hides the label),
    // hovering a page link shows its name in the same anchored/caret tooltip as the
    // right-side icons. Only fires while collapsed — the label speaks for itself
    // when it's visible.
    const navLink = e.target.closest('.nav-link');
    if (navLink && navLink.closest('.top-nav.nav-compact')) {
        const lbl = navLink.querySelector('span');
        const txt = lbl ? lbl.textContent.trim() : '';
        if (txt) {
            customTooltip.style.setProperty('--tip-color', 'var(--sage-professional)');
            customTooltip.innerHTML = `<span style="font-size: 12.5px; font-weight: 600; color: var(--slate-charcoal); white-space: normal;">${txt}</span>`;
            customTooltip.classList.add('show', 'anchored');
            _tipAnchored = true;
            _anchorTipBelow(navLink);
            return;
        }
    }

    // Call Backs sheet: any element carrying data-cb-tip gets the standard site tooltip
    const cbTip = e.target.closest('[data-cb-tip]');
    if (cbTip) {
        customTooltip.style.setProperty('--tip-color', 'var(--sage-professional)');
        customTooltip.innerHTML = `<strong style="display:block; color: var(--sage-professional); font-size: 13px; white-space: nowrap;">${cbTip.dataset.cbTip}</strong>`;
        customTooltip.classList.add('show');
        return;
    }

    const infoI = e.target.closest('.goals-info-i');
    if (infoI && infoI.dataset.tipTitle) {
        customTooltip.style.setProperty('--tip-color', 'var(--sage-professional)');
        customTooltip.innerHTML = `
            <strong style="display:block; margin-bottom: 6px; color: var(--sage-professional); font-size: 13px;">${infoI.dataset.tipTitle}</strong>
            ${infoI.dataset.tipDesc ? `<span style="font-size: 12px; color: var(--slate-charcoal); line-height: 1.5;">${infoI.dataset.tipDesc}</span>` : ''}`;
        customTooltip.classList.add('show');
        return;
    }

    const awardI = e.target.closest('.award-info-btn');
    if (awardI) {
        const wrap = awardI.closest('.aw') || awardI.closest('.award-card-trophy-wrap');
        const nameEl = wrap ? wrap.querySelector('.aw-name, .award-card-name') : null;
        const title = nameEl ? nameEl.innerText.replace(/\s+/g, ' ').trim() : 'Award';
        customTooltip.style.setProperty('--tip-color', 'var(--sage-professional)');
        customTooltip.innerHTML = `
            <strong style="display:block; margin-bottom: 6px; color: var(--sage-professional); font-size: 13px;">${title}</strong>
            ${awardI.dataset.desc ? `<span style="font-size: 12px; color: var(--slate-charcoal); line-height: 1.5;">${awardI.dataset.desc}</span>` : ''}`;
        customTooltip.classList.add('show');
        return;
    }

    const goalMini = e.target.closest('.dg-goal-mini');
    if (goalMini) {
        const title = goalMini.dataset.goalTitle;
        const desc = goalMini.dataset.goalDesc;
        if (title) {
            customTooltip.style.setProperty('--tip-color', 'var(--sage-professional)');
            customTooltip.innerHTML = `
                <strong style="display:block; margin-bottom: 6px; color: var(--sage-professional); font-size: 13px;">${title}</strong>
                ${desc ? `<span style="font-size: 12px; color: var(--slate-charcoal); line-height: 1.5;">${desc}</span>` : ''}`;
            customTooltip.classList.add('show');
            return;
        }
    }

    // Goal / initiative hover text — rendered in the redesigned clean tooltip.
    const panelItem = e.target.closest('.cpb-project-item, .mgb-goal-item');
    if (panelItem) {
        const titleEl = panelItem.querySelector('.mgb-goal-title');
        const descEl  = panelItem.querySelector('.mgb-goal-desc');
        const titleText = titleEl ? titleEl.innerText.trim() : '';
        const descText  = descEl  ? descEl.innerText.trim()  : '';
        if (titleText || descText) {
            customTooltip.innerHTML = `
                <strong style="display:block; font-size: 12.5px; color: var(--slate-charcoal);">${titleText}</strong>
                ${descText ? `<span style="display:block; margin-top: 4px; font-size: 12px; color: #647082; line-height: 1.45;">${descText}</span>` : ''}`;
            customTooltip.classList.add('show');
            return;
        }
    }

    const card = e.target.closest('.doc-card');

    if (card) {
        const titleEl = card.querySelector('.doc-title');
        const descEl = card.querySelector('.doc-desc');

        if (titleEl && descEl) {
            const isTitleCut = titleEl.scrollWidth > titleEl.clientWidth;
            const isDescCut = descEl.scrollHeight > descEl.clientHeight;

            if (isTitleCut || isDescCut) {
                customTooltip.innerHTML = `
                    <strong style="display:block; margin-bottom: 6px; color: var(--sage-professional); font-size: 14px; white-space: nowrap;">
                        ${titleEl.innerText.trim()}
                    </strong>
                    <span style="font-size: 12px; color: var(--slate-charcoal); line-height: 1.4;">
                        ${descEl.innerText.trim()}
                    </span>`;
                customTooltip.classList.add('show');
                return;
            }
        }
    }
    customTooltip.classList.remove('show');
});

document.addEventListener('mousemove', function(e) {
    if (_tipAnchored) return;   // pinned under a nav button — don't trail the cursor
    if (customTooltip.classList.contains('show')) {
        // Client coords — the tooltip is position:fixed (see _tipPlaceAtCursor).
        let x = e.clientX - customTooltip.offsetWidth - 15;
        let y = e.clientY + 15;

        if (x < 10) x = 10;
        if (y + customTooltip.offsetHeight > window.innerHeight - 20) {
            y = e.clientY - customTooltip.offsetHeight - 10;
        }

        customTooltip.style.left = x + 'px';
        customTooltip.style.top = y + 'px';
    }
});

document.addEventListener('mouseout', function(e) {
    if (e.target.closest('.doc-card') || e.target.closest('.dg-goal-mini')) {
        customTooltip.classList.remove('show');
    }
});

window.addEventListener('scroll', function() {
    customTooltip.classList.remove('show');
}, { passive: true });

// ============================================================================
// 24. ZERO-FLICKER SPA ROUTER
// ============================================================================
document.addEventListener('click', async (e) => {
    const link = e.target.closest('.nav-link'); 
    
    if (link && link.href && link.href.startsWith(window.location.origin) && !link.href.includes('#')) {
        e.preventDefault(); 
        
        const targetUrl = link.href;
        if (targetUrl === window.location.href) return; 
        
        try {
            const response = await fetch(targetUrl);
            const html = await response.text();
            
            const parser = new DOMParser();
            const newDoc = parser.parseFromString(html, 'text/html');
            
            const currentMain = document.querySelector('.main-content');
            const newMain = newDoc.querySelector('.main-content');
            
            if (currentMain && newMain) {
                currentMain.innerHTML = newMain.innerHTML;
            }

            // This swap only replaces .main-content, so the SPEEKS Tools chrome
            // (button, side panel, tool modals) — which lives OUTSIDE .main-content —
            // would otherwise stay frozen at whatever the first full page load had,
            // and any tool modal a page authored INSIDE .main-content would be wiped.
            // Sync it all from the fetched doc so every tool opens on every tab
            // without a hard refresh.
            const newBtn = newDoc.getElementById('toolsNavBtn');
            const curBtn = document.getElementById('toolsNavBtn');
            if (newBtn && curBtn) curBtn.className = newBtn.className;
            const newPanel = newDoc.getElementById('toolsSidePanel');
            const curPanel = document.getElementById('toolsSidePanel');
            if (newPanel && curPanel) {
                curPanel.className = newPanel.className;
                curPanel.innerHTML = newPanel.innerHTML;
            }
            // Pull in any modal/overlay the fetched page keeps outside .main-content
            // that the live DOM is now missing.
            const nMain = newDoc.querySelector('.main-content');
            newDoc.querySelectorAll('.modal-menu, .overlay').forEach(m => {
                if (m.id && (!nMain || !nMain.contains(m)) && !document.getElementById(m.id)) {
                    document.body.appendChild(document.importNode(m, true));
                }
            });
            // De-dupe: a modal authored inside .main-content on this page can now
            // coexist with a persistent copy carried over from the previous page.
            const _seenModalIds = new Set();
            document.querySelectorAll('.modal-menu, .overlay').forEach(el => {
                if (!el.id) return;
                if (_seenModalIds.has(el.id)) el.remove(); else _seenModalIds.add(el.id);
            });

            document.querySelectorAll('.nav-link').forEach(nav => nav.classList.remove('active'));
            const newActiveLink = Array.from(document.querySelectorAll('.nav-link')).find(n => n.href === targetUrl);
            if (newActiveLink) newActiveLink.classList.add('active');

            window.history.pushState({ path: targetUrl }, '', targetUrl);
            document.title = newDoc.title;

            applyRoleBasedUI();
            closeAllModals();

            // Start the new tab at the top. This swap replaces .main-content in
            // place rather than navigating, so the scroll offset carries over from
            // whatever you were reading on the previous tab — and because the new
            // page is a different length, you land somewhere arbitrary rather than
            // where you were. Has to come AFTER closeAllModals, which restores the
            // scroll position it pinned when a modal opened and would otherwise
            // undo this. Back/forward still restore position: popstate does a real
            // reload and the browser handles that.
            window.scrollTo(0, 0);
            document.documentElement.scrollTop = 0;

            if (targetUrl.includes('docs.html')) {
                if (typeof loadDocs === 'function') loadDocs();
                const docSearch = document.getElementById('docSearch');
                if (docSearch) docSearch.addEventListener('keyup', filterDocs);
            } else {
                setTimeout(() => {
                    if (typeof initDashboardData === 'function') initDashboardData();
                    if (typeof applyKpiReminder === 'function') applyKpiReminder();
                    if (document.querySelector('.ws-wrap') && typeof initWorkspace === 'function') initWorkspace();
                    if (document.querySelector('.ops-wrap') && typeof initOperations === 'function') initOperations();
                    if (document.getElementById('mainKpiChart') && typeof syncAllData === 'function') syncAllData();
                    if (document.getElementById('pane-records') && typeof fetchRecordsData === 'function') fetchRecordsData();
                    if (document.getElementById('listing-champions-body') && typeof fetchChampions === 'function') fetchChampions();
                }, 100);
            }

        } catch (err) {
            console.error("SPA Routing failed, falling back to hard load", err);
            window.location.href = targetUrl; 
        }
    }
});

window.addEventListener('popstate', () => {
    window.location.reload(); 
});

// ============================================================================
// 25. THE MISSING FUNCTIONS (CHARTS & MANAGER MODALS)
// ============================================================================

// --- CHART: RENDER KPI ---
function renderKpiChart(payload, metric) {
    if (!document.getElementById('mainKpiChart')) return;
    if (typeof Chart === 'undefined') {
        const loader = document.getElementById('chartLoading');
        if (loader) { loader.innerHTML = '<div class="status-message" style="color:var(--red-alert);">Chart.js Library Missing!</div>'; loader.style.display = 'flex'; }
        return;
    }
    if (!payload) return;

    // ── Metric config ────────────────────────────────────────────────────────
    const METRIC = {
        conversion: { field: 'customer_conversion_pct', moName: 'Customer Conversion %', unit: '%',  isPct: true  },
        margin:     { field: 'gross_margin_pct',         moName: 'Gross Margin %',         unit: '%',  isPct: true  },
        nodeals:    { field: 'no_deal_count',             moName: 'No Deal Count',           unit: '',   isPct: false },
        time:       { field: 'avg_transaction_time',      moName: 'Avg Transaction Time',    unit: ' min',isPct: false },
    };
    const mc = METRIC[metric] || METRIC.conversion;
    const { field, unit, isPct } = mc;

    const STORE_COLORS = { OVL:'#7c6fd6', LEE:'#4e90cf', WSP:'#2ea36a', MPL:'#d99f43', BAL:'#d9776a' };
    const EMP_COLORS   = ['#a855f7','#3b82f6','#22c55e','#f97316','#ef4444','#14b8a6','#eab308','#ec4899'];

    const dmDropdown = document.getElementById('dmChartStoreSelector');
    if (dmDropdown) dmDropdown.style.display = payload.mode === 'employees' ? 'block' : 'none';

    const safeVal = (v) => {
        if (v == null || isNaN(Number(v))) return null;
        const n = Number(v);
        if (!isFinite(n)) return null;
        if (n === 0 && metric !== 'nodeals') return null;
        return n;
    };

    let lbls = [], fData = [], nums = [];

    // ── AVERAGES MODE ────────────────────────────────────────────────────────
    if (payload.mode === 'averages') {

        if (payload.tf === 'Monthly') {
            // monthly-kpi returns { months:[...], data:[{name, values}] } per store
            const first = (payload.results || []).find(r => r && r.months && r.months.length);
            lbls = first ? first.months : [];

            (payload.results || []).forEach((r, idx) => {
                if (!r || !r.months || !r.data) return;
                const store = payload.stores[idx];
                const row = r.data.find(m => m.name.toLowerCase().includes(
                    metric === 'conversion' ? 'customer conversion' :
                    metric === 'margin'     ? 'gross margin'        :
                    metric === 'nodeals'    ? 'no deal count'       : 'avg transaction'
                ));
                if (!row) return;
                const vals = lbls.map(lbl => {
                    const i = r.months.indexOf(lbl);
                    return i === -1 ? null : safeVal(row.values[i]);
                });
                const valid = vals.filter(v => v !== null);
                if (!valid.length) return;
                nums.push(...valid);
                fData.push({ label: '   ' + store + '   ', data: vals, borderColor: STORE_COLORS[store], backgroundColor: STORE_COLORS[store], tension: 0.4, pointRadius: 5, spanGaps: true });
            });

        } else {
            // 4-Week: kpi-manage returns periods newest-first — reverse for left=old, right=new
            const first = (payload.results || []).find(r => r && r.periods && r.periods.length);
            lbls = first ? [...first.periods].reverse().map(p => _kpiWeekRangeLabel(p.period_end_date)) : [];

            (payload.results || []).forEach((r, idx) => {
                if (!r || !r.periods) return;
                const store = payload.stores[idx];
                const vals = [...r.periods].reverse().map(p => {
                    if (!p.entries || !p.entries.length) return null;
                    const total = _kpiStoreTotalRowHtml ? (() => {
                        // compute totals inline without the HTML builder
                        const t2 = { employee_name: 'Store Total' };
                        _KPI_INPUT_FIELDS.forEach(function(f) {
                            if (f === 'avg_transaction_time') {
                                const vs = p.entries.map(e => Number(e[f])).filter(v => v > 0 && !isNaN(v));
                                t2[f] = vs.length ? vs.reduce((a,b)=>a+b,0)/vs.length : null;
                            } else {
                                const vs = p.entries.map(e => Number(e[f])).filter(v => v != null && !isNaN(v));
                                t2[f] = vs.length ? vs.reduce((a,b)=>a+b,0) : null;
                            }
                        });
                        return _kpiCalcDerived(t2);
                    })() : null;
                    return total ? safeVal(total[field]) : null;
                });
                const valid = vals.filter(v => v !== null);
                if (!valid.length) return;
                nums.push(...valid);
                fData.push({ label: '   ' + store + '   ', data: vals, borderColor: STORE_COLORS[store], backgroundColor: STORE_COLORS[store], tension: 0.4, pointRadius: 5, spanGaps: true });
            });
        }

    // ── EMPLOYEES MODE ───────────────────────────────────────────────────────
    } else {
        const r = payload.result;
        if (!r || !r.periods || !r.periods.length) {
            const loader = document.getElementById('chartLoading');
            if (loader) { loader.innerHTML = '<div class="status-message">No data available.</div>'; loader.style.display = 'flex'; }
            return;
        }

        // kpi-manage returns newest-first — reverse so chart reads left=old, right=new
        const periods = [...r.periods].reverse();

        lbls = payload.tf === 'Monthly'
            ? periods.map(p => p.period_label)
            : periods.map(p => _kpiWeekRangeLabel(p.period_end_date));

        // Only chart employees who are still current — use the editable (current) period's
        // roster as the authoritative list, filtering out anyone who has since left the store
        const editablePeriod = r.periods.find(p => p.is_editable);
        const currentEmpSet = editablePeriod
            ? new Set(editablePeriod.entries.map(e => e.employee_name))
            : null;

        const allEmpNames = [...new Set(periods.flatMap(p => (p.entries || []).map(e => e.employee_name)))];
        const empNames = currentEmpSet ? allEmpNames.filter(n => currentEmpSet.has(n)) : allEmpNames;

        empNames.forEach((name, eIdx) => {
            const vals = periods.map(p => {
                const entry = (p.entries || []).find(e => e.employee_name === name);
                if (!entry) return null;
                const computed = _kpiCalcDerived(entry);
                return safeVal(computed[field]);
            });
            const valid = vals.filter(v => v !== null);
            if (!valid.length) return;
            nums.push(...valid);
            const color = EMP_COLORS[eIdx % EMP_COLORS.length];
            fData.push({ label: '   ' + name + '   ', data: vals, borderColor: color, backgroundColor: color, tension: 0.4, pointRadius: 5, spanGaps: true });
        });
    }

    // ── Y-axis bounds ────────────────────────────────────────────────────────
    let yMin = 0, yMax = 100;
    if (nums.length) {
        const mx = Math.max(...nums), mn = Math.min(...nums);
        if (isPct) {
            yMin = Math.max(0, Math.floor(mn/10)*10 - 10);
            yMax = Math.min(100, Math.ceil(mx/10)*10 + 10);
        } else if (metric === 'time') {
            yMin = Math.max(0, Math.floor(mn) - 1);
            yMax = Math.ceil(mx) + 1;
        } else {
            yMin = 0;
            yMax = Math.max(1, Math.ceil(mx * 1.2));
        }
    }

    const fmtVal = (v) => {
        if (v === null) return '';
        if (metric === 'time') { const m2=Math.floor(v), s=Math.round((v-m2)*60); return m2+':'+(s<10?'0':'')+s; }
        return (Math.round(v*10)/10) + unit;
    };

    // ── Draw chart ───────────────────────────────────────────────────────────
    if (mainChartInstance) mainChartInstance.destroy();

    mainChartInstance = new Chart(document.getElementById('mainKpiChart').getContext('2d'), {
        type: 'line',
        plugins: typeof ChartDataLabels !== 'undefined' ? [ChartDataLabels] : [],
        data: { labels: lbls, datasets: fData },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: { padding: { top: 55, right: 20, left: 10, bottom: 0 } },
            animation: { duration: 400 },
            plugins: {
                legend: { position: 'bottom', labels: { font: { size: 13, family:"'Inter',sans-serif", weight:'bold' }, usePointStyle: true, boxWidth: 8, padding: 20 } },
                datalabels: { align:'top', anchor:'end', formatter: fmtVal, font:{ size:11, weight:'bold' }, color:'#666', offset:4 },
                tooltip: { callbacks: { label: ctx => { const lbl = ctx.dataset.label.trim(); return lbl + ': ' + fmtVal(ctx.parsed.y); } } }
            },
            scales: {
                y: { min: yMin, max: yMax, ticks: { callback: v => metric === 'time' ? (Math.floor(v)+':'+(Math.round((v-Math.floor(v))*60)<10?'0':'')+Math.round((v-Math.floor(v))*60)) : (v+unit) } },
                x: { grid: { display: false } }
            }
        }
    });

    const activeLoader = document.getElementById('chartLoading');
    if (activeLoader) activeLoader.style.display = 'none';
}

// --- CHART: DRAW LEADERBOARD ---
function drawLeaderboard() {
    // Standings list (replaced the Chart.js "race" — see combined Performance widget).
    // Reads the same cachedLeaderboardData the race used; Revenue/GP toggle unchanged.
    const wrapper = document.getElementById('lb-wrapper');
    const monthLabel = document.getElementById('lb-month-display');
    if (!wrapper || !cachedLeaderboardData || !cachedLeaderboardData.activeStores) return;

    const now = new Date();
    if (monthLabel) monthLabel.innerText = now.toLocaleString('default', { month: 'long', year: 'numeric' });

    const colors = { 'OVL': '#7c6fd6', 'LEE': '#4e90cf', 'WSP': '#2ea36a', 'MPL': '#d99f43', 'BAL': '#d9776a' };
    const dataPacket = currentLeaderboardMetric === 'Revenue' ? cachedLeaderboardData.revenue : cachedLeaderboardData.gp;
    const myStore = (sessionStorage.getItem('speeksUserStore') || '').toUpperCase();

    const rows = cachedLeaderboardData.activeStores
        .filter(st => dataPacket && dataPacket[st])
        .map(st => {
            const arr = dataPacket[st];
            const lastIdx = arr.findLastIndex(v => v !== null && v !== undefined);
            return { store: st, val: lastIdx !== -1 ? (arr[lastIdx] || 0) : 0 };
        })
        .sort((a, b) => b.val - a.val);

    if (!rows.length) { wrapper.innerHTML = '<div class="status-message">No data yet.</div>'; return; }

    const fmt = v => '$' + Math.round(v).toLocaleString();

    // No bars. This is a standings list — the rank column already gives the order
    // and the money column already gives the size, so a bar scaled to the leader
    // was a third encoding of what two columns had said, and the one that took the
    // most room. (It also lost the .lbs-info wrapper, which existed only to stack
    // the name over its bar.)
    wrapper.innerHTML = rows.map((r, i) => `
        <div class="lbs-row${r.store === myStore ? ' me' : ''}">
            <span class="lbs-rank${i === 0 ? ' g' : ''}">${i + 1}</span>
            <span class="lbs-store">
                <span class="lbs-dot" style="background:${colors[r.store] || '#94a3b8'}"></span>
                <span class="lbs-nm">${r.store}</span>
            </span>
            <span class="lbs-val">${fmt(r.val)}</span>
        </div>`).join('');
}

