// Total possible audit points (derived, = 165) and a quick id→{pts,text,section} lookup.
const AUDIT_POSSIBLE = AUDIT_DEFINITION.reduce((s, sec) => s + sec.items.reduce((a, i) => a + i.pts, 0), 0);
const AUDIT_ITEM_MAP = (() => {
    const m = {};
    AUDIT_DEFINITION.forEach(sec => sec.items.forEach(i => { m[i.id] = { pts: i.pts, text: i.text, section: sec.title }; }));
    return m;
})();

// ============================================================================
// DB ITEM CATALOG — both instruments are editable from the Manage Items tab
// (scorecard_items / paymore_audit_items via the scorecard fn). The GET
// response carries the catalog; the hardcoded AUDIT_DEFINITION / SCORECARD_*
// constants above are only the fallback until it loads.
// ============================================================================

// Audit catalog → AUDIT_DEFINITION-shaped sections. includeInactive for the
// Manage tab; scoring/breakdown use active items only.
function _auSections(includeInactive) {
    const cat = window._auCatalog;
    if (!cat || !cat.length) return AUDIT_DEFINITION;
    const rows = (includeInactive ? cat : cat.filter(i => i.active))
        .slice().sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
    const sections = [], idx = {};
    rows.forEach(i => {
        if (!(i.section in idx)) { idx[i.section] = sections.length; sections.push({ title: i.section, items: [] }); }
        sections[idx[i.section]].items.push({
            id: i.item_id, pts: Number(i.points) || 0, text: i.item_text,
            dbId: i.id, active: !!i.active,
        });
    });
    return sections;
}

function _auditPossibleNow() {
    const cat = window._auCatalog;
    if (!cat || !cat.length) return AUDIT_POSSIBLE;
    return cat.filter(i => i.active).reduce((a, i) => a + (Number(i.points) || 0), 0);
}

// Scorecard catalog → [{id?, item_key, label, max_score, active}] (0–5 selects).
function _scCats(includeInactive) {
    const cat = window._scCatalog;
    if (!cat || !cat.length) {
        const keys = ['online_store_pictures', 'facebook_listings', 'social_media_posts', 'paymore_sync'];
        return SCORECARD_CATEGORIES.map((label, i) => ({ id: null, item_key: keys[i], label, max_score: 5, active: true }));
    }
    return (includeInactive ? cat : cat.filter(i => i.active))
        .slice().sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
}

// Fetch the catalog (plus fresh store data) if we don't have it yet — the
// submit modal can open before the dashboard widget's fetch has run. Only
// re-renders the entry forms while they're still untouched.
let _scCatalogFetching = false;
function _ensureScCatalog(force) {
    if (window._scCatalog && window._auCatalog && !force) return;
    if (_scCatalogFetching) return;
    _scCatalogFetching = true;
    fetch(`${SCORECARD_URL}?v=${Date.now()}`).then(r => r.json()).then(json => {
        if (!json || !json.success) return;
        window._scorecardAllData = json.data || window._scorecardAllData || [];
        if (json.catalog) {
            window._scCatalog = json.catalog.scorecard_items || [];
            window._auCatalog = json.catalog.audit_items || [];
        }
        // _auditHasWork also counts notes and photos, which the old earned-points
        // check missed — an audit part-way through those would still get rebuilt.
        if (!_auditHasWork()) { _buildScorecardModalInputs(); renderAuditEntry(); }
        if (currentScoreTab === 'manage') renderManageItems();
    }).catch(() => {}).finally(() => { _scCatalogFetching = false; });
}

// Where a score stands against the two thresholds, in three words. Was a tile
// of its own ("Audit Standing") until a second audit arrived beside the first
// and a single unlabelled standing stopped saying which one it belonged to —
// now each audit carries its own on its sub-line (Ethan 2026-08-12).
function _auStanding(pct) {
    if (pct >= AUDIT_TARGET_PCT) return 'On Target';
    if (pct >= AUDIT_PASS_PCT) return 'Passing';
    return 'Below Pass';
}

// Audit color by percentage: target 90+ green, pass 80+ amber, else red.
function auditPctColor(pct) {
    if (pct >= AUDIT_TARGET_PCT) return { bg: '#d1fae5', fg: '#059669' };
    if (pct >= AUDIT_PASS_PCT) return { bg: '#fef3c7', fg: '#d97706' };
    return { bg: '#fee2e2', fg: '#dc2626' };
}

function openScorecardModal() {
    toggleModal('scorecardSubmitModal');

    const dateInput = document.getElementById('dm-score-date');
    if (dateInput) dateInput.valueAsDate = new Date();
    _scoreDateLast = dateInput ? dateInput.value : ''; // the date to fall back to if a swap is declined

    _paDirty = false;   // a fresh open starts from what is saved, not from last time
    switchScoreTab('scorecard');
    _buildScorecardModalInputs();
    renderAuditEntry();
    _ensureScCatalog();
}

// ---- Submit-modal tabs (Scorecard | SPEEKS Audit | PayMore Audit | Manage) ----
// Who may record what PayMore said. The same allow-list the scorecard fn
// enforces server-side — the tab being hidden is a convenience, the 403 is the
// rule. See [[kpi-role-gate]] for what happens when these two drift apart.
function _paCanEdit() {
    const r = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    return r === 'district manager' || r === 'district-manager' || r === 'ceo';
}

let currentScoreTab = 'scorecard';
function switchScoreTab(tab) {
    // Nobody but a DM or the CEO can land on the PayMore tab, however they got
    // there — a stale onclick, a bookmarked state, the console.
    if (tab === 'paudit' && !_paCanEdit()) tab = 'scorecard';
    currentScoreTab = tab;
    const scTab = document.getElementById('sc-tab-scorecard');
    const auTab = document.getElementById('sc-tab-audit');
    const paTab = document.getElementById('sc-tab-paudit');
    const mgTab = document.getElementById('sc-tab-manage');
    if (scTab) scTab.classList.toggle('active', tab === 'scorecard');
    if (auTab) auTab.classList.toggle('active', tab === 'audit');
    if (paTab) {
        paTab.style.display = _paCanEdit() ? '' : 'none';
        paTab.classList.toggle('active', tab === 'paudit');
    }
    if (mgTab) mgTab.classList.toggle('active', tab === 'manage');
    const scPanel = document.getElementById('sc-panel-scorecard');
    const auPanel = document.getElementById('sc-panel-audit');
    const paPanel = document.getElementById('sc-panel-paudit');
    const mgPanel = document.getElementById('sc-panel-manage');
    if (scPanel) scPanel.style.display = tab === 'scorecard' ? 'block' : 'none';
    if (auPanel) auPanel.style.display = tab === 'audit' ? 'block' : 'none';
    if (paPanel) paPanel.style.display = tab === 'paudit' ? 'block' : 'none';
    if (mgPanel) mgPanel.style.display = tab === 'manage' ? 'block' : 'none';
    const scBtn = document.getElementById('submitScorecardBtn');
    const auBtn = document.getElementById('submitAuditBtn');
    const paBtn = document.getElementById('submitPauditBtn');
    if (scBtn) scBtn.style.display = tab === 'scorecard' ? '' : 'none';
    if (auBtn) auBtn.style.display = tab === 'audit' ? '' : 'none';
    if (paBtn) paBtn.style.display = tab === 'paudit' ? '' : 'none';
    // The two Remove buttons are shown CONDITIONALLY by their own tab's
    // renderer, which only ever runs while that tab is open — so nothing was
    // switching them off on the way out and the PayMore one followed you to
    // the Scorecard tab, where it would have removed a PayMore audit.
    // Hidden here unconditionally; the renderers below put them back if the
    // selected store and date actually have something to remove.
    const paDel = document.getElementById('deletePauditBtn');
    if (paDel) paDel.style.display = 'none';
    const auDel = document.getElementById('deleteAuditBtn');
    if (auDel) auDel.style.display = 'none';
    if (tab === 'manage') renderManageItems();
    if (tab === 'paudit') renderPaymoreAuditTab();
    _syncAuditDeleteBtn();
}

// ---- the real PayMore audit: a date and a score ----------------------------
// The store and date come from the two controls at the top of the modal, shared
// with the other tabs. Everything below is the one figure corporate gives us.

// The points the audit is out of: the active catalog's total, exactly what the
// SPEEKS Audit is scored against. Read from the catalog rather than hardcoded at
// 165 — the Manage Items tab can change it, and a stale constant here would put
// two different denominators on one row of the district board.
function _paPossible() {
    return (window._auCatalog || [])
        .reduce((a, i) => a + (i.active ? (Number(i.points) || 0) : 0), 0);
}

// The saved audit for the store and date on screen, if there is one.
function _paSaved() {
    const store = (document.getElementById('dm-store-select')?.value || '').toUpperCase();
    const date = document.getElementById('dm-score-date')?.value || '';
    const row = (window._scorecardAllData || []).find(d => String(d.store).toUpperCase() === store);
    const a = row && row.officialAudit;
    return (a && a.date === date) ? a : null;
}

// Anything typed into the PayMore form that has not been saved. The date is a
// LABEL on the audit, not a different form — correcting it must never cost the
// figures already entered, which is how the SPEEKS audit tab behaves and what
// this now matches (Ethan 2026-08-12).
let _paDirty = false;
function _paTouch() { _paDirty = true; _paPreview(); }

// What is actually on the "out of" input, falling back to the catalog total.
function _paPossibleInput() {
    const v = parseFloat(document.getElementById('pa-possible')?.value);
    return Number.isFinite(v) && v > 0 ? v : _paPossible();
}

function _paPreview() {
    const poss = _paPossibleInput();
    const el = document.getElementById('pa-earned');
    const out = document.getElementById('pa-pct');
    const note = document.getElementById('pa-poss-note');
    // Said only when it is true. A note that the total differs is worth reading;
    // one confirming it is the usual 165 is noise on every single entry.
    if (note) {
        const std = _paPossible();
        note.innerHTML = (std && poss && Math.abs(poss - std) > 0.001)
            ? 'Scored out of <b>' + poss + '</b> rather than the SPEEKS Audit&rsquo;s <b>' + std
              + '</b>. The percentage is what the board compares, so it still reads against the same targets.'
            : '';
    }
    if (!out) return;
    const v = parseFloat(el && el.value);
    if (!poss || !Number.isFinite(v)) { out.innerHTML = '&mdash;'; out.style.color = ''; return; }
    const pct = Math.round(Math.min(Math.max(v, 0), poss) / poss * 1000) / 10;
    out.textContent = pct + '%';
    // Same three bands as everywhere else this score is shown, so the number the
    // DM types goes the colour it will be on the board before they save it.
    out.style.color = pct >= 80 ? '#178048' : (pct >= 50 ? '#b3760a' : '#dc2626');
}

function renderPaymoreAuditTab() {
    // Loading an existing entry rather than presenting a blank form over the top
    // of one: re-entering the same store and date corrects it, and the DM should
    // be able to see what they are correcting.
    const saved = _paSaved();
    // Untouched form: load whatever is saved for this store and date. Touched:
    // leave every field exactly as typed and only refresh the notes around them.
    // Changing the date is how you say WHEN the audit happened, and doing that
    // after typing the score used to wipe the score.
    if (!_paDirty) {
        // A saved audit keeps the total it was scored against, not today's
        // catalog total — otherwise reopening a 120-point audit would silently
        // re-base it on 165 and change the percentage on save without anyone
        // touching the figure.
        const poss = saved ? saved.possible : _paPossible();
        const pEl = document.getElementById('pa-possible');
        if (pEl) pEl.value = poss || '';
        const earned = document.getElementById('pa-earned');
        if (earned) earned.value = saved ? saved.earned : '';
    }
    const del = document.getElementById('deletePauditBtn');
    if (del) del.style.display = saved ? '' : 'none';

    const note = document.getElementById('pa-existing');
    if (note) {
        const store = (document.getElementById('dm-store-select')?.value || '').toUpperCase();
        const row = (window._scorecardAllData || []).find(d => String(d.store).toUpperCase() === store);
        const last = row && row.officialAudit;
        note.innerHTML = saved
            ? '<div class="pa-hint" style="margin:0 0 12px;">Editing the audit already saved for this date &mdash; '
              + '<b>' + saved.earned + ' / ' + saved.possible + '</b> (' + saved.pct + '%). Saving replaces it.</div>'
            : (last
                ? '<div class="pa-hint" style="margin:0 0 12px;">Last PayMore audit for ' + escapeHtml(store)
                  + ' was <b>' + last.pct + '%</b> on ' + escapeHtml(_dcShortDay(last.date))
                  + '. Saving against a new date adds another.</div>'
                : '<div class="pa-hint" style="margin:0 0 12px;">No PayMore audit recorded for '
                  + escapeHtml(store) + ' yet.</div>');
    }
    _paPreview();
}

async function submitPaymoreAudit() {
    const store = document.getElementById('dm-store-select')?.value || '';
    const date = document.getElementById('dm-score-date')?.value || '';
    const raw = document.getElementById('pa-earned')?.value;
    const btn = document.getElementById('submitPauditBtn');
    if (!store || !date) { alert('Pick a store and date.'); return; }
    const earned = parseFloat(raw);
    if (!Number.isFinite(earned)) { alert('Enter the points PayMore scored the store.'); return; }
    const possible = parseFloat(document.getElementById('pa-possible')?.value);
    if (!Number.isFinite(possible) || possible <= 0) { alert('Enter the points the audit was out of.'); return; }
    if (earned > possible) {
        if (!confirm(`${earned} is more than the ${possible} points available.\n\nSave it as ${possible}?`)) return;
    }

    btn.disabled = true; btn.style.opacity = '0.7'; btn.innerText = 'Saving…';
    try {
        const res = await fetch(SCORECARD_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'submit_official_audit', store, date, earned, possible,
                enteredBy: sessionStorage.getItem('speeksUserName') || null,
                role: (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim(),
            })
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Save failed');
        _paDirty = false;   // saved — nothing left to protect from a date change
        btn.innerText = `Saved — ${json.earned}/${json.possible} (${json.pct}%)`;
        btn.style.background = 'var(--sage-professional)';
        setTimeout(() => {
            if (typeof fetchScorecardData === 'function') fetchScorecardData();
            if (typeof fetchMasterDistrictDashboard === 'function') fetchMasterDistrictDashboard();
            closeScorecardModal();
            btn.innerText = 'Save PayMore Audit';
            btn.style.background = ''; btn.style.opacity = ''; btn.disabled = false;
        }, 1200);
    } catch (err) {
        alert('Error saving the PayMore audit: ' + (err.message || err));
        btn.innerText = 'Save PayMore Audit';
        btn.style.background = ''; btn.style.opacity = ''; btn.disabled = false;
    }
}

async function deletePaymoreAudit() {
    const store = document.getElementById('dm-store-select')?.value || '';
    const date = document.getElementById('dm-score-date')?.value || '';
    if (!store || !date) return;
    if (!confirm(`Remove the PayMore audit saved for ${store} on ${date}?`)) return;
    try {
        const res = await fetch(SCORECARD_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'delete_official_audit', store, date,
                role: (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim(),
            })
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Delete failed');
        _paDirty = false;
        if (typeof fetchScorecardData === 'function') await fetchScorecardData();
        if (typeof fetchMasterDistrictDashboard === 'function') fetchMasterDistrictDashboard();
        _ensureScCatalog(true);
        renderPaymoreAuditTab();
    } catch (err) {
        alert('Error removing the PayMore audit: ' + (err.message || err));
    }
}

// ---- delete a SPEEKS audit -------------------------------------------------
// For the walkthrough submitted before it was finished. DM/CEO only, and the
// server enforces that independently — the button being hidden is convenience.
// Deliberately named with the date in the confirm: the tool always has SOME
// store and date selected, and "delete the audit" without saying which is how
// somebody throws away the wrong one.
async function deleteSpeeksAudit() {
    const store = (document.getElementById('dm-store-select')?.value || '').toUpperCase();
    const date = document.getElementById('dm-score-date')?.value || '';
    const saved = _selectedStoreAudit();
    if (!saved || saved.date !== date) {
        alert('There is no SPEEKS Audit saved for ' + (store || 'this store') + ' on ' + (date || 'this date') + '.');
        return;
    }
    if (!confirm(`Delete ${store}'s SPEEKS Audit from ${date}?\n\n`
        + `${saved.earned}/${saved.possible} (${saved.pct}%). This removes its photos too and cannot be undone.`)) return;

    const btn = document.getElementById('deleteAuditBtn');
    if (btn) { btn.disabled = true; btn.innerText = 'Deleting…'; }
    try {
        const res = await fetch(SCORECARD_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'delete_audit', store, date,
                role: (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim(),
            })
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Delete failed');
        // The scored answers on screen belong to a row that no longer exists.
        _auditDirty = false;
        if (typeof fetchScorecardData === 'function') await fetchScorecardData();
        if (typeof fetchMasterDistrictDashboard === 'function') fetchMasterDistrictDashboard();
        _ensureScCatalog(true);
        renderAuditEntry();
        _syncAuditDeleteBtn();
    } catch (err) {
        alert('Error deleting the audit: ' + (err.message || err));
    }
    if (btn) { btn.disabled = false; btn.innerText = 'Remove'; }
}

// Shown only on the SPEEKS Audit tab, only to a DM or the CEO, and only when the
// selected store and date actually have one saved — otherwise it is a button
// that can only ever produce an error.
function _syncAuditDeleteBtn() {
    const btn = document.getElementById('deleteAuditBtn');
    if (!btn) return;
    const date = document.getElementById('dm-score-date')?.value || '';
    const saved = _selectedStoreAudit();
    const show = currentScoreTab === 'audit' && _paCanEdit() && saved && saved.date === date;
    btn.style.display = show ? '' : 'none';
}

function onScoreStoreChange() {
    _buildScorecardModalInputs();
    renderAuditEntry();
    // The PayMore tab reads the store and date straight off these two controls,
    // so it has to be re-read when either moves — otherwise the form shows one
    // store's saved score under another store's name. A different STORE is a
    // different subject, not a relabelling, so the typed figures are dropped
    // here where a date change keeps them.
    _paDirty = false;
    if (currentScoreTab === 'paudit') renderPaymoreAuditTab();
    _syncAuditDeleteBtn();
}
// The date is a label on the walkthrough, not a different form, so correcting it
// must never cost the auditor their answers — this used to rebuild the checklist
// from scratch and wipe an almost-finished audit. Only one date change genuinely
// needs a reset: one landing on a date that already HAS a saved audit for this
// store, which can't be shown without discarding what's on screen. That case asks
// first, and puts the date back if the answer is no.
let _scoreDateLast = '';
function onScoreDateChange() {
    const el = document.getElementById('dm-score-date');
    const dateVal = el?.value || '';
    // What is on screen is a SAVED audit that nobody has touched since it loaded.
    // Those answers belong to the date they were loaded from, not to the date
    // just picked — carrying them forward showed a finished audit's scores under
    // a day that has none, which reads as that day already being audited.
    // Rebuilding is free here precisely because there is nothing unsaved to lose.
    const justLoaded = !!_auditLoadedDate && !_auditDirty && _auditLoadedDate !== dateVal;

    if (justLoaded || !_auditHasWork()) {
        renderAuditEntry();
        if (currentScoreTab === 'paudit') renderPaymoreAuditTab();
        _syncAuditDeleteBtn();
        _scoreDateLast = dateVal;
        return;
    }
    const existing = _selectedStoreAudit();
    if (existing && existing.date === dateVal) {
        const d = new Date(dateVal + 'T00:00:00');
        const lbl = isNaN(d.getTime()) ? dateVal : d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
        if (!confirm(`${lbl} already has a saved audit for this store.\n\nLoad it and discard the audit you're filling out now?`)) {
            if (el) el.value = _scoreDateLast;
            return;
        }
        renderAuditEntry();
    } else {
        // New date, no saved audit behind it — keep every answer exactly as typed.
        // The checklist itself doesn't depend on the date, so there is nothing to
        // rebuild at all.
        updateAuditRunningBar();
    }
    // Reached only when the date actually moved — a declined swap returns above
    // with the old date put back, and the form on screen is still the right one.
    if (currentScoreTab === 'paudit') renderPaymoreAuditTab();
    _syncAuditDeleteBtn();
    _scoreDateLast = dateVal;
}

function _buildScorecardModalInputs() {
    const storeEl = document.getElementById('dm-store-select');
    const store = (storeEl ? storeEl.value : null) || sessionStorage.getItem('speeksUserStore') || '';
    const existingEntry = (window._scorecardAllData || []).find(d => String(d.store).toUpperCase() === store.toUpperCase());

    const container = document.getElementById('dm-category-inputs');
    if (!container) return;
    // Categories come from the DB catalog (Manage Items tab); the hardcoded
    // list is only the pre-load fallback. One section: Online & Marketing.
    const cats = _scCats();
    const existingBucket = existingEntry && existingEntry.buckets
        ? existingEntry.buckets.find(b => b.name === 'Online & Marketing')
        : null;
    const existingNote = existingBucket && existingBucket.notes ? existingBucket.notes : '';
    let html = `<div style="grid-column: 1 / -1; padding-bottom: 4px; border-bottom: 1px solid #e2e8f0;">
            <span style="font-size: 10px; font-weight: 800; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px;">Online & Marketing</span>
        </div>`;
    cats.forEach(cat => {
        let opts = '<option value="">--</option>';
        const max = Math.max(1, Number(cat.max_score) || 5);
        for (let p = max; p >= 0; p--) opts += `<option value="${p}">${p}</option>`;
        html += `<div style="display: flex; flex-direction: column;">
                <label class="form-label-caps">${escapeHtml(cat.label)}</label>
                <select id="score-input-${cat.item_key}" class="form-input-lg" data-itemkey="${cat.item_key}" style="margin-top: 0; padding: 10px; font-size: 14px;">${opts}</select>
            </div>`;
    });
    const escapedNote = existingNote.replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    html += `<div style="grid-column: 1 / -1; margin-top: 4px; margin-bottom: 2px;">
            <label class="form-label-caps" style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">Section Notes <span style="font-weight: 400; text-transform: none; font-size: 10px; color: #94a3b8; letter-spacing: 0;">(optional)</span></label>
            <textarea id="score-notes-0" class="scorecard-notes-input" rows="2" placeholder="Leave a note for the manager about this section...">${escapedNote}</textarea>
        </div>`;
    container.innerHTML = html;
}

function refreshScorecardNotes() {
    _buildScorecardModalInputs();
}

function toggleScorecardSection(bIdx) {
    const enabled = document.getElementById(`section-toggle-${bIdx}`).checked;
    const wrapper = document.getElementById(`section-inputs-${bIdx}`);
    if (wrapper) wrapper.style.display = enabled ? 'contents' : 'none';
}

// We don't even need a custom close function anymore!
// Your native "closeAllModals()" command takes care of it.

function closeScorecardModal() {
    closeAllModals(); // Your native function handles hiding everything
}

function submitNewScorecard() {
    const store = document.getElementById('dm-store-select').value;
    const date = document.getElementById('dm-score-date').value;
    const btn = document.getElementById('submitScorecardBtn');

    // Scores keyed by item_key (the fn's preferred shape) from the
    // catalog-driven inputs; untouched categories stay null.
    const scores = {};
    document.querySelectorAll('#dm-category-inputs [data-itemkey]').forEach(el => {
        const v = el.value;
        scores[el.getAttribute('data-itemkey')] = v === '' ? null : parseFloat(v);
    });
    const noteEl = document.getElementById('score-notes-0');

    btn.innerText = "Saving...";
    btn.style.opacity = "0.7";
    btn.disabled = true;

    const payload = {
        action: 'submit_scorecard',
        store: store,
        date: date,
        scores,
        notes: noteEl ? noteEl.value.trim() : '',
        // Who is saving this. The scorecard function has always passed it on as
        // excludeUser so the submitter is left out of the alert, but this payload
        // never sent it — so excludeUser was null every time and the DM got
        // emailed about the score he had just entered himself.
        submittedBy: sessionStorage.getItem('speeksUserName') || null,
    };

    fetch(SCORECARD_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
    }).then(async res => {
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Save failed');

        btn.innerText = "Saved Successfully!";
        btn.style.background = "var(--sage-professional)";

        setTimeout(() => {
            if (typeof fetchScorecardData === 'function') fetchScorecardData();
            if (typeof fetchMasterDistrictDashboard === 'function') fetchMasterDistrictDashboard();
            closeScorecardModal();
            btn.innerText = "Save Scorecard";
            btn.style.background = "";
            btn.disabled = false;
        }, 1500);
    }).catch(err => {
        alert("Error saving scorecard: " + (err.message || err));
        btn.innerText = "Save Scorecard";
        btn.style.background = "";
        btn.disabled = false;
    });
}

// ============================================================================
// SPEEKS AUDIT — entry form (in the submit modal) + read-only breakdown popout.
// Uses AUDIT_DEFINITION / AUDIT_ITEM_MAP / AUDIT_POSSIBLE defined near the top.
// ============================================================================

// Returns the cached latest audit for the modal's selected store (or null).
function _selectedStoreAudit() {
    const store = (document.getElementById('dm-store-select')?.value || '').toUpperCase();
    const entry = (window._scorecardAllData || []).find(d => String(d.store).toUpperCase() === store);
    return entry && entry.audit ? entry.audit : null;
}

// Per-section notes + photo attachments captured while scoring a practice audit.
// Notes: { [sectionTitle]: string }. Photos: { [sectionTitle]: [{file?,localUrl?,url?,path?,name}] }
// New photos upload to the audit-photos bucket on save; a store's previous-audit
// photos are cleared server-side once a new audit is scored.
let _auditEntryNotes = {};
let _auditEntryPhotos = {};
let _auditDirty = false; // unsaved audit work — closeAllModals asks before discarding
// The date whose SAVED audit is currently on screen, '' when the form is the
// auditor's own work. Read only alongside !_auditDirty — together they mean
// "what is on screen is a saved audit, untouched".
let _auditLoadedDate = '';

function _auSecTitle(sIdx) { return (_auSections()[sIdx] || {}).title || String(sIdx); }

function onAuditNoteInput(sIdx) {
    const el = document.getElementById(`audit-note-${sIdx}`);
    _auditEntryNotes[_auSecTitle(sIdx)] = el ? el.value : '';
    _auditDirty = true;
}

// Per-section photo cap. Photos land in the audit-photos bucket individually,
// so this is just a sanity guard against accidental bulk-selects, not a
// payload limit.
const AUDIT_PHOTO_MAX = 20;

function onAuditPhotoAdd(sIdx, input) {
    const title = _auSecTitle(sIdx);
    if (!_auditEntryPhotos[title]) _auditEntryPhotos[title] = [];
    const MAX = AUDIT_PHOTO_MAX;
    [...(input.files || [])].forEach(f => {
        if (!f.type || !f.type.startsWith('image/')) return;
        if (_auditEntryPhotos[title].length >= MAX) { return; }
        _auditEntryPhotos[title].push({ file: f, localUrl: URL.createObjectURL(f), name: f.name });
        _auditDirty = true;
    });
    input.value = '';
    renderAuditSectionPhotos(sIdx);
}

function removeAuditPhoto(sIdx, idx) {
    const arr = _auditEntryPhotos[_auSecTitle(sIdx)];
    if (arr) { arr.splice(idx, 1); _auditDirty = true; renderAuditSectionPhotos(sIdx); }
}

function renderAuditSectionPhotos(sIdx) {
    const wrap = document.getElementById(`audit-photos-${sIdx}`);
    if (!wrap) return;
    const arr = _auditEntryPhotos[_auSecTitle(sIdx)] || [];
    wrap.innerHTML = arr.map((p, i) => {
        const src = p.url || p.localUrl;
        return `<div style="position:relative; width:64px; height:64px; border-radius:8px; overflow:hidden; border:1px solid #e2e8f0;">
            <img src="${src}" style="width:100%; height:100%; object-fit:cover; cursor:pointer;" onclick="openAuditPhotoLightbox('${src}')">
            <button type="button" onclick="removeAuditPhoto(${sIdx}, ${i})" title="Remove" style="position:absolute; top:2px; right:2px; width:18px; height:18px; border:none; border-radius:50%; background:rgba(15,23,42,.78); color:#fff; font-size:12px; line-height:1; cursor:pointer;">&times;</button>
        </div>`;
    }).join('');
    const hint = document.getElementById(`audit-photo-hint-${sIdx}`);
    if (hint) hint.textContent = arr.length ? `${arr.length} attached` : '';
}

// Full-screen image viewer (created lazily; sits above any modal).
function openAuditPhotoLightbox(src) {
    let lb = document.getElementById('auditPhotoLightbox');
    if (!lb) {
        lb = document.createElement('div');
        lb.id = 'auditPhotoLightbox';
        // Closes itself only — never the audit modal underneath. Backdrop
        // click, the ✕, or Escape (handled by the global keydown) all work.
        lb.onclick = () => { lb.style.display = 'none'; };
        lb.style.cssText = 'display:none; position:fixed; inset:0; z-index:4000; background:rgba(2,6,23,.85); align-items:center; justify-content:center; padding:30px; cursor:zoom-out;';
        lb.innerHTML = '<img alt="" onclick="event.stopPropagation();" style="max-width:92vw; max-height:88vh; border-radius:10px; box-shadow:0 20px 60px rgba(0,0,0,.5); cursor:default;">' +
            '<button type="button" title="Close photo" onclick="event.stopPropagation(); document.getElementById(\'auditPhotoLightbox\').style.display=\'none\';" ' +
            'style="position:absolute; top:16px; right:20px; width:38px; height:38px; border:none; border-radius:50%; background:rgba(255,255,255,0.14); color:#fff; font-size:17px; font-weight:800; line-height:1; cursor:pointer;">✕</button>';
        document.body.appendChild(lb);
    }
    lb.querySelector('img').src = src;
    lb.style.display = 'flex';
}

// Live camera capture (works on laptops with a webcam + phones) via getUserMedia,
// so a photo can be taken in-app even where the file picker won't open a camera.
// Uploading via "Add photo(s)" stays available alongside this.
let _auditCamStream = null;

async function openAuditCamera(sIdx) {
    const md = navigator.mediaDevices;
    if (!md || !md.getUserMedia) {
        alert('Live camera is not available on this device/browser. Use "Add photo(s)" to upload instead.');
        return;
    }
    // Acquire the camera BEFORE showing the modal, so a denied/failed request
    // never leaves an empty black camera box on screen. Prefer the rear camera
    // on phones; laptops fall back to their only/default camera.
    let stream;
    try {
        stream = await md.getUserMedia({ video: { facingMode: 'environment' }, audio: false });
    } catch (e) {
        const name = e && e.name;
        let msg;
        if (name === 'NotAllowedError' || name === 'SecurityError') {
            msg = 'Camera access is blocked for this site. Click the camera (or lock) icon in your browser’s address bar, choose Allow for the camera, then tap “Take photo” again.';
        } else if (name === 'NotFoundError' || name === 'OverconstrainedError' || name === 'DevicesNotFoundError') {
            msg = 'No camera was found on this device.';
        } else if (name === 'NotReadableError' || name === 'TrackStartError') {
            msg = 'The camera is already in use by another app. Close it and try again.';
        } else {
            msg = 'Could not access the camera' + (e && e.message ? ': ' + e.message : '') + '.';
        }
        alert(msg + '\nYou can still use “Add photo(s)” to upload a picture.');
        return;
    }

    _auditCamStream = stream;
    let cam = document.getElementById('auditCameraModal');
    if (!cam) {
        cam = document.createElement('div');
        cam.id = 'auditCameraModal';
        cam.style.cssText = 'display:none; position:fixed; inset:0; z-index:4100; background:rgba(2,6,23,.92); flex-direction:column; align-items:center; justify-content:center; gap:14px; padding:20px;';
        cam.innerHTML =
            '<video id="auditCamVideo" autoplay playsinline muted style="max-width:92vw; max-height:68vh; border-radius:12px; background:#000;"></video>' +
            '<div style="display:flex; gap:12px;">' +
              '<button id="auditCamShot" type="button" style="background:#16a34a; color:#fff; border:none; border-radius:10px; padding:12px 22px; font-size:14px; font-weight:800; cursor:pointer;">📸 Capture</button>' +
              '<button id="auditCamCancel" type="button" style="background:#334155; color:#fff; border:none; border-radius:10px; padding:12px 22px; font-size:14px; font-weight:800; cursor:pointer;">Cancel</button>' +
            '</div>';
        document.body.appendChild(cam);
    }
    cam.querySelector('#auditCamCancel').onclick = () => closeAuditCamera();
    cam.querySelector('#auditCamShot').onclick = () => captureAuditPhoto(sIdx);
    cam.querySelector('#auditCamVideo').srcObject = _auditCamStream;
    cam.style.display = 'flex';
}

function closeAuditCamera() {
    const cam = document.getElementById('auditCameraModal');
    if (_auditCamStream) { _auditCamStream.getTracks().forEach(t => t.stop()); _auditCamStream = null; }
    if (cam) { const v = cam.querySelector('#auditCamVideo'); if (v) v.srcObject = null; cam.style.display = 'none'; }
}

function captureAuditPhoto(sIdx) {
    const cam = document.getElementById('auditCameraModal');
    const video = cam && cam.querySelector('#auditCamVideo');
    if (!video || !video.videoWidth) return;
    const title = _auSecTitle(sIdx);
    if (!_auditEntryPhotos[title]) _auditEntryPhotos[title] = [];
    if (_auditEntryPhotos[title].length >= AUDIT_PHOTO_MAX) { alert(`Up to ${AUDIT_PHOTO_MAX} photos per section.`); closeAuditCamera(); return; }
    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext('2d').drawImage(video, 0, 0);
    canvas.toBlob((blob) => {
        if (blob) {
            const file = new File([blob], `audit_capture_${Date.now()}.jpg`, { type: 'image/jpeg' });
            _auditEntryPhotos[title].push({ file, localUrl: URL.createObjectURL(blob), name: file.name });
            _auditDirty = true;
            renderAuditSectionPhotos(sIdx);
        }
        closeAuditCamera();
    }, 'image/jpeg', 0.9);
}

// Upload one image to the audit-photos bucket; returns {url, path, name}.
async function _uploadAuditPhoto(file) {
    const safeName = `${Date.now()}_${Math.round(Math.random() * 1e6)}_${file.name.replace(/[^a-zA-Z0-9._-]/g, '_')}`;
    const resp = await fetch(`${_SUPABASE_URL}/storage/v1/object/audit-photos/${safeName}`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${_SUPABASE_ANON_KEY}`,
            'apikey': _SUPABASE_ANON_KEY,
            'Content-Type': file.type || 'application/octet-stream',
            'x-upsert': 'true',
        },
        body: file,
    });
    if (!resp.ok) throw new Error(await resp.text());
    return { url: `${_SUPABASE_URL}/storage/v1/object/public/audit-photos/${safeName}`, path: safeName, name: file.name };
}

// Everything typed into the entry form right now, keyed by audit item id, so a
// rebuild can put every answer back where it was. Notes and photos already live
// outside the DOM in _auditEntryNotes/_auditEntryPhotos and survive on their own.
function _auditEntrySnapshot() {
    const vals = {};
    document.querySelectorAll('.audit-entry-input').forEach(el => {
        const id = el.getAttribute('data-itemid');
        if (id) vals[id] = el.value;
    });
    return vals;
}

// Is there audit work on screen worth protecting from a rebuild? _auditDirty
// alone isn't enough (a programmatic re-render clears it) and awarded points
// alone aren't either (an audit can be all notes and photos so far), so this
// asks all three.
function _auditHasWork() {
    if (_auditDirty) return true;
    if (document.querySelector('.audit-entry-input') && _auditEntryTotals().earned > 0) return true;
    if (Object.values(_auditEntryNotes || {}).some(v => String(v || '').trim())) return true;
    if (Object.values(_auditEntryPhotos || {}).some(a => Array.isArray(a) && a.length)) return true;
    return false;
}

// Build the collapsible audit checklist. If an audit already exists for the
// selected store AND the chosen date matches it, pre-check its results (edit mode).
//
// opts.preserve keeps what the auditor has already entered — every typed award,
// the section notes and photos, the auditor name and the time — and only rebuilds
// the scaffolding around them. Anything that changes the form WITHOUT changing
// which audit is being filled out (correcting the date, picking up an edited item
// catalog) must pass it: a walkthrough is 165 points of typing and a rebuild that
// silently zeroes it costs the whole visit. Changing the STORE is the one case
// that legitimately starts over, because it's a different audit.
function renderAuditEntry(opts = {}) {
    const container = document.getElementById('audit-entry-container');
    if (!container) return;
    const keep = !!opts.preserve;
    const typed = keep ? _auditEntrySnapshot() : null;
    const dateVal = document.getElementById('dm-score-date')?.value || '';
    const existing = _selectedStoreAudit();
    const prefill = (existing && existing.date === dateVal && existing.results) ? existing.results : {};
    const editingThis = !!(existing && existing.date === dateVal);
    // Which date's SAVED audit is on screen, when nothing has been typed since.
    // A preserving render leaves it alone: it carries the same content across a
    // scaffolding rebuild, and if the auditor had typed anything _auditDirty is
    // already true, which is what actually gates the reader below.
    if (!keep) _auditLoadedDate = editingThis ? dateVal : '';
    if (!keep) {
        _auditEntryNotes = (editingThis && existing.notes && typeof existing.notes === 'object' && !Array.isArray(existing.notes)) ? { ...existing.notes } : {};
        _auditEntryPhotos = {};
        if (editingThis && existing.photos && typeof existing.photos === 'object') {
            Object.entries(existing.photos).forEach(([k, arr]) => { if (Array.isArray(arr)) _auditEntryPhotos[k] = arr.slice(); });
        }
        const auditorEl = document.getElementById('dm-audit-auditor');
        if (auditorEl) auditorEl.value = (editingThis && existing.auditor) ? existing.auditor : '';
        const timeEl = document.getElementById('dm-audit-time');
        if (timeEl) timeEl.value = (editingThis && existing.time) ? existing.time : '';
    }

    let html = '';
    const sections = _auSections();
    sections.forEach((sec, sIdx) => {
        const secTotal = sec.items.reduce((a, i) => a + i.pts, 0);
        html += `<div class="audit-entry-section" style="border:1px solid #e2e8f0; border-radius:10px; margin-bottom:10px; overflow:hidden;">
            <div onclick="toggleAuditEntrySection(${sIdx})" style="display:flex; align-items:center; justify-content:space-between; gap:8px; padding:11px 13px; background:#f8fafc; cursor:pointer;">
                <span style="font-size:12px; font-weight:800; color:var(--slate-charcoal); text-transform:uppercase; letter-spacing:.4px;">${sec.title}</span>
                <span style="display:flex; align-items:center; gap:8px;">
                    <span id="audit-sec-sub-${sIdx}" style="font-size:11px; font-weight:900; color:#64748b; background:#fff; border:1px solid #e2e8f0; padding:3px 0; border-radius:6px; display:inline-block; min-width:56px; text-align:center;">0/${secTotal}</span>
                    <span id="audit-sec-caret-${sIdx}" style="color:#94a3b8; font-size:10px; font-weight:800; transition:transform .2s; transform:rotate(-90deg);">▼</span>
                </span>
            </div>
            <div id="audit-sec-body-${sIdx}" style="display:none; padding:6px 13px 11px;">`;
        sec.items.forEach(item => {
            const aw = _prefillAward(keep && typed[item.id] !== undefined ? typed[item.id] : prefill[item.id], item.pts);
            // Typed number entry, 0..max in half-point steps — quicker than a
            // dropdown when an item is worth several points.
            const control = `<input type="number" class="audit-entry-input" data-section="${sIdx}" data-pts="${item.pts}" data-itemid="${item.id}" value="${aw}" min="0" max="${item.pts}" step="0.5" inputmode="decimal" oninput="onAuditEntryToggle(${sIdx})" onblur="_auditSnapInput(this, ${sIdx})" style="width:58px; padding:5px 6px; font-size:13px; font-weight:800; color:var(--slate-charcoal); border:1px solid #cbd5e1; border-radius:7px; background:#fff; text-align:center;">
                <span style="font-size:10px; font-weight:800; color:#94a3b8; width:26px; text-align:right;">/ ${item.pts}</span>`;
            html += `<div style="display:flex; align-items:center; gap:10px; padding:7px 2px; border-bottom:1px solid #f1f5f9;">
                <span style="flex:1; font-size:12.5px; color:var(--slate-charcoal); line-height:1.4;">${escapeHtml(item.text)}</span>
                <span style="flex-shrink:0; display:flex; align-items:center; justify-content:flex-end; gap:8px; width:100px;">${control}</span>
            </div>`;
        });
        html += `<div style="margin-top:10px; padding-top:11px; border-top:1px dashed #e2e8f0;">
            <label style="display:block; font-size:10.5px; font-weight:800; color:#94a3b8; text-transform:uppercase; letter-spacing:.4px; margin-bottom:5px;">Section notes</label>
            <textarea id="audit-note-${sIdx}" oninput="onAuditNoteInput(${sIdx})" placeholder="Notes for this section (optional)…" style="width:100%; box-sizing:border-box; min-height:50px; resize:vertical; border:1px solid #cbd5e1; border-radius:8px; padding:8px 10px; font-size:12.5px; font-family:inherit; color:var(--slate-charcoal);"></textarea>
            <div style="display:flex; align-items:center; gap:10px; margin-top:8px; flex-wrap:wrap;">
                <label style="display:inline-flex; align-items:center; gap:6px; font-size:11.5px; font-weight:800; color:#475569; background:#f1f5f9; border:1px solid #cbd5e1; border-radius:8px; padding:6px 11px; cursor:pointer;">
                    📷 Add photo(s)
                    <input type="file" accept="image/*" multiple onchange="onAuditPhotoAdd(${sIdx}, this)" style="display:none;">
                </label>
                <button type="button" onclick="openAuditCamera(${sIdx})" style="display:inline-flex; align-items:center; gap:6px; font-size:11.5px; font-weight:800; color:#475569; background:#f1f5f9; border:1px solid #cbd5e1; border-radius:8px; padding:6px 11px; cursor:pointer;">📸 Take photo</button>
                <span id="audit-photo-hint-${sIdx}" style="font-size:11px; color:#94a3b8; font-weight:700;"></span>
            </div>
            <div id="audit-photos-${sIdx}" style="display:flex; flex-wrap:wrap; gap:8px; margin-top:8px;"></div>
        </div>`;
        html += `</div></div>`;
    });
    container.innerHTML = html;

    // Refresh subtotals + running bar; restore any per-section notes/photos.
    sections.forEach((sec, sIdx) => {
        onAuditEntryToggle(sIdx, true);
        const ta = document.getElementById(`audit-note-${sIdx}`);
        if (ta) ta.value = _auditEntryNotes[sec.title] || '';
        renderAuditSectionPhotos(sIdx);
    });
    updateAuditRunningBar();
    // A fresh render is a clean slate — but a preserving one carried unsaved work
    // across, so it must not report that work as saved.
    if (!keep) _auditDirty = false;
}

// Blur handler for the typed award: snap to the half-point grid and clamp to
// the item's max, writing the cleaned value back into the box.
function _auditSnapInput(el, sIdx) {
    const pts = parseFloat(el.getAttribute('data-pts')) || 0;
    const v = parseFloat(el.value);
    el.value = Number.isFinite(v) ? Math.min(Math.max(Math.round(v * 2) / 2, 0), pts) : 0;
    onAuditEntryToggle(sIdx);
}

// Clamp a stored result value (boolean legacy or number) to 0..pts, snapped
// to the half-point grid.
function _prefillAward(v, pts) {
    if (v === true) return pts;
    const num = Number(v);
    return Number.isFinite(num) ? Math.min(Math.max(Math.round(num * 2) / 2, 0), pts) : 0;
}

// Points awarded by one entry control (checkbox = 0|pts, select = its value).
// Half-point values (e.g. 0.5, 2.5) are valid.
function _auditItemAward(el) {
    const pts = parseInt(el.getAttribute('data-pts')) || 0;
    if (el.type === 'checkbox') return el.checked ? pts : 0;
    const v = parseFloat(el.value);
    return Number.isFinite(v) ? Math.min(Math.max(Math.round(v * 2) / 2, 0), pts) : 0;
}

// One section open at a time — opening a section collapses the others.
function toggleAuditEntrySection(sIdx) {
    const body = document.getElementById(`audit-sec-body-${sIdx}`);
    const caret = document.getElementById(`audit-sec-caret-${sIdx}`);
    if (!body) return;
    const isOpen = body.style.display === 'block';
    document.querySelectorAll('[id^="audit-sec-body-"]').forEach(el => { el.style.display = 'none'; });
    document.querySelectorAll('[id^="audit-sec-caret-"]').forEach(el => { el.style.transform = 'rotate(-90deg)'; });
    if (!isOpen) {
        body.style.display = 'block';
        if (caret) caret.style.transform = 'rotate(0deg)';
    }
}

// Recompute one section's subtotal; if not a silent refresh, also bump the running bar.
function onAuditEntryToggle(sIdx, silent) {
    const sec = _auSections()[sIdx];
    if (!sec) return;
    if (!silent) _auditDirty = true; // silent = programmatic refresh, not typing
    const secTotal = sec.items.reduce((a, i) => a + i.pts, 0);
    let earned = 0;
    document.querySelectorAll(`.audit-entry-input[data-section="${sIdx}"]`).forEach(el => { earned += _auditItemAward(el); });
    const sub = document.getElementById(`audit-sec-sub-${sIdx}`);
    if (sub) {
        sub.textContent = `${earned}/${secTotal}`;
        const full = earned === secTotal;
        sub.style.color = full ? '#059669' : (earned > 0 ? '#d97706' : '#64748b');
    }
    if (!silent) updateAuditRunningBar();
}

function _auditEntryTotals() {
    let earned = 0;
    document.querySelectorAll('.audit-entry-input').forEach(el => { earned += _auditItemAward(el); });
    return { earned, possible: _auditPossibleNow() };
}

function updateAuditRunningBar() {
    const bar = document.getElementById('dm-audit-runningbar');
    if (!bar) return;
    const { earned, possible } = _auditEntryTotals();
    const pct = possible ? Math.round((earned / possible) * 1000) / 10 : 0;
    // Neutral (not alarming red) until the auditor starts checking items.
    const started = earned > 0;
    const c = started ? auditPctColor(pct) : { bg: '#f1f5f9', fg: '#64748b' };
    const verdict = !started ? 'Not started — check items as you walk the store'
        : (pct >= AUDIT_PASS_PCT ? (pct >= AUDIT_TARGET_PCT ? 'On target' : 'Passing') : 'Below pass')
          + ` · pass ${AUDIT_PASS_PCT}% · target ${AUDIT_TARGET_PCT}%+`;
    bar.innerHTML = `
        <div style="display:flex; align-items:center; justify-content:space-between; gap:10px; background:${c.bg}; border-radius:10px; padding:10px 13px;">
            <span style="font-size:12px; font-weight:800; color:${c.fg}; text-transform:uppercase; letter-spacing:.4px;">Live Audit Score</span>
            <span style="font-size:18px; font-weight:900; color:${c.fg};">${earned}/${possible} <span style="font-size:13px;">(${pct}%)</span></span>
        </div>
        <div style="height:7px; border-radius:6px; background:#eef2f6; overflow:hidden; margin-top:6px;"><div style="height:100%; width:${pct}%; background:${c.fg}; border-radius:6px; transition:width .2s;"></div></div>
        <div style="font-size:10.5px; color:#94a3b8; font-weight:700; margin-top:4px;">${verdict}</div>`;
}

async function submitNewAudit() {
    const store = document.getElementById('dm-store-select').value;
    const date = document.getElementById('dm-score-date').value;
    const auditor = (document.getElementById('dm-audit-auditor')?.value || '').trim()
        || sessionStorage.getItem('speeksUserName') || null;
    const time = document.getElementById('dm-audit-time')?.value || null; // HH:MM or null
    const btn = document.getElementById('submitAuditBtn');
    if (!store || !date) { alert('Pick a store and date.'); return; }

    const results = {};
    document.querySelectorAll('.audit-entry-input').forEach(el => {
        results[el.getAttribute('data-itemid')] = _auditItemAward(el);
    });

    // Per-section notes (skip blanks).
    const sectionNotes = {};
    Object.entries(_auditEntryNotes).forEach(([k, v]) => {
        if (v && String(v).trim()) sectionNotes[k] = String(v).trim();
    });

    btn.disabled = true;
    btn.style.opacity = '0.7';

    // Upload any newly-added photos; keep already-uploaded ones (edit mode) as-is.
    const sectionPhotos = {};
    try {
        for (const [section, arr] of Object.entries(_auditEntryPhotos)) {
            const out = [];
            for (const p of (arr || [])) {
                if (p.path && p.url) { out.push({ url: p.url, path: p.path, name: p.name || '' }); continue; }
                if (p.file) { btn.innerText = 'Uploading photos…'; out.push(await _uploadAuditPhoto(p.file)); }
            }
            if (out.length) sectionPhotos[section] = out;
        }
    } catch (e) {
        alert('Photo upload failed: ' + (e.message || e));
        btn.innerText = 'Save Audit'; btn.style.opacity = ''; btn.disabled = false;
        return;
    }

    btn.innerText = 'Saving...';
    try {
        const res = await fetch(SCORECARD_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            // submittedBy is the logged-in person, deliberately separate from
            // auditor: auditor is typed and names who walked the store, which may
            // be somebody else. Only the person clicking Save should be dropped
            // from the alert.
            body: JSON.stringify({ action: 'submit_audit', store, date, auditor, time, results, sectionNotes, sectionPhotos,
                submittedBy: sessionStorage.getItem('speeksUserName') || null })
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Save failed');
        btn.innerText = `Saved — ${json.earned}/${json.possible} (${json.pct}%)`;
        btn.style.background = 'var(--sage-professional)';
        _auditDirty = false; // saved — nothing left to lose on close
        setTimeout(() => {
            if (typeof fetchScorecardData === 'function') fetchScorecardData();
            if (typeof fetchMasterDistrictDashboard === 'function') fetchMasterDistrictDashboard();
            closeScorecardModal();
            btn.innerText = 'Save Audit';
            btn.style.background = '';
            btn.style.opacity = '';
            btn.disabled = false;
        }, 1400);
    } catch (err) {
        alert('Error saving audit: ' + (err.message || err));
        btn.innerText = 'Save Audit';
        btn.style.background = '';
        btn.style.opacity = '';
        btn.disabled = false;
    }
}

// ============================================================================
// MANAGE ITEMS TAB (DM/CEO) — add / pause / delete catalog items for both
// instruments. Pausing hides an item from scoring and the totals but keeps
// history; deleting removes it from the checklist going forward (past audits
// still render it via AUDIT_ITEM_MAP / stored results).
// ============================================================================

async function _scorecardAdminPost(payload) {
    const res = await fetch(SCORECARD_URL, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...payload, role: sessionStorage.getItem('speeksUserRole') || '' }),
    });
    const json = await res.json().catch(() => ({}));
    if (!res.ok || json.success === false) throw new Error(json.error || 'Request failed');
    return json;
}

// Refetch the catalog after any change, then re-render everything that shows it.
async function _refreshScCatalog() {
    try {
        const res = await fetch(`${SCORECARD_URL}?v=${Date.now()}`);
        const json = await res.json();
        if (json && json.success) {
            window._scorecardAllData = json.data || [];
            if (json.catalog) {
                window._scCatalog = json.catalog.scorecard_items || [];
                window._auCatalog = json.catalog.audit_items || [];
            }
        }
    } catch (e) { /* keep whatever catalog we had */ }
    renderManageItems();
    _buildScorecardModalInputs();
    // Editing the item catalog mid-audit has to show the new items without
    // throwing away the answers already entered against the old ones.
    renderAuditEntry({ preserve: _auditHasWork() });
}

function renderManageItems() {
    const panel = document.getElementById('sc-panel-manage');
    if (!panel) return;
    if (!window._scCatalog || !window._auCatalog) {
        panel.innerHTML = '<div class="status-message">Loading item catalog…</div>';
        _ensureScCatalog();
        return;
    }
    const scRows = _scCats(true);
    const auSections = _auSections(true);
    const activeAu = (window._auCatalog || []).filter(i => i.active);
    const activePts = activeAu.reduce((a, i) => a + (Number(i.points) || 0), 0);

    const secHdr = t => `<div style="font-size:11px; font-weight:900; color:#94a3b8; text-transform:uppercase; letter-spacing:.5px; margin:16px 0 6px;">${t}</div>`;
    const inp = 'padding:8px 10px; border:1.5px solid #cbd5e1; border-radius:8px; font-size:12.5px; font-weight:600; background:#fff; box-sizing:border-box;';
    const rowStyle = active => `display:flex; align-items:center; gap:9px; padding:7px 4px; border-bottom:1px solid #f1f5f9; ${active ? '' : 'opacity:.45;'}`;
    const delBtn = (fn, id, label) => `<button onclick="${fn}('${id}', this)" title="Delete ${label} — past scores keep their history" style="flex:none; display:inline-flex; align-items:center; justify-content:center; width:26px; height:26px; background:#fff5f5; border:1.5px solid #fecaca; border-radius:7px; cursor:pointer; font-size:13px; line-height:1;">🗑</button>`;
    const pauseBox = (fn, id, active) => `<input type="checkbox" ${active ? 'checked' : ''} onchange="${fn}('${id}', this.checked, this)" title="${active ? 'Active — untick to pause (hidden from scoring, history kept)' : 'Paused — tick to reactivate'}" style="flex:none; width:16px; height:16px; cursor:pointer; accent-color:#059669;">`;

    let html = `<div style="font-size:12px; color:#64748b; font-weight:600; margin-bottom:2px;">Tick = active. Unticking <b>pauses</b> an item — it disappears from scoring and the totals but keeps its history. 🗑 deletes it from the checklist going forward.</div>`;

    // ---- Scorecard categories ----
    html += secHdr(`Scorecard Categories (scored 0–5)`);
    scRows.forEach(c => {
        html += `<div style="${rowStyle(c.active)}">
            ${pauseBox('scToggleItem', c.id, c.active)}
            <span style="flex:1; font-size:12.5px; font-weight:700; color:var(--slate-charcoal);">${escapeHtml(c.label)}</span>
            <span style="flex:none; font-size:10.5px; font-weight:800; color:#94a3b8;">/ ${Number(c.max_score) || 5}</span>
            ${delBtn('scDeleteItem', c.id, 'this category')}
        </div>`;
    });
    html += `<div style="display:flex; gap:8px; margin-top:8px;">
        <input id="sc-add-label" placeholder="New category name" style="${inp} flex:1;">
        <button class="btn-secondary" onclick="scAddItem(this)" style="flex:none;">+ Add</button>
    </div>`;

    // ---- Audit items ----
    html += secHdr(`SPEEKS Audit Items — active: ${activeAu.length} items · ${activePts} pts`);
    auSections.forEach(sec => {
        html += `<div style="font-size:10.5px; font-weight:800; color:#64748b; text-transform:uppercase; letter-spacing:.4px; margin:10px 0 2px;">${escapeHtml(sec.title)}</div>`;
        sec.items.forEach(item => {
            html += `<div style="${rowStyle(item.active !== false)}">
                ${pauseBox('auToggleItem', item.dbId, item.active !== false)}
                <span style="flex:1; font-size:12px; color:var(--slate-charcoal); line-height:1.35;">${escapeHtml(item.text)}</span>
                <span style="flex:none; font-size:10.5px; font-weight:800; color:#94a3b8;">${item.pts} pt${item.pts === 1 ? '' : 's'}</span>
                ${delBtn('auDeleteItem', item.dbId, 'this item')}
            </div>`;
        });
    });
    const secOpts = auSections.map(s => `<option value="${escapeHtml(s.title)}">${escapeHtml(s.title)}</option>`).join('')
        + `<option value="__new">+ New section…</option>`;
    html += `<div style="margin-top:10px; background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px; padding:12px;">
        <div style="font-size:11px; font-weight:900; color:#64748b; text-transform:uppercase; letter-spacing:.4px; margin-bottom:8px;">Add an audit item</div>
        <div style="display:flex; gap:8px; flex-wrap:wrap;">
            <select id="au-add-section" onchange="document.getElementById('au-add-section-new').style.display = this.value === '__new' ? '' : 'none';" style="${inp} flex:1; min-width:140px; cursor:pointer;">${secOpts}</select>
            <input id="au-add-section-new" placeholder="New section name" style="${inp} flex:1; min-width:140px; display:none;">
        </div>
        <div style="display:flex; gap:8px; margin-top:8px;">
            <input id="au-add-text" placeholder="What is being checked?" style="${inp} flex:1;">
            <input id="au-add-pts" type="number" min="1" step="1" value="1" title="Points" style="${inp} width:64px; flex:none; text-align:center;">
            <button class="btn-secondary" onclick="auAddItem(this)" style="flex:none;">+ Add</button>
        </div>
    </div>`;

    panel.innerHTML = html;
}

function _manageActionFail(e) {
    alert('Could not save that change: ' + (e.message || e));
    renderManageItems();
}

function scToggleItem(id, active) {
    _scorecardAdminPost({ action: 'scorecard_item_upsert', id, active }).then(_refreshScCatalog).catch(_manageActionFail);
}
function scDeleteItem(id) {
    const item = (window._scCatalog || []).find(c => String(c.id) === String(id));
    if (!confirm(`Delete "${item ? item.label : 'this category'}"? Past scorecards keep their history; the category just stops being scored. To hide it temporarily, pause it instead.`)) return;
    _scorecardAdminPost({ action: 'scorecard_item_delete', id }).then(_refreshScCatalog).catch(_manageActionFail);
}
function scAddItem(btn) {
    const label = (document.getElementById('sc-add-label')?.value || '').trim();
    if (!label) { alert('Enter a name for the new category.'); return; }
    btn.disabled = true;
    _scorecardAdminPost({ action: 'scorecard_item_upsert', label, max_score: 5 })
        .then(_refreshScCatalog).catch(_manageActionFail).finally(() => { btn.disabled = false; });
}

function auToggleItem(id, active) {
    _scorecardAdminPost({ action: 'audit_item_upsert', id, active }).then(_refreshScCatalog).catch(_manageActionFail);
}
function auDeleteItem(id) {
    const item = (window._auCatalog || []).find(c => String(c.id) === String(id));
    if (!confirm(`Delete "${item ? item.item_text : 'this item'}"? Past audits keep their history; the item just leaves the checklist. To hide it temporarily, pause it instead.`)) return;
    _scorecardAdminPost({ action: 'audit_item_delete', id }).then(_refreshScCatalog).catch(_manageActionFail);
}
function auAddItem(btn) {
    const selEl = document.getElementById('au-add-section');
    let section = selEl ? selEl.value : '';
    if (section === '__new') section = (document.getElementById('au-add-section-new')?.value || '').trim();
    const text = (document.getElementById('au-add-text')?.value || '').trim();
    const points = Math.max(1, parseInt(document.getElementById('au-add-pts')?.value) || 1);
    if (!section) { alert('Pick or name a section.'); return; }
    if (!text) { alert('Describe what the item checks.'); return; }
    btn.disabled = true;
    _scorecardAdminPost({ action: 'audit_item_upsert', section, item_text: text, points })
        .then(_refreshScCatalog).catch(_manageActionFail).finally(() => { btn.disabled = false; });
}

// 'HH:MM' (24h, as stored) → '2:30 PM' for display; '' when unset/invalid.
function _fmtAuditTime(t) {
    const m = /^(\d{1,2}):(\d{2})/.exec(String(t || ''));
    if (!m) return '';
    let h = parseInt(m[1], 10);
    const ampm = h >= 12 ? 'PM' : 'AM';
    h = h % 12 || 12;
    return `${h}:${m[2]} ${ampm}`;
}

// ---- Read-only Audit Breakdown popout (reused by every display site) ----
function openAuditBreakdown(store) {
    renderAuditBreakdown(store);
    toggleModal('auditBreakdownModal');   // closes any open modal, then shows this one + backdrop
}
function closeAuditBreakdown() {
    closeAllModals();
}

// Render a saved section note for display: lines beginning with -, * or •
// become real bullet points; other lines keep their line breaks. Notes are
// stored as the raw textarea text, so this is display-only — editing an
// audit still shows (and saves) exactly what was typed.
function _auditNoteHtml(note) {
    const lines = String(note).split(/\r?\n/);
    let html = '';
    let bullets = [];
    const flush = () => {
        if (!bullets.length) return;
        html += `<ul style="margin:2px 0; padding-left:18px;">${bullets.map(t => `<li style="margin:1px 0;">${escapeHtml(t)}</li>`).join('')}</ul>`;
        bullets = [];
    };
    lines.forEach(raw => {
        const line = raw.trim();
        if (!line) { flush(); return; }
        const m = line.match(/^[-*•]\s*(.*)$/);
        if (m) bullets.push(m[1]);
        else { flush(); html += `<div>${escapeHtml(line)}</div>`; }
    });
    flush();
    return html;
}

function renderAuditBreakdown(store) {
    const body = document.getElementById('audit-breakdown-body');
    const title = document.getElementById('audit-breakdown-title');
    if (!body) return;
    const entry = (window._scorecardAllData || []).find(d => String(d.store).toUpperCase() === String(store).toUpperCase());
    const audit = entry && entry.audit ? entry.audit : null;

    if (!audit) {
        if (title) title.textContent = `${store} · SPEEKS Audit Breakdown`;
        body.innerHTML = `<div style="padding:24px 4px; text-align:center; color:#94a3b8; font-weight:600;">No practice audit on file for ${store} yet.</div>`;
        return;
    }
    const results = audit.results || {};
    const c = auditPctColor(audit.pct);
    const dateStr = audit.date ? new Date(audit.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '';
    if (title) title.textContent = `${store} · SPEEKS Audit Breakdown`;

    let html = `<div style="display:flex; align-items:center; justify-content:space-between; gap:10px; background:${c.bg}; border-radius:10px; padding:12px 14px; margin-bottom:14px;">
        <div>
            <div style="font-size:11px; font-weight:800; color:${c.fg}; text-transform:uppercase; letter-spacing:.4px;">SPEEKS Audit${dateStr ? ' · ' + dateStr : ''}${audit.time ? ' · ' + _fmtAuditTime(audit.time) : ''}${audit.auditor ? ' · ' + escapeHtml(audit.auditor) : ''}</div>
            <div style="font-size:11px; color:#64748b; font-weight:600; margin-top:2px;">Pass ${AUDIT_PASS_PCT}% · Target ${AUDIT_TARGET_PCT}%+${audit.prevPct != null ? ` · prev ${audit.prevPct}%` : ''}</div>
        </div>
        <div style="font-size:22px; font-weight:900; color:${c.fg};">${audit.earned}/${audit.possible} <span style="font-size:14px;">(${audit.pct}%)</span></div>
    </div>`;

    // Sections from the live catalog, but keep any items this audit scored
    // that were since paused/removed — history must still render.
    const sections = _auSections().map(s => ({ title: s.title, items: s.items.slice() }));
    const known = new Set();
    sections.forEach(s => s.items.forEach(i => known.add(i.id)));
    const orphans = Object.keys(results).filter(id => !known.has(id) && AUDIT_ITEM_MAP[id]);
    orphans.forEach(id => {
        const meta = AUDIT_ITEM_MAP[id];
        let sec = sections.find(s => s.title === meta.section);
        if (!sec) { sec = { title: meta.section, items: [] }; sections.push(sec); }
        sec.items.push({ id, pts: meta.pts, text: meta.text });
    });

    sections.forEach(sec => {
        const secTotal = sec.items.reduce((a, i) => a + i.pts, 0);
        let secEarned = 0;
        sec.items.forEach(i => { secEarned += _prefillAward(results[i.id], i.pts); });
        const secFull = secEarned === secTotal;
        html += `<div style="margin-bottom:12px;">
            <div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:5px;">
                <span style="font-size:11px; font-weight:800; color:#94a3b8; text-transform:uppercase; letter-spacing:.5px;">${sec.title}</span>
                <span style="font-size:11px; font-weight:900; color:${secFull ? '#059669' : (secEarned > 0 ? '#d97706' : '#dc2626')};">${secEarned}/${secTotal}</span>
            </div>`;
        sec.items.forEach(item => {
            const aw = _prefillAward(results[item.id], item.pts);
            const full = aw === item.pts, none = aw === 0;
            const icon = full ? '✓' : (none ? '✗' : '◐');
            const iconColor = full ? '#16a34a' : (none ? '#dc2626' : '#d97706');
            const valColor = full ? '#16a34a' : (none ? '#cbd5e1' : '#d97706');
            html += `<div style="display:flex; align-items:flex-start; gap:9px; padding:4px 2px;">
                <span style="font-size:13px; font-weight:900; line-height:1.3; color:${iconColor}; flex-shrink:0;">${icon}</span>
                <span style="font-size:12px; color:${full ? '#94a3b8' : 'var(--slate-charcoal)'}; line-height:1.4; flex:1; ${full ? '' : 'font-weight:600;'}">${escapeHtml(item.text)}</span>
                <span style="font-size:11px; font-weight:800; color:${valColor}; flex-shrink:0;">${aw}/${item.pts}</span>
            </div>`;
        });
        const secNote = (audit.notes && !Array.isArray(audit.notes)) ? audit.notes[sec.title] : null;
        const secPhotos = (audit.photos && !Array.isArray(audit.photos)) ? audit.photos[sec.title] : null;
        if (secNote && String(secNote).trim()) {
            html += `<div style="margin-top:6px; background:#f8fafc; border:1px solid #e2e8f0; border-left:3px solid #94a3b8; border-radius:7px; padding:7px 10px; font-size:12px; color:var(--slate-charcoal); line-height:1.45;"><div style="font-weight:800; color:#64748b; font-size:11px; margin-bottom:2px;">📝 Notes</div>${_auditNoteHtml(secNote)}</div>`;
        }
        if (Array.isArray(secPhotos) && secPhotos.length) {
            html += `<div style="display:flex; flex-wrap:wrap; gap:6px; margin-top:6px;">` + secPhotos.map(p => {
                const src = (p && p.url) ? p.url : '';
                return src ? `<img src="${src}" onclick="openAuditPhotoLightbox('${src}')" style="width:56px; height:56px; object-fit:cover; border-radius:6px; border:1px solid #e2e8f0; cursor:pointer;" alt="">` : '';
            }).join('') + `</div>`;
        }
        html += `</div>`;
    });
    body.innerHTML = html;
}

// Audit summary block for the manager Store Scorecard widget: score + trend +
// missed points + a button into the full breakdown popout.
function buildAuditSummaryHtml(audit, store) {
    if (!audit) {
        return `<div style="display:flex; align-items:center; justify-content:space-between;">
                <span class="scorecard-label" style="text-align:left;">SPEEKS Audit</span>
                <span style="font-size:12px; color:#94a3b8; font-weight:700;">No practice audit yet</span>
            </div>`;
    }
    const c = auditPctColor(audit.pct);
    const dateStr = audit.date ? new Date(audit.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '';
    let trend = '';
    if (audit.prevPct != null) {
        const delta = Math.round((audit.pct - audit.prevPct) * 10) / 10;
        const up = delta >= 0;
        trend = `<span style="font-size:11px; font-weight:800; color:${up ? '#16a34a' : '#dc2626'};">${up ? '▲' : '▼'} ${Math.abs(delta)}%</span>`;
    }

    return `<div style="display:flex; align-items:center; justify-content:space-between; gap:8px;">
            <div>
                <div class="scorecard-label" style="text-align:left; margin-bottom:2px;">SPEEKS Audit</div>
                <div class="scorecard-date" style="font-size:11px;">${dateStr}${audit.time ? ' · ' + _fmtAuditTime(audit.time) : ''}${audit.auditor ? ' · ' + escapeHtml(audit.auditor) : ''}</div>
            </div>
            <div style="display:flex; align-items:center; gap:8px;">
                ${trend}
                <span style="font-size:16px; font-weight:900; background:${c.bg}; color:${c.fg}; padding:4px 10px; border-radius:8px;">${audit.earned}/${audit.possible} · ${audit.pct}%</span>
            </div>
        </div>
        <button onclick="openAuditBreakdown('${store}')" class="btn-secondary" style="margin-top:10px; width:100%; padding:8px; font-size:12px; font-weight:800;">SPEEKS Audit Breakdown</button>`;
}

// =========================================================
//  SHOPIFY INSURANCE CLAIMS / ITEM-NOT-RECEIVED TOOL
//  Store managers + owner-managers + multi-store managers log
//  claims here. A manager sees their store's cases; a Multi-Store
//  Manager sees every store they manage, from either dashboard.
// =========================================================
const CLAIM_STATUS = {
    in_progress: { label: 'In Progress', bg: '#fef3c7', fg: '#b45309' },
    recovered:   { label: 'Recovered',   bg: '#d1fae5', fg: '#059669' },
    denied:      { label: 'Denied',      bg: '#fee2e2', fg: '#dc2626' },
};

// Which store(s) this user can file/view claims for.
function _claimStores() {
    if (typeof isMultiStoreManager === 'function' && isMultiStoreManager()) {
        return [...MULTISTORE_MANAGER_STORES];
    }
    const s = (sessionStorage.getItem('speeksUserStore') || '').toUpperCase();
    return (s && s !== 'ALL' && s !== 'CORP') ? [s] : [];
}

function openClaimsModal() {
    toggleModal('claimsModal');
    _buildClaimStorePicker();
    ['claim-case-number', 'claim-sku', 'claim-price', 'claim-cost', 'claim-detail'].forEach(id => {
        const el = document.getElementById(id); if (el) el.value = '';
    });
    const r = document.getElementById('claim-reason'); if (r) r.selectedIndex = 0;
    const ct = document.getElementById('claim-type'); if (ct) ct.selectedIndex = 0;
    _onClaimReasonChange();
    switchClaimsTab('new');
}

// "Claim Type" (Damage / Loss) only applies to a Claim, not an Item-Not-Received case.
function _onClaimReasonChange() {
    const reason = (document.getElementById('claim-reason') || {}).value;
    const wrap = document.getElementById('claim-type-wrap');
    if (wrap) wrap.style.display = reason !== 'Item Not Received' ? 'block' : 'none';
}

function switchClaimsTab(tab) {
    const nb = document.getElementById('claims-tab-new');
    const vb = document.getElementById('claims-tab-view');
    if (nb) nb.classList.toggle('active', tab === 'new');
    if (vb) vb.classList.toggle('active', tab === 'view');
    const np = document.getElementById('claims-panel-new');
    const vp = document.getElementById('claims-panel-view');
    if (np) np.style.display = tab === 'new' ? 'block' : 'none';
    if (vp) vp.style.display = tab === 'view' ? 'block' : 'none';
    const sb = document.getElementById('submitClaimBtn');
    if (sb) sb.style.display = tab === 'new' ? '' : 'none';
    if (tab === 'view') fetchMyClaims();
}

// MSM gets a store chooser; a single-store manager is locked to their store.
function _buildClaimStorePicker() {
    const row = document.getElementById('claims-store-row');
    const sel = document.getElementById('claim-store');
    if (!sel) return;
    const stores = _claimStores();
    sel.innerHTML = stores.map(s => `<option value="${s}">${s}</option>`).join('');
    const multi = stores.length > 1;
    sel.disabled = !multi;
    sel.style.opacity = multi ? '1' : '0.7';
    sel.style.cursor = multi ? 'pointer' : 'not-allowed';
    if (row) row.style.display = stores.length ? 'block' : 'none';
    // Default to the store this open targets for an MSM — a single-store alert
    // override if pending, else the active dashboard store; everyone else keeps
    // their only option. Still switchable via the dropdown when multi-store.
    const def = _msmToolStore();
    if (def && [...sel.options].some(o => o.value === def)) sel.value = def;
    else if (sel.options.length) sel.selectedIndex = 0;
}

async function submitClaim() {
    const val = id => (document.getElementById(id) || {}).value;
    const store = (val('claim-store') || '').toUpperCase();
    const caseNumber = (val('claim-case-number') || '').trim();
    const sku = (val('claim-sku') || '').trim();
    const priceRaw = val('claim-price');
    const costRaw = val('claim-cost');
    const reason = val('claim-reason');
    const claimType = val('claim-type');
    const detail = (val('claim-detail') || '').trim();
    const status = 'in_progress'; // a ticket is always open the moment it's created

    // Every claim type (Shopify / USPS / UPS) carries its Damage/Loss type;
    // only Item Not Received stands alone.
    const reasonType = reason !== 'Item Not Received' ? `${reason} — ${claimType}` : reason;

    if (!store) { alert('Please select a store for this case.'); return; }
    if (!caseNumber) { alert('Please enter a case number.'); return; }

    const num = v => (v === '' || v == null) ? null : Number(v);
    const btn = document.getElementById('submitClaimBtn');
    const old = btn ? btn.innerText : '';
    if (btn) { btn.disabled = true; btn.innerText = 'Saving…'; }
    try {
        const res = await fetch(CLAIMS_URL, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'submit_claim', store, case_number: caseNumber, item_sku: sku,
                price: num(priceRaw), cost: num(costRaw),
                reason_type: reasonType, reason_detail: detail || null, status,
                created_by: sessionStorage.getItem('speeksUserName') || null,
            }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Save failed');
        switchClaimsTab('view'); // jump to My Cases so they see it landed
    } catch (e) {
        alert('Could not save the case: ' + e.message);
    } finally {
        if (btn) { btn.disabled = false; btn.innerText = old; }
    }
}

let _claimsAll = []; // last fetched cases, so the MSM store filter can re-render without refetching

async function fetchMyClaims() {
    const wrap = document.getElementById('claims-table-wrap');
    if (!wrap) return;
    const stores = _claimStores();
    if (!stores.length) {
        wrap.innerHTML = '<div style="padding:24px; text-align:center; color:#94a3b8; font-weight:600;">No store assigned to your account.</div>';
        return;
    }
    wrap.innerHTML = '<div style="padding:24px; text-align:center; color:#94a3b8; font-weight:600;">Loading cases…</div>';
    try {
        const res = await fetch(`${CLAIMS_URL}?stores=${encodeURIComponent(stores.join(','))}&v=${Date.now()}`);
        const json = await res.json();
        if (!json.success) throw new Error(json.error);
        _claimsAll = json.data || [];
        _buildClaimsViewFilter(stores);
        renderClaimsTable();
    } catch (e) {
        wrap.innerHTML = '<div style="color:var(--red-alert); padding:24px; text-align:center; font-weight:700;">Error loading cases.</div>';
    }
}

// MSM-only: a store filter on the My Cases tab (single-store managers don't need it).
function _buildClaimsViewFilter(stores) {
    const row = document.getElementById('claims-view-filter-row');
    const sel = document.getElementById('claims-view-filter');
    if (!row || !sel) return;
    if (stores.length <= 1) { row.style.display = 'none'; return; }
    row.style.display = 'block';
    const current = sel.value;
    sel.innerHTML = `<option value="">All stores</option>` +
        stores.map(s => `<option value="${s}">${s}</option>`).join('');
    if ([...sel.options].some(o => o.value === current)) sel.value = current;
}

function renderClaimsTable() {
    const wrap = document.getElementById('claims-table-wrap');
    if (!wrap) return;
    const stores = _claimStores();
    const multi = stores.length > 1;
    const filterStore = (document.getElementById('claims-view-filter') || {}).value || '';
    const filterStatus = (document.getElementById('claims-status-filter') || {}).value || '';
    let rows = _claimsAll;
    if (filterStore) rows = rows.filter(r => (r.store || '').toUpperCase() === filterStore);
    const showStore = multi && !filterStore; // store column only matters when mixing stores
    const colCount = (showStore ? 1 : 0) + 10; // # column + 9 base

    // A follow-up loss claim is a real claim row with parent_id pointing at the
    // Item-Not-Received ticket it came from. Render it nested under its parent.
    const byId = {}; rows.forEach(r => { byId[r.id] = r; });
    const kidsOf = {}; rows.forEach(r => { if (r.parent_id) (kidsOf[r.parent_id] = kidsOf[r.parent_id] || []).push(r); });
    // Status filter applies to top-level claims; their child claims render alongside.
    let tops = rows.filter(r => !r.parent_id || !byId[r.parent_id]);
    if (filterStatus) tops = tops.filter(r => r.status === filterStatus);
    // Needs-attention first: over-7-day open → other open → escalated INRs → resolved;
    // newest first within each group. (An INR with a child loss claim isn't "aging".)
    const clRank = r => {
        if (r.status !== 'in_progress') return 3;
        if ((kidsOf[r.id] || []).length) return 2;
        if (_isClaimAging(r)) return 0;
        return 1;
    };
    tops.sort((a, b) => clRank(a) - clRank(b) || new Date(b.created_at) - new Date(a.created_at));

    if (!tops.length) {
        wrap.innerHTML = '<div style="padding:28px 20px; text-align:center; color:#94a3b8; font-weight:600;">No cases match this view.</div>';
        return;
    }
    const th = t => `<th style="text-align:left; font-size:9.5px; font-weight:800; text-transform:uppercase; letter-spacing:.4px; color:#94a3b8; padding:8px 10px; border-bottom:1px solid #e2e8f0; white-space:nowrap;">${t}</th>`;
    let html = `<div style="overflow-x:auto;"><table style="width:100%; border-collapse:collapse; font-size:12.5px;">
        <thead><tr>${th('#')}${showStore ? th('Store') : ''}${th('Case #')}${th('SKU')}${th('Value')}${th('Cost')}${th('Reason')}${th('Status')}${th('Created')}${th('Resolved')}${th('')}</tr></thead><tbody>`;
    let n = 0;
    tops.forEach(r => {
        const kids = kidsOf[r.id] || [];
        const isINR = String(r.reason_type || '').toLowerCase().startsWith('item not received');
        const canEscalate = isINR && !kids.length; // one loss claim per INR ticket
        n++;
        html += _claimRowHtml(r, showStore, false, canEscalate, kids.length > 0, `${n}`);
        if (canEscalate) html += _escalateFormRow(r, colCount);
        kids.forEach((k, ci) => { html += _claimRowHtml(k, showStore, true, false, false, `${n}.${ci + 1}`); });
    });
    html += '</tbody></table></div>';
    wrap.innerHTML = html;
}

// ── Shared copy chip ───────────────────────────────────────────────────────
// A 📋 button beside an identifier whose whole job is to be pasted somewhere
// else: a claim case number into a carrier's status lookup, a recycle SKU into
// inventory. Styling is .site-copy in styles.css — one definition, so a
// copyable value looks and behaves the same in every tool.
//
// `what` names the value in the tooltip, the screen-reader label and the
// failure message, so the fallback tells you WHICH thing to copy by hand.
//
// Both the copy mark and the success check live in one SVG; CSS shows one at a
// time. Line-icon style with stroke-width 2.4 to match the nav icons — at 12px
// a thinner stroke greys out.
const _SITE_COPY_SVG =
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<g class="site-copy-mark-copy"><rect x="9" y="9" width="12" height="12" rx="2.5"/>'
    + '<path d="M6 15H4.5A1.5 1.5 0 0 1 3 13.5v-9A1.5 1.5 0 0 1 4.5 3h9A1.5 1.5 0 0 1 15 4.5V6"/></g>'
    + '<polyline class="site-copy-mark-ok" points="20 6 10 17 5 12"/></svg>';

function siteCopyBtn(value, what) {
    const v = String(value ?? '').trim();
    if (!v) return '';
    const label = escapeHtml(what || 'value');
    // No whitespace between the value and this button at any call site: with no
    // break opportunity there, the icon can never be orphaned onto its own line
    // even when the column is narrow enough that the value itself wraps.
    return `<button type="button" class="site-copy" data-copy="${escapeHtml(v)}" data-what="${label}"`
        + ` title="Copy ${label}" aria-label="Copy ${label}" onclick="siteCopy(event, this)">${_SITE_COPY_SVG}</button>`;
}

// A SKU / identifier value for a table cell. Never wrap one of these in
// white-space:nowrap: SKU fields are free text and stores really do paste
// several SKUs into a single line, and one unbreakable 224-character value is
// enough to widen its column past the modal, push every later column
// off-screen, and crush the neighbouring prose column to a few characters wide.
// The cap bounds the column's max-content width so it can never dominate, and
// overflow-wrap:anywhere means even a long value with no spaces wraps rather
// than pushes. A normal SKU sits well under the cap and still never breaks at
// its own hyphens, so it stays readable and copyable in one piece.
// `min` is the floor the column may not be squeezed below. overflow-wrap:anywhere
// is what stops a pathological SKU widening the column, but it does it by telling
// the browser the value may break at ANY character — so min-content becomes one
// character wide, and in a crowded table the column collapses and an ordinary
// 14-character SKU stacks four letters to a line. A min-width raises that floor
// back to one line's worth without giving up the cap at the other end.
function siteSkuSpan(value, style = '', max = 230, min = 0) {
    return `<span style="display:inline-block; max-width:${max}px;`
        + (min ? ` min-width:${min}px;` : '')
        + ` overflow-wrap:anywhere; ${style}">${escapeHtml(value)}</span>`;
}

function siteCopy(ev, btn) {
    // These chips sit inside table rows and cards that have their own click
    // handlers (opening a note, following a product link) — copying must not
    // also fire those.
    if (ev) { ev.stopPropagation(); ev.preventDefault(); }
    const v = btn.dataset.copy || '';
    if (!v) return;
    const flash = () => {
        btn.classList.add('site-copy-ok');
        // The table may have re-rendered underneath us in the meantime, in
        // which case this button is detached and resetting it is harmless.
        setTimeout(() => btn.classList.remove('site-copy-ok'), 1200);
    };
    // navigator.clipboard is undefined on a non-secure origin, so the old
    // textarea trick is the fallback rather than an outright failure.
    const manual = () => {
        try {
            const ta = document.createElement('textarea');
            ta.value = v;
            ta.setAttribute('readonly', '');
            ta.style.cssText = 'position:fixed; top:-1000px; opacity:0;';
            document.body.appendChild(ta);
            ta.select();
            const ok = document.execCommand('copy');
            document.body.removeChild(ta);
            if (!ok) throw new Error('denied');
            flash();
        } catch (_) {
            alert(`Could not copy — please select and copy the ${btn.dataset.what || 'value'} manually.`);
        }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(v).then(flash).catch(manual);
    } else {
        manual();
    }
}

// Copy button next to a case number so the ID can be pasted straight into
// Shopify / UPS / USPS status lookups.
function _claimCopyBtn(r) {
    return siteCopyBtn(r.case_number, 'case number');
}

// One claim row. `isChild` nests it (indent + blue edge) under its parent INR ticket;
// it's otherwise a full, normal claim row with its own status/value/cost/dates/actions.
function _claimRowHtml(r, showStore, isChild, canEscalate, hasChild, num) {
    const fmtPrice = v => (v == null || v === '') ? '—' : '$' + Number(v).toFixed(2);
    const fmtDate = d => { const x = new Date(d); return isNaN(x.getTime()) ? '' : x.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }); };
    const td = (c, extra = '') => `<td style="padding:9px 10px; border-bottom:1px solid #f1f5f9; vertical-align:top; ${extra}">${c}</td>`;
    const opts = Object.entries(CLAIM_STATUS).map(([k, v]) => `<option value="${k}" ${k === r.status ? 'selected' : ''}>${v.label}</option>`).join('');
    const sc = CLAIM_STATUS[r.status] || CLAIM_STATUS.in_progress;
    const aging = _isClaimAging(r) && !hasChild; // a parent superseded by a loss claim isn't "aging"
    const caret = encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 10 10"><path d="M2 3.5L5 6.5L8 3.5" stroke="#475569" stroke-width="1.7" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`);
    // Once a loss claim is opened, status tracking moves to that child claim — so a
    // parent INR with a child shows a static status, and only the claim has the pill.
    const statusCell = hasChild
        ? `<span style="font-size:11px; font-weight:800; color:#94a3b8;">${sc.label}</span><div style="font-size:9px; color:#cbd5e1; font-weight:800; text-transform:uppercase; letter-spacing:.3px; margin-top:1px;">on claim ↓</div>`
        : `<select onchange="updateClaimStatus('${r.id}', this.value)" style="appearance:none; -webkit-appearance:none; font-size:11px; font-weight:800; border:1.5px solid ${sc.fg}55; border-radius:999px; padding:5px 26px 5px 12px; cursor:pointer; background-color:#fff; color:#1e293b; background-image:url('data:image/svg+xml,${caret}'); background-repeat:no-repeat; background-position:right 9px center;">${opts}</select>`;

    let reasonCell = `${escapeHtml(r.reason_type || '—')}`;
    if (r.reason_detail) reasonCell += `<div style="color:#94a3b8; font-size:11px; margin-top:2px;">${escapeHtml(r.reason_detail)}</div>`;
    if (aging) {
        // An aging INR ticket gets the triage instruction, not just an age flag:
        // delivered since → eBay refunds (mark Recovered); still lost → open a claim.
        reasonCell += canEscalate
            ? `<div style="color:#dc2626; font-size:11px; font-weight:800; margin-top:3px;">⚠️ Open ${_claimDaysOpen(r)} days — check tracking: delivered since? Call eBay for the refund. Still lost? Open a claim.</div>`
            : `<div style="color:#dc2626; font-size:11px; font-weight:800; margin-top:3px;">⚠️ Open ${_claimDaysOpen(r)} days</div>`;
    }

    const sBtn = 'font-size:11px; font-weight:800; border-radius:7px; padding:5px 9px; cursor:pointer; line-height:1; white-space:nowrap;';
    const acts = [];
    if (aging && canEscalate) acts.push(`<button onclick="updateClaimStatus('${r.id}', 'recovered')" title="Tracking shows it arrived — call eBay for the refund, then mark Recovered" style="${sBtn} background:#f0fdf4; border:1.5px solid #86efac; color:#15803d;">📦 Delivered</button>`);
    if (aging) acts.push(`<button onclick="ackClaim('${r.id}')" title="Mark that you checked on this — resets the 7-day reminder" style="${sBtn} background:#ecfdf5; border:1.5px solid #a7f3d0; color:#047857;">✓ Still in progress</button>`);
    if (canEscalate) acts.push(`<button onclick="toggleEscalateRow('${r.id}')" title="Still lost — open a loss claim on this ticket" style="${sBtn} background:#eff6ff; border:1.5px solid #bfdbfe; color:#1d4ed8;">Open a claim</button>`);
    // Deleting a claim needs DM/CEO approval — the trash button sends a request, and a
    // claim already awaiting approval shows a pending badge instead.
    if (r.delete_requested_at) {
        acts.push(`<span title="Waiting on DM/CEO approval" style="display:inline-flex; align-items:center; gap:4px; font-size:10.5px; font-weight:800; color:#b45309; background:#fffbeb; border:1.5px solid #fde68a; border-radius:9px; padding:6px 9px; white-space:nowrap;">🗑 Delete requested</span>`);
    } else {
        acts.push(`<button onclick="requestClaimDelete('${r.id}', ${!!hasChild})" title="Request deletion (a DM or CEO must approve)" style="display:inline-flex; align-items:center; justify-content:center; width:34px; height:34px; background:#fff5f5; border:1.5px solid #fecaca; border-radius:9px; cursor:pointer; font-size:17px; line-height:1;" onmouseover="this.style.background='#fee2e2';" onmouseout="this.style.background='#fff5f5';">🗑</button>`);
    }
    const actionsCell = `<div style="display:flex; flex-direction:column; gap:5px; align-items:flex-start;">${acts.join('')}</div>`;

    const resolvedCell = r.resolved_at
        ? `<span style="color:${sc.fg}; white-space:nowrap; font-weight:700;">${fmtDate(r.resolved_at)}</span>`
        : `<span style="color:#cbd5e1; white-space:nowrap;">—</span>`;

    // Aging → red tint/edge; otherwise a child claim gets a blue tint/edge.
    let rowStyle = '';
    if (aging) rowStyle = 'background:#fef2f2; box-shadow:inset 3px 0 0 #dc2626;';
    else if (isChild) rowStyle = 'background:#f0f7ff; box-shadow:inset 3px 0 0 #93c5fd;';

    const caseCell = (isChild
        ? `<span style="color:#60a5fa; font-weight:900; margin-right:5px;">↳</span><span style="font-weight:700; color:var(--slate-charcoal);">${escapeHtml(r.case_number || '')}</span>`
        : `<span style="font-weight:700; color:var(--slate-charcoal);">${escapeHtml(r.case_number || '')}</span>`) + _claimCopyBtn(r);

    return `<tr style="${rowStyle}">
        ${td(`<span style="font-weight:800; color:${isChild ? '#94a3b8' : 'var(--slate-charcoal)'};">${num}</span>`, 'white-space:nowrap;')}
        ${showStore ? td(isChild ? '' : `<span style="font-weight:800; color:var(--slate-charcoal);">${escapeHtml(r.store || '')}</span>`) : ''}
        ${td(caseCell, isChild ? 'padding-left:20px;' : '')}
        ${td(escapeHtml(r.item_sku || '—'))}
        ${td(fmtPrice(r.price), 'white-space:nowrap; font-weight:700;')}
        ${td(fmtPrice(r.cost), 'white-space:nowrap; font-weight:700; color:#64748b;')}
        ${td(reasonCell)}
        ${td(statusCell, 'white-space:nowrap;')}
        ${td(`<span style="color:#94a3b8; white-space:nowrap;">${fmtDate(r.created_at)}</span>`)}
        ${td(resolvedCell)}
        ${td(actionsCell)}
    </tr>`;
}

// Inline form (a hidden table row) for opening a loss claim on an Item-Not-Received
// ticket — same fields as a new claim, prefilled with the item's value/cost.
function _escalateFormRow(r, colCount) {
    const inp = 'width:100%; padding:7px 9px; border:1.5px solid #cbd5e1; border-radius:7px; font-size:12px; font-weight:600; box-sizing:border-box; background:#fff;';
    const lbl = t => `<label style="display:block; font-size:9px; font-weight:800; text-transform:uppercase; letter-spacing:.4px; color:#94a3b8; margin-bottom:3px;">${t}</label>`;
    const val = r.price != null ? r.price : '';
    const cost = r.cost != null ? r.cost : '';
    return `<tr id="esc-row-${r.id}" style="display:none; background:#f1f5f9;">
        <td colspan="${colCount}" style="padding:14px 16px; border-bottom:1px solid #e2e8f0;">
            <div style="font-weight:800; font-size:12px; color:#1d4ed8; margin-bottom:4px;">Open a loss claim on this ticket</div>
            <div style="font-size:11px; color:#64748b; margin-bottom:10px;">Check tracking first — if the item has since been delivered, call eBay for the refund and mark the ticket <b>Recovered</b>. Only open a claim if it's still lost.</div>
            <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(120px, 1fr)); gap:10px;">
                <div>${lbl('Claim')}<select id="esc-${r.id}-reason" style="${inp}"><option value="Shopify Claim">Shopify Claim</option><option value="USPS Claim">USPS Claim</option><option value="UPS Claim">UPS Claim</option></select></div>
                <div>${lbl('Type')}<select id="esc-${r.id}-type" style="${inp}"><option value="Loss">Loss</option><option value="Damage">Damage</option></select></div>
                <div>${lbl('Claim #')}<input id="esc-${r.id}-num" style="${inp}" placeholder="e.g. 9400-1234"></div>
                <div>${lbl('Value')}<input id="esc-${r.id}-value" type="number" step="0.01" min="0" value="${val}" style="${inp}"></div>
                <div>${lbl('Cost')}<input id="esc-${r.id}-cost" type="number" step="0.01" min="0" value="${cost}" style="${inp}"></div>
                <div>${lbl('Detail (optional)')}<input id="esc-${r.id}-detail" style="${inp}" placeholder="Notes"></div>
            </div>
            <div style="display:flex; gap:8px; margin-top:12px;">
                <button onclick="saveEscalation('${r.id}')" class="btn-primary" style="font-size:12px; padding:7px 16px;">Save claim</button>
                <button onclick="toggleEscalateRow('${r.id}')" class="btn-secondary" style="font-size:12px; padding:7px 16px;">Cancel</button>
            </div>
        </td>
    </tr>`;
}

function toggleEscalateRow(id) {
    const row = document.getElementById('esc-row-' + id);
    if (row) row.style.display = (row.style.display === 'none' || !row.style.display) ? 'table-row' : 'none';
}

// "Still in progress" — verify the manager checked on an aging case (resets the clock).
async function ackClaim(id) {
    try {
        const res = await fetch(CLAIMS_URL, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'ack_claim', id }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Failed');
        const seen = _seenAgingClaims(); seen.delete(id); _saveSeenAgingClaims(seen);
        fetchMyClaims();
        // Re-run the aging check now rather than leaving the alert up until the next
        // 10-minute poll — the manager just did the work, so the nag should go with it.
        if (typeof checkAgingClaims === 'function') checkAgingClaims();
    } catch (e) {
        alert('Could not update: ' + e.message);
    }
}

// Save the inline "open a claim" form — creates a real child claim linked to the
// Item-Not-Received ticket (and resets the parent's clock; that's a check-in).
async function saveEscalation(id) {
    const g = s => { const el = document.getElementById(`esc-${id}-${s}`); return el ? String(el.value).trim() : ''; };
    const reason = g('reason'), type = g('type'), num = g('num'), value = g('value'), cost = g('cost'), detail = g('detail');
    const num2 = v => (v === '' || v == null) ? null : Number(v);
    try {
        const res = await fetch(CLAIMS_URL, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'escalate_claim', id,
                reason_type: `${reason} — ${type}`,
                case_number: num || null,
                price: num2(value), cost: num2(cost),
                reason_detail: detail || null,
                created_by: sessionStorage.getItem('speeksUserName') || null,
            }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Failed');
        const seen = _seenAgingClaims(); seen.delete(id); _saveSeenAgingClaims(seen);
        fetchMyClaims();
        // Re-run the aging check now rather than leaving the alert up until the next
        // 10-minute poll — the manager just did the work, so the nag should go with it.
        if (typeof checkAgingClaims === 'function') checkAgingClaims();
    } catch (e) {
        alert('Could not save: ' + e.message);
    }
}

// =========================================================
//  DM / CEO CLAIMS OVERSIGHT — checks & balances across all stores
// =========================================================
const _CLAIMS_OVERSIGHT_STORES = ['OVL', 'LEE', 'WSP', 'MPL', 'BAL'];
let _oversightAll = [];
let _oversightReminders = [];
let _ovStore = '', _ovStatus = ''; // oversight "All claims" filters

// A reminder is a nudge, not a nag: once sent, that store's button locks until the
// manager acknowledges it or the cooldown lapses. Without this a DM could stack up
// reminders faster than anyone could act on them.
const CLAIM_REMINDER_COOLDOWN_DAYS = 3;

// Newest UNACKNOWLEDGED reminder for a store that's still inside the cooldown, or
// null. Acknowledging (the manager hit "Review claims") frees the button early.
function _claimReminderLock(store) {
    const s = String(store || '').toUpperCase();
    const cutoff = Date.now() - CLAIM_REMINDER_COOLDOWN_DAYS * 86400000;
    return _oversightReminders
        .filter(r => String(r.store || '').toUpperCase() === s
            && !r.acknowledged_at
            && new Date(r.created_at).getTime() > cutoff)
        .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))[0] || null;
}

function openClaimsOversight() {
    toggleModal('claimsOversightModal');
    fetchAllClaims();
}

async function fetchAllClaims() {
    const body = document.getElementById('claims-oversight-body');
    if (!body) return;
    body.innerHTML = '<div class="status-message">Loading all claims…</div>';
    try {
        const res = await fetch(`${CLAIMS_URL}?v=${Date.now()}`); // no stores param → every store
        const json = await res.json();
        if (!json.success) throw new Error(json.error);
        _oversightAll = json.data || [];
        // Drives the per-store reminder cooldown. Non-fatal: if it fails the buttons
        // simply stay unlocked rather than blocking the whole oversight view.
        try {
            const rr = await fetch(`${CLAIMS_URL}?reminders=1&stores=${_CLAIMS_OVERSIGHT_STORES.join(',')}&v=${Date.now()}`);
            const rj = await rr.json();
            _oversightReminders = rj.success ? (rj.data || []) : [];
        } catch (_) { _oversightReminders = []; }
        renderClaimsOversight();
    } catch (e) {
        body.innerHTML = '<div class="status-message" style="color:var(--red-alert);">Failed to load claims.</div>';
    }
}

function renderClaimsOversight() {
    const body = document.getElementById('claims-oversight-body');
    if (!body) return;
    const rows = _oversightAll;
    // An INR ticket that's been escalated to a loss claim (has a child) is no longer
    // an open claim itself — the child loss claim is the active one. Exclude it.
    const supersededParents = new Set(rows.filter(r => r.parent_id).map(r => r.parent_id));
    const open = rows.filter(r => r.status === 'in_progress' && !supersededParents.has(r.id));
    const aging = open.filter(_isClaimAging);
    const reviewed = open.filter(r => r.last_checked_at && !_isClaimAging(r)); // checked in & current
    const resolved = rows.filter(r => r.status !== 'in_progress');
    const fmtDate = d => { const x = new Date(d); return isNaN(x.getTime()) ? '' : x.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }); };

    const card = (label, val, color) => `<div style="flex:1; min-width:110px; background:#fff; border:1px solid #e2e8f0; border-radius:12px; padding:13px 15px;">
        <div style="font-size:26px; font-weight:900; color:${color}; line-height:1;">${val}</div>
        <div style="font-size:10.5px; font-weight:800; text-transform:uppercase; letter-spacing:.4px; color:#94a3b8; margin-top:4px;">${label}</div>
    </div>`;
    let html = `<div style="display:flex; gap:10px; flex-wrap:wrap; margin-bottom:18px;">
        ${card('Open', open.length, '#1e293b')}
        ${card('Over 7 days', aging.length, aging.length ? '#dc2626' : '#94a3b8')}
        ${card('Reviewed', reviewed.length, '#059669')}
        ${card('Resolved', resolved.length, '#64748b')}
    </div>`;

    // Pending delete requests — a manager can't remove a claim directly; a DM/CEO
    // approves (permanently deletes) or denies (keeps it). Shown up top for action.
    const deleteReqs = rows.filter(r => r.delete_requested_at)
        .sort((a, b) => new Date(a.delete_requested_at) - new Date(b.delete_requested_at));
    if (deleteReqs.length) {
        html += `<div style="background:#fffbeb; border:1.5px solid #fde68a; border-radius:12px; padding:14px 16px; margin-bottom:18px;">
            <div style="font-weight:800; font-size:13px; color:#92400e; margin-bottom:10px;">🗑 Delete Requests (${deleteReqs.length}) — Approval Needed</div>
            <div style="display:flex; flex-direction:column; gap:8px;">`;
        deleteReqs.forEach(r => {
            const who = r.delete_requested_by ? escapeHtml(r.delete_requested_by) : 'Manager';
            html += `<div style="display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; background:#fff; border:1px solid #fde68a; border-radius:9px; padding:9px 12px;">
                <div style="font-size:12.5px; color:var(--slate-charcoal);">
                    <span style="font-weight:800;">${escapeHtml(r.store || '')}</span>
                    · <span style="font-weight:700;">${escapeHtml(r.case_number || '')}</span>${siteCopyBtn(r.case_number, 'case number')}
                    <span style="color:#94a3b8;"> — ${escapeHtml(r.reason_type || '')}</span>
                    <span style="color:#b45309; font-weight:700;"> · Requested by ${who}</span>
                </div>
                <div style="display:flex; gap:8px;">
                    <button onclick="approveClaimDelete('${r.id}')" style="font-size:11px; font-weight:800; border-radius:7px; padding:6px 13px; cursor:pointer; background:#fef2f2; border:1.5px solid #fecaca; color:#b91c1c;">Approve Delete</button>
                    <button onclick="denyClaimDelete('${r.id}')" style="font-size:11px; font-weight:800; border-radius:7px; padding:6px 13px; cursor:pointer; background:#f1f5f9; border:1.5px solid #cbd5e1; color:#475569;">Deny</button>
                </div>
            </div>`;
        });
        html += `</div></div>`;
    }

    // Per-store breakdown + a reminder ping.
    const byStore = {};
    _CLAIMS_OVERSIGHT_STORES.forEach(s => { byStore[s] = { open: 0, aging: 0, reviewed: 0 }; });
    open.forEach(r => {
        const s = (r.store || '').toUpperCase();
        if (!byStore[s]) byStore[s] = { open: 0, aging: 0, reviewed: 0 };
        byStore[s].open++;
        if (_isClaimAging(r)) byStore[s].aging++;
        else if (r.last_checked_at) byStore[s].reviewed++;
    });
    // Centred, and the header sits over the number it counts. Left-aligned counts
    // in a full-width table drift far from their headings — the eye has to travel
    // to work out whether a 1 under "Over 7 Days" belongs to that column or the
    // next one. The store code stays left; the action column stays right.
    const th = (t, align = 'center') => `<th style="text-align:${align}; font-size:9.5px; font-weight:800; text-transform:uppercase; letter-spacing:.4px; color:#94a3b8; padding:8px 10px; border-bottom:1px solid #e2e8f0;">${t}</th>`;
    const td = (c, extra = 'text-align:center;') => `<td style="padding:9px 10px; border-bottom:1px solid #f1f5f9; ${extra}">${c}</td>`;
    html += `<div style="font-weight:800; font-size:13px; margin-bottom:8px; color:var(--slate-charcoal);">By store</div>
        <div style="overflow-x:auto;"><table style="width:100%; border-collapse:collapse; font-size:12.5px; margin-bottom:20px;">
        <colgroup><col style="width:16%;"><col style="width:14%;"><col style="width:16%;"><col style="width:14%;"><col></colgroup>
        <thead><tr>${th('Store', 'left')}${th('Open')}${th('Over 7 Days')}${th('Reviewed')}${th('', 'right')}</tr></thead><tbody>`;
    Object.keys(byStore).forEach(s => {
        const d = byStore[s];
        // A reminder is only warranted for claims over 7 days that haven't been
        // reviewed or escalated to a claim — i.e. the store's aging count. If a
        // store is caught up (or only has fresh/reviewed claims), no button.
        // Already reminded and still inside the cooldown → show when it unlocks
        // instead of the button, so the DM can see the nudge landed and isn't
        // left wondering whether the click registered.
        const lock = d.aging ? _claimReminderLock(s) : null;
        let ping;
        if (!d.aging) {
            ping = `<span style="color:#cbd5e1; font-size:11px;">—</span>`;
        } else if (lock) {
            const sentDays = Math.floor((Date.now() - new Date(lock.created_at).getTime()) / 86400000);
            const backIn = Math.max(1, CLAIM_REMINDER_COOLDOWN_DAYS - sentDays);
            const sentTxt = sentDays === 0 ? 'today' : sentDays === 1 ? 'yesterday' : `${sentDays}d ago`;
            ping = `<span title="Reminder sent ${sentTxt} and not yet reviewed. You can send another in ${backIn} day${backIn === 1 ? '' : 's'}, or sooner if the manager reviews it."
                style="display:inline-flex; align-items:center; gap:5px; font-size:11px; font-weight:800; color:#94a3b8; background:#f8fafc; border:1.5px solid #e2e8f0; border-radius:7px; padding:5px 11px; cursor:default;">🔔 Reminded ${sentTxt}</span>`;
        } else {
            ping = `<button onclick="pingStoreClaims('${s}')" style="font-size:11px; font-weight:800; border-radius:7px; padding:5px 11px; cursor:pointer; background:#eff6ff; border:1.5px solid #bfdbfe; color:#1d4ed8;">🔔 Send reminder</button>`;
        }
        html += `<tr>
            ${td(`<span style="font-weight:800; color:var(--slate-charcoal);">${s}</span>`, 'text-align:left;')}
            ${td(`<span style="font-weight:700;">${d.open}</span>`)}
            ${td(`<span style="font-weight:800; color:${d.aging ? '#dc2626' : '#cbd5e1'};">${d.aging}</span>`)}
            ${td(`<span style="font-weight:800; color:${d.reviewed ? '#059669' : '#cbd5e1'};">${d.reviewed}</span>`)}
            ${td(ping, 'text-align:right;')}
        </tr>`;
    });
    html += `</tbody></table></div>`;

    // Full claims list — every claim across all stores, with details + store/status filters.
    const byId = {}; rows.forEach(r => { byId[r.id] = r; });
    const storeOpts = ['', ..._CLAIMS_OVERSIGHT_STORES].map(s => `<option value="${s}" ${s === _ovStore ? 'selected' : ''}>${s || 'All stores'}</option>`).join('');
    const statusOpts = [['', 'All statuses'], ['in_progress', 'In Progress'], ['recovered', 'Recovered'], ['denied', 'Denied']]
        .map(([v, l]) => `<option value="${v}" ${v === _ovStatus ? 'selected' : ''}>${l}</option>`).join('');
    const selStyle = 'padding:8px 10px; border:1.5px solid #cbd5e1; border-radius:8px; font-size:12.5px; font-weight:600; background:#fff;';
    html += `<div style="display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap; margin:6px 0 10px;">
        <div style="font-weight:800; font-size:13px; color:var(--slate-charcoal);">All claims</div>
        <div style="display:flex; gap:8px; flex-wrap:wrap;">
            <select onchange="_ovStore=this.value; renderClaimsOversight();" style="${selStyle}">${storeOpts}</select>
            <select onchange="_ovStatus=this.value; renderClaimsOversight();" style="${selStyle}">${statusOpts}</select>
        </div>
    </div>`;

    // Nest loss claims under their original INR ticket (same as the manager view).
    const hasKids = new Set(rows.filter(r => r.parent_id).map(r => r.parent_id));
    const kidsOf = {}; rows.forEach(r => { if (r.parent_id) (kidsOf[r.parent_id] = kidsOf[r.parent_id] || []).push(r); });
    let tops = rows.filter(r => !r.parent_id || !byId[r.parent_id]);
    if (_ovStore) tops = tops.filter(r => (r.store || '').toUpperCase() === _ovStore);
    if (_ovStatus) tops = tops.filter(r => r.status === _ovStatus);
    // Sort needs-attention first: over-7-day open claims → other open → escalated
    // INRs → resolved; newest created first within each group.
    const ovRank = r => {
        if (r.status !== 'in_progress') return 3;          // resolved (recovered/denied)
        if (supersededParents.has(r.id)) return 2;         // INR that became a loss claim
        if (_isClaimAging(r)) return 0;                    // open & over 7 days — act now
        return 1;                                          // open & current
    };
    tops.sort((a, b) => ovRank(a) - ovRank(b) || new Date(b.created_at) - new Date(a.created_at));
    if (!tops.length) {
        html += `<div style="padding:18px; text-align:center; color:#94a3b8; font-weight:600; background:#f8fafc; border-radius:10px;">No claims match this view.</div>`;
    } else {
        html += `<div style="overflow-x:auto;"><table style="width:100%; border-collapse:collapse; font-size:12px;">
            <thead><tr>${th('#')}${th('Store')}${th('Case #')}${th('SKU')}${th('Value')}${th('Cost')}${th('Reason')}${th('Status')}${th('Created')}${th('Reviewed')}</tr></thead><tbody>`;
        let n = 0;
        tops.forEach(r => {
            n++;
            html += _ovRowHtml(r, byId, hasKids.has(r.id), `${n}`);
            (kidsOf[r.id] || []).forEach((k, ci) => { html += _ovRowHtml(k, byId, false, `${n}.${ci + 1}`); });
        });
        html += `</tbody></table></div>`;
    }
    body.innerHTML = html;
}

// Read-only detail row for the oversight "All claims" table. A child loss claim
// (parent_id set) is indented and notes which ticket it came from.
function _ovRowHtml(r, byId, hasChild, num) {
    const isChild = !!r.parent_id;
    const fmtPrice = v => (v == null || v === '') ? '—' : '$' + Number(v).toFixed(2);
    const fmtDate = d => { const x = new Date(d); return isNaN(x.getTime()) ? '' : x.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }); };
    const td = (c, extra = '') => `<td style="padding:8px 10px; border-bottom:1px solid #f1f5f9; vertical-align:top; ${extra}">${c}</td>`;
    const sc = CLAIM_STATUS[r.status] || CLAIM_STATUS.in_progress;
    const aging = _isClaimAging(r) && !hasChild;
    // Mirror the manager view: a parent INR with a child shows status "on claim ↓".
    const statusCell = hasChild
        ? `<span style="font-size:11px; font-weight:800; color:#94a3b8;">${sc.label}</span><div style="font-size:9px; color:#cbd5e1; font-weight:800; text-transform:uppercase; letter-spacing:.3px; margin-top:1px;">on claim ↓</div>`
        : `<span style="display:inline-block; font-size:10px; font-weight:800; background:${sc.bg}; color:${sc.fg}; border-radius:999px; padding:3px 10px; white-space:nowrap;">${sc.label}</span>`;
    let reasonCell = escapeHtml(r.reason_type || '—');
    if (aging) reasonCell += `<div style="color:#dc2626; font-size:10.5px; font-weight:800; margin-top:2px;">⚠️ Open ${_claimDaysOpen(r)} days</div>`;
    if (r.delete_requested_at) reasonCell += `<div style="color:#b45309; font-size:10.5px; font-weight:800; margin-top:2px;">🗑 Delete requested</div>`;
    const reviewed = r.status !== 'in_progress'
        ? `<span style="color:#cbd5e1;">—</span>`
        : (r.last_checked_at ? `<span style="color:#059669; font-weight:700; white-space:nowrap;">${fmtDate(r.last_checked_at)}</span>` : `<span style="color:#dc2626; font-weight:800;">Never</span>`);
    let rowStyle = '';
    if (aging) rowStyle = 'background:#fef2f2; box-shadow:inset 3px 0 0 #dc2626;';
    else if (isChild) rowStyle = 'background:#f0f7ff; box-shadow:inset 3px 0 0 #93c5fd;';
    const parent = isChild ? byId[r.parent_id] : null;
    const caseCell = isChild
        ? `<span style="color:#60a5fa; font-weight:900; margin-right:5px;">↳</span><span style="font-weight:700; color:var(--slate-charcoal);">${escapeHtml(r.case_number || '')}</span>${_claimCopyBtn(r)}${parent ? `<div style="font-size:10px; color:#94a3b8; font-weight:600;">claim on ${escapeHtml(parent.case_number || '')}</div>` : ''}`
        : `<span style="font-weight:700; color:var(--slate-charcoal);">${escapeHtml(r.case_number || '')}</span>${_claimCopyBtn(r)}`;
    return `<tr style="${rowStyle}">
        ${td(`<span style="font-weight:800; color:${isChild ? '#94a3b8' : 'var(--slate-charcoal)'};">${num}</span>`, 'white-space:nowrap;')}
        ${td(`<span style="font-weight:800; color:var(--slate-charcoal);">${escapeHtml(r.store || '')}</span>`)}
        ${td(caseCell, isChild ? 'padding-left:18px;' : '')}
        ${td(escapeHtml(r.item_sku || '—'))}
        ${td(fmtPrice(r.price), 'white-space:nowrap; font-weight:700;')}
        ${td(fmtPrice(r.cost), 'white-space:nowrap; font-weight:700; color:#64748b;')}
        ${td(reasonCell)}
        ${td(statusCell, 'white-space:nowrap;')}
        ${td(`<span style="color:#94a3b8; white-space:nowrap;">${fmtDate(r.created_at)}</span>`)}
        ${td(reviewed)}
    </tr>`;
}

// Nudge a store's manager to review their open claims. Delivers as a dedicated RED
// review pop-up on the manager's dashboard (separate from green store comments).
async function pingStoreClaims(store) {
    const rows = _oversightAll || [];
    // Reminders target only claims that are actually behind: open, over 7 days,
    // not yet reviewed ("Still in progress") and not already escalated to a claim.
    // Escalated INRs (parents with a child loss claim) are excluded like everywhere else.
    const sup = new Set(rows.filter(r => r.parent_id).map(r => r.parent_id));
    const aging = rows.filter(r => r.status === 'in_progress'
        && (r.store || '').toUpperCase() === store
        && !sup.has(r.id)
        && _isClaimAging(r));
    if (!aging.length) {
        alert(`${store} has no claims over 7 days awaiting review — nothing to remind about.`);
        return;
    }
    // Belt-and-braces: the button is already hidden during the cooldown, but a stale
    // render (or a second tab) shouldn't be able to stack reminders.
    const lock = _claimReminderLock(store);
    if (lock) {
        const backIn = Math.max(1, CLAIM_REMINDER_COOLDOWN_DAYS
            - Math.floor((Date.now() - new Date(lock.created_at).getTime()) / 86400000));
        alert(`${store} was already reminded and hasn't reviewed yet.\n\nYou can send another in ${backIn} day${backIn === 1 ? '' : 's'}, or as soon as they review it.`);
        return;
    }
    if (!confirm(`Send ${store} a reminder to review ${aging.length} claim${aging.length === 1 ? '' : 's'} open over 7 days without a review?`)) return;
    // Message is generic — the manager's popup computes the live over-7-day count.
    try {
        const res = await fetch(CLAIMS_URL, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'send_reminder', store,
                message: 'Please review your open insurance claims.',
                from: sessionStorage.getItem('speeksUserName') || 'Leadership',
            }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Failed');
        alert(`Reminder sent to ${store}.`);
        fetchAllClaims(); // re-read reminders so the button flips to its locked state
    } catch (e) {
        alert('Could not send the reminder: ' + (e.message || e));
    }
}

async function updateClaimStatus(id, status) {
    try {
        const res = await fetch(CLAIMS_URL, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'update_status', id, status }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Update failed');
        // Resolving is the other way a claim leaves the aging set — clear the alert
        // straight away instead of waiting on the 10-minute poll.
        const seen = _seenAgingClaims(); seen.delete(id); _saveSeenAgingClaims(seen);
        fetchMyClaims();
        if (typeof checkAgingClaims === 'function') checkAgingClaims();
    } catch (e) {
        alert('Could not update status: ' + e.message);
        fetchMyClaims();
    }
}

// Manager-side: request deletion. Claims are never deleted directly by a manager —
// a DM/CEO must approve, so nothing is quietly removed.
async function requestClaimDelete(id, hasChild) {
    // Deleting an Item-Not-Received ticket that already has a loss claim removes
    // both (child cascades) — spell that out so it isn't a surprise.
    const msg = hasChild
        ? 'Request deletion of this Item-Not-Received ticket?\n\nThis also removes the loss claim opened on it. A DM or CEO must approve before anything is removed.'
        : 'Request deletion of this claim?\n\nA DM or CEO must approve it before the claim is removed.';
    if (!confirm(msg)) return;
    try {
        const res = await fetch(CLAIMS_URL, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'request_delete', id, requested_by: sessionStorage.getItem('speeksUserName') || null }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Request failed');
        alert('Delete request sent. A DM or CEO will review it.');
        fetchMyClaims();
    } catch (e) {
        alert('Could not send the request: ' + (e.message || e));
    }
}

// DM/CEO-side: approve a pending delete request → permanently removes the claim.
async function approveClaimDelete(id) {
    const kids = (_oversightAll || []).filter(r => r.parent_id === id).length;
    const msg = kids
        ? `Approve deletion? This permanently removes the ticket AND the ${kids} loss claim${kids === 1 ? '' : 's'} opened on it. This cannot be undone.`
        : 'Approve deletion? This permanently removes the claim and cannot be undone.';
    if (!confirm(msg)) return;
    try {
        const res = await fetch(CLAIMS_URL, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'delete_claim', id }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Delete failed');
        fetchAllClaims();
    } catch (e) {
        alert('Could not delete: ' + (e.message || e));
    }
}

// DM/CEO-side: deny a pending delete request → keeps the claim, clears the flag.
async function denyClaimDelete(id) {
    try {
        const res = await fetch(CLAIMS_URL, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'deny_delete', id }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok || json.success === false) throw new Error(json.error || 'Failed');
        fetchAllClaims();
    } catch (e) {
        alert('Could not deny: ' + (e.message || e));
    }
}

// --- AGING-CLAIM RED ALERT BUBBLE ---
// Nudges managers to revisit any case still "In Progress" after 7 days. For an
// Item-Not-Received case that old, the buyer was likely already refunded and the
// item is probably truly lost — so we recommend opening a Damage/Loss claim.
const CLAIM_AGE_DAYS = 7;

// A case "ages" from when it was last checked on (last_checked_at) or, if never
// checked, from when it was opened (created_at). Acking via "Still in progress"
// resets this clock.
function _claimEffectiveDate(r) {
    return new Date(r.last_checked_at || r.created_at).getTime();
}
function _claimDaysOpen(r) {
    const t = _claimEffectiveDate(r);
    return isNaN(t) ? '?' : Math.floor((Date.now() - t) / 86400000);
}
function _isClaimAging(r) {
    if (!r || r.status !== 'in_progress') return false;
    const t = _claimEffectiveDate(r);
    return !isNaN(t) && t < Date.now() - CLAIM_AGE_DAYS * 86400000;
}

// Both claim suppression lists are per-USER, not per-browser. Without the name in
// the key, one account's dismissal silences the alert for whoever logs in next on
// the same machine — a shared store computer, or a sign-out/sign-in into a
// different role, would land on an already-"seen" id set and render nothing.
function _seenAgingKey() {
    const u = (sessionStorage.getItem('speeksUserName') || 'anon').trim().toLowerCase();
    return 'speeksSeenAgingClaims_' + u;
}
function _seenAgingClaims() {
    try { return new Set(JSON.parse(sessionStorage.getItem(_seenAgingKey()) || '[]')); }
    catch (e) { return new Set(); }
}
function _saveSeenAgingClaims(keys) {
    sessionStorage.setItem(_seenAgingKey(), JSON.stringify([...keys]));
}

// True while a DM/CEO-pushed reminder currently owns the shared red bubble, so the
// generic aging alert won't overwrite it (avoids the login flicker of two firing).
let _reminderBubbleActive = false;
// Mark reminders read locally + server-side. Shared by the ✕ / "Review claims"
// button and by the silent ack when a reminder turns out to have nothing overdue.
function _ackClaimReminders(ids) {
    if (!ids || !ids.length) return;
    const acked = _ackedReminders();
    ids.forEach(id => acked.add(id));
    _saveAckedReminders(acked);
    fetch(CLAIMS_URL, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'ack_reminder', ids, by: sessionStorage.getItem('speeksUserName') || null }),
    }).catch(() => { /* local copy still suppresses it on this device */ });
}

window.closeClaimAlertBubble = function () {
    const b = document.getElementById('claimAlertBubble');
    if (b) b.style.display = 'none';
    _reminderBubbleActive = false; // free the bubble for a later aging alert
    // Acknowledging the bubble (the ✕ OR the "Review claims" button, which calls
    // this first) marks whatever DM/CEO reminder it's showing as read. Persisted
    // SERVER-SIDE via ack_reminder so it never returns — localStorage alone
    // couldn't survive clearing browsing data or a different device — plus a
    // local copy so it hides instantly without waiting on the round-trip.
    if (_shownReminderIds.length) {
        const ids = _shownReminderIds.slice();
        _shownReminderIds = [];
        _ackClaimReminders(ids);
    }
};

// --- DM/CEO-pushed review reminders (delivered to the manager as the same RED bubble) ---
// Read state persists across sessions in localStorage: once a manager dismisses
// or reviews a reminder it stays read. (This used to live in sessionStorage,
// which is wiped on every new browser session, so each fresh login re-fired an
// already-handled reminder — the "popup keeps coming back after opening the
// claims" bug.)
function _ackedRemindersKey() {
    const u = (sessionStorage.getItem('speeksUserName') || 'anon').trim().toLowerCase();
    return 'speeksReadClaimReminders_' + u;
}
function _ackedReminders() {
    try { return new Set(JSON.parse(localStorage.getItem(_ackedRemindersKey()) || '[]')); }
    catch (e) { return new Set(); }
}
function _saveAckedReminders(keys) {
    // The API only ever returns the last 20 reminders, so keep the read list
    // bounded rather than letting it grow forever.
    localStorage.setItem(_ackedRemindersKey(), JSON.stringify([...keys].slice(-200)));
}
let _shownReminderIds = []; // reminder ids the on-screen bubble covers, acked together on close

async function checkClaimReminders() {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase();
    if (!_CLAIM_ALERT_ROLES.has(role)) return;
    const stores = (typeof _claimStores === 'function') ? _claimStores() : [];
    if (!stores.length) return;
    try {
        const res = await fetch(`${CLAIMS_URL}?reminders=1&stores=${encodeURIComponent(stores.join(','))}&v=${Date.now()}`);
        const json = await res.json();
        if (!json.success) return;
        const acked = _ackedReminders();
        const fresh = (json.data || []).filter(r => !acked.has(r.id)); // newest first from API
        if (!fresh.length) return;
        // Already showing this batch (newest id unchanged) — don't re-animate on
        // the 30s poll. A newer reminder arriving changes fresh[0] and re-shows.
        if (_shownReminderIds.length && _shownReminderIds[0] === fresh[0].id) return;

        // Compute the manager's CURRENT open / over-7-day counts so the reminder
        // reflects what actually still needs review (not a stale number).
        let openCount = 0, agingCount = 0, agingINRCount = 0, breakdown = '', agingStores = [];
        try {
            const cRes = await fetch(`${CLAIMS_URL}?stores=${encodeURIComponent(stores.join(','))}&v=${Date.now()}`);
            const cj = await cRes.json();
            if (cj.success) {
                const sup = new Set((cj.data || []).filter(r => r.parent_id).map(r => r.parent_id));
                const op = (cj.data || []).filter(r => r.status === 'in_progress' && !sup.has(r.id));
                openCount = op.length;
                const agingRows = op.filter(_isClaimAging);
                agingCount = agingRows.length;
                agingINRCount = agingRows.filter(_isINRTicket).length;
                agingStores = [...new Set(agingRows.map(r => (r.store || '').toUpperCase()).filter(Boolean))];
                // Same reasoning as the aging alert: a Multi-Store Manager's reminder
                // spans both stores, so a bare total doesn't say where to look.
                if (stores.length > 1) {
                    const byStore = {};
                    agingRows.forEach(r => { const s = (r.store || '?').toUpperCase(); byStore[s] = (byStore[s] || 0) + 1; });
                    breakdown = Object.keys(byStore).sort().map(s => `${s} ${byStore[s]}`).join(' · ');
                }
            }
        } catch (e) { /* counts stay 0 */ }
        // Nothing is actually overdue, so there is nothing to act on. The feed is a
        // list of work, and this row is styled as a red "Insurance claims aging"
        // deadline — showing "you're all caught up" under that badge contradicts
        // itself and can only be snoozed, never cleared. The DM's nudge was to get
        // overdue claims reviewed; with none overdue it's already satisfied, so ack
        // it silently instead of parking a no-op in the feed. (The DM still has
        // their own oversight view of every store.)
        if (!agingCount) { _ackClaimReminders(fresh.map(r => r.id)); return; }

        // Remember which reminders this bubble represents; closing it marks them
        // all read (newest supersedes any older unread ones it stacks over).
        _shownReminderIds = fresh.map(r => r.id);
        _showClaimReminder(fresh[0], openCount, agingCount, agingINRCount, breakdown, agingStores);
    } catch (e) { /* silent */ }
}

function _showClaimReminder(rem, openCount, agingCount, agingINRCount = 0, breakdown = '', agingStores = null) {
    const from = rem.from_name ? escapeHtml(rem.from_name) : 'Leadership';
    let body;
    if (agingCount) {
        body = (agingCount === 1
            ? '1 claim has been open over 7 days. Please review it.'
            : `${agingCount} claims have been open over 7 days. Please review them.`)
            + (breakdown ? ` <b>${escapeHtml(breakdown)}</b>` : '')
            + _inrGuidanceHtml(agingINRCount);
    } else if (openCount) {
        body = "You're all caught up on aging claims.";
    } else {
        body = 'All your claims are resolved — nice work!';
    }
    _reminderBubbleActive = true; // claims the shared bubble so the aging alert won't clobber it
    // With a breakdown the full sentence would run past the feed's ~100-char cap and
    // clip exactly the store split the MSM needs, so lead with counts + stores and
    // demote the INR flag to a short tag (matches _showClaimAlert).
    const summary = agingCount
        ? `${from}: ` + (breakdown
            ? `${agingCount} open over 7 days · ${breakdown}` + (agingINRCount ? ` · ${agingINRCount} Item Not Received` : '')
            : _claimFeedSummary(agingCount, agingINRCount))
        : `${from}: ` + (openCount ? 'all caught up on aging claims.' : 'all your claims are resolved.');
    // Keyed to the actual reminder id(s): every new push is a new escalation and
    // gets past any snooze the manager already had in place.
    _renderClaimBubble('🛟', `${from} — Claims Review`, body, summary,
        'rem:' + (_shownReminderIds.length ? _shownReminderIds.join(',') : (rem && rem.id) || ''),
        agingStores);
}

let _claimAlertPollStarted = false;
const _CLAIM_ALERT_ROLES = new Set(['manager', 'owner (manager)', 'owner manager']);
async function checkAgingClaims() {
    // Same audience as the Insurance Claims tool: managers, owner-managers, MSM
    // (MSM logs in as role 'manager'). ASMs/employees never file claims.
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase();
    if (!_CLAIM_ALERT_ROLES.has(role)) return;
    const stores = (typeof _claimStores === 'function') ? _claimStores() : [];
    if (!stores.length) return; // no store scope → nothing to check

    if (!_claimAlertPollStarted) {
        _claimAlertPollStarted = true;
        setInterval(checkAgingClaims, 10 * 60 * 1000);
    }

    try {
        const res = await fetch(`${CLAIMS_URL}?stores=${encodeURIComponent(stores.join(','))}&v=${Date.now()}`);
        const json = await res.json();
        if (!json.success) return;
        const data = json.data || [];
        const sup = new Set(data.filter(r => r.parent_id).map(r => r.parent_id)); // exclude escalated INRs
        const aging = data.filter(r => !sup.has(r.id) && _isClaimAging(r));
        // The OTHER thing waiting on the DM in this tool, and it behaves nothing
        // like ageing: a manager who asked to delete a claim is blocked until the
        // DM approves or denies it. So it is STATE-based and never marked seen —
        // a glance must not silence work somebody else is waiting on. Exactly the
        // rule checkRecycleReminders already applies to its own delete queue.
        //
        // Not filtered through `sup`: a parent claim that has been escalated to an
        // INR child is excluded from AGEING (the child carries the clock now), but
        // a delete request on it is still a real approval someone is waiting for.
        // The oversight panel lists them the same way.
        const pendingDelete = data.filter(r => r.delete_requested_at);

        if (!aging.length && !pendingDelete.length) {
            // Nothing is aging any more (reviewed via "Still in progress", resolved,
            // or escalated). This used to just `return`, leaving a stale "claims are
            // aging" bubble — and therefore a stale feed row — on screen for the rest
            // of the session after the manager had already done the work. Clear it so
            // the row actually disappears, as the Snooze tooltip promises.
            const b = document.getElementById('claimAlertBubble');
            if (b && getComputedStyle(b).display !== 'none') {
                b.style.display = 'none';
                _reminderBubbleActive = false; // any DM reminder it showed is moot now
                if (typeof _positionClaimAlert === 'function') _positionClaimAlert(); // re-flow the stack
            }
            return;
        }

        // A DM/CEO reminder already owns the bubble — don't clobber it (it already
        // conveys the aging count). The aging alert can show once that's dismissed.
        const bubble = document.getElementById('claimAlertBubble');
        const bubbleVisible = bubble && getComputedStyle(bubble).display !== 'none';
        if (_reminderBubbleActive && bubbleVisible) return;

        // Only auto-pop when there's an aging case we haven't surfaced this session.
        const seen = _seenAgingClaims();
        if (!aging.some(r => !seen.has(r.id))) return;
        aging.forEach(r => seen.add(r.id));
        _saveSeenAgingClaims(seen);

        // A Multi-Store Manager covers two stores at once, so "2 claims are aging"
        // doesn't tell them where to look. Break it down by store whenever the
        // user's claim scope spans more than one; single-store managers are
        // unaffected and keep the plain wording.
        const byStore = {};
        aging.forEach(r => { const s = (r.store || '?').toUpperCase(); byStore[s] = (byStore[s] || 0) + 1; });
        const breakdown = stores.length > 1
            ? Object.keys(byStore).sort().map(s => `${s} ${byStore[s]}`).join(' · ')
            : '';
        _showClaimAlert(aging.length, aging.filter(_isINRTicket).length, breakdown, Object.keys(byStore));
    } catch (e) {
        console.error('Aging claim check failed:', e);
    }
}

// --- DM: claims aging ACROSS ALL STORES -------------------------------------
// The manager-side check is store-scoped, and _claimStores() returns [] for a DM
// (their store is ALL), so they were never told about overdue claims anywhere.
// This is the district view: one row covering every store, with the per-store
// breakdown, mirroring the oversight modal's all-stores fetch (no stores param).
// CEO is deliberately excluded — they keep tool access without the notifications.
let _dmClaimAlertPollStarted = false;
async function checkAgingClaimsDM() {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    if (role !== 'district manager') return;

    if (!_dmClaimAlertPollStarted) {
        _dmClaimAlertPollStarted = true;
        setInterval(checkAgingClaimsDM, 10 * 60 * 1000);
    }

    try {
        const res = await fetch(`${CLAIMS_URL}?v=${Date.now()}`);   // no stores param → every store
        const json = await res.json();
        if (!json.success) return;
        const data = json.data || [];
        // An INR ticket escalated to a loss claim is no longer open itself — the
        // child claim is. Same exclusion the oversight table uses.
        const sup = new Set(data.filter(r => r.parent_id).map(r => r.parent_id));
        let aging = data.filter(r => !sup.has(r.id) && _isClaimAging(r));

        // A store the DM has already nudged (active, unacknowledged reminder still
        // inside the cooldown) is the manager's court now — don't keep nagging the
        // DM about it. It returns to the district alert once the reminder is acked
        // (the manager reviewed, which also clears the aging) or the cooldown lapses
        // so the DM can re-nudge. Without this, sending a reminder left the same
        // aging row on the DM's own feed indefinitely.
        try {
            const rr = await fetch(`${CLAIMS_URL}?reminders=1&stores=OVL,LEE,WSP,MPL,BAL&v=${Date.now()}`);
            const rj = await rr.json();
            if (rj.success) {
                const cutoff = Date.now() - CLAIM_REMINDER_COOLDOWN_DAYS * 86400000;
                const nudged = new Set((rj.data || [])
                    .filter(r => !r.acknowledged_at && new Date(r.created_at).getTime() > cutoff)
                    .map(r => (r.store || '').toUpperCase()));
                if (nudged.size) aging = aging.filter(r => !nudged.has((r.store || '').toUpperCase()));
            }
        } catch (_) { /* if reminders fail to load, show everything rather than hide */ }

        // The OTHER thing waiting on the DM in this tool, and it behaves nothing
        // like ageing: a manager who asked to delete a claim is blocked until the
        // DM approves or denies it. So it is STATE-based and never marked seen —
        // a glance must not silence work somebody else is waiting on. Exactly the
        // rule checkRecycleReminders already applies to its own delete queue.
        //
        // Not filtered through `sup`: a parent claim that has been escalated to an
        // INR child is excluded from AGEING (the child carries the clock now), but
        // a delete request on it is still a real approval someone is waiting for.
        // The oversight panel lists them the same way.
        const pendingDelete = data.filter(r => r.delete_requested_at);

        if (!aging.length && !pendingDelete.length) {
            // Nothing is aging any more (reviewed via "Still in progress", resolved,
            // or escalated). This used to just `return`, leaving a stale "claims are
            // aging" bubble — and therefore a stale feed row — on screen for the rest
            // of the session after the manager had already done the work. Clear it so
            // the row actually disappears, as the Snooze tooltip promises.
            const b = document.getElementById('claimAlertBubble');
            if (b && getComputedStyle(b).display !== 'none') {
                b.style.display = 'none';
                _reminderBubbleActive = false; // any DM reminder it showed is moot now
                if (typeof _positionClaimAlert === 'function') _positionClaimAlert(); // re-flow the stack
            }
            return;
        }

        // Same once-per-session rule as the manager alert — but for the AGEING
        // half only. Ageing is a standing condition, not a handoff, and
        // re-announcing it every poll is what made the old toast unbearable.
        const seen = _seenAgingClaims();
        const freshAging = aging.filter(r => !seen.has(r.id));
        if (!freshAging.length && !pendingDelete.length) return;
        if (freshAging.length) {
            aging.forEach(r => seen.add(r.id));
            _saveSeenAgingClaims(seen);
        }

        const bodyParts = [], sumParts = [];
        if (freshAging.length) {
            const byStore = {};
            aging.forEach(r => { const s = (r.store || '?').toUpperCase(); byStore[s] = (byStore[s] || 0) + 1; });
            const stores = Object.keys(byStore).sort();
            const breakdown = stores.map(s => `${s} ${byStore[s]}`).join(' · ');
            const inrCount = aging.filter(_isINRTicket).length;

            const head = aging.length === 1
                ? '1 claim has been open over 7 days.'
                : `${aging.length} claims have been open over 7 days.`;
            bodyParts.push(`${head} Across ${stores.length === 1 ? '1 store' : stores.length + ' stores'} — ${breakdown}.`
                + _inrGuidanceHtml(inrCount));
            sumParts.push(`${aging.length} open over 7 days · ${breakdown}`);
        }
        if (pendingDelete.length) {
            // Name the case when there are only one or two. "1 delete request" is
            // not something you can go and find; a case number is. Same reasoning
            // as _rcLabel on the recycle side.
            const _clLabel = r => `${(r.store || '').toUpperCase()} ${String(r.case_number || 'no case #').trim()}`;
            const askers = [...new Set(pendingDelete
                .map(r => String(r.delete_requested_by || '').trim()).filter(Boolean))];
            const which = pendingDelete.length <= 2
                ? pendingDelete.map(_clLabel).join(', ')
                : `${pendingDelete.length} claims`;
            const line = `${pendingDelete.length} delete request${pendingDelete.length > 1 ? 's' : ''} awaiting approval — ${which}`
                + `${askers.length === 1 ? `, requested by ${askers[0]}` : ''}.`;
            bodyParts.push(escapeHtml(line));
            sumParts.push(line);
        }

        // The snooze identity carries the pending delete ids, so a SECOND request
        // arrives as new information rather than being swallowed by a snooze taken
        // on the first one.
        const sig = `ag:${freshAging.length}|del:${pendingDelete.map(r => r.id).sort().join(',')}`;
        _renderClaimBubble(
            pendingDelete.length ? '🗑' : '⚠️',
            pendingDelete.length && !freshAging.length ? 'Claim Delete Requests' : 'Claims Review — District',
            bodyParts.join('<br><br>'), sumParts.join(' · '), sig);
        // Tells the feed card which of the two it is looking at (see _samReminderCfg).
        const _clT = document.getElementById('claimAlertBubbleText');
        if (_clT) {
            if (pendingDelete.length) _clT.dataset.del = freshAging.length ? 'mixed' : 'only';
            else delete _clT.dataset.del;
        }
    } catch (e) {
        console.error('DM aging claim check failed:', e);
    }
}

// Keep the claim alert stacked UNDER the green store-comment bubble whenever that
// one is showing; otherwise sit at the normal top spot. Called both when the alert
// appears and when the comment bubble shows/hides, so order of arrival doesn't matter.
function _positionClaimAlert() {
    const bubble = document.getElementById('claimAlertBubble');
    if (!bubble) return;
    const daily = document.getElementById('dailyMessageBubble');
    const dailyVisible = daily && getComputedStyle(daily).display !== 'none' && daily.offsetHeight > 0;
    bubble.style.top = dailyVisible ? (daily.getBoundingClientRect().bottom + 12) + 'px' : '116px';
    // The recycle bubble stacks below this one — re-flow it whenever this moves.
    if (typeof _positionRecycleAlert === 'function') _positionRecycleAlert();
}

// A general red reminder — it does NOT name specific cases; the My Cases tab
// highlights the actual aging case(s) in red. A button jumps straight there.
// Shared red-bubble renderer (same size/format as the green store-comment bubble:
// emoji in the icon slot, title + body in the text slot), with a Review button.
// `summary` is the compact one-liner the Action Menu feed shows (see
// _samGatherReminders). The bubble keeps the full instructional copy; the feed
// gets a short version instead of a truncated scrape of it.
function _renderClaimBubble(icon, titleHtml, bodyHtml, summary, sig, stores) {
    const bubble = document.getElementById('claimAlertBubble');
    const textEl = document.getElementById('claimAlertBubbleText');
    const iconEl = document.getElementById('claimAlertBubbleIcon');
    if (!bubble || !textEl) return;
    if (summary) textEl.dataset.summary = summary;
    else delete textEl.dataset.summary;
    // Stores this alert covers → routes an MSM single-store click (see
    // _samGatherReminders). Cleared when only one/none so it doesn't go stale.
    if (stores && stores.length) textEl.dataset.stores = [...new Set(stores.map(s => String(s).toUpperCase()))].join(',');
    else delete textEl.dataset.stores;
    // Optional snooze IDENTITY, separate from the displayed text. A DM-pushed
    // reminder is a deliberate escalation, so it must break through an existing
    // snooze even when its wording happens to match what was snoozed (same DM,
    // same counts, sent again after the manager acked the previous one). Without
    // this the second nudge would be silently swallowed. Falls back to the
    // summary, which is the right behaviour for the generic aging alert.
    if (sig) textEl.dataset.sig = sig;
    else delete textEl.dataset.sig;
    if (iconEl) { iconEl.textContent = icon; iconEl.style.display = ''; }
    textEl.style.display = 'flex';
    textEl.style.flexDirection = 'column';
    textEl.style.gap = '7px';
    textEl.innerHTML = `
        <div style="line-height:1.4;"><strong>${titleHtml}</strong></div>
        <div style="line-height:1.4; opacity:0.96;">${bodyHtml}</div>
        <button onclick="closeClaimAlertBubble(); openClaimsModal(); switchClaimsTab('view');"
            style="align-self:flex-start; background:rgba(255,255,255,0.18); border:1px solid rgba(255,255,255,0.5); color:#fff; font-weight:800; font-size:12px; border-radius:8px; padding:6px 12px; cursor:pointer;"
            onmouseover="this.style.background='rgba(255,255,255,0.3)';" onmouseout="this.style.background='rgba(255,255,255,0.18)';">Review claims</button>`;
    bubble.style.display = 'flex';
    _positionClaimAlert();
    bubble.animate([
        { transform: 'scale(0.95) translateX(10px)', opacity: 0 },
        { transform: 'scale(1) translateX(0)', opacity: 1 }
    ], { duration: 400, easing: 'cubic-bezier(0.4, 0, 0.2, 1)' });
}

function _isINRTicket(r) {
    return String(r?.reason_type || '').toLowerCase().startsWith('item not received');
}

// Shared "check tracking" instruction for Item-Not-Received tickets, appended to
// whichever red bubble is surfacing them.
function _inrGuidanceHtml(inrCount) {
    if (!inrCount) return '';
    const noun = inrCount === 1 ? 'an <b>Item Not Received</b> ticket' : `${inrCount} <b>Item Not Received</b> tickets`;
    return `<div style="line-height:1.4; opacity:0.96; margin-top:2px;">That includes ${noun} — check tracking first: if it's since been delivered, call eBay for the refund and mark it <b>Recovered</b>. If it's still lost, open a claim on the ticket.</div>`;
}

function _showClaimAlert(count, inrCount = 0, breakdown = '', stores = null) {
    const body = (count === 1
        ? '1 claim has been open over 7 days. Please review it.'
        : `${count} claims have been open over 7 days. Please review them.`)
        + (breakdown ? ` <b>${escapeHtml(breakdown)}</b>` : '')
        + _inrGuidanceHtml(inrCount);
    // With a per-store breakdown the full sentence runs close to the feed's
    // 100-char cap, and the breakdown is last — so an overflow would cut exactly
    // the store info a multi-store manager needs. Lead with counts + stores and
    // demote the INR flag to a short tag; the guidance is in the tool anyway.
    const summary = breakdown
        ? `${count} open over 7 days · ${breakdown}` + (inrCount ? ` · ${inrCount} Item Not Received` : '')
        : _claimFeedSummary(count, inrCount);
    _renderClaimBubble('⚠️', 'Claims Review', body, summary, null, stores);
}

// One line for the feed: the counts, and a flag that some are Item Not Received.
// The full "check tracking first…" guidance stays in the claims tool, which is
// where the row's click takes you anyway.
function _claimFeedSummary(count, inrCount) {
    const base = count === 1 ? '1 claim open over 7 days' : `${count} claims open over 7 days`;
    if (!inrCount) return base + '.';
    return `${base}, including ${inrCount === 1 ? '1 Item Not Received' : inrCount + ' Item Not Received'} — check tracking first.`;
}

// Console preview of the red aging-claim bubble (no need to wait 7 days):
// open DevTools → console and run:  _previewClaimAlert()
window._previewClaimAlert = function () { _showClaimAlert(2, 1); };

// Console diagnostic for "why is there no claim row in the feed?". Walks the whole
// chain in order and reports the first link that would suppress it, so a silent
// alert can be traced without guessing. Run:  _dbgClaims()
window._dbgClaims = async function () {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase();
    const stores = _claimStores();
    const out = {
        buildVersion: (document.querySelector('script[src*="speeks.js"]') || {}).src || '?',
        user: sessionStorage.getItem('speeksUserName'),
        role, isMSM: isMultiStoreManager(), stores,
        roleAllowed: _CLAIM_ALERT_ROLES.has(role),
    };
    if (!out.roleAllowed) { out.VERDICT = 'BLOCKED: role not in _CLAIM_ALERT_ROLES'; console.table(out); return out; }
    if (!stores.length) { out.VERDICT = 'BLOCKED: no store scope'; console.table(out); return out; }

    const q = `stores=${encodeURIComponent(stores.join(','))}&v=${Date.now()}`;
    try {
        const rj = await (await fetch(`${CLAIMS_URL}?reminders=1&${q}`)).json();
        const acked = _ackedReminders();
        out.remindersFromApi = (rj.data || []).length;
        out.remindersFresh = (rj.data || []).filter(r => !acked.has(r.id)).length;
        out.ackedKey = _ackedRemindersKey();

        const cj = await (await fetch(`${CLAIMS_URL}?${q}`)).json();
        const sup = new Set((cj.data || []).filter(r => r.parent_id).map(r => r.parent_id));
        const aging = (cj.data || []).filter(r => !sup.has(r.id) && _isClaimAging(r));
        const seen = _seenAgingClaims();
        out.agingCount = aging.length;
        out.agingUnseen = aging.filter(r => !seen.has(r.id)).length;
        out.seenKey = _seenAgingKey();
    } catch (e) { out.VERDICT = 'BLOCKED: fetch failed (ad blocker?) — ' + e.message; console.table(out); return out; }

    const el = document.getElementById('claimAlertBubble');
    out.bubbleDisplay = el ? getComputedStyle(el).display : 'MISSING';
    out.feedSummary = (document.getElementById('claimAlertBubbleText') || {}).dataset?.summary || '(none)';
    out.dismissedToday = Object.keys(_samGetDismissedRem()).join(', ') || '(none)';
    out.claimsInFeed = _samGatherReminders().some(r => r.key === 'claims');
    out.reminderOwnsBubble = _reminderBubbleActive;

    out.VERDICT = out.bubbleDisplay === 'flex'
        ? (out.claimsInFeed ? 'Bubble is live — row IS in the feed' : 'Bubble is live but snoozed at this exact wording')
        : (out.remindersFresh === 0 && out.agingUnseen === 0
            ? 'BLOCKED: everything already acked/seen for this user'
            : 'BLOCKED: checks have not run yet or errored — reload and wait ~2s');
    console.table(out);
    return out;
};

// --- STORE COMMENTS LOGIC ---

// Per-comment fingerprint tracking so new comments always show even after closing a previous one
function _getSeenCommentKeys() {
    try { return new Set(JSON.parse(sessionStorage.getItem('speeksSeenCommentKeys') || '[]')); }
    catch(e) { return new Set(); }
}
function _saveSeenCommentKeys(keys) {
    sessionStorage.setItem('speeksSeenCommentKeys', JSON.stringify([...keys]));
}
function _commentKey(c) {
    return `${String(c.store||'').trim()}|${String(c.date||'').trim()}|${String(c.author||'').trim()}|${String(c.message||'').trim()}`.slice(0, 120);
}

// Ids of the store comments currently shown in the bubble — marked read when
// the user dismisses (X) the bubble. Accumulates across polls until dismissed.
let _shownCommentIds = [];

let _storeCommentPollingStarted = false;
function startStoreCommentPolling() {
    if (_storeCommentPollingStarted) return;
    _storeCommentPollingStarted = true;
    setInterval(() => { fetchAndDisplayStoreComment(); checkClaimReminders(); }, 30 * 1000);
}

// Opens the modal normally from the Speeks Tools menu (Fully Unlocked)
// null = exec (every store's reads); an array = a manager's own store(s), which
// scopes both the Read Receipts fetch and the store pickers.
let _commentReadsStoreScope = null;
const _EXEC_STORE_OPTIONS =
    '<option value="ALL">All Stores</option>' +
    '<option value="OVL">OVL</option>' +
    '<option value="LEE">LEE</option>' +
    '<option value="WSP">WSP</option>' +
    '<option value="MPL">MPL</option>' +
    '<option value="BAL">BAL</option>';

function toggleSendCommentModal() {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase();
    // DM/CEO keep the company-wide sender; everyone else with the tool (Manager,
    // Owner Manager, MSM) gets a version scoped to their own store(s).
    if (role === 'district manager' || role === 'ceo') { openCEOStoreComment(null); return; }
    openManagerStoreComment();
}

// Opens the modal from the CEO Rings and locks it to the specific store
window.openCEOStoreComment = function(targetStore) {
    closeAllModals();
    const dropdown = document.getElementById('sendCommentModal');
    if (!dropdown) return;

    dropdown.classList.add('show');
    lockAndBlurScreen();
    document.getElementById('commentMessageInput').value = '';

    const storeSelect = document.getElementById('commentStoreSelect');
    if (storeSelect) {
        // Restore the full exec list (ALL + every store) in case a manager build
        // of this modal ran earlier in the session.
        storeSelect.innerHTML = _EXEC_STORE_OPTIONS;
        if (targetStore) {
            // Lock it to the specific store clicked
            storeSelect.value = targetStore;
            storeSelect.disabled = true;
            storeSelect.style.opacity = '0.6';
            storeSelect.style.cursor = 'not-allowed';
        } else {
            // Unlock it for general use via the Speeks Tools menu
            storeSelect.value = 'ALL';
            storeSelect.disabled = false;
            storeSelect.style.opacity = '1';
            storeSelect.style.cursor = 'pointer';
        }
    }

    _commentReadsStoreScope = null; // exec sees every store's reads
    // Two tabs: Send Message | Read Receipts (built once, then reset to Send).
    _setupCommentModalTabs();
    _scopeCommentReadsFilter(null);
    _commentReadsCache = null; // refetch reads each time the modal opens
    switchCommentTab('send');
};

// Manager / Owner Manager / Multi-Store Manager: send only to their own store(s).
// Single-store managers get a locked selector; the MSM gets BAL/MPL unlocked. The
// message is authored under their name (submitStoreComment reads speeksUserName)
// so on the recipient side it behaves identically to a DM/CEO comment.
window.openManagerStoreComment = function() {
    closeAllModals();
    const dropdown = document.getElementById('sendCommentModal');
    if (!dropdown) return;

    dropdown.classList.add('show');
    lockAndBlurScreen();
    document.getElementById('commentMessageInput').value = '';

    const isMSM = typeof isMultiStoreManager === 'function' && isMultiStoreManager();
    const active = String(sessionStorage.getItem('speeksUserStore') || '').toUpperCase();
    const stores = isMSM
        ? MULTISTORE_MANAGER_STORES.map(s => String(s).toUpperCase())
        : (active ? [active] : []);
    _commentReadsStoreScope = stores.slice();

    const storeSelect = document.getElementById('commentStoreSelect');
    if (storeSelect) {
        storeSelect.innerHTML = stores.map(s => `<option value="${s}">${s}</option>`).join('');
        storeSelect.value = stores.includes(active) ? active : (stores[0] || '');
        const lock = stores.length <= 1; // one store = nothing to choose
        storeSelect.disabled = lock;
        storeSelect.style.opacity = lock ? '0.6' : '1';
        storeSelect.style.cursor = lock ? 'not-allowed' : 'pointer';
    }

    _setupCommentModalTabs();
    _scopeCommentReadsFilter(stores);
    _commentReadsCache = null;
    switchCommentTab('send');
};

// Restrict the Read Receipts store dropdown. Managers see only their store(s);
// exec (null/empty) gets the full All-Stores list.
function _scopeCommentReadsFilter(stores) {
    const sel = document.getElementById('commentReadsStore');
    if (!sel) return;
    if (stores && stores.length) {
        const opts = stores.length > 1
            ? ['<option value="ALL">All My Stores</option>'].concat(
                  stores.map(s => `<option value="${s}">${s}</option>`))
            : stores.map(s => `<option value="${s}">${s}</option>`);
        sel.innerHTML = opts.join('');
        sel.value = stores.length > 1 ? 'ALL' : stores[0];
    } else {
        sel.innerHTML = _EXEC_STORE_OPTIONS;
        sel.value = 'ALL';
    }
}

// Adds the Send | Read Receipts tab bar + a reads panel to the send modal (once).
function _setupCommentModalTabs() {
    const modal = document.getElementById('sendCommentModal');
    if (!modal || document.getElementById('commentTabBar')) return;
    const header = modal.querySelector('.modal-header');
    const content = modal.querySelector('.manage-content');
    if (!header || !content) return;

    const bar = document.createElement('div');
    bar.id = 'commentTabBar';
    bar.style.cssText = 'padding:14px 18px 14px;';
    bar.innerHTML = `<div class="notif-tabs" style="display:inline-flex;">
        <button id="comment-tab-send" class="tab-btn active" onclick="switchCommentTab('send')">Send Message</button>
        <button id="comment-tab-reads" class="tab-btn" onclick="switchCommentTab('reads')">Read Receipts</button>
    </div>`;
    header.insertAdjacentElement('afterend', bar);

    const panel = document.createElement('div');
    panel.id = 'commentReadsPanel';
    panel.className = 'manage-content';
    panel.style.display = 'none';
    panel.innerHTML = `
        <div style="display:flex; align-items:center; gap:10px; margin-bottom:14px; flex-wrap:wrap;">
            <label class="form-label-caps" style="margin:0;">Store</label>
            <select id="commentReadsStore" class="form-input-lg" style="max-width:220px;" onchange="renderStoreCommentReads()">
                <option value="ALL">All Stores</option>
                <option value="OVL">OVL</option>
                <option value="LEE">LEE</option>
                <option value="WSP">WSP</option>
                <option value="MPL">MPL</option>
                <option value="BAL">BAL</option>
            </select>
        </div>
        <div id="commentReadsStats"></div>
        <div id="commentReadsList"></div>`;
    content.insertAdjacentElement('afterend', panel);
}

function switchCommentTab(tab) {
    const isSend = tab !== 'reads';
    const modal = document.getElementById('sendCommentModal');
    if (!modal) return;
    document.getElementById('comment-tab-send')?.classList.toggle('active', isSend);
    document.getElementById('comment-tab-reads')?.classList.toggle('active', !isSend);
    const form = modal.querySelector('.manage-content'); // the send form (first .manage-content)
    const footer = modal.querySelector('.manage-footer');
    const panel = document.getElementById('commentReadsPanel');
    if (form) form.style.display = isSend ? '' : 'none';
    if (footer) footer.style.display = isSend ? '' : 'none';
    if (panel) panel.style.display = isSend ? 'none' : 'flex';
    if (!isSend) loadStoreCommentReads();
}

let _commentReadsCache = null;

// Fetch the last 30 days of comments + their reads (once per modal open), then render.
async function loadStoreCommentReads() {
    const listEl = document.getElementById('commentReadsList');
    if (!listEl) return;
    if (!_commentReadsCache) {
        listEl.innerHTML = `<div style="color:#94a3b8; font-size:13px;">Loading…</div>`;
        try {
            const scope = (_commentReadsStoreScope && _commentReadsStoreScope.length)
                ? `&stores=${encodeURIComponent(_commentReadsStoreScope.join(','))}` : '';
            const res = await fetch(`${STORE_COMMENT_URL}?mode=reads${scope}&v=${Date.now()}`);
            const rows = await res.json();
            _commentReadsCache = Array.isArray(rows) ? rows : [];
        } catch (e) {
            listEl.innerHTML = `<div style="color:var(--red-alert); font-size:13px;">Failed to load read counts.</div>`;
            return;
        }
    }
    renderStoreCommentReads();
}

function _crStat(label, val) {
    return `<div style="flex:1; min-width:92px; background:#fff; border:1px solid #e2e8f0; border-radius:12px; padding:11px 14px;">
        <div style="font-size:22px; font-weight:900; color:#1e293b; line-height:1;">${val}</div>
        <div style="font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:.4px; color:#94a3b8; margin-top:3px;">${label}</div>
    </div>`;
}

// Render the cached reads filtered by the store dropdown, with stats + per-store breakdown.
function renderStoreCommentReads() {
    const statsEl = document.getElementById('commentReadsStats');
    const listEl = document.getElementById('commentReadsList');
    if (!listEl) return;
    const all = _commentReadsCache || [];
    const store = document.getElementById('commentReadsStore')?.value || 'ALL';
    const rows = store === 'ALL' ? all : all.filter(r => String(r.store || '').toUpperCase() === store);

    const msgs = rows.length;
    const totalReads = rows.reduce((s, r) => s + (r.readCount || 0), 0);
    const avg = msgs ? (totalReads / msgs) : 0;

    let statsHtml = `<div style="display:flex; gap:10px; flex-wrap:wrap; margin-bottom:14px;">
        ${_crStat('Messages', msgs)}
        ${_crStat('Total reads', totalReads)}
        ${_crStat('Avg reads / msg', avg.toFixed(1))}
    </div>`;

    // Per-store breakdown (only meaningful on the All view).
    if (store === 'ALL' && msgs) {
        const byStore = {};
        all.forEach(r => {
            const s = String(r.store || '').toUpperCase() || '—';
            (byStore[s] ||= { m: 0, reads: 0 });
            byStore[s].m++; byStore[s].reads += (r.readCount || 0);
        });
        statsHtml += `<div style="background:#fff; border:1px solid #e2e8f0; border-radius:10px; padding:4px 2px; margin-bottom:14px;">`
            + Object.keys(byStore).sort().map(s => {
                const v = byStore[s];
                return `<div style="display:flex; justify-content:space-between; align-items:center; gap:10px; padding:6px 12px; font-size:12.5px; border-bottom:1px solid #f1f5f9;">
                    <span style="font-weight:800; color:var(--slate-charcoal);">${escapeHtml(s)}</span>
                    <span style="color:#64748b; text-align:right; white-space:nowrap; font-variant-numeric:tabular-nums;">${v.m} msg · ${v.reads} reads · ${(v.reads / v.m).toFixed(1)} avg</span>
                </div>`;
            }).join('')
            + `</div>`;
    }
    if (statsEl) statsEl.innerHTML = statsHtml;

    if (!msgs) {
        listEl.innerHTML = `<div style="color:#94a3b8; font-size:13px;">No messages${store !== 'ALL' ? ' for ' + escapeHtml(store) : ''} in the last 30 days.</div>`;
        return;
    }
    listEl.innerHTML = rows.slice(0, 80).map(r => {
        const names = (r.readBy || []).map(escapeHtml).join(', ');
        const msg = escapeHtml(String(r.message || '').slice(0, 160));
        const cnt = r.readCount || 0;
        const sentBy = r.author ? ` · <span style="font-weight:600; color:#64748b;">by ${escapeHtml(r.author)}</span>` : '';
        return `<div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px; padding:11px 13px; margin-bottom:8px;">
            <div style="display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:5px;">
                <span style="font-size:11px; font-weight:800; color:var(--slate-charcoal);">${escapeHtml(r.store || '')} · ${escapeHtml(r.date || '')}${sentBy}</span>
                <span style="font-size:11px; font-weight:900; color:${cnt ? '#059669' : '#94a3b8'}; background:#fff; border:1px solid #e2e8f0; border-radius:20px; padding:3px 10px; white-space:nowrap;">👁 Read by ${cnt}</span>
            </div>
            <div style="font-size:12.5px; color:var(--slate-charcoal); line-height:1.4;${names ? ' margin-bottom:5px;' : ''}">${msg}</div>
            ${names ? `<div style="font-size:11px; color:#64748b;"><strong style="color:#94a3b8;">Read by:</strong> ${names}</div>` : ''}
        </div>`;
    }).join('');
}

async function submitStoreComment() {
    const store = document.getElementById('commentStoreSelect').value;
    const message = document.getElementById('commentMessageInput').value.trim();
    const btn = document.getElementById('sendCommentBtn');

    if (!store) {
        alert("No store is set for your account, so there's nowhere to post this. Contact your DM.");
        return;
    }
    if (!message) {
        alert("Please write a message before sending.");
        return;
    }

    btn.innerText = "Sending...";
    btn.style.opacity = "0.7";

    const todayStr = new Date().toLocaleDateString('en-US', { timeZone: 'America/Chicago' });
    const author = sessionStorage.getItem('speeksUserName') || 'Executive Team';

    const payload = {
        date: todayStr,
        store: store,
        author: author,
        message: message
    };

    try {
        await postWrite(STORE_COMMENT_URL, payload);

        alert("Success! The message is live for " + store);
        closeAllModals();
    } catch (e) {
        alert("Failed to send the message: " + (e.message || e));
    } finally {
        btn.innerText = "Send Message";
        btn.style.opacity = "1";
    }
}

// Close the bubble AND log a read for each comment it was showing — dismissing
// the message (X) is the "I saw this" signal DM/CEO see in the send tool.
window.closeDailyCommentBubble = function() {
    const bubble = document.getElementById('dailyMessageBubble');
    if (bubble) bubble.style.display = 'none';
    if (typeof _positionClaimAlert === 'function') _positionClaimAlert(); // claim alert moves back up

    if (_shownCommentIds.length) {
        const user = sessionStorage.getItem('speeksUserName') || null;
        const ids = _shownCommentIds.slice();
        _shownCommentIds = [];
        ids.forEach(_addLocalNoteRead);   // survive a re-fetch before the POST lands
        postWrite(STORE_COMMENT_URL, { type: 'mark_read', commentIds: ids, user })
            .catch(err => console.warn('comment mark_read failed:', err.message));
    }
};

// Local read-cache for store comments, mirroring speeksLocalRead_ for announcements.
// Marking a comment read is a fire-and-forget POST; until the server has recorded
// it, every re-fetch (the 30s poll, a new announcement landing, a page change)
// returns readByMe:false and the comment springs back as unread. Announcements,
// reminders and patch notes all already keep a local copy of the read — comments
// were the one type that trusted the round-trip. Entries are dropped once the
// server confirms, so this never masks a genuinely-unread comment.
// Which stores' comments belong to this user. A Multi-Store Manager covers both
// their stores at once — the checklist, audit and listing-goals widgets all
// already fan out over MULTISTORE_MANAGER_STORES, but comments were still
// matching the single active store, so an MSM sitting on BAL could not see MPL's
// comments at all (and vice versa) no matter which dashboard they switched to.
function _commentStoresForUser() {
    try {
        if (typeof isMultiStoreManager === 'function' && isMultiStoreManager()) {
            return MULTISTORE_MANAGER_STORES.map(s => String(s).toUpperCase());
        }
    } catch (_) {}
    // NO 'OVL' fallback here. Everywhere else in the app that default is harmless
    // (it picks which store you're acting on, and by then the store is known), but
    // this decides which store's comments you're allowed to SEE. During sign-in
    // there's a window where speeksUnlocked is set before speeksUserStore is, and
    // a poll landing in that window served OVL's comments to whoever was logging
    // in — they flashed up and vanished on the next poll once the store resolved.
    // Unknown store means show nothing, never someone else's store.
    const s = String(sessionStorage.getItem('speeksUserStore') || '').trim().toUpperCase();
    return s ? [s] : [];
}

function _noteReadKey() {
    const u = (sessionStorage.getItem('speeksUserName') || 'anon').trim().toLowerCase();
    return 'speeksLocalNoteRead_' + u;
}
function _getLocalNoteReads() {
    try { return new Set(JSON.parse(localStorage.getItem(_noteReadKey()) || '[]')); } catch (_) { return new Set(); }
}
function _addLocalNoteRead(id) {
    if (!id) return;
    const s = _getLocalNoteReads();
    s.add(String(id));
    try { localStorage.setItem(_noteReadKey(), JSON.stringify([...s])); } catch (_) {}
}

async function fetchAndDisplayStoreComment() {
    // MOCD works out of a store but isn't part of its team, so store comments
    // aren't meant for them.
    if ((sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim() === 'mocd') return;
    const userStore = String(sessionStorage.getItem('speeksUserStore') || '').trim().toUpperCase();
    // Set, not a single value — an MSM matches both of their stores at once, so the
    // same comments show on either dashboard rather than following the switcher.
    const myStores = new Set(_commentStoresForUser());
    // Store not resolved yet (mid sign-in): bail rather than fall back to a real
    // store. ALL/CORP comments are withheld for one poll too, which is the right
    // trade — they arrive a few seconds later instead of leaking another store's.
    if (!myStores.size) return;
    const isMyStore = cStore => myStores.has(cStore) || cStore === 'ALL' || cStore === 'CORP';
    const userName = String(sessionStorage.getItem('speeksUserName') || '').trim();
    const todayStr = new Date().toLocaleDateString('en-US', { timeZone: 'America/Chicago' });

    try {
        // reader= tells the fn which comments this user already dismissed, so a
        // read (X) permanently suppresses the message across sign-outs.
        const res = await fetch(`${STORE_COMMENT_URL}?reader=${encodeURIComponent(userName)}&v=${Date.now()}`);
        const comments = await res.json();

        // A comment is read if the server says so OR we recorded it locally and the
        // server hasn't caught up yet. Once the server confirms, drop the local copy
        // so the cache can't grow without bound or outlive the record it shadows.
        const localReads = _getLocalNoteReads();
        let localDirty = false;
        comments.forEach(c => {
            if (c.readByMe && localReads.delete(String(c.id))) localDirty = true;
        });
        if (localDirty) { try { localStorage.setItem(_noteReadKey(), JSON.stringify([...localReads])); } catch (_) {} }
        const isNoteRead = c => !!c.readByMe || localReads.has(String(c.id));

        // Store comments expire OFF THE DASHBOARD at midnight but stay in the hub
        // ("All updates") as a permanent archive: one from before today is just
        // auto-marked read there (dimmed, out of Unread, no nag) — the system reads
        // it for them once the day passes. Today's follow the real read state, so a
        // user can Mark as read to clear it off their feed early. The dashboard feed
        // shows only today's UNREAD. Auto-read is display-only — it posts nothing, so
        // it never fabricates a read in the DM/CEO read receipts.
        const isCommentToday = c => {
            const rawDateStr = String(c.date || '').trim();
            let parsedDateStr = "";
            try { const parsed = new Date(c.date); if (!isNaN(parsed.getTime())) parsedDateStr = parsed.toLocaleDateString('en-US', { timeZone: 'America/Chicago' }); } catch (e) {}
            return parsedDateStr === todayStr || rawDateStr.includes(todayStr);
        };
        // Never show a user their OWN store note — a manager sending to their own
        // store would otherwise get their message back as a bubble/feed item. (DM/CEO
        // never hit this since their store isn't a real store, but the guard is
        // author-based so it's correct for everyone.) Excludes it from the bubble,
        // the Action Menu feed and the hub archive alike.
        const forMeComments = comments
            .filter(c => isMyStore(String(c.store || '').trim().toUpperCase()))
            .filter(c => String(c.author || '').trim().toLowerCase() !== userName.toLowerCase())
            .reverse(); // newest first

        window._hubStoreNotes = forMeComments.map(c => ({
            author: c.author, text: c.message || c.text || '', date: c.date, created_at: c.created_at, store: c.store, id: c.id,
            read: isNoteRead(c) || !isCommentToday(c)   // older-than-today auto-reads
        }));
        try { if (typeof renderHubFeed === 'function') renderHubFeed(); } catch (_) {}

        const todayComments = forMeComments.filter(isCommentToday);

        // Surface today's store notes in the Action Menu feed. Exclude ones the
        // user already marked read (readByMe, from the server) so a dismissed note
        // doesn't reappear on the next sign-in — same rule the bubble uses.
        window._samStoreNotes = todayComments.filter(c => !isNoteRead(c)).map(c => ({
            author: c.author, text: c.message || c.text || '', date: c.date, created_at: c.created_at, store: c.store, id: c.id
        }));
        try { if (typeof renderActionFeed === 'function') renderActionFeed(); } catch (e) { console.warn('Action Menu feed failed:', e); }

        // Show only comments the user hasn't permanently dismissed (readByMe, from
        // the server) and hasn't already seen this session.
        const seenKeys = _getSeenCommentKeys();
        const newComments = todayComments.filter(c => !isNoteRead(c) && !seenKeys.has(_commentKey(c)));
        if (newComments.length === 0) return;

        // Remember which comments are on screen so the X (dismiss) can log a read.
        newComments.forEach(c => { if (c.id && !_shownCommentIds.includes(c.id)) _shownCommentIds.push(c.id); });

        // Mark all today's comments seen now so repeat polls don't re-show the same ones
        todayComments.forEach(c => seenKeys.add(_commentKey(c)));
        _saveSeenCommentKeys(seenKeys);

        if (newComments.length > 0) {
            const bubble = document.getElementById('dailyMessageBubble');
            const textEl = document.getElementById('dailyMessageBubbleText');
            const iconEl = document.getElementById('dailyMessageBubbleIcon');
            
            if (bubble && textEl && iconEl) {
                iconEl.style.display = 'none';
                textEl.style.display = 'flex';
                textEl.style.flexDirection = 'column';
                textEl.style.gap = '8px';
                textEl.style.padding = '2px 0';

                // Build the HTML for new (unseen) messages only
                let messagesHtml = '';
                newComments.forEach(msg => {
                    const authorName = msg.author || 'Executive Team';
                    const emoji = '📣';

                    const cStore = String(msg.store || '').trim().toUpperCase();
                    const isAllStores = (cStore === 'ALL' || cStore === 'CORP');
                    const scopeBadge = isAllStores
                        ? `<span style="display:inline-block;font-size:10px;font-weight:600;background:rgba(255,255,255,0.12);color:#fde68a;border:1px solid rgba(253,230,138,0.35);border-radius:4px;padding:1px 5px;margin-left:5px;vertical-align:middle;letter-spacing:0.3px;">Company</span>`
                        : `<span style="display:inline-block;font-size:10px;font-weight:600;background:rgba(255,255,255,0.08);color:#a7f3d0;border:1px solid rgba(167,243,208,0.3);border-radius:4px;padding:1px 5px;margin-left:5px;vertical-align:middle;letter-spacing:0.3px;">${cStore}</span>`;

                    messagesHtml += `
                        <div style="display: flex; align-items: flex-start; gap: 8px; line-height: 1.4;">
                            <span style="font-size: 15px; flex-shrink: 0; margin-top: -2px;">${emoji}</span>
                            <span><strong style="color: #fef3c7;">${authorName}:</strong>${scopeBadge} <span style="opacity: 0.95;">${msg.message}</span></span>
                        </div>
                    `;
                });

                textEl.innerHTML = messagesHtml;

                setTimeout(() => {
                    bubble.style.display = 'flex';
                    if (typeof _positionClaimAlert === 'function') _positionClaimAlert(); // push the red claim alert below this
                    bubble.animate([
                        { transform: 'scale(0.9) translateX(10px)', opacity: 0 },
                        { transform: 'scale(1) translateX(0)', opacity: 1 }
                    ], { duration: 400, easing: 'cubic-bezier(0.4, 0, 0.2, 1)' });
                }, 1500);
            }
        }
    } catch (e) {
        console.error("Failed to fetch store comments. Error:", e);
    }
}

// --- 14.5. MODULE: WEEKLY CHAMPIONS (LISTERS & BUYERS) ---
async function fetchChampions() {
    const listerBody = document.getElementById('lister-champions-body');
    const buyerBody = document.getElementById('buyer-champions-body');
    const grBody = document.getElementById('google-review-champions-body');
    const lDate = document.getElementById('lister-champions-date');
    const bDate = document.getElementById('buyer-champions-date');
    const grDate = document.getElementById('google-review-champions-date');
    try {
        const stores = ['OVL', 'LEE', 'WSP', 'MPL', 'BAL'];
        let allListers = [];
        let allBuyers = [];
        let allGoogleReviews = [];

        // 1. Calculate "Week Of" based on the previous Monday
        const now = new Date();
        const day = now.getDay();
        const diffToMonday = day === 0 ? -6 : 1 - day;
        const startOfWeek = new Date(now);
        startOfWeek.setDate(now.getDate() + diffToMonday);
        const weekText = "Week of " + startOfWeek.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
        
        if (lDate) lDate.innerText = weekText;
        if (bDate) bDate.innerText = weekText;
        if (grDate) grDate.innerText = weekText;

        // 2. User Directory matching (Gets Full Names)
        let authCache = {};
        try { authCache = JSON.parse(localStorage.getItem('speeksAuthCache')) || {}; } catch(e){}
        const users = authCache.users || [];
        const getFullName = (shortName) => {
            const s = String(shortName).toLowerCase().trim();
            const matched = users.find(u => {
                const full = String(u.name).toLowerCase().trim();
                return full === s || full.split(' ')[0] === s || full.startsWith(s);
            });
            return matched ? matched.name : shortName; 
        };

        // 3. FETCH LISTERS
        const listerFetches = stores.map(s => fetch(`${WEEKLY_KPI_URL}?store=${s}&v=${Date.now()}`).then(r => r.json()));
        const listerResults = await Promise.all(listerFetches);

        listerResults.forEach((d, storeIdx) => {
            // New clean JSON format: { employees, store_total, period_label }
            (d.employees || []).forEach(e => {
                const listed  = parseNum(e.listed_count);
                const reviews = parseNum(e.mtd_google_reviews);
                if (listed  > 0) allListers.push({ name: getFullName(e.employee_name), store: stores[storeIdx], listed });
                if (reviews > 0) allGoogleReviews.push({ name: getFullName(e.employee_name), store: stores[storeIdx], reviews });
            });
        });

        // 4. FETCH BUYERS — ranks by the Buyer Champion Final Score from the old
        // Team Member KPIs "Weekly Scores" tab, computed from each store's weekly entries:
        //   Final = (ConvScore + MarginScore) × (BuyValue + 1.2 × #Converted) / 100
        try {
            const buyerFetches = stores.map(s => fetch(`${WEEKLY_KPI_URL}?store=${s}&v=${Date.now()}`).then(r => r.json()));
            const buyerResults = await Promise.all(buyerFetches);
            buyerResults.forEach((d, storeIdx) => {
                (d.employees || []).forEach(e => {
                    const bv  = parseNum(e.buying_value);
                    const bc  = parseNum(e.buying_cost);
                    const tc  = parseNum(e.transaction_count);
                    const tco = parseNum(e.transaction_converted);
                    if (bv <= 0) return;
                    const conv = tc > 0 ? tco / tc : 0;
                    const gm   = 1 - bc / bv;
                    const convScore = conv >= 0.95 ? 100 : conv >= 0.9 ? 400 * conv - 280 : conv >= 0.8 ? 600 * conv - 460 : conv >= 0.7 ? 200 * conv - 140 : 0;
                    const mgnScore  = gm >= 0.6 ? 100 : gm >= 0.5 ? 800 * gm - 380 : gm >= 0.45 ? 400 * gm - 180 : 0;
                    const score = ((convScore + mgnScore) * (bv + tco * 1.2)) / 100;
                    if (score > 0) allBuyers.push({ name: getFullName(e.employee_name), store: stores[storeIdx], score });
                });
            });
        } catch (buyerErr) {
            console.error("Failed to fetch Weekly Buyers:", buyerErr);
        }

        // 5. BUILDER HELPER — featured champion + runner-up rows (calm redesign)
        const buildPodiumHtml = (dataArray, sortBy, labelText, type) => {
            const merged = {};
            dataArray.forEach(emp => {
                if (!merged[emp.name]) merged[emp.name] = { ...emp };
                else {
                    if (type === 'lister') merged[emp.name].listed += emp.listed;
                    if (type === 'buyer') merged[emp.name].score = Math.max(merged[emp.name].score, emp.score);
                    if (type === 'review') merged[emp.name].reviews += emp.reviews;
                }
            });

            const uniqueEmps = Object.values(merged);
            uniqueEmps.sort((a, b) => b[sortBy] - a[sortBy]);
            const top3 = uniqueEmps.slice(0, 3);

            if (top3.length === 0) return '<div class="champion-empty">No data available yet.</div>';

            // Buyer raw score scales with dollars (tens of thousands), so show a
            // compact, absolute "points" figure: raw score / 100, rounded. This
            // preserves the exact ranking while staying small and readable.
            const valOf = (emp) => type === 'lister' ? emp.listed
                                 : type === 'review' ? emp.reviews
                                 : Math.round(emp.score / 100);

            const champ = top3[0];
            const runners = top3.slice(1);

            const runnerHtml = runners.map((emp, i) => {
                const place = i + 2;                       // 2 or 3
                const cls = place === 2 ? 's' : 'b';       // silver / bronze
                return `
                <div class="cf-run">
                    <span class="cf-rk ${cls}">${place}</span>
                    <div class="cf-rinfo">
                        <span class="cf-rn">${emp.name}</span>
                        <span class="cf-rs">${emp.store}</span>
                    </div>
                    <span class="cf-rv">${valOf(emp)}</span>
                </div>`;
            }).join('');

            return `
            <div class="champ-featured-wrap">
                <div class="cf-feat">
                    <span class="cf-crown">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
                        Champion
                    </span>
                    <div class="cf-id">
                        <div class="cf-name">${champ.name}</div>
                        <div class="cf-store">${champ.store}</div>
                    </div>
                    <div class="cf-val"><b>${valOf(champ)}</b><span>${labelText}</span></div>
                </div>
                ${runners.length ? `<div class="cf-runners">${runnerHtml}</div>` : ''}
            </div>`;
        };

        feedChampionsToTicker(allBuyers, allListers, allGoogleReviews);
        _tickerSourceDone('champions');

        if (listerBody) listerBody.innerHTML = buildPodiumHtml(allListers, 'listed', 'Items', 'lister');
        if (grBody) grBody.innerHTML = buildPodiumHtml(allGoogleReviews, 'reviews', 'Reviews', 'review');
        if (buyerBody) buyerBody.innerHTML = buildPodiumHtml(allBuyers, 'score', 'Score', 'buyer');

    } catch (e) {
        if (listerBody) listerBody.innerHTML = '<div style="color: var(--red-alert); font-weight: bold;">Failed to load Champions.</div>';
        if (grBody) grBody.innerHTML = '<div style="color: var(--red-alert); font-weight: bold;">Failed to load Champions.</div>';
        if (buyerBody) buyerBody.innerHTML = '<div style="color: var(--red-alert); font-weight: bold;">Failed to load Champions.</div>';
        _tickerSourceDone('champions');
    }
}

// ============================================================================
// MANAGER CHECKLIST MODULE
// ============================================================================
let currentChecklistTab = 'daily';
let checklistDataCache = { daily: [], weekly: [], monthly: [], quarterly: [] };
// Multi-Store Manager (e.g. BAL + MPL): one checklist cache per managed store, so
// both stores' lists render stacked in the same panel without switching dashboards.
// { BAL: {daily,weekly,monthly,quarterly}, MPL: {...} }. Empty for everyone else.
let checklistDataCacheMS = {};
const _pendingTogglesMS = new Map();   // key: "STORE::id" -> { checked, expiresAt }
function _isMSMChecklist() {
    return typeof isMultiStoreManager === 'function' && isMultiStoreManager();
}
// Tracks optimistic toggle state for up to 20 seconds so a slow backend response
// can't overwrite a locally-checked item before Apps Script persists it.
const _pendingToggles = new Map(); // id -> { checked, expiresAt }

function _applyPendingToggles() {
    const now = Date.now();
    for (const [id, { checked, expiresAt }] of _pendingToggles) {
        if (now > expiresAt) { _pendingToggles.delete(id); continue; }
        for (const tab of Object.keys(checklistDataCache)) {
            const item = checklistDataCache[tab].find(i => i.id === id);
            if (item) item.checked = checked;
        }
    }
}

// For assistant managers, returns the store's primary manager name so both share the same
// checklist data (incl. BAL/MPL, whose manager is the Multi-Store Manager — see
// _resolveStoreManager). All other roles return their own name, preserving existing behavior.
function getChecklistUser() {
    const role = sessionStorage.getItem('speeksUserRole') || '';
    const store = sessionStorage.getItem('speeksUserStore') || 'OVL';
    const userName = sessionStorage.getItem('speeksUserName') || 'Unknown';

    if (role !== 'assistant manager') return userName;
    return _resolveStoreManager(store) || userName;
}

// MOCD gets a personal-only checklist: no store broadcasts or DM required
// tasks — it starts blank until they (or a DM) add tasks for them directly.
function _checklistPersonalParam() {
    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase().trim();
    return role === 'mocd' ? '&personal=1' : '';
}

function switchChecklistTab(tab) {
    currentChecklistTab = tab;
    document.getElementById('cl-tab-daily').classList.toggle('active', tab === 'daily');
    document.getElementById('cl-tab-weekly').classList.toggle('active', tab === 'weekly');
    document.getElementById('cl-tab-monthly').classList.toggle('active', tab === 'monthly');
    
    // Safety check just in case the button isn't on the screen
    const qTab = document.getElementById('cl-tab-quarterly');
    if (qTab) qTab.classList.toggle('active', tab === 'quarterly');

    if (_isMSMChecklist()) renderChecklistMS(); else renderChecklist();
}

async function loadChecklist() {
    // Only run when the panel is actually opening — not on close.
    // Without this guard, the GET races against the in-flight toggle POST and
    // overwrites the cache with stale (unchecked) data before the backend saves.
    const panel = document.getElementById('checklistSidePanel');
    if (!panel?.classList.contains('open')) return;

    // Multi-Store Managers get both managed stores stacked in one panel.
    if (_isMSMChecklist()) { await loadChecklistMS(); return; }

    const container = document.getElementById('checklistContent');
    const userName = getChecklistUser();
    const store = sessionStorage.getItem('speeksUserStore') || 'OVL';

    const role = (sessionStorage.getItem('speeksUserRole') || '').toLowerCase();
    const isASM = role === 'assistant manager';

    // ASMs see Daily and Weekly; Monthly and Quarterly remain hidden for them
    const weeklyTab = document.getElementById('cl-tab-weekly');
    const monthlyTab = document.getElementById('cl-tab-monthly');
    if (weeklyTab) weeklyTab.style.display = '';
    if (monthlyTab) monthlyTab.style.display = isASM ? 'none' : '';
    if (isASM && currentChecklistTab !== 'daily' && currentChecklistTab !== 'weekly') switchChecklistTab('daily');

    // Only show Quarterly tab for CORP/ALL stores (never for ASMs)
    const qTab = document.getElementById('cl-tab-quarterly');
    if (qTab) {
        if (!isASM && (store === 'CORP' || store === 'ALL')) {
            qTab.style.display = 'inline-flex';
        } else {
            qTab.style.display = 'none';
            if (currentChecklistTab === 'quarterly') switchChecklistTab('daily');
        }
    }

    container.innerHTML = '<div class="status-message">Syncing Checklist...</div>';

    try {
        const res = await fetch(`${CHECKLIST_URL}?user=${encodeURIComponent(userName)}&store=${store}${_checklistPersonalParam()}&v=${Date.now()}`);
        checklistDataCache = await res.json();
        _applyPendingToggles();
        renderChecklist();
    } catch (e) {
        console.error("Checklist Fetch Error", e);
        container.innerHTML = '<div class="status-message" style="color: var(--red-alert);">Failed to load checklist.</div>';
    }
}

function renderChecklist() {
    const container = document.getElementById('checklistContent');
    const rawItems = checklistDataCache[currentChecklistTab] || [];

    // Collapse duplicate GLOBAL/required tasks (same text) that a manager can't
    // delete themselves — e.g. LEE daily had "Live Product Category Check" twice.
    // Personal items are left alone (those have their own delete button).
    const seenGlobal = new Set();
    const items = rawItems.filter(it => {
        if (it.isGlobal) {
            const key = String(it.text || '').trim().toLowerCase();
            if (seenGlobal.has(key)) return false;
            seenGlobal.add(key);
        }
        return true;
    });

    if (items.length === 0) {
        container.innerHTML = `<div style="text-align: center; padding: 30px; color: #888; font-weight: 600; font-size: 13px;">No tasks for this tab. Add one below!</div>`;
        return;
    }

    let html = '';
    items.forEach(item => {
        const completedClass = item.checked ? 'completed' : '';
        
        // Only allow deletion of personal items
        const deleteHtml = !item.isGlobal ? 
            `<button class="cl-delete-btn" onclick="deleteChecklistItem('${item.id}')" data-tip="Delete Task">✖</button>` : '';

        html += `
        <div class="cl-item ${completedClass}">
            <input type="checkbox" class="cl-checkbox" ${item.checked ? 'checked' : ''} onchange="toggleChecklistState('${item.id}', this.checked)">
            <div class="cl-content-wrapper" style="justify-content: center;">
                <span class="cl-text">${escapeHtml(item.text)}</span>
            </div>
            ${deleteHtml}
        </div>`;
    });

    container.innerHTML = html;
    updateChecklistChip();
}

// ============================================================================
// MULTI-STORE MANAGER — dual-store checklist (both managed stores in one panel)
// A MSM (Joseph: BAL + MPL) does everything a manager does, but for every store
// they run. Rather than reload the dashboard to switch stores, we fetch each
// managed store's checklist (user = the MSM) and render them as stacked, per-store
// sections in the same panel, each with its own progress + add row. ASMs are
// single-store and never hit this path, so their behavior is unchanged.
// ============================================================================

// Hide the single-store footer/add row in MSM mode — each store gets its own add row.
function _setMSChecklistChrome(isMS) {
    const inputArea = document.querySelector('#checklistSidePanel .cl-input-area');
    const footer    = document.querySelector('#checklistSidePanel .cl-footer-row');
    if (inputArea) inputArea.style.display = isMS ? 'none' : '';
    if (footer)    footer.style.display    = isMS ? 'none' : '';
}

// Per-store accent color so the stacked sections/pills are distinguishable at a glance.
// `solid` matches the site-wide store colors (`_storeColors`, used by the monthly-goals
// banner & charts — BAL red, MPL orange, etc.); `soft` is a light tint for backgrounds.
function _msStoreAccent(store) {
    const map = {
        OVL: { solid: '#7c3aed', soft: '#f5f3ff' },   // purple
        LEE: { solid: '#2563eb', soft: '#eff6ff' },   // blue
        WSP: { solid: '#5a8d3b', soft: '#f3f8ee' },   // green
        MPL: { solid: '#ea580c', soft: '#fff7ed' },   // orange
        BAL: { solid: '#dc2626', soft: '#fef2f2' },   // red
    };
    return map[String(store || '').toUpperCase()] || { solid: '#64748b', soft: '#f1f5f9' };
}

// Collapse duplicate GLOBAL/required tasks by text (mirrors renderChecklist).
function _dedupeGlobals(rawItems) {
    const seen = new Set();
    return (rawItems || []).filter(it => {
        if (it.isGlobal) {
            const key = String(it.text || '').trim().toLowerCase();
            if (seen.has(key)) return false;
            seen.add(key);
        }
        return true;
    });
}

function _applyPendingTogglesMS() {
    const now = Date.now();
    for (const [key, val] of _pendingTogglesMS) {
        if (val.expiresAt < now) { _pendingTogglesMS.delete(key); continue; }
        const [store, id] = key.split('::');
        const cache = checklistDataCacheMS[store];
        if (!cache) continue;
        for (const tab of Object.keys(cache)) {
            const item = (cache[tab] || []).find(i => i.id === id);
            if (item) item.checked = val.checked;
        }
    }
}

async function loadChecklistMS() {
    const container = document.getElementById('checklistContent');
    const userName = getChecklistUser();
    _setMSChecklistChrome(true);

    // MSM effective role is manager: Daily/Weekly/Monthly apply; Quarterly is CORP/ALL-only.
    document.getElementById('cl-tab-weekly')?.style && (document.getElementById('cl-tab-weekly').style.display = '');
    document.getElementById('cl-tab-monthly')?.style && (document.getElementById('cl-tab-monthly').style.display = '');
    const qTab = document.getElementById('cl-tab-quarterly');
    if (qTab) {
        qTab.style.display = 'none';
        if (currentChecklistTab === 'quarterly') { currentChecklistTab = 'daily'; switchChecklistTab('daily'); return; }
    }

    if (container) container.innerHTML = '<div class="status-message">Syncing Checklist...</div>';
    try {
        const results = await Promise.all(MULTISTORE_MANAGER_STORES.map(s =>
            fetch(`${CHECKLIST_URL}?user=${encodeURIComponent(userName)}&store=${s}&v=${Date.now()}`).then(r => r.json())
        ));
        checklistDataCacheMS = {};
        MULTISTORE_MANAGER_STORES.forEach((s, i) => {
            checklistDataCacheMS[s] = results[i] || { daily: [], weekly: [], monthly: [], quarterly: [] };
        });
        _applyPendingTogglesMS();
        renderChecklistMS();
    } catch (e) {
        console.error('MSM Checklist Fetch Error', e);
        if (container) container.innerHTML = '<div class="status-message" style="color: var(--red-alert);">Failed to load checklist.</div>';
    }
}

function renderChecklistMS() {
    const container = document.getElementById('checklistContent');
    if (!container) return;

    let html = '';
    MULTISTORE_MANAGER_STORES.forEach(store => {
        const cache = checklistDataCacheMS[store] || {};
        const items = _dedupeGlobals(cache[currentChecklistTab] || []);
        const total = items.length;
        const done  = items.filter(i => i.checked).length;
        const progTxt = total ? (done === total ? `✓ ${total}/${total}` : `${done}/${total}`) : '—';
        const _ac = _msStoreAccent(store);
        const _allDone = total && done === total;

        html += `<div class="ms-store-section" style="border-left: 4px solid ${_ac.solid};">
            <div class="ms-store-head" style="border-bottom-color: ${_ac.soft};">
                <span class="ms-store-name" style="color: ${_ac.solid};">${escapeHtml(store)}</span>
                <span class="ms-store-prog ${_allDone ? 'all-done' : ''}"${_allDone ? '' : ` style="background: ${_ac.soft}; color: ${_ac.solid};"`}>${progTxt}</span>
            </div>`;

        if (total === 0) {
            html += `<div class="ms-empty">No tasks for this tab.</div>`;
        } else {
            items.forEach(item => {
                const completedClass = item.checked ? 'completed' : '';
                const deleteHtml = !item.isGlobal
                    ? `<button class="cl-delete-btn" onclick="deleteChecklistItemMS('${store}','${item.id}')" data-tip="Delete Task">✖</button>`
                    : '';
                html += `
                <div class="cl-item ${completedClass}">
                    <input type="checkbox" class="cl-checkbox" ${item.checked ? 'checked' : ''} onchange="toggleChecklistStateMS('${store}','${item.id}', this.checked)">
                    <div class="cl-content-wrapper" style="justify-content: center;">
                        <span class="cl-text">${escapeHtml(item.text)}</span>
                    </div>
                    ${deleteHtml}
                </div>`;
            });
        }

        html += `<div class="ms-add-row">
                <input type="text" id="msNewTask_${store}" placeholder="Add a ${escapeHtml(store)} task..." onkeydown="if(event.key==='Enter')addChecklistItemMS('${store}')">
                <button class="btn-primary cl-add-btn" onclick="addChecklistItemMS('${store}')">Add</button>
            </div>
        </div>`;
    });

    container.innerHTML = html;
    updateChecklistChipMS();
}

function toggleChecklistStateMS(store, id, isChecked) {
    const userName = getChecklistUser();
    const cache = checklistDataCacheMS[store];
    if (!cache) return;
    const item = (cache[currentChecklistTab] || []).find(i => i.id === id);
    if (item) item.checked = isChecked;
    _pendingTogglesMS.set(store + '::' + id, { checked: isChecked, expiresAt: Date.now() + 20000 });
    renderChecklistMS();

    postWrite(CHECKLIST_URL, { action: 'toggle', id, checked: isChecked, tab: currentChecklistTab, user: userName, store })
        .catch(err => {
            const it = (cache[currentChecklistTab] || []).find(i => i.id === id);
            if (it) it.checked = !isChecked;
            _pendingTogglesMS.delete(store + '::' + id);
            renderChecklistMS();
            alert('Could not save that change: ' + err.message);
        });
}

async function addChecklistItemMS(store) {
    const input = document.getElementById('msNewTask_' + store);
    if (!input) return;
    const text = input.value.trim();
    if (!text) return;

    input.disabled = true;
    const userName = getChecklistUser();
    try {
        const out = await postWrite(CHECKLIST_URL, { action: 'add', tab: currentChecklistTab, text, user: userName, store });
        const cache = checklistDataCacheMS[store] || (checklistDataCacheMS[store] = { daily: [], weekly: [], monthly: [], quarterly: [] });
        (cache[currentChecklistTab] ||= []).push({ id: out.id || ('temp_' + Date.now()), text, isGlobal: false, checked: false });
        renderChecklistMS();
    } catch (e) {
        alert('Failed to add task: ' + (e.message || e));
    } finally {
        const el = document.getElementById('msNewTask_' + store);
        if (el) { el.value = ''; el.disabled = false; el.focus(); }
    }
}

function deleteChecklistItemMS(store, id) {
    const userName = getChecklistUser();
    const cache = checklistDataCacheMS[store];
    if (!cache) return;
    const list = cache[currentChecklistTab] || [];
    const removed = list.find(i => i.id === id);
    cache[currentChecklistTab] = list.filter(i => i.id !== id);
    renderChecklistMS();

    postWrite(CHECKLIST_URL, { action: 'delete', id, tab: currentChecklistTab, user: userName, store })
        .catch(err => {
            if (removed) { (cache[currentChecklistTab] ||= []).push(removed); renderChecklistMS(); }
            alert('Could not delete task: ' + err.message);
        });
}

// Combined nudge chip across both managed stores (based on the Daily list).
function updateChecklistChipMS() {
    const segs = [];
    const samStores = [];
    let anyOutstanding = false, anyTasks = false;
    MULTISTORE_MANAGER_STORES.forEach(store => {
        const items = _dedupeGlobals((checklistDataCacheMS[store] || {}).daily || []);
        if (!items.length) return;
        anyTasks = true;
        const done = items.filter(i => i.checked).length;
        samStores.push({ store, done, total: items.length });
        const ac = _msStoreAccent(store);
        const label = done === items.length ? `${store} ✓` : `${store} ${done}/${items.length}`;
        segs.push(`<span class="ms-chip-seg" style="background: ${ac.solid};">${label}</span>`);
        if (done < items.length) anyOutstanding = true;
    });
    if (typeof samSetProgress === 'function') samSetProgress('cl', samStores.length ? { stores: samStores } : { done: 0, total: 0 });

    const chip = document.getElementById('cl-progress-chip');
    const btn = document.querySelector('.cl-nav-toggle');
    if (!chip || !btn) return;

    if (!anyTasks) { chip.textContent = ''; chip.classList.remove('ms-chip'); }
    else { chip.classList.add('ms-chip'); chip.innerHTML = segs.join(''); }
    const panel = document.getElementById('checklistSidePanel');
    const isOpen = panel && panel.classList.contains('open');
    btn.classList.toggle('cl-needs-attention', anyOutstanding && !isOpen);
}

// --- API ACTIONS (POST to Apps Script) ---
async function toggleChecklistState(id, isChecked) {
    const userName = getChecklistUser();
    const store = sessionStorage.getItem('speeksUserStore') || 'OVL';
    
    const item = checklistDataCache[currentChecklistTab].find(i => i.id === id);
    if (item) item.checked = isChecked;
    // Protect this optimistic state for 20s so a slow server response can't overwrite it
    _pendingToggles.set(id, { checked: isChecked, expiresAt: Date.now() + 20000 });
    renderChecklist();

    postWrite(CHECKLIST_URL, { action: 'toggle', id: id, checked: isChecked, tab: currentChecklistTab, user: userName, store: store })
        .catch(err => {
            // Write failed — revert the optimistic toggle so the UI matches the server.
            const it = checklistDataCache[currentChecklistTab].find(i => i.id === id);
            if (it) it.checked = !isChecked;
            _pendingToggles.delete(id);
            renderChecklist();
            alert('Could not save that change: ' + err.message);
        });
}

async function addChecklistItem() {
    const input = document.getElementById('newChecklistTask');
    const text = input.value.trim();
    if (!text) return;

    input.value = 'Saving...';
    input.disabled = true;

    const userName = getChecklistUser();
    const store = sessionStorage.getItem('speeksUserStore');
    const tempId = 'temp_' + Date.now();

    const payload = {
        action: 'add',
        tab: currentChecklistTab,
        text: text,
        user: userName,
        store: store
    };

    try {
        const out = await postWrite(CHECKLIST_URL, payload);

        // Add to local cache so they see it instantly (use the server id when returned)
        checklistDataCache[currentChecklistTab].push({ id: out.id || tempId, text: text, isGlobal: false, checked: false });
        renderChecklist();
    } catch (e) {
        alert("Failed to add task: " + (e.message || e));
    } finally {
        input.value = '';
        input.disabled = false;
        input.focus();
    }
}

async function deleteChecklistItem(id) {
    const userName = getChecklistUser();
    const store = sessionStorage.getItem('speeksUserStore') || 'OVL';

    const removed = checklistDataCache[currentChecklistTab].find(i => i.id === id);
    checklistDataCache[currentChecklistTab] = checklistDataCache[currentChecklistTab].filter(i => i.id !== id);
    renderChecklist();

    postWrite(CHECKLIST_URL, { action: 'delete', id: id, tab: currentChecklistTab, user: userName, store: store })
        .catch(err => {
            // Restore the item if the server rejected the delete.
            if (removed) { checklistDataCache[currentChecklistTab].push(removed); renderChecklist(); }
            alert('Could not delete task: ' + err.message);
        });
}

function clearChecklistTab() {
    const items = checklistDataCache[currentChecklistTab] || [];
    const checkedItems = items.filter(i => i.checked);
    if (checkedItems.length === 0) return;

    const userName = getChecklistUser();
    const store = sessionStorage.getItem('speeksUserStore') || 'OVL';

    items.forEach(i => i.checked = false);
    renderChecklist();

    Promise.allSettled(checkedItems.map(item =>
        postWrite(CHECKLIST_URL, { action: 'toggle', id: item.id, checked: false, tab: currentChecklistTab, user: userName, store: store })
            .then(() => ({ ok: true }))
            .catch(() => ({ ok: false, item }))
    )).then(results => {
        const failed = results.filter(r => r.value && !r.value.ok).map(r => r.value.item);
        if (failed.length) {
            // Re-check the ones the server didn't accept so the UI stays truthful.
            failed.forEach(it => {
                const c = checklistDataCache[currentChecklistTab].find(i => i.id === it.id);
                if (c) c.checked = true;
            });
            renderChecklist();
            alert('Some items could not be cleared — please try again.');
        }
    });
}

// --- CHECKLIST NUDGE HELPERS ---
function updateChecklistChip() {
    const dailyItems = checklistDataCache['daily'] || [];
    const total = dailyItems.length;
    const done = dailyItems.filter(i => i.checked).length;
    if (typeof samSetProgress === 'function') samSetProgress('cl', { done, total });

    const chip = document.getElementById('cl-progress-chip');
    const btn = document.querySelector('.cl-nav-toggle');
    if (!chip || !btn) return;

    if (total === 0) {
        chip.textContent = '';
        btn.classList.remove('cl-needs-attention');
        return;
    }

    chip.textContent = done === total ? '✓ All done' : `${done}/${total} done`;

    const panel = document.getElementById('checklistSidePanel');
    const isOpen = panel && panel.classList.contains('open');
    btn.classList.toggle('cl-needs-attention', done < total && !isOpen);
}

// Fetches checklist data at startup to populate the progress chip without opening the panel.
// Uses a separate path from loadChecklist() so the panel-open guard doesn't suppress it.
async function _prefetchChecklistForChip() {
    const userName = getChecklistUser();
    if (_isMSMChecklist()) {
        try {
            const results = await Promise.all(MULTISTORE_MANAGER_STORES.map(s =>
                fetch(`${CHECKLIST_URL}?user=${encodeURIComponent(userName)}&store=${s}&v=${Date.now()}`).then(r => r.json())
            ));
            checklistDataCacheMS = {};
            MULTISTORE_MANAGER_STORES.forEach((s, i) => {
                checklistDataCacheMS[s] = results[i] || { daily: [], weekly: [], monthly: [], quarterly: [] };
            });
            _applyPendingTogglesMS();
            updateChecklistChipMS();
        } catch (_) {}
        return;
    }
    const store = sessionStorage.getItem('speeksUserStore') || 'OVL';
    try {
        const res = await fetch(`${CHECKLIST_URL}?user=${encodeURIComponent(userName)}&store=${store}${_checklistPersonalParam()}&v=${Date.now()}`);
        checklistDataCache = await res.json();
        _applyPendingToggles();
        updateChecklistChip();
    } catch (_) {}
}

// --- BULLETPROOF TOGGLE & CLICK-AWAY LOGIC ---
let _clSyncInterval = null;

function _startChecklistSync() {
    if (_clSyncInterval) return;
    _clSyncInterval = setInterval(async () => {
        const panel = document.getElementById('checklistSidePanel');
        if (!panel?.classList.contains('open')) return;
        const userName = getChecklistUser();
        if (_isMSMChecklist()) {
            try {
                const results = await Promise.all(MULTISTORE_MANAGER_STORES.map(s =>
                    fetch(`${CHECKLIST_URL}?user=${encodeURIComponent(userName)}&store=${s}&v=${Date.now()}`).then(r => r.json())
                ));
                checklistDataCacheMS = {};
                MULTISTORE_MANAGER_STORES.forEach((s, i) => {
                    checklistDataCacheMS[s] = results[i] || { daily: [], weekly: [], monthly: [], quarterly: [] };
                });
                _applyPendingTogglesMS();
                renderChecklistMS();
            } catch (_) {}
            return;
        }
        const store = sessionStorage.getItem('speeksUserStore') || 'OVL';
        try {
            const res = await fetch(`${CHECKLIST_URL}?user=${encodeURIComponent(userName)}&store=${store}${_checklistPersonalParam()}&v=${Date.now()}`);
            checklistDataCache = await res.json();
            _applyPendingToggles();
            renderChecklist();
        } catch (_) {}
    }, 30000);
}

function _stopChecklistSync() {
    if (_clSyncInterval) { clearInterval(_clSyncInterval); _clSyncInterval = null; }
}

window.toggleChecklistPanel = function(event) {
    if (event) event.stopPropagation();
    const panel = document.getElementById('checklistSidePanel');
    if (!panel) return;
    const isOpen = panel.classList.toggle('open');
    const toggle = document.querySelector('.cl-nav-toggle');
    if (toggle) {
        toggle.classList.toggle('panel-active', isOpen);
        if (isOpen) toggle.classList.remove('cl-needs-attention');
    }
    if (isOpen) {
        _closeSidePanels('checklistSidePanel');
        _startChecklistSync();
    } else {
        _stopChecklistSync();
    }
};

// Closes the panel if you click outside of it
document.addEventListener('click', function(e) {
    // CRITICAL FIX: If the clicked element was just removed from the DOM (like deleting a task), ignore the click!
    if (!document.body.contains(e.target)) return;
    // Don't close panels while a modal is open or the click was inside one (e.g. ✖ button fires closeAllModals before bubbling)
    if (document.getElementById('globalOverlay')?.classList.contains('show')) return;
    if (e.target.closest('.modal-menu')) return;

    const clPanel = document.getElementById('checklistSidePanel');
    if (clPanel && clPanel.classList.contains('open')) {
        if (!clPanel.contains(e.target)) {
            clPanel.classList.remove('open');
            document.querySelector('.cl-nav-toggle')?.classList.remove('panel-active');
            _stopChecklistSync();
        }
    }

    const giPanel = document.getElementById('goalsSidePanel');
    const giToggle = document.querySelector('.gi-nav-toggle');
    if (giPanel && giPanel.classList.contains('open')) {
        if (!giPanel.contains(e.target) && !giToggle?.contains(e.target)) {
            giPanel.classList.remove('open');
            giToggle?.classList.remove('panel-active');
            _resetToCurrentMonth();
                }
    }

    const auditPanel = document.getElementById('auditSidePanel');
    const auditToggle = document.querySelector('.audit-nav-toggle');
    if (auditPanel && auditPanel.classList.contains('open')) {
        if (!auditPanel.contains(e.target) && !auditToggle?.contains(e.target)) {
            auditPanel.classList.remove('open');
            auditToggle?.classList.remove('panel-active');
            _stopAuditSync();
        }
    }
});

// =============================================================================
// STORE AUDIT CHECKLIST — PayMore audit-readiness, shared per store.
// Two tabs: Daily (resets each day) and Weekly (resets each Monday). Reads a
// fixed admin-defined list (store-audit fn); completions are shared per store.
// =============================================================================
let auditDataCache = { daily: { items: [], total: 0, completed: 0 }, weekly: { items: [], total: 0, completed: 0 } };
let currentAuditTab = 'daily';
let _auditSyncInterval = null;
// Multi-Store Manager: one audit cache per managed store, rendered stacked. Empty for others.
let auditDataCacheMS = {};   // { BAL: {daily,weekly}, MPL: {daily,weekly} }

function _auditTab(tab) { return auditDataCache[tab] || { items: [], total: 0, completed: 0 }; }

function switchAuditTab(tab) {
    currentAuditTab = tab;
    document.getElementById('audit-tab-daily')?.classList.toggle('active', tab === 'daily');
    document.getElementById('audit-tab-weekly')?.classList.toggle('active', tab === 'weekly');
    if (_isMSMChecklist()) renderAuditMS(); else renderAudit();
}

async function loadAudit() {
    const panel = document.getElementById('auditSidePanel');
    if (!panel?.classList.contains('open')) return;   // only fetch when opening
    if (_isMSMChecklist()) { await loadAuditMS(); return; }
    const store = sessionStorage.getItem('speeksUserStore') || 'OVL';
    const container = document.getElementById('auditContent');
    if (container) container.innerHTML = '<div class="status-message">Syncing checklist...</div>';
    try {
        const res = await fetch(`${STORE_AUDIT_URL}?store=${store}&v=${Date.now()}`);
        auditDataCache = await res.json();
        renderAudit();
    } catch (e) {
        console.error('Audit Fetch Error', e);
        if (container) container.innerHTML = '<div class="status-message" style="color: var(--red-alert);">Failed to load the cleaning checklist.</div>';
    }
}

function renderAudit() {
    const container = document.getElementById('auditContent');
    if (!container) return;
    const data = _auditTab(currentAuditTab);
    const items = data.items || [];

    const label = document.getElementById('audit-week-label');
    if (label) {
        label.textContent = items.length
            ? `${data.completed || 0}/${data.total || items.length} complete ${currentAuditTab === 'daily' ? 'today' : 'this week'}`
            : '';
    }

    if (items.length === 0) {
        container.innerHTML = `<div style="text-align: center; padding: 30px; color: #888; font-weight: 600; font-size: 13px;">No ${currentAuditTab} audit items have been set up yet.</div>`;
        updateAuditChip();
        return;
    }

    let html = '';
    let lastSection = null;
    items.forEach(item => {
        if (item.section !== lastSection) {
            html += `<div style="font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .5px; color: #94a3b8; margin: 14px 4px 6px;">${escapeHtml(item.section)}</div>`;
            lastSection = item.section;
        }
        const completedClass = item.checked ? 'completed' : '';
        html += `
        <div class="cl-item ${completedClass}">
            <input type="checkbox" class="cl-checkbox" ${item.checked ? 'checked' : ''} onchange="toggleAuditState('${item.id}', this.checked)">
            <div class="cl-content-wrapper" style="justify-content: center;">
                <span class="cl-text">${escapeHtml(item.text)}</span>
            </div>
        </div>`;
    });
    container.innerHTML = html;
    updateAuditChip();
}

// ============================================================================
// MULTI-STORE MANAGER — dual-store audit checklist (both stores stacked).
// The audit checklist is shared per store; a MSM sees both managed stores in one
// panel. ASMs (single store) and the DM overview are unaffected.
// ============================================================================
async function loadAuditMS() {
    const container = document.getElementById('auditContent');
    if (container) container.innerHTML = '<div class="status-message">Syncing checklist...</div>';
    try {
        const results = await Promise.all(MULTISTORE_MANAGER_STORES.map(s =>
            fetch(`${STORE_AUDIT_URL}?store=${s}&v=${Date.now()}`).then(r => r.json())
        ));
        auditDataCacheMS = {};
        MULTISTORE_MANAGER_STORES.forEach((s, i) => {
            auditDataCacheMS[s] = results[i] || { daily: { items: [], total: 0, completed: 0 }, weekly: { items: [], total: 0, completed: 0 } };
        });
        renderAuditMS();
    } catch (e) {
        console.error('MSM Audit Fetch Error', e);
        if (container) container.innerHTML = '<div class="status-message" style="color: var(--red-alert);">Failed to load the cleaning checklist.</div>';
    }
}

function renderAuditMS() {
    const container = document.getElementById('auditContent');
    if (!container) return;

    const label = document.getElementById('audit-week-label');
    if (label) label.textContent = currentAuditTab === 'daily' ? 'Today · both stores' : 'This week · both stores';

    let html = '';
    MULTISTORE_MANAGER_STORES.forEach(store => {
        const data = (auditDataCacheMS[store] || {})[currentAuditTab] || { items: [], total: 0, completed: 0 };
        const items = data.items || [];
        const total = data.total || items.length;
        const done  = (data.completed != null) ? data.completed : items.filter(i => i.checked).length;
        const progTxt = total ? (done === total ? `✓ ${total}/${total}` : `${done}/${total}`) : '—';
        const _ac = _msStoreAccent(store);
        const _allDone = total && done === total;

        html += `<div class="ms-store-section" style="border-left: 4px solid ${_ac.solid};">
            <div class="ms-store-head" style="border-bottom-color: ${_ac.soft};">
                <span class="ms-store-name" style="color: ${_ac.solid};">${escapeHtml(store)}</span>
                <span class="ms-store-prog ${_allDone ? 'all-done' : ''}"${_allDone ? '' : ` style="background: ${_ac.soft}; color: ${_ac.solid};"`}>${progTxt}</span>
            </div>`;

        if (items.length === 0) {
            html += `<div class="ms-empty">No ${currentAuditTab} audit items set up.</div>`;
        } else {
            let lastSection = null;
            items.forEach(item => {
                if (item.section !== lastSection) {
                    html += `<div style="font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .5px; color: #94a3b8; margin: 12px 4px 6px;">${escapeHtml(item.section)}</div>`;
                    lastSection = item.section;
                }
                const completedClass = item.checked ? 'completed' : '';
                html += `
                <div class="cl-item ${completedClass}">
                    <input type="checkbox" class="cl-checkbox" ${item.checked ? 'checked' : ''} onchange="toggleAuditStateMS('${store}','${item.id}', this.checked)">
                    <div class="cl-content-wrapper" style="justify-content: center;">
                        <span class="cl-text">${escapeHtml(item.text)}</span>
                    </div>
                </div>`;
            });
        }
        html += `</div>`;
    });

    container.innerHTML = html;
    updateAuditChipMS();
}

function toggleAuditStateMS(store, id, isChecked) {
    const userName = sessionStorage.getItem('speeksUserName') || 'Unknown';
    const tab = currentAuditTab;
    const data = (auditDataCacheMS[store] || {})[tab];
    if (!data) return;

    const item = (data.items || []).find(i => i.id === id);
    if (item) item.checked = isChecked;
    data.completed = (data.items || []).filter(i => i.checked).length;
    renderAuditMS();

    postWrite(STORE_AUDIT_URL, { action: 'toggle', id, checked: isChecked, store, user: userName, period: tab })
        .catch(err => {
            if (item) item.checked = !isChecked;
            data.completed = (data.items || []).filter(i => i.checked).length;
            renderAuditMS();
            alert('Could not save that change: ' + err.message);
        });
}

function updateAuditChipMS() {
    const segs = [];
    const samStores = [];
    let anyOutstanding = false, anyItems = false;
    MULTISTORE_MANAGER_STORES.forEach(store => {
        const daily = (auditDataCacheMS[store] || {}).daily || { items: [], total: 0, completed: 0 };
        const total = daily.total || (daily.items || []).length;
        if (!total) return;
        anyItems = true;
        const done = (daily.completed != null) ? daily.completed : (daily.items || []).filter(i => i.checked).length;
        samStores.push({ store, done, total });
        const ac = _msStoreAccent(store);
        const label = done === total ? `${store} ✓` : `${store} ${done}/${total}`;
        segs.push(`<span class="ms-chip-seg" style="background: ${ac.solid};">${label}</span>`);
        if (done < total) anyOutstanding = true;
    });
    if (typeof samSetProgress === 'function') samSetProgress('audit', samStores.length ? { stores: samStores } : { done: 0, total: 0 });

    const chip = document.getElementById('audit-progress-chip');
    const btn = document.querySelector('.audit-nav-toggle');
    if (!chip || !btn) return;

    if (!anyItems) { chip.textContent = ''; chip.classList.remove('ms-chip'); }
    else { chip.classList.add('ms-chip'); chip.innerHTML = segs.join(''); }
    const panel = document.getElementById('auditSidePanel');
    const isOpen = panel && panel.classList.contains('open');
    btn.classList.toggle('cl-needs-attention', anyOutstanding && !isOpen);
}

async function toggleAuditState(id, isChecked) {
    const store = sessionStorage.getItem('speeksUserStore') || 'OVL';
    const userName = sessionStorage.getItem('speeksUserName') || 'Unknown';
    const tab = currentAuditTab;
    const data = _auditTab(tab);

    const item = (data.items || []).find(i => i.id === id);
    if (item) item.checked = isChecked;
    data.completed = (data.items || []).filter(i => i.checked).length;
    renderAudit();

    postWrite(STORE_AUDIT_URL, { action: 'toggle', id: id, checked: isChecked, store: store, user: userName, period: tab })
        .catch(err => {
            if (item) item.checked = !isChecked;
            data.completed = (data.items || []).filter(i => i.checked).length;
            renderAudit();
            alert('Could not save that change: ' + err.message);
        });
}

function updateAuditChip() {
    // Chip reflects the DAILY list (the everyday cadence).
    const daily = _auditTab('daily');
    const total = daily.total || (daily.items || []).length;
    const done = (daily.completed != null) ? daily.completed : (daily.items || []).filter(i => i.checked).length;
    if (typeof samSetProgress === 'function') samSetProgress('audit', { done, total });

    const chip = document.getElementById('audit-progress-chip');
    const btn = document.querySelector('.audit-nav-toggle');
    if (!chip || !btn) return;

    if (total === 0) {
        chip.textContent = '';
        btn.classList.remove('cl-needs-attention');
        return;
    }
    chip.textContent = done === total ? '✓ All done' : `${done}/${total} today`;

    const panel = document.getElementById('auditSidePanel');
    const isOpen = panel && panel.classList.contains('open');
    btn.classList.toggle('cl-needs-attention', done < total && !isOpen);
}

async function _prefetchAuditForChip() {
    if (_isMSMChecklist()) {
        try {
            const results = await Promise.all(MULTISTORE_MANAGER_STORES.map(s =>
                fetch(`${STORE_AUDIT_URL}?store=${s}&v=${Date.now()}`).then(r => r.json())
            ));
            auditDataCacheMS = {};
            MULTISTORE_MANAGER_STORES.forEach((s, i) => {
                auditDataCacheMS[s] = results[i] || { daily: { items: [], total: 0, completed: 0 }, weekly: { items: [], total: 0, completed: 0 } };
            });
            updateAuditChipMS();
        } catch (_) {}
        return;
    }
    const store = sessionStorage.getItem('speeksUserStore') || 'OVL';
    try {
        const res = await fetch(`${STORE_AUDIT_URL}?store=${store}&v=${Date.now()}`);
        auditDataCache = await res.json();
        updateAuditChip();
    } catch (_) {}
}

function _startAuditSync() {
    if (_auditSyncInterval) return;
    _auditSyncInterval = setInterval(async () => {
        const panel = document.getElementById('auditSidePanel');
        if (!panel?.classList.contains('open')) return;
        if (_isMSMChecklist()) {
            try {
                const results = await Promise.all(MULTISTORE_MANAGER_STORES.map(s =>
                    fetch(`${STORE_AUDIT_URL}?store=${s}&v=${Date.now()}`).then(r => r.json())
                ));
                auditDataCacheMS = {};
                MULTISTORE_MANAGER_STORES.forEach((s, i) => {
                    auditDataCacheMS[s] = results[i] || { daily: { items: [], total: 0, completed: 0 }, weekly: { items: [], total: 0, completed: 0 } };
                });
                renderAuditMS();
            } catch (_) {}
            return;
        }
        const store = sessionStorage.getItem('speeksUserStore') || 'OVL';
        try {
            const res = await fetch(`${STORE_AUDIT_URL}?store=${store}&v=${Date.now()}`);
            auditDataCache = await res.json();
            renderAudit();
        } catch (_) {}
    }, 30000);
}

function _stopAuditSync() {
    if (_auditSyncInterval) { clearInterval(_auditSyncInterval); _auditSyncInterval = null; }
}

window.toggleAuditPanel = function(event) {
    if (event) event.stopPropagation();
    const panel = document.getElementById('auditSidePanel');
    if (!panel) return;
    const isOpen = panel.classList.toggle('open');
    const toggle = document.querySelector('.audit-nav-toggle');
    if (toggle) {
        toggle.classList.toggle('panel-active', isOpen);
        if (isOpen) toggle.classList.remove('cl-needs-attention');
    }
    if (isOpen) {
        // mutually exclusive with the other side panels
        _closeSidePanels('auditSidePanel');
        _startAuditSync();
    } else {
        _stopAuditSync();
    }
};

// --- ROLE SELECTION LOGIC ---
// Per-role capacity: every role is 1-per-store. Extended lister roles (L3, L4, …
// on big rosters) aren't listed here — the `|| 1` lookup below caps them too.
// OFF is the exception and must stay uncapped: any number of people can be off
// on the same day, and a cap of 1 would lock the chip after the first one.
const ROLE_CAP = { B1: 1, B2: 1, L1: 1, L2: 1, OFF: Infinity };

window.updateRoleLocks = function() {
    // Role capacity is per STORE. Normally the page shows one store's dots, so the
    // whole document is one scope; the MSM's stacked dual-store widget marks each
    // store section with data-goals-scope so BAL's B1 doesn't lock MPL's B1.
    const sections = document.querySelectorAll('[data-goals-scope]');
    const scopes = sections.length ? Array.from(sections) : [document];

    scopes.forEach(scope => {
        // Count how many people currently hold each role within this scope.
        const counts = {};
        scope.querySelectorAll('.role-dot.active').forEach(btn => {
            const r = _roleOf(btn);
            counts[r] = (counts[r] || 0) + 1;
        });

        scope.querySelectorAll('.role-dot').forEach(btn => {
            if (btn.classList.contains('active')) {
                // Active buttons always look fully visible.
                if (!btn.hasAttribute('disabled')) { btn.style.opacity = '1'; btn.style.cursor = 'pointer'; }
                return;
            }
            const role = _roleOf(btn);
            const cap = ROLE_CAP[role] || 1;
            const isFull = (counts[role] || 0) >= cap;
            if (isFull) {
                // At capacity for this role. (L1 still allows a deliberate swap — see selectRole.)
                btn.style.opacity = '0.3';
                btn.style.cursor = 'not-allowed';
                btn.dataset.roleTaken = 'true';
            } else if (!btn.hasAttribute('disabled')) {
                // Only restore if it isn't locked by the 10:30am cutoff.
                btn.style.opacity = '1';
                btn.style.cursor = 'pointer';
                btn.dataset.roleTaken = 'false';
            }
        });
    });
};

window.selectRole = function(clickedBtn, emp, role) {
    if (clickedBtn.hasAttribute('disabled')) return;

    const isAlreadyActive = clickedBtn.classList.contains('active');

    // A floater is claimed by whichever store puts him on their board first, and
    // released when they take him off. The server decides, so the UI only paints
    // after it answers — losing the race has to leave the dot unselected rather
    // than showing a role this store doesn't actually have.
    const _store = _goalsRoleScopeStore(clickedBtn);
    if (_goalsIsFloater(_store, emp)) {
        const releasing = isAlreadyActive || role === GOALS_OFF;
        _goalsClaimFloater(_store, emp, releasing).then(err => {
            if (err) {
                alert(err);
                // Repaint from the server's answer so he greys out here.
                if (typeof loadManagerGoals === 'function') loadManagerGoals();
                return;
            }
            _goalsApplyRole(clickedBtn, role, isAlreadyActive);
        });
        return;
    }

    // 1. If clicking the already active role, toggle it off and free it up.
    if (isAlreadyActive) {
        clickedBtn.classList.remove('active');
        updateRoleLocks();
        recomputeGoalDisplays();
        scheduleGoalsAutosave();
        return;
    }

    // 2. Role already taken by someone else? One person per role.
    if (clickedBtn.dataset.roleTaken === 'true') {
        alert(`The role ${role} is already assigned to another team member. Please deselect it from them first.`);
        return;
    }

    // 3. Remove ALL roles from the CURRENT employee (only 1 role per person).
    const parentRow = clickedBtn.closest('.goals-edit-roles');
    if (parentRow) {
        parentRow.querySelectorAll('.role-dot').forEach(btn => btn.classList.remove('active'));
    }

    // 4. Activate the clicked button.
    clickedBtn.classList.add('active');

    updateRoleLocks();
    recomputeGoalDisplays();
    scheduleGoalsAutosave();
};

// Recompute every visible auto-goal from the currently selected roles.
window.recomputeGoalDisplays = function() {
    if (_msGoalsActive()) return recomputeGoalDisplaysMS();
    if (!document.getElementById('goal-display-0') && !document.querySelector('.goal-auto-display')) return;
    let staffedCount = 0;
    goalsRoster.forEach((emp, idx) => {
        if (_isWorkingRole(_activeRoleIn(document.getElementById(`roles-${idx}`)))) staffedCount++;
    });
    const rosterSize = effectiveTeamSize(goalsTargetStore);
    const dateStr = new Date().toLocaleDateString('en-US', { timeZone: 'America/Chicago' });

    let todayTotal = 0;
    let weekTotal = 0;
    goalsRoster.forEach((emp, idx) => {
        const role = _activeRoleIn(document.getElementById(`roles-${idx}`));
        const todayGoal = _isWorkingRole(role) ? ListingGoalsEngine.goalFor(role, dateStr, { employee: emp, store: goalsTargetStore }) : 0;

        const disp = document.getElementById(`goal-display-${idx}`);
        if (disp) {
            disp.innerText = _isOffRole(role) ? 'Off' : (role === '-' ? '–' : todayGoal);
            disp.classList.toggle('goal-auto-set', _isWorkingRole(role));
            disp.classList.toggle('goal-off-set', _isOffRole(role));
        }
        todayTotal += todayGoal;

        const weekVal = (_priorWeekGoals[idx] || 0) + todayGoal;
        const wkEl = document.getElementById(`week-display-${idx}`);
        if (wkEl) wkEl.innerText = weekVal || '–';
        weekTotal += weekVal;
    });

    const todayEl = document.getElementById('goals-total-target');
    if (todayEl) todayEl.innerText = todayTotal;
    const weekEl = document.getElementById('goals-total-actual');
    if (weekEl) weekEl.innerText = weekTotal;

    _goalsResaveIfStale(dateStr);
};

// If the DM changes the weekly total AFTER a store has already picked its roles,
// the saved daily goals still hold the numbers they were computed with — and the
// district view, the employee widgets and the weekly report all read those saved
// rows, not this screen. store-targets doesn't broadcast, so nothing tells an open
// widget to catch up.
//
// So: whenever the displayed goals disagree with what's stored for today, write
// the recomputed values back. Self-healing — one autosave and they agree, so this
// can't loop. Only ever touches TODAY, and only in the manager's own editable
// widget (the read-only views don't render goal-display-* nodes).
function _goalsResaveIfStale(dateStr) {
    if (!Array.isArray(liveGoalsData) || !liveGoalsData.length) return;
    if (typeof scheduleGoalsAutosave !== 'function') return;
    const stale = goalsRoster.some((emp, idx) => {
        const role = _activeRoleIn(document.getElementById(`roles-${idx}`));
        // Off (and unset) carry no goal, so there is nothing that can go stale.
        if (!_isWorkingRole(role)) return false;
        const saved = liveGoalsData.find(r => r.employee === emp
            && normalizeGoalDate(r.date) === dateStr && r.role === role);
        if (!saved || saved.goal == null || saved.goal === '') return false;
        const disp = document.getElementById(`goal-display-${idx}`);
        const shown = disp ? parseInt(disp.innerText, 10) : NaN;
        return Number.isFinite(shown) && parseInt(saved.goal, 10) !== shown;
    });
    if (stale) scheduleGoalsAutosave();
}

// --- PATCH NOTES ---
function parsePatchDate(d) {
    if (!d) return new Date(0);
    if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(d)) {
        const p = d.split('/');
        return new Date(p[2], p[0] - 1, p[1]);
    }
    const fallback = new Date(d);
    return isNaN(fallback) ? new Date(0) : fallback;
}

function formatPatchDate(d) {
    const date = parsePatchDate(d);
    if (!date || isNaN(date.getTime()) || date.getTime() === 0) return d;
    return date.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }).toUpperCase();
}

function formatPatchSummary(text) {
    if (!text) return '';
    const lines = text.split('\n').map(l => l.trim()).filter(l => l);
    if (!lines.length) return text;
    let html = '', inList = false;
    lines.forEach(l => {
        if (/^[-•]/.test(l)) {
            if (!inList) { html += '<ul class="pn-bullet-list">'; inList = true; }
            html += `<li>${l.replace(/^[-•]\s*/, '')}</li>`;
        } else {
            if (inList) { html += '</ul>'; inList = false; }
            html += `<span class="pn-item-line">${l}</span>`;
        }
    });
    if (inList) html += '</ul>';
    return html;
}

function buildPatchGroups(entries) {
    const groups = {};
    entries.forEach(e => {
        const key = e.title + '|' + e.date;
        if (!groups[key]) groups[key] = { title: e.title, date: e.date, items: [] };
        groups[key].items.push(e);
    });
    return Object.values(groups).sort((a, b) => parsePatchDate(b.date) - parsePatchDate(a.date));
}

// DEAD as of 2026-08-18: nothing creates #patchNotesList and nothing calls
// renderPatchNotes(). The hub feed draws patch notes — see _hubPatchItems().
// Left in place rather than deleted, but do not add to it: a read receipt was
// built here first and would never have appeared on screen.
function buildPatchCardHTML(group, isLatest) {
    const versionLabel = group.title;
    const catOrder = ['New Features', 'Improvements', 'Bug Fixes'];
    const catIcons = { 'New Features': '✨', 'Improvements': '🚀', 'Bug Fixes': '🔧' };
    const sections = catOrder.map(cat => {
        const items = group.items.filter(i => i.category === cat);
        if (!items.length) return '';
        return `
            <div class="pn-section">
                <h4 class="pn-section-title">${catIcons[cat]} ${cat.toUpperCase()}</h4>
                ${items.map(item => `
                    <div class="pn-item">
                        <div class="pn-item-text">${formatPatchSummary(item.summary)}</div>
                    </div>`).join('')}
            </div>`;
    }).join('');
    return `
        <div class="pn-release-card">
            <div class="pn-release-card-header">
                <div class="pn-header-left">
                    <span class="pn-version">${versionLabel}</span>
                    ${isLatest ? '<span class="pn-latest-badge">Latest</span>' : ''}
                </div>
                <span class="pn-date">${formatPatchDate(group.date)}</span>
            </div>
            <div class="pn-release-card-body">${sections}</div>
        </div>`;
}

async function loadPatchNotes() {
    try {
        const response = await fetch(`${PATCH_NOTES_URL}?v=${Date.now()}`);
        const data = await response.json();
        window._hubPatchData = data;
        // Opening the hub is NOT reading. This used to call markLatestPatchSeen(),
        // which cleared the badge and the "New patch notes" row the instant the
        // popup opened — so patch notes could never actually be read, only
        // dismissed by walking past them. Record the latest version so the card can
        // tell unread from history, and let the explicit Mark-as-read button do the
        // marking (hubMarkPatchRead).
        const _pg = (data && data.entries) ? buildPatchGroups(data.entries) : [];
        if (_pg.length) _latestPatchKey = _pg[0].title + '|' + _pg[0].date;
        renderHubFeed();
    } catch (e) { /* leave existing hub content */ }
}

function renderPatchNotes(data) {
    const listEl = document.getElementById('patchNotesList');
    if (!listEl) return;

    const { entries } = data;
    if (!entries || !entries.length) {
        listEl.innerHTML = '<div class="pn-loading">No patch notes available.</div>';
        return;
    }

    const sorted = buildPatchGroups(entries);
    listEl.innerHTML = sorted.map((g, i) => buildPatchCardHTML(g, i === 0)).join('');

    // Opening the hub used to mark the latest version read on the spot, so patch
    // notes cleared themselves whether or not anyone read a word — the same
    // "click it to skip it" problem that got Mark-all-as-read removed. Reading is
    // now a deliberate act: hubMarkPatchRead() runs off an explicit button.
    if (sorted.length > 0) _latestPatchKey = sorted[0].title + '|' + sorted[0].date;
}

// Explicit "Mark as read" for patch notes (button lives on the hub card).
// Mirrors _samMarkAnnRead: record locally first so the read survives a failed or
// slow POST, then tell the server, then re-render both feeds.
function hubMarkPatchRead() {
    const currentUser = sessionStorage.getItem('speeksUserName');
    const cleanUser = currentUser ? String(currentUser).trim().toLowerCase() : null;
    if (!cleanUser || !_latestPatchKey) return;
    localStorage.setItem('speeksPatchNotesSeen_' + cleanUser, _latestPatchKey);
    localStorage.removeItem('speeksUnseenPatchNotes_' + cleanUser);
    try {
        postWrite(PATCH_NOTES_URL, { action: 'markPatchRead', user: cleanUser, lastSeenKey: _latestPatchKey }).catch(() => {});
    } catch (_) {}
    const pnBadge = document.getElementById('patchNotesBadge');
    if (pnBadge) { pnBadge.style.display = 'none'; pnBadge.classList.remove('active'); }
    if (typeof updateMainBadge === 'function') updateMainBadge();
    try { renderHubFeed(); } catch (_) {}
    try { if (typeof renderActionFeed === 'function') renderActionFeed(); } catch (_) {}
}

function togglePatchNotes() {
    const modal = document.getElementById('notifDropdown');
    if (!modal) return;
    const isOpen = modal.classList.contains('show');
    closeAllModals();
    if (!isOpen) {
        modal.classList.add('show');
        lockAndBlurScreen();
        trackUsage('open', 'patchNotesModal', _usageLabel('patchNotesModal'));
        switchAnnTab('patchnotes');
    }
}

